#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <mcp_common.h>
#include <mcp_spi.h>

#define MCP3008_CE 8
#define MCP3008_MOSI 10
#define MCP3008_MISO 9
#define MCP3008_SCLK 11
#define SAMPLING_RATE 1000  // Samples per second

// Function to handle SIGINT and SIGTERM signals
void signal_handler(int signum) {
    printf("Exiting gracefully...\n");
    mcp_spi_close(mcp_handle);
    exit(0);
}

int main() {
    int mcp_fd, ret;
    struct sigaction sa;

    // Initialize signal handler
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Initialize MCP3008 SPI
    mcp_fd = open("/dev/spidev0.0", O_RDWR);
    if (mcp_fd < 0) {
        perror("Failed to open MCP3008 SPI device");
        return EXIT_FAILURE;
    }

    mcp_handle = mcp_init(mcp_fd);
    if (!mcp_handle) {
        perror("Failed to initialize MCP3008");
        close(mcp_fd);
        return EXIT_FAILURE;
    }

    // Set CE pin as output
    if (write(mcp_fd, (void *)CE_OFF, 1) != 1) {
        perror("Failed to write to MCP3008 CE pin");
        mcp_close(mcp_handle);
        close(mcp_fd);
        return EXIT_FAILURE;
    }

    // Configure channel 0 for single-shot mode
    if (mcp_config_channel(mcp_handle, 0, MCP_SINGLE, 0) != 0) {
        perror("Failed to configure channel 0");
        mcp_close(mcp_handle);
        close(mcp_fd);
        return EXIT_FAILURE;
    }

    // Start ADC conversion
    ret = mcp_start_conversion(mcp_handle);
    if (ret != 0) {
        perror("Failed to start ADC conversion");
        mcp_close(mcp_handle);
        close(mcp_fd);
        return EXIT_FAILURE;
    }

    // Read ADC value
    uint16_t adc_value;
    ret = mcp_read_adc(mcp_handle, &adc_value);
    if (ret != 0) {
        perror("Failed to read ADC value");
        mcp_close(mcp_handle);
        close(mcp_fd);
        return EXIT_FAILURE;
    }

    // Convert 10-bit value to raw ADC value
    uint8_t raw_value = (uint8_t)(adc_value >> 8);

    // Print timestamp and raw ADC value
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    printf("Timestamp: %ld ms  Raw ADC Value: %d\n", (long)ts.tv_sec * 1000 + ts.tv_nsec / 1000000, raw_value);

    // Wait for next conversion
    usleep(1000000 / SAMPLING_RATE);

    // Repeat until SIGINT or SIGTERM is received
    while (1) {
        usleep(1000000 / SAMPLING_RATE);
    }

    // Clean up and exit
    mcp_close(mcp_handle);
    close(mcp_fd);
    return EXIT_SUCCESS;
}

