#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/wait.h>
#include <errno.h>
#include <pigpio.h>

#define ADS1115_ADDR 0x48  // ADS1115 I2C address
#define GPIO2 2           // GPIO2 for SDA
#define GPIO3 3           // GPIO3 for SCL

// Function to read 16-bit value from ADS1115
uint16_t read_adc(int fd, uint8_t channel) {
    uint8_t buffer[2];
    int bytes_read;

    bytes_read = read(fd, buffer, 2);
    if (bytes_read != 2) {
        perror("Failed to read from ADS1115");
        return 0;
    }

    // Extract the 16-bit value from the buffer
    uint16_t adc_value = (buffer[0] << 8) | buffer[1];
    return adc_value;
}

// Function to convert ADC value to current (assuming ±4.096V range)
float adc_to_amp(uint16_t adc_value) {
    float gain = 4.096;
    return (adc_value * gain) / 3300.0; // 3300 is the full-scale range in µV
}

int main() {
    int fd, ret;
    struct i2c_fd i2c_fd;

    // Initialize pigpio
    if (piGPIO_init() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    // Open ADS1115 I2C device
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        piGPIO_cleanup();
        return EXIT_FAILURE;
    }

    i2c_fd.fd = fd;
    i2c_fd.mode = I2C_M_BUS;

    // Configure ADS1115 for single-shot mode, single-ended input on AIN0, gain ±4.096V, 128SPS
    ret = ioctl(fd, I2C_SLAVE, ADS1115_ADDR);
    if (ret < 0) {
        perror("Failed to set ADS1115 address");
        close(fd);
        piGPIO_cleanup();
        return EXIT_FAILURE;
    }

    ret = ioctl(fd, WHO_AM_I);
    if (ret < 0) {
        perror("Failed to get ADS1115 ID");
        close(fd);
        piGPIO_cleanup();
        return EXIT_FAILURE;
    }

    if (WHO_AM_I(ret) != 0x48) {
        fprintf(stderr, "ADS1115 is not present or not configured correctly\n");
        close(fd);
        piGPIO_cleanup();
        return EXIT_FAILURE;
    }

    ret = ioctl(fd, ADSC_M_SS);
    if (ret < 0) {
        perror("Failed to set ADS1115 to single-shot mode");
        close(fd);
        piGPIO_cleanup();
        return EXIT_FAILURE;
    }

    ret = ioctl(fd, ADSC_M_SE);
    if (ret < 0) {
        perror("Failed to set ADS1115 to single-ended input");
        close(fd);
        piGPIO_cleanup();
        return EXIT_FAILURE;
    }

    ret = ioctl(fd, ADSC_M_GAIN);
    if (ret < 0) {
        perror("Failed to set ADS1115 gain");
        close(fd);
        piGPIO_cleanup();
        return EXIT_FAILURE;
    }

    ret = ioctl(fd, ADSC_M_DR);
    if (ret < 0) {
        perror("Failed to set ADS1115 data rate");
        close(fd);
        piGPIO_cleanup();
        return EXIT_FAILURE;
    }

    // Read current from the sensor
    while (1) {
        uint16_t adc_value = read_adc(fd, 0); // Read from channel AIN0

        if (adc_value == 0) {
            fprintf(stderr, "ADS1115 sensor not detected\n");
            break;
        }

        float current = adc_to_amp(adc_value);
        printf("Current: %.3f A\n", current);

        usleep(500000); // Wait for 500ms
    }

    // Close I2C device and pigpio
    close(fd);
    piGPIO_cleanup();

    return EXIT_SUCCESS;
}

