#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <linux/spi/spidev.h>
#include <mcp3008.h>

#define GPIO4 2
#define GPIO8 8
#define SPI0 0

#define FLAME_SENSOR_PIN GPIO4
#define MCP3008_CE0 GPIO8
#define MCP3008_DATA_OUT 0

#define LOG_INTERVAL_SEC 1.0

int main(int argc, char *argv[]) {
    int fd;
    struct spidev_dev *dev;
    mcp3008_t mcp;
    uint32_t spi_speed = 1000000; // 1 MHz
    uint8_t read_buffer[2];
    int flame_detected = 0;
    float temperature;

    // Initialize GPIO and SPI
    if (gpio_request(GPIO4, "flame_sensor") < 0) {
        perror("Failed to request GPIO4");
        exit(EXIT_FAILURE);
    }
    gpio_direction_output(GPIO4, 0);

    if (gpio_request(MCP3008_CE0, "mcp3008_ce0") < 0) {
        perror("Failed to request MCP3008_CE0");
        exit(EXIT_FAILURE);
    }
    gpio_set_direction(MCP3008_CE0, GPIO_OUTPUT);

    dev = spidev_open(SPI0, 0);
    if (dev == NULL) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    mcp_init(&mcp, dev);
    if (mcp_set_channel(mcp, 0) < 0) {
        perror("Failed to set MCP3008 channel");
        spidev_close(dev);
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (1) {
        // Read digital flame sensor
        int sensor_state = gpio_get_level(FLAME_SENSOR_PIN);
        flame_detected = sensor_state == 0;

        // Read analog temperature
        if (mcp_read_value(&mcp) < 0) {
            fprintf(stderr, "Failed to read analog value from MCP3008\n");
            continue;
        }
        temperature = mcp_get_voltage(mcp) * 1000.0 / 3300.0; // Assuming 3300mV full-scale range

        // Log data to CSV file
        FILE *fp = fopen("flame_data.csv", "a");
        if (!fp) {
            fprintf(stderr, "Failed to open flame_data.csv for appending\n");
            continue;
        }

        // Timestamp
        time_t now = time(NULL);
        char time_str[80];
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", localtime(&now));

        // Log entry
        fprintf(fp, "%s, %d, %f\n", time_str, flame_detected, temperature);
        fclose(fp);

        // Wait for next interval
        usleep(LOG_INTERVAL_SEC * 1000000);
    }

    // Clean up
    mcp_deinit(mcp);
    spidev_close(dev);
    gpio_free(GPIO4);
    gpio_free(MCP3008_CE0);

    return 0;
}

