#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <signal.h>
#include <time.h>
#include <wiringPi.h>
#include <pigpio.h>

#define BUZZER_GPIO 27
#define FLAME_SENSOR_GPIO 4
#define HEAT_SENSOR_GPIO 7
#define ADS1115_I2C_ADDR 0x48
#define ADC_CHANNEL_AIN0 0
#define DEBOUNCE_MS 50
#define POLL_MS 100
#define TEMP_THRESHOLD 60
#define LOG_FILE "fire_log.txt"

int buzzer_gpio = BUZZER_GPIO;
int flame_sensor_gpio = FLAME_SENSOR_GPIO;
int heat_sensor_gpio = HEAT_SENSOR_GPIO;
int adc_channel = ADC_CHANNEL_AIN0;
int debounce_ms = DEBOUNCE_MS;
int poll_ms = POLL_MS;
int temp_threshold = TEMP_THRESHOLD;

int buzzer_on = 0;
int flame_detected = 0;
int heat_detected = 0;

int buzzer_is_on = 0;
int running = 1;

void sigint_handler(int signum) {
    running = 0;
}

void setup_pi() {
    if (wiringPiSetup() < 0) {
        fprintf(stderr, "Failed to initialize wiringPi\n");
        exit(1);
    }

    if (pigpioSetup() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(1);
    }
}

void read_flame_sensor() {
    static int last_state = 0;
    int current_state = digitalRead(flame_sensor_gpio);
    if (current_state != last_state) {
        last_state = current_state;
        if (current_state == HIGH && !flame_detected) {
            flame_detected = 1;
            usleep(debounce_ms / 200);
        }
    }
}

void read_heat_sensor() {
    int adc_value;
    if (i2c_open(ADS1115_I2C_ADDR, 0) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        exit(1);
    }

    if (i2c_write_byte_data(ADS1115_I2C_ADDR, adc_channel, 0) < 0) {
        fprintf(stderr, "Failed to configure ADC channel\n");
        exit(1);
    }

    if (i2c_read_byte_data(ADS1115_I2C_ADDR, adc_channel) < 0) {
        fprintf(stderr, "Failed to read ADC value\n");
        exit(1);
    }

    adc_value = i2c_read_byte_data(ADS1115_I2C_ADDR, adc_channel);
    i2c_close(ADS1115_I2C_ADDR);

    if (adc_value > temp_threshold) {
        heat_detected = 1;
    }
}

void log_event(const char *message) {
    time_t now = time(NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file for writing\n");
        exit(1);
    }

