#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_FAN 18
#define ADC_THRESHOLD 1023

#define SPI_TRANSFER_SIZE 2

int main(int argc, char *argv[]) {
    int spi_fd, fan_fd;
    struct spidev_ioctl_data spi_data;
    struct gpio_desc *gpio_desc;
    long fan_value;

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd == -1) {
        perror("open spi device");
        exit(EXIT_FAILURE);
    }

    spi_data.data = (void *)0;
    spi_data.len = SPI_TRANSFER_SIZE;

    while (1) {
        // Read from ADC
        if (spidev_ioctl(spi_fd, SPI_RDWR, &spi_data) < 0) {
            perror("spidev_ioctl");
            exit(EXIT_FAILURE);
        }

        // Convert ADC value to current (assuming 10mV/A)
        int adc_value = spi_data.data[0];
        float current = (adc_value * 10.0) / 1023.0;

        // Log current reading with timestamp
        time_t now = time(NULL);
        char timestamp[80];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));
        FILE *log_file = fopen("current_log.txt", "a");
        if (!log_file) {
            perror("fopen current_log.txt");
            exit(EXIT_FAILURE);
        }
        fprintf(log_file, "%s, %d\n", timestamp, current);
        fclose(log_file);

        // Check for sensor absence
        if (adc_value == 0 || adc_value == 255) {
            fprintf(stderr, "Sensor absent, setting fan to OFF\n");
            gpio_set_value(GPIO_FAN, 0);
        } else {
            // Drive fan based on current threshold
            if (current > ADC_THRESHOLD) {
                fprintf(stderr, "Current exceeds threshold, setting fan to HIGH\n");
                gpio_set_value(GPIO_FAN, 1);
            } else {
                gpio_set_value(GPIO_FAN, 0);
            }
        }

        // Sleep for 1 second
        usleep(1000000);
    }

    // Close SPI file descriptor and release resources
    close(spi_fd);
    spi_fd = -1;

    // Release GPIO lines
    gpio_request(GPIO_FAN, "fan");
    gpio_direction_output(GPIO_FAN, 1);

    // Exit cleanly
    exit(EXIT_SUCCESS);
}

