        fprintf(stderr, "CO sensor not found on I2C bus 1.\n");
        return 1;
    }

    // Main loop
    while (1) {
        // Read raw CO resistance from sensor
        if (i2c_read(I2C_BUS, &raw_value, 1) < 0) {
            fprintf(stderr, "Failed to read from CO sensor.\n");
