#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <linux/spi/spidev.h>
#include <linux/gpio.h>
#include <linux/delay.h>

#define GPIO_FLAME_SENSOR 4
#define GPIO_MCP3008_CS 8
#define GPIO_MCP3008_SCLK 11
#define GPIO_MCP3008_MOSI 10
#define GPIO_MCP3008_MISO 9
#define SPI_BUS_SPEED 1000000

#define FLAME_SENSOR_D0 0
#define MCP3008_CHANNEL_0 0

#define LOG_FILE "flame_data.csv"

int flame_sensor_gpio = GPIO_FLAME_SENSOR;
int mcp3008_cs_gpio = GPIO_MCP3008_CS;
int mcp3008_sclk_gpio = GPIO_MCP3008_SCLK;
int mcp3008_mosi_gpio = GPIO_MCP3008_MOSI;
int mcp3008_miso_gpio = GPIO_MCP3008_MISO;

int spi_device = 0;
int spi_speed = SPI_BUS_SPEED;

int spi_handle;

int flame_present = 0;
int temperature_reading = 0;

void spi_init() {
    int file = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (file == -1) {
        perror("Error opening log file");
        exit(EXIT_FAILURE);
    }

    spi_handle = spidev_open(spi_device, 0);
    if (spi_handle == -1) {
        perror("Error opening SPI device");
        close(file);
        exit(EXIT_FAILURE);
    }

    spidev_control(spi_handle, SPID_CSR_SPEED, spi_speed);

    if (spidev_probe(spi_handle, "spidev0.0") < 0) {
        perror("Error probing SPI device");
        close(file);
        spi_close(spi_handle);
        exit(EXIT_FAILURE);
    }

    spidev_set_driver(spi_handle, SPID_DRV_AUTO);
}

void mcp3008_init() {
    if (gpio_request(mcp3008_cs_gpio, "mcp3008_cs") < 0) {
        perror("Error requesting MCP3008 CS pin");
        exit(EXIT_FAILURE);
    }

    if (gpio_direction_output(mcp3008_cs_gpio) < 0) {
        perror("Error setting MCP3008 CS pin as output");
        exit(EXIT_FAILURE);
    }

    if (gpio_request(mcp3008_mosi_gpio, "mcp3008_mosi") < 0) {
        perror("Error requesting MCP3008 MOSI pin");
        exit(EXIT_FAILURE);
    }

