#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_ADDRESS 0x70  // Replace with the actual I2C address of your sensor
#define CO_ALERT_THRESHOLD 25
#define CO_LOG_FILE "co_log.txt"
#define ALERT_LOG_FILE "alert_log.txt"

void read_sensor(int *co_ppm, int *alert) {
    int file_co_log = open(CO_LOG_FILE, "a");
    if (file_co_log == -1) {
        perror("Error opening co_log.txt");
        return;
    }

    int file_alert_log = open(ALERT_LOG_FILE, "a");
    if (file_alert_log == -1) {
        perror("Error opening alert_log.txt");
        close(file_co_log);
        return;
    }

    int i2c_fd;
    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) == -1) {
        perror("Failed to open i2c bus");
        close(file_co_log);
        close(file_alert_log);
        return;
    }

    if (set_i2c_address(i2c_fd, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(file_co_log);
        close(file_alert_log);
        return;
    }

    uint8_t buffer[4];
    if (read(i2c_fd, buffer, 4) != 4) {
        perror("Failed to read from I2C device");
        close(file_co_log);
        close(file_alert_log);
        return;
    }

    *co_ppm = (buffer[0] << 8) | buffer[1];
    *alert = (buffer[2] << 8) | buffer[3];

    close(file_co_log);
    close(file_alert_log);
}

int main(int argc, char *argv[]) {
    int co_ppm, alert;
    pigpio_init(5);

    while (1) {
        read_sensor(&co_ppm, &alert);

        if (*co_ppm >= CO_ALERT_THRESHOLD) {
            fprintf(stderr, "Alert: CO concentration is %d ppm\n", *co_ppm);
            write(1, "Alert: CO concentration is %d ppm\n", *co_ppm, 16);
            fflush(stdout);
        }

        // Append CO ppm to co_log.txt
        FILE *co_log = fopen(CO_LOG_FILE, "a");
        if (co_log == NULL) {
            perror("Failed to open co_log.txt");
            continue;
        }
        fprintf(co_log, "%d\n", *co_ppm);
        fclose(co_log);

        usleep(5000000); // Wait for 5 seconds
    }

    pigpio_stop(pigpio_get_pointer());
    close(1);
    close(2);
    close(3);
    close(0);

    return 0;
}

