#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <pthread.h>
#include <libgpiod.h>

#define I2C_BUS 1
#define GPIO_MIC1 2
#define GPIO_MIC2 3
#define SAMPLE_INTERVAL_MS 100
#define LOG_FILE "audio_log.txt"

#define MAX_LOG_ENTRIES 1000

typedef struct {
    float level;
    struct timespec timestamp;
} LogEntry;

static LogEntry log_entries[MAX_LOG_ENTRIES];
static int log_entries_written = 0;

static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

static int mic1_fd, mic2_fd;

static int read_mic(int fd, float *level) {
    int result;
    struct i2c_rdwr_regval_t regval = {
        .reg = 0x10, // Register for pressure level reading
        .val = 0x00  // Initial value for reading
    };

    result = libgpiod_read_i2c_mem_raw(mic1_fd, &regval, sizeof(regval));
    if (result < 0) {
        perror("Failed to read from MIC1");
        return -999.0f;
    }

    *level = (float)(regval.val) * 0.00488f; // Convert raw value to dB

    return 0;
}

static int read_mic2(int fd, float *level) {
    int result;
    struct i2c_rdwr_regval_t regval = {
        .reg = 0x10, // Register for pressure level reading
        .val = 0x00  // Initial value for reading
    };

    result = libgpiod_read_i2c_mem_raw(mic2_fd, &regval, sizeof(regval));
    if (result < 0) {
        perror("Failed to read from MIC2");
        return -999.0f;
    }

    *level = (float)(regval.val) * 0.00488f; // Convert raw value to dB

    return 0;
}

static void write_log_entry(float level) {
    struct timespec now;
    clock_gettime(CLOCK_REALTIME, &now);

    LogEntry entry;
    entry.level = level;
    entry.timestamp = now;

    pthread_mutex_lock(&mutex);
    if (log_entries_written < MAX_LOG_ENTRIES) {
        log_entries[log_entries_written].level = entry.level;
        log_entries[log_entries_written].timestamp = entry.timestamp;
        log_entries_written++;
        pthread_mutex_unlock(&mutex);
    } else {
        fprintf(stderr, "Log file is full, discarding entry.\n");
    }
}

int main(int argc, char *argv[]) {
    int ret;
    struct i2c_client client;

    ret = libgpiod_init(I2C_BUS);
    if (ret < 0) {
        perror("Failed to initialize I2C");
        return EXIT_FAILURE;
    }

    client.dev = 0;
    client.addr = 0x1A; // I2C address of the IMP23ABSU

    mic1_fd = libgpiod_i2c_open(&client, I2C_BUS);
    if (mic1_fd < 0) {
        perror("Failed to open MIC1");
        return EXIT_FAILURE;
    }

    mic2_fd = libgpiod_i2c_open(&client, I2C_BUS);
    if (mic2_fd < 0) {
        perror("Failed to open MIC2");
        return EXIT_FAILURE;
    }

    while (1) {
        float level1, level2;

        ret = read_mic(mic1_fd, &level1);
        if (ret != 0) {
            write_log_entry(level1);
        }

        ret = read_mic2(mic2_fd, &level2);
        if (ret != 0) {
            write_log_entry(level2);
        }

        usleep(SAMPLE_INTERVAL_MS * 1000 / 1000);
    }

    libgpiod_i2c_close(mic1_fd);
    libgpiod_i2c_close(mic2_fd);
    libgpiod_cleanup(I2C_BUS);

    return EXIT_SUCCESS;
}

