#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <linux/spi/spidev.h>
#include <wiringPi/wiringPi.h>
#include <wiringPi/wiringPiSPI.h>

#define CE0 8
#define CE1 9
#define MISO 9
#define MOSI 10
#define SCLK 11
#define LED 27

#define SAMPLE_RATE 1000  // Samples per second
#define WINDOW_LENGTH 100  // Samples per window
#define HIGH_THRESHOLD 500  // RMS threshold

int spi_device = -1;
int spi_speed = 1000000;

void init_spi(void) {
    spi_device = wiringPiSPISetup(0, 1000000, CE0, CE1);
    if (spi_device == -1) {
        perror("SPI initialization failed");
        exit(EXIT_FAILURE);
    }
}

int read_adc(int channel) {
    uint16_t value;
    int ret;

    ret = spidev_xfer(&channel, 0x00, 0x00, 0, 0, &value);
    if (ret < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    return value;
}

double rms_calculation(int *adc_values, int num_samples) {
    double sum = 0, rms = 0;
    for (int i = 0; i < num_samples; i++) {
        sum += (double)adc_values[i];
    }
    rms = sqrt(sum / num_samples);
    return rms;
}

void log_to_file(const char *timestamp, double mic1_rms, double mic2_rms) {
    FILE *file = fopen("audio_events.csv", "a");
    if (!file) {
        perror("Failed to open file for appending");
        return;
    }

    fprintf(file, "%s,%f,%f\n", timestamp, mic1_rms, mic2_rms);
    fclose(file);
}

void trigger_led(int duration) {
    printf("LED will stay on for %d ms\n", duration);
    sleep(duration / 1000);
    printf("LED turned off\n");
}

