#include <sys/types.h>
#include <sys/stat.h>
#include <sys/wait.h>
#include <errno.h>
#include <signal.h>
#include <pthread.h>

#define I2C_BUS 1
#define SDA_PIN 2
#define SCL_PIN 3
#define LED_PIN 17
#define BUFFER_SIZE 100
#define SAMPLE_RATE 10

typedef struct {
    int fd;
    struct i2c_client *client;
    int channel;
} i2c_context_t;

typedef struct {
    int head;
    int tail;
    int count;
    float buffer[BUFFER_SIZE];
} circular_buffer_t;

circular_buffer_t buffer;

void warning_led_on(int led_fd) {
    write(led_fd, "1", 1);
}

void warning_led_off(int led_fd) {
    write(led_fd, "0", 1);
}

void handle_signal(int signum) {
    printf("Exiting gracefully...\n");
    warning_led_off(LED_PIN);
    pthread_join(thread_id, NULL);
    close(buffer.fd);
    close(led_fd);
    exit(0);
}

void *sample_thread(void *arg) {
    i2c_context_t *i2c_ctx = (i2c_context_t *)arg;
    float current;

    while (1) {
        int result = i2c_read_reg(i2c_ctx->fd, i2c_ctx->client, MLX91204_CONFIG_REG, 1);
        if (result == -1) {
            perror("i2c_read_reg");
            return NULL;
        }

        current = (float)i2c_read_reg(i2c_ctx->fd, i2c_ctx->client, MLX11204_RAW_DATA_REG) << 8 | i2c_read_reg(i2c_ctx->fd, i2c_ctx->client, MLX11204_RAW_DATA_REG) & 0xFF;

        if (current == 0) {
            printf("MLX91204 sensor not found.\n");
            return NULL;
        }

        current /= 1024.0; // Convert raw ADC value to millivolts

        if (buffer.head != buffer.tail) {
            buffer.buffer[buffer.head] = current;
            buffer.head = (buffer.head + 1) % BUFFER_SIZE;
        }

        if (buffer.count == BUFFER_SIZE) {
            float avg_current = 0.0;
            for (int i = 0; i < BUFFER_SIZE; i++) {
                avg_current += buffer.buffer[i];
            }
            avg_current /= BUFFER_SIZE;

            if (avg_current > 50.0) {
                warning_led_on(LED_PIN);
            }
        }

        usleep(1000000 / SAMPLE_RATE); // Delay for 1 second
    }
}

int main() {
    int led_fd, i2c_fd, buffer_fd;
    i2c_context_t i2c_ctx;
    pthread_t thread_id;

    led_fd = open(LED_PIN, O_WRONLY | O_CREAT, 0666);
    if (led_fd == -1) {
        perror("open LED_PIN");
        exit(EXIT_FAILURE);
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR | O_NDELAY);
    if (i2c_fd == -1) {
        perror("open i2c-1");
        exit(EXIT_FAILURE);
    }

    i2c_ctx.client = i2c_get_device(i2c_fd, I2C_BUS);
    if (!i2c_ctx.client) {
        perror("i2c_get_device");
        exit(EXIT_FAILURE);
    }

    i2c_ctx.channel = 0x20; // ADS1115 channel A0

    if (ioctl(i2c_fd, I2C_SLAVE, i2c_ctx.client) == -1) {
        perror("ioctl I2C_SLAVE");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, SLAVE_READ_REG, MLX91204_CONFIG_REG) == -1) {
        perror("ioctl SLAVE_READ_REG");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, SLAVE_READ_DATA_16, MLX11204_RAW_DATA_REG) == -1) {
        perror("ioctl SLAVE_READ_DATA_16");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    buffer_fd = shmget(SHM_SIZE, sizeof(circular_buffer_t), 0666 | IPC_CREAT);
    if (buffer_fd == -1) {
        perror("shmget");
        exit(EXIT_FAILURE);
    }

    if (shmctl(buffer_fd, IPC_RMID, NULL) == -1) {
        perror("shmctl");
        exit(EXIT_FAILURE);
    }

    if (shmctl(buffer_fd, IPC_SET, &buffer) == -1) {
        perror("shmctl");
        exit(EXIT_FAILURE);
    }

    pthread_create(&thread_id, NULL, sample_thread, &i2c_ctx);

    signal(SIGINT, handle_signal);

    printf("Sampling started...\n");
    while (1) {
        usleep(1000000); // Sleep for 1 second
    }

    pthread_join(thread_id, NULL);
    close(i2c_fd);
    close(led_fd);
    shmctl(buffer_fd, IPC_RMID, NULL);
    shmget(SHM_SIZE, NULL, 0666);
    exit(0);
}

