#include <libgpiod/gpio-private.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/epoll.h>
#include <sys/select.h>
#include <time.h>

#define I2C_BUS 1
#define TCS34725_ID 0x20
#define COLOR_REG 0x00
#define CLEAR_REG 0x01
#define RED_REG 0x02
#define GREEN_REG 0x03
#define BLUE_REG 0x04

#define LOG_FILE "color_log.csv"
#define HEADER_ROW "YYYY-MM-DD HH:MM:SS,clear,red,green,blue"
#define INTERVAL_MS 1000
#define MAX_ATTEMPTS 3

int i2c_fd;
int sensor_id;

void sigint_handler(int signum) {
    close(i2c_fd);
    close(log_fd);
    gpiod_disable(GPIO_DEFAULT);
    fprintf(stderr, "Received signal, exiting gracefully.\n");
    exit(EXIT_SUCCESS);
}

void sigterm_handler(int signum) {
    sigint_handler(signum);
}

void init_i2c() {
    int result;
    result = ioctl(i2c_fd, I2C_SLAVE, TCS34725_ID);
    if (result < 0) {
        fprintf(stderr, "Failed to find TCS34725 sensor on I2C bus %d.\n", I2C_BUS);
        exit(EXIT_FAILURE);
    }
    result = ioctl(i2c_fd, I2C_READ_REG, COLOR_REG);
    if (result < 0) {
        fprintf(stderr, "Failed to read sensor ID register.\n");
        exit(EXIT_FAILURE);
    }
    sensor_id = ntohl(result);
    if (sensor_id != 0x1A) {
        fprintf(stderr, "Sensor ID mismatch, exiting.\n");
        exit(EXIT_FAILURE);
    }
}

void read_color_data() {
    int result;
    char buffer[6];

    result = ioctl(i2c_fd, I2C_READ_BYTE_DIST, CLEAR_REG);
    if (result < 0) {
        fprintf(stderr, "Failed to read clear value.\n");
        return;
    }
    result = ioctl(i2c_fd, I2C_READ_BYTE_DIST, RED_REG);
    if (result < 0) {
        fprintf(stderr, "Failed to read red value.\n");
        return;
    }
    result = ioctl(i2c_fd, I2C_READ_BYTE_DIST, GREEN_REG);
    if (result < 0) {
        fprintf(stderr, "Failed to read green value.\n");
        return;
    }
    result = ioctl(i2c_fd, I2C_READ_BYTE_DIST, BLUE_REG);
    if (result < 0) {
        fprintf(stderr, "Failed to read blue value.\n");
        return;
    }

    time_t now = time(NULL);
    struct tm *timeinfo = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open color_log.csv for appending.\n");
        return;
    }

    fprintf(log_file, "%s,clear,%d,%d,%d,%d\n", timestamp,
            (int)clear_value, (int)red_value, (int)green_value, (int)blue_value);
    fclose(log_file);
}

int main(int argc, char *argv[]) {
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    init_i2c();

    if (open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644) < 0) {
        perror("Failed to open color_log.csv");
        exit(EXIT_FAILURE);
    }

    while (1) {
        read_color_data();
        usleep(INTERVAL_MS / 1000);

        int attempts = 0;
        while (attempts < MAX_ATTEMPTS) {
            if (ioctl(i2c_fd, I2C_READ_BYTE_DIST, CLEAR_REG) < 0) {
                attempts++;
                if (attempts == MAX_ATTEMPTS) {
                    fprintf(stderr, "Three consecutive I2C read failures, exiting.\n");
                    exit(EXIT_FAILURE);
                }
            } else {
                break;
            }
        }
    }

    close(i2c_fd);
    fclose(log_fd);
    gpiod_disable(GPIO_DEFAULT);
    return 0;
}

