    if (!log_file) {
        fprintf(stderr, "Failed to open color_log.csv for appending.\n");
        return;
    }

    fprintf(log_file, "%s,clear,%d,%d,%d,%d\n", timestamp,
            (int)clear_value, (int)red_value, (int)green_value, (int)blue_value);
    fclose(log_file);
}

int main(int argc, char *argv[]) {
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    init_i2c();

    if (open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644) < 0) {
        perror("Failed to open color_log.csv");
        exit(EXIT_FAILURE);
    }

    while (1) {
        read_color_data();
        usleep(INTERVAL_MS / 1000);

        int attempts = 0;
        while (attempts < MAX_ATTEMPTS) {
            if (ioctl(i2c_fd, I2C_READ_BYTE_DIST, CLEAR_REG) < 0) {
                attempts++;
                if (attempts == MAX_ATTEMPTS) {
                    fprintf(stderr, "Three consecutive I2C read failures, exiting.\n");
                    exit(EXIT_FAILURE);
                }
            } else {
                break;
            }
        }
    }

    close(i2c_fd);
    fclose(log_fd);
    gpiod_disable(GPIO_DEFAULT);
    return 0;
}
