#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <libgpiod.h>

#define MLX91211_CE GPIO8
#define MCP3008_SCLK GPIO11
#define MCP3008_MOSI GPIO10
#define MCP3008_MISO GPIO9
#define MCP3008_CHANNEL 0
#define MOTOR_SHUTDOWN GPIO17

#define LOG_FILE "current_log.csv"
#define MAX_ERRORS 3
#define SAMPLE_INTERVAL 1000

int spi_fd;
int mcp3008_channel;

void spi_init(void) {
    spi_fd = open("/dev/spidev0.0", O_RDWR | O_NOCTTY | O_NDELAY);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }
}

int mcp3008_init(void) {
    if (libgpiod_init() < 0) {
        perror("Failed to initialize libgpiod");
        exit(EXIT_FAILURE);
    }

    if (gpio_request(MLX91211_CE, "MLX91211_CE") < 0) {
        perror("Failed to request MLX91211_CE");
        exit(EXIT_FAILURE);
    }

    if (gpio_direction_output(MLX91211_CE) < 0) {
        perror("Failed to set MLX91211_CE as output");
        exit(EXIT_FAILURE);
    }

    if (gpio_request(MCP3008_SCLK, "MCP3008_SCLK") < 0) {
        perror("Failed to request MCP3008_SCLK");
        exit(EXIT_FAILURE);
    }

    if (gpio_direction_output(MCP3008_SCLK) < 0) {
        perror("Failed to set MCP3008_SCLK as output");
        exit(EXIT_FAILURE);
    }

    if (gpio_request(MCP3008_MOSI, "MCP3008_MOSI") < 0) {
        perror("Failed to request MCP3008_MOSI");
        exit(EXIT_FAILURE);
    }

    if (gpio_direction_output(MCP3008_MOSI) < 0) {
        perror("Failed to set MCP3008_MOSI as output");
        exit(EXIT_FAILURE);
    }

    if (gpio_request(MCP3008_MISO, "MCP3008_MISO") < 0) {
        perror("Failed to request MCP3008_MISO");
        exit(EXIT_FAILURE);
    }

    if (gpio_direction_output(MCP3008_MISO) < 0) {
        perror("Failed to set MCP3008_MISO as output");
        exit(EXIT_FAILURE);
    }

    if (gpio_request(MOTOR_SHUTDOWN, "MOTOR_SHUTDOWN") < 0) {
        perror("Failed to request MOTOR_SHUTDOWN");
        exit(EXIT_FAILURE);
    }

    if (gpio_direction_output(MOTOR_SHUTDOWN) < 0) {
        perror("Failed to set MOTOR_SHUTDOWN as output");
        exit(EXIT_FAILURE);
    }

    return 0;
}

int adc_read(void) {
    int count = 0;
    int data[8];

    while (count < 20); // Wait for SPI to settle

    if (libgpiod_read(MCP3008_CHANNEL, data, 8) < 0) {
        if (errno == EIO || errno == E2BIG) {
            for (int i = 0; i < MAX_ERRORS; i++) {
                if (libgpiod_read(MCP3008_CHANNEL, data, 8) == 0)
                    break;
            }
        } else {
            perror("Failed to read from MCP3008");
            exit(EXIT_FAILURE);
        }
    }

    return data[0];
}

void log_current(int current) {
    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        if (errno == EACCES) {
            fprintf(stderr, "Cannot write to %s: Permission denied\n", LOG_FILE);
            exit(EXIT_FAILURE);
        } else {
            perror("Failed to open file for appending");
            exit(EXIT_FAILURE);
        }
    }

    if (file) {
        fprintf(file, "%d,%f\n", time(NULL), current);
        fclose(file);
    }
}

void handle_over_current(void) {
    printf("Over-current detected! Motor disabled.\n");
    gpio_set_level(MOTOR_SHUTDOWN, 0);
    usleep(1000000);
    gpio_set_level(MOTOR_SHUTDOWN, 1);
}

void signal_handler(int signum) {
    printf("Received signal %d, cleaning up and exiting...\n", signum);
    spi_close();
    mcp3008_close();
    gpio_free(MLX91211_CE);
    gpio_free(MCP3008_SCLK);
    gpio_free(MCP3008_MOSI);
    gpio_free(MCP3008_MISO);
    gpio_free(MOTOR_SHUTDOWN);
    exit(0);
}

int main(int argc, char *argv[]) {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    spi_init();
    mcp3008_init();

    while (1) {
        int current = adc_read();
        log_current(current);

        if (current > 10.0) {
            handle_over_current();
        }

        usleep(SAMPLE_INTERVAL * 1000);
    }

    spi_close();
    mcp3008_close();
    gpio_free(MLX91211_CE);
    gpio_free(MCP3008_SCLK);
    gpio_free(MCP3008_MOSI);
    gpio_free(MCP3008_MISO);
    gpio_free(MOTOR_SHUTDOWN);

    return 0;
}

