#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x5A  // MLX90817 default I2C address
#define LOG_FILE "pressure_log.csv"
#define LOG_INTERVAL_S 1  // Read every second

// I2C register addresses for MLX90817
#define MLX90817_DATA_REG 0x28
#define MLX90817_STATUS_REG 0x29
#define MLX90817_CONFIG_REG 0x2A
#define MLX90817_PRESSURE_REG 0x2B

// Function to read I2C register
int i2c_read(int file, unsigned char reg, unsigned char *data, int len) {
    int ret;
    ret = read(file, data, len);
    if (ret < 0) {
        perror("i2c_read");
        return -1;
    }
    return ret;
}

// Function to write I2C register
int i2c_write(int file, unsigned char reg, unsigned char data) {
    int ret;
    ret = write(file, &data, 1);
    if (ret < 0) {
        perror("i2c_write");
        return -1;
    }
    return ret;
}

// Function to initialize I2C
int init_i2c() {
    int file = open("/dev/i2c-1", O_RDWR);
    if (file == -1) {
        perror("open /dev/i2c-1");
        return -1;
    }

    if (ioctl(file, I2C_SLAVE, I2C_ADDR) == -1) {
        perror("ioctl I2C_SLAVE");
        close(file);
        return -1;
    }

    return file;
}

// Function to close I2C
void close_i2c(int file) {
    close(file);
}

// Function to open the log file
int open_log_file() {
    int fd = open(LOG_FILE, "w");
    if (fd == -1) {
        perror("open log file");
        return -1;
    }
    return fd;
}

// Function to flush and close the log file
void close_log_file(int fd) {
    if (fd != -1) {
        write(fd, "\n", 1);
        close(fd);
    }
}

// Function to write to the log file
void log_pressure(unsigned int timestamp, double pressure) {
    char timestamp_str[32];
    time_t now = time(NULL);
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%dT%H:%M:%SZ", localtime(&now));

    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log file");
        return;
    }

    fprintf(fp, "%s,%.2f\n", timestamp_str, pressure);
    fclose(fp);
}

int main(int argc, char *argv[]) {
    int i2c_fd, log_fd;
    struct i2c_client i2c_client;

    // Initialize I2C
    i2c_fd = init_i2c();
    if (i2c_fd == -1) {
        return 1;
    }

    // Open log file
    log_fd = open_log_file();
    if (log_fd == -1) {
        close_i2c(i2c_fd);
        return 1;
    }

    // Read pressure from sensor
    unsigned char config_reg[1];
    unsigned char pressure_reg[4];

    while (1) {
        // Read configuration register
        if (i2c_read(i2c_fd, MLX90817_CONFIG_REG, config_reg, 1) == -1) {
            fprintf(stderr, "Failed to read config register\n");
            continue;
        }

        // Check for sensor presence
        if (config_reg[0] & 0x02) {  // Check if the sensor is present
            // Read pressure register
            if (i2c_read(i2c_fd, MLX90817_PRESSURE_REG, pressure_reg, 4) == -1) {
                fprintf(stderr, "Failed to read pressure register\n");
                continue;
            }

            // Convert pressure to kPa
            double pressure = (double)(pressure_reg[0] << 8 | pressure_reg[1]) / 1000.0;

            // Log the pressure
            log_pressure(get_iso8601_timestamp(), pressure);
        }

        // Sleep for the specified interval
        usleep(LOG_INTERVAL_S * 1000000);
    }

    // Close I2C and log file
    close_i2c(i2c_fd);
    close_log_file(log_fd);

    // Clean up pigpio
    pigpio_terminate(1000);

    return 0;
}

// Helper function to get current ISO 8601 UTC timestamp
char *get_iso8601_timestamp() {
    time_t now = time(NULL);
    struct tm *local_time = localtime(&now);
    char timestamp_str[32];
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%dT%H:%M:%S", local_time);
    return timestamp_str;
}

