#include <sys/mman.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <errno.h>
#include <pigpio.h>

#define AIN0_ADDRESS 0x48  // ADS1115 AIN0 address
#define AIN1_ADDRESS 0x49  // ADS1115 AIN1 address
#define LED_PIN 17
#define I2C_BUS_NUMBER 1   // Assuming I2C bus 1

#define MAX_RETRIES 3

int pressure_channel = 0;
int temperature_channel = 1;

int main() {
    int led_fd;
    int ret;
    int i2c_fd;
    int retries = 0;
    int pressure_kpa = 0.0;
    int temperature_c = 0.0;

    gpioInitialise();

    led_fd = open(LED_PIN, O_WRONLY | O_CREAT, 0666);
    if (led_fd == -1) {
        perror("Failed to open LED pin");
        exit(EXIT_FAILURE);
    }

    gpioSetMode(LED_PIN, GPIO_OUTPUT);

    while (1) {
        ret = i2c_open(I2C_BUS_NUMBER, "melexis_mlx90834");
        if (ret < 0) {
            if (retries < MAX_RETRIES) {
                printf("I2C error, retrying...\n");
                ret = i2c_open(I2C_BUS_NUMBER, "melexis_mlx90834");
                retries++;
            } else {
                printf("Failed to connect to MLX90834 after %d retries.\n", MAX_RETRIES);
                break;
            }
        }

        ret = i2c_write_reg_byte(i2c_fd, AIN0_ADDRESS, 0x40);
        if (ret < 0) {
            printf("Failed to write to AIN0 address.\n");
            i2c_close(i2c_fd);
            continue;
        }

        ret = i2c_write_reg_byte(i2c_fd, AIN1_ADDRESS, 0x40);
        if (ret < 0) {
            printf("Failed to write to AIN1 address.\n");
            i2c_close(i2c_fd);
            continue;
        }

        ret = i2c_read_byte_range(i2c_fd, AIN0_ADDRESS, 0x00, 1);
        if (ret < 0) {
            printf("Failed to read from AIN0 address.\n");
            i2c_close(i2c_fd);
            continue;
        }

        pressure_kpa = (ret * 2) / 1024;

        ret = i2c_read_byte_range(i2c_fd, AIN1_ADDRESS, 0x00, 1);
        if (ret < 0) {
            printf("Failed to read from AIN1 address.\n");
            i2c_close(i2c_fd);
            continue;
        }

        temperature_c = (ret * 256) / 1024;

        if (pressure_kpa > 105.0) {
            gpioWrite(LED_PIN, HIGH);
        }

        printf("Pressure: %.2f kPa, Temperature: %.2f °C\n", pressure_kpa, temperature_c);

        usleep(1000000);
    }

    gpioDisable(LED_PIN);
    i2c_close(i2c_fd);
    close(led_fd);
    pigpioTerminate();

    return 0;
}

