#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <linux/spi/spidev.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <signal.h>
#include <pthread.h>

#define SPI_DEVICE 0
#define SPI_SPEED 1000000
#define MCP3008_CHANNEL 0
#define CO_THRESHOLD 2.5

#define LOG_FILE "co_log.txt"
#define ALARM_PIN 4

int spi_fd;
struct spidev_ioctl_data spi_data;

void spi_init(void) {
    spi_fd = spidev_open(SPI_DEVICE, 0);
    if (spi_fd < 0) {
        perror("spidev_open");
        exit(EXIT_FAILURE);
    }

    spi_data.flags = SPI_FLAG_RSS;
    if (ioctl(spi_fd, SPI_RSS, &spi_data) < 0) {
        perror("ioctl(SPI_RSS)");
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_SET_BAUDRATE, SPI_SPEED) < 0) {
        perror("ioctl(SPI_SET_BAUDRATE)");
        exit(EXIT_FAILURE);
    }
}

int mcp3008_read(void) {
    uint8_t cmd[2];
    cmd[0] = 0xAE; // Set to single shot mode
    cmd[1] = 0;

    if (spidev_write(spi_fd, cmd, 2) < 0) {
        perror("spidev_write");
        return -1;
    }

    cmd[0] = 0x00; // Read channel 0
    if (spidev_read(spi_fd, cmd, 1) < 0) {
        perror("spidev_read");
        return -1;
    }

    return cmd[0];
}

void log_voltage(double voltage) {
    struct tm now = *localtime(NULL);
    char timestamp[80];
    sprintf(timestamp, "%04d-%02d-%02d %02d:%02d:%02d", now.tm_year + 1900,
            now.tm_mon + 1, now.tm_mday, now.tm_hour, now.tm_min, now.tm_sec);

    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        perror("fopen");
        return;
    }

    fprintf(file, "%s,Voltage: %.2f V\n", timestamp, voltage);
    fclose(file);
}

void alarm_control(int state) {
    if (state) {
        printf("Alarm OFF\n");
        // Turn off the alarm (GPIO 4)
    } else {
        printf("Alarm ON\n");
        // Turn on the alarm (GPIO 4)
    }
}

void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        alarm_control(0);
        spi_close();
        fclose(stdout);
        exit(0);
    }
}

void *read_thread(void *arg) {
    while (1) {
        double voltage = mcp3008_read();
        if (voltage == -1) {
            usleep(1000000); // Wait for 1 second
            continue;
        }

        if (voltage > CO_THRESHOLD) {
            printf("Voltage exceeds threshold, setting alarm\n");
            alarm_control(1);
        }

        log_voltage(voltage);
        usleep(1000000000); // Sleep for 1 second
    }
    return NULL;
}

int main(int argc, char *argv[]) {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    spi_init();

    pthread_t thread;
    if (pthread_create(&thread, NULL, read_thread, NULL) != 0) {
        perror("pthread_create");
        spi_close();
        fclose(stdout);
        exit(EXIT_FAILURE);
    }

    pthread_join(thread, NULL);

    spi_close();
    fclose(stdout);
    return 0;
}

