#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/wait.h>
#include <errno.h>
#include <pthread.h>
#include <time.h>

#define I2C_BUS 1
#define SDA_PIN 2
#define SCL_PIN 3
#define MLX90830_CHANNEL AIN0
#define SAMPLE_RATE 1000
#define LOG_FILE "pressure_log.txt"

typedef struct {
    int fd;
    struct i2c_client *client;
} i2c_context_t;

void log_entry(const char *timestamp, double pressure) {
    time_t now = time(NULL);
    struct tm *local_time = localtime(&now);
    char time_str[80];
    sprintf(time_str, "%04d-%02d-%02d %02d:%02d:%02d",
            local_time->tm_year + 1900, local_time->tm_mon + 1,
            local_time->tm_mday, local_time->tm_hour, local_time->tm_min, local_time->tm_sec);

    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        perror("Failed to open log file");
        return;
    }
    fprintf(file, "%s,%f\n", time_str, pressure);
    fclose(file);
}

int main(int argc, char *argv[]) {
    pthread_t thread;
    i2c_context_t i2c_context;
    int i2c_fd;
    int adc_channel;
    int adc_value;
    double pressure;

    if (argc != 2) {
        fprintf(stderr, "Usage: %s <sensor_address>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    i2c_context.fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_context.fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    struct i2c_client *client = i2c_open_dev(i2c_context.fd, I2C_BUS);
    if (!client) {
        perror("Failed to open I2C client");
        close(i2c_context.fd);
        exit(EXIT_FAILURE);
    }

    i2c_context.client = client;

    if (ioctl(i2c_context.fd, I2C_SLAVE, (u_int8_t)atoi(argv[1])) < 0) {
        perror("Failed to set I2C address");
        close(i2c_context.fd);
        i2c_close(client);
        exit(EXIT_FAILURE);
    }

    adc_channel = 0; // Assuming the MLX90830 is on channel AIN0
    adc_value = 0;

    while (1) {
        if (read(i2c_context.fd, &adc_value, 1) != 1) {
            perror("Failed to read from ADC");
            break;
        }

        pressure = (adc_value * 3.3) / 65535.0; // Convert 16-bit ADC value to pressure (0-100 kPa)

        if (pressure < 0.0 || pressure > 100.0) {
            fprintf(stderr, "Pressure out of range: %f kPa\n", pressure);
            log_entry(time(NULL), 0.0);
            continue;
        }

        log_entry(time(NULL), pressure);

        usleep(SAMPLE_RATE * 1000000 / 1000); // Delay for 1 second
    }

    i2c_close(client);
    close(i2c_context.fd);

    return 0;
}

