#include <netdb.h>
#include <arpa/inet.h>
#include <openssl/ssl.h>
#include <openssl/err.h>
#include <libgpiod/gpio.h>
#include <pigpio.h>

#define GPIO_CE0 8
#define ADC_CHANNEL 0
#define TEMP_SCALE 0.001
#define HUMIDITY_SCALE 100.0
#define EMAIL_THRESHOLD 80

void send_email(const char *to) {
    char command[256];
    sprintf(command, "ssmtp -t -v -u your_email@example.com -p your_password %s", to);
    system(command);
}

int main(int argc, char *argv[]) {
    int spi_fd, adc_fd, file_desc;
    struct stat file_stat;
    struct timeval tv;
    pid_t child_pid;

    // Initialize libgpiod
    if (libgpiod_init() < 0) {
        perror("libgpiod_init");
        return EXIT_FAILURE;
    }

    // Initialize pigpio
    if (piGPIO_init() < 0) {
        perror("piGPIO_init");
        return EXIT_FAILURE;
    }

    // Set GPIO8 as output for CE0
    gpioOutput(GPIO_CE0);

    // Open SPI0 bus
    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("open spi");
        return EXIT_FAILURE;
    }

    // Configure SPI0 for MCP3208
    if (spi_write(spi_fd, 0x01, 2) != 2) {
        perror("SPI0 write failed");
        return EXIT_FAILURE;
    }

    // Initialize ADC
    if (gpioPinMode(GPIO_CE0, GPIO_OUTPUT) < 0) {
        perror("gpioPinMode failed");
        return EXIT_FAILURE;
    }

    // Open humidity_log.txt for appending
    file_desc = open("humidity_log.txt", O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (file_desc < 0) {
        perror("open humidity_log.txt");
        return EXIT_FAILURE;
    }

    // Get current timestamp
    gettimeofday(&tv, NULL);
    strftime(const char *buf, size_t bufsiz, "%Y-%m-%d %H:%M:%S", localtime(&tv.tv_sec));

    // Read ADC data
    uint16_t adc_value;
    if (spi_read(spi_fd, &adc_value, 1) != 1) {
        perror("SPI read failed");
        return EXIT_FAILURE;
    }

    // Convert ADC value to humidity and temperature
    float humidity = (adc_value * HUMIDITY_SCALE) / 1023.0;
    float temperature = (adc_value * TEMP_SCALE) / 1023.0 - 50.0;

    // Append to file
    if (write(file_desc, buf, strlen(buf)) != (size_t)strlen(buf)) {
        perror("write to file failed");
        return EXIT_FAILURE;
    }

    // Check if humidity exceeds threshold
    if (humidity > EMAIL_THRESHOLD) {
        send_email("recipient@example.com");
    }

    // Close resources
    close(file_desc);
    close(spi_fd);
    gpioPinDisable(GPIO_CE0);
    piGPIO_cleanup();

    // Handle SIGINT and SIGTERM
    if (signal(SIGINT, signal_handler) == SIG_IGN || signal(SIGTERM, signal_handler) == SIG_IGN) {
        perror("Failed to set signal handler");
        return EXIT_FAILURE;
    }

    return EXIT_0;
}

void signal_handler(int signum) {
    printf("Received signal %d, cleaning up and exiting...\n", signum);
    exit(EXIT_SUCCESS);
}

int signal_handler(int signum) {
    perror("Failed to set signal handler");
    return EXIT_FAILURE;
}

