#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define CE_PIN 4
#define SCLK_PIN 11
#define MOSI_PIN 10
#define MISO_PIN 9
#define SPI_MODE 0
#define SPI_BITS 8
#define SPI_SPEED 1000000
#define ADC_CHANNEL 0
#define TEMP_CEL_MIN -40
#define TEMP_CEL_MAX 125
#define LOG_FILE "temperature_log.csv"

#define BUFFER_SIZE 1

void spi_open(int fd, int mode, int bits, int speed) {
    if (ioctl(fd, SPI_IOC_MESSAGE(1), &mode) < 0) {
        perror("ioctl spi_open");
        exit(EXIT_FAILURE);
    }
    if (ioctl(fd, SPI_IOC_MESSAGE(2), &bits) < 0) {
        perror("ioctl spi_open");
        exit(EXIT_FAILURE);
    }
    if (ioctl(fd, SPI_IOC_MESSAGE(3), &speed) < 0) {
        perror("ioctl spi_open");
        exit(EXIT_FAILURE);
    }
}

void spi_close(int fd) {
    if (close(fd) < 0) {
        perror("close spi");
        exit(EXIT_FAILURE);
    }
}

void mcp3208_read(int fd, int channel) {
    uint8_t cmd[2] = {SPI_IOC_MESSAGE(4), channel};
    if (ioctl(fd, SPI_IOC_MESSAGE(5), cmd) < 0) {
        perror("ioctl mcp3208_read");
        exit(EXIT_FAILURE);
    }
}

int main() {
    int fd, ret;
    struct sigaction sa;
    sigset_t sigset;

    // Initialize signal handlers
    sa.sa_handler = sigint_handler;
    sigemptyset(&sigset);
    sigaddset(&sigset, SIGINT);
    sigaddset(&sigset, SIGTERM);
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction sigint");
        exit(EXIT_FAILURE);
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction SIGTERM");
        exit(EXIT_FAILURE);
    }

    // Open SPI device
    fd = open(SPI_DEVICE, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd < 0) {
        perror("open SPI_DEVICE");
        exit(EXIT_FAILURE);
    }

    // Configure SPI
    spi_open(fd, SPI_MODE, SPI_BITS, SPI_SPEED);

    // Initialize GPIO for CE0
    if (write(fd, (void *)CE_PIN, 1) != 1) {
        perror("write CE_PIN");
        spi_close(fd);
        exit(EXIT_FAILURE);
    }

    // Read ADC data at 1 Hz
    while (1) {
        ret = mcp3208_read(fd, ADC_CHANNEL);
        if (ret < 0) {
            perror("mcp3208_read");
            spi_close(fd);
            exit(EXIT_FAILURE);
        }

        // Validate ADC reading
        if (ret == 0) {
            // Sensor absent or out of range
            printf("Error: Invalid ADC reading\n");
            continue;
        }

        // Convert ADC value to temperature
        int16_t adc_value = read_adc_word(ret);
        float temperature_fahrenheit = (adc_value * 3.3) / 6144;
