        fprintf(log_file, "%llu, %d, %d, 0\n", (long long)clock(), hr, spO2);

        // Sleep for the specified interval
        usleep(SAMPLE_INTERVAL * 1000);
    }

    // Close resources on exit
    fclose(log_file);
    close(i2c_fd);
    pigpio_terminate(1000);

    return EXIT_SUCCESS;
