#include <sys/types.h>
#include <sys/wait.h>
#include <pthread.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x43
#define LOG_FILE "environmental_data.csv"
#define SAMPLE_INTERVAL 5000 // 5 seconds

typedef struct {
    int fd;
    struct i2c_client *client;
    int pressure_msb;
    int pressure_lsb;
    int temperature_msb;
    int temperature_lsb;
    int crc_msb;
    int crc_lsb;
} sensor_data;

void log_reading(const char *timestamp, int pressure_msb, int pressure_lsb, int temperature_msb, int temperature_lsb, int crc_msb, int crc_lsb) {
    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        perror("Failed to open log file");
        return;
    }
    time_t now = time(NULL);
    fprintf(file, "%s, %d,%d,%d,%d,%d\n", ctime(&now), pressure_msb, pressure_lsb, temperature_msb, temperature_lsb, crc_msb, crc_lsb);
    fclose(file);
}

void* read_sensor_data(void *arg) {
    sensor_data data;
    int ret;

    while (1) {
        ret = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
        if (ret < 0) {
            perror("Failed to open log file");
            return NULL;
        }

        ret = ioctl(fileno(log_fd), I2C_SLAVE, I2C_ADDR);
        if (ret < 0) {
            perror("Failed to set I2C slave address");
            return NULL;
        }

        ret = ioctl(fileno(log_fd), I2C_MEM_READ, &data);
        if (ret < 0) {
            perror("Failed to read from I2C device");
            return NULL;
        }

        if (ret == 0) {
            log_reading(ctime(NULL), data.pressure_msb, data.pressure_lsb, data.temperature_msb, data.temperature_lsb, data.crc_msb, data.crc_lsb);
            printf("Pressure: %d MSB, %d LSB, Temperature: %d MSB, %d LSB\n", data.pressure_msb, data.pressure_lsb, data.temperature_msb, data.temperature_lsb);
        }

        usleep(SAMPLE_INTERVAL * 1000000 / 1000); // Convert 5 seconds to microseconds
    }

    return NULL;
}

int main(int argc, char *argv[]) {
    pthread_t thread;
    int log_fd;

    log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    if (ioctl(log_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(log_fd);
        return EXIT_FAILURE;
    }

    if (ioctl(log_fd, I2C_MEM_READ, NULL) < 0) {
        perror("Failed to read from I2C device");
        close(log_fd);
        return EXIT_FAILURE;
    }

    if (pthread_create(&thread, NULL, read_sensor_data, NULL) != 0) {
        perror("Failed to create thread");
        close(log_fd);
        return EXIT_FAILURE;
    }

    printf("Sensor reading thread started.\n");

    while (1) {
        sleep(1);
    }

    pthread_join(thread, NULL);

    if (close(log_fd) < 0) {
        perror("Failed to close log file");
    }

    printf("Exiting...\n");
    return EXIT_SUCCESS;
}

