#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <libgpiod/gpio.h>
#include <pigpio.h>

#define ADC_CHANNEL 0
#define SAMPLE_INTERVAL_SECONDS 60
#define LOG_FILE "moisture_log.txt"

void spi_init() {
    int spi_device = 0; // CE0 on Raspberry Pi 4
    if (gpio_setup(spi_device, GP_OUTPUT) < 0) {
        perror("Failed to initialize SPI device");
        exit(EXIT_FAILURE);
    }
}

void adc_init() {
    if (libgpiod_init() < 0) {
        perror("Failed to initialize libgpiod");
        exit(EXIT_FAILURE);
    }

    if (gpio_request(ADC_CHANNEL, "MCP3008_CH0") < 0) {
        perror("Failed to request ADC channel");
        exit(EXIT_FAILURE);
    }

    if (gpio_direction_output(ADC_CHANNEL) < 0) {
        perror("Failed to set ADC channel as output");
        exit(EXIT_FAILURE);
    }
}

void write_to_spi(unsigned char *data) {
    if (libgpiod_write_spi(ADC_CHANNEL, data, 1) < 0) {
        perror("Failed to write to SPI");
        exit(EXIT_FAILURE);
    }
}

int read_adc_value() {
    unsigned int adc_value;
    if (libgpiod_read_adc(ADC_CHANNEL, &adc_value) < 0) {
        perror("Failed to read ADC value");
        return -1;
    }

    if (adc_value < 0 || adc_value > 1023) {
        return -1; // Out of range
    }

    return adc_value;
}

void log_moisture_data(const char *timestamp, int adc_value) {
    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        perror("Failed to open log file");
        return;
    }

    fprintf(file, "%s,%d\n", timestamp, adc_value);
    fclose(file);
}

void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        spi_cleanup();
        adc_cleanup();
        pigpio_cleanup();
        exit(0);
    }
}

int main() {
    spi_init();
    adc_init();

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        unsigned char data[1];
        data[0] = 0x01; // Command to read ADC value from channel 0

        write_to_spi(data);
        int adc_value = read_adc_value();

        if (adc_value != -1) {
            char timestamp[32];
            time_t now = time(NULL);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", localtime(&now));

            log_moisture_data(timestamp, adc_value);
        }

        usleep(SAMPLE_INTERVAL_SECONDS * 1000000); // Convert seconds to microseconds
    }

    return 0;
}

