    if (adc_value < 0 || adc_value > 1023) {
        return -1; // Out of range
    }

    return adc_value;
}

void log_moisture_data(const char *timestamp, int adc_value) {
    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        perror("Failed to open log file");
        return;
    }

    fprintf(file, "%s,%d\n", timestamp, adc_value);
    fclose(file);
}

void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        spi_cleanup();
        adc_cleanup();
        pigpio_cleanup();
        exit(0);
    }
}

int main() {
    spi_init();
    adc_init();

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        unsigned char data[1];
        data[0] = 0x01; // Command to read ADC value from channel 0

        write_to_spi(data);
        int adc_value = read_adc_value();

        if (adc_value != -1) {
            char timestamp[32];
            time_t now = time(NULL);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", localtime(&now));

            log_moisture_data(timestamp, adc_value);
        }

        usleep(SAMPLE_INTERVAL_SECONDS * 1000000); // Convert seconds to microseconds
    }

    return 0;
}
