#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <json-c/json.h>
#include <libgpiod/gpio.h>

#define MCP3008_CHANNEL 0
#define MCP3008_SPI_MODE 0
#define MCP3008_SPI_SPEED 1000000
#define LED_GPIO 17
#define SPI_CLOCK_POLARITY 0
#define SPI_CLOCK_PHASE 0
#define SPI_BITS_PER_WORD 8
#define SPI_MODE_0 0

#define UPDATE_INTERVAL_SEC 5.0
#define SLEEP_INCREMENT_MS 100

#define LED_ON 1
#define LED_OFF 0

static json_object *water_levels = NULL;

void spi_init(void) {
    int ret;
    ret = gpio_request(8, "MCP3008_CE0");
    if (ret != 0) {
        perror("gpio_request");
        exit(EXIT_FAILURE);
    }

    ret = gpio_direction_output(8);
    if (ret != 0) {
        perror("gpio_direction_output");
        exit(EXIT_FAILURE);
    }

    ret = gpio_set_level(8, LED_OFF);
    if (ret != 0) {
        perror("gpio_set_level");
        exit(EXIT_FAILURE);
    }

    ret = spi_enable();
    if (ret != 0) {
        perror("spi_enable");
        exit(EXIT_FAILURE);
    }

    ret = spi_configure(SPI_CLOCK_SPEED, SPI_MODE_0, SPI_CPOL_0, SPI_CPHA_0);
    if (ret != 0) {
        perror("spi_configure");
        exit(EXIT_FAILURE);
    }
}

void mcp3008_read(uint16_t channel) {
    int ret;
    ret = spi_master_send(0x40, 0x00, 0x00, 0x00, 0x00);
    if (ret < 0) {
        perror("spi_master_send");
        return;
    }

    uint16_t data = spi_master_receive(0x40, 1);
    if (data == 0) {
        return;
    }

    int adc_value = data >> 8;
    int adc_bit_value = data & 0x00FF;

    float voltage = (adc_bit_value * 3.30 / 1023.0);
    float percentage = voltage * 100;

    json_object *level = json_object_new();
    json_object_set_new(level, "timestamp", json_object_new_datetime());
    json_object_set(level, "percentage", json_object_new_number(percentage));
    json_object_set(water_levels, json_object_get(level, "timestamp").ptr, json_object_new_array());
    json_object_set(water_levels, json_object_get(level, "percentage").ptr, json_object_new_number(percentage));
    json_object_put(level);

    json_object_put(water_levels);
}

void led_control(int state) {
    int ret;
    ret = gpio_set_level(LED_GPIO, state);
    if (ret != 0) {
        perror("gpio_set_level");
        exit(EXIT_FAILURE);
    }
}

void signal_handler(int signum) {
    printf("Received signal %d, exiting gracefully...\n", signum);
    json_object_put(water_levels);
    led_control(LED_OFF);
    spi_disable();
    exit(0);
}

int main(int argc, char *argv[]) {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    spi_init();

    while (1) {
        mcp3008_read(MCP3008_CHANNEL);
        usleep(SLEEP_INCREMENT_MS * 1000 / 1000);
    }

    json_object_put(water_levels);
    led_control(LED_OFF);
    spi_disable();

    return 0;
}

