    json_object *level = json_object_new();
    json_object_set_new(level, "timestamp", json_object_new_datetime());
    json_object_set(level, "percentage", json_object_new_number(percentage));
    json_object_set(water_levels, json_object_get(level, "timestamp").ptr, json_object_new_array());
    json_object_set(water_levels, json_object_get(level, "percentage").ptr, json_object_new_number(percentage));
    json_object_put(level);

    json_object_put(water_levels);
}

void led_control(int state) {
    int ret;
    ret = gpio_set_level(LED_GPIO, state);
    if (ret != 0) {
        perror("gpio_set_level");
        exit(EXIT_FAILURE);
    }
}

void signal_handler(int signum) {
    printf("Received signal %d, exiting gracefully...\n", signum);
    json_object_put(water_levels);
    led_control(LED_OFF);
    spi_disable();
    exit(0);
}

int main(int argc, char *argv[]) {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    spi_init();

    while (1) {
        mcp3008_read(MCP3008_CHANNEL);
        usleep(SLEEP_INCREMENT_MS * 1000 / 1000);
    }

    json_object_put(water_levels);
    led_control(LED_OFF);
    spi_disable();

    return 0;
}
