#include <linux/delay.h>

#define MCP3008_CS 8
#define SPI_BUS 0
#define SPI_SPEED 1000000
#define ADC_CHANNEL 0
#define LOG_FILE "soil_moisture.log"
#define DEFAULT_INTERVAL 1

#define MOISTURE_SCALE_FACTOR 1024.0 / 4095.0

void spi_init(void) {
    int fd = open(fmt("/dev/spidev0.0"), O_RDWR);
    if (fd < 0) {
        perror("open /dev/spidev0.0");
        exit(EXIT_FAILURE);
    }

    if (ioctl(fd, SPI_IOC_PLATFORM_SET_MAX_SPEED, SPI_SPEED) < 0) {
        perror("ioctl SPI_IOC_PLATFORM_SET_MAX_SPEED");
        close(fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(fd, SPI_IOC_MESSAGE_LEN, 16) < 0) {
        perror("ioctl SPI_IOC_MESSAGE_LEN");
        close(fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(fd, SPI_IOC_TRIS_MCP3008, 0x00) < 0) {
        perror("ioctl SPI_IOC_TRIS_MCP3008");
        close(fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(fd, SPI_IOC_MISO_TX, 0) < 0) {
        perror("ioctl SPI_IOC_MISO_TX");
        close(fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(fd, SPI_IOC_MOSI_RX, 1) < 0) {
        perror("ioctl SPI_IOC_MOSI_RX");
        close(fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(fd, SPI_IOC_CS_CHANGE, MCP3008_CS) < 0) {
        perror("ioctl SPI_IOC_CS_CHANGE");
        close(fd);
        exit(EXIT_FAILURE);
    }
}

int mcp3008_read(void) {
    int data;
    if (ioctl(fd, SPI_IOC_MESSAGE, (void *)"read", 8) < 0) {
        perror("ioctl SPI_IOC_MESSAGE");
        return -1;
    }

    data = readl(&spidev_rd);
    if (data == -1) {
        perror("read from SPI");
        return -1;
    }

    return data;
}

double read_analog(void) {
    int raw_value = mcp3008_read();
    if (raw_value == -1) {
        return -1.0;
    }

    return raw_value * MOISTURE_SCALE_FACTOR / 4095.0;
}

void log_moisture(double moisture) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[80];
    sprintf(timestamp, "%04d-%02d-%02d %02d:%02d:%02d",
            tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday,
            tm->tm_hour, tm->tm_min, tm->tm_sec);

    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen soil_moisture.log");
        return;
    }

    fprintf(fp, "%s, %f, %f\n", timestamp, moisture, read_analog());
    fclose(fp);
}

void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        log_moisture(read_analog());
        close(fd);
        fclose(fp);
        spi_cleanup();
        exit(0);
    }
}

int main(int argc, char *argv[]) {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    spi_init();

    int interval = DEFAULT_INTERVAL;
    if (argc > 1) {
        interval = atoi(argv[1]);
    }

    while (1) {
        double moisture = read_analog();
        if (moisture == -1.0) {
            fprintf(stderr, "Sensor error, exiting.\n");
            break;
        }

        log_moisture(moisture);
        usleep(interval * 1000000);
    }

    spi_cleanup();
    return 0;
}

