#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define SPI_BUS 0
#define MCP3008_CE GPIO8
#define MCP3008_MISO GPIO9
#define MCP3008_MOSI GPIO10
#define MCP3008_SCLK GPIO11
#define MLX90823_ADDR 0x5A
#define MLX90823_DATA_OUT 0

// Function to handle SPI communication
int mcp3008_read_adc(int channel) {
    int spi_fd, ret;
    struct spi_device *dev;

    spi_fd = spi_open(SPI_BUS, "mcp3008");
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    dev = spi_lookup_by_address(spi_fd, MLX90823_ADDR);
    if (!dev) {
        spi_close(spi_fd);
        perror("Failed to find MCP3008 device");
        return -1;
    }

    ret = spi_xfer(dev, &channel, 0, 0, 0);
    if (ret < 0) {
        perror("Failed to perform SPI transfer");
        spi_close(spi_fd);
        return -1;
    }

    return spi_xfer(dev, NULL, 0, 0, 0);
}

// Function to read pressure from MLX90823
int read_pressure(int channel) {
    int adc_value;
    int pressure;

    adc_value = mcp3008_read_adc(channel);
    if (adc_value == -1) {
        return -1;
    }

    // Convert ADC value to pressure (assuming 10-bit resolution)
    pressure = (adc_value * 5.0) / 1024.0;

    // Check for out-of-range values
    if (pressure < 0 || pressure > 1000) {
        printf("Out-of-range pressure value: %f\n", pressure);
        return -1;
    }

    return pressure;
}

// Signal handler for SIGINT (Ctrl+C)
void sigint_handler(int sig) {
    printf("Exiting gracefully...\n");
    exit(0);
}

// Signal handler for SIGTERM
void sigterm_handler(int sig) {
    printf("Exiting gracefully...\n");
    exit(0);
}

int main(int argc, char *argv[]) {
    int channel = 0;
    int ret;

    // Initialize gpiod
    if (gpiod_init() < 0) {
        perror("Failed to initialize gpiod");
        return EXIT_FAILURE;
    }

    // Set up signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Open SPI bus
    ret = gpiod_gpio_export(MLX90823_CE, 1);
    if (ret < 0) {
        perror("Failed to export GPIO8 as CE");
        return EXIT_FAILURE;
    }

    // Read pressure periodically
    while (1) {
        ret = read_pressure(channel);
        if (ret == -1) {
            continue;
        }

        // Get current timestamp
        time_t now = time(NULL);
        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", localtime(&now));

        // Print pressure and timestamp
        printf("Pressure: %.2f, Timestamp: %s\n", ret, timestamp);

        // Wait for 1 second
        usleep(1000000);
    }

    // Clean up resources
    gpiod_gpio_delexport(MLX90823_CE);
    return EXIT_SUCCESS;
}

