    uint8_t buffer[2];
    return spi_transfer(fd, &channel, 1, buffer, 1, ADC_READ_TIMEOUT);
}

int mcp3008_read_value(int fd, int channel) {
    uint16_t value;
    return spi_transfer(fd, &value, 2, NULL, 0, ADC_READ_TIMEOUT);
}

void handle_error(const char *msg) {
    fprintf(stderr, "Error: %s\n", msg);
    exit(EXIT_FAILURE);
}

void signal_handler(int signum) {
    printf("Received signal %d, shutting down...\n", signum);
    spi_close(spidev_fd);
    exit(signum == SIGINT || signum == SIGTERM ? EXIT_SUCCESS : EXIT_FAILURE);
}

int main(int argc, char *argv[]) {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int spidev_fd, ret;
    struct spidev_dev *dev;

    spidev_fd = spidev_open(0, 0);
    if (spidev_fd < 0) {
        handle_error("Failed to open SPI device");
    }

    dev = spidev_alloc_device(spidev_fd);
    if (!dev) {
        spi_close(spidev_fd);
        handle_error("Failed to allocate SPI device");
    }

    spidev_cfg.direction = SPI_DIRECTION_GPIO;
    spidev_cfg.speed_hz = 1000000;
    spidev_cfg.chipselect = dev->chipselect;
    spidev_cfg.mode = SPI_MODE0;

    spi_init(spidev_fd);

    ret = spi_open(spidev_fd);
    if (ret < 0) {
        handle_error("Failed to open SPI device");
    }

    while (1) {
        uint16_t value = 0;
        int ret_value = mcp3008_read_value(ret, ADC_CHANNEL);
        if (ret_value < 0) {
            handle_error("SPI transfer failed");
        }
        value = ret_value;

        if (value == 0 || value == 0x1023) {
            printf("Sensor detected as absent or faulty, reading stopped.\n");
            break;
        }

        uint8_t cs;
        mcp3008_cs(ret, CS);
        mcp3008_read_channel(ret, ADC_CHANNEL);
        mcp3008_cs(ret, cs);

        uint16_t adc_value = mcp3008_read_value(ret, ADC_CHANNEL);
        uint8_t timestamp[32];
        sprintf(timestamp, "%lu", (uint64_t)time(NULL));

        printf("Soil Moisture: %d\n", adc_value);
        printf("Timestamp: %s\n", timestamp);
        fflush(stdout);

        usleep(SAMPLE_INTERVAL * 1000000 / HRTIME_PER_SEC);
    }

    spi_close(ret);
    spi_free_device(dev);
    return 0;
