#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <sys/ioctl.h>
#include <spidev.h>

#define MCP3008_ADDRESS 0x29
#define SPI_DEV "/dev/spidev0.0"
#define SPI_MODE 0
#define SPI_BITS 8
#define SPI_SPEED 1000000

#define READ_COMMAND 0x80
#define CONFIG_REG 0x40
#define DATA_REG 0x42

// Function to read 3-byte single-ended value from MCP3008
uint16_t read_mcp3008(int fd) {
    uint8_t command[3];
    command[0] = READ_COMMAND;
    command[1] = CONFIG_REG;
    command[2] = 0x00; // Don't care byte

    uint16_t data;
    ssize_t ret = spidev_write_cd(fd, command, 3);
    if (ret != 3) {
        perror("spidev_write_cd failed");
        return 0;
    }

    ret = spidev_read_piod(fd, (uint32_t)MCP3008_ADDRESS, (uint32_t)&data, 2);
    if (ret != 2) {
        perror("spidev_read_piod failed");
        return 0;
    }

    return data;
}

// Function to convert raw ADC value to moisture percentage
float adc_to_moisture(uint16_t adc_value) {
    // MCP3008 datasheet: ADC resolution = 10 bits, full scale = 1024
    // Moisture percentage = (ADC value / 1024.0) * 100
    return (float)adc_value / 1024.0 * 100.0;
}

int main() {
    int fd, ret;
    fd = open(SPI_DEV, O_RDWR);
    if (fd == -1) {
        perror("open failed");
        exit(EXIT_FAILURE);
    }

    ret = ioctl(fd, SPI_IOC_MESSAGE(1), &struct spi_ioc_transfer{
        .len = sizeof(uint16_t),
        .data = (void*)read_mcp3008
    });
    if (ret < 0) {
        perror("ioctl failed");
        close(fd);
        exit(EXIT_FAILURE);
    }

    while (1) {
        uint16_t adc_value = read_mcp3008(fd);
        float moisture_percentage = adc_to_moisture(adc_value);

        printf("Moisture Percentage: %.2f%%\n", moisture_percentage);
        usleep(5000000); // 5 seconds delay
    }

    close(fd);
    return 0;
}

