#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <linux/spi/spidev-dev.h>

#define SPI_DEVICE 0
#define SPI_SPEED 1000000
#define GPIO_PIN 8

#define BUFFER_SIZE 4

int spi_fd;
struct spidev_ioctl_data spi_data;

void log_to_file(const char *timestamp, float voltage) {
    FILE *file = fopen("environmental_data.csv", "a");
    if (!file) {
        perror("Failed to open file for appending");
        return;
    }
    fprintf(file, "%s,%.3f\n", timestamp, voltage);
    fclose(file);
}

void init_spi() {
    spi_fd = spidev_open(SPI_DEVICE, 0);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    spi_data.direction = SPI_MSI_DIR_OUTPUT | SPI_MSI_DIR_INPUT;
    spi_data.length = 2;
    spi_data.data = (uint8_t *)"00000000"; // Chip select low

    if (spidev_ioctl(spi_fd, SPI_IOC_MESSAGE, &spi_data) < 0) {
        perror("Failed to set up SPI communication");
        exit(EXIT_FAILURE);
    }
}

void close_spi() {
    if (spi_fd >= 0) {
        spidev_close(spi_fd);
        spi_fd = -1;
    }
}

void read_analog_sensors() {
    uint8_t buffer[BUFFER_SIZE];
    int i;

    for (i = 0; i < BUFFER_SIZE; i++) {
        if (spidev_control(spi_fd, SPI_IOC_MESSAGE, &spi_data, 1) < 0) {
            perror("Failed to read from SPI device");
            return;
        }

        spi_data.data[i] = 0; // Clear the data buffer
    }

    // Read from MCP3008 channels 0-3
    spi_data.data[0] = 0x01; // Select channel 0
    spidev_control(spi_fd, SPI_IOC_MESSAGE, &spi_data, 1);
    if (spidev_control(spi_fd, SPI_IOC_MESSAGE, buffer, 1) < 0) {
        perror("Failed to read from channel 0");
        return;
    }

    spi_data.data[0] = 0x00; // Select channel 0
    spidev_control(spi_fd, SPI_IOC_MESSAGE, buffer, 1);
    if (spidev_control(spi_fd, SPI_IOC_MESSAGE, buffer, 1) < 0) {
        perror("Failed to read from channel 1");
        return;
    }

    spi_data.data[0] = 0x02; // Select channel 2
    spidev_control(spi_fd, SPI_IOC_MESSAGE, buffer, 1);
    if (spidev_control(spi_fd, SPI_IOC_MESSAGE, buffer, 1) < 0) {
        perror("Failed to read from channel 2");
        return;
    }

    spi_data.data[0] = 0x03; // Select channel 3
    spidev_control(spi_fd, SPI_IOC_MESSAGE, buffer, 1);
    if (spidev_control(spi_fd, SPI_IOC_MESSAGE, buffer, 1) < 0) {
        perror("Failed to read from channel 3");
        return;
    }

    // Convert SPI data to voltage (assuming 10-bit resolution)
    float voltage_0 = (buffer[0] << 8) / 1024.0;
    float voltage_1 = (buffer[1] << 8) / 1024.0;
    float voltage_2 = (buffer[2] << 8) / 1024.0;
    float voltage_3 = (buffer[3] << 8) / 1024.0;

    // Log the voltage readings
    char timestamp[20];
    time_t now = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    log_to_file(timestamp, voltage_0);
    log_to_file(timestamp, voltage_1);
    log_to_file(timestamp, voltage_2);
    log_to_file(timestamp, voltage_3);
}

int main(int argc, char *argv[]) {
    init_spi();

    while (1) {
        read_analog_sensors();
        usleep(1000000); // Wait for 1 second
    }

    close_spi();
    return 0;
}

