#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <linux/timer.h>
#include <sys/epoll.h>
#include <sys/select.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <signal.h>
#include <pthread.h>

#define BUFFER_SIZE 20
#define LOW_THRESHOLD 300
#define HIGH_THRESHOLD 600
#define PUMP_GPIO 17
#define SPI_DEVICE 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SAMPLE_INTERVAL 5

typedef struct {
    struct timespec arrival;
    int value;
    char timestamp[20];
} LogEntry;

static LogEntry log_buffer[BUFFER_SIZE];
static int log_head = 0;
static int log_tail = 0;

static int pump_state = 0;

void spi_init() {
    int file = open("/dev/spidev0.0", O_RDWR);
    if (file < 0) {
        perror("open /dev/spidev0.0");
        exit(EXIT_FAILURE);
    }

    if (ioctl(file, SPI_SET_MODE, SPI_MODE) < 0) {
        perror("set SPI mode");
        exit(EXIT_FAILURE);
    }

    if (ioctl(file, SPI_SET_CLOCKS(SPI_CLOCK_1MHZ), SPI_SPEED) < 0) {
        perror("set SPI clocks");
        exit(EXIT_FAILURE);
    }

    if (ioctl(file, SPI_ENABLE) < 0) {
        perror("enable SPI");
        exit(EXIT_FAILURE);
    }
}

void spi_close() {
    close(open("/dev/spidev0.0", O_WRONLY).fd);
}

void mcp3008_read(int channel) {
    uint32_t cmd = (channel << 16) | SPI_READ_REG | SPI_READ_DATA;
    write(fileno(spidev), &cmd, sizeof(cmd));

    uint32_t data;
    read(fileno(spidev), &data, sizeof(data));

    log_buffer[log_tail].value = data;
    strncpy(log_buffer[log_tail].timestamp, __datetime__, 19);
    log_tail = (log_tail + 1) % BUFFER_SIZE;
}

void pump_control(int state) {
    pump_state = state;
}

void *sample_thread(void *arg) {
    while (1) {
        mcp3008_read(0); // Read from channel 0
        usleep(SAMPLE_INTERVAL * 1000000); // Wait for 5 seconds

        if (log_head == log_tail) {
            log_tail = (log_tail + 1) % BUFFER_SIZE;
        }

        // Print log entries
        for (int i = log_head; i != log_tail; i = (i + 1) % BUFFER_SIZE) {
            printf("Moisture: %d, Timestamp: %s\n", log_buffer[i].value, log_buffer[i].timestamp);
        }

        // Check pump state
        if (log_buffer[log_head - 1].value < LOW_THRESHOLD) {
            pump_control(1); // Turn on pump
        } else if (log_buffer[log_head - 1].value > HIGH_THRESHOLD) {
            pump_control(0); // Turn off pump
        }

        // Sleep for a short time to avoid busy-waiting
        usleep(100000);
    }
}

int main() {
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    spi_init();

    pthread_t sample_thread_id;
    if (pthread_create(&sample_thread_id, NULL, sample_thread, NULL) != 0) {
        perror("pthread_create");
        spi_close();
        exit(EXIT_FAILURE);
    }

    while (1) {
        select(log_tail - log_head + 1, NULL, NULL, NULL, NULL);
        if (pump_state == 1) {
            pump_control(0); // Turn off pump
        }
    }

    pthread_join(sample_thread_id, NULL);
    spi_close();

    return 0;
}

void sigint_handler(int signum) {
    pump_control(0); // Turn off pump
    printf("Received SIGINT, stopping...\n");
    exit(0);
}

void sigterm_handler(int signum) {
    pump_control(0); // Turn off pump
    printf("Received SIGTERM, stopping...\n");
    exit(0);
}

