#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS 1
#define MAX30102_ADDRESS 0x12
#define LOG_FILE "health_log.txt"

void log_entry(const char *timestamp, int spO2, int hr) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file.\n");
        return;
    }
    time_t now = time(NULL);
    struct tm *timeinfo = localtime(&now);
    fprintf(log_file, "%s,%d,%d\n", ctime(timeinfo), spO2, hr);
    fclose(log_file);
}

int main(int argc, char *argv[]) {
    int i2c_fd, max30102_fd;
    struct i2c_client *client;
    int max30102_part_id;
    int spO2, hr;

    if (argc != 2) {
        fprintf(stderr, "Usage: %s <command> [options]\n", argv[0]);
        return 1;
    }

    if (strcmp(argv[1], "start") == 0) {
        i2c_fd = open("/dev/i2c-1", O_RDWR);
        if (i2c_fd < 0) {
            perror("Failed to open i2c bus");
            return 1;
        }

        client = i2c_client_new(i2c_fd, MAX30102_ADDRESS);
        if (!client) {
            perror("Failed to create i2c client");
            return 1;
        }

        max30102_part_id = read(client->handle, &max30102_part_id, 1);
        if (max30102_part_id != 1 || max30102_part_id != 0x12) {
            fprintf(stderr, "MAX30102 sensor not found, aborting.\n");
            close(i2c_fd);
            i2c_client_free(client);
            return 1;
        }

        pigpio_init(1); // Initialize pigpio for PWM control (optional for this task)

        while (1) {
            spO2 = read_spO2();
            hr = read_heart_rate();

            if (spO2 < 95 || hr > 100) {
                log_entry(ctime(NULL), spO2, hr);
            }

            usleep(1000000); // Sleep for 1 second
        }
    } else if (strcmp(argv[1], "stop") == 0) {
        pigpio_terminate(NULL); // Terminate pigpio
        close(i2c_fd);
        i2c_client_free(client);
        return 0;
    } else {
        fprintf(stderr, "Invalid command: %s\n", argv[1]);
        return 1;
    }
}

int read_spO2() {
    int data;
    write(client->handle, &data, 1);
    return data;
}

int read_heart_rate() {
    int data;
    write(client->handle, &data, 1);
    return data;
}

int main(int argc, char *argv[]) {
    // The main function remains the same as above.
}

