#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <errno.h>
#include <pthread.h>

#define ADC_ADDRESS 0x48
#define RELAY_GPIO 17
#define REED_GPIO 27
#define THRESHOLD 100
#define CALIBRATION_SAMPLES 10
#define SAMPLE_INTERVAL 200
#define CALIBRATION_INTERVAL 50
#define LOG_FILE "/var/log/door_events.log"

typedef struct {
    int fd;
    int adc_address;
    int reed_pin;
} i2c_context;

void calibrate_adc(i2c_context *ctx) {
    // Calibration logic here
    // For simplicity, we assume calibration is done by reading 10 samples
    for (int i = 0; i < CALIBRATION_SAMPLES; i++) {
        // Read ADC value
        int adc_value;
        if (ioctl(ctx->fd, I2C_RDWR, (unsigned long)ADC_ADDRESS, &adc_value) < 0) {
            perror("I2C read failed");
            return;
        }
        // Store calibration data
        // ...
    }
}

void energize_relay(i2c_context *ctx) {
    // Energize relay logic here
    // Assuming GPIO 17 is set high for 3 seconds
    printf("Energizing relay...\n");
    // Use a timer or delay function to hold HIGH for 3 seconds
    // ...
}

void deenergize_relay(i2c_context *ctx) {
    // De-energize relay logic here
    // Assuming GPIO 17 is set low
    printf("De-energizing relay...\n");
    // Use a timer or delay function to hold LOW for 3 seconds
    // ...
}

void log_event(i2c_context *ctx, int reed_state) {
    // Log event with timestamp
    char timestamp[20];
    time_t now = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file) {
        fprintf(log_file, "%s: door opened\n", timestamp);
        fclose(log_file);
    } else {
        perror("Failed to open log file");
    }
}

void *monitor_loop(void *arg) {
    i2c_context *ctx = (i2c_context *)arg;
    while (1) {
        int adc_value;
        if (ioctl(ctx->fd, I2C_RDWR, (unsigned long)ctx->adc_address, &adc_value) < 0) {
            perror("I2C read failed");
            continue;
        }

        // Check if calibration is complete
        if (adc_value < 100) {
            calibrate_adc(ctx);
        }

        // Check if calibration is complete
        if (adc_value < 100) {
            energize_relay(ctx);
            usleep(SAMPLE_INTERVAL * 1000 * 1000); // Sleep for 200ms
            deenergize_relay(ctx);
            usleep(SAMPLE_INTERVAL * 1000 * 1000); // Sleep for 200ms
            log_event(ctx, digitalRead(REED_GPIO) == 0); // Read reed sensor
        }
    }
    return NULL;
}

int main() {
    int relay_fd, reed_fd;
    i2c_context ctx;
    ctx.fd = -1;
    ctx.adc_address = ADC_ADDRESS;
    ctx.reed_pin = REED_GPIO;

    relay_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (relay_fd == -1) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    ctx.fd = open("/dev/i2c-1", O_RDWR | O_SYNC);
    if (ctx.fd == -1) {
        perror("Failed to open I2C bus");
        close(relay_fd);
        exit(EXIT_FAILURE);
    }

    pthread_t thread;
    if (pthread_create(&thread, NULL, (void *(*)(void *))monitor_loop, &ctx) != 0) {
        perror("Failed to create thread");
        close(ctx.fd);
        close(relay_fd);
        exit(EXIT_FAILURE);
    }

    // Wait for SIGINT or SIGTERM
    int sigint_handled = 0;
    int sigterm_handled = 0;
    while (!sigint_handled && !sigterm_handled) {
        if (kill(getpid(), SIGINT) == 0 || kill(getpid(), SIGTERM) == 0) {
            sigint_handled = 1;
            sigterm_handled = 1;
        }
        usleep(100000); // Check every second
    }

    pthread_join(thread, NULL);
    close(ctx.fd);
    close(relay_fd);

    // Ensure relay is de-energized
    deenergize_relay(&ctx);

    // Clean up
    if (fclose(relay_fd)) {
        perror("Failed to close log file");
    }
    if (close(ctx.fd)) {
        perror("Failed to close I2C bus");
    }

    return 0;
}

