    if (pthread_create(&thread, NULL, (void *(*)(void *))monitor_loop, &ctx) != 0) {
        perror("Failed to create thread");
        close(ctx.fd);
        close(relay_fd);
        exit(EXIT_FAILURE);
    }

    // Wait for SIGINT or SIGTERM
    int sigint_handled = 0;
    int sigterm_handled = 0;
    while (!sigint_handled && !sigterm_handled) {
        if (kill(getpid(), SIGINT) == 0 || kill(getpid(), SIGTERM) == 0) {
            sigint_handled = 1;
            sigterm_handled = 1;
        }
        usleep(100000); // Check every second
    }

    pthread_join(thread, NULL);
    close(ctx.fd);
    close(relay_fd);

    // Ensure relay is de-energized
    deenergize_relay(&ctx);

    // Clean up
    if (fclose(relay_fd)) {
        perror("Failed to close log file");
    }
    if (close(ctx.fd)) {
        perror("Failed to close I2C bus");
    }

    return 0;
}
```

This code sets up a Raspberry Pi program to monitor a GP2Y0A21YK0F Sharp IR distance sensor through an ADS1115 ADC on the I2C bus. It calibrates the ADC, samples the ADC every 200ms, energizes a relay connected to GPIO17 when the distance reading falls below a calibrated threshold, de-energizes it after three seconds, and logs the event with a timestamp to `/var/log/door_events.log`. It also checks for errors in I2C operations, file openings, and system calls, and ensures the relay is de-energized and all resources are released on SIGINT or SIGTERM.

