#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <linux/i2c-dev.h>
#include <linux/delay.h>

#define MCP3008_SPI_DEVICE 0
#define MCP3008_SPI_SPEED 1000000
#define MCP3008_SPI_MODE 0
#define RELAY_PIN 17
#define PUMP_DURATION_DEFAULT 10
#define SLEEP_INTERVAL_DEFAULT 60
#define THRESHOLD_DEFAULT 0.3

#define LOG_FILE "irrigation.log"

#define MAX_RETRIES 3

void spi_init() {
    int file = open( "/dev/spidev0.0", O_RDWR );
    if ( file == -1 ) {
        perror( "open /dev/spidev0.0" );
        exit( EXIT_FAILURE );
    }

    struct spi_ioc_reg spi_regs[4] = {
        .read = (uint32_t)0x20,
        .write = (uint32_t)0x24,
        .control = (uint32_t)(SPID_MODE0 | SPID_CPOL_LOW | SPID_CPHA_2EDGE),
        .le_to_mr = 0
    };

    if ( ioctl( file, SPI_IOC_REGSET, spi_regs ) < 0 ) {
        perror( "ioctl SPI_IOC_REGSET" );
        close( file );
        exit( EXIT_FAILURE );
    }

    close( file );
}

int mcp3008_read(int channel) {
    int file = open( "/dev/spidev0.0", O_RDWR );
    if ( file == -1 ) {
        perror( "open /dev/spidev0.0" );
        return -1;
    }

    uint8_t cmd[2] = { channel | 0x01, 0x00 };
    write( file, cmd, 2 );

    uint8_t status;
    read( file, &status, 1 );

    if ( status & 0x02 ) {
        // Read data
        uint16_t data;
        read( file, &data, 2 );
        return data;
    } else {
        close( file );
        return -1;
    }
}

void mcp3008_write(int channel, uint16_t value) {
    int file = open( "/dev/spidev0.0", O_RDWR );
    if ( file == -1 ) {
        perror( "open /dev/spidev0.0" );
        return;
    }

    uint8_t cmd[2] = { channel | 0x01, 0x00 };
    write( file, cmd, 2 );

    uint8_t status;
    write( file, &value, 2 );

    if ( status & 0x02 ) {
        close( file );
    }
}

void log_moisture_reading(uint16_t reading) {
    time_t now = time( NULL );
    char timestamp[80];
    strftime( timestamp, sizeof( timestamp ), "%Y-%m-%d %H:%M:%S", localtime( &now ) );
    FILE *file = fopen( LOG_FILE, "a" );
    if ( file == NULL ) {
        perror( "fopen log_moisture_reading" );
        return;
    }
    fprintf( file, "%s: Moisture reading: %d\n", timestamp, reading );
    fclose( file );
}

void activate_pump(int duration) {
    printf("Activating pump for %d seconds...\n", duration);
    // Here you would implement the logic to turn on the relay for the specified duration.
    // This is a placeholder for the actual GPIO control.
}

void deactivate_pump() {
    printf("Deactivating pump...\n");
    // Here you would implement the logic to turn off the relay.
    // This is a placeholder for the actual GPIO control.
}

void signal_handler(int signum) {
    printf("Received signal, turning off pump...\n");
    deactivate_pump();
    exit( EXIT_SUCCESS );
}

int main(int argc, char *argv[]) {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int threshold = 0;
    int pump_duration = PUMP_DURATION_DEFAULT;
    int sleep_interval = SLEEP_INTERVAL_DEFAULT;

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-t") == 0) {
            threshold = atoi(argv[i + 1]);
        } else if (strcmp(argv[i], "-d") == 0) {
            pump_duration = atoi(argv[i + 1]);
        } else if (strcmp(argv[i], "-s") == 0) {
            sleep_interval = atoi(argv[i + 1]);
        }
    }

    spi_init();

    uint16_t reading;
    while (1) {
        reading = mcp3008_read(0);
        if (reading == -1) {
            fprintf(stderr, "Failed to read from MCP3008, retrying...\n");
            if (--max_retries >= 0) {
                continue;
            } else {
                fprintf(stderr, "Failed to read from MCP3008 after retries, skipping cycle.\n");
                break;
            }
        }

        double moisture_level = (double)reading / 3300.0;
        if (moisture_level < threshold) {
            activate_pump(pump_duration);
            usleep(sleep_interval * 1000000);
            deactivate_pump();
        }

        log_moisture_reading(reading);
        usleep(sleep_interval * 1000000);
    }

    return 0;
}

