#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <libgpiod.h>

#define I2C_BUS 1
#define PCF8591_ADDRESS 0x40
#define SAMPLE_INTERVAL_MS 100

int i2c_fd;

void sigint_handler(int signum) {
    close(i2c_fd);
    exit(1);
}

int main() {
    int ret;

    // Initialize gpiod
    if (lgpiod_init() < 0) {
        perror("Failed to initialize gpiod");
        exit(1);
    }

    // Register SIGINT handler
    signal(SIGINT, sigint_handler);

    // Open I2C bus
    i2c_fd = open("/dev/i2c-1", O_RDWR | O_NOCTTY);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(1);
    }

    // Set I2C bus parameters
    if (ioctl(i2c_fd, I2C_SLAVE, PCF8591_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        exit(1);
    }

    // Read dummy value first
    uint8_t dummy_read;
    ret = read(i2c_fd, &dummy_read, 1);
    if (ret != 1 || dummy_read != 0) {
        perror("Failed to read dummy value");
        exit(1);
    }

    // Main loop
    while (1) {
        // Read current sample
        uint8_t sample;
        ret = read(i2c_fd, &sample, 1);
        if (ret != 1 || sample == 0) {
            perror("Failed to read sample");
            continue;
        }

        // Print the sample value
        printf("Sample: %d\n", sample);

        // Wait for the specified interval
        usleep(SAMPLE_INTERVAL_MS * 1000 / HRTIME_PER_SEC);
    }

    // Close I2C bus
    close(i2c_fd);

    // Terminate
    return 0;
}

