#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>
#include <syslog.h>

#define BUF_SIZE 100
#define SAMPLE_RATE 1
#define GPIO27 27
#define ADC_ADDRESS 0x48
#define AIN0_CHANNEL 0

#define LOG_FACILITY "myapp"
#define LOG_PRIORITY syslog(LOG_LEVEL_ERR)

#define MAX_LOG_MSG 1024

#define I2C_DEVICE "/dev/i2c-1"

int i2c_fd;
piGPIO_handle handle;
int buffer[BUF_SIZE];
int head = 0;
int tail = 0;
int count = 0;
int threshold = 500;

void log_error(const char *msg) {
    char buffer[MAX_LOG_MSG];
    snprintf(buffer, MAX_LOG_MSG, "[ERROR] %s", msg);
    syslog(LOG_ERR, buffer);
}

void log_warning(const char *msg) {
    char buffer[MAX_LOG_MSG];
    snprintf(buffer, MAX_LOG_MSG, "[WARNING] %s", msg);
    syslog(LOG_WARNING, buffer);
}

void log_info(const char *msg) {
    char buffer[MAX_LOG_MSG];
    snprintf(buffer, MAX_LOG_MSG, "[INFO] %s", msg);
    syslog(LOG_INFO, buffer);
}

int main(int argc, char *argv[]) {
    if (argc != 1) {
        log_error("Usage: %s <threshold_gauss>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    threshold = atoi(argv[1]);

    if (open(I2C_DEVICE, O_RDWR) == -1) {
        log_error("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADC_ADDRESS) == -1) {
        log_error("Failed to set I2C slave address");
        exit(EXIT_FAILURE);
    }

    if (piGPIO_init() == -1) {
        log_error("Failed to initialize pigpio");
        exit(EXIT_FAILURE);
    }

    log_info("Starting sensor monitoring...");

    while (1) {
        int adc_value;
        int voltage;

        if (piGPIO_output(GPIO27, 1) == -1) {
            log_error("Failed to set GPIO27 to HIGH");
            continue;
        }

        if (piADC_read(i2c_fd, AIN0_CHANNEL) == -1) {
            log_warning("ADC read failed, skipping this sample");
            continue;
        }

        voltage = piADC_get_raw(i2c_fd, AIN0_CHANNEL);

        if (voltage < 0 || voltage > 3.3) {
            log_warning("ADC voltage out of range, skipping this sample");
            continue;
        }

        int magnetic_field = (voltage / 3.3) * threshold;

        if (magnetic_field > threshold) {
            log_info("Threshold exceeded, driving GPIO27 HIGH");
            piGPIO_output(GPIO27, 1);
        }

        buffer[tail] = magnetic_field;
        tail = (tail + 1) % BUF_SIZE;
        count++;

        if (count > BUF_SIZE) {
            buffer[head] = buffer[tail];
            head = (head + 1) % BUF_SIZE;
            count--;
        }

        log_info("Rolling average: %d", buffer[head]);

        usleep(SAMPLE_RATE * 1000000 / 1000); // Convert to microseconds
    }

    piGPIO_output(GPIO27, 0);
    piGPIO_cleanup();
    close(i2c_fd);
    syslog(LOG_CLOSING, "Exiting...");

    return 0;
}

