#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/statfs.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <errno.h>
#include <signal.h>

#define SPI_DEVICE 0
#define SPI_SPEED 1000000
#define MCP3008_CHANNEL 0
#define PWM_PIN 18
#define ADC_PIN 8
#define PWM_FREQ 1000
#define PWM_DUTY_CYCLE_MAX 1023

#define BUFFER_SIZE 1

void spi_init(int fd) {
    struct spi_fd_info info;
    int ret;

    ret = spi_init(fd, SPI_SPEED, SPI_DEVICE, 0, &info);
    if (ret < 0) {
        perror("spi_init");
        exit(EXIT_FAILURE);
    }
}

int spi_transfer(int fd, const void *send, size_t len) {
    struct spi_ioc_transfer req;
    int ret;

    req.transfer_type = SPI_MCI_SEND;
    req.addr = 0;
    req.len = len;
    req.data = send;

    ret = spi_transfer(fd, &req, 1);
    if (ret < 0) {
        perror("spi_transfer");
        exit(EXIT_FAILURE);
    }

    return ret;
}

int read_adc(int fd, uint16_t *adc_value) {
    uint8_t buffer[BUFFER_SIZE];
    int ret;

    ret = spi_transfer(fd, buffer, sizeof(buffer));
    if (ret != BUFFER_SIZE) {
        perror("read_adc");
        return ret;
    }

    *adc_value = ((uint16_t)buffer[0] << 8) | buffer[1];
    return BUFFER_SIZE;
}

void set_pwm(int fd, uint16_t duty_cycle) {
    struct spi_ioc_wr_reg req;
    int ret;

    req.reg = SPI_MCR;
    req.wdata = duty_cycle;

    ret = spi_transfer(fd, &req, 1);
    if (ret != 1) {
        perror("set_pwm");
    }
}

void handle_interrupts(int sig) {
    set_pwm(fd, 0); // Stop PWM output
    spi_transfer(fd, NULL, 0); // Clear SPI transfer queue
    exit(0);
}

int main(int argc, char *argv[]) {
    int fd, ret;
    struct stat sb;

    fd = open("/dev/spidev0.0", O_RDWR);
    if (fd < 0) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    ret = spi_init(fd);
    if (ret < 0) {
        perror("spi_init");
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, handle_interrupts);
    signal(SIGTERM, handle_interrupts);

    while (1) {
        uint16_t adc_value;
        int ret = read_adc(fd, &adc_value);
        if (ret != BUFFER_SIZE) {
            perror("read_adc");
            continue;
        }

        uint16_t pwm_duty_cycle = adc_value / 4095 * PWM_DUTY_CYCLE_MAX;
        set_pwm(fd, pwm_duty_cycle);

        printf("ADC: %d, PWM: %d\n", adc_value, pwm_duty_cycle);
        usleep(100000); // Sleep for 100ms
    }

    spi_transfer(fd, NULL, 0); // Clear SPI transfer queue
    return 0;
}

