#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADC_CHANNEL 0
#define PGA_GAIN 4.096
#define LED_PIN 17
#define BLINK_DURATION 1000000UL // 1 second in microseconds
#define THRESHOLD 100.0

int adc_read(int i2c_fd, int channel) {
    struct i2c_rdwr_cmd cmd = {
        .addr = ADS1115_ADDR,
        .flags = I2C_M_READ,
        .len = 2,
        .data = (uint8_t *)"0x00", // Start register
        .data2 = (uint8_t *)"0x00", // Read data
    };

    int ret = ioctl(i2c_fd, I2C_RDWR, &cmd);
    if (ret < 0) {
        perror("I2C read failed");
        return -1;
    }

    return cmd.data[1];
}

int main(int argc, char *argv[]) {
    int i2c_fd, led_fd;
    float magnetic_field;
    int threshold;

    if (argc < 2) {
        printf("Usage: %s -t <threshold> [options]\n", argv[0]);
        return EXIT_FAILURE;
    }

    threshold = atoi(argv[1]);

    if (pigpioSetup() < 0) {
        perror("pigpioSetup failed");
        return EXIT_FAILURE;
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR | O_NOCTTY);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        pigpioExit();
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        pigpioExit();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        perror("pigpioInitialise failed");
        close(i2c_fd);
        pigpioExit();
        return EXIT_FAILURE;
    }

    gpioSetMode(LED_PIN, PI_OUTPUT);

    while (1) {
        magnetic_field = adc_read(i2c_fd, ADC_CHANNEL);
        if (magnetic_field == -1) {
            perror("ADC read failed");
            break;
        }

        magnetic_field *= PGA_GAIN / 1024.0; // Convert to Gauss

        if (magnetic_field > threshold) {
            gpioWrite(LED_PIN, GPIO_OUTPUT);
            while (magnetic_field > threshold) {
                gpioWrite(LED_PIN, GPIO_ON);
                usleep(50000); // 50 ms
                gpioWrite(LED_PIN, GPIO_OFF);
                usleep(50000); // 50 ms
            }
        }

        printf("Magnetic field strength: %.2f Gauss\n", magnetic_field);
        usleep(100000); // 100 ms delay
    }

    gpioFinalise();
    close(i2c_fd);
    pigpioExit();

    return EXIT_SUCCESS;
}

