#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define MCP3008_CS 8
#define MCP3008_CLK 11
#define MCP3008_DOUT 9

#define VREF 3.3
#define VDD 3.3

int main() {
    int fd;
    struct spidev_generic arg;
    uint8_t value;

    fd = open("/dev/spidev0.0", O_RDWR);
    if (fd < 0) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    arg.mode = SPI_MODE0;
    arg.bits_per_word = 10;
    arg.frequency = 1000000; // 1 MHz

    if (ioctl(fd, SPI_SET_MODE, &arg) < 0) {
        perror("ioctl(SPI_SET_MODE)");
        close(fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(fd, SPI_SET_BITS, 10) < 0) {
        perror("ioctl(SPI_SET_BITS)");
        close(fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(fd, SPI_SET_FREQ, 1000000) < 0) {
        perror("ioctl(SPI_SET_FREQ)");
        close(fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(fd, SPI_ACTIVE, 1) < 0) {
        perror("ioctl(SPI_ACTIVE)");
        close(fd);
        exit(EXIT_FAILURE);
    }

    while (1) {
        arg.count = 1;
        if (ioctl(fd, SPI_CMDS_SINGLE, &arg) < 0) {
            perror("ioctl(SPI_CMDS_SINGLE)");
            continue;
        }

        value = arg.result[0];

        // Convert raw value to voltage
        uint16_t raw_value = value;
        float voltage = (raw_value * VREF) / (1024.0 * 3.3);

        printf("Raw Value: 0x%02X, Voltage: %.2f V\n", value, voltage);

        usleep(500000); // Wait for 500ms
    }

    close(fd);
    return 0;
}

