#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <libgpiod/gpio.h>
#include <mcp3008.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define BUFFER_SIZE 3 * 4  // 3 channels * 10 bits each
#define CSV_FILE "sensor_data.csv"
#define UPDATE_INTERVAL 5  // seconds

void signal_handler(int signum) {
    printf("Received signal %d, shutting down...\n", signum);
    mcp3008_close(mcp3008_get_instance());
    close(open_flag);
    exit(0);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    open_flag = open(SPI_DEVICE, O_RDWR | O_NOCTTY | O_NDELAY);
    if (open_flag == -1) {
        perror("open_flag");
        exit(EXIT_FAILURE);
    }

    mcp3008_config(mcp3008_get_instance(), MCP3008_SPIE_ENABLE);
    if (mcp3008_init(mcp3008_get_instance()) != MCP3008_SUCCESS) {
        perror("mcp3008_init");
        close(open_flag);
        exit(EXIT_FAILURE);
    }

    FILE *csv_file = fopen(CSV_FILE, "a");
    if (!csv_file) {
        perror("fopen");
        close(open_flag);
        exit(EXIT_FAILURE);
    }

    while (1) {
        struct timespec write_ts;
        clock_gettime(CLOCK_REALTIME, &write_ts);

        int channel_data[3];
        for (int i = 0; i < 3; i++) {
            channel_data[i] = mcp3008_read_channel(mcp3008_get_instance(), i);
            if (channel_data[i] == MCP3008_ERROR) {
                fprintf(stderr, "Error reading channel %d\n", i);
                continue;
            }
        }

        double voltage_channels[3];
        for (int i = 0; i < 3; i++) {
            voltage_channels[i] = (double)(channel_data[i] * 3.3) / 1023.0;
        }

        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&write_ts.tv_sec));
        char line[100];
        sprintf(line, "%s,%.2f,%.2f,%.2f\n", timestamp, voltage_channels[0], voltage_channels[1], voltage_channels[2]);
        fwrite(line, strlen(line), sizeof(line), csv_file);

        usleep(UPDATE_INTERVAL * 1e6);
    }

    fclose(csv_file);
    mcp3008_close(mcp3008_get_instance());
    close(open_flag);

    return 0;
}

