#include <spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define ADC_CHANNEL 0
#define MOTOR_GPIO17 17
#define MOTOR_GPIO27 27
#define NOISE_THRESHOLD 500
#define SAMPLE_INTERVAL_MS 10
#define SAMPLE_RATE 100
#define VIBRATION_LOG "vibration_log.txt"

int spi_fd;
int adc_channel = ADC_CHANNEL;
int motor1_gpio = MOTOR_GPIO17;
int motor2_gpio = MOTOR_GPIO27;

void log_vibration_event(const char *timestamp) {
    FILE *file = fopen(VIBRATION_LOG, "a");
    if (!file) {
        fprintf(stderr, "Error opening vibration log file.\n");
        return;
    }
    fprintf(file, "%s\n", timestamp);
    fclose(file);
}

void setup_gpio() {
    if (gpio_init() < 0) {
        fprintf(stderr, "Failed to initialize GPIO.\n");
        exit(EXIT_FAILURE);
    }
    gpio_set_dir(motor1_gpio, GPIO_OUTPUT);
    gpio_set_dir(motor2_gpio, GPIO_OUTPUT);
}

void setup_spi() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device.\n");
        exit(EXIT_FAILURE);
    }
    if (spidev_init(spi_fd) < 0) {
        fprintf(stderr, "Failed to initialize SPI.\n");
        exit(EXIT_FAILURE);
    }
}

void read_adc() {
    uint16_t adc_value;
    if (spidev_xfer(&adc_channel, 0, 0, 0, 0) < 0) {
        fprintf(stderr, "Failed to read ADC value.\n");
        return;
    }
    adc_value = spidev_get_raw(spi_fd, adc_channel);
    // Convert raw ADC value to voltage (if needed)
    // ...
}

void modulate_motors(uint16_t adc_value) {
    if (adc_value > NOISE_THRESHOLD) {
        gpio_set_level(motor1_gpio, HIGH);
        gpio_set_level(motor2_gpio, HIGH);
    } else {
        gpio_set_level(motor1_gpio, LOW);
        gpio_set_level(motor2_gpio, LOW);
    }
}

int main(int argc, char *argv[]) {
    setup_gpio();
    setup_spi();

    while (1) {
        uint16_t adc_value;
        clock_gettime(CLOCK_MONOTONIC, &start_time);
        read_adc();
        clock_gettime(CLOCK_MONOTONIC, &end_time);
        uint64_t elapsed_ms = (end_time.tv_sec - start_time.tv_sec) * 1000000 + (end_time.tv_nsec - start_time.tv_nsec) / 1000;
        if (elapsed_ms >= SAMPLE_INTERVAL_MS) {
            modulate_motors(adc_value);
            log_vibration_event(get_timestamp());
        }
        usleep(SAMPLE_RATE * 1000 / SAMPLE_RATE);
    }

    gpio_cleanup();
    spidev_cleanup();
    close(spi_fd);
    return 0;
}

