#define SPI_BUS 0
#define SPI_DEVICE 0
#define SPI_PIN 0

#define MAX_FILE_SIZE 1000000 // 1 MB

int i2c_fd, spi_fd, csv_fd;
int max_readings = MAX_READINGS;

typedef struct {
    int light_lux;
    int sound_level_db;
    int error_code;
} sensor_data;

sensor_data read_sensor() {
    sensor_data data;
    int light_lux, sound_level_db, error_code;

    // Read light level from BH1750
    light_lux = read_bh1750_lux();
    if (light_lux == -1) {
        error_code = 1; // I2C communication error
    } else {
        error_code = 0;
    }

    // Read sound level from MAX9814 via MCP3008 ADC
    sound_level_db = read_max9814_db(spi_fd);
    if (sound_level_db == -1) {
        error_code = 2; // ADC read failure
    } else {
        error_code = 0;
    }

    data.light_lux = light_lux;
    data.sound_level_db = sound_level_db;
    data.error_code = error_code;

    return data;
}

int read_bh1750_lux() {
    int file;
    char buffer[2];

    file = open("/dev/i2c-1", O_RDWR);
    if (file == -1) {
        return -1; // I2C communication error
    }

    write(file, "A", 1);
    read(file, buffer, 1);
    close(file);

    if (buffer[0] != '1') {
        return -1; // Invalid response from BH1750
    }

    buffer[0] = '\0';
    return atoi(buffer);
}

int read_max9814_db(int spi_fd) {
    int chip_select = 0;
    int data_in, data_out;
    int result;

    // Set chip select for MAX9814
    write(spi_fd, &chip_select, 1);

    // Read analog input from MAX9814
    data_in = read(spi_fd, &data_out, 1);
    if (data_in == -1) {
        return -1; // ADC read failure
    }

    // Convert raw data to dB
    result = data_out * 100 / 1023;

    return result;
}

void log_reading(sensor_data data) {
    time_t now = time(NULL);
    char timestamp[32];
    sprintf(timestamp, "%ld", now);

    char line[1024];
    sprintf(line, "%s,%d,%d,%d\n", timestamp, data.sound_level_db, data.light_lux, data.error_code);

    csv_fd = fopen("tamper_log.csv", "a");
    if (csv_fd == NULL) {
        perror("Error opening tamper_log.csv");
        exit(EXIT_FAILURE);
    }

    fwrite(line, sizeof(char), strlen(line), csv_fd);
    fclose(csv_fd);
}

int main(int argc, char *argv[]) {
    int ret;
    int i;

    // Initialize pigpio for PWM control (if needed)
    if (pigpioSetup() == -1) {
        perror("Failed to initialize pigpio");
        exit(EXIT_FAILURE);
    }

    // Initialize SPI and I2C
    spi_fd = spidev_open(SPI_BUS, SPI_DEVICE);
    if (spi_fd == -1) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    i2c_fd = i2c_open(I2C_BUS, 0x18);
    if (i2c_fd == -1) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    // Open CSV file for writing
    csv_fd = fopen("tamper_log.csv", "w");
    if (csv_fd == NULL) {
        perror("Error opening tamper_log.csv");
        exit(EXIT_FAILURE);
    }

    // Log readings every 5 seconds
    for (i = 0; i < max_readings; i++) {
        sensor_data data = read_sensor();
        log_reading(data);

        usleep(LOG_INTERVAL * 1000 / 1000); // Sleep for 5 ms
    }

    // Clean up and exit
    pigpioTerminate();
    spidev_close(spi_fd);
    i2c_close(i2c_fd);
    fclose(csv_fd);

    return 0;
}

