#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

#define MCP3008_CS 0
#define MCP3008_SPI_CHANNEL 0
#define VH400_PIN 0
#define RELAY_PIN 17
#define SPI_FREQ_HZ 1000000
#define SPI_POLARITY_0
#define SPI_PHASE_0
#define SPI_BITS_PER_WORD 8
#define MOISTURE_THRESHOLD 30
#define LOG_INTERVAL_S 60

int mcp3008_fd;
int spi_fd;

void spi_init(void) {
    int file;
    struct spi_fd_info info;

    file = open("/dev/spidev0.0", O_RDWR);
    if (file == -1) {
        perror("open /dev/spidev0.0");
        exit(EXIT_FAILURE);
    }

    info.file = file;
    info.mode = SPI_MODE0;
    info.speed_hz = SPI_FREQ_HZ;
    info.polarity = SPI_POLARITY_0;
    info.phase = SPI_PHASE_0;
    info.bits_per_word = SPI_BITS_PER_WORD;

    if (ioctl(file, SPI_IOC_NRINGS, 1) == -1) {
        perror("ioctl SPI_IOC_NRINGS");
        close(file);
        exit(EXIT_FAILURE);
    }

    if (ioctl(file, SPI_IOC_ENTER, &info) == -1) {
        perror("ioctl SPI_IOC_ENTER");
        close(file);
        exit(EXIT_FAILURE);
    }
}

int mcp3008_read(int channel) {
    int buf[2];
    int ret;

    ret = read(mcp3008_fd, buf, 2);
    if (ret != 2) {
        perror("read from MCP3008");
        return -1;
    }

    return buf[0] << 8 | buf[1];
}

int gpio_init(void) {
    int gpio_fd;

    gpio_fd = open("/dev/gpioP1", O_RDWR);
    if (gpio_fd == -1) {
        perror("open /dev/gpioP1");
        exit(EXIT_FAILURE);
    }

    if (pigpio_init() == -1) {
        perror("pigpio_init");
        close(gpio_fd);
        exit(EXIT_FAILURE);
    }

    return gpio_fd;
}

void gpio_set_output(int pin) {
    pigpio_set_mode(gpio_fd, PI_OUTPUT);
    pigpio_write(gpio_fd, pin);
}

void gpio_set_input(int pin) {
    pigpio_set_mode(gpio_fd, PI_INPUT);
}

int gpio_read_input(int pin) {
    return pigpio_get_level(gpio_fd, pin);
}

void water_pump_on(void) {
    pigpio_write(gpio_fd, RELAY_PIN);
}

void water_pump_off(void) {
    pigpio_write(gpio_fd, 0);
}

void log_reading(const char *timestamp) {
    printf("%s: Moisture: %d\n", timestamp, mcp3008_read(VH400_PIN));
}

int main(void) {
    spi_init();
    int mcp3008_addr = 0x20;
    int mcp3008_reg_address = 0x40;
    int mcp3008_data;
    int moisture_reading = 0;
    int retry_count = 0;
    struct timespec start_time, end_time;
    double elapsed_time;

    gpio_fd = gpio_init();

    if (gpio_fd == -1) {
        printf("Failed to initialize GPIO.\n");
        return EXIT_FAILURE;
    }

    gpio_set_output(RELAY_PIN);

    while (1) {
        start_time = clock();
        moisture_reading = mcp3008_read(VH400_PIN);
        end_time = clock();
        elapsed_time = (end_time - start_time).tv_sec - (end_time.tv_nsec / 1e9);

        if (moisture_reading == -1) {
            retry_count++;
            if (retry_count > 3) {
                printf("Failed to read from MCP3008 after retries.\n");
                water_pump_off();
                break;
            }
            printf("Retrying MCP3008 read...\n");
            continue;
        }

        if (moisture_reading < (MOISTURE_THRESHOLD * 100 / 100)) {
            water_pump_on();
            printf("Water pump activated due to low moisture level.\n");
        }

        log_reading(clock_gettime(CLOCK_REALTIME, NULL).tv_sec);

        if (elapsed_time >= LOG_INTERVAL_S) {
            water_pump_off();
            printf("Water pump deactivated.\n");
        }

        usleep(100000); // Sleep for 100ms between readings
    }

    pigpio_cleanup(gpio_fd);
    close(spi_fd);
    close(mcp3008_fd);

    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

