int main(int argc, char *argv[]) {
    int logfd;
    struct itimerspec timers[2];
    timers[0].it_value.tv_sec = 0;
    timers[0].it_value.tv_nsec = LOG_INTERVAL * 1000000000;
    timers[1].it_value.tv_sec = -1;
    timers[1].it_value.tv_nsec = 0;

    if (signal(SIGINT, sigint_handler) == SIG_ERR) {
        perror("signal");
        exit(EXIT_FAILURE);
    }
    if (signal(SIGTERM, sigterm_handler) == SIG_ERR) {
        perror("signal");
        exit(EXIT_FAILURE);
    }

    if (spi_init() < 0) {
        perror("spi_init");
        exit(EXIT_FAILURE);
    }

    if (mcp3008_init(SPI_CHANNEL, CE_PIN) < 0) {
        perror("mcp3008_init");
        spi_close(spi_handle);
        exit(EXIT_FAILURE);
    }

