        struct timespec timeout;
        timeout.tv_sec = 0;
        timeout.tv_nsec = 1000000000;

        if (select(logfd + 1, NULL, NULL, NULL, &timeout, NULL) == -1) {
            perror("select");
            spi_close(spi_handle);
            close(logfd);
            exit(EXIT_FAILURE);
