        int adc_read[3] = {0};
        int success = 0;

        for (int i = 0; i < 3; i++) {
            if (mcp3008_read_channel(SPI_CHANNEL, ADC_CHANNEL, adc_read) < 0) {
                success = 1;
                break;
            }
        }

        if (!success) {
            write(logfd + 1, "Failed to read ADC values\n", 18);
            continue;
        }

        int average = (adc_read[0] + adc_read[1] + adc_read[2]) / 3;
        int duty_cycle = (int)((average / ADC_RESOLUTION) * 100);

        if (write(logfd + 1, "Raw ADC readings: ", 21) != 21) {
            perror("write");
            spi_close(spi_handle);
            close(logfd);
            exit(EXIT_FAILURE);
        }

        for (int i = 0; i < 3; i++) {
            if (write(logfd + 1, "Raw ADC value: ", 16) != 16) {
