            spi_close(spi_handle);
            close(logfd);
            exit(EXIT_FAILURE);
        }

        for (int i = 0; i < 3; i++) {
            if (write(logfd + 1, "Raw ADC value: ", 16) != 16) {
                perror("write");
                spi_close(spi_handle);
                close(logfd);
                exit(EXIT_FAILURE);
            }
            write(logfd + 1, "%d ", adc_read[i], 1);
        }

        if (write(logfd + 1, "Average: ", 6) != 6) {
            perror("write");
            spi_close(spi_handle);
            close(logfd);
            exit(EXIT_FAILURE);
        }

        write(logfd + 1, "%d ", average, 1);

        if (write(logfd + 1, "Valve position: ", 12) != 12) {
            perror("write");
            spi_close(spi_handle);
            close(logfd);
            exit(EXIT_FAILURE);
        }

        write(logfd + 1, "%d ", duty_cycle, 1);

        if (write(logfd + 1, "\n", 1) != 1) {
            perror("write");
            spi_close(spi_handle);
            close(logfd);
            exit(EXIT_FAILURE);
        }

        gpiod_output_t valve_output;
        gpiod_output_init(&valve_output, GPIO_VALVE);
        gpiod_output_set(&valve_output, duty_cycle);

        usleep(100000); // Adjust as needed for 100Hz PWM
    }

    spi_close(spi_handle);
    close(logfd);
    gpiod_disable(GPIOD_OUTPUT_DEFAULT);
    return 0;
}
```

This code uses `libgpiod` for GPIO control and `spidev` for SPI communication. It reads three successive ADC values from an MCP3008 ADC connected to a Raspberry Pi, computes their average, and sets the duty cycle of a PWM signal to control an ASCO RedHat 8210 series solenoid valve. The program logs every 5 seconds to a file named `irrigation.log` with timestamps, raw ADC readings, the computed average, and the resulting valve position. It also handles signal handlers for SIGINT and SIGTERM to provide a graceful shutdown.

