#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <pthread.h>
#include <time.h>
#include <libgpiod.h>

#define SPI_BUS 0
#define SPI_SPEED 1000000
#define MCP3008_CHANNEL 0
#define MOISTURE_THRESHOLD 0.5
#define LOG_FILE "soil_data.txt"
#define MAX_RETRIES 5
#define BACKOFF_FACTOR 2

#define SPI_CMD_START 0x01
#define SPI_CMD_SINGLE_ENDED 0x02
#define SPI_CMD_SELECT_CHANNEL 0x03
#define SPI_CMD_READ_DATA 0x04

#define LOG_ENTRY "%d:%d\n"

void spi_init(int bus) {
    int fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (fd == -1) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    struct stat sb;
    if (fstat(fd, &sb) == -1) {
        perror("fstat");
        close(fd);
        exit(EXIT_FAILURE);
    }

    if (sb.st_size == 0) {
        if (lseek(fd, 0, SEEK_SET) == -1) {
            perror("lseek");
            close(fd);
            exit(EXIT_FAILURE);
        }
    }

    close(fd);
}

void spi_write(int fd, uint8_t *data, size_t len) {
    if (write(fd, data, len) != len) {
        perror("write");
        exit(EXIT_FAILURE);
    }
}

uint16_t spi_read(int fd) {
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        perror("read");
        exit(EXIT_FAILURE);
    }
    return ((buf[0] << 8) | buf[1]);
}

void spi_close(int fd) {
    close(fd);
}

void spi_error_handler(int fd, int error) {
    fprintf(stderr, "SPI error: %d\n", error);
    spi_close(fd);
}

void* spi_thread(void* arg) {
    int fd = *(int*)arg;
    while (1) {
        uint16_t adc_value = spi_read(fd);
        if (adc_value == 0xFFFF) {
            fprintf(stderr, "SPI communication error, retrying...\n");
            usleep(BACKOFF_FACTOR * (int)rand() * RAND_MAX);
            continue;
        }

        if (adc_value > 1023 || adc_value < 0) {
            fprintf(stderr, "ADC value out of range, skipping\n");
            continue;
        }

        double moisture_percentage = (adc_value * 100.0) / 1023.0;
        if (moisture_percentage < MOISTURE_THRESHOLD) {
            fprintf(fd, LOG_ENTRY time(NULL) "Low moisture: %f\n", moisture_percentage);
        } else {
            fprintf(fd, LOG_ENTRY time(NULL) "High moisture: %f\n", moisture_percentage);
        }

        sleep(5);
    }
    return NULL;
}

int main() {
    int fd;
    spi_init(SPI_BUS);

    int ret = gpiod_setup_zero();
    if (ret < 0) {
        perror("gpiod_setup_zero");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_add_gpio_channel(SPI_BUS, 8, 1);
    if (ret < 0) {
        perror("gpiod_add_gpio_channel");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_output_init(SPI_BUS, 8, 1);
    if (ret < 0) {
        perror("gpiod_output_init");
        exit(EXIT_FAILURE);
    }

    pthread_t spi_thread_id;
    int arg = (int)&fd;
    if (pthread_create(&spi_thread_id, NULL, spi_thread, &arg) != 0) {
        perror("pthread_create");
        spi_close(fd);
        exit(EXIT_FAILURE);
    }

    while (1) {
        sleep(1);
    }

    pthread_join(spi_thread_id, NULL);
    spi_close(fd);
    gpiod_disable(SPI_BUS);
    gpiod_free_output_channel(SPI_BUS, 8);
    gpiod_cleanup();

    return 0;
}

