#include <libgpiod.h>

#define SPI_BUS 0
#define SPI_DEVICE 0
#define MCP3008_CHANNEL 0
#define PUMP_GPIO 18
#define LOG_FILE "irrigation.log"
#define SAMPLE_INTERVAL 60000  // 60 seconds in milliseconds
#define THRESHOLD 300

int spi_fd;
int mcp3008_fd;
int pump_gpio;

void setup_gpio(void) {
    int ret;
    ret = gpio_request(PUMP_GPIO, "pump");
    if (ret != 0) {
        perror("Failed to request GPIO");
        exit(EXIT_FAILURE);
    }
    gpio_direction_output(PUMP_GPIO);
}

void setup_spi(void) {
    int ret;
    ret = spi_open(SPI_BUS, 0, &spi_fd);
    if (ret < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }
}

int read_mcp3008(void) {
    uint32_t addr = (MCP3008_CHANNEL << 16) | 0x00;
    uint8_t data[2];
    int ret = spi_write(spi_fd, &addr, 1, SPI_MODE0);
    if (ret < 0) {
        perror("Failed to write to SPI");
        return -1;
    }
    ret = spi_read(spi_fd, data, 1, SPI_MODE0);
    if (ret < 0) {
        perror("Failed to read from SPI");
        return -1;
    }
    return data[0];
}

int main(int argc, char *argv[]) {
    setup_gpio();
    setup_spi();

    struct stat sb;
    if (stat(LOG_FILE, &sb) != 0) {
        if (open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644) == -1) {
            perror("Failed to open log file");
            exit(EXIT_FAILURE);
        }
    }

    while (1) {
        int moisture_value = read_mcp3008();
        if (moisture_value == -1) {
            fprintf(stderr, "Failed to read from MCP3008\n");
            continue;
        }

        uint32_t adc_value = moisture_value;
        if (adc_value < THRESHOLD) {
            gpio_set_level(PUMP_GPIO, 1);
            fprintf(stdout, "Moisture: %d, Pump ON, Time: %lu ms\n", adc_value, (unsigned long)millis());
        } else {
            gpio_set_level(PUMP_GPIO, 0);
            fprintf(stdout, "Moisture: %d, Pump OFF, Time: %lu ms\n", adc_value, (unsigned long)millis());
        }

        usleep(SAMPLE_INTERVAL * 1000 / HRTIME_PER_SEC);
    }

    close(spi_fd);
    close(mcp3008_fd);
    gpio_set_level(PUMP_GPIO, 0);  // Turn off the pump before exiting
    exit(0);
}

