void spi_init(int bus, int device) {
    int file = open("/dev/spidev0.0", O_RDWR);
    if (file == -1) {
        perror("open /dev/spidev0.0");
        exit(EXIT_FAILURE);
    }

    struct spi_fd_info info;
    if (ioctl(file, SPI_IOC_RDWR_CONTROL, &info) == -1) {
        perror("ioctl SPI_IOC_RDWR_CONTROL");
        close(file);
        exit(EXIT_FAILURE);
    }

    info.mode = SPI_MODE;
    info.bus_freq = SPI_BUS_FREQ;

    if (ioctl(file, SPI_IOC_RDWR_EDGE, &info) == -1) {
        perror("ioctl SPI_IOC_RDWR_EDGE");
        close(file);
        exit(EXIT_FAILURE);
    }

    if (ioctl(file, SPI_IOC_WR_REG, &info.reg) == -1) {
        perror("ioctl SPI_IOC_WR_REG");
        close(file);
        exit(EXIT_FAILURE);
    }

    if (ioctl(file, SPI_IOC_WR_DATA, &info.data) == -1) {
        perror("ioctl SPI_IOC_WR_DATA");
        close(file);
        exit(EXIT_FAILURE);
    }

    if (ioctl(file, SPI_IOC_RD_DATA, &info.data) == -1) {
        perror("ioctl SPI_IOC_RD_DATA");
        close(file);
        exit(EXIT_FAILURE);
    }

    close(file);
}

