#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/statfs.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <wiringPi.h>
#include <wiringPiSPI.h>
#include <wiringPiLED.h>

#define GPIO_SPI_CS 8
#define GPIO_SPI_MOSI 10
#define GPIO_SPI_MISO 9
#define GPIO_SPI_SCLK 11
#define GPIO_LED 17

#define BUFFER_SIZE 10
#define SAMPLE_TIME_MS 10
#define NOISE_CALIBRATION_SECONDS 5

int spi_fd;
int mcp3008_channel = 0;
uint16_t adc_buffer[BUFFER_SIZE];
uint16_t noise_buffer[BUFFER_SIZE];
int noise_buffer_index = 0;
int noise_calibrated = 0;
int noise_threshold = 0;
int led_state = 0;

void spi_init() {
    spi_fd = spidev_open(0, 0);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    struct spidev_dev_info info;
    if (spidev_probe(spi_fd, "Adafruit MAX9814 Electret Microphone Amplifier") < 0) {
        perror("Failed to probe SPI device");
        exit(EXIT_FAILURE);
    }

    if (spidev_set_mode(spi_fd, SPI_MODE0) < 0) {
        perror("Failed to set SPI mode");
        exit(EXIT_FAILURE);
    }
}

void gpio_init() {
    if (wiringPiSetup() < 0) {
        perror("Failed to initialize wiringPi");
        exit(EXIT_FAILURE);
    }

    if (wiringPiHardwarePinMapping() < 0) {
        perror("Failed to get hardware pin mapping");
        exit(EXIT_FAILURE);
    }

    if (wiringPiLEDSetup(GPIO_LED) < 0) {
        perror("Failed to set up GPIO LED");
        exit(EXIT_FAILURE);
    }

    if (wiringPiSPISetup(GPIO_SPI_CS, 0) < 0) {
        perror("Failed to set up SPI");
        exit(EXIT_FAILURE);
    }
}

void calibrate_noise() {
    clock_gettime(CLOCK_REALTIME, &start_time);
    for (int i = 0; i < SAMPLE_TIME_MS / 10; i++) {
        uint16_t adc_value = spidev_read8(spi_fd, mcp3008_channel);
        adc_buffer[noise_buffer_index++] = adc_value;
        usleep(100000); // 100 ms delay
    }

    noise_calibrated = 1;
    noise_threshold = adc_buffer[noise_buffer_index - 1];
    noise_buffer_index = 0;
}

void read_sound_level() {
    clock_gettime(CLOCK_REALTIME, &start_time);
    for (int i = 0; i < BUFFER_SIZE; i++) {
        uint16_t adc_value = spidev_read8(spi_fd, mcp3008_channel);
        adc_buffer[i] = adc_value;
        usleep(100000); // 100 ms delay
    }

    uint16_t sound_level = 0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sound_level += adc_buffer[i];
    }
    sound_level /= BUFFER_SIZE;

    if (noise_calibrated) {
        if (sound_level > noise_threshold + 50) {
            led_state = 1;
        }
    }
}

void debounce_check() {
    if (led_state == 1 && !last_debounce_time) {
        led_state = 0;
        last_debounce_time = time(NULL);
    } else if (!led_state && time(NULL) - last_debounce_time > SAMPLE_TIME_MS / 10) {
        led_state = 1;
        last_debounce_time = time(NULL);
    }
}

int main(int argc, char *argv[]) {
    spi_init();
    gpio_init();

    calibrate_noise();

    while (1) {
        read_sound_level();
        debounce_check();

        if (wiringPiInputRead(GPIO_LED) == 1) {
            printf("Sound detected!\n");
        }

        usleep(100000); // 100 ms delay
    }

    return 0;
}

