        exit(EXIT_FAILURE);
    }
    ret = spidev_set_bandwidth(dev, SPI_BANDWIDTH_FULL);
    if (ret < 0) {
        perror("spidev_set_bandwidth");
        exit(EXIT_FAILURE);
