#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <linux/spi/spidev.h>
#include <math.h>

#define MCP3008_CS 8
#define MCP3008_MOSI 10
#define MCP3008_MISO 9
#define MCP3008_SCLK 11
#define ADXL335_X_OUT 0
#define ADXL335_Y_OUT 1
#define ADXL335_Z_OUT 2
#define ADXL335_REF 3.3
#define FILTER_RATE 10
#define BUFFER_SIZE 10

typedef struct {
    int16_t raw_x, raw_y, raw_z;
    float filtered_x, filtered_y, filtered_z;
} AccelerationData;

static int mcp3008_fd;
static int adxl335_fd;
static AccelerationData buffer[BUFFER_SIZE];

void spi_init(void) {
    int file = open("/dev/spidev0.0", O_RDWR);
    if (file < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(file, SPI_SET_MODE, SPI_MODE0) < 0) {
        perror("Failed to set SPI mode");
        close(file);
        exit(EXIT_FAILURE);
    }

    if (ioctl(file, SPI_SET_BITS per_word, 10) < 0) {
        perror("Failed to set bits per word");
        close(file);
        exit(EXIT_FAILURE);
    }
}

void adxl335_init(void) {
    adxl335_fd = open("ttyAMA0", O_RDWR | O_NOCTTY | O_NDELAY);
    if (adxl335_fd < 0) {
        perror("Failed to open ADXL335");
        exit(EXIT_FAILURE);
    }

    if (ioctl(adxl335_fd, ADXL_SET_XOUT, ADXL335_X_OUT) < 0) {
        perror("Failed to set X-out");
        close(adxl335_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(adxl335_fd, ADXL_SET_YOUT, ADXL335_Y_OUT) < 0) {
        perror("Failed to set Y-out");
        close(adxl335_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(adxl335_fd, ADXL_SET_ZOUT, ADXL335_Z_OUT) < 0) {
        perror("Failed to set Z-out");
        close(adxl335_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(adxl335_fd, ADXL_SET_REF, ADXL335_REF) < 0) {
        perror("Failed to set reference");
        close(adxl335_fd);
        exit(EXIT_FAILURE);
    }
}

void kalman_filter(int16_t *raw_x, int16_t *raw_y, int16_t *raw_z) {
    static float k_x = 0.0, k_y = 0.0, k_z = 0.0;
    static AccelerationData last_data = {0, 0, 0};

    int16_t dx = *raw_x - last_data.filtered_x;
    int16_t dy = *raw_y - last_data.filtered_y;
    int16_t dz = *raw_z - last_data.filtered_z;

    k_x = (1.0 / BUFFER_SIZE) * dx + (1.0 / 2.0) * k_x;
    k_y = (1.0 / BUFFER_SIZE) * dy + (1.0 / 2.0) * k_y;
    k_z = (1.0 / BUFFER_SIZE) * dz + (1.0 / 2.0) * k_z;

    last_data.filtered_x += k_x;
    last_data.filtered_y += k_y;
    last_data.filtered_z += k_z;

    buffer[0].raw_x = *raw_x;
    buffer[0].raw_y = *raw_y;
    buffer[0].raw_z = *raw_z;
    buffer[0].filtered_x = last_data.filtered_x;
    buffer[0].filtered_y = last_data.filtered_y;
    buffer[0].filtered_z = last_data.filtered_z;
}

void read_accelerometer(void) {
    int16_t raw_x, raw_y, raw_z;

    if (ioctl(adxl335_fd, ADXL_GET_RAW, &raw_x, &raw_y, &raw_z) < 0) {
        perror("Failed to read raw accelerometer data");
        return;
    }

    kalman_filter(&raw_x, &raw_y, &raw_z);

    printf("X: %.2f g, Y: %.2f g, Z: %.2f g\n", raw_x / 10.0, raw_y / 10.0, raw_z / 10.0);
}

void signal_handler(int sig) {
    printf("Received signal %d, exiting gracefully...\n", sig);
    exit(0);
}

int main(int argc, char *argv[]) {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    spi_init();
    adxl335_init();

    while (1) {
        read_accelerometer();
        usleep(100000); // 100 ms interval
    }

    close(mcp3008_fd);
    close(adxl335_fd);

    return 0;
}

