}

int main(int argc, char *argv[]) {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    spi_init();
    adxl335_init();

    while (1) {
        read_accelerometer();
        usleep(100000); // 100 ms interval
    }

    close(mcp3008_fd);
    close(adxl335_fd);

    return 0;
}
