        // Parent process
        waitpid(pid, NULL, 0);
    }

    piod_disable_timeout(gpios, 3);
    piod_cleanup();

    if (close(STDOUT_FILENO) == -1) {
        perror("close");
        exit(EXIT_FAILURE);
    }
    if (close(STDERR_FILENO) == -1) {
        perror("close");
        exit(EXIT_FAILURE);
    }

    if (unlink(LOG_FILE) == -1) {
        perror("unlink");
        exit(EXIT_FAILURE);
    }

    return 0;
}

