#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <linux/spi/spidev.h>
#include <errno.h>
#include <signal.h>

#define SPI_DEVICE 0
#define SPI_SPEED 500000
#define MCP3008_CHANNEL 0
#define PUMP_GPIO 17
#define LOG_FILE "watering.log"
#define LOG_INTERVAL 60
#define MOISTURE_THRESHOLD 30

void log_event(const char *event) {
    time_t now = time(NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    FILE *file = fopen(LOG_FILE, "a");
    if (file) {
        fprintf(file, "%s: %s\n", timestamp, event);
        fclose(file);
    }
}

void spi_init() {
    int file = open("/dev/spidev0.0", O_RDWR);
    if (file < 0) {
        perror("open /dev/spidev0.0");
        exit(EXIT_FAILURE);
    }

    if (ioctl(file, SPI_IOC_DEVICE, SPI_DEVICE) < 0) {
        perror("ioctl SPI_IOC_DEVICE");
        close(file);
        exit(EXIT_FAILURE);
    }

    if (ioctl(file, SPI_IOC_SPEED_HIGH, SPI_SPEED) < 0) {
        perror("ioctl SPI_IOC_SPEED_HIGH");
        close(file);
        exit(EXIT_FAILURE);
    }

    if (ioctl(file, SPI_IOC_MODE, SPI_MODE0) < 0) {
        perror("ioctl SPI_IOC_MODE");
        close(file);
        exit(EXIT_FAILURE);
    }

    close(file);
}

int mcp3008_read(int channel) {
    int file = open("/dev/spidev0.0", O_RDWR);
    if (file < 0) {
        perror("open /dev/spidev0.0");
        return -1;
    }

    if (ioctl(file, SPI_IOC_MESSAGE, (void *)"read: 0x" MCP3008_CHANNEL) < 0) {
        perror("ioctl SPI_IOC_MESSAGE");
        close(file);
        return -1;
    }

    uint32_t data;
    if (read(fileno(file), &data, sizeof(data)) != sizeof(data)) {
        perror("read from SPI");
        close(file);
        return -1;
    }

    close(file);
    return data >> 8;
}

int main() {
    spi_init();

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    log_event("Program started");

    while (1) {
        int moisture_value = mcp3008_read(MCP3008_CHANNEL);
        if (moisture_value == -1) {
            log_event("Error reading from MCP3008 ADC");
            continue;
        }

        float moisture_percent = (float)moisture_value * 0.01;
        log_event(moisture_percent < MOISTURE_THRESHOLD ? "Pump ON" : "Pump OFF");

        if (moisture_percent < MOISTURE_THRESHOLD) {
            log_event("Moisture level below threshold, turning pump ON");
            printf("Moisture level below threshold, turning pump ON\n");
            gpioSet(PUMP_GPIO, 1);
        } else {
            log_event("Moisture level above or equal to threshold, turning pump OFF");
            printf("Moisture level above or equal to threshold, turning pump OFF\n");
            gpioSet(PUMP_GPIO, 0);
        }

        usleep(LOG_INTERVAL * 1000000);
    }

    log_event("Program terminated");
    return 0;
}

void sigint_handler(int signum) {
    log_event("SIGINT received, turning pump OFF");
    gpioSet(PUMP_GPIO, 0);
}

void sigterm_handler(int signum) {
    log_event("SIGTERM received, turning pump OFF");
    gpioSet(PUMP_GPIO, 0);
}

void gpioSet(int pin, int state) {
    // Assuming gpio_set_level is a function from a GPIO library
    // For simplicity, we'll just print the state here
    printf("Setting GPIO%d to %d\n", pin, state);
}

