#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <errno.h>

#define CHANNELS 3
#define FILE_NAME "sensor_data.csv"
#define SPI_DEV "/dev/spidev0.0"
#define SPI_SPEED 10000000  // 10 MHz
#define SPI_MODE 0           // SPI Mode 0
#define SPI_BITS 8            // 8 bits per word

void sigint_handler(int sig) {
    close(fildes);
    printf("Exiting gracefully...\n");
    exit(0);
}

int main() {
    int fildes;
    struct spidev_dev *dev;
    unsigned char buffer[3];

    // Initialize signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Open SPI device
    fildes = open(SPI_DEV, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fildes == -1) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    // Set SPI mode and speed
    if (ioctl(fildes, SPI_SET_MODE, SPI_MODE) == -1) {
        perror("ioctl(SPI_SET_MODE)");
        close(fildes);
        exit(EXIT_FAILURE);
    }
    if (ioctl(fildes, SPI_SET_BITS per_word, SPI_BITS) == -1) {
        perror("ioctl(SPI_SET_BITS_PER_WORD)");
        close(fildes);
        exit(EXIT_FAILURE);
    }
    if (ioctl(fildes, SPI_SET_CLOCKS, &SPI_CLOCK_1MHZ) == -1) {
        perror("ioctl(SPI_SET_CLOCKS)");
        close(fildes);
        exit(EXIT_FAILURE);
    }

    // Initialize MCP3008
    dev = (struct spidev_dev *)fildes;
    if (ioctl(dev, SPI_READ_REGISTER, MCP3008_REG_CTRLA) == -1) {
        perror("ioctl(MCP3008_REG_CTRLA)");
        close(fildes);
        exit(EXIT_FAILURE);
    }
    dev->regs[MCP3008_REG_CH0CTRLA] |= MCP3008_CH0_ANALOGINPUT;
    dev->regs[MCP3008_REG_CH1CTRLA] |= MCP3008_CH1_ANALOGINPUT;
    dev->regs[MCP3008_REG_CH2CTRLA] |= MCP3008_CH2_ANALOGINPUT;

    // Enable channels
    if (ioctl(dev, SPI_WRITE_REGISTER, MCP3008_REG_CH0CTRLB) == -1) {
        perror("ioctl(MCP3008_REG_CH0CTRLB)");
        close(fildes);
        exit(EXIT_FAILURE);
    }
    dev->regs[MCP3008_REG_CH0CTRLB] |= MCP3008_CH0_ANALOGSELECT_0;

    if (ioctl(dev, SPI_WRITE_REGISTER, MCP3008_REG_CH1CTRLB) == -1) {
        perror("ioctl(MCP3008_REG_CH1CTRLB)");
        close(fildes);
        exit(EXIT_FAILURE);
    }
    dev->regs[MCP3008_REG_CH1CTRLB] |= MCP3008_CH1_ANALOGSELECT_1;

    if (ioctl(dev, SPI_WRITE_REGISTER, MCP3008_REG_CH2CTRLB) == -1) {
        perror("ioctl(MCP3008_REG_CH2CTRLB)");
        close(fildes);
        exit(EXIT_FAILURE);
    }
    dev->regs[MCP3008_REG_CH2CTRLB] |= MCP3008_CH2_ANALOGSELECT_2;

    // Read channels
    while (1) {
        for (int i = 0; i < CHANNELS; i++) {
            if (ioctl(dev, SPI_READ_REGISTER, MCP3008_REG_CH0CH0) == -1) {
                perror("ioctl(MCP3008_REG_CH0CH0)");
                break;
            }
            buffer[i] = dev->regs[MCP3008_REG_CH0CH0];

            if (ioctl(dev, SPI_READ_REGISTER, MCP3008_REG_CH1CH1) == -1) {
                perror("ioctl(MCP3008_REG_CH1CH1)");
                break;
            }
            buffer[i + CHANNELS] = dev->regs[MCP3008_REG_CH1CH1];

            if (ioctl(dev, SPI_READ_REGISTER, MCP3008_REG_CH2CH2) == -1) {
                perror("ioctl(MCP3008_REG_CH2CH2)");
                break;
            }
            buffer[i + 2 * CHANNELS] = dev->regs[MCP3008_REG_CH2CH2];
        }

        // Write to CSV file
        fildes = open(FILE_NAME, O_WRONLY | O_CREAT | O_APPEND, 0644);
        if (fildes == -1) {
            perror("open");
            exit(EXIT_FAILURE);
        }
        if (write(fildes, buffer, 3 * sizeof(unsigned char)) == -1) {
            perror("write");
            close(fildes);
            exit(EXIT_FAILURE);
        }
        close(fildes);

        usleep(1000000); // Wait for 1 second
    }

    return 0;
}

