            if (ioctl(dev, SPI_READ_REGISTER, MCP3008_REG_CH0CH0) == -1) {
                perror("ioctl(MCP3008_REG_CH0CH0)");
                break;
            }
            buffer[i] = dev->regs[MCP3008_REG_CH0CH0];

            if (ioctl(dev, SPI_READ_REGISTER, MCP3008_REG_CH1CH1) == -1) {
                perror("ioctl(MCP3008_REG_CH1CH1)");
                break;
            }
            buffer[i + CHANNELS] = dev->regs[MCP3008_REG_CH1CH1];

            if (ioctl(dev, SPI_READ_REGISTER, MCP3008_REG_CH2CH2) == -1) {
                perror("ioctl(MCP3008_REG_CH2CH2)");
                break;
            }
            buffer[i + 2 * CHANNELS] = dev->regs[MCP3008_REG_CH2CH2];
        }

        // Write to CSV file
        fildes = open(FILE_NAME, O_WRONLY | O_CREAT | O_APPEND, 0644);
        if (fildes == -1) {
            perror("open");
            exit(EXIT_FAILURE);
        }
        if (write(fildes, buffer, 3 * sizeof(unsigned char)) == -1) {
            perror("write");
            close(fildes);
            exit(EXIT_FAILURE);
        }
        close(fildes);

        usleep(1000000); // Wait for 1 second
    }

    return 0;
}
```

This code uses the `spidev` library to communicate with the MCP3008 analog-to-digital converter over the SPI bus. It reads three channels (0, 1, and 2) and logs the readings to a CSV file named `sensor_data.csv`. The program checks the result of every open, ioctl, read, and write call and exits gracefully on any failure. It also installs a SIGINT handler to properly close the CSV file and release SPI resources when Ctrl+C is pressed.

Before compiling, make sure to install the `spidev` library:

```sh
sudo apt-get install libspidev-dev
```

Compile the code with:

```sh
gcc -o mcp3008_reader mcp3008_reader.c -lspidev
```

Then run the program:

```sh
./mcp3008_reader
```

