#define MQTT_BROKER "mqtt.eclipseprojects.io"
#define MQTT_PORT 1883
#define MQTT_TOPIC "home/led_control"
#define MQTT_CLIENT_ID "rpi_led_control"
#define MQTT_QOS 0
#define LED_PIN 17

// MQTT client callback functions
void on_connect(struct mqtt *client, struct mqtt_connect_info *connect_info) {
    printf("Connected as %s\n", client->client_id.data);
}

void on_disconnect(struct mqtt *client, int graceful) {
    printf("Disconnected\n");
}

void on_message(struct mqtt *client, const struct mqtt_message *message) {
    char *payload = mqtt_message_payload(message);
    size_t payload_len = mqtt_message_len(message);
    char *json_str = mqtt_message_json_str(message);
    size_t json_len = mqtt_message_json_len(message);

    if (json_str == NULL || json_len == 0) {
        printf("Invalid JSON payload\n");
        return;
    }

    // Parse JSON
    char *led_state = strtok(json_str, "\"");
    if (led_state == NULL) {
        printf("JSON parsing error\n");
        return;
    }

    bool led_on = strcmp(led_state, "true") == 0;

    // Clean up JSON
    free(json_str);

    // Control GPIO
    bool led_control_signal = led_on;
    if (led_control_signal != gpio_get_value(LED_PIN)) {
        gpio_set_value(LED_PIN, led_control_signal);
    }
}

// Signal handlers
void signal_handler(int signum) {
    printf("Received signal %d, performing clean shutdown\n", signum);
    mqtt_disconnect(client);
    gpio_set_value(LED_PIN, 0);
    exit(0);
}

int main(int argc, char *argv[]) {
    struct mqtt_client client;
    struct sigset_t sigset;
    int sig;

    // Initialize gpiod
    if (gpiod_init() < 0) {
        perror("Failed to initialize gpiod");
        return EXIT_FAILURE;
    }

    // Initialize signal handlers
    sigset_t sigmask;
    sigemptyset(&sigmask);
    sigaddset(&sigmask, SIGINT);
    sigaddset(&sigmask, SIGTERM);
    if (sigprocmask(SIG_BLOCK, &sigmask, NULL) == -1) {
        perror("Failed to block signals");
        return EXIT_FAILURE;
    }

    // Initialize MQTT client
    mqtt_init(&client);
    mqtt_set_callback(&client, on_connect, NULL, NULL);
    mqtt_set_callback(&client, on_disconnect, NULL, NULL);
    mqtt_set_callback(&client, on_message, NULL, NULL);
    mqtt_connect(&client, MQTT_BROKER, MQTT_PORT, MQTT_CLIENT_ID, MQTT_QOS, NULL, on_connect);

    // Exponential backoff for reconnection
    int reconnect_delay = 1;
    int max_delay = 60;
    int current_delay = reconnect_delay;

    while (1) {
        mqtt_loop(&client, current_delay);

        // Check for errors
        if (mqtt_get_error(&client) != MQTT_ERR_NONE) {
            printf("MQTT error: %s\n", mqtt_get_error_str(&client));
            current_delay = min(current_delay * 2, max_delay);
            printf("Reconnecting in %d seconds\n", current_delay);
            usleep(current_delay * 1000000);
        }

        // Signal handling
        sigaddset(&sigset, signum);
        if (sigwait(&sigset, &sig) == signum) {
            signal_handler(signum);
        }
    }

    // Clean up
    mqtt_disconnect(&client);
    gpio_set_value(LED_PIN, 0);
    gpiod_destroy(0);
    return EXIT_SUCCESS;
}

