#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <string.h>
#include <errno.h>
#include <pigpio.h>

#define GPIO_DO 17
#define GPIO_LED 18
#define DELAY_MS 100

void alarm_led(int led_gpio) {
    gpioOutput(led_gpio, 1);
    sleep(1);
    gpioOutput(led_gpio, 0);
}

int main(int argc, char *argv[]) {
    int led_gpio = GPIO_LED;
    int do_gpio = GPIO_DO;
    int sound_level;
    int ret;

    // Initialize pigpio
    if (gpioInit() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(EXIT_FAILURE);
    }

    // Open the chip
    if (gpioOpen(do_gpio) < 0) {
        fprintf(stderr, "Failed to open GPIO%d\n", do_gpio);
        gpioClose(do_gpio);
        exit(EXIT_FAILURE);
    }

    // Request line handling
    if (gpioLineRequest(do_gpio, PI_ACTIVE_HIGH) < 0) {
        fprintf(stderr, "Failed to request line handling for GPIO%d\n", do_gpio);
        gpioClose(do_gpio);
        exit(EXIT_FAILURE);
    }

    // Set up signal handlers
    signal(SIGINT, signalHandler);
    signal(SIGTERM, signalHandler);

    // Main loop
    while (1) {
        ret = gpioRead(do_gpio);
        if (ret < 0) {
            fprintf(stderr, "Error reading GPIO%d: %s\n", do_gpio, strerror(errno));
            break;
        }

        sound_level = ret;

        if (sound_level == 0) {
            printf("No sound detected\n");
        } else {
            printf("Sound detected\n");
            alarm_led(led_gpio);
        }

        usleep(DELAY_MS * 1000);
    }

    // Clean up
    gpioClose(do_gpio);
    gpioLineRelease(do_gpio);
    gpioExit();

    return 0;

signalHandler:
    printf("Received signal, cleaning up and exiting...\n");
    gpioClose(do_gpio);
    gpioLineRelease(do_gpio);
    gpioExit();
    exit(EXIT_SUCCESS);
}

