#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>
#include <linux/gpiochip.h>
#include <linux/delay.h>
#include <signal.h>
#include <stdatomic.h>

#define GPIO_LINE "/dev/gpiochip0"
#define GPIO_PIN 17
#define LOG_FILE "/var/log/vibration_shutdown.log"
#define LOG_MESSAGE "Vibration detected!"

volatile sig_atomic_t shutdown_requested = 0;

void signal_handler(int signum) {
    shutdown_requested = 1;
}

int main() {
    int fd;
    struct gpio_request req;
    struct gpio_value_request val;
    struct gpio_line_request line;
    struct timespec ts;
    char log_msg[256];

    // Initialize signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    fd = open(GPIO_LINE, O_RDWR);
    if (fd < 0) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    // Request line
    req.size = sizeof(req);
    req.type = GPIOD_LINE;
    req.flags = GPIOD_LINE_NONBLOCK;
    req.value = 0; // Initially, line is off
    if (gpio_request(fd, &req) < 0) {
        perror("Failed to request line");
        close(fd);
        exit(EXIT_FAILURE);
    }

    // Obtain line
    line.line = GPIO_LINE;
    line.pin = GPIO_PIN;
    if (gpio_line_request(fd, &line) < 0) {
        perror("Failed to obtain line");
        close(fd);
        exit(EXIT_FAILURE);
    }

    // Configure for falling edge detection
    val.value = 0; // Initially, line is off
    if (gpio_line_value_get(fd, &val) < 0) {
        perror("Failed to get initial line value");
        close(fd);
        exit(EXIT_FAILURE);
    }
    if (gpio_line_edge_request(fd, line.pin, EDGE_FALLING) < 0) {
        perror("Failed to configure for falling edge detection");
        close(fd);
        exit(EXIT_FAILURE);
    }

    // Open log file
    fd = open(LOG_FILE, O_APPEND | O_CREAT | O_WRONLY, 0644);
    if (fd < 0) {
        perror("Failed to open log file");
        close(fd);
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (!shutdown_requested) {
        // Wait for event
        ts.tv_sec = 0;
        ts.tv_nsec = 0;
        if (gpio_line_event_wait(fd, &ts, 1000000) < 0) {
            perror("Failed to wait for event");
            continue;
        }

        // Read event
        if (gpio_line_event_read(fd) < 0) {
            perror("Failed to read event");
            continue;
        }

        // Log and print message
        snprintf(log_msg, sizeof(log_msg), "%s\n", ctime(NULL));
        write(fd, log_msg, strlen(log_msg));
        printf("%s\n", log_msg);

        // Shutdown on vibration
        system("sudo shutdown -h now");
    }

    // Release resources
    gpio_line_disable(fd, line.pin);
    gpio_line_request(fd, &line);
    gpio_request(fd, &req);
    close(fd);

    return 0;
}

