#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <linux/spi/spidev.h>
#include <linux/gpio/gpio.h>
#include <linux/gpio/spidev.h>
#include <errno.h>
#include <signal.h>

#define BUFFER_SIZE 120
#define SAMPLING_INTERVAL_SECONDS 5

#define CE0_GPIO 8
#define CS_GPIO 9
#define SCLK_GPIO 10
#define DOUT_GPIO 11

#define SPI_DEVICE 0
#define SPI_SPEED 1000000

#define TEMP_LOG_FILE "temp_log.dat"

typedef struct {
    float data[BUFFER_SIZE];
    int head;
    int tail;
} CircularBuffer;

CircularBuffer buffer;

void spi_init(void) {
    int file = open(TEMP_LOG_FILE, O_WRONLY | O_CREAT | O_TRUNC, 0666);
    if (file == -1) {
        perror("Error opening temp_log.dat");
        return;
    }
    ftruncate(file, sizeof(float) * BUFFER_SIZE);
    close(file);

    int spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd == -1) {
        perror("Error opening SPI device");
        return;
    }

    if (ioctl(spi_fd, SPI_SET_MODE, SPI_MODE0) == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return;
    }

    if (ioctl(spi_fd, SPI_SET_BITS per 32, SPI_BITS_16) == -1) {
        perror("Error setting SPI bits per word");
        close(spi_fd);
        return;
    }

    if (ioctl(spi_fd, SPI_SET_CLOCK_POLARITY, 0) == -1) {
        perror("Error setting SPI clock polarity");
        close(spi_fd);
        return;
    }

    if (ioctl(spi_fd, SPI_SET_CLOCK_PHASE, 0) == -1) {
        perror("Error setting SPI clock phase");
        close(spi_fd);
        return;
    }

    if (ioctl(spi_fd, SPI_SET_MAX_SPEED, SPI_SPEED) == -1) {
        perror("Error setting SPI maximum speed");
        close(spi_fd);
        return;
    }
}

void mcp3008_init(void) {
    int file = open(TEMP_LOG_FILE, "r+b");
    if (file == -1) {
        perror("Error opening temp_log.dat for reading");
        return;
    }

    fseek(file, 0, SEEK_SET);
    fread(&buffer.data, sizeof(float) * BUFFER_SIZE, 1, file);
    fclose(file);

    buffer.head = 0;
    buffer.tail = 0;
}

void spi_transfer(uint16_t address, uint16_t reg, uint16_t value) {
    char buf[3];
    sprintf(buf, "%04x", address);
    write(spi_fd, buf, 4);

    sprintf(buf, "%02x", reg);
    write(spi_fd, buf, 2);

    sprintf(buf, "%04x", value);
    write(spi_fd, buf, 4);

    read(spi_fd, &buffer, sizeof(buffer));
}

float read_temperature(void) {
    uint16_t address = 0x40; // MCP3008 channel 0
    uint16_t reg = 0x00; // Read raw ADC value
    uint16_t value;

    spi_transfer(address, reg, 0);
    read(spi_fd, &value, sizeof(value));

    return (float)value * 3.3 / 1023.0; // Convert raw ADC value to temperature in Celsius
}

void log_temperature(float temp) {
    if (buffer.head == BUFFER_SIZE) {
        close(buffer.tail);
        buffer.tail = (buffer.tail + 1) % BUFFER_SIZE;
    }

    buffer.data[buffer.head] = temp;
    buffer.head = (buffer.head + 1) % BUFFER_SIZE;

    if (buffer.head == buffer.tail) {
        int file = open(TEMP_LOG_FILE, "ab");
        if (file == -1) {
            perror("Error appending to temp_log.dat");
            return;
        }
        fwrite(&buffer.data, sizeof(float), 1, file);
        close(file);
    }
}

void signal_handler(int signum) {
    spi_close();
    mcp3008_close();
    close(temp_log_fd);
    exit(0);
}

int main(void) {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    spi_init();
    mcp3008_init();

    while (1) {
        float temp = read_temperature();
        log_temperature(temp);
        usleep(100000000 / SAMPLING_INTERVAL_SECONDS);
    }

    return 0;
}

