            timeinfo->tm_year + 1900, timeinfo->tm_mon + 1, timeinfo->tm_mday,
            timeinfo->tm_hour, timeinfo->tm_min, timeinfo->tm_sec);

    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
    fprintf(file, "%s, %d, %d\n", time_str, pin, state);
    fclose(file);
}

int main(int argc, char *argv[]) {
    pigpio_init(5); // Initialize pigpio with default config

    if (gpioSetup(PIN, PIGO_INPUT, 1) < 0) {
        fprintf(stderr, "Error setting up GPIO pin %d as input with pull-down\n", PIN);
        pigpioExit();
        exit(EXIT_FAILURE);
    }

    FILE *log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        pigpioExit();
        exit(EXIT_FAILURE);
    }

    while (1) {
        int state = gpioRead(PIN);
        log_event(get_time_str(), PIN, state);

        if (state == HIGH) {
            fprintf(stderr, "ALARM: Flame detected\n");
            system("echo 'ALARM: Flame detected' > /dev/ttyAMA0"); // Assuming output to serial console
        }

        usleep(POLL_INTERVAL * 1000); // Sleep for the specified interval
    }

    pigpioExit();
    fclose(log_file);
    remove(LOG_FILE); // Clean up log file on exit

    return 0;
}

int gpioSetup(int pin, int mode, int pull) {
    int result = pigpioSetupPin(pin, mode, pull);
    if (result < 0) {
        fprintf(stderr, "Error setting up GPIO pin %d: %s\n", pin, pigpio_strerror(result));
        return result;
    }
    return 0;
}
