    struct spi_ioc_transfer spi_transfer = {
        .transfer_type = SPI_RTC_READ,
        .addr_r = (channel << 16) | 0x00,
        .data_r = 0,
        .len = 1,
        .timeout_msec = 500000
    };
    return spidev_recv(fd, &spi_transfer, 1);
}

unsigned int map_adc_to_temp(unsigned int adc_count) {
    // Conversion factor from ADC to temperature (10-bit resolution)
    // Adjust as needed based on your MCP3008 configuration
    return (adc_count * 3.3 / 1023.0) * 100;
}

void mcp4725_write(unsigned int dac_voltage) {
    char command[10];
    snprintf(command, sizeof(command), "0x%02X", dac_voltage);
    write(fd_i2c, command, strlen(command));
}

void mcp4725_close(struct i2c_client *client) {
    i2c_client_put(client);
    i2c_close(MCP4725_ADDRESS);
}

