#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <linux/spi/spidev.h>
#include <libgpiod/gpio.h>

#define MCP3008_CE 0
#define MCP3008_SPI_SPEED 1000000
#define SENSOR_COUNT 3
#define SENSORS_CHANNELS {0, 1, 2}
#define LOG_FILE "soil_data.txt"
#define LOG_FORMAT "%Y-%m-%d %H:%M:%S"

int mcp3008_spi_init(int fd) {
    struct spi_device *dev;
    int ret;

    dev = spi_open(MCP3008_CE, 0);
    if (!dev) {
        perror("Failed to open MCP3008 CE");
        return -1;
    }

    ret = spi_configure(dev, MCP3008_SPI_SPEED);
    if (ret) {
        perror("Failed to configure MCP3008");
        spi_close(dev);
        return -1;
    }

    return 0;
}

int mcp3008_read_adc(int fd, int channel) {
    uint32_t value;
    int ret;

    ret = spi_write_reg(fd, MCP3008_REG_ADC_CHSEL, channel);
    if (ret) {
        perror("Failed to write channel select register");
        return -1;
    }

    ret = spi_read_reg(fd, MCP3008_REG_ADC_RESULT, &value);
    if (ret) {
        perror("Failed to read ADC result");
        return -1;
    }

    return value;
}

int main(int argc, char *argv[]) {
    int fd, ret;
    struct stat sb;
    char *log_path = LOG_FILE;

    fd = spidev_open(0, 0);
    if (fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    ret = mcp3008_spi_init(fd);
    if (ret) {
        fprintf(stderr, "Failed to initialize MCP3008\n");
        spidev_close(fd, 0);
        return 1;
    }

    struct tm timeinfo;
    time_t now = time(NULL);
    struct itimerspec timers;
    timers.it_value.tv_sec = 60;
    timers.it_value.tv_nsec = 0;
    timers.it_repeat.val = -1;

    if (setitimer(ITIMERS_INTERVAL, &timers, NULL) < 0) {
        perror("Failed to set interval timer");
        spidev_close(fd, 0);
        return 1;
    }

    while (1) {
        for (int i = 0; i < SENSOR_COUNT; i++) {
            int adc_value = mcp3008_read_adc(fd, SENSORS_CHANNELS[i]);
            if (adc_value == -1) {
                fprintf(stderr, "Invalid ADC value from sensor %d\n", i + 1);
                continue;
            }

            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), LOG_FORMAT, localtime(&now));

            FILE *log_file = fopen(log_path, "a");
            if (!log_file) {
                perror("Failed to open log file");
                continue;
            }

            fprintf(log_file, "%s: %d\n", timestamp, adc_value);
            fclose(log_file);
        }

        usleep(1000000); // Sleep for 1 second
    }

    fprintf(stderr, "Exiting on SIGINT\n");
    spidev_close(fd, 0);

    return 0;
}

