#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <string.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <linux/gpio.h>
#include <pigpio.h>

#define RELAY_PINS {17, 22, 23, 24}
#define RELAY_ACTIVE_LOW 1
#define RELAY_DEACTIVE_HIGH 0
#define RELAY_ON_TIME_SEC 1.0
#define RELAY_OFF_TIME_SEC 1.0

void signal_handler(int signum) {
    for (int i = 0; i < sizeof(RELAY_PINS) / sizeof(int); i++) {
        gpioSetDirection(RELAY_PINS[i], GPIO_OUT);
    }
    for (int i = 0; i < sizeof(RELAY_PINS) / sizeof(int); i++) {
        gpioWrite(RELAY_PINS[i], RELAY_DEACTIVE_HIGH);
    }
}

int main(int argc, char *argv[]) {
    if (signal(SIGINT, signal_handler) == SIG_IGN || signal(SIGTERM, signal_handler) == SIG_IGN) {
        perror("Failed to set signal handler");
        exit(EXIT_FAILURE);
    }

    pigpio_init(5); // Initialize pigpio with 5 available pins

    for (int i = 0; i < sizeof(RELAY_PINS) / sizeof(int); i++) {
        gpioSetDirection(RELAY_PINS[i], GPIO_OUTPUT); // Set relay pins as output
    }

    while (1) {
        for (int i = 0; i < sizeof(RELAY_PINS) / sizeof(int); i++) {
            gpioWrite(RELAY_PINS[i], RELAY_ACTIVE_LOW); // Activate relay
            sleep(RELAY_ON_TIME_SEC); // Wait for one second
            gpioWrite(RELAY_PINS[i], RELAY_DEACTIVE_HIGH); // Deactivate relay
            sleep(RELAY_OFF_TIME_SEC); // Wait for one second
        }
    }

    pigpio_cleanup(); // Release GPIO resources
    return 0;
}

