#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <errno.h>
#include <signal.h>
#include <pthread.h>
#include <libgpiod.h>
#include <mcp3008.h>
#include <l298n.h>

#define SPI_CHANNEL 0
#define SPI_FREQ_HZ 1000000
#define SPI_MODE 0
#define RAIN_SENSOR_PIN 0
#define MOTOR_FORWARD_PIN 17
#define MOTOR_REVERSE_PIN 18
#define MOTOR_EN_PIN 27
#define RAIN_THRESHOLD 5
#define LOG_FILE "rain_log.txt"
#define LOG_INTERVAL_S 1

volatile sig_atomic_t stop_loop = 0;

void signal_handler(int signum) {
    global_signal_set(SIGINT, SIG_IGN);
    global_signal_set(SIGTERM, SIG_IGN);
    global_signal_set(SIGUSR1, signal_handler);
    global_signal_set(SIGUSR2, signal_handler);
    global_signal_set(SIGINT, signal_handler);
    global_signal_set(SIGTERM, signal_handler);
    global_signal_set(SIGSEGV, signal_handler);
    global_signal_set(SIGABRT, signal_handler);
    global_signal_set(SIGFPE, signal_handler);
    global_signal_set(SIGILL, signal_handler);
    global_signal_set(SIGTRAP, signal_handler);
    global_signal_set(SIGEMT, signal_handler);
    global_signal_set(SIGBUS, signal_handler);
    global_signal_set(SIGUSR0, signal_handler);
    stop_loop = 1;
}

void setup_log_file() {
    int fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (fd == -1) {
        perror("Error opening log file");
        exit(EXIT_FAILURE);
    }
    struct stat sb;
    if (fstat(fd, &sb) == -1) {
        perror("Error getting file stats");
        close(fd);
        exit(EXIT_FAILURE);
    }
    if (sb.st_size == 0) {
        if (chmod(LOG_FILE, 0644) == -1) {
            perror("Error setting file permissions");
            close(fd);
            exit(EXIT_FAILURE);
        }
    }
    close(fd);
}

void log_rain_level(int level) {
    char timestamp[20];
    time_t now = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file for writing");
        return;
    }
    fprintf(fp, "%s: Rain level: %d\n", timestamp, level);
    fclose(fp);
}

void drive_motor(bool forward) {
    if (forward) {
        gpiod_output_t ch;
        gpiod_channel_t ch_id;
        gpiod_arg_init(&ch, MOTOR_EN_PIN);
        gpiod_arg_add_edge(&ch, GPIOD_OUTPUT_ACTIVE_HIGH);
        gpiod_channel_add(&ch, &ch_id);
        gpiod_channel_value_set(&ch, 1);
        gpiod_output_enable(&ch);
        gpiod_output_t ch_reverse = ch;
        gpiod_channel_t ch_id_reverse;
        gpiod_arg_init(&ch_reverse, MOTOR_REVERSE_PIN);
        gpiod_arg_add_edge(&ch_reverse, GPIOD_OUTPUT_ACTIVE_HIGH);
        gpiod_channel_add(&ch_reverse, &ch_id_reverse);
        gpiod_channel_value_set(&ch_reverse, 0);
        gpiod_output_enable(&ch_reverse);
        if (forward) {
            gpiod_pwm_t pwm_ch;
            gpiod_arg_init(&pwm_ch, MOTOR_FORWARD_PIN);
            gpiod_arg_add_edge(&pwm_ch, GPIOD_OUTPUT_PWM);
            gpiod_channel_add(&pwm_ch, &ch_id);
            gpiod_pwm_config_t pwm_config = {
                .duty_cycle = 150,
                .period_cycles = 255,
                .clock_source = GPIOD_CLOCK_SPI,
                .clock_divisor = 1,
                .output_edge_detect = GPIOD_EDGE_FALLING
            };
            gpiod_pwm_init(&pwm_ch, &pwm_config);
            gpiod_pwm_start(&pwm_ch);
        } else {
            gpiod_pwm_stop(&ch_reverse);
        }
    } else {
        gpiod_output_t ch;
        gpiod_channel_t ch_id;
        gpiod_arg_init(&ch, MOTOR_EN_PIN);
        gpiod_arg_add_edge(&ch, GPIOD_OUTPUT_ACTIVE_HIGH);
        gpiod_channel_add(&ch, &ch_id);
        gpiod_channel_value_set(&ch, 0);
        gpiod_output_enable(&ch);
        if (!forward) {
            gpiod_pwm_t pwm_ch;
            gpiod_arg_init(&pwm_ch, MOTOR_REVERSE_PIN);
            gpiod_arg_add_edge(&pwm_ch, GPIOD_OUTPUT_PWM);
            gpiod_channel_add(&pwm_ch, &ch_id);
            gpiod_pwm_config_t pwm_config = {
                .duty_cycle = 150,
                .period_cycles = 255,
                .clock_source = GPIOD_CLOCK_SPI,
                .clock_divisor = 1,
                .output_edge_detect = GPIOD_EDGE_FALLING
            };
            gpiod_pwm_init(&pwm_ch, &pwm_config);
            gpiod_pwm_start(&pwm_ch);
        }
    }
}

int main() {
    setup_log_file();

    struct mcp3008_context ctx;
    mcp3008_init(&ctx, SPI_CHANNEL, SPI_FREQ_HZ, SPI_MODE);
    if (!ctx.is_ok()) {
        fprintf(stderr, "Failed to initialize MCP3008\n");
        return EXIT_FAILURE;
    }

    L298N_Config config = {
        .IN1 = MOTOR_FORWARD_PIN,
        .IN2 = MOTOR_REVERSE_PIN,
        .ENA = MOTOR_EN_PIN
    };
    if (l298n_init(&config) != L298N_SUCCESS) {
        fprintf(stderr, "Failed to initialize L298N motor driver\n");
        return EXIT_FAILURE;
    }

    drive_motor(true);

    while (!stop_loop) {
        int level = mcp3008_read_channel(&ctx, RAIN_SENSOR_PIN);
        log_rain_level(level);

        if (level > RAIN_THRESHOLD) {
            drive_motor(true);
            usleep(3000000); // 3 seconds
        } else {
            drive_motor(false);
        }

        usleep(LOG_INTERVAL_S * 1000000); // 1 second delay
    }

    l298n_deinit();
    mcp3008_deinit(&ctx);
    fclose(stdout);
    close(STDOUT_FILENO);
    close(STDIN_FILENO);
    close(STDERR_FILENO);
    gpiod_disable_all_outputs();
    gpiod_disable_all_pdhs();
    gpiod_disable_all_pdhs_and_pdhs_edges();
    pthread_join(pthread_self(), NULL);

    return 0;
}

