#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_PIN 17
#define LOG_FILE "distance_log.txt"
#define DELAY_SEC 1

void sigint_handler(int signum) {
    gpiod_disable(GPIO_PIN);
    fprintf(stderr, "Received SIGINT, cleaning up GPIO17 and exiting.\n");
    exit(0);
}

void sigterm_handler(int signum) {
    gpiod_disable(GPIO_PIN);
    fprintf(stderr, "Received SIGTERM, cleaning up GPIO17 and exiting.\n");
    exit(0);
}

int main() {
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    int fd;
    char timestamp[20];
    struct tm tm;

    // Initialize libgpiod
    if (gpiod_init() != 0) {
        perror("Failed to initialize libgpiod");
        return EXIT_FAILURE;
    }

    // Enable GPIO17 as output
    if (gpiod_export_pin(GPIO_PIN) != 0) {
        perror("Failed to export GPIO17");
        return EXIT_FAILURE;
    }

    // Open the log file in append mode
    fd = open(LOG_FILE, O_APPEND | O_CREAT | O_WRONLY, 0644);
    if (fd == -1) {
        if (errno == EACCES) {
            perror("Failed to open log file, retrying in 1 second...");
            usleep(DELAY_SEC * 1000000);
            return main();
        } else {
            perror("Failed to open log file");
            return EXIT_FAILURE;
        }
    }

    // Read and log the sensor data
    while (1) {
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));

        int value = gpiod_get_value(GPIO_PIN);
        if (value == 0) {
            fprintf(fd, "%s", timestamp);
            fprintf(stderr, "Feeder Idle\n");
        } else {
            fprintf(fd, "%s", timestamp);
            fprintf(stderr, "Feeder Activated\n");
        }

        usleep(DELAY_SEC * 1000000);
    }

    // Clean up
    gpiod_disable(GPIO_PIN);
    close(fd);
    return EXIT_SUCCESS;
}

