#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <linux/spi/spidev.h>
#include <wiringPi.h>
#include <wiringPiSPI.h>

#define SPI_DEVICE 0
#define MCP3008_CS 9
#define PUMP_GPIO 17
#define LOG_FILE "soil_moisture.log"
#define SAMPLE_INTERVAL 60000  // 60 seconds in milliseconds
#define MOISTURE_THRESHOLD 500  // Adjust this value based on your sensor

int mcp3008_cs;
int mcp3008_fd;
int pump_state;

void init_spi();
void init_mcp3008();
void read_adc();
void log_sample(int adc_value, int timestamp);
void activate_pump();
void deactivate_pump();
void handle_sigint();

int main(int argc, char *argv[]) {
    int ret;
    struct spi_dev *spidev;
    int chip_select;

    wiringPiSetup();
    ret = wiringPiSPISetup(SPI_DEVICE, 0);
    if (ret < 0) {
        perror("SPI setup failed");
        exit(EXIT_FAILURE);
    }

    mcp3008_cs = wiringPiGPIO(MCP3008_CS);
    ret = wiringPiSPISetup(mcp3008_cs, 1);
    if (ret < 0) {
        perror("MCP3008 SPI setup failed");
        exit(EXIT_FAILURE);
    }

    init_mcp3008();

    while (1) {
        read_adc();
        activate_pump();
        usleep(SAMPLE_INTERVAL * 1000 / HRTIME_PER_SEC);
        deactivate_pump();
    }

    return 0;
}

void init_spi() {
    // SPI initialization is already handled in wiringPiSPISetup
}

void init_mcp3008() {
    // Initialize MCP3008 ADC
    ret = spi_begin(mcp3008_cs);
    if (ret < 0) {
        perror("MCP3008 SPI initialization failed");
        exit(EXIT_FAILURE);
    }
    ret = spi_set_bits_per_chip(3);
    if (ret < 0) {
        perror("MCP3008 bits per chip setup failed");
        exit(EXIT_FAILURE);
    }
    ret = spi_set_clock_speed(100000);  // Adjust clock speed as needed
    if (ret < 0) {
        perror("MCP3008 clock speed setup failed");
        exit(EXIT_FAILURE);
    }
}

void read_adc() {
    uint16_t adc_value;
    ret = spi_write_ctrl(mcp3008_cs, 0x01);  // Start conversion
    if (ret < 0) {
        perror("MCP3008 read control register failed");
        return;
    }
    while (spi_transfer(mcp3008_cs, 0x00, 1, &adc_value, 2) == 2);
    adc_value <<= 8;
    adc_value |= spi_read_ctrl(mcp3008_cs, 0x01);  // Read data
    if (ret < 0) {
        perror("MCP3008 read data failed");
        return;
    }

    if (adc_value < 1024) {
        printf("ADC reading failed: %d\n", adc_value);
        return;
    }

    int moisture_percentage = map_adc_to_moisture(adc_value);
    if (moisture_percentage < MOISTURE_THRESHOLD) {
        activate_pump();
        log_sample(adc_value, get_timestamp());
    } else {
        deactivate_pump();
    }
}

int map_adc_to_moisture(uint16_t adc_value) {
    // Map ADC value to moisture percentage (0-1023 to 0-100%)
    return (adc_value * 100) / 1023;
}

void activate_pump() {
    pump_state = 1;
}

void deactivate_pump() {
    pump_state = 0;
}

void log_sample(int adc_value, int timestamp) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }
    fprintf(log_file, "%d %d %s\n", get_timestamp(), adc_value, pump_state ? "ON" : "OFF");
    fclose(log_file);
}

void handle_sigint() {
    deactivate_pump();
    fclose(log_file);
    spi_close(mcp3008_cs);
    close(mcp3008_fd);
    remove(LOG_FILE);
    exit(0);
}

int get_timestamp() {
    time_t now = time(NULL);
    struct tm *local_time = localtime(&now);
    char buffer[80];
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", local_time);
    return atoi(buffer);
}

int main(int argc, char *argv[]) {
    // ... (previous code)

    signal(SIGINT, handle_sigint);

    // ... (rest of the main function)
}

