#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <stdbool.h>
#include <stdint.h>
#include <linux/spi/spidev.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>

#define SPI_DEV "/dev/spidev0.0"
#define SPI_SPEED 10000000
#define MCP3008_CHANNEL 0
#define B_MT_DECIMAL_PLACES 2
#define MAGNETIC_LOG_FILE "magnetic_log.txt"

#define GPIO_MCP3008_CS 8
#define GPIO_MCP3008_DIN 9
#define GPIO_MCP3008_DOUT 10
#define GPIO_DRV5055_VCC 3.3

#define ADC_READ_INTERVAL_MS 500

int main() {
    int fd_spi;
    struct spidev_ioctl_data spi_data;
    uint32_t config;

    fd_spi = open(SPI_DEV, O_RDWR);
    if (fd_spi < 0) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    spi_data.config = SPI_SPEED;
    spi_data.direction = SPI_DIR_OUTPUT | SPI_DIR_INPUT;
    spi_data.lclkhss = 0;

    if (ioctl(fd_spi, SPI_IOC_CONFIGURE, &spi_data) < 0) {
        perror("ioctl");
        exit(EXIT_FAILURE);
    }

    // Initialize GPIO lines
    if (gpio-setmode(GPIO_MCP3008_CS, GPIO_OUTPUT) < 0) {
        perror("gpio-setmode");
        exit(EXIT_FAILURE);
    }
    if (gpio-setmode(GPIO_MCP3008_DIN, GPIO_INPUT) < 0) {
        perror("gpio-setmode");
        exit(EXIT_FAILURE);
    }
    if (gpio-setmode(GPIO_MCP3008_DOUT, GPIO_OUTPUT) < 0) {
        perror("gpio-setmode");
        exit(EXIT_FAILURE);
    }

    // Initialize MCP3008
    if (gpio-output(GPIO_MCP3008_CS) < 0) {
        perror("gpio-output");
        exit(EXIT_FAILURE);
    }

    // Read sensor data
    while (true) {
        struct timespec start, end;
        double start_time = clock64();

        if (gpio-write(GPIO_MCP3008_CS, LOW) < 0) {
            perror("gpio-write");
            continue;
        }

        if (gpio-write(GPIO_MCP3008_DIN, 0) < 0) {
            perror("gpio-write");
            continue;
        }

        if (ioctl(fd_spi, SPI_IOC_MESSAGE, &spi_data) < 0) {
            perror("ioctl");
            continue;
        }

        spi_data.data[0] = 0x00;
        spi_data.data[1] = 0x01;
        spi_data.data[2] = 0x00;
        spi_data.data[3] = 0x00;

        if (ioctl(fd_spi, SPI_IOC_MESSAGE, &spi_data) < 0) {
            perror("ioctl");
            continue;
        }

        if (gpio-read(GPIO_MCP3008_DOUT) < 0) {
            perror("gpio-read");
            continue;
        }

        uint16_t raw_value = spi_data.data[4];
        uint8_t status = spi_data.data[5];

        if (status & 0x02) {
            // ADC conversion complete
            uint16_t converted_value = raw_value * 3.3 / 65535; // Convert to voltage
            printf("<%ld>,%f\n", (long)clock64(), converted_value);

            // Write converted value to magnetic_log.txt
            FILE *fp = fopen(MAGNETIC_LOG_FILE, "a");
            if (!fp) {
                perror("fopen");
                continue;
            }
            fprintf(fp, "%ld,%f\n", (long)clock64(), converted_value);
            fclose(fp);
        }

        gpio-low(GPIO_MCP3008_CS);
        delay(ADC_READ_INTERVAL_MS / 1000);
        gpio-high(GPIO_MCP3008_CS);
    }

    // Release GPIO lines
    if (gpio-setmode(GPIO_MCP3008_CS, GPIO_INPUT) < 0) {
        perror("gpio-setmode");
    }
    if (gpio-setmode(GPIO_MCP3008_DIN, GPIO_INPUT) < 0) {
        perror("gpio-setmode");
    }
    if (gpio-setmode(GPIO_MCP3008_DOUT, GPIO_INPUT) < 0) {
        perror("gpio-setmode");
    }

    // Close SPI file descriptor
    if (close(fd_spi) < 0) {
        perror("close");
    }

    // Close magnetic_log.txt
    if (fclose(stdout) < 0) {
        perror("fclose");
    }

    return 0;
}

