        exit(EXIT_FAILURE);
    }

    spi_control(spi_fd, SPI_SPEED);
}

void adc_init() {
    led_pin = GPIO21;
    gpio_request(led_pin, "led");
    if (gpio_request(led_pin, "led") < 0) {
        perror("Failed to request LED pin");
        exit(EXIT_FAILURE);
