    spi_write_byte(spi_fd, 0x00); // Set to 0x00 for channel 0
    spi_write_byte(spi_fd, 0x00); // Set to 0x00 for 4.096V reference
    spi_write_byte(spi_fd, 0x00); // Set to 0x00 for 100ms conversion time
    spi_write_byte(spi_fd, 0x00); // Set to 0x00 for single-shot mode
    spi_write_byte(spi_fd, 0x00); // Set to 0x00 for no auto-power-down
}

void adc_read() {
    uint16_t value;
    spi_control(spi_fd, SPI_SPEED);
    spi_write_byte(spi_fd, 0x00); // Start conversion
    while (spi_read(spi_fd) != 0x00); // Wait for conversion to complete

    spi_control(spi_fd, SPI_SPEED);
    value = spi_read(spi_fd) << 8 | spi_read(spi_fd);

    // Convert ADC value to magnetic field strength (assuming 4.096V reference)
    float magnetic_field_strength = (value * 4.096) / 3300.0;

