    if (write(GPIO_PIN, 1) == -1) {
        perror("Failed to set GPIO pin");
        exit(EXIT_FAILURE);
    }
}

void teardown_gpio() {
    if (write(GPIO_PIN, 0) == -1) {
        perror("Failed to reset GPIO pin");
    }
}

void setup_spi() {
    spi_fd = open(SPI_DEV, O_RDWR | O_NOCTTY | O_NDELAY);
    if (spi_fd == -1) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }
}

void teardown_spi() {
    close(spi_fd);
}

void log_current(float current) {
    char timestamp[32];
    time_t now = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        perror("Failed to open log file");
        return;
    }
    fprintf(file, "%s,%.3f\n", timestamp, current);
    fclose(file);
}

int main() {
    setup_gpio();
    setup_spi();

    while (1) {
        int adc_value = read(spi_fd, &current, 2);
        if (adc_value == -1) {
            perror("Failed to read from SPI device");
            log_current(0.0);
            continue;
        }

        float voltage = adc_value * 3.3 / 1024.0;
        float current_A = voltage / 100.0; // Assuming 100 mV/A

        log_current(current_A);

        usleep(SAMPLE_INTERVAL * 1000000 / 1000); // Convert microseconds to seconds
    }

    teardown_spi();
    teardown_gpio();

    return 0;
}

