#include <fcntl.h>
#include <errno.h>
#include <libgpiod.h>
#include <mcp3008.h>

#define SPI_CLOCK_FREQ 1000000
#define MCP3008_CE0 8
#define MCP3008_MOSI 10
#define MCP3008_MISO 9
#define MCP3008_SCLK 11
#define MLX91211_VDD 5
#define MLX91211_OUTPUT_PIN 0

#define LOG_FILE "current_log.txt"

