        return;
    }

    fprintf(fp, "%s XX.XXA\n", buffer);
    fclose(fp);
}

int main(int argc, char *argv[]) {
    spi_init();

    while (!quit) {
        double voltage = read_analog_input(MLX91211_OUTPUT_PIN);

        if (voltage < 0 || voltage > 5) {
            fprintf(stderr, "Voltage out of range, skipping sample\n");
            continue;
        }

        log_to_file(voltage);

        usleep(100000); // Wait for 100ms
    }

    mcp3008_deinit();
    fclose(log_file_fd);
    close(log_file_fd);

    return 0;
}

