#define MCP3008_MOSI 10
#define MCP3008_MISO 9
#define MCP3008_SCLK 11
#define MLX91211_VDD 5
#define MLX91211_OUTPUT_PIN 0

#define LOG_FILE "current_log.txt"

int log_file_fd;
volatile int quit = 0;

void spi_init() {
    int ret;

    ret = mcp3008_init(MCP3008_CE0);
    if (ret < 0) {
        fprintf(stderr, "Failed to initialize MCP3008\n");
        exit(EXIT_FAILURE);
    }

    ret = mcp3008_set_clock_freq(SPI_CLOCK_FREQ, MCP3008_MODE0);
    if (ret < 0) {
        fprintf(stderr, "Failed to set SPI clock frequency\n");
        mcp3008_deinit();
        exit(EXIT_FAILURE);
    }
}

double read_analog_input(int channel) {
    int ret;
    mcp3008_channel_t channel_num;

    channel_num = (mcp3008_get_channel_by_num(channel));
    if (channel_num < 0) {
        fprintf(stderr, "Invalid channel number\n");
        return -1.0;
    }

    ret = mcp3008_read_adc(channel_num);
    if (ret < 0) {
        fprintf(stderr, "SPI transfer error\n");
        return -1.0;
    }

    return ret / 1024.0; // Convert to voltage
}

void log_to_file(double current) {
    time_t rawtime;
    struct tm * timeinfo;
    char buffer[80];

    time ( &rawtime );
    timeinfo = localtime ( &rawtime );

    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);

    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open file for writing\n");
        return;
    }

    fprintf(fp, "%s XX.XXA\n", buffer);
    fclose(fp);
}

int main(int argc, char *argv[]) {
    spi_init();

