#define SENSOR1_GPIO 4
#define SENSOR2_GPIO 17
#define DEBOUNCE_INTERVAL_MS 2000
#define LOG_INTERVAL_S 1

bool sensor_states[2] = {false, false};
int sensor_count = 0;

void debounce_handler(const struct gpiod_device *device, gpiod_value_t *value, void *user_data) {
    static int debounced_count = 0;
    static bool first_debounce = true;

    if (user_data) {
        if (debounced_count >= 5) {
            sensor_states[device->gpio_num - 1] = !value[0];
            debounced_count = 0;
        } else if (!first_debounce) {
            sensor_states[device->gpio_num - 1] = *value;
            debounced_count++;
            first_debounce = true;
        }
    }
}

void signal_handler(int signum) {
    if (signum == SIGINT) {
        for (int i = SENSOR1_GPIO; i <= SENSOR2_GPIO; i++) {
            gpiod_pin_get_direction(gp, i, &direction);
            gpiod_pin_free_output(gp, i);
        }
        exit(EXIT_SUCCESS);
    }
}

int main() {
    gp = gpiod_get_default_pool();
    if (!gp) {
        fprintf(stderr, "Failed to get gpiod default pool\n");
        exit(EXIT_FAILURE);
    }

    if (gpiod_setup(gp, NULL, NULL) < 0) {
        fprintf(stderr, "Failed to set up gpiod\n");
        exit(EXIT_FAILURE);
    }

    gpiod_pin_configure_input(gp, SENSOR1_GPIO, GPIOD_OUTPUT_ACTIVE_LOW);
    gpiod_pin_configure_input(gp, SENSOR2_GPIO, GPIOD_OUTPUT_ACTIVE_LOW);

    gpiod_pin_add_event_source(gp, SENSOR1_GPIO, DEBOUNCE_HANDLER, NULL, NULL);
    gpiod_pin_add_event_source(gp, SENSOR2_GPIO, DEBOUNCE_HANDLER, NULL, NULL);

    gpiod_device_enable(gp, SENSOR1_GPIO);
    gpiod_device_enable(gp, SENSOR2_GPIO);

    signal(SIGINT, signal_handler);

    while (1) {
        bool sensor1_state = sensor_states[0];
        bool sensor2_state = sensor_states[1];

        if (sensor1_state && sensor2_state) {
            printf("ALERT: Both sensors detect object\n");
        }

        if (sensor1_state) {
            sensor_states[0] = true;
        } else {
            sensor_states[0] = false;
        }

        if (sensor2_state) {
            sensor_states[1] = true;
        } else {
            sensor_states[1] = false;
        }

        if (sensor_count > 0 && sensor_states[0] != sensor_states[1]) {
            printf("0\n");
            sensor_count = 0;
        } else {
            printf("1\n");
            sensor_count++;
            if (sensor_count == LOG_INTERVAL_S) {
                sensor_count = 0;
            }
        }

        usleep(DEBOUNCE_INTERVAL_MS / 1000);
    }

    return 0;
}

