#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include "driver_library.h"

#define SPI_CHANNEL(0)
#define SPI_BAUD(1000000)
#define MCP3008_CHANNEL(0)
#define READ_DELAY(60)
#define MIN_ADC(300)
#define MAX_ADC(800)
#define LOG_FILE("soil_moisture_log.csv")

volatile sig_atomic_t sig_int_flag = 0;

void signal_handler(int signal) {
    sig_int_flag = 1;
}

void spi_setup(spi_config_t *config) {
    // Initialize SPI
    if (spi_init(config) != 0) {
        perror("SPI initialization failed");
        exit(EXIT_FAILURE);
    }
}

int read_mcp3008(int channel) {
    // Read from MCP3008 ADC
    uint16_t adc_value;
    if (spi_transfer(channel, &adc_value, 1, READ_DELAY) != 0) {
        perror("SPI transfer failed");
        return -1;
    }
    return adc_value;
}

double calculate_moisture_level(int adc_value) {
    // Convert ADC value to moisture percentage
    double moisture_percentage = (double)(adc_value - MIN_ADC) / (MAX_ADC - MIN_ADC) * 100;
    return moisture_percentage;
}

void log_data(double moisture_level) {
    // Log data to file
    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        perror("Failed to open log file");
        return;
    }
    time_t now = time(NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    fprintf(file, "%s, %.2f\n", timestamp, moisture_level);
    fclose(file);
    printf("%s, %.2f\n", timestamp, moisture_level);
}

int main() {
    spi_config_t config = {
        .mode = SPI_MODE0,
        .data_bits = 8,
        .clock_polarity = SPI_POLARITY_0,
        .clock_phase = SPI_PHASE_0,
        .nSS = false,
        .max_speed_hz = SPI_BAUD / 1000000
    };

    spi_setup(&config);

    while (!sig_int_flag) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value == -1) {
            continue;
        }
        double moisture_level = calculate_moisture_level(adc_value);
        log_data(moisture_level);
        usleep(READ_DELAY * 1000000); // Delay for 60 seconds
    }

    spi_deinit();
    return 0;
}

// Signal handler for SIGINT
signal(SIGINT, signal_handler);

