#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <syslog.h>
#include <libpigpio.h>
#include <time.h>

#define PIR_PIN 17
#define POLL_INTERVAL_MS 50
#define DEBOUNCE_MS 200
#define CAPTURE_DIR "/home/pi/security_cam"

void pir_callback(int state) {
    static int motion_detected = 0;
    if (state == PI_INPUT) {
        motion_detected = 1;
        if (motion_detected) {
            // Apply debounce
            usleep(DEBOUNCE_MS);
            // Re-read to confirm motion
            if (state == PI_INPUT) {
                motion_detected = 1;
            }
        }
    } else {
        motion_detected = 0;
    }
}

int main() {
    int pir_pin = PIR_PIN;
    gpioInitialise();

    if (gpioGetMode(pir_pin) != PI_INPUT) {
        syslog(LOG_ERR, "Failed to set GPIO%d as input", pir_pin);
        return 1;
    }

    gpioSetPullUp(pir_pin);

    gpioSetChangeCallback(pir_pin, pir_callback);

    while (1) {
        sleep(1); // Poll every 50ms
        if (motion_detected) {
            // Construct output path
            char timestamp[32];
            time_t now = time(NULL);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));
            char output_path[256];
            snprintf(output_path, sizeof(output_path), CAPTURE_DIR "/motion_%s.jpg", timestamp);

            // Ensure capture directory exists
            if (!access(output_path, F_OK)) {
                // Capture image using libcamera-still
                char cmd[256];
                snprintf(cmd, sizeof(cmd), "lccapture --format jpeg --filename %s", output_path);
                int status = fork();
                if (status == 0) {
                    // Child process
                    if (system(cmd) != 0) {
                        syslog(LOG_ERR, "Failed to capture image: %s", cmd);
                    } else {
                        syslog(LOG_INFO, "Image captured successfully: %s", output_path);
                    }
                    exit(0);
                } else {
                    // Parent process
                    if (wait(NULL) != 0) {
                        syslog(LOG_ERR, "Child process failed to capture image");
                    }
                }
            } else {
                syslog(LOG_INFO, "Capture directory does not exist, skipping.");
            }
        }
        motion_detected = 0;
    }

    gpioDisable(pir_pin);
    gpioDeinitialise();

    syslog(LOG_INFO, "Program exiting cleanly.");
    return 0;
}

