#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/select.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <errno.h>

#define BUFFER_SIZE 1024 * 1024 // 1MB buffer
#define FRAME_LOG_FILE "frame_log.txt"

int main(int argc, char *argv[]) {
    int video_fd, ret;
    struct timeval tv;
    struct ftime ft;
    char *log_file = FRAME_LOG_FILE;
    FILE *log_fp = fopen(log_file, "a");
    if (!log_fp) {
        perror("fopen");
        return EXIT_FAILURE;
    }

    video_fd = open("/dev/video0", O_RDWR | O_NONBLOCK);
    if (video_fd == -1) {
        perror("open");
        return EXIT_FAILURE;
    }

    ret = ioctl(video_fd, VIDIOC_QUERYSTREAMPARAM, &ft);
    if (ret < 0) {
        perror("ioctl VIDIOC_QUERYSTREAMPARAM");
        close(video_fd);
        return EXIT_FAILURE;
    }

    while (1) {
        memset(&tv, 0, sizeof(tv));
        fd_set readfds;
        FD_ZERO(&readfds);
        FD_SET(video_fd, &readfds);

        select(video_fd + 1, &readfds, NULL, NULL, &tv);

        if (FD_ISSET(video_fd, &readfds)) {
            ret = read(video_fd, &ft, sizeof(ft));
            if (ret < 0) {
                perror("read");
                break;
            }

            if (ret == 0) {
                // No data available, continue checking
                continue;
            }

            // Map the buffer
            void *map_buf = mmap(NULL, BUFFER_SIZE, PROT_READ | PROT_WRITE, MAP_SHARED, video_fd, 0);
            if (map_buf == MAP_FAILED) {
                perror("mmap");
                close(video_fd);
                return EXIT_FAILURE;
            }

            // Copy the frame data
            memcpy(map_buf, &ft, sizeof(ft));

            // Timestamp the frame
            time_t timestamp = time(NULL);
            struct tm *tm = localtime(&timestamp);
            char timestamp_str[32];
            sprintf(timestamp_str, "%ld.%06ld", (long)timestamp / 1000000, (long)microsecond_time(NULL));

            // Write to log file
            fprintf(log_fp, "%s\n", timestamp_str);

            // Unmap the buffer
            munmap(map_buf, BUFFER_SIZE);
        }
    }

    // Clean up and exit
    munmap(map_buf, BUFFER_SIZE);
    close(log_fp);
    close(video_fd);

    return EXIT_SUCCESS;
}

