#include <fcntl.h>
#include <sys/mman.h>
#include <sys/socket.h>
#include <netinet/ip.h>
#include <arpa/inet.h>
#include <errno.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <linux/videodev2.h>
#include <linux/input-dev.h>
#include <pigpio.h>

#define BUFFER_SIZE 1024
#define FRAGMENT_SIZE 65000
#define NUM_FRAMES 4

#define TARGET_IP "127.0.0.1"
#define TARGET_PORT 5000

int main(int argc, char *argv[]) {
    int video_fd, ret;
    struct v4l2_compat v4l2_compat_version = { 2, 0 };
    struct v4l2_format fmt;
    struct v4l2_pixfmt pixfmt;
    struct iphdr *iphdr;
    struct tcphdr *tcphdr;
    uint8_t *frame_buffer;
    int frame_index, fragment_index, total_fragments;
    int socket_fd;
    char ip_str[INET_ADDRSTRLEN];

    if (argc != 2) {
        fprintf(stderr, "Usage: %s ioctl\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    video_fd = open("/dev/video0", O_RDWR);
    if (video_fd < 0) {
        perror("open /dev/video0");
        exit(EXIT_FAILURE);
    }

    ret = ioctl(video_fd, VIDIOC_QUERYFORMAT(video_fd), &fmt);
    if (ret < 0) {
        perror("ioctl VIDIOC_QUERYFORMAT");
        close(video_fd);
        exit(EXIT_FAILURE);
    }

    pixfmt.format = fmt.format;
    pixfmt.pixeltype = fmt.pixeltype;
    pixfmt.width = fmt.width;
    pixfmt.height = fmt.height;
    pixfmt.field = fmt.field;
    pixfmt.pix_clks = fmt.pix_clks;
    pixfmt.fb_size = fmt.fb_size;

    frame_buffer = mmap(NULL, BUFFER_SIZE, PROT_READ | PROT_WRITE, MAP_SHARED, video_fd, 0);
    if (frame_buffer == MAP_FAILED) {
        perror("mmap");
        close(video_fd);
        exit(EXIT_FAILURE);
    }

    total_fragments = 0;
    for (frame_index = 0; frame_index < NUM_FRAMES; frame_index++) {
        ret = ioctl(video_fd, VIDIOC_STREAMON(video_fd, VIDIOC_DQ_FRAME), &fmt);
        if (ret < 0) {
            perror("ioctl VIDIOC_STREAMON");
            munmap(frame_buffer, BUFFER_SIZE);
            close(video_fd);
            exit(EXIT_FAILURE);
        }

        ret = ioctl(video_fd, VIDIOC_DQFRAME(video_fd), frame_buffer);
        if (ret < 0) {
            perror("ioctl VIDIOC_DQFRAME");
            munmap(frame_buffer, BUFFER_SIZE);
            close(video_fd);
            exit(EXIT_FAILURE);
        }

        total_fragments++;

        // Fragment the frame
        uint8_t *fragment = frame_buffer;
        for (fragment_index = 0; fragment_index < 4; fragment_index++) {
            uint8_t *start = fragment;
            size_t size = FRAGMENT_SIZE;
            memcpy(fragment, start, size);
            fragment += size;
            if (fragment < start) {
                // Handle fragment wraparound
                fragment = start;
            }
        }

        // Prepare UDP datagram
        iphdr = (struct iphdr *)malloc(sizeof(struct iphdr) + sizeof(struct tcphdr));
        tcphdr = (struct tcphdr *)malloc(sizeof(struct tcphdr));
        iphdr->version = 4;
        iphdr->ihl = 5;
        iphdr->tos = 0;
        iphdr->tot_len = sizeof(struct iphdr) + sizeof(struct tcphdr) + 20; // 20 for header + payload
        iphdr->id = htons(ntohs(total_fragments));
        iphdr->frag_off = 0;
        iphdr->ttl = 64;
        iphdr->protocol = IPPROTO_UDP;
        iphdr->check = 0;
        iphdr->saddr = INADDR_ANY;
        iphdr->daddr = inet_addr(TARGET_IP);

        tcphdr->source = htons(ntohs(0));
        tcphdr->dest = htons(ntohs(TARGET_PORT));
        tcphdr->seq = ntohs(total_fragments);
        tcphdr->ack_seq = 0;
        tcphdr->data_offset = 8;
        tcphdr->flags = 0;
        tcphdr->window = 65535;
        tcphdr->check = 0;

        // Prefix header with frame index, fragment index, total fragments, and payload size
        uint16_t header_size = sizeof(struct iphdr) + sizeof(struct tcphdr) + 20;
        uint16_t payload_size = FRAGMENT_SIZE;
        uint16_t total_fragments_header = ntohs(total_fragments);
        uint16_t fragment_index_header = ntohs(fragment_index);

        memcpy(iphdr->payload, &header_size, 2);
        memcpy(iphdr->payload + 2, &total_fragments_header, 2);
        memcpy(iphdr->payload + 4, &fragment_index_header, 2);
        memcpy(iphdr->payload + 6, &payload_size, 2);

        socket_fd = socket(AF_INET, SOCK_DGRAM, 0);
        if (socket_fd < 0) {
            perror("socket");
            free(iphdr);
            free(tcphdr);
            munmap(frame_buffer, BUFFER_SIZE);
            close(video_fd);
            exit(EXIT_FAILURE);
        }

        ret = sendto(socket_fd, iphdr, header_size, 0, (struct sockaddr *)&iphdr->saddr, sizeof(iphdr->saddr));
        if (ret < 0) {
            perror("sendto");
            free(iphdr);
            free(tcphdr);
            munmap(frame_buffer, BUFFER_SIZE);
            close(socket_fd);
            close(video_fd);
            exit(EXIT_FAILURE);
        }

        ret = sendto(socket_fd, tcphdr, sizeof(struct tcphdr), 0, (struct sockaddr *)&iphdr->saddr, sizeof(iphdr->saddr));
        if (ret < 0) {
            perror("sendto");
            free(iphdr);
            free(tcphdr);
            munmap(frame_buffer, BUFFER_SIZE);
            close(socket_fd);
            close(video_fd);
            exit(EXIT_FAILURE);
        }

        ret = sendto(socket_fd, fragment, FRAGMENT_SIZE, 0, (struct sockaddr *)&iphdr->saddr, sizeof(iphdr->saddr));
        if (ret < 0) {
            perror("sendto");
            free(iphdr);
            free(tcphdr);
            munmap(frame_buffer, BUFFER_SIZE);
            close(socket_fd);
            close(video_fd);
            exit(EXIT_FAILURE);
        }

        free(iphdr);
        free(tcphdr);
    }

    munmap(frame_buffer, BUFFER_SIZE);
    close(video_fd);

    return 0;
}

