#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod/gpio.h>

#define PAN_GPIO 4
#define TILT_GPIO 5
#define TILT_UP_GPIO 6
#define TILT_DOWN_GPIO 7
#define PAN_LEFT_GPIO 8
#define PAN_RIGHT_GPIO 9

#define PWM_PERIOD_MS 20
#define PWM_FREQ_HZ 50
#define PWM_MAX_DUTY 100
#define PWM_MIN_DUTY 50
#define PWM_DUTY_RANGE 100
#define BUTTON_POLL_MS 50

int pan_gpio, tilt_gpio, tilt_up_gpio, tilt_down_gpio, pan_left_gpio, pan_right_gpio;

void button_handler(int gpio) {
    int button_state = gdbit(&pan_gpio) || gdbit(&tilt_gpio) || gdbit(&tilt_up_gpio) || gdbit(&tilt_down_gpio) || gdbit(&pan_left_gpio) || gdbit(&pan_right_gpio);
    if (button_state) {
        int axis = gpio % 2 == 0 ? TILT_GPIO : PAN_GPIO;
        int direction = gpio / 2 == 0 ? -1 : 1;
        int new_position = (axis == TILT_GPIO) ? 25 + (direction * 5) : 25 + (direction * 5);
        new_position = constrain(new_position, 25, 125);
        gpiowrite(axis, new_position & 0xFF);
    }
}

void setup_pwm(void) {
    int error;
    pan_gpio = gpio_request(PAN_GPIO, "pan_pwm");
    tilt_gpio = gpio_request(TILT_GPIO, "tilt_pwm");
    tilt_up_gpio = gpio_request(TILT_UP_GPIO, "tilt_up_pwm");
    tilt_down_gpio = gpio_request(TILT_DOWN_GPIO, "tilt_down_pwm");
    pan_left_gpio = gpio_request(PAN_LEFT_GPIO, "pan_left_pwm");
    pan_right_gpio = gpio_request(PAN_RIGHT_GPIO, "pan_right_pwm");

    if (pan_gpio < 0 || tilt_gpio < 0 || tilt_up_gpio < 0 || tilt_down_gpio < 0 || pan_left_gpio < 0 || pan_right_gpio < 0) {
        perror("Failed to request GPIO pins");
        exit(EXIT_FAILURE);
    }

    gpio_direction_output_fast(pan_gpio);
    gpio_direction_output_fast(tilt_gpio);
    gpio_direction_output_fast(tilt_up_gpio);
    gpio_direction_output_fast(tilt_down_gpio);
    gpio_direction_output_fast(pan_left_gpio);
    gpio_direction_output_fast(pan_right_gpio);

    error = libgpiod_pwm_output_configure(pan_gpio, 0, PWM_FREQ_HZ, PWM_PERIOD_MS * 1000 / PWM_FREQ_HZ, 0, PWM_MAX_DUTY, PWM_MIN_DUTY);
    if (error) {
        perror("Failed to configure PWM on pan_gpio");
        exit(EXIT_FAILURE);
    }

    error = libgpiod_pwm_output_configure(tilt_gpio, 0, PWM_FREQ_HZ, PWM_PERIOD_MS * 1000 / PWM_FREQ_HZ, 0, PWM_MAX_DUTY, PWM_MIN_DUTY);
    if (error) {
        perror("Failed to configure PWM on tilt_gpio");
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, button_handler);
}

int main(int argc, char *argv[]) {
    setup_pwm();

    while (1) {
        usleep(BUTTON_POLL_MS * 1000 / HRTIME_PER_MS);
        for (int i = TILT_UP_GPIO; i <= PAN_RIGHT_GPIO; i += 2) {
            button_handler(i);
        }
    }

    return 0;
}

