        fprintf(stderr, "Usage: %s <image_name>\n", argv[0]);
        exit(1);
    }

    // Initialize pigpio
    if (piGPIO_init() < 0) {
        perror("Failed to initialize pigpio");
        exit(1);
    }

    // Open USB camera
    fd = open(argv[1], O_RDWR | O_SYNC);
    if (fd < 0) {
        perror("Failed to open camera");
        exit(1);
    }

