    mode.flags = V4L2_FMT_YUYV;
    if (ioctl(fd, VIDCQFMT, &mode) < 0) {
        perror("Failed to set camera mode");
        exit(1);
    }

    // Request buffers and memory-map them
    yuv_buffer = mmap(NULL, BUFFER_SIZE, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (yuv_buffer == MAP_FAILED) {
        perror("Failed to memory-map yuv buffer");
        exit(1);
    }

    rgb_buffer = (unsigned char *)yuv_buffer;

    // Queue a buffer for capture
    fmt.format = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.format << V4L2_BUF_TYPE_VIDEO_STREAM_BITSTREAM;
    fmt.pix_fmt = V4L2_PIX_FMT_YUYV;
    fmt.width = 640;
    fmt.height = 480;
    fmt.field = V4L2_FIELD_INTERLACE_NONE;
    fmt.pixel_aspect_ratio = 1;
    fmt.display_matrix = V4L2_DISPLAY_MATRIX_DEFAULT;
    fmt.transfer_mode = V4L2_TRANSFER_MODE_YUYV;
    fmt.flags = V4L2_BUF_TYPE_VIDEO_CAPTURE | V4L2_BUF_TYPE_VIDEO_STREAMING;

    struct v4l2_requestbuffers reqbuf;
    reqbuf.count = 1;
    reqbuf.type = fmt.format;
    reqbuf.memory = V4L2_MEMORY_USERPTR;
    reqbuf.index = 0;
    reqbuf.buf = yuv_buffer;
    reqbuf.bytes = BUFFER_SIZE;

    if (ioctl(fd, VIDCQREQUESTBUFFERS, &reqbuf) < 0) {
        perror("Failed to request capture buffer");
        exit(1);
    }

    // Start streaming
    ret = ioctl(fd, VIDCQSTART, (void *)fmt);
    if (ret < 0) {
        perror("Failed to start streaming");
        exit(1);
    }

    // Wait for a frame with select()
    fd_set readfds;
    FD_ZERO(&readfds);
    FD_SET(fd, &readfds);
    tv.tv_sec = 2;
    tv.tv_usec = 0;

    while (1) {
        ret = select(fd + 1, &readfds, NULL, NULL, &tv);
        if (ret == -1) {
            perror("select() error");
            break;
        }

        if (FD_ISSET(fd, &readfds)) {
            // Dequeue the captured frame
            ret = ioctl(fd, VIDCQDEQUEUEFRAME, (void *)buffer);
            if (ret < 0) {
                perror("Failed to dequeue frame");
                break;
            }

            // Convert YUYV to RGB24
            for (int i = 0; i < BUFFER_SIZE / 2; i += 2) {
                unsigned char y = buffer[i];
                unsigned char u = buffer[i + 1];
                unsigned char v = buffer[i + 3];

                // Convert YUYV to RGB24 (simplified conversion)
