                rgb_buffer[i] = (y << 16) | (v << 8) | u;
            }

            // Apply blur filter (simplified placeholder)
            // This would involve a convolution kernel and multiple iterations
            for (int i = 0; i < BUFFER_SIZE / 2; i += 2) {
                // Apply blur filter logic here
            }

            // Encode as JPEG
            jpeg_fd = open(argv[1], O_WRONLY | O_SYNC);
            if (jpeg_fd < 0) {
                perror("Failed to open JPEG file");
                exit(1);
            }

            struct jpeg_progressive_quality pq;
            pq.quality = JPEG_QUALITY;

            // Write JPEG data
            if (jpeg_write_start(jpeg_fd, &pq, buffer, BUFFER_SIZE) < 0) {
                perror("Failed to write JPEG data");
                exit(1);
            }

            // Close JPEG file
            jpeg_write_end(jpeg_fd);
            jpeg_destroy(jpeg_fd);
            close(jpeg_fd);

            // Clean up
            free(yuv_buffer);
            yuv_buffer = NULL;
            break;
        }
    }

    // Stop streaming
    ioctl(fd, VIDCQSTOP, (void *)fmt);
    if (ioctl(fd, VIDCQRELEASEBUFFERS, &reqbuf) < 0) {
        perror("Failed to release capture buffer");
        exit(1);
    }

    // Unmap memory
    munmap(yuv_buffer, BUFFER_SIZE);

    // Close file descriptor
    close(fd);

    // Terminate pigpio
    piGPIO_terminate();

    return 0;
