        perror("Failed to query device capabilities");
        close(fd);
        exit(EXIT_FAILURE);
    }

    printf("Supported resolutions:\n");
    for (int i = 0; i < cap.num_formats; i++) {
        if (cap.formats[i].pix_format & V4L2_PIX_FMT_YUYV) {
            printf("YUYV - %dx%d\n", cap.formats[i].width, cap.formats[i].height);
        }
    }

    if (cap.formats[0].pix_format & V4L2_PIX_FMT_MJPG) {
        printf("MJPG - %dx%d\n", cap.formats[0].width, cap.formats[0].height);
    }

    printf("\nSupported frame rates:\n");
    for (int i = 0; i < cap.num_formats; i++) {
        if (cap.formats[i].frame_rate & V4L2_FRAME_RATE_INTERLACE_PROGRESSIVE) {
            printf("Progressive - %d fps\n", cap.formats[i].frame_rate);
        }
    }

    if (cap.formats[0].frame_rate & V4L2_FRAME_RATE_INTERLACE_PROGRESSIVE) {
        printf("Progressive - %d fps\n", cap.formats[0].frame_rate);
    }

    printf("\nAutofocus capability:\n");
    if (ioctl(fd, VIDIOC_QUERYCTRL, &ctrl) < 0) {
        perror("Failed to query focus control");
        close(fd);
        exit(EXIT_FAILURE);
    }

    if (ctrl.id == V4L2_CID_FOCUS_AUTO) {
        printf("Autofocus is supported.\n");
    } else {
        printf("Autofocus is not supported.\n");
    }

    close(fd);
    return EXIT_SUCCESS;
}

