#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod/gpio.h>

#define PAN_GPIO 4
#define TILT_GPIO 5
#define UP_BUTTON 6
#define DOWN_BUTTON 7
#define LEFT_BUTTON 8
#define RIGHT_BUTTON 9

#define PWM_FREQUENCY 50
#define PWM_PERIOD_US 20000
#define PWM_IN_US_PER_PERIOD 1000
#define CENTER_POSITION 1500

void handle_button_press(int gpio) {
    if (gpio == UP_BUTTON) {
        tilt_pwm_set_pulsewidth(TILT_GPIO, CENTER_POSITION - 500);
    } else if (gpio == DOWN_BUTTON) {
        tilt_pwm_set_pulsewidth(TILT_GPIO, CENTER_POSITION + 500);
    } else if (gpio == LEFT_BUTTON) {
        pan_pwm_set_pulsewidth(PAN_GPIO, CENTER_POSITION - 500);
    } else if (gpio == RIGHT_BUTTON) {
        pan_pwm_set_pulsewidth(PAN_GPIO, CENTER_POSITION + 500);
    }
}

void signal_handler(int signum) {
    tilt_pwm_set_pulsewidth(TILT_GPIO, 0);
    pan_pwm_set_pulsewidth(PAN_GPIO, 0);
    libgpiod_cleanup();
    exit(0);
}

int main() {
    int ret;

    // Initialize libgpiod
    ret = libgpiod_init(NULL);
    if (ret < 0) {
        fprintf(stderr, "Failed to initialize libgpiod\n");
        exit(EXIT_FAILURE);
    }

    printf("Camera Pan-Tilt Mount Control\n");
    printf("Pan servo connected to GPIO%d (BCM %d)\n", PAN_GPIO, PAN_GPIO);
    printf("Tilt servo connected to GPIO%d (BCM %d)\n", TILT_GPIO, TILT_GPIO);
    printf("UP button: GPIO%d (BCM %d)\n", UP_BUTTON, UP_BUTTON);
    printf("DOWN button: GPIO%d (BCM %d)\n", DOWN_BUTTON, DOWN_BUTTON);
    printf("LEFT button: GPIO%d (BCM %d)\n", LEFT_BUTTON, LEFT_BUTTON);
    printf("RIGHT button: GPIO%d (BCM %d)\n", RIGHT_BUTTON, RIGHT_BUTTON);
    printf("Center position: %d µs\n", CENTER_POSITION);

    // Initialize GPIO pins
    ret = gpio_request(PAN_GPIO, "pan_servo");
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO%d for pan servo\n", PAN_GPIO);
        libgpiod_cleanup();
        exit(EXIT_FAILURE);
    }
    gpio_direction_output_fast(PAN_GPIO);

    ret = gpio_request(TILT_GPIO, "tilt_servo");
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO%d for tilt servo\n", TILT_GPIO);
        libgpiod_cleanup();
        exit(EXIT_FAILURE);
    }
    gpio_direction_output_fast(TILT_GPIO);

    ret = gpio_request(UP_BUTTON, "up_button");
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO%d for up button\n", UP_BUTTON);
        libgpiod_cleanup();
        exit(EXIT_FAILURE);
    }
    gpio_set_direction(UP_BUTTON, GPIO_OUTPUT);

    ret = gpio_request(DOWN_BUTTON, "down_button");
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO%d for down button\n", DOWN_BUTTON);
        libgpiod_cleanup();
        exit(EXIT_FAILURE);
    }
    gpio_set_direction(DOWN_BUTTON, GPIO_OUTPUT);

    ret = gpio_request(LEFT_BUTTON, "left_button");
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO%d for left button\n", LEFT_BUTTON);
        libgpiod_cleanup();
        exit(EXIT_FAILURE);
    }
    gpio_set_direction(LEFT_BUTTON, GPIO_OUTPUT);

    ret = gpio_request(RIGHT_BUTTON, "right_button");
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO%d for right button\n", RIGHT_BUTTON);
        libgpiod_cleanup();
        exit(EXIT_FAILURE);
    }
    gpio_set_direction(RIGHT_BUTTON, GPIO_OUTPUT);

    // Set initial PWM values
    tilt_pwm_set_pulsewidth(TILT_GPIO, CENTER_POSITION);
    pan_pwm_set_pulsewidth(PAN_GPIO, CENTER_POSITION);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Handle button presses
        for (int gpio = UP_BUTTON; gpio <= RIGHT_BUTTON; ++gpio) {
            if (gpio_get_level(gpio) == 0) {
                handle_button_press(gpio);
            }
        }

        // Update PWM values
        tilt_pwm_set_pulsewidth(TILT_GPIO, libgpiod_get_pwm_period() / 2);
        pan_pwm_set_pulsewidth(PAN_GPIO, libgpiod_get_pwm_period() / 2);

        // Sleep for 50ms
        usleep(50000);
    }

    return 0;
}

