#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>
#include <json-c/json.h>
#include <pigpio.h>

#define GPIO_PIN 11
#define BUFF_SIZE 1024
#define POLL_INTERVAL 100
#define DEBOUNCE_TIME 2000
#define JPEG_QUALITY 85
#define CAMERA_DIR "motion_captures"

#define HTTP_ENDPOINT "http://<IP>:<port>/upload"

int gpio_init(void);
int pigpio_init(void);
int sensor_init(void);
int file_system_init(void);
int http_init(const char *endpoint);
int http_post(const char *payload);
int capture_image(const char *filename);
int debouncing(int *motion_status);

int main(int argc, char *argv[]) {
    int gpio_status, pigpio_status, sensor_status, file_system_status, http_status;

    if (gpio_init() < 0 || pigpio_init() < 0 || sensor_init() < 0 ||
        file_system_init() < 0 || http_init(HTTP_ENDPOINT) < 0) {
        fprintf(stderr, "Failed to initialize any component.\n");
        return EXIT_FAILURE;
    }

    while (1) {
        int motion_status = 0;
        int last_motion_time = time(NULL);

        while (!motion_status && time(NULL) - last_motion_time < DEBOUNCE_TIME) {
            usleep(100000);
        }

        if (motion_status) {
            char timestamp[32];
            time_t now = time(NULL);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S.%L", localtime(&now));
            char filename[64];
            sprintf(filename, CAMERA_DIR "/%s.jpg", timestamp);

            if (capture_image(filename) < 0) {
                fprintf(stderr, "Failed to capture image.\n");
                continue;
            }

            json_object *jobj = json_object_new();
            json_object_set_new(jobj, "filename", json_object_from_string(filename));
            json_object_set_new(jobj, "timestamp", json_object_from_str(timestamp));
            json_object_set_new(jobj, "motion", json_object_from_bool(motion_status));
            json_object_set_new(jobj, "gpio", json_object_from_long(GPIO_PIN));

            if (http_post(json_object_to_json_string(jobj)) < 0) {
                fprintf(stderr, "Failed to send HTTP request.\n");
                json_object_free(jobj);
            }

            json_object_free(jobj);
            free(filename);
        }

        usleep(POLL_INTERVAL * 1000);
    }

    gpio_cleanup();
    pigpio_cleanup();
    file_system_cleanup();
    http_cleanup();

    return EXIT_SUCCESS;
}

int gpio_init(void) {
    int ret = gpio_set_mode(GPIO_PIN, GPIO_OUTPUT);
    if (ret < 0) {
        perror("gpio_set_mode");
        return ret;
    }
    return 0;
}

int pigpio_init(void) {
    int ret = pigpio_init();
    if (ret < 0) {
        perror("pigpio_init");
        return ret;
    }
    return 0;
}

int sensor_init(void) {
    int ret = gpio_set_pullup_down(GPIO_PIN, GPIO_PULLDOWN);
    if (ret < 0) {
        perror("gpio_set_pullup_down");
        return ret;
    }
    return 0;
}

int file_system_init(void) {
    int ret = mkdir(CAMERA_DIR, 0777);
    if (ret != 0) {
        perror("mkdir");
        return ret;
    }
    return 0;
}

int http_init(const char *endpoint) {
    int ret = http_client_new();
    if (ret < 0) {
        perror("http_client_new");
        return ret;
    }

    json_object *jobj = json_object_new();
    json_object_set_new(jobj, "endpoint", json_object_from_str(endpoint));

    http_client_set_request_header(ret, "Content-Type", "application/json");
    http_client_set_request_body(ret, json_object_to_json_string(jobj));

    return ret;
}

int http_post(const char *payload) {
    int ret = http_client_perform(ret);
    if (ret < 0) {
        perror("http_client_perform");
        return ret;
    }

    if (http_client_get_response_code(ret) != 200) {
        fprintf(stderr, "HTTP POST failed with code %d.\n", http_client_get_response_code(ret));
        return -1;
    }

    return 0;
}

int capture_image(const char *filename) {
    int ret = camera_capture_jpeg(filename, JPEG_QUALITY);
    if (ret < 0) {
        perror("camera_capture_jpeg");
        return ret;
    }
    return 0;
}

int debouncing(int *motion_status) {
    // Simple debouncing logic, can be replaced with more sophisticated methods
    *motion_status = 1;
    usleep(100000);
    *motion_status = 0;
    return 0;
}

int gpio_cleanup(void) {
    gpio_set_mode(GPIO_PIN, GPIO_INPUT);
    gpio_set_pullup_down(GPIO_PIN, GPIO_PULLUP);
    return 0;
}

int pigpio_cleanup(void) {
    pigpio_terminate();
    return 0;
}

int file_system_cleanup(void) {
    rmdir(CAMERA_DIR);
    return 0;
}

int http_cleanup(void) {
    http_client_free(http_client_);
    return 0;
}

