#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <time.h>
#include <errno.h>
#include <libgpgod.h>

#define GPIO_PIN 11
#define DEBOUNCE_TIMEOUT_MS 50
#define CAPTURE_COMMAND "raspistill -o /home/pi/images/ -tw 640 -h 480 -q 85 -t 2000 -nopreview -k 0 -st 1"
#define LOG_FILE "/home/pi/motion_capture.log"

int gpio_fd;
int pir_pin = GPIO_PIN;

void pir_init() {
    gpio_fd = open("/dev/gpioctrl", O_RDWR);
    if (gpio_fd < 0) {
        perror("Failed to open /dev/gpioctrl");
        exit(EXIT_FAILURE);
    }

    if (gpioctrl_init(gpio_fd) < 0) {
        perror("Failed to initialize gpioctrl");
        exit(EXIT_FAILURE);
    }

    gpioctrl_output_pin_t pin_mode = GPIO_OUTPUT;
    if (gpioctrl_pin_mode(gpio_fd, pir_pin, &pin_mode) < 0) {
        perror("Failed to set GPIO pin mode");
        exit(EXIT_FAILURE);
    }
}

void pir_debounce() {
    struct timespec timeout;
    timeout.tv_sec = 0;
    timeout.tv_nsec = DEBOUNCE_TIMEOUT_MS * 1e9;

    int ret = libgpiod_poll(gpio_fd, pir_pin, LIBGPIOD_EVENT_FALLING, &timeout);
    if (ret < 0) {
        perror("Failed to wait for edge fall event");
        exit(EXIT_FAILURE);
    }
}

void capture_image() {
    char cmd[256];
    snprintf(cmd, sizeof(cmd), CAPTURE_COMMAND, "YYYYMMDD_%04d_%02d_%02d_%02d_mm.jpg");

    pid_t pid = fork();
    if (pid < 0) {
        perror("Failed to fork");
        exit(EXIT_FAILURE);
    } else if (pid == 0) { // Child process
        close(STDIN_FILENO);
        close(STDOUT_FILENO);
        close(STDERR_FILENO);

        if (execlp(CAPTURE_COMMAND, CAPTURE_COMMAND, cmd, NULL) < 0) {
            perror("Failed to execute capture command");
            exit(EXIT_FAILURE);
        }
    } else { // Parent process
        waitpid(pid, NULL, 0);
        if (WIFEXITED(waitpid(pid, NULL, 0))) {
            if (WEXITSTATUS(waitpid(pid, NULL, 0)) != 0) {
                fprintf(LOG_FILE, "Capture command failed with exit code %d\n", WEXITSTATUS(waitpid(pid, NULL, 0)));
            }
        }
    }
}

int main(int argc, char *argv[]) {
    pir_init();

    while (1) {
        pir_debounce();
        if (gpioctrl_read(gpio_fd, pir_pin) == 0) {
            capture_image();
        }
    }

    close(gpio_fd);
    return 0;
}

