#define FIELD_NONE 0

int capture_frame(int fd, unsigned char *buffer) {
    struct v4l2_pixfmt_desc fmt;
    int ret;

    ret = v4l2_querypixelformat(fd, &fmt);
    if (ret < 0) {
        perror("v4l2_querypixelformat");
        return -1;
    }

    if (fmt.pixelformat != PIX_FMT_YUYV || fmt.field == FIELD_NONE) {
        fprintf(stderr, "Unsupported pixel format or field\n");
        return -1;
    }

    ret = v4l2_requestbuffer(fd, &fmt, V4L2_BUF_TYPE_VIDEO_CAPTURE, -1);
    if (ret < 0) {
        perror("v4l2_requestbuffer");
        return -1;
    }

    ret = v4l2_borrow(fd, 0);
    if (ret < 0) {
        perror("v4l2_borrow");
        return -1;
    }

    ret = v4l2_requestbuffer(fd, &fmt, V4L2_BUF_TYPE_VIDEO_CAPTURE, -1);
    if (ret < 0) {
        perror("v4l2_requestbuffer");
        v4l2_returnbuffer(fd, 0);
        return -1;
    }

    ret = v4l2_extract_buffer(fd, &fmt, buffer);
    if (ret < 0) {
        perror("v4l2_extract_buffer");
        v4l2_returnbuffer(fd, 0);
        return -1;
    }

    v4l2_returnbuffer(fd, 0);
    return 0;
}

int main() {
    int fd, ret;
    struct stat sb;
    pthread_t handler;

    fd = open(CAMERA_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    ret = ioctl(fd, VIDIOC_QUERYCAP, (unsigned long *)&sb);
    if (ret < 0) {
        perror("ioctl VIDIOC_QUERYCAP");
        close(fd);
        exit(EXIT_FAILURE);
    }

    if (sb.st_nlink != 1 || sb.st_mode & S_IFMT != S_IFDEVT) {
        fprintf(stderr, "Not a valid video device\n");
        close(fd);
        exit(EXIT_FAILURE);
    }

    ret = ioctl(fd, VIDIOC_S_FMT, (unsigned long *)&fmt);
    if (ret < 0) {
        perror("ioctl VIDIOC_S_FMT");
        close(fd);
        exit(EXIT_FAILURE);
    }

    ret = ioctl(fd, VIDIOC_STREAMON, (unsigned long *)&fmt);
    if (ret < 0) {
        perror("ioctl VIDIOC_STREAMON");
        close(fd);
        exit(EXIT_FAILURE);
    }

    ret = ioctl(fd, VIDIOC_REQBUFS, &req);
    if (ret < 0) {
        perror("ioctl VIDIOC_REQBUFS");
        close(fd);
        exit(EXIT_FAILURE);
    }

    ret = ioctl(fd, VIDIOC_STREAMOFF, (unsigned long *)&fmt);
    if (ret < 0) {
        perror("ioctl VIDIOC_STREAMOFF");
        close(fd);
        exit(EXIT_FAILURE);
    }

    unsigned char *buffer = mmap(NULL, BUFFER_SIZE, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (buffer == MAP_FAILED) {
        perror("mmap");
        close(fd);
        exit(EXIT_FAILURE);
    }

    ret = capture_frame(fd, buffer);
    if (ret < 0) {
        goto cleanup;
    }

    struct stat sb_file;
    FILE *fp = fopen("cropped.yuv", "wb");
    if (!fp) {
        perror("fopen");
        munmap(buffer, BUFFER_SIZE);
        close(fd);
        exit(EXIT_FAILURE);
    }

    int y, u, v;
    for (int i = 0; i < BUFFER_SIZE / (200 * 150 * 2); i++) {
        y = buffer[i * 2];
        u = buffer[i * 2 + 1];
        v = buffer[i * 2 + 2];

        fwrite(&y, 1, 1, fp);
        fwrite(&u, 1, 1, fp);
        fwrite(&v, 1, 1, fp);
    }

    fclose(fp);
    munmap(buffer, BUFFER_SIZE);
    close(fd);

cleanup:
    if (handler) {
        pthread_join(handler, NULL);
    }

    return 0;
}

