#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define OLED_ADDRESS 0x3C
#define OLED_WIDTH 128
#define OLED_HEIGHT 64
#define BITMAP_FONT_SIZE 5

#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define CPU_USAGE_FILE "/proc/stat"

#define UPDATE_INTERVAL_SECONDS 1.0

void oled_init(void);
void oled_clear(void);
void oled_print_string(const char *str, int x, int y);
void oled_print_bitmap(const unsigned char *bitmap, int x, int y, int width, int height);

int main(int argc, char *argv[]) {
    pigpio pi = pigpio_begin(50000);
    if (!pi) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    oled_init();

    while (1) {
        struct timespec timeout;
        timeout.tv_sec = UPDATE_INTERVAL_SECONDS;
        timeout.tv_nsec = 0;

        if (select(1, NULL, NULL, NULL, &timeout, NULL) == -1) {
            perror("select");
            exit(1);
        }

        if (pi_get_temp(pi, OLED_ADDRESS) < 0) {
            fprintf(stderr, "Error reading OLED address\n");
            exit(1);
        }

        if (pi_get_cpu_usage(pi, OLED_ADDRESS) < 0) {
            fprintf(stderr, "Error reading CPU usage\n");
            exit(1);
        }

        char temp_str[16];
        FILE *temp_file = fopen(TEMP_FILE, "r");
        if (!temp_file) {
            fprintf(stderr, "Failed to open CPU temperature file\n");
            exit(1);
        }
        fgets(temp_str, sizeof(temp_str), temp_file);
        fclose(temp_file);

        char cpu_usage_str[16];
        FILE *cpu_usage_file = fopen(CPU_USAGE_FILE, "r");
        if (!cpu_usage_file) {
            fprintf(stderr, "Failed to open CPU usage file\n");
            exit(1);
        }
        fgets(cpu_usage_str, sizeof(cpu_usage_str), cpu_usage_file);
        fclose(cpu_usage_file);

        oled_clear();
        oled_print_string("Temp: ", 4, 0);
        oled_print_bitmap(temp_str, 4, 0, 1, 1);
        oled_print_string(" %d", atoi(temp_str), 4, 6);

        oled_print_string("CPU Usage: ", 14, 18);
        oled_print_bitmap(cpu_usage_str, 14, 18, 1, 1);

        usleep(1000000 * UPDATE_INTERVAL_SECONDS);
    }

    pigpio_terminate(pi);
    return 0;
}

void oled_init(void) {
    if (ioctl(OLED_ADDRESS, OLED_POWERON, 0) < 0) {
        fprintf(stderr, "Failed to initialize OLED\n");
        exit(1);
    }

    if (ioctl(OLED_ADDRESS, OLED_SET_MULTIPLEX_RATIO, 16 / 4) < 0) {
        fprintf(stderr, "Failed to set multiplex ratio\n");
        exit(1);
    }

    if (ioctl(OLED_ADDRESS, OLED_DISPLAY()) < 0) {
        fprintf(stderr, "Failed to enable display\n");
        exit(1);
    }
}

void oled_clear(void) {
    for (int y = 0; y < OLED_HEIGHT; y++) {
        for (int x = 0; x < OLED_WIDTH; x++) {
            ioctl(OLED_ADDRESS, OLED_PIXEL_OFF, x * 4 + y * OLED_WIDTH * 2);
        }
    }
}

void oled_print_string(const char *str, int x, int y) {
    for (int i = 0; str[i] != '\0'; i++) {
        ioctl(OLED_ADDRESS, OLED_CHAR_SET, OLED_FONT_5x7);
        ioctl(OLED_ADDRESS, OLED_TEXT_COLOR, 0x0000);
        ioctl(OLED_ADDRESS, OLED_PIXEL_ROW_ENABLE, y * 4);
        ioctl(OLED_ADDRESS, OLED_PIXEL_COLUMN_ENABLE, x * 2);
        ioctl(OLED_ADDRESS, OLED_PIXEL_WRITE, str[i]);
    }
}

void oled_print_bitmap(const unsigned char *bitmap, int x, int y, int width, int height) {
    for (int i = 0; i < height; i++) {
        for (int j = 0; j < width; j++) {
            ioctl(OLED_ADDRESS, OLED_PIXEL_SET, bitmap[i * width + j] << 1);
        }
    }
}

int pi_get_temp(pigpio pi, int oled_address) {
    FILE *temp_file = fopen(TEMP_FILE, "r");
    if (!temp_file) {
        return -1;
    }
    fgets(temp_str, sizeof(temp_str), temp_file);
    fclose(temp_file);
    return atoi(temp_str);
}

int pi_get_cpu_usage(pigpio pi, int oled_address) {
    FILE *cpu_usage_file = fopen(CPU_USAGE_FILE, "r");
    if (!cpu_usage_file) {
        return -1;
    }
    fgets(cpu_usage_str, sizeof(cpu_usage_str), cpu_usage_file);
    fclose(cpu_usage_file);
    return atoi(cpu_usage_str);
}

