int main(int argc, char *argv[]) {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    gpio_init();
    i2c_init();

    while (1) {
        read_flow_sensor(NULL);
        if (total_volume > 0 && (total_volume % UPDATE_INTERVAL_SECS == 0)) {
            update_lcd(NULL);
        }
        usleep(LOG_INTERVAL_SECS * 1000000);
    }

    gpio_cleanup();
    i2c_cleanup();

    return 0;
}

