#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define LCD_ADDRESS 0x27
#define LCD_DATA_PIN 4
#define LCD_COMMAND_REGISTER 0x01
#define LCD_DATA_REGISTER 0x02
#define FLOW_RATE_INTERVAL_S 1
#define MAX_PULSES 10000
#define SENSOR_THRESHOLD 100

int gpio_fd;
int i2c_fd;

void init_gpio(void);
void init_i2c(void);
void setup_gpio(void);
void setup_i2c(void);
void read_sensor_pulses(void);
void display_flow_rate(float rate);
void handle_sensor_absence(void);
void cleanup(void);

int main(int argc, char *argv[]) {
    int ret;

    if (argc != 1) {
        fprintf(stderr, "Usage: %s\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    init_gpio();
    init_i2c();
    setup_gpio();
    setup_i2c();

    while (1) {
        read_sensor_pulses();
        display_flow_rate(calculate_flow_rate());
        usleep(FLOW_RATE_INTERVAL_S * 1000000);
    }

    cleanup();
    return 0;
}

void init_gpio(void) {
    gpio_fd = open("/dev/gpiomem", O_RDWR);
    if (gpio_fd == -1) {
        perror("Failed to open /dev/gpiomem");
        exit(EXIT_FAILURE);
    }

    if (ftruncate(gpio_fd, 4) == -1) {
        perror("Failed to truncate /dev/gpiomem");
        close(gpio_fd);
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(gpio_fd, GPIO_OUTPUT) == -1) {
        perror("Failed to set GPIO mode");
        close(gpio_fd);
        exit(EXIT_FAILURE);
    }
}

void init_i2c(void) {
    i2c_fd = open("/dev/i2c-1", O_RDWR | O_NOCTTY);
    if (i2c_fd == -1) {
        perror("Failed to open /dev/i2c-1");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, LCD_ADDRESS) == -1) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

void setup_gpio(void) {
    gpioWrite(gpio_fd, GPIO_PIN);
}

void setup_i2c(void) {
    // No setup needed for I2C
}

void read_sensor_pulses(void) {
    int pulse_count = 0;
    unsigned int value;

    while (pulse_count < MAX_PULSES) {
        ret = read_i2c_byte(i2c_fd, LCD_DATA_REGISTER);
        if (ret == -1) {
            perror("Failed to read from I2C");
            return;
        }

        value = read_i2c_byte(i2c_fd, LCD_COMMAND_REGISTER);
        if (value & 0x01) {
            pulse_count++;
        }

        usleep(10000); // Adjust pulse reading frequency as needed
    }

    if (pulse_count < SENSOR_THRESHOLD) {
        handle_sensor_absence();
    }
}

void display_flow_rate(float rate) {
    char buffer[20];

    sprintf(buffer, "Flow Rate: %.2f L/min", rate);
    write_i2c_byte(i2c_fd, LCD_DATA_REGISTER, 0);
    write_i2c_byte(i2c_fd, LCD_COMMAND_REGISTER, 0x06);
    write_i2c_byte(i2c_fd, 0, (char)buffer[0]);
    write_i2c_byte(i2c_fd, 1, (char)buffer[1]);
    write_i2c_byte(i2c_fd, 2, 0);
    write_i2c_byte(i2c_fd, 3, 0);
    write_i2c_byte(i2c_fd, 4, 0);
    write_i2c_byte(i2c_fd, 5, 0);
    write_i2c_byte(i2c_fd, 6, 0);
    write_i2c_byte(i2c_fd, 7, 0);
    write_i2c_byte(i2c_fd, 8, 0);
    write_i2c_byte(i2c_fd, 9, 0);
    write_i2c_byte(i2c_fd, 10, 0);
    write_i2c_byte(i2c_fd, 11, 0);
    write_i2c_byte(i2c_fd, 12, 0);
    write_i2c_byte(i2c_fd, 13, 0);
    write_i2c_byte(i2c_fd, 14, 0);
    write_i2c_byte(i2c_fd, 15, 0);
}

void handle_sensor_absence(void) {
    printf("Sensor not detected. Flow rate: 0.00 L/min\n");
    display_flow_rate(0.00);
}

void cleanup(void) {
    if (gpio_fd != -1) {
        close(gpio_fd);
        gpio_fd = -1;
    }

    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

int read_i2c_byte(int fd, int register_address) {
    unsigned char data;
    int ret = read(fd, &data, 1);
    if (ret == -1) {
        perror("Failed to read from I2C");
        return -1;
    }
    return data;
}

int write_i2c_byte(int fd, int register_address, unsigned char data) {
    return write(fd, &data, 1);
}

float calculate_flow_rate(void) {
    int pulse_count = 0;
    unsigned int value;

    while (pulse_count < MAX_PULSES) {
        ret = read_i2c_byte(i2c_fd, LCD_DATA_REGISTER);
        if (ret == -1) {
            perror("Failed to read from I2C");
            return 0.0;
        }

        value = read_i2c_byte(i2c_fd, LCD_COMMAND_REGISTER);
        if (value & 0x01) {
            pulse_count++;
        }

        usleep(10000); // Adjust pulse reading frequency as needed
    }

    // Assuming 1 pulse per liter for this example
    float rate = (float)pulse_count / FLOW_RATE_INTERVAL_S / 60.0;
    return rate;
}

