#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <string.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>

#define NUM_ROWS 8
#define NUM_COLS 8
#define ROW_ANODE_PIN 17
#define COL_CATHODE_PIN 5
#define ROW_DELAY_US 800

#define GPIO_MODE_OUTPUT 1
#define GPIO_OUTPUT_PIN 1

#define GPIO_PIN_ROW_ANODE ROW_ANODE_PIN
#define GPIO_PIN_COL_CATHODE COL_CATHODE_PIN

void init_gpio(void) {
    int i;
    for (i = GPIO_PIN_ROW_ANODE; i < GPIO_PIN_ROW_ANODE + NUM_ROWS; i++) {
        if (open_gpio_file(i, O_WRONLY | O_NONBLOCK) < 0) {
            perror("Failed to open GPIO pin");
            exit(EXIT_FAILURE);
        }
        set_gpio_mode(i, GPIO_MODE_OUTPUT);
    }

    for (i = GPIO_PIN_COL_CATHODE; i < GPIO_PIN_COL_CATHODE + NUM_COLS; i++) {
        if (open_gpio_file(i, O_WRONLY | O_NONBLOCK) < 0) {
            perror("Failed to open GPIO pin");
            exit(EXIT_FAILURE);
        }
        set_gpio_mode(i, GPIO_MODE_OUTPUT);
    }
}

void close_gpio(void) {
    int i;
    for (i = GPIO_PIN_ROW_ANODE; i < GPIO_PIN_ROW_ANODE + NUM_ROWS; i++) {
        if (close_gpio_file(i) < 0) {
            perror("Failed to close GPIO pin");
        }
    }

    for (i = GPIO_PIN_COL_CATHODE; i < GPIO_PIN_COL_CATHODE + NUM_COLS; i++) {
        if (close_gpio_file(i) < 0) {
            perror("Failed to close GPIO pin");
        }
    }
}

void set_led(int row, int col) {
    if (row < 0 || row >= NUM_ROWS || col < 0 || col >= NUM_COLS) {
        fprintf(stderr, "Error: Invalid row or column index.\n");
        exit(EXIT_FAILURE);
    }

    write(GPIO_PIN_ROW_ANODE + row, &1); // Set row HIGH
    write(GPIO_PIN_COL_CATHODE + col, &0); // Set column LOW
}

void clear_led(int row, int col) {
    if (row < 0 || row >= NUM_ROWS || col < 0 || col >= NUM_COLS) {
        fprintf(stderr, "Error: Invalid row or column index.\n");
        exit(EXIT_FAILURE);
    }

    write(GPIO_PIN_ROW_ANODE + row, &0); // Set row LOW
    write(GPIO_PIN_COL_CATHODE + col, &1); // Set column HIGH
}

void wave_animation_left(void) {
    int i, j;
    for (i = 0; i < NUM_ROWS; i++) {
        for (j = 0; j < NUM_COLS; j++) {
            set_led(i, j);
            usleep(ROW_DELAY_US / 2);
            clear_led(i, j);
        }
    }
}

void wave_animation_right(void) {
    int i, j;
    for (i = NUM_ROWS - 1; i >= 0; i--) {
        for (j = 0; j < NUM_COLS; j++) {
            set_led(i, j);
            usleep(ROW_DELAY_US / 2);
            clear_led(i, j);
        }
    }
}

void signal_handler(int signum) {
    fprintf(stderr, "Received signal %d, shutting down...\n", signum);
    wave_animation_left();
    wave_animation_right();
    close_gpio();
    exit(EXIT_SUCCESS);
}

int main(int argc, char *argv[]) {
    signal(SIGINT, signal_handler);

    init_gpio();

    wave_animation_left();
    wave_animation_right();

    close_gpio();

    return 0;
}

