#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x53
#define LOG_FILE "depth_log.csv"
#define SAMPLE_INTERVAL 100

#define HEADER_ROW "timestamp,distance\n"

void init_i2c();
void write_to_log(int distance);
void read_sensor_data();
void handle_error(const char *msg);

int main(int argc, char *argv[]) {
    int file_descriptor;
    struct stat file_stat;
    char log_file_path[256];

    if (argc != 2) {
        fprintf(stderr, "Usage: %s <log_file>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    strcpy(log_file_path, argv[1]);

    init_i2c();

    file_descriptor = open(log_file_path, O_WRONLY | O_CREAT | O_APPEND, S_IRUSR | S_IWUSR);
    if (file_descriptor == -1) {
        handle_error("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    // Create a CSV header row if the file is newly created
    if (fstat(file_descriptor, &file_stat) == -1 || S_ISREG(file_stat.st_mode)) {
        write_to_log(0);
        close(file_descriptor);
        return 0;
    }

    write(file_descriptor, HEADER_ROW, strlen(HEADER_ROW));
    close(file_descriptor);

    while (1) {
        read_sensor_data();
        usleep(SAMPLE_INTERVAL * 1000);
    }

    close(file_descriptor);
    return 0;
}

void init_i2c() {
    int file_descriptor;
    char i2c_bus_name[16];

    file_descriptor = open("/dev/i2c-1", O_RDWR);
    if (file_descriptor == -1) {
        handle_error("Failed to open i2c bus");
        exit(EXIT_FAILURE);
    }

    strcpy(i2c_bus_name, "i2c-1");

    if (ioctl(file_descriptor, I2C_SLAVE, I2C_ADDR) == -1) {
        handle_error("Failed to set i2c bus address");
        close(file_descriptor);
        exit(EXIT_FAILURE);
    }

    close(file_descriptor);
}

void write_to_log(int distance) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        handle_error("Failed to open log file for writing");
        return;
    }

    fprintf(fp, "%d,%d\n", time(NULL), distance);
    fclose(fp);
}

void read_sensor_data() {
    int sensor_data;
    char buffer[4];

    sensor_data = read(1, buffer, 1);
    if (sensor_data == -1) {
        handle_error("Failed to read from I2C sensor");
        return;
    }

    if (sensor_data == 0x00) {
        write_to_log(1);
    } else {
        write_to_log(sensor_data);
    }
}

void handle_error(const char *msg) {
    fprintf(stderr, "Error: %s\n", msg);
    exit(EXIT_FAILURE);
}

