#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SENSOR_ADDRESS 0x5A
#define SAMPLE_INTERVAL_MS 500
#define LOG_FILE "biometric_log.txt"

#define ISO_8601_FORMAT "%Y-%m-%dT%H:%M:%SZ"

void sigint_handler(int sig) {
    close(i2c_fd);
    close(log_fd);
    sensor_call(SENSOR_ADDRESS);
    fprintf(stderr, "Exiting due to SIGINT\n");
    exit(EXIT_SUCCESS);
}

int main(int argc, char *argv[]) {
    int i2c_fd, log_fd;
    struct i2c_client *client;
    pigpio_setup();

    if (pigpio_init() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpio_strerror());
        return EXIT_FAILURE;
    }

    client = i2c_client_new(I2C_BUS, SENSOR_ADDRESS);
    if (!client) {
        fprintf(stderr, "Failed to open I2C client: %s\n", pigpio_strerror());
        pigpio_cleanup();
        return EXIT_FAILURE;
    }

    if (i2c_regwrite(client, SENSOR_ADDRESS, 0x20, 0x00) < 0) {
        fprintf(stderr, "Failed to write to SENSOR_ADDRESS register 0x20\n");
        i2c_client_free(client);
        pigpio_cleanup();
        return EXIT_FAILURE;
    }

    if (i2c_regread(client, SENSOR_ADDRESS, 0x24, &config) < 0) {
        fprintf(stderr, "Failed to read config register\n");
        i2c_client_free(client);
        pigpio_cleanup();
        return EXIT_FAILURE;
    }

    if (!(config & 0x02)) {
        fprintf(stderr, "Sensor not present or initialization failed\n");
        pigpio_cleanup();
        return EXIT_FAILURE;
    }

    if (pigpio_set_mode(0, PIGO_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        i2c_client_free(client);
        pigpio_cleanup();
        return EXIT_FAILURE;
    }

    if (pigpio_write(0, 1) < 0) {
        fprintf(stderr, "Failed to set GPIO pin as output\n");
        i2c_client_free(client);
        pigpio_cleanup();
        return EXIT_FAILURE;
    }

    if (pigpio_setup_timer(sigint_handler, 0) < 0) {
        fprintf(stderr, "Failed to set SIGINT handler\n");
        i2c_client_free(client);
        pigpio_cleanup();
        return EXIT_FAILURE;
    }

    log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd == -1) {
        perror("Failed to open log file");
        i2c_client_free(client);
        pigpio_cleanup();
        return EXIT_FAILURE;
    }

    while (1) {
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), ISO_8601_FORMAT, &ts);

        int proximity, light;
        if (i2c_read_i2c_reg(client, SENSOR_ADDRESS, 0x00, &proximity, 1) < 0) {
            fprintf(stderr, "Failed to read proximity\n");
        }
        if (i2c_read_i2c_reg(client, SENSOR_ADDRESS, 0x01, &light, 1) < 0) {
            fprintf(stderr, "Failed to read light\n");
        }

        if (write(log_fd, timestamp, strlen(timestamp)) < 0) {
            perror("Failed to write timestamp");
        }
        if (write(log_fd, &proximity, 1) < 0) {
            perror("Failed to write proximity");
        }
        if (write(log_fd, &light, 1) < 0) {
            perror("Failed to write light");
        }

        usleep(SAMPLE_INTERVAL_MS * 1000 / 1000);
    }

    close(log_fd);
    i2c_client_free(client);
    pigpio_cleanup();
    return EXIT_SUCCESS;
}

