#define PROXIMITY_REGISTER 0x00
#define LIGHT_REGISTER 0x01
#define LOG_FILE "biometric_data.log"
#define LOG_FORMAT "%Y-%m-%dT%H:%M:%S,%f,%f,%f\n"

#define BUFFER_SIZE 1024
char buffer[BUFFER_SIZE];

void sigint_handler(int sig) {
    close(pierc_fd);
    close(log_fd);
    pigpio_api_call(SIL1145_ADDRESS, 0x00, 0x00);
    printf("Program terminated.\n");
    exit(0);
}

int main() {
    int pierc_fd, log_fd;
    struct i2c_client *client;
    int status;

    pierc_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (pierc_fd == -1) {
        perror("Error opening log file");
        return EXIT_FAILURE;
    }

    client = i2c_open(I2C_BUS, SIL1145_ADDRESS);
    if (client == NULL) {
        perror("Failed to open I2C bus");
        close(pierc_fd);
        return EXIT_FAILURE;
    }

    if (i2c_transfer(client, SIL1145_ADDRESS, PROXIMITY_REGISTER, 0, BUFFER_SIZE, buffer) < BUFFER_SIZE) {
        perror("Failed to read proximity data");
        close(client);
        close(pierc_fd);
        return EXIT_FAILURE;
    }

    if (i2c_transfer(client, SIL1145_ADDRESS, LIGHT_REGISTER, 0, BUFFER_SIZE, buffer) < BUFFER_SIZE) {
        perror("Failed to read light data");
        close(client);
        close(pierc_fd);
        return EXIT_FAILURE;
    }

    int proximity = (buffer[0] << 8) | buffer[1];
    int light = (buffer[2] << 8) | buffer[3];

    if (proximity == 0xFF) {
        printf("Sensor not found.\n");
        close(client);
        close(pierc_fd);
        return EXIT_FAILURE;
    }

    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), LOG_FORMAT, &ts);
    write(pierc_fd, timestamp, strlen(timestamp));
    write(pierc_fd, &proximity, sizeof(proximity));
