#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <pthread.h>
#include <libgpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 27
#define TIMEOUT_MS 30
#define RISE_TIME_MS 30
#define LOG_INTERVAL_S 60
#define LOG_FILE "distance_log.txt"
#define LOG_FORMAT "%Y-%m-%dT%H:%M:%S"

#define MAX_DISTANCE 400
#define MIN_DISTANCE 2

#define BUFFER_SIZE 10
char log_buffer[BUFFER_SIZE];

void log_distance(float distance) {
    struct tm tm;
    time_t now = time(NULL);
    strftime(log_buffer, BUFFER_SIZE, LOG_FORMAT, localtime_r(&now, &tm));
    log_buffer[strcspn(log_buffer, "\n")] = '\0';

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }
    fprintf(log_file, "%s: ", log_buffer);
    fprintf(log_file, "%.2f\n", distance);
    fclose(log_file);
}

void handle_sensor_error() {
    log_distance(-1); // Signal an error
    exit(EXIT_FAILURE);
}

void handle_timeout() {
    log_distance(-1); // Signal a timeout
    exit(EXIT_FAILURE);
}

void handle_sensor_absent() {
    log_distance(-1); // Signal sensor absent
    exit(EXIT_FAILURE);
}

void distance_measurement(float *distance) {
    int echo_pin = ECHO_PIN;
    int trigger_pin = TRIGGER_PIN;
    int echo_divider = 2; // 1kΩ/2kΩ divider
    int echo_high_time = 0;
    int trigger_pulse_width = 10; // in microseconds
    int rise_time = 0;
    int echo_time = 0;
    int timeout = 0;

    // Initialize GPIO
    if (gpiod_setup_pin_in(&trigger_pin_config, TRIGGER_PIN) < 0) {
        handle_sensor_error();
    }
    if (gpiod_setup_pin_in(&echo_pin_config, ECHO_PIN) < 0) {
        handle_sensor_error();
    }

    // Set up GPIO
    if (gpiod_output_init(&trigger_pin_output, &trigger_pin_config, 1) < 0) {
        handle_sensor_error();
    }
    if (gpiod_input_init(&echo_pin_input, &echo_pin_config, 1) < 0) {
        handle_sensor_error();
    }

    // Drive trigger pulse
    gpiod_output_set(&trigger_pin_output, 1);
    usleep(trigger_pulse_width / 2);
    gpiod_output_set(&trigger_pin_output, 0);

    // Wait for echo rise
    rise_time = 0;
    while (echo_high_time == 0 && rise_time < TIMEOUT_MS) {
        echo_time = gpiod_get_value(&echo_pin_input);
        if (echo_time == 1) {
            echo_high_time = 1;
        } else {
            echo_high_time = 0;
        }
        rise_time++;
        usleep(100000); // 100 µs
    }

    // Check for timeout
    if (rise_time >= TIMEOUT_MS) {
        handle_timeout();
    }

    // Measure distance
    if (echo_high_time == 1) {
        int duration = gpiod_get_value(&echo_pin_input);
        *distance = (duration * 29.1 / 2) / 2; // Convert to cm
        if (*distance < MIN_DISTANCE || *distance > MAX_DISTANCE) {
            log_distance(*distance);
        } else if (*distance < 15) {
            log_distance(*distance);
            fprintf(stdout, "Time to water the plant!\n");
        }
    } else {
        log_distance(-1); // Signal sensor error
    }

    // Reset GPIO
    gpiod_output_disable(&trigger_pin_output);
    gpiod_input_disable(&echo_pin_input);
}

int main(int argc, char *argv[]) {
    pthread_t thread;
    float distance;

    if (pthread_create(&thread, NULL, (void *(*)(void *))distance_measurement, &distance) != 0) {
        handle_sensor_error();
    }

    // Graceful shutdown
    struct sigaction sa;
    sa.sa_handler = SIG_DFL;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGINT handler\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGTERM handler\n");
    }

    // Close log file
    if (fclose(log_file) != 0) {
        fprintf(stderr, "Error closing log file\n");
    }

    // Wait for thread to finish
    pthread_join(thread, NULL);

    return 0;
}

