void write_to_csv(const char *timestamp, int r, int g, int b, int proximity) {
    FILE *file = fopen(CSV_FILE, "a");
    if (!file) {
        perror("Error opening file");
        return;
    }
    time_t now = time(NULL);
    fprintf(file, "%s,%d,%d,%d,%d\n", ctime(&now), r, g, b, proximity);
    fclose(file);
}

void handle_i2c_error(const char *msg) {
    printf("I2C error: %s\n", msg);
    // Reopen I2C bus and reinitialize the sensor
    close(I2C_BUS);
    open_i2c_device(I2C_BUS);
    init_apds9960();
}

void open_i2c_device(int fd) {
    struct i2c_client *client;
    int ret = i2c_alloc_device(fd, I2C_ADDR);
    if (ret < 0) {
        handle_i2c_error("i2c_alloc_device failed");
        exit(EXIT_FAILURE);
    }
    client = i2c_get_client(fd, I2C_ADDR);
    if (!client) {
        handle_i2c_error("i2c_get_client failed");
        exit(EXIT_FAILURE);
