    if (file < 0) {
        perror("Failed to open i2c bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(file, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C address");
        exit(EXIT_FAILURE);
    }
}

void i2c_smbus_write_byte(int file, uint8_t reg, uint8_t data) {
    write(file, &reg, 1);
    write(file, &data, 1);
}

uint16_t i2c_smbus_read_byte_data(int file, uint8_t reg) {
    uint8_t buf[2];
    read(file, buf, 2);
    return ((buf[0] << 8) | buf[1]);
}

