            perror("Failed to create heartrate.csv");
            return EXIT_FAILURE;
        }
    }

    while (running) {
        if (signum_received(SIGINT) || signum_received(SIGTERM)) {
            running = 0;
            break;
        }

        uint16_t proximity_data;
        if (read_proximity_data(&proximity_data) < 0) {
            fprintf(stderr, "Warning: Failed to read proximity data\n");
            continue;
        }

        int bpm = (proximity_data >> 8) * 100;

        write_to_csv(get_iso_timestamp(), bpm);

        usleep(SAMPLE_INTERVAL_MS * 1000 / HRZ);
