#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <libgpiod/gpio.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SAMPLING_INTERVAL_MS 200
#define TRIGGER_DELAY_MS 50
#define LOG_FILE "distance_log.txt"
#define BUFFER_SIZE 20

#define ULTRASONIC_ADDRESS 0x53
#define ULTRASONIC_REG_STATUS 0x00
#define ULTRASONIC_REG_DISTANCE 0x01

#define TIMESTAMP_FORMAT "%Y-%m-%d %H:%M:%S"

void log_to_file(const char *timestamp, int distance) {
    char log_entry[BUFFER_SIZE];
    sprintf(log_entry, "%s, %d\n", timestamp, distance);
    int log_fd = open(LOG_FILE, O_APPEND | O_CREAT | O_WRONLY, 0644);
    if (log_fd == -1) {
        perror("Failed to open log file");
        return;
    }
    write(log_fd, log_entry, strlen(log_entry));
    close(log_fd);
}

void handle_interrupt(int sig) {
    printf("Exiting sampling loop...\n");
    close(log_fd);
    close(i2c_fd);
    gpio_set_function(ULTRASONIC_ADDRESS, GPIO_OUTPUT);
    gpio_set_level(ULTRASONIC_ADDRESS, 0);
    exit(0);
}

int main() {
    int i2c_fd, log_fd;
    gpio_init();

    if (gpio_request(ULTRASONIC_ADDRESS, "ultrasonic") < 0) {
        perror("Failed to request GPIO pin");
        return EXIT_FAILURE;
    }

    if (gpio_is_output(ULTRASONIC_ADDRESS) < 0) {
        perror("Failed to set GPIO pin as output");
        return EXIT_FAILURE;
    }

    if (gpio_set_dir(ULTRASONIC_ADDRESS, GPIO_OUT) < 0) {
        perror("Failed to set GPIO pin direction");
        return EXIT_FAILURE;
    }

    if ((i2c_fd = open(LOG_FILE, O_WRONLY | O_CREAT, 0644)) == -1) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    if (ftruncate(fileno(i2c_fd), 0) == -1) {
        perror("Failed to truncate log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (pigpio_init(1) < 0) {
        perror("Failed to initialize pigpio");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (pigpio_setup_i2c(I2C_BUS) < 0) {
        perror("Failed to set up I2C bus");
        close(i2c_fd);
        pigpio_terminate();
        return EXIT_FAILURE;
    }

    if (pigpio_setup_pin(ULTRASONIC_ADDRESS) < 0) {
        perror("Failed to set up GPIO pin");
        close(i2c_fd);
        pigpio_terminate();
        return EXIT_FAILURE;
    }

    while (1) {
        struct timespec start_time;
        clock_gettime(CLOCK_REALTIME, &start_time);

        // Trigger the sensor
        pigpio_write_i2c_mem_block(ULTRASONIC_ADDRESS, ULTRASONIC_REG_STATUS, &0x00, 1);
        usleep(TRIGGER_DELAY_MS * 1000);

        // Read the distance
        int distance;
        pigpio_read_i2c_mem_block(ULTRASONIC_ADDRESS, ULTRASONIC_REG_DISTANCE, &distance, 1);

        // Log the reading
        char timestamp[BUFFER_SIZE];
        time_str(timestamp, TIMESTAMP_FORMAT);
        log_to_file(timestamp, distance);
        printf("Distance: %d mm\n", distance);

        // Wait for the next sample
        usleep(SAMPLING_INTERVAL_MS * 1000);
    }

    sigset_t sigset;
    sigaddset(&sigset, SIGINT);
    signal(SIGINT, handle_interrupt);

    pigpio_cleanup();
    close(i2c_fd);
    return 0;
}

