    if (log_fd < 0) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    // Signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        // Read sensor states
        int sensor1_reading = gpiod_get_value(&button);
        int sensor2_reading = gpiod_get_value(&button);

        // Store readings
        sensor_readings[0] = sensor1_reading;
        sensor_readings[1] = sensor2_reading;

        // Write to log file with timestamp
        now = time(NULL);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        fprintf(log_fd, "Timestamp: %s, Sensor 1: %d, Sensor 2: %d\n", timestamp, sensor_readings[0], sensor_readings[1]);

        // Sleep for the specified interval
        usleep(LOG_INTERVAL * 1000);
    }

    // Close the log file
    close(log_fd);

    // Clean up gpiod
    gpiod_button_destroy(&button);
    gpiod_ctx_destroy(&ctx);

    return 0;
}

