#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <libgpiod/gpio.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SAMPLING_INTERVAL_MS 500
#define LOG_FILE "biometric_log.txt"
#define MAX_RETRIES 3

typedef struct {
    int16_t proximity;
    int16_t light;
    struct timespec timestamp;
} SensorReading;

static int i2c_fd;
static SensorReading read_sensor_data() {
    SensorReading reading;
    int ret;

    for (int i = 0; i < MAX_RETRIES; i++) {
        ret = pigpio_begin_i2c(i2c_fd, I2C_BUS);
        if (ret < 0) {
            if (errno == EBUSY) {
                printf("I2C bus is busy, retrying...\n");
                usleep(100000); // Wait for 100ms
            } else {
                printf("Failed to open I2C bus, exiting.\n");
                exit(EXIT_FAILURE);
            }
        }

        ret = pigpio_write_byte_range(i2c_fd, 0x20, 0x00); // Address of Si1182
        if (ret < 0) {
            printf("Failed to write to Si1182, retrying...\n");
            usleep(100000);
            continue;
        }

        ret = pigpio_read_byte_range(i2c_fd, 0x24, &reading.proximity); // Read proximity
        if (ret < 0) {
            printf("Failed to read proximity, retrying...\n");
            usleep(100000);
            continue;
        }

        ret = pigpio_read_byte_range(i2c_fd, 0x26, &reading.light); // Read light
        if (ret < 0) {
            printf("Failed to read light, retrying...\n");
            usleep(100000);
            continue;
        }

        ret = pigpio_write_byte_range(i2c_fd, 0x28, 0x01); // Start conversion
        if (ret < 0) {
            printf("Failed to start conversion, retrying...\n");
            usleep(100000);
            continue;
        }

        ret = pigpio_read_byte_range(i2c_fd, 0x2A, &reading.timestamp.tv_sec); // Read timestamp
        if (ret < 0) {
            printf("Failed to read timestamp, retrying...\n");
            usleep(100000);
            continue;
        }

        ret = pigpio_read_byte_range(i2c_fd, 0x2C, &reading.timestamp.tv_nsec); // Read timestamp
        if (ret < 0) {
            printf("Failed to read timestamp, retrying...\n");
            usleep(100000);
            continue;
        }

        reading.timestamp.tv_sec += (reading.timestamp.tv_nsec / 100000000);
        reading.timestamp.tv_nsec %= 100000000;

        pigpio_write_byte_range(i2c_fd, 0x28, 0x00); // Stop conversion

        return reading;
    }

    printf("Failed to read sensor data after %d retries, exiting.\n", MAX_RETRIES);
    exit(EXIT_FAILURE);
}

void sigint_handler(int signum) {
    close(i2c_fd);
    fclose(stdout);
    printf("Exiting...\n");
    exit(0);
}

int main() {
    signal(SIGINT, sigint_handler);

    i2c_fd = pigpio_open_i2c(I2C_BUS);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    pigpio_setmode(i2c_fd, PIGIO_MODE_NORMAL);

    while (1) {
        SensorReading reading = read_sensor_data();
        if (fwrite(&reading, sizeof(SensorReading), 1, stdout) != 1) {
            perror("Failed to write to log file");
            exit(EXIT_FAILURE);
        }
    }

    pigpio_close_i2c(i2c_fd);
    fclose(stdout);
    return 0;
}

