#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS 1
#define GPIO_LED 17
#define POLLING_INTERVAL_MS (50)
#define DEFAULT_THRESHOLD (100)
#define LOG_FILE "tof_log.txt"

int i2c_fd;
int gpio_led = GPIO_SET;

void init_gpio(void) {
    if (gpio_init() < 0) {
        perror("Failed to initialize GPIO");
        exit(EXIT_FAILURE);
    }
    gpioSetMode(GPIO_LED);
}

int init_i2c(const char *bus_address) {
    i2c_fd = open(bus_address, O_RDWR | O_NOCTTY | O_NDELAY);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, (u_int8_t)bus_address) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    return i2c_fd;
}

int read_distance(void) {
    char command[3] = {0x44, 0x00, 0x00}; // Read register command
    write(i2c_fd, command, 3);

    char response[3];
    read(i2c_fd, &response, 1);

    if (response != '0') {
        fprintf(stderr, "Error reading distance\n");
        return -1;
    }

    return (response & 0x01) << 8 | (response & 0x02);
}

int set_distance(uint16_t distance) {
    char command[3] = {0x44, 0x01, (distance >> 8) & 0xFF};
    write(i2c_fd, command, 3);

    char response[3];
    read(i2c_fd, &response, 1);

    if (response != '0') {
        fprintf(stderr, "Error setting distance\n");
        return -1;
    }

    return 0;
}

int main(int argc, char *argv[]) {
    int threshold = DEFAULT_THRESHOLD;
    if (argc > 1) {
        threshold = atoi(argv[1]);
    }

    init_gpio();
    init_i2c("0x28"); // TDK InvenSense ICU-20201 default address

    pigio_init(NULL);
    gpio_setmode(GPIO_LED, GPIO_OUTPUT);

    while (1) {
        uint16_t distance = read_distance();
        if (distance == -1) {
            break;
        }

        if (distance < threshold) {
            gpioWrite(GPIO_LED, GPIO_HIGH);
            fprintf(stdout, "Distance: %d mm, LED ON\n", distance);
            write_log(distance);
        }

        set_distance(distance);
        usleep(POLLING_INTERVAL_MS * 1000 / 1000);
    }

    gpioReset(GPIO_LED);
    close(i2c_fd);
    pigio_cleanup();

    return 0;
}

void write_log(uint16_t distance) {
    time_t now = time(NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    fprintf(log_file, "%s: Distance: %d mm\n", timestamp, distance);
    fclose(log_file);
}

int gpio_init(void) {
    int file = open("/dev/gpiomem", O_RDWR | O_NOCTTY | O_NDELAY);
    if (file < 0) {
        return -1;
    }

    if (ftruncate(file, 0) < 0) {
        close(file);
        return -1;
    }

    if (gpio_write(file, 0x00) < 0) {
        close(file);
        return -1;
    }

    if (gpio_write(file, 0x01) < 0) {
        close(file);
        return -1;
    }

    if (gpio_write(file, 0x00) < 0) {
        close(file);
        return -1;
    }

    close(file);
    return 0;
}

int gpio_setmode(int pin, int mode) {
    int file = open("/dev/gpiomem", O_RDWR | O_NOCTTY | O_NDELAY);
    if (file < 0) {
        return -1;
    }

    if (gpio_write(file, pin) < 0) {
        close(file);
        return -1;
    }

    if (gpio_write(file, mode) < 0) {
        close(file);
        return -1;
    }

    close(file);
    return 0;
}

int gpio_write(int file, int value) {
    int ret = write(file, &value, 1);
    if (ret < 0) {
        perror("Failed to write to GPIO");
        return -1;
    }
    return ret;
}

int gpio_read(int file, int *value) {
    int ret = read(file, value, 1);
    if (ret < 0) {
        perror("Failed to read from GPIO");
        return -1;
    }
    return ret;
}

int gpio_reset(int pin) {
    int file = open("/dev/gpiomem", O_RDWR | O_NOCTTY | O_NDELAY);
    if (file < 0) {
        return -1;
    }

    if (gpio_write(file, pin) < 0) {
        close(file);
        return -1;
    }

    close(file);
    return 0;
}

