#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/epoll.h>
#include <signal.h>

#define I2C_BUS 1
#define I2C_ADDR 0x52
#define COMMAND_FRAME 0x01
#define RESPONSE_LEN 15
#define SAMPLE_DELAY 100000  // 100ms in microseconds
#define AVERAGE_THRESHOLD 1000
#define LOG_FILE "intrusion_log.txt"

#define SIGINT_HANDLER "SIGINT"

int i2c_fd;

void sigint_handler(int signum) {
    close(i2c_fd);
    fprintf(stderr, "Exiting on SIGINT\n");
    exit(0);
}

void install_sigint_handler() {
    signal(SIGINT, sigint_handler);
}

int open_i2c_device() {
    int file = open(fmt("/dev/i2c-%d", I2C_BUS), O_RDWR | O_SYNC);
    if (file < 0) {
        perror("open_i2c_device");
        return -1;
    }

    if (ioctl(file, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(file);
        return -1;
    }

    i2c_fd = file;
    return 0;
}

int write_i2c_command(const uint8_t *command, size_t len) {
    return write(i2c_fd, command, len);
}

int read_i2c_response(uint8_t *response, size_t len) {
    return read(i2c_fd, response, len);
}

int verify_header(const uint8_t *response) {
    if (response[0] != COMMAND_FRAME) {
        fprintf(stderr, "Invalid I2C response header\n");
        return -1;
    }
    return 0;
}

int extract_distance(const uint8_t *response, int *distance) {
    if (response[10] != 0x01 || response[11] != 0x02 || response[12] != 0x03 || response[13] != 0x04) {
        fprintf(stderr, "Invalid distance format in I2C response\n");
        return -1;
    }
    *distance = (response[11] << 8) | response[12];
    return 0;
}

int sample_sensor() {
    uint8_t command[4] = {COMMAND_FRAME, 0x00, 0x00, 0x00};
    write_i2c_command(command, sizeof(command));

    uint8_t response[RESPONSE_LEN];
    read_i2c_response(response, sizeof(response));

    if (verify_header(response) < 0) {
        return -1;
    }

    int distance;
    if (extract_distance(response, &distance) < 0) {
        return -1;
    }

    // Simulate 100ms delay
    usleep(SAMPLE_DELAY * 1000000);

    return 0;
}

int log_intrusion(const char *timestamp, double average_distance) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen intrusion_log.txt");
        return -1;
    }

    fprintf(log_file, "%s: %f mm\n", timestamp, average_distance);
    fclose(log_file);
    return 0;
}

int main() {
    install_sigint_handler();

    if (open_i2c_device() < 0) {
        return -1;
    }

    int average_distance = 0;
    int samples = 0;

    while (1) {
        int result = sample_sensor();
        if (result < 0) {
            fprintf(stderr, "Error sampling sensor\n");
            break;
        }

        average_distance += (double)distance;
        samples++;

        if (samples >= 10 && average_distance < AVERAGE_THRESHOLD) {
            char timestamp[32];
            time_t now = time(NULL);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
            log_intrusion(timestamp, average_distance / samples);
        }

        usleep(SAMPLE_DELAY * 1000000);
    }

    close(i2c_fd);
    return 0;
}

