#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x29
#define RESULT_INTERRUPT_STATUS 0x01
#define POLLING_INTERVAL_MS 100
#define PRINT_INTERVAL_MS 500

int main(int argc, char *argv[]) {
    int i2c_fd;
    gpioOutput(0); // Ensure GPIO0 is output for VL53L0X reset

    if (pigpioInit(I2C_BUS) != 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n");
        pigpioExit();
        return 1;
    }

    if (i2c_fd = open(I2C_ADDRESS, O_RDWR) < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n");
        pigpioExit();
        return 1;
    }

    uint8_t model_id[2];
    if (read(i2c_fd, model_id, 2) != 2) {
        fprintf(stderr, "Failed to read model ID: %s\n");
        close(i2c_fd);
        pigpioExit();
        return 1;
    }

    if (model_id[0] != 0x53 || model_id[1] != 0x68) {
        fprintf(stderr, "Invalid model ID, expected 0x53 0x68\n");
        close(i2c_fd);
        pigpioExit();
        return 1;
    }

    if (write(i2c_fd, (uint8_t *)"01", 1) != 1) {
        fprintf(stderr, "Failed to reset VL53L0X\n");
        close(i2c_fd);
        pigpioExit();
        return 1;
    }

    if (read(i2c_fd, &RESULT_INTERRUPT_STATUS, 1) != 1) {
        fprintf(stderr, "Failed to read RESULT_INTERRUPT_STATUS: %s\n");
        close(i2c_fd);
        pigpioExit();
        return 1;
    }

    if (!(RESULT_INTERRUPT_STATUS & 0x02)) {
        fprintf(stderr, "VL53L0X not ready\n");
        close(i2c_fd);
        pigpioExit();
        return 1;
    }

    double distance;
    while (1) {
        if (read(i2c_fd, &distance, sizeof(distance)) != sizeof(distance)) {
            fprintf(stderr, "Failed to read distance: %s\n");
            sleep(POLLING_INTERVAL_MS / 1000.0);
            continue;
        }

        printf("%04d-%02d-%02d %02d:%02d:%02d Distance: %.1f mm\n",
               (int)(distance / 1000),
               (int)(distance % 100) / 10,
               (int)(distance % 10) % 10,
               distance / 60 / 60,
               (distance % 60) / 10,
               distance % 10);

        usleep(PRINT_INTERVAL_MS / 1000.0);
    }

    close(i2c_fd);
    pigpioExit();
    return 0;
}

