#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SDA_PIN 2
#define SCL_PIN 3
#define SILICON_LABS_ID 0x1A
#define SILICON_LABS_ADDR 0x5A
#define LOG_INTERVAL 500 // milliseconds

void sigint_handler(int signum) {
    piSetup();
    pigioStopAll();
    pigioExit();
    exit(0);
}

int main(int argc, char *argv[]) {
    int i2c_fd;
    struct i2c_client *client;
    int proximity_data;

    // Initialize pigpio for I2C communication
    if (pigioInit() < 0) {
        perror("pigpioInit");
        return EXIT_FAILURE;
    }

    // Set up I2C bus
    if (pigioSetMode(I2C_BUS, PI_OUTPUT) < 0) {
        perror("pigioSetMode");
        return EXIT_FAILURE;
    }

    // Open I2C bus
    i2c_fd = pigioOpen(I2C_BUS, SCL_PIN, SDA_PIN);
    if (i2c_fd < 0) {
        perror("pigioOpen");
        return EXIT_FAILURE;
    }

    // Check for Silicon Labs ID
    if (pigioWrite(i2c_fd, SILICON_LABS_ID) != 4) {
        if (pigioError(i2c_fd) != EIO) {
            perror("pigioWrite");
            return EXIT_FAILURE;
        }
        // Sensor not present
    }

    // Start I2C communication
    client = pigioClient(i2c_fd);
    if (!client) {
        perror("pigioClient");
        return EXIT_FAILURE;
    }

    // Read proximity data
    while (1) {
        proximity_data = pigioReadI2C(client, SILICON_LABS_ID, 0x20);
        if (proximity_data == -1) {
            perror("pigioReadI2C");
            break;
        }

        // Log the proximity data
        printf("Proximity: %d\n", proximity_data);

        // Wait for the next reading
        usleep(LOG_INTERVAL * 1000 / 1000);
    }

    // Clean up and exit
    pigioClose(client);
    pigioExit();

    return EXIT_SUCCESS;
}

// Install SIGINT handler
signal(SIGINT, sigint_handler);

// Compile with: pigpiod --build-pkg=all

