#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/wait.h>
#include <signal.h>

#define I2C_BUS 1
#define I2C_DEVICE 0x1A  // MLX75030 default I2C address

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("\nCleaning up and exiting...\n");
        close(fildes);
        exit(0);
    }
}

int main() {
    int fildes;
    struct i2c_client *client;
    int ret;

    // Initialize signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    fildes = open("/dev/i2c-1", O_RDWR);
    if (fildes < 0) {
        perror("Failed to open I2C bus");
        exit(1);
    }

    // Set I2C client structure
    client = &i2c_client;
    client->device = (u8)I2C_BUS;
    client->address = (u8)I2C_DEVICE;

    // Check if the device is present
    ret = ioctl(fildes, I2C_SLAVE, I2C_DEVICE);
    if (ret == -1) {
        perror("Failed to set I2C slave address");
        close(fildes);
        exit(1);
    }

    // Verify device response
    ret = ioctl(fildes, I2C_GET_STATUS, (u32)I2C_M_READ);
    if (ret == -1) {
        perror("Failed to read device status");
        close(fildes);
        exit(1);
    }

    // Read distance measurement every 500ms
    while (1) {
        ret = ioctl(fildes, I2C_READ_BYTE_RDWR, (u32)I2C_M_RD);
        if (ret == -1) {
            if (errno == EIO || errno == EFAULT) {
                fprintf(stderr, "Error reading from I2C device\n");
            } else {
                fprintf(stderr, "Unexpected error occurred\n");
            }
        } else {
            // Process the distance value (MLX75030 distance is in 16-bit signed integer)
            int16_t distance = ((int16_t)client->data[0] << 8) | client->data[1];
            printf("Distance: %d mm\n", distance);
        }

        // Sleep for 500ms
        nanosleep(&struct timespec {
            .tv_sec = 0;
            .tv_nsec = 500000000;
        }, NULL);
    }

    // Close I2C file descriptor
    close(fildes);

    return 0;
}
