#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS 1
#define OPT3101_ADDRESS 0x5A
#define LOG_INTERVAL 500

int i2c_fd;
piGPIO_handle handle;

void init_i2c() {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, OPT3101_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

void setup_pigpio() {
    if (piGPIO_init() < 0) {
        perror("Failed to initialize pigpio");
        exit(EXIT_FAILURE);
    }
}

void log_data(int distance, int ambient_light, int error_flag) {
    static int last_log_time = 0;
    int current_time = time(NULL);

    if (current_time - last_log_time > LOG_INTERVAL) {
        last_log_time = current_time;
        printf("Time: %d ms\tDistance: %d mm\tAmbient Light: %d\tError Flag: %d\n",
               current_time, distance, ambient_light, error_flag);
    }
}

void read_opt3101() {
    uint8_t buffer[6];
    int read_bytes;

    read_bytes = read(i2c_fd, buffer, 6);
    if (read_bytes != 6) {
        perror("Failed to read from OPT3101");
        return;
    }

    int distance = buffer[0] << 8 | buffer[1];
    int ambient_light = buffer[2] << 8 | buffer[3];
    int error_flag = buffer[4] << 8 | buffer[5];

    log_data(distance, ambient_light, error_flag);
}

void cleanup() {
    piGPIO_shutdown();
    close(i2c_fd);
    pigpio_terminate();
}

int main(int argc, char *argv[]) {
    init_i2c();
    setup_pigpio();

    while (1) {
        read_opt3101();
        usleep(LOG_INTERVAL / 1000);
    }

    cleanup();
    return 0;
}

