#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define TIMEOUT_US 200000  // 200 ms in microseconds
#define MAX_DISTANCE 3800  // Maximum range in cm

void log_measurement(double distance) {
    time_t now = time(NULL);
    struct tm *timeinfo = localtime(&now);
    printf("Time: %s, Distance: %.2f cm\n", asctime(timeinfo), distance);
}

int main(int argc, char *argv[]) {
    pigpio_init(5);  // Initialize pigpio with 3.3V GPIO

    if (pigpio_init(5) != 0) {
        perror("Failed to initialize pigpio");
        return EXIT_FAILURE;
    }

    double last_distance = -1;
    while (1) {
        double distance = measure_distance();
        if (distance != last_distance) {
            log_measurement(distance);
            last_distance = distance;
        }
        usleep(1000000 / 60);  // Sleep for 16.67 ms (1 second)
    }

    pigpio_terminate(1000);  // Terminate pigpio on exit
    return EXIT_SUCCESS;
}

double measure_distance() {
    int trigger_out = 0;
    pigpio_write(TRIGGER_PIN, 0, 0);  // Send a 10 µs pulse
    usleep(10000);  // 10 µs delay

    int echo_in = 0;
    pigpio_read(ECHO_PIN);

    int duration = pigpio_get_input(ECHO_PIN);
    double time_us = (duration * 1000000) / 256;  // Convert to microseconds

    if (time_us < 10 || time_us > 38) {
        printf("Invalid pulse duration detected, skipping this reading.\n");
        return -1;
    }

    double speed_of_sound = 0.034;  // m/µs
    double distance = speed_of_sound * time_us / 2;

    if (distance < 0 || distance > MAX_DISTANCE) {
        printf("Distance out of range, skipping this reading.\n");
        return -1;
    }

    return distance;
}

