#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>
#include <time.h>

#define SENSOR_PIN 17
#define BUZZER_PIN 18
#define POLL_INTERVAL_MS 100
#define LOG_FILE "obstacle_log.txt"

void log_state_transition(const char* timestamp, int state) {
    time_t now = time(NULL);
    struct tm* now_time = localtime(&now);
    char timestamp_str[80];
    sprintf(timestamp_str, "%04d-%02d-%02d %02d:%02d:%02d",
            now_time->tm_year + 1900, now_time->tm_mon + 1,
            now_time->tm_mday, now_time->tm_hour, now_time->tm_min, now_time->tm_sec);

    FILE* log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file for writing.\n");
        return;
    }

    fprintf(log_file, "%s,Sensor: %s,Buzzer: %d\n", timestamp_str, state ? "ON" : "OFF", state);
    fclose(log_file);
}

int main() {
    int sensor_fd, buzzer_fd;
    struct gpio_req req_sensor, req_buzzer;

    sensor_fd = open("/dev/gpiochip", O_RDWR);
    if (sensor_fd < 0) {
        perror("Failed to open /dev/gpiochip");
        exit(EXIT_FAILURE);
    }

    req_sensor.mode = GPIO_OUTPUT;
    req_sensor.pin = SENSOR_PIN;
    if (ioctl(sensor_fd, GPIO_REQUEST, &req_sensor) < 0) {
        perror("Failed to request GPIO pin for sensor");
        exit(EXIT_FAILURE);
    }

    req_buzzer.mode = GPIO_OUTPUT;
    req_buzzer.pin = BUZZER_PIN;
    if (ioctl(sensor_fd, GPIO_REQUEST, &req_buzzer) < 0) {
        perror("Failed to request GPIO pin for buzzer");
        close(sensor_fd);
        exit(EXIT_FAILURE);
    }

    gpioset(sensor_fd, SENSOR_PIN, GPIO_INPUT);
    gpioset(sensor_fd, BUZZER_PIN, GPIO_OUTPUT);

    while (1) {
        int sensor_state = gpioget(sensor_fd, SENSOR_PIN);
        int buzzer_state = gpioget(sensor_fd, BUZZER_PIN);

        if (sensor_state == 0 && buzzer_state == 1) {
            log_state_transition(ctime(NULL), 0);
            gpioset(sensor_fd, SENSOR_PIN, GPIO_INPUT);
            gpioset(sensor_fd, BUZZER_PIN, GPIO_OUTPUT);
        } else if (sensor_state == 1 && buzzer_state == 0) {
            log_state_transition(ctime(NULL), 1);
            gpioset(sensor_fd, SENSOR_PIN, GPIO_INPUT);
            gpioset(sensor_fd, BUZZER_PIN, GPIO_OUTPUT);
        }

        usleep(POLL_INTERVAL_MS * 1000 / 1000);
    }

    close(sensor_fd);
    close(buzzer_fd);

    return 0;
}

