#define I2C_BUS 1
#define I2C_ADDR 0x53
#define GPIO_PIN 17
#define LOG_FILE "distance_log.txt"
#define LOG_INTERVAL 100
#define MIN_DISTANCE 10.0

#define PI_ERROR -1

void log_distance(const float distance) {
    time_t now = time(NULL);
    struct tm *timeinfo = localtime(&now);
    char time_str[80];
    sprintf(time_str, "%04d-%02d-%02d %02d:%02d:%02d",
            timeinfo->tm_year + 1900, timeinfo->tm_mon + 1, timeinfo->tm_mday,
            timeinfo->tm_hour, timeinfo->tm_min, timeinfo->tm_sec);

    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        perror("Failed to open log file");
        return;
    }
    fprintf(file, "%s, %f\n", time_str, distance);
    fclose(file);
}

void gpio_alert() {
    gpioInitialise();
    gpioSetMode(GPIO_PIN, GPIO_OUTPUT);
    gpioWrite(GPIO_PIN, 1);
    sleep(1);
    gpioWrite(GPIO_PIN, 0);
    gpioDeinitialise();
}

int main(int argc, char *argv[]) {
    int i2c_fd, gpio_fd;
    struct i2c_client *client;
    float distance;

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return PI_ERROR;
    }

    client = i2c_client_new(i2c_fd, I2C_BUS);
    if (!client) {
        perror("Failed to create I2C client");
        close(i2c_fd);
        return PI_ERROR;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        i2c_client_free(client);
        close(i2c_fd);
        return PI_ERROR;
    }

    if (i2c_register_write_byte(client, 0x00, 0x00) < 0) {
        perror("Failed to read distance register");
        i2c_client_free(client);
        close(i2c_fd);
        return PI_ERROR;
    }

    while (1) {
        distance = i2c_register_read_byte(client, 0x00);
        if (distance == 0xFF) {
            fprintf(stderr, "Sensor not detected\n");
            break;
        }

        log_distance(distance);

        if (distance < MIN_DISTANCE) {
            gpio_alert();
        }

        usleep(LOG_INTERVAL * 1000 / 1000);
    }

    i2c_client_free(client);
    close(i2c_fd);

    return 0;
}

