#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <libgpiod/gpio.h>
#include <pigpio.h>
#include <wiringPiI2C.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x29
#define POLL_INTERVAL_MS 100
#define LOG_FILE "distance_log.csv"

void signal_handler(int signum) {
    printf("Received signal %d, performing graceful shutdown.\n", signum);
    gpioRelease(I2C_BUS);
    close(logfd);
    pigpioInit(1);
    pigpioDetach();
}

int main() {
    int logfd;
    struct i2c_fd i2c_fd;
    gpio_adrc_t adrc;
    int sensor_distance;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (wiringPiI2cInit(I2C_BUS) < 0) {
        perror("wiringPiI2cInit");
        exit(EXIT_FAILURE);
    }

    if (wiringPiI2cOpen(I2C_BUS, I2C_ADDRESS) < 0) {
        perror("wiringPiI2cOpen");
        exit(EXIT_FAILURE);
    }

    if (wiringPiI2CReadRegister(I2C_BUS, I2C_ADDRESS, 0x00) < 0) {
        perror("wiringPiI2CReadRegister");
        exit(EXIT_FAILURE);
    }

    if (gpioSetup(I2C_BUS, I2C_ADDRESS, PI_OUTPUT) < 0) {
        perror("gpioSetup");
        exit(EXIT_FAILURE);
    }

    if (gpioAttach(I2C_BUS, I2C_ADDRESS, PI_OUTPUT) < 0) {
        perror("gpioAttach");
        exit(EXIT_FAILURE);
    }

    while (1) {
        sensor_distance = wiringPiI2CReadWord(I2C_BUS, I2C_ADDRESS, 0x01);

        if (sensor_distance == -1) {
            perror("wiringPiI2CReadWord");
            break;
        }

        if (file_exists(LOG_FILE)) {
            FILE *logfile = fopen(LOG_FILE, "a");
            if (logfile == NULL) {
                perror("fopen");
                exit(EXIT_FAILURE);
            }
        } else {
            fopen(LOG_FILE, "w");
        }

        if (fputs(getTimestamp(), logfile) < 0) {
            perror("fputs");
            exit(EXIT_FAILURE);
        }

        fprintf(logfile, "%d, %d\n", (int)time(NULL), sensor_distance);
        fclose(logfile);

        if (sensor_distance < 300) {
            printf("STOP\n");
        } else if (sensor_distance >= 300 && sensor_distance < 600) {
            printf("APPROACH\n");
        } else if (sensor_distance >= 600 && sensor_distance < 1200) {
            printf("SLOW\n");
        } else {
            printf("CLEAR\n");
        }

        usleep(POLL_INTERVAL_MS * 1000 / HRTIME_PER_SEC);
    }

    gpioDetach(I2C_BUS, I2C_ADDRESS);
    wiringPiI2CClose(I2C_BUS);
    wiringPiI2cExit(I2C_BUS);
    pigpioDetach();

    return 0;
}

int file_exists(const char *filename) {
    struct stat sb;
    return (stat(filename, &sb) == 0);
}

char *getTimestamp(void) {
    char timestamp[32];
    time_t t = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&t));
    return timestamp;
}

