#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/wait.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x50  // TDK InvenSense CH201 default I2C address
#define LED_GPIO 18
#define I2C_TIMEOUT 10000  // 10 ms
#define BLINK_DELAY 500  // 500 ms per half-cycle

#define MAX_RETRIES 3

void handle_signal(int signum) {
    close(i2c_fd);
    gpio_set_value(LED_GPIO, 0);
    printf("Program terminated. Cleaning up...\n");
    exit(0);
}

void setup_i2c() {
    int fd;
    char i2c_bus_name[16];

    snprintf(i2c_bus_name, sizeof(i2c_bus_name), "/dev/i2c-%d", I2C_BUS);
    fd = open(i2c_bus_name, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        if (errno == EOPERNOTFOUND) {
            printf("I2C slave not found, attempting to initialize...\n");
            for (int i = 0; i < MAX_RETRIES; i++) {
                if (ioctl(fd, I2C_SLAVE, I2C_ADDR) == 0) {
                    break;
                }
                usleep(I2C_TIMEOUT * 1000 / 3);
            }
            if (i == MAX_RETRIES) {
                perror("Failed to initialize I2C slave after retries");
                exit(EXIT_FAILURE);
            }
        } else {
            perror("Failed to set I2C slave address");
            exit(EXIT_FAILURE);
        }
    }
}

void setup_gpio() {
    if (gpio_init() < 0) {
        perror("Failed to initialize GPIO");
        exit(EXIT_FAILURE);
    }
    gpio_set_value(LED_GPIO, 0);  // Initialize LED as output
}

void blink_led(int duration) {
    gpio_set_value(LED_GPIO, 1);
    usleep(duration * 100000);  // 100 ms
    gpio_set_value(LED_GPIO, 0);
    usleep(duration * 100000);  // 100 ms
}

void read_distance(int *distance) {
    unsigned char buffer[6];
    int retries = 0;
    int ret;

    while (retries < MAX_RETRIES) {
        ret = read_i2c_regblock(i2c_fd, buffer, sizeof(buffer));
        if (ret >= 0) {
            *distance = buffer[2];  // Assuming distance is in the 4th byte
            break;
        }
        retries++;
        usleep(I2C_TIMEOUT * 1000 / 3);
    }

    if (retries == MAX_RETRIES) {
        perror("Failed to read distance after retries");
        exit(EXIT_FAILURE);
    }
}

int main(int argc, char *argv[]) {
    int i2c_fd, led_gpio;
    int distance;
    struct timespec start_time, end_time;
    double elapsed_time;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    setup_i2c();
    setup_gpio();

    i2c_fd = open("i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    led_gpio = fileno(open("/dev/gpiochip0", O_RDWR));
    if (led_gpio < 0) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    while (1) {
        gettimeofday(&start_time, NULL);

        read_distance(&distance);

        blink_led(BLINK_DELAY);

        end_time = gettimeofday();
        elapsed_time = (end_time.tv_sec - start_time.tv_sec) + (end_time.tv_usec - start_time.tv_usec) / 1000000.0;

        printf("Distance: %d cm, Blink Frequency: %f Hz\n", distance, 1 / elapsed_time);

        usleep(100000);  // Sleep for 100 ms
    }

    close(i2c_fd);
    close(led_gpio);
    gpio_cleanup();
    return 0;
}

