This code sets up an I2C connection to the TDK InvenSense CH201 ultrasonic sensor, initializes a GPIO pin for controlling an LED, and reads the distance every 100 ms. It logs the timestamped distance and blink frequency to stdout, controls the LED to blink faster as the distance decreases, and handles various error conditions. The program also cleans up resources on termination and handles SIGINT and SIGTERM signals gracefully.

Please note that this code assumes the sensor's distance is stored in the 4th byte of the response. Adjust the `read_distance` function if your sensor's distance register layout is different. Also, ensure that the GPIO pin connected to the LED is correctly configured as an output in your Raspberry Pi's configuration.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SAMPLING_INTERVAL_MS 100
#define MAX_ERRORS 5
#define RETRY_DELAY_MS 1000

#define LOG_FILE "distance_log.csv"

void log_error(const char *msg) {
    fprintf(stderr, "%s\n", msg);
}

int i2c_open(int file) {
    int fd = open(file, O_RDWR);
    if (fd < 0) {
        log_error("Failed to open I2C bus");
        return -1;
    }
    return fd;
}

int i2c_close(int fd) {
    close(fd);
    return 0;
}

int i2c_write_byte(int fd, uint8_t cmd) {
    uint8_t buf[2];
    buf[0] = cmd;
    return write(fd, buf, 1);
}

int i2c_read_byte(int fd, uint8_t *buf) {
    return read(fd, buf, 1);
}

int read_distance(int fd) {
    uint8_t cmd = 0x00; // MLX75030 register address for distance
    uint16_t distance;

    for (int retry = 0; retry < MAX_ERRORS; retry++) {
        if (i2c_write_byte(fd, cmd) == 1) {
            if (i2c_read_byte(fd, &distance) == 1) {
                return distance;
            }
        }
        log_error("I2C read failed, retrying...");
        usleep(RETRY_DELAY_MS);
    }
    log_error("Failed to read distance after %d retries", MAX_ERRORS);
    return -1;
}

void write_timestamp(FILE *fp) {
    time_t now = time(NULL);
    char time_str[80];
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", localtime(&now));
    fprintf(fp, "%s,", time_str);
}

void write_distance(FILE *fp, uint16_t distance) {
    fprintf(fp, "%lu,", distance);
}

void write_newline(FILE *fp) {
    fprintf(fp, "\n");
}

int main(int argc, char *argv[]) {
    int i2c_fd, ret;
