    int fd = open(file, O_RDWR);
    if (fd < 0) {
        log_error("Failed to open I2C bus");
        return -1;
    }
    return fd;
}

int i2c_close(int fd) {
    close(fd);
    return 0;
}

int i2c_write_byte(int fd, uint8_t cmd) {
    uint8_t buf[2];
    buf[0] = cmd;
    return write(fd, buf, 1);
}

int i2c_read_byte(int fd, uint8_t *buf) {
    return read(fd, buf, 1);
}

int read_distance(int fd) {
    uint8_t cmd = 0x00; // MLX75030 register address for distance
    uint16_t distance;

    for (int retry = 0; retry < MAX_ERRORS; retry++) {
        if (i2c_write_byte(fd, cmd) == 1) {
            if (i2c_read_byte(fd, &distance) == 1) {
                return distance;
            }
        }
        log_error("I2C read failed, retrying...");
        usleep(RETRY_DELAY_MS);
    }
    log_error("Failed to read distance after %d retries", MAX_ERRORS);
    return -1;
}

