#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <pigpio.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 27
#define DEBOUNCE_TIME 50
#define POLL_INTERVAL 10
#define LOG_FILE "proximity_log.txt"

void debounce(int gpio) {
    volatile int last_state = 0;
    unsigned long last_debounce_time = 0;

    while (1) {
        int current_state = piGPIOSetReadDir(gpio);
        if (current_state != last_state) {
            last_state = current_state;
            last_debounce_time = millis();
        }
        if ((millis() - last_debounce_time) > DEBOUNCE_TIME) {
            piGPIOSetDir(gpio, current_state);
        }
    }
}

void log_event(int sensor_id, char event_type) {
    time_t now = time(NULL);
    struct tm *time_info = localtime(&now);
    char timestamp[80];
    sprintf(timestamp, "%04d-%02d-%02dT%02d:%02d:%02d",
            time_info->tm_year + 1900, time_info->tm_mon + 1, time_info->tm_mday,
            time_info->tm_hour, time_info->tm_min, time_info->tm_sec);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    fprintf(log_file, "%s %d %s\n", timestamp, sensor_id, event_type);
    fclose(log_file);
}

int main() {
    int gpio_17 = SENSOR_1_GPIO;
    int gpio_27 = SENSOR_2_GPIO;

    if (piGPIOInit() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    debounce(gpio_17);
    debounce(gpio_27);

    while (1) {
        int sensor_1_state = piGPIOGet(gpio_17);
        int sensor_2_state = piGPIOGet(gpio_27);

        if (sensor_1_state != piGPIOReadDir(gpio_17)) {
            log_event(1, "DETECTED");
        }
        if (sensor_2_state != piGPIOReadDir(gpio_27)) {
            log_event(2, "DETECTED");
        }

        if (sensor_1_state == piGPIOReadDir(gpio_17)) {
            log_event(1, "CLEARED");
        }
        if (sensor_2_state == piGPIOReadDir(gpio_27)) {
            log_event(2, "CLEARED");
        }

        usleep(POLL_INTERVAL * 1000 / HRTIME_PER_SEC);
    }

    piGPIOExit();
    fclose(stdout);
    return 0;
}

void signal_handler(int signum) {
    log_event(0, "SHUTDOWN");
    exit(signum == SIGINT || signum == SIGTERM ? 0 : EXIT_FAILURE);
}

