#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/wait.h>
#include <pthread.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x53
#define POLL_TIMEOUT_MS 50
#define SAMPLE_DELAY_MS 500
#define CSV_FILE "distance_log.csv"

#define LOG_FORMAT "%Y-%m-%T,%.6f\n"

void log_distance(double distance) {
    time_t now = time(NULL);
    struct tm *timeinfo = localtime(&now);
    char time_str[80];
    sprintf(time_str, "%04d-%02d-%02d %02d:%02d:%02d",
            timeinfo->tm_year + 1900, timeinfo->tm_mon + 1, timeinfo->tm_day,
            timeinfo->tm_hour, timeinfo->tm_min, timeinfo->tm_sec);
    FILE *file = fopen(CSV_FILE, "a");
    if (!file) {
        fprintf(stderr, "Error opening CSV file: %s\n", strerror(errno));
        return;
    }
    fprintf(file, LOG_FORMAT "%s,%.6f\n", time_str, distance);
    fclose(file);
}

int i2c_open(int fd, int bus, int addr) {
    int result = open("/dev/i2c-" BUS, O_RDWR);
    if (result < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return result;
    }
    result = ioctl(fd, I2C_SLAVE, addr);
    if (result < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(fd);
        return result;
    }
    return fd;
}

int i2c_write_read(int fd, uint8_t *readbuf, size_t readlen, uint8_t *writebuf, size_t writelen) {
    int result = readwrite(fd, writebuf, writelen, readbuf, readlen);
    if (result < 0) {
        fprintf(stderr, "Error performing I2C write-then-read: %s\n", strerror(errno));
        return result;
    }
    return 0;
}

int main(int argc, char *argv[]) {
    int i2c_fd, ret;
    struct i2c_device *dev;
    uint8_t meas_status;
    double distance;

    i2c_fd = i2c_open(i2c_fd, I2C_BUS, I2C_ADDR);
    if (i2c_fd < 0) {
        return 1;
    }

    dev = i2c_device_alloc(i2c_fd);
    if (!dev) {
        fprintf(stderr, "Error allocating I2C device: %s\n", strerror(errno));
        i2c_close(i2c_fd, dev);
        return 1;
    }

    while (1) {
        ret = i2c_write_read(i2c_fd, &meas_status, 1, NULL, 0);
        if (ret < 0) {
            fprintf(stderr, "Error reading MEAS_STATUS: %s\n", strerror(errno));
            continue;
        }

        if (meas_status & 0x04) { // Check if the sensor is ready
            ret = i2c_write_read(i2c_fd, NULL, 0, (uint8_t *)&distance, sizeof(distance));
            if (ret < 0) {
                fprintf(stderr, "Error reading distance: %s\n", strerror(errno));
                continue;
            }

            if (ret == 0) {
                log_distance(distance);
            }

            usleep(SAMPLE_DELAY_MS * 1000);
        }

        usleep(POLL_TIMEOUT_MS * 1000);
    }

    i2c_device_free(dev);
    close(i2c_fd);

    return 0;
}

