#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <errno.h>

#define I2C_BUS 1
#define I2C_ADDR 0x53
#define ZONE_CONFIG_REG 0x1A
#define ZONE_DATA_REG 0x20
#define ZONE_COUNT 64

void read_zone_data(int file_fd, uint8_t *data) {
    struct i2c_rdwr_ctx ctx;
    ctx.addr = I2C_ADDR;
    ctx.flags = I2C_M_BRIGHT;
    ctx.len = sizeof(data);
    ctx.buf = (void *)data;

    if (ioctl(file_fd, I2C_SLAVE, I2C_BUS) < 0) {
        perror("Failed to set I2C slave address");
        return;
    }

    if (ioctl(file_fd, I2C_MEMREAD, &ctx) < 0) {
        perror("Failed to read from I2C device");
        return;
    }
}

int main(int argc, char *argv[]) {
    int file_fd, ret;
    uint8_t zone_data[ZONE_COUNT];
    long start_time;

    file_fd = open("/dev/i2c-1", O_RDWR);
    if (file_fd < 0) {
        perror("Failed to open /dev/i2c-1");
        exit(EXIT_FAILURE);
    }

    ret = ioctl(file_fd, I2C_SLAVE, I2C_BUS);
    if (ret < 0) {
        perror("Failed to set I2C slave address");
        close(file_fd);
        exit(EXIT_FAILURE);
    }

    // Configure sensor for 8x8 zone grid
    write_config_reg(file_fd, ZONE_CONFIG_REG, 0x00); // Set zone count to 64

    // Read initial zone data
    read_zone_data(file_fd, zone_data);

    while (1) {
        start_time = current_time();
        for (int i = 0; i < ZONE_COUNT; i++) {
            printf("Zone %d: %lu cm\n", i, zone_data[i]);
        }
        usleep(500 * 1000 / HRTIME_PER_SEC); // 500ms delay
    }

    close(file_fd);
    return 0;
}

// Helper function to get current time in microseconds
long current_time() {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) < 0) {
        perror("clock_gettime");
        exit(EXIT_FAILURE);
    }
    return ts.tv_sec * 1000000000 + ts.tv_nsec / 1000;
}

// Helper function to write a register value
void write_config_reg(int file_fd, uint8_t reg, uint8_t value) {
    struct i2c_rdwr_ctx ctx;
    ctx.addr = I2C_ADDR;
    ctx.flags = I2C_M_BRIGHT;
    ctx.len = 1;
    ctx.buf = &value;

    if (ioctl(file_fd, I2C_SLAVE, I2C_BUS) < 0) {
        perror("Failed to set I2C slave address");
        return;
    }

    if (ioctl(file_fd, I2C_MEMWRITE, &ctx) < 0) {
        perror("Failed to write to I2C device");
        return;
    }
}

