#define MAX_RETRIES 3
#define DELAY_BETWEEN_RETRIES 10  // milliseconds

typedef struct {
    int fd;
    int retries;
} I2C_Context;

static int i2c_open(const char *bus, int addr, I2C_Context *ctx) {
    int file = open(bus, O_RDWR);
    if (file < 0) {
        perror("open");
        return -1;
    }
    ctx->fd = file;
    return 0;
}

static int i2c_write(int fd, uint8_t *buf, size_t len) {
    return write(fd, buf, len);
}

static int i2c_read(int fd, uint8_t *buf, size_t len) {
    return read(fd, buf, len);
}

static int i2c_close(int fd, I2C_Context *ctx) {
    close(fd);
    return 0;
}

static int read_distance(I2C_Context *ctx) {
    uint8_t cmd[1];
    cmd[0] = 0x20; // MLX75030 register address for distance measurement

    int ret = 0;
    for (int i = 0; i < MAX_RETRIES; i++) {
        ret = i2c_write(ctx->fd, cmd, 1);
        if (ret == 1) {
            ret = i2c_read(ctx->fd, &cmd[0], 1);
            if (ret == 1) {
                if (cmd[0] == 0x00) {
                    // Distance measurement successful
                    return cmd[0];
                } else {
                    // Error, retry
                    printf("I2C read failed, retrying...\n");
                }
            } else {
                // I2C read timeout, retry
                printf("I2C read timeout, retrying...\n");
            }
        } else {
            // I2C write failed, retry
            printf("I2C write failed, retrying...\n");
        }
        usleep(DELAY_BETWEEN_RETRIES * 1000 / 1000); // Delay between retries
    }

    // If all retries failed, return an error code
    return -1;
}

int main(int argc, char *argv[]) {
    I2C_Context ctx;
    ctx.fd = -1;
    ctx.retries = 0;

    if (argc != 2) {
        fprintf(stderr, "Usage: %s <i2c_bus_number>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    int i2c_bus = atoi(argv[1]);
    if (i2c_bus != I2C_BUS) {
        fprintf(stderr, "Invalid I2C bus number: %d\n", i2c_bus);
        exit(EXIT_FAILURE);
    }

    ctx.fd = i2c_open(NULL, I2C_ADDR, &ctx);
    if (ctx.fd < 0) {
        perror("i2c_open");
        exit(EXIT_FAILURE);
    }

    pigpio_init(1); // Initialize pigpio for PWM control (not needed for I2C)

    while (1) {
        int distance = read_distance(&ctx);
        if (distance == -1) {
            break;
        }

        // Assuming the distance value is in the least significant byte
        uint8_t distance_value = distance;
        printf("Distance: %d\n", distance_value);

        usleep(SAMPLE_INTERVAL * 1000 / 1000); // Wait for next sample
    }

    pigpio_terminate(1); // Terminate pigpio
    i2c_close(ctx.fd, &ctx); // Close I2C handle

    return 0;
}

