#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <time.h>
#include <stdlib.h>
#include <signal.h>

#define I2C_BUS 1
#define I2C_ADDR 0x5A
#define POLL_INTERVAL_MS 500

typedef struct {
    int fd;
    struct i2c_client *client;
} I2C_Context;

static int i2c_open(const char *path, int bus, int addr, struct i2c_client **client)
{
    int ret;
    *client = i2c_alloc(path, bus);
    if (!*client) {
        perror("i2c_alloc");
        return errno;
    }

    ret = i2c_config(*client, I2C_SLAVE_ONLY, addr);
    if (ret < 0) {
        i2c_free(*client);
        *client = NULL;
        perror("i2c_config");
        return errno;
    }

    return 0;
}

static int i2c_close(struct i2c_client *client)
{
    i2c_free(client);
    return 0;
}

static int i2c_write(struct i2c_client *client, uint8_t *buf, size_t count)
{
    return ioctl(client->fd, I2C_SLAVE, client->addr) == client->addr;
}

static int i2c_read(struct i2c_client *client, uint8_t *buf, size_t count)
{
    return ioctl(client->fd, I2C_READ, client->addr, buf, count);
}

static int get_distance(I2C_Context *ctx)
{
    uint8_t status_reg[2];
    uint8_t data_reg[2];

    if (i2c_read(ctx->client, status_reg, 2) != 2 ||
        i2c_read(ctx->client, data_reg, 2) != 2) {
        perror("i2c_read");
        return -1;
    }

    if (!(status_reg[0] & 0x20)) {
        return 0; // No interrupt, skip this cycle
    }

    // Read distance data from the next register
    uint8_t distance_reg[2];
    if (i2c_read(ctx->client, distance_reg, 2) != 2) {
        perror("i2c_read");
        return -1;
    }

    // Convert distance to microseconds
    long distance_us = (long)distance_reg[0] << 8 | distance_reg[1];

    // Format and print the timestamp and distance
    time_t now = time(NULL);
    struct tm *local_time = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", local_time);
    printf("Timestamp: %s, Distance: %lu mm\n", timestamp, distance_us);

    return 0;
}

void signal_handler(int signum)
{
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Exiting...\n");
        i2c_close(ctx->client);
        close(ctx->fd);
        exit(0);
    }
}

int main(int argc, char *argv[])
{
    sigset_t sigset;
    int ret;

    // Initialize signal handlers
    sigset_init(&sigset);
    sigaddset(&sigset, SIGINT);
    sigaddset(&sigset, SIGTERM);
    sigprocmask(SIG_BLOCK, &sigset, NULL);

    I2C_Context ctx = {0};

    if ((ret = i2c_open("/dev/i2c-1", I2C_BUS, I2C_ADDR, &ctx.client)) < 0) {
        perror("i2c_open");
        exit(EXIT_FAILURE);
    }

    ctx.fd = ctx.client->fd;

    while (1) {
        get_distance(&ctx);
        usleep(POLL_INTERVAL_MS * 1000 / 1000);
    }

    return 0;
}

