#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS 1
#define BUZzer_GPIO 22
#define TIME_INTERVAL_MS 500
#define MIN_DISTANCE 100

int main(int argc, char *argv[]) {
    int buzzer_gpio, i2c_fd, error;
    struct i2c_client *client;
    struct vl53l1x_config config;
    float distance;

    buzzer_gpio = GPIO_NUM(BUZzer_GPIO);
    if (pigpio_init(1) < 0) {
        perror("Failed to initialize pigpio");
        return EXIT_FAILURE;
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus 1");
        pigpio_shutdown();
        return EXIT_FAILURE;
    }

    client = i2c_client_new(i2c_fd, 0x4A); // VL53L1X address
    if (!client) {
        perror("Failed to create i2c client");
        close(i2c_fd);
        pigpio_shutdown();
        return EXIT_FAILURE;
    }

    config.mode = VL53L1X_MODE_CONTINUOUS;
    config.range = VL53L1X_RANGE_MM;
    config.distance_unit = VL53L1X_DISTANCE_MM;
    config.trigger_source = VL53L1X_TRIGGER_EXTERNAL;
    config.external_trigger_source = VL53L1X_EXTERNAL_GPIO;
    config.external_trigger_gpio = buzzer_gpio;

    if (i2c_write_reg8(client, VL53L1X_REG_CONFIG, config.mode) < 0) {
        error = ioctl(i2c_fd, I2C_SLAVE, client->addr);
        if (error < 0) {
            perror("Failed to set I2C slave address");
            i2c_client_free(client);
            close(i2c_fd);
            pigpio_shutdown();
            return EXIT_FAILURE;
        }
        printf("Failed to write configuration register\n");
    }

    while (1) {
        distance = i2c_read_word_data(client, VL53L1X_REG_DISTANCE);
        if (distance < MIN_DISTANCE) {
            printf("Distance: %.2f mm\n", distance);
            pigpio_set_mode(buzzer_gpio, PI_OUTPUT);
            pigpio_sound(buzzer_gpio, 1000); // 1000 ms beep
            pigpio_sound(buzzer_gpio, 1000); // 1000 ms off
            pigpio_set_mode(buzzer_gpio, PI_NOMODE);
        }

        usleep(TIME_INTERVAL_MS * 1000 / HRTIME_PER_SEC);
    }

    i2c_client_free(client);
    close(i2c_fd);
    pigpio_shutdown();
    return EXIT_SUCCESS;
}

