#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 17
#define LOG_FILE "sensor_data.log"
#define TIMEOUT_MS 50
#define MAX_DISTANCE 400
#define MIN_DISTANCE 2
#define LOG_ENTRY_SIZE 128

void log_entry(const char *entry) {
    int fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (fd < 0) {
        perror("Failed to open log file");
        return;
    }
    if (write(fd, entry, strlen(entry)) != strlen(entry)) {
        perror("Failed to write to log file");
    }
    close(fd);
}

int main(int argc, char *argv[]) {
    pigpio_init(5); // Initialize pigpio with 5 seconds timeout

    if (pigpio_init(5000) < 0) {
        perror("Failed to initialize pigpio");
        return EXIT_FAILURE;
    }

    struct itimerspec timerspec = {200000}; // 200ms interval
    epoll_ctl(epoll_create1(), EPOLL_CTL_ADD, SERVO_PIN, (void *)1, 0, 0);

    char log_entry[LOG_ENTRY_SIZE];
    while (1) {
        struct timespec timeout;
        timeout.tv_sec = 0;
        timeout.tv_nsec = 1000000; // 1ms timeout

        int r = epoll_wait(epoll_create1(), (struct epoll_event *)NULL, 1, timeout.tv_sec, timeout.tv_nsec);
        if (r == -1) {
            perror("epoll_wait");
            continue;
        }

        if (epoll_event_data((epoll_event *)epoll_wait_events[0]) == (void *)1) {
            // Servo control event
            int servo_state = pigpioGetMode(SERVO_PIN);
            if (servo_state == PI_CONTINUOUS_OUTPUT) {
                // Set servo angle based on distance
                double distance = 0.0;
                int echo_time = 0;
                int trigger_time = 0;

                // Send trigger pulse
                pigpioOutput(TRIGGER_PIN, PI_HIGH);
                usleep(10000); // 10µs trigger pulse

                // Read echo pulse
                echo_time = pigpioRead(ECHO_PIN);
                trigger_time = pigpioRead(TRIGGER_PIN);

                // Calculate distance
                distance = (echo_time * 1000000) / 2;

                // Check for timeout
                if (echo_time < 50 || echo_time > 50000) {
                    log_entry("Sensor timeout\n");
                    distance = -1; // Sentinel error value
                }

                // Map distance to servo angle
                double angle = (distance - MIN_DISTANCE) * 90.0 / (MAX_DISTANCE - MIN_DISTANCE);
                if (angle < -90.0) angle = -90.0;
                if (angle > 90.0) angle = 90.0;

                // Set servo angle
                pigpioSetMode(SERVO_PIN, PI_CONTINUOUS_OUTPUT);
                pigpioWrite(SERVO_PIN, angle);

                // Log successful reading
                char timestamp[64];
                time_t now = time(NULL);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
                log_entry(strftime(log_entry, LOG_ENTRY_SIZE, "Distance: %d cm, Angle: %f\n", distance, angle));
            }
        }
    }

    // Release resources on exit
    pigpio_terminate(pigpio_get_pi);
    close(epoll_fd);
    close(fd);

    return EXIT_SUCCESS;
}
```

This code initializes the pigpio library, sets up an epoll event to monitor the servo control pin, and continuously reads distances using an HC-SR04 sensor connected to GPIO 23 (trigger) and GPIO 24 (echo). The distances are mapped to servo angles between -90° and +90°, and the servo is set to the corresponding angle. Successful readings are logged to a file named `sensor_data.log` with a timestamp. The loop runs every 200ms, and the program exits cleanly when interrupted (SIGINT or SIGTERM).

