#define I2C_BUS 1
#define BUZZER_GPIO 23
#define DISTANCE_LOG_QUEUE 12345
#define TIMEOUT 50

struct timespec start_time;
struct timespec end_time;

void *read_distance(void *arg) {
    struct i2c_rdwr_ctx ctx;
    int fd;
    long distance;

    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("open /dev/i2c-1");
        return NULL;
    }

    ctx.fd = fd;
    ctx.control = (u8 *)"0x60"; // VL53L1X register address
    ctx.len = 1;
    ctx.buf = (u8 *)"0x00"; // Command to read distance

    clock_gettime(CLOCK_REALTIME, &start_time);

    if (i2c_transfer(&ctx, (void *)"0x00", 1, TIMEOUT) < 0) {
        perror("i2c_transfer failed");
        close(fd);
        return NULL;
    }

    clock_gettime(CLOCK_REALTIME, &end_time);
    uint64_t elapsed_time = end_time.tv_sec - start_time.tv_sec + (end_time.tv_nsec - start_time.tv_nsec) / 1e9;

    if (elapsed_time > TIMEOUT) {
        fprintf(stderr, "I2C communication took too long.\n");
        close(fd);
        return NULL;
    }

    distance = ((long)ctx.buf[0] << 8) | ctx.buf[1];

    if (distance < 100) {
        gpioOutput(BUZZER_GPIO, 1); // Activate buzzer
    }

    close(fd);
    return NULL;
}

