void i2c_init(void) {
    int file;
    char buf[2];

    file = open("/dev/i2c-1", O_RDWR);
    if (file < 0) {
        perror("open /dev/i2c-1");
        exit(EXIT_FAILURE);
    }

    if (ioctl(file, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(file);
        exit(EXIT_FAILURE);
    }

    i2c_ctx.file = file;
    i2c_ctx.client = i2c_get_device(&i2c_ctx.file, I2C_ADDR);
    if (!i2c_ctx.client) {
        perror("i2c_get_device");
        close(file);
        exit(EXIT_FAILURE);
    }

    // Software reset
    write(i2c_ctx.file, &0x00, 1);
    usleep(10000);

    // Wait for boot
    write(i2c_ctx.file, &0x01, 1);
    usleep(10000);

    // Start ranging
    write(i2c_ctx.file, &0x02, 1);
    usleep(10000);

    // Read 16-bit distance
    read(i2c_ctx.file, buf, 1);
    i2c_ctx.client->write(0, buf);

    close(file);
}

