#define TRIG_LEVEL LOW
#define ECHO_LEVEL HIGH
#define SAMPLE_INTERVAL_MS 200
#define SAMPLE_RATE 5
#define LOG_FILE "distance_log.txt"
#define MAX_REJECTIONS 10

// Function to handle the falling edge interrupt
void echo_callback(gp_gpio_ev_t *ev) {
    if (ev->ev_type == GP_GPIO_EV_FALLING_EDGE) {
        uint32_t tick = gp_get_current_tick();
        uint32_t rising_tick = gp_get_previous_tick();
        uint32_t duration = tick - rising_tick;

        if (duration < 100 || duration > 30000) {
            fprintf(stderr, "Warning: Invalid pulse duration detected: %lu us\n", duration);
        }

        // Log the timestamp and distance
        time_t now = time(NULL);
        char timestamp[80];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%T", localtime(&now));
        FILE *log_file = fopen(LOG_FILE, "a");
        if (log_file) {
            fprintf(log_file, "%s, %lu\n", timestamp, duration);
            fclose(log_file);
        }
    }
}

int main(int argc, char *argv[]) {
    int ret;
    gp_gpio_init();

    if (gp_gpio_pin_config(TRIG_PIN, GP_GPIO_OUTPUT, TRIG_LEVEL) < 0) {
        fprintf(stderr, "Failed to configure TRIG pin\n");
        return EXIT_FAILURE;
    }

    if (gp_gpio_pin_config(ECHO_PIN, GP_GPIO_INPUT, ECHO_LEVEL, GP_GPIO_PULL_DOWN) < 0) {
        fprintf(stderr, "Failed to configure ECHO pin\n");
        return EXIT_FAILURE;
    }

    // Set up the timer for 200ms intervals
    gp_timer_t timer;
    gp_timer_init(&timer, gp_timer_mode_one_shot, 200000);
    gp_timer_set_callback(&timer, echo_callback);
    gp_timer_start(&timer);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        usleep(SAMPLE_INTERVAL_MS * 1000 / SAMPLE_RATE);
    }

    // Clean shutdown
    fclose(stdout);
    gp_gpio_cleanup();
    gp_timer_cancel(&timer);
    return 0;

signal_handler:
    fprintf(stderr, "Received signal, performing clean shutdown...\n");
    fclose(stdout);
    gp_gpio_cleanup();
    gp_timer_cancel(&timer);
    return 0;
}

void signal_handler(int signum) {
    fprintf(stderr, "Received signal %d, performing clean shutdown...\n", signum);
    fclose(stdout);
    gp_gpio_cleanup();
    gp_timer_cancel(&timer);
    exit(0);
}

