#define LOG_FILE "parking_log.txt"

typedef struct {
    int fd;
    struct i2c_client *client;
} i2c_context_t;

void log_gate_state(const char *state, double distance) {
    time_t now = time(NULL);
    char timestamp[20];
    sprintf(timestamp, "%ld", (long)now);
    char log_entry[100];
    sprintf(log_entry, "%s %s %f\n", timestamp, state, distance);
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp) {
        fputs(log_entry, fp);
        fclose(fp);
    }
}

int verify_vl53l1x_model(i2c_context_t *ctx) {
    uint8_t model_id[2];
    ssize_t read_bytes = read(ctx->fd, model_id, sizeof(model_id));
    if (read_bytes != sizeof(model_id)) {
        syslog(LOG_ERR, "Failed to read VL53L1X model ID");
        return 0;
    }
    if (model_id[0] != 0x5A || model_id[1] != 0x01) {
        syslog(LOG_ERR, "Invalid VL53L1X model ID");
        return 0;
    }
    return 1;
}

int init_vl53l1x(i2c_context_t *ctx) {
    int ret;
    ret = ioctl(ctx->fd, I2C_SLAVE, VL53L1X_ADDR);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to set VL53L1X slave address");
        return 0;
    }
    ret = ioctl(ctx->fd, I2C_REQUEST_SLAVE);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to request VL53L1X");
        return 0;
    }
    ret = ioctl(ctx->fd, I2C_READ_I2C_BLOCK, VL53L1X_MODEL_ID_OFFSET);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to read VL53L1X model ID");
        return 0;
    }
    if (!verify_vl53l1x_model(ctx)) {
        syslog(LOG_ERR, "VL53L1X model ID verification failed");
        return 0;
    }
    return 1;
}

int setup_servo(void) {
    int ret;
    ret = ioctl(SERVO_PIN, WHO_AM_I);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to identify servo");
        return 0;
    }
    ret = ioctl(SERVO_PIN, SET_PWM_RANGE, 0x0000);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to set servo PWM range");
        return 0;
    }
    ret = ioctl(SERVO_PIN, SET_PWM_RESOLUTION, 16);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to set servo PWM resolution");
        return 0;
    }
    return 1;
}

int main(int argc, char *argv[]) {
    i2c_context_t i2c_ctx;
    pthread_t log_thread;

    if (argc < 2) {
        fprintf(stderr, "Usage: %s [start|stop]\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    if (strcmp(argv[1], "start") == 0) {
        if (setup_servo() && init_vl53l1x(&i2c_ctx) && signal(SIGINT, sigterm_handler) && signal(SIGTERM, sigterm_handler)) {
            while (1) {
                int distance;
                int state = "open";
                int shutdown_pin = 1;

                // Read distance from VL53L1X
                ret = ioctl(i2c_ctx.fd, I2C_READ_I2C_BLOCK, VL53L1X_DISTANCE_OFFSET);
                if (ret < 0) {
                    syslog(LOG_ERR, "Failed to read distance from VL53L1X");
                    continue;
                }
                distance = ntohl(ret);

                // Check if object is within 50cm and less than 60cm
                if (distance < 50 && distance > 60) {
                    state = "closed";
                }

                // Log gate state and distance
                log_gate_state(state, distance);

                // Write state to shutdown pin
                write(SHUTDOWN_PIN, &shutdown_pin, 1);

                // Sleep for a short duration to avoid busy-waiting
                usleep(100000);
            }
        } else {
            syslog(LOG_ERR, "Failed to start the parking gate program");
        }
    } else if (strcmp(argv[1], "stop") == 0) {
        // Clean up resources
        close(i2c_ctx.fd);
        close(SERVO_PIN);
        pthread_join(log_thread, NULL);
        syslog(LOG_INFO, "Parking gate program stopped");
    } else {
        fprintf(stderr, "Invalid command. Use 'start' or 'stop'.\n");
        exit(EXIT_FAILURE);
    }

    return 0;
}

void sigterm_handler(int sig) {
    syslog(LOG_INFO, "Received SIGTERM, shutting down gracefully...");
    // Add any cleanup code here if needed
    exit(EXIT_SUCCESS);
}

