#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <libgpiod/gpio.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SENSOR_ADDRESS 0x5A
#define RANGE_START_REGISTER 0x0C
#define RANGE_RESULT_REGISTER 0x0D
#define GPIO_OPEN_GATE 18
#define GPIO_CLOSE_GATE 19
#define LOG_FILE "gate_events.log"
#define TIMEOUT 500 * 1000 // 500ms

void sigint_handler(int signum) {
    close(gpio_fd);
    gpio_set_dir(GPIO_OPEN_GATE, 0);
    gpio_set_dir(GPIO_CLOSE_GATE, 1);
    close(log_fd);
    pigpio_terminate(1);
    exit(0);
}

void sigterm_handler(int signum) {
    sigint_handler(signum);
}

int main(int argc, char *argv[]) {
    int gpio_fd, log_fd;
    struct i2c_rdwr_t i2c_wr;
    struct i2c_rdwr_t i2c_rd;
    int sensor_present = 0;
    int sensor_error = 0;
    time_t now;
    struct tm *local_time;

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    gpio_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (gpio_fd == -1) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    sensor_present = pigpio_init();
    if (sensor_present < 0) {
        sensor_error = 1;
        fprintf(log_fd, "Error initializing pigpio\n");
        pigpio_terminate(1);
        close(gpio_fd);
        exit(EXIT_FAILURE);
    }

    i2c_wr.address = SENSOR_ADDRESS;
    i2c_wr.data = (uint8_t *)0x01; // Soft reset
    i2c_wr.len = 1;
    if (libgpiod_i2c_transfer(I2C_BUS, &i2c_wr, 1, &i2c_rd) != 0) {
        sensor_error = 1;
        fprintf(log_fd, "Error performing soft reset\n");
        pigpio_terminate(1);
        close(gpio_fd);
        exit(EXIT_FAILURE);
    }

    i2c_wr.address = SENSOR_ADDRESS;
    i2c_wr.data = (uint8_t *)0x02; // Configure timing budget
    i2c_wr.len = 1;
    if (libgpiod_i2c_transfer(I2C_BUS, &i2c_wr, 1, &i2c_rd) != 0) {
        sensor_error = 1;
        fprintf(log_fd, "Error configuring timing budget\n");
        pigpio_terminate(1);
        close(gpio_fd);
        exit(EXIT_FAILURE);
    }

