#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS 1
#define MOTOR_FORWARD 17
#define MOTOR_BACKWARD 18
#define TRIGGER_PIN 24

#define MAX_RETRIES 10
#define RETRY_DELAY_MS 100

void i2c_write(int file, uint8_t *data, size_t len) {
    int ret = write(file, data, len);
    if (ret < 0) {
        perror("i2c_write");
        exit(EXIT_FAILURE);
    }
}

int i2c_read(int file, uint8_t *data, size_t len) {
    int ret = read(file, data, len);
    if (ret < 0) {
        perror("i2c_read");
        exit(EXIT_FAILURE);
    }
    return ret;
}

void setup_pigpio() {
    if (piGPIO_init() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(EXIT_FAILURE);
    }
}

void setup_i2c() {
    int file = open("/dev/i2c-1", O_RDWR);
    if (file < 0) {
        perror("open /dev/i2c-1");
        exit(EXIT_FAILURE);
    }

    if (ioctl(file, I2C_SLAVE, 0x22) < 0) {
        int retries = 0;
        while (retries < MAX_RETRIES) {
            sleep(RETRY_DELAY_MS / 1000.0);
            retries++;
            if (ioctl(file, I2C_SLAVE, 0x22) == 0)
                break;
        }
        if (retries == MAX_RETRIES) {
            fprintf(stderr, "Failed to find VL53L1X sensor after %d retries\n", MAX_RETRIES);
            exit(EXIT_FAILURE);
        }
    }
}

void distance_callback(const struct i2c_rdwr_req *req) {
    uint8_t status;
    uint16_t distance;

    i2c_read(req->fd, &status, 1);
    if (status & 0x01) { // Data-ready bit set
        i2c_read(req->fd, &distance, 2);
        printf("Distance: %d mm\n", distance);

        if (distance < 100) {
            gpioOutput(MOTOR_FORWARD, HIGH);
        } else if (distance > 300) {
            gpioOutput(MOTOR_BACKWARD, HIGH);
        } else {
            gpioOutput(MOTOR_FORWARD, LOW);
        }
    }
}

int main(int argc, char *argv[]) {
    setup_pigpio();
    setup_i2c();

    gpioSetup(MOTOR_FORWARD, GPIO_OUTPUT);
    gpioSetup(MOTOR_BACKWARD, GPIO_OUTPUT);
    gpioSetup(TRIGGER_PIN, GPIO_INPUT | GPIO_TRIGGER);

    gpioRegisterInterrupt(TRIGGER_PIN, distance_callback, NULL, NULL);

    while (1) {
        sleep(1);
    }

    gpioDisable(MOTOR_FORWARD);
    gpioDisable(MOTOR_BACKWARD);
    piGPIO_cleanup();
    close(open("/dev/i2c-1", O_RDWR));
    exit(EXIT_SUCCESS);
}

