#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS "/dev/i2c-1"
#define SDA_PIN 2
#define SCL_PIN 3
#define LED_GPIO 17
#define LED2_GPIO 18
#define LED3_GPIO 27
#define LED4_GPIO 22

#define PROXIMITY_INTERVAL_MS 50
#define REG_CHECK_VALUE 0x00

void log_event(const char *message) {
    char timestamp[20];
    time_t now = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    fprintf(stderr, "[%s] %s\n", timestamp, message);
}

int main(int argc, char *argv[]) {
    int i2c_fd, ret;
    gpioSetup(LED_GPIO, PI_OUTPUT);
    gpioSetup(LED2_GPIO, PI_OUTPUT);
    gpioSetup(LED3_GPIO, PI_OUTPUT);
    gpioSetup(LED4_GPIO, PI_OUTPUT);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    ret = ioctl(i2c_fd, I2C_SLAVE, 0x1A);
    if (ret < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    log_event("MPR121 sensor initialized.");

    while (1) {
        ret = read(i2c_fd, &reg_check_value, 1);
        if (ret != 1) {
            log_event("Failed to read from MPR121 sensor.");
            close(i2c_fd);
            gpioReset(LED_GPIO);
            gpioReset(LED2_GPIO);
            gpioReset(LED3_GPIO);
            gpioReset(LED4_GPIO);
            exit(EXIT_SUCCESS);
        }

        if (reg_check_value != 0x00) {
            log_event("MPR121 sensor detected.");
            gpioReset(LED_GPIO);
            gpioReset(LED2_GPIO);
            gpioReset(LED3_GPIO);
            gpioReset(LED4_GPIO);
        }

        ret = read(i2c_fd, &proximity_status, 12);
        if (ret != 12) {
            log_event("Failed to read from MPR121 sensor.");
            close(i2c_fd);
            gpioReset(LED_GPIO);
            gpioReset(LED2_GPIO);
            gpioReset(LED3_GPIO);
            gpioReset(LED4_GPIO);
            exit(EXIT_FAILURE);
        }

        for (int i = 0; i < 12; i++) {
            if (proximity_status[i] & 0x01) {
                gpioSet(LED_GPIO, 1);
                gpioSet(LED2_GPIO, 1);
                gpioSet(LED3_GPIO, 1);
                gpioSet(LED4_GPIO, 1);
                log_event("Proximity detected on electrode %d.", i + 1);
                usleep(PROXIMITY_INTERVAL_MS * 1000 / 1000); // Convert ms to us
            } else {
                gpioSet(LED_GPIO, 0);
                gpioSet(LED2_GPIO, 0);
                gpioSet(LED3_GPIO, 0);
                gpioSet(LED4_GPIO, 0);
            }
        }

        usleep(PROXIMITY_INTERVAL_MS * 1000 / 1000); // Convert ms to us
    }

    close(i2c_fd);
    gpioReset(LED_GPIO);
    gpioReset(LED2_GPIO);
    gpioReset(LED3_GPIO);
    gpioReset(LED4_GPIO);

    log_event("Program terminated.");
    return 0;
}

