typedef struct {
    int file;
    int fd;
    struct i2c_client *client;
} I2C_Context;

void i2c_init(I2C_Context *ctx) {
    ctx->file = open(ctx->bus == 1 ? "/dev/i2c-1" : "/dev/i2c-2", O_RDWR);
    if (ctx->file < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    ctx->fd = fileno(ctx->file);
    ctx->client = i2c_alloc(ctx->fd);
    if (!ctx->client) {
        perror("Failed to allocate I2C client");
        close(ctx->file);
        exit(EXIT_FAILURE);
    }

    if (ioctl(ctx->fd, I2C_SLAVE, ctx->addr) < 0) {
        perror("Failed to set I2C slave address");
        close(ctx->file);
        i2c_free(ctx->client);
        exit(EXIT_FAILURE);
    }
}

void i2c_release(I2C_Context *ctx) {
    i2c_free(ctx->client);
    close(ctx->fd);
    if (ctx->file) {
        close(ctx->file);
    }
}

void write_i2c(I2C_Context *ctx, uint8_t *data, size_t len) {
    if (write(ctx->fd, data, len) != len) {
        perror("Failed to write to I2C bus");
        exit(EXIT_FAILURE);
    }
}

void read_i2c(I2C_Context *ctx, uint8_t *data, size_t len) {
    if (read(ctx->fd, data, len) != len) {
        perror("Failed to read from I2C bus");
        exit(EXIT_FAILURE);
    }
}

int mpr121_read_device_id(I2C_Context *ctx) {
    uint8_t id[2];
    read_i2c(ctx, id, sizeof(id));
    if (id[0] != 0x1A && id[1] != 0x01) {
        return 0; // Device not found
    }
    return 1;
}

