    // This is a simplified example, actual configuration would involve multiple reads and writes
    write_i2c(ctx, 0x00, 0x01); // FFI
    write_i2c(ctx, 0x01, 0x01); // SFI
    write_i2c(ctx, 0x02, 0x01); // ESI
    write_i2c(ctx, 0x03, 0x01); // Debounce
    write_i2c(ctx, 0x04, 0x01); // AFE
    write_i2c(ctx, 0x05, 0x01); // Baseline filtering
}

