#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define SPEED_OF_SOUND 343
#define MAX_DISTANCE 400
#define MIN_DISTANCE 2
#define LOG_FILE "distance_log.txt"
#define LOG_INTERVAL 1000

volatile sig_atomic_t sig_interrupt_flag = 0;

void signal_handler(int signum) {
    sig_interrupt_flag = 1;
}

void setup_gpio(void) {
    int ret;

    ret = gpiod_plugin_init();
    if (ret < 0) {
        perror("Failed to initialize gpiod");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_plugin_add_device(TRIGGER_PIN, GPIOD_MODE_OUTPUT, NULL);
    if (ret < 0) {
        perror("Failed to add trigger pin as output");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_plugin_add_device(ECHO_PIN, GPIOD_MODE_INPUT, NULL);
    if (ret < 0) {
        perror("Failed to add echo pin as input");
        exit(EXIT_FAILURE);
    }
}

void read_distance(void) {
    uint32_t echo_time, start_time;
    float distance;

    echo_time = read_gpio(ECHO_PIN);
    start_time = read_gpio(TRIGGER_PIN);

    if (echo_time == 0) {
        printf("Error: Echo pin not detected.\n");
        return;
    }

    uint32_t pulse_width = echo_time - start_time;
    distance = (pulse_width * SPEED_OF_SOUND) / 2;

    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        printf("Error: Distance out of range (2-400 cm).\n");
    } else {
        write_log(timestamp(), distance);
    }
}

void write_log(const char *timestamp, float distance) {
    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    struct tm *time_struct = localtime(&now);
    char time_str[80];
    sprintf(time_str, "%04d-%02d-%02dT%02d:%02d:%02d",
            time_struct->tm_year + 1900, time_struct->tm_mon + 1,
            time_struct->tm_mday, time_struct->tm_hour, time_struct->tm_min,
            time_struct->tm_sec);

    fprintf(file, "%s,%f\n", time_str, distance);
    fclose(file);
}

int main(int argc, char *argv[]) {
    setup_gpio();

    signal(SIGINT, signal_handler);

    while (!sig_interrupt_flag) {
        read_distance();
        usleep(LOG_INTERVAL * 1000); // Sleep for LOG_INTERVAL ms
    }

    close(stdout);
    fclose(stdout);

    gpiod_plugin_exit();
    return 0;
}

