#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/epoll.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/epoll.h>
#include <linux/gpio.h>
#include <pigpio.h>

#define TRIG_PIN 17
#define ECHO_PIN 18
#define DIVIDER_RES 2000
#define LOG_FILE "distance_log.txt"
#define LOG_INTERVAL 1000  // 1 second
#define MIN_PULSE_WIDTH 58e-6  // 58 µs
#define MAX_PULSE_WIDTH 25e-3  // 25 ms

#define BUFFER_SIZE 1024
char log_buffer[BUFFER_SIZE];
int log_fd;

void setup_gpio(void) {
    if (gpio_init() < 0) {
        perror("Failed to initialize GPIO");
        exit(EXIT_FAILURE);
    }

    gpioSetMode(ECHO_PIN, GPIO_OUTPUT);
    gpioSetMode(TRIG_PIN, GPIO_OUTPUT);
    gpioWrite(TRIG_PIN, LOW);
    gpioWrite(ECHO_PIN, LOW);
}

void setup_interrupt(void) {
    struct sigaction sa;
    sa.sa_handler = handle_interrupt;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    epoll_ctl(EPOLL_CREATE, EPOLLIN, TRIG_PIN, &log_fd);
}

void handle_interrupt(int signum) {
    gpioWrite(TRIG_PIN, LOW);
    gpioWrite(ECHO_PIN, LOW);
    gpioWrite(TRIG_PIN, HIGH);
    usleep(10000);
    gpioWrite(TRIG_PIN, LOW);
}

void read_distance(void) {
    uint32_t echo_time;
    gpioRead(ECHO_PIN, &echo_time);

    uint32_t pulse_width = echo_time - (gpioRead(TRIG_PIN, &echo_time) << 15);

    if (pulse_width > MIN_PULSE_WIDTH && pulse_width < MAX_PULSE_WIDTH) {
        double distance = pulse_width * 0.0343 / 2;
        char timestamp[32];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        snprintf(log_buffer, BUFFER_SIZE, "%s, %f\n", timestamp, distance);
        log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
        if (log_fd == -1) {
            perror("Failed to open log file");
            exit(EXIT_FAILURE);
        }
        write(log_fd, log_buffer, strlen(log_buffer));
        close(log_fd);
    }
}

int main(void) {
    setup_gpio();
    setup_interrupt();

    while (1) {
        read_distance();
        usleep(LOG_INTERVAL * 1000);
    }

    return 0;
}

