#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <syslog.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x2A
#define GPIO_PIN 27

#define LOG_FACILITY LOG_USER
#define LOG_PRIORITY LOG_INFO

void log_message(const char *format, ...) {
    char buffer[1024];
    vafmt(buffer, format, 0, 0);
    syslog(LOG_FACILITY, LOG_PRIORITY, "%s", buffer);
}

int main() {
    int i2c_fd, gpio_fd;
    struct i2c_client *client;
    int sensor_status;
    double distance;

    // Initialize syslog
    openlog("vl53l1x_reader", LOG_PID | LOG_PERR, LOG_USER);

    // Initialize pigpio
    if (piGPIO_init() < 0) {
        log_message(LOG_ERR, "Failed to initialize pigpio");
        return -1;
    }

    // Initialize I2C
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        log_message(LOG_ERR, "Failed to open I2C device");
        piGPIO_shutdown();
        return -1;
    }

    client = i2c_client_new(i2c_fd, I2C_BUS);
    if (!client) {
        log_message(LOG_ERR, "Failed to create I2C client");
        close(i2c_fd);
        piGPIO_shutdown();
        return -1;
    }

    // Enable XSHUT pin
    if (write(client->fd, 0x01, 1) != 1) {
        log_message(LOG_ERR, "Failed to write to XSHUT pin");
        close(i2c_fd);
        i2c_client_free(client);
        piGPIO_shutdown();
        return -1;
    }

    // Read distance every 100ms
    while (1) {
        if (read(client->fd, &distance, sizeof(distance)) != sizeof(distance)) {
            log_message(LOG_ERR, "Failed to read distance");
            continue;
        }

        sensor_status = read(client->fd, &distance, sizeof(distance));
        if (sensor_status != sizeof(distance)) {
            log_message(LOG_ERR, "Failed to read sensor status");
            continue;
        }

        // Log the reading to syslog
        log_message(LOG_INFO, "Distance: %.2f mm, Sensor Status: %d", distance, sensor_status);

        // Sleep for 100ms
        usleep(100000);
    }

    // Clean up
    close(i2c_fd);
    i2c_client_free(client);
    piGPIO_shutdown();

    // Exit cleanly
    log_message(LOG_INFO, "Exiting...");
    return 0;
}

