#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <libgpiod/gpio.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x5A
#define GATE_PIN 24
#define LOG_FILE "gate_log.txt"
#define LOG_INTERVAL_MS 100
#define MAX_LOG_ENTRIES 1000

typedef struct {
    time_t timestamp;
    int distance_cm;
    int gate_state;
} LogEntry;

static LogEntry log_entries[MAX_LOG_ENTRIES];
static int log_entries_written = 0;
static int log_file_fd = -1;

void log_entry(const char *message) {
    time_t current_time = time(NULL);
    LogEntry entry;
    entry.timestamp = current_time;
    entry.distance_cm = get_distance_cm();
    entry.gate_state = get_gate_state();
    strncat(log_entries[log_entries_written].timestamp,
            "%ld ", (long)current_time);
    strncat(log_entries[log_entries_written].distance_cm,
            "%d ", distance_cm);
    strncat(log_entries[log_entries_written].gate_state,
            (gate_state ? "OPEN" : "CLOSED"));
    log_entries_written++;
    if (log_entries_written >= MAX_LOG_ENTRIES) {
        log_entries_written = 0;
    }
    write(log_file_fd, &log_entries[log_entries_written - 1],
          sizeof(LogEntry));
}

int init_log_file() {
    log_file_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_file_fd == -1) {
        return errno;
    }
    return 0;
}

void close_log_file() {
    if (log_file_fd != -1) {
        close(log_file_fd);
        log_file_fd = -1;
    }
}

void sigint_handler(int sig) {
    close_log_file();
    close(log_file_fd);
    gpio_output_set(GATE_PIN, 0);
    sleep(1);
    gpio_output_set(GATE_PIN, 1);
    exit(0);
}

void sigterm_handler(int sig) {
    sigint_handler(sig);
}

int main(int argc, char *argv[]) {
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    int i2c_fd, ret;
    struct i2c_client *client;
    int vl53l1x_address = VL53L1X_ADDR;

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd == -1) {
        perror("Failed to open I2C bus");
        return -1;
    }

    client = i2c_client_new(i2c_fd, vl53l1x_address);
    if (!client) {
        perror("Failed to create I2C client");
        close(i2c_fd);
        return -1;
    }

    if (gpio_init() < 0) {
        perror("Failed to initialize GPIO");
        i2c_client_free(client);
        close(i2c_fd);
        return -1;
    }

    if (gpio_output_init(GATE_PIN, 1) < 0) {
        perror("Failed to initialize GPIO for gate actuator");
        i2c_client_free(client);
        close(i2c_fd);
        return -1;
    }

    if (gpio_request(GATE_PIN, "gate_actuator") < 0) {
        perror("Failed to request GPIO pin for gate actuator");
        i2c_client_free(client);
        close(i2c_fd);
        return -1;
    }

    if (gpio_direction_output(GATE_PIN) < 0) {
        perror("Failed to set GPIO pin direction for gate actuator");
        i2c_client_free(client);
        close(i2c_fd);
        return -1;
    }

    if (gpio_set_level(GATE_PIN, 0) < 0) {
        perror("Failed to set initial state of gate actuator");
        i2c_client_free(client);
        close(i2c_fd);
        return -1;
    }

    while (1) {
        ret = i2c_transfer(client, 0x5A, 0x00, 0x01, 1000, 0);
        if (ret < 0) {
            perror("I2C transfer failed");
            log_entry("I2C transfer failed");
            continue;
        }

        int16_t distance_mm = i2c_read_byte_data(client, 0x5A, 0x00);
        int distance_cm = distance_mm * 10;

        if (distance_cm < 20) {
            gpio_output_set(GATE_PIN, 1);
            log_entry("Distance: %d cm, Gate: OPEN", distance_cm);
        } else {
            gpio_output_set(GATE_PIN, 0);
            log_entry("Distance: %d cm, Gate: CLOSED", distance_cm);
        }

        log_entry("Time: %s, Distance: %d cm, Gate: %s",
                ctime(&log_entries[log_entries_written - 1].timestamp),
                distance_cm,
                (log_entries[log_entries_written - 1].gate_state == 'O' ? "OPEN" : "CLOSED"));

        usleep(LOG_INTERVAL_MS / 1000);
    }

    close(i2c_fd);
    i2c_client_free(client);
    gpio_output_disable(GATE_PIN);
    gpio_output_disable(VL53L1X_ADDR);
    gpio_cleanup();
    close_log_file();

    return 0;
}

