#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <signal.h>
#include <libgpiod.h>
#include <servo.h>

#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 18
#define LOG_FILE "distance_log.csv"
#define SAMPLE_SIZE 5
#define TIMEOUT_US 30000
#define TRIG_US 10000

volatile sig_atomic_t stop_signal = 0;

struct servo_handle servo_handle;

void signal_handler(int signum) {
    stop_signal = 1;
}

void setup_gpio(void) {
    if (gpio_init() < 0) {
        perror("Failed to initialize GPIO");
        exit(EXIT_FAILURE);
    }

    gpio_output_init(TRIGGER_PIN);
    gpio_output_init(ECHO_PIN);
    gpio_output_init(SERVO_PIN);

    if (gpio_add_terminal_output(TRIGGER_PIN) < 0) {
        perror("Failed to add output to TRIGGER_PIN");
        exit(EXIT_FAILURE);
    }

    if (gpio_add_terminal_output(ECHO_PIN) < 0) {
        perror("Failed to add output to ECHO_PIN");
        exit(EXIT_FAILURE);
    }

    if (gpio_add_terminal_output(SERVO_PIN) < 0) {
        perror("Failed to add output to SERVO_PIN");
        exit(EXIT_FAILURE);
    }

    if (gpio_set_level(TRIGGER_PIN, 0) < 0) {
        perror("Failed to set TRIGGER_PIN level");
        exit(EXIT_FAILURE);
    }

    if (gpio_set_level(ECHO_PIN, 0) < 0) {
        perror("Failed to set ECHO_PIN level");
        exit(EXIT_FAILURE);
    }
}

void interrupt_callback(void *data) {
    static volatile sig_atomic_t pulse_width = 0;
    static volatile sig_atomic_t new_pulse = 0;

    if (gpio_get_level(ECHO_PIN) == 0) {
        return;
    }

    pulse_width = gpio_get_level(ECHO_PIN);
    new_pulse = 1;

    if (pulse_width == 0) {
        printf("-1.0\t");
    } else {
        double distance = (pulse_width * 58.0 / 400000.0) * 100;
        printf("%.2f\t", distance);

        // Filtered distance
        static int distance_buffer[SAMPLE_SIZE] = {0};
        int index = SAMPLE_SIZE - 1;
        for (int i = 0; i < SAMPLE_SIZE; i++) {
            distance_buffer[i] = distance_buffer[i - 1];
        }
        distance_buffer[index] = distance;
        double filtered_distance = 0;
        for (int i = 0; i < SAMPLE_SIZE; i++) {
            filtered_distance += distance_buffer[i];
        }
        filtered_distance /= SAMPLE_SIZE;
        printf("%.2f\t", filtered_distance);

        // Servo angle
        servo_set_angle(servo_handle, 90);
    }
}

int main(void) {
    setup_gpio();

    if (gpio_register_interrupt(ECHO_PIN, interrupt_callback, NULL) < 0) {
        perror("Failed to register interrupt");
        exit(EXIT_FAILURE);
    }

    if (servo_init(&servo_handle) < 0) {
        perror("Failed to initialize servo");
        exit(EXIT_FAILURE);
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    fprintf(log_file, "%s", "timestamp,distance,angle\n");

    while (!stop_signal) {
        usleep(TIMEOUT_US / 2);
    }

    fclose(log_file);
    servo_cleanup(&servo_handle);
    gpio_disable_interrupt(ECHO_PIN);
    gpio_disable_output(TRIGGER_PIN);
    gpio_disable_output(ECHO_PIN);
    gpio_disable_output(SERVO_PIN);

    return 0;
}

