int i2c_open(const char *bus_name) {
    int file = open("/dev/i2c-" + bus_name, O_RDWR);
    if (file < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }
    return file;
}

int i2c_close(int fd) {
    close(fd);
    return 0;
}

int i2c_write_byte(int fd, uint8_t addr, uint8_t data) {
    return write(fd, &addr, 1) == 1 && write(fd, &data, 1) == 1;
}

int i2c_read_byte(int fd, uint8_t addr) {
    uint8_t buf[2];
    int ret = read(fd, buf, 2);
    if (ret == 2 && buf[0] == addr) {
