#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <pthread.h>
#include <sigaction.h>
#include <i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS 1
#define GPIO27 27
#define DEFAULT_THRESHOLD 1000
#define LOG_FILE "proximity.log"

typedef struct {
    int i2c_address;
    int flag;
} proximity_context;

void i2c_init(void) {
    int file;
    file = open("/dev/i2c-1", O_RDWR);
    if (file == -1) {
        perror("open /dev/i2c-1");
        exit(EXIT_FAILURE);
    }

    if (ioctl(file, I2C_SLAVE, (u_int8_t)atoi(argv[1])) == -1) {
        perror("ioctl I2C_SLAVE");
        close(file);
        exit(EXIT_FAILURE);
    }
}

void gpio_init(void) {
    if (piGPIO_openAll() == -1) {
        perror("piGPIO_openAll");
        exit(EXIT_FAILURE);
    }
}

void setup_sensor(proximity_context *ctx) {
    if (piGPIO_setMode(GPIO27, PI_OUTPUT) == -1) {
        perror("piGPIO_setMode");
        exit(EXIT_FAILURE);
    }
}

void interrupt_handler(int signum, siginfo_t *info, void *context) {
    static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    static volatile int interrupt_flag = 0;

    pthread_mutex_lock(&mutex);
    if (!interrupt_flag) {
        // Read proximity value
        int16_t proximity = read_i2c_register(ctx->i2c_address, 0x00);

        // Compare with threshold
        if (proximity <= ctx->threshold) {
            write_i2c_register(ctx->i2c_address, 0x01, 0x00); // Clear interrupt
        } else {
            write_i2c_register(ctx->i2c_address, 0x01, 0x01); // Set interrupt
        }

        // Append to log file
        char timestamp[20];
        time_r(time(NULL), timestamp);
        fprintf(fopen(LOG_FILE, "a"), "%s: %d\n", timestamp, proximity);

        // Clear interrupt flag
        interrupt_flag = 0;
    }
    interrupt_flag = 1;
    pthread_mutex_unlock(&mutex);
}

int read_i2c_register(int address, int register_address) {
    int data;
    write(fileno(ctx->i2c_file), &register_address, 2);
    read(fileno(ctx->i2c_file), &data, 2);
    return data;
}

void write_i2c_register(int address, int register_address, int data) {
    write(fileno(ctx->i2c_file), &register_address, 2);
    write(fileno(ctx->i2c_file), &data, 2);
}

int main(int argc, char *argv[]) {
    proximity_context ctx;
    int i2c_file, sigmask[2];

    i2c_init();
    gpio_init();
    ctx.i2c_address = atoi(argv[1]);
    ctx.threshold = DEFAULT_THRESHOLD;

    if (argc > 2) {
        ctx.threshold = atoi(argv[2]);
    }

    if (open(LOG_FILE, O_WRONLY | O_CREAT, S_IRUSR | S_IWUSR) == -1) {
        perror("open proximity.log");
        exit(EXIT_FAILURE);
    }

    sigaction sa;
    sa.sa_handler = interrupt_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaddset(&sa.sa_mask, SIGINT) == 0) {
        sigaction(SIGINT, &sa, NULL);
    }

    i2c_file = open(LOG_FILE, O_WRONLY | O_CREAT, S_IRUSR | S_IWUSR);
    if (i2c_file == -1) {
        perror("open proximity.log");
        exit(EXIT_FAILURE);
    }

    if (piGPIO_setMode(GPIO27, PI_OUTPUT) == -1) {
        perror("piGPIO_setMode");
        close(i2c_file);
        exit(EXIT_FAILURE);
    }

    if (piGPIO_write(GPIO27, 0) == -1) {
        perror("piGPIO_write");
        close(i2c_file);
        exit(EXIT_FAILURE);
    }

    if (piGPIO_read(GPIO27) == -1) {
        perror("piGPIO_read");
        close(i2c_file);
        exit(EXIT_FAILURE);
    }

    pthread_t thread;
    if (pthread_create(&thread, NULL, interrupt_handler, &ctx) != 0) {
        perror("pthread_create");
        close(i2c_file);
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (1) {
        sleep(1);
    }

    pthread_join(thread, NULL);
    close(i2c_file);
    piGPIO_closeAll();
    return 0;
}

