#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <stdbool.h>
#include <libgpiod.h>

#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define PWM_PIN 18
#define SPEAKER_PIN 27
#define PWM_FREQUENCY 48000
#define MAX_DISTANCE 200
#define MIN_DISTANCE 2
#define LOG_SCALE 50

#define PWM_WIDTH_US 10000
#define TIMEOUT_MS 200

static gpiod_ctx_t gpiod_ctx;
static gpiod_button_t button;

static int pwm_width_us = PWM_WIDTH_US;
static int distance = 0;

void handle_interrupt(int sig) {
    gpiod_button_del(&button);
    gpiod_ctx_destroy(&gpiod_ctx);
    exit(0);
}

void setup_gpio(void) {
    int ret;

    ret = gpiod_setup(&gpiod_ctx, NULL, NULL);
    if (ret < 0) {
        perror("Failed to initialize GPIO context");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_button_add_edge_detect(&gpiod_ctx, TRIGGER_PIN, GPIONOZERO, GPIONOW);
    if (ret < 0) {
        perror("Failed to add button on TRIGGER_PIN");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_button_add_edge_detect(&gpiod_ctx, ECHO_PIN, GPIONOZERO, GPIONOW);
    if (ret < 0) {
        perror("Failed to add button on ECHO_PIN");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_output_tform_create(&gpiod_ctx, PWM_PIN, GPAMODE_OUTPUT);
    if (ret < 0) {
        perror("Failed to configure PWM_PIN as output");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_output_tform_set_freq(&gpiod_ctx, PWM_PIN, PWM_FREQUENCY);
    if (ret < 0) {
        perror("Failed to set PWM frequency");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_output_tform_set_duty_cycle(&gpiod_ctx, PWM_PIN, 0);
    if (ret < 0) {
        perror("Failed to set PWM duty cycle");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_output_tform_enable(&gpiod_ctx, PWM_PIN);
    if (ret < 0) {
        perror("Failed to enable PWM_PIN");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_output_tform_set_edge_detect(&gpiod_ctx, PWM_PIN, GPIONOEDGE);
    if (ret < 0) {
        perror("Failed to disable edge detection on PWM_PIN");
        exit(EXIT_FAILURE);
    }
}

void read_distance(void) {
    static uint32_t last_time = 0;
    uint32_t current_time;

    current_time = rtc_get_time(RTC_BASE);
    uint32_t elapsed_us = current_time - last_time;

    if (elapsed_us < TIMEOUT_MS / 2) {
        return;
    }

    last_time = current_time;

    // HC-SR04 trigger pulse
    gpio_pin_set(TRIGGER_PIN, GPIO_OUTPUT);
    gpio_pin_write(TRIGGER_PIN, LOW);
    usleep(PWM_WIDTH_US / 2);
    gpio_pin_write(TRIGGER_PIN, HIGH);
    usleep(PWM_WIDTH_US / 2);
    gpio_pin_write(TRIGGER_PIN, LOW);

    // Read echo pulse duration
    uint32_t start_time = rtc_get_time(RTC_BASE);
    gpio_pin_set(ECHO_PIN, GPIO_INPUT);
    uint32_t end_time = rtc_get_time(RTC_BASE);

    while (rtc_time_elapsed(start_time, end_time) < 10) {}

    uint32_t duration_us = end_time - start_time;
    distance = (duration_us * 1000000) / 2; // Convert to cm

    // Map distance to frequency
    int frequency = 0;
    if (distance < MIN_DISTANCE) {
        frequency = 200;
    } else if (distance > MAX_DISTANCE) {
        frequency = 2000;
    } else {
        frequency = (2000 * log((float)distance / 100.0f, LOG_SCALE)) / 100.0f;
    }

    // Set PWM duty cycle
    gpio_pin_set(PWM_PIN, GPIO_OUTPUT);
    gpio_pin_write(PWM_PIN, 0);
    gpio_pin_set_pulse_width(PWM_PIN, frequency);
}

void play_tone(void) {
    int freq = (int)(frequency * PWM_FREQUENCY / 2);
    int duty = (int)(log(freq / 200.0f, LOG_SCALE) * 100);

    gpio_pin_set(SPEAKER_PIN, GPIO_OUTPUT);
    gpio_pin_write(SPEAKER_PIN, 0);
    gpio_pin_set_pulse_width(SPEAKER_PIN, duty);
    usleep(1000000 / frequency); // Approximate 1ms for a 1kHz tone
}

int main(int argc, char *argv[]) {
    signal(SIGINT, handle_interrupt);
    signal(SIGTERM, handle_interrupt);

    setup_gpio();

    while (1) {
        read_distance();
        play_tone();
        usleep(100000); // Adjust as needed
    }

    return 0;
}

