#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <string.h>
#include <errno.h>
#include <pigpio.h>

#define BUZZER_PIN 18
#define TRIG_PIN 23
#define ECHO_PIN 24
#define MAX_DISTANCE 50
#define MIN_DISTANCE 5
#define FREQ_MIN 200
#define FREQ_MAX 2000
#define PWM_FREQ 1000

#define BUFFER_SIZE 10
char buffer[BUFFER_SIZE] = {0};

void signal_handler(int signum) {
    piGPIOoutput(BUZZER_PIN, 0);
    pigpio_terminate(1000);
    exit(0);
}

void init_gpio() {
    if (pigpio_init() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        exit(EXIT_FAILURE);
    }

    if (gpioSetup(TRIG_PIN, PIGGPIO_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set up TRIG_PIN\n");
        exit(EXIT_FAILURE);
    }

    if (gpioSetup(ECHO_PIN, PIGGPIO_INPUT, PIGGPIO_ATTEN_1_1) < 0) {
        fprintf(stderr, "Failed to set up ECHO_PIN\n");
        exit(EXIT_FAILURE);
    }

    if (gpioMode(BUZZER_PIN, PIGGPIO_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set up BUZZER_PIN as output\n");
        exit(EXIT_FAILURE);
    }
}

int measure_distance() {
    gpioToggle(TRIG_PIN);
    usleep(10);
    gpioToggle(TRIG_PIN);

    uint32_t start_time = piGPIOget(ECHO_PIN);
    uint32_t end_time;
    do {
        end_time = piGPIOget(ECHO_PIN);
    } while (piGPIOget(ECHO_PIN) == 0 && microseconds() < 100000);

    uint32_t duration = end_time - start_time;
    double distance = (duration / 2) / PIGGPIO_FREQUENCY(ECHO_PIN) * 1000;

    if (distance > MAX_DISTANCE)
        distance = MAX_DISTANCE;
    if (distance < MIN_DISTANCE)
        distance = MIN_DISTANCE;

    return (int)distance;
}

void generate_tone(int frequency) {
    int duty_cycle = PWM_FREQ / frequency;
    piPWMset(BUZZER_PIN, duty_cycle);
}

int main(int argc, char *argv[]) {
    signal(SIGINT, signal_handler);

    init_gpio();

    while (1) {
        int distance = measure_distance();
        int frequency = (int)((distance / 10) * PWM_FREQ) % (FREQ_MAX - FREQ_MIN + 1) + FREQ_MIN;

        generate_tone(frequency);
        printf("Distance: %d cm, Frequency: %d Hz\n", distance, frequency);
        usleep(10000);
    }

    return 0;
}

