    uint32_t start_time = piGPIOget(ECHO_PIN);
    uint32_t end_time;
    do {
        end_time = piGPIOget(ECHO_PIN);
    } while (piGPIOget(ECHO_PIN) == 0 && microseconds() < 100000);

    uint32_t duration = end_time - start_time;
    double distance = (duration / 2) / PIGGPIO_FREQUENCY(ECHO_PIN) * 1000;

    if (distance > MAX_DISTANCE)
        distance = MAX_DISTANCE;
    if (distance < MIN_DISTANCE)
        distance = MIN_DISTANCE;

    return (int)distance;
}

void generate_tone(int frequency) {
    int duty_cycle = PWM_FREQ / frequency;
    piPWMset(BUZZER_PIN, duty_cycle);
}

int main(int argc, char *argv[]) {
    signal(SIGINT, signal_handler);

    init_gpio();

    while (1) {
        int distance = measure_distance();
        int frequency = (int)((distance / 10) * PWM_FREQ) % (FREQ_MAX - FREQ_MIN + 1) + FREQ_MIN;

        generate_tone(frequency);
        printf("Distance: %d cm, Frequency: %d Hz\n", distance, frequency);
        usleep(10000);
    }

    return 0;
}
```

This code initializes the pigpio library, sets up the GPIO pins, and continuously measures distance using the HC-SR04 sensor, generating a tone on the piezo buzzer based on the distance. It handles errors, ensures clean shutdown on SIGINT, and prints the measured distance and frequency to the console.

Please note that you need to have the pigpio library installed on your Raspberry Pi for this code to work. You can install it using:

```bash
sudo apt-get install pigpio
```

Also, ensure that the GPIO pins are correctly connected to the buzzer and the ultrasonic sensor as described in the comments.

