#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod/gpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define TIMEOUT_MS 50
#define LOOP_MS 500

int valid_distance_flag = 0;

void signal_handler(int signum) {
    global_flags->exit_loop = 1;
}

int main() {
    int ret;
    struct gpiod_digital_out_attr attr;
    struct gpiod_digital_in_attr echo_attr;

    ret = gpiod_attribute_init(&attr);
    if (ret < 0) {
        perror("Failed to initialize digital_out attribute");
        exit(EXIT_FAILURE);
    }
    attr.default_value = GPIO_OUTPUT_LOW;
    ret = gpiod_digital_out_configure(TRIGGER_PIN, &attr);
    if (ret < 0) {
        perror("Failed to configure TRIGGER_PIN");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_attribute_init(&echo_attr);
    if (ret < 0) {
        perror("Failed to initialize digital_in attribute");
        exit(EXIT_FAILURE);
    }
    ret = gpiod_digital_in_configure(ECHO_PIN, &echo_attr);
    if (ret < 0) {
        perror("Failed to configure ECHO_PIN");
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, signal_handler);

    while (!valid_distance_flag) {
        ret = gpiod_get_value(ECHO_PIN);
        if (ret == -1) {
            printf("Timeout reading echo\n");
            continue;
        }

        unsigned long echo_duration = ret;
        double distance = (echo_duration * 58) / 2; // Conversion from us to cm

        if (distance < 2 || distance > 400) {
            printf("Invalid reading: %f cm\n", distance);
        } else if (distance < 10) {
            printf("Too close! %f cm\n", distance);
        } else {
            printf("Distance: %.2f cm\n", distance);
        }

        usleep(LOOP_MS * 1000 / HRTIME_PER_SEC);
    }

    gpiod_attribute_destroy(&attr);
    gpiod_attribute_destroy(&echo_attr);

    return 0;
}

