#define SPI_DATA_REG 0x00
#define SPI_CMD_REG 0x01
#define SPI_STATUS_REG 0x02

// SPI and GPIO configuration
int spi_fd;
int ce_gpio_fd;

// Function prototypes
void spi_init(void);
void ce_gpio_init(void);
void spi_read_distance(float *distance);
void spi_error_handler(const char *msg);
void sigint_handler(int sig);
void sigterm_handler(int sig);

int main(int argc, char *argv[]) {
    spi_fd = open(DISTANCE_LOG, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (spi_fd == -1) {
        perror("Error opening distance_log.csv");
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    spi_init();
    ce_gpio_init();

    while (1) {
        spi_read_distance(&distance);
        char timestamp[32];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

        char log_entry[128];
        sprintf(log_entry, "%s, %f\n", timestamp, distance);
        write(spi_fd, log_entry, strlen(log_entry));

        usleep(LOG_INTERVAL * 1000);
    }

    return 0;
}

void spi_init(void) {
    int file = open("/dev/spidev0.0", O_RDWR);
    if (file == -1) {
        spi_error_handler("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    spi_fd = file;

    // Configure SPI mode 0, 1 MHz clock
    if (ioctl(file, SPI_SET_MODE, SPI_MODE0) == -1) {
        spi_error_handler("Failed to set SPI mode");
        exit(EXIT_FAILURE);
    }

    if (ioctl(file, SPI_SET_BRIGHT_BIT, 0) == -1) {
        spi_error_handler("Failed to set BRIGHT bit");
        exit(EXIT_FAILURE);
    }

    if (ioctl(file, SPI_SET_POLARITY_0, 0) == -1) {
        spi_error_handler("Failed to set Polarity 0");
        exit(EXIT_FAILURE);
    }

    if (ioctl(file, SPI_SET_PHASE, 0) == -1) {
        spi_error_handler("Failed to set Phase 0");
        exit(EXIT_FAILURE);
    }

    ce_gpio_fd = open("/sys/class/gpio/gpio8/output", O_WRLCK | O_CREAT | 0666, 0666);
    if (ce_gpio_fd == -1) {
        spi_error_handler("Failed to open CE0 GPIO");
        close(file);
        exit(EXIT_FAILURE);
    }

    if (flock(ce_gpio_fd, LOCK_EX) == -1) {
        spi_error_handler("Failed to acquire lock on CE0 GPIO");
        close(file);
        exit(EXIT_FAILURE);
    }

    if (ioctl(ce_gpio_fd, GPIO_OUTPUT, 1) == -1) {
        spi_error_handler("Failed to set CE0 GPIO output");
        close(ce_gpio_fd);
        close(file);
        exit(EXIT_FAILURE);
    }

    close(ce_gpio_fd);
}

void ce_gpio_init(void) {
    // No initialization needed for CE0 GPIO
}

void spi_read_distance(float *distance) {
    uint8_t cmd[1] = {0x00};
    uint8_t status;

    if (write(spi_fd, cmd, 1) == -1) {
        spi_error_handler("Failed to send command");
        return;
    }

    if (read(spi_fd, &status, 1) == -1) {
        spi_error_handler("Failed to read status");
        return;
    }

    if (status & 0x01) {
        // Error condition
        spi_error_handler("SPI communication error");
        return;
    }

    // Read distance data (assuming 12 bits, 2's complement)
    uint16_t distance_data;
    if (read(spi_fd, &distance_data, 2) == -1) {
        spi_error_handler("Failed to read distance data");
        return;
    }

    // Convert to millimeters
    *distance = (float)distance_data / 1000.0;
}

void spi_error_handler(const char *msg) {
    fprintf(stderr, "Error: %s\n", msg);
    exit(EXIT_FAILURE);
}

void sigint_handler(int sig) {
    spi_error_handler("SIGINT received, closing SPI and logging file");
    close(spi_fd);
    spi_fd = -1;

    spi_error_handler("Closing CSV log file");
    close(fildes(spi_fd));
    unlink(DISTANCE_LOG);
    rmdir(NULL);

    exit(EXIT_SUCCESS);
}

void sigterm_handler(int sig) {
    sigterm_handler(sig);
}

