#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <time.h>
#include <stdint.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x4C  // Silicon Labs Si1175 default I2C address
#define LOG_FILE "proximity_log.csv"

#define SAMPLE_INTERVAL_SEC 5.0

void log_reading(const uint16_t light_value) {
    time_t now = time(NULL);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    fprintf(log_file, "%s,%hu\n", timestamp, light_value);
    fclose(log_file);
}

int main() {
    int i2c_fd;
    struct i2c_client *client;

    i2c_fd = open(I2C_BUS, O_RDWR | O_SYNC);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    client = i2c_client_new(i2c_fd, I2C_ADDR);
    if (!client) {
        perror("Failed to create I2C client");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    while (1) {
        int result = i2c_transfer(client, 0x1C, 0x00, 1, (uint8_t *)NULL, 1);
        if (result < 0) {
            perror("I2C read failed");
            continue;
        }

        uint16_t light_value = ntohs(*((uint16_t *)result));
        log_reading(light_value);

        usleep(SAMPLE_INTERVAL_SEC * 1000000);
    }

    i2c_client_free(client);
    close(i2c_fd);

    return 0;
}

