#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x5A
#define SAMPLE_INTERVAL_MS 500
#define RETRY_DELAY_MS 10
#define LOG_FILE "si1120_log.txt"
#define PART_ID_REGISTER 0x00
#define ALS_DATA_REGISTER 0x01
#define PROX_DATA_REGISTER 0x02

#define ALS_DATA_WIDTH 12
#define PROX_DATA_WIDTH 8

#define LOG_ENTRY_SIZE (ALS_DATA_WIDTH + PROX_DATA_WIDTH + 16)

int main(int argc, char *argv[]) {
    int i2c_fd, ret;
    struct i2c_client *client;
    char log_entry[LOG_ENTRY_SIZE + 1];
    struct timespec ts;
    pid_t pid;

    pid = getpid();

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("open /dev/i2c-1");
        exit(EXIT_FAILURE);
    }

    client = i2c_client_new(i2c_fd, 0x20);
    if (!client) {
        perror("i2c_client_new");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    while (1) {
        ret = i2c_transfer(client, I2C_ADDR, ALS_DATA_REGISTER, 0, ALS_DATA_WIDTH >> 1, log_entry);
        if (ret < 0) {
            if (errno == EIO || errno == EBUSY) {
                for (int i = 0; i < 3; i++) {
                    usleep(RETRY_DELAY_MS * 1000);
                    ret = i2c_transfer(client, I2C_ADDR, ALS_DATA_REGISTER, 0, ALS_DATA_WIDTH >> 1, log_entry);
                    if (ret == 0) {
                        break;
                    }
                }
                if (ret < 0) {
                    fprintf(stderr, "Failed to read ALS data after retries\n");
                    exit(EXIT_FAILURE);
                }
            } else {
                fprintf(stderr, "I2C transfer failed: %s\n", strerror(errno));
                exit(EXIT_FAILURE);
            }
        }

        ret = i2c_transfer(client, I2C_ADDR, PROX_DATA_REGISTER, 0, PROX_DATA_WIDTH >> 1, log_entry + ALS_DATA_WIDTH);
        if (ret < 0) {
            if (errno == EIO || errno == EBUSY) {
                for (int i = 0; i < 3; i++) {
                    usleep(RETRY_DELAY_MS * 1000);
                    ret = i2c_transfer(client, I2C_ADDR, PROX_DATA_REGISTER, 0, PROX_DATA_WIDTH >> 1, log_entry + ALS_DATA_WIDTH);
                    if (ret == 0) {
                        break;
                    }
                }
                if (ret < 0) {
                    fprintf(stderr, "Failed to read proximity data after retries\n");
                    exit(EXIT_FAILURE);
                }
            } else {
                fprintf(stderr, "I2C transfer failed: %s\n", strerror(errno));
                exit(EXIT_FAILURE);
            }
        }

        // Verify part ID
        ret = i2c_transfer(client, I2C_ADDR, PART_ID_REGISTER, 0, 1, &client->reg_value);
        if (ret < 0) {
            fprintf(stderr, "Failed to read part ID: %s\n", strerror(errno));
            exit(EXIT_FAILURE);
        }

        if (client->reg_value != 0x01) {
            fprintf(stderr, "Part ID mismatch, sensor reset failed\n");
            exit(EXIT_FAILURE);
        }

        // Combine ALS and proximity data
        uint16_t combined_data = ((uint16_t)log_entry[ALS_DATA_WIDTH] << 8) | log_entry[ALS_DATA_WIDTH + PROX_DATA_WIDTH];

        // Get current timestamp
        time(ts);
        strftime(log_entry + LOG_ENTRY_SIZE, sizeof(log_entry) - 1, "%Y-%m-%d %H:%M:%S", localtime(&ts));

        // Append to log file
