#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>

#define I2C_BUS "/dev/i2c-1"
#define SIL1182_ADDR 0x28
#define LUX_REG 0x00
#define PROX_REG 0x01
#define PROX_DATA_WIDTH 16
#define LUX_DATA_WIDTH 12
#define LOG_FILE "biometric_log.txt"
#define LOG_FORMAT "%Y-%m-%d %H:%M:%S.%3m"

int i2c_fd;

void handle_error(const char *msg) {
    perror(msg);
    exit(EXIT_FAILURE);
}

int init_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR | O_SYNC);
    if (i2c_fd == -1) {
        handle_error("open i2c-1");
    }
    if (ioctl(i2c_fd, I2C_SLAVE, SIL1182_ADDR) == -1) {
        handle_error("set i2c-1 slave address");
    }
    return 0;
}

int read_part_id() {
    unsigned char part_id[2];
    ssize_t ret = read(i2c_fd, part_id, sizeof(part_id));
    if (ret == -1) {
        handle_error("read part ID");
    }
    if (ret != sizeof(part_id)) {
        handle_error("I2C read error (NACK)");
    }
    if (part_id[0] != 0x11 && part_id[1] != 0x82) {
        printf("Sensor not found.\n");
        return -1;
    }
    return 0;
}

int configure_sensor() {
    unsigned char config[2];
    config[0] = 0x20; // Measurement rate (100 Hz)
    config[1] = 0x00; // Data format (12-bit LUX)

    ssize_t ret = write(i2c_fd, config, sizeof(config));
    if (ret == -1) {
        handle_error("write sensor config");
    }
    return 0;
}

int read_lux_and_proximity() {
    unsigned short lux, prox;
    ssize_t ret = read(i2c_fd, &lux, sizeof(lux));
    if (ret == -1) {
        handle_error("read LUX");
    }
    ret = read(i2c_fd, &prox, sizeof(prox));
    if (ret == -1) {
        handle_error("read proximity");
    }

    return 0;
}

void log_reading(const char *timestamp, unsigned short lux, unsigned short prox) {
    time_t now = time(NULL);
    struct tm *tinfo = localtime(&now);
    char timestamp_str[32];
    sprintf(timestamp_str, LOG_FORMAT, tinfo->tm_year + 1900,
            tinfo->tm_mon + 1, tinfo->tm_mday, tinfo->tm_hour,
            tinfo->tm_min, tinfo->tm_sec, (tinfo->tm_sec % 1) * 100);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        handle_error("open log file");
    }
    fprintf(log_file, "%s,%u,%u\n", timestamp_str, lux, prox);
    fclose(log_file);

    printf("%s,%u,%u\n", timestamp_str, lux, prox);
}

int main(int argc, char *argv[]) {
    int ret;

    ret = init_i2c();
    if (ret) {
        return ret;
    }

    ret = read_part_id();
    if (ret) {
        goto exit_main;
    }

    ret = configure_sensor();
    if (ret) {
        goto exit_main;
    }

    while (1) {
        ret = read_lux_and_proximity();
        if (ret) {
            goto exit_main;
        }

        log_reading(get_timestamp(), lux, prox);
    }

exit_main:
    close(i2c_fd);
    if (ret) {
        fprintf(stderr, "I2C error: %s\n", strerror(errno));
    }

    // SIGINT and SIGTERM handlers
    if (signal(SIGINT) == SIG_IGN || signal(SIGTERM) == SIG_IGN) {
        handle_error("SIGINT or SIGTERM not handled");
    }

    // Close I2C file descriptor and log file on exit
    close(i2c_fd);
    fclose(stdout);

    return 0;
}

