#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define BUZZER_PIN 27

#define TRIG_PULSE_WIDTH 10e-6 // 10 µs

void interrupt_handler(int id) {
    static long last_echo_time = 0;
    static int distance;

    long current_time = microtime();

    if (current_time - last_echo_time > TRIG_PULSE_WIDTH) {
        distance = (microseconds_to_mm(current_time - microtime()) * 2) / 2;

        if (distance < 20) {
            gpioOutput(BUZZER_PIN, 1);
        } else {
            gpioOutput(BUZZER_PIN, 0);
        }

        last_echo_time = current_time;
    }
}

int main() {
    int ret;

    // Initialize pigpio
    ret = pigpioInit(5);
    if (ret != 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pi_strerror(ret));
        exit(EXIT_FAILURE);
    }

    // Set up GPIO pins
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Configure trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
    usleep(TRIG_PULSE_WIDTH * 1000000);
    gpioWrite(TRIGGER_PIN, 1);
    usleep(TRIG_PULSE_WIDTH * 1000000);
    gpioWrite(TRIGGER_PIN, 0);

    // Set up interrupt
    gpioSetEdgeBoth(ECHO_PIN, interrupt_handler);

    // Main loop
    while (1) {
        sleep(1);
    }

    // Clean exit
    pigpioTerminate(1);
    return 0;
}

// Helper function to convert microseconds to centimeters
static inline int microseconds_to_mm(long microseconds) {
    return (microseconds * 10) / 2;
}

// Signal handler for SIGINT
void sigint_handler(int signum) {
    fprintf(stderr, "Received SIGINT, cleaning up and exiting...\n");
    pigpioTerminate(1);
    exit(EXIT_SUCCESS);
}

// Install SIGINT handler
signal(SIGINT, sigint_handler);
