#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <stdbool.h>
#include <pigpio.h>

#define TRIGGER_PIN 4
#define ECHO_PIN 17
#define SERVO_PIN 18
#define UPDATE_INTERVAL 100

bool running = true;

void signal_handler(int signum) {
    printf("Program received signal %d, exiting gracefully...\n", signum);
    pigpio_terminate();
    exit(0);
}

void setup_pi() {
    if (pigpio_init() != 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        exit(1);
    }

    if (gpioSetup(TRIGGER_PIN, PIGIO_OUTPUT) == -1) {
        fprintf(stderr, "Failed to set %s as output\n", gpio_pinname(TRIGGER_PIN));
        exit(1);
    }

    if (gpioSetup(ECHO_PIN, PIGIO_INPUT) == -1) {
        fprintf(stderr, "Failed to set %s as input\n", gpio_pinname(ECHO_PIN));
        exit(1);
    }

    if (gpioSetup(SERVO_PIN, PIGIO_OUTPUT) == -1) {
        fprintf(stderr, "Failed to set %s as output\n", gpio_pinname(SERVO_PIN));
        exit(1);
    }
}

void loop_pi() {
    while (running) {
        int echo_time = gpioRead(ECHO_PIN);
        if (echo_time == -1) {
            printf("Echo timeout, retrying...\n");
            continue;
        }

        float duration = (echo_time * 0.000001) / 2; // Convert to microseconds
        float distance = (duration * 34300) / 2; // Speed of sound in cm/s

        if (distance < 20) {
            gpioWrite(SERVO_PIN, 0); // Servo at 0°
        } else if (distance < 110) {
            gpioWrite(SERVO_PIN, 90); // Servo at 90°
        } else if (distance < 200) {
            gpioWrite(SERVO_PIN, 180); // Servo at 180°
        } else {
            gpioWrite(SERVO_PIN, 0); // Servo at 0°
        }

        printf("Distance: %.1f cm\n", distance);
        usleep(UPDATE_INTERVAL * 1000000 / 100); // Adjust for 100ms update interval
    }
}

int main(int argc, char *argv[]) {
    setup_pi();

    signal(SIGINT, signal_handler);

    while (running) {
        loop_pi();
    }

    pigpio_terminate();
    return 0;
}

