#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29  // VL53L1X default address
#define DIST_REG 0x00
#define MODEL_ID 0x01
#define TIMING_BUDGET 0x02
#define RANGE_START 0x03
#define PWM_GPIO 18

#define LOG_FILE "gate_log.txt"

int i2c_fd;
piGPIO_handle handle;

void init_i2c() {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open i2c bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set i2c slave address");
        exit(EXIT_FAILURE);
    }
}

void setup_pi() {
    handle = piGPIO_open(PWM_GPIO);
    if (!handle) {
        perror("Failed to open pigpio handle");
        exit(EXIT_FAILURE);
    }

    piGPIO_setMode(handle, PWM_OUTPUT);
}

void set_timing_budget(uint16_t budget) {
    if (ioctl(i2c_fd, WHO_AM_I, NULL) < 0) {
        perror("Failed to get model ID");
        exit(EXIT_FAILURE);
    }

    if (read(i2c_fd, &budget, 2) != 2) {
        perror("Failed to read timing budget");
        exit(EXIT_FAILURE);
    }

    if (budget != 0x0000) {
        perror("Invalid timing budget");
        exit(EXIT_FAILURE);
    }

    write(i2c_fd, &timing_budget, 2);
}

void start_range() {
    if (ioctl(i2c_fd, VL53L1X_START_RANGE, 0) < 0) {
        perror("Failed to start ranging");
        exit(EXIT_FAILURE);
    }
}

uint16_t read_distance() {
    uint16_t distance;
    if (ioctl(i2c_fd, VL53L1X_READ_DISTANCE, DIST_REG, &distance, 2) < 0) {
        perror("Failed to read distance");
        return -1;
    }
    return distance;
}

void control_gate(uint16_t distance) {
    if (distance > 250) {
        piGPIO_pulse(handle, PWM_GPIO, 1000);
    } else if (distance < 200) {
        piGPIO_pulse(handle, PWM_GPIO, 2000);
    } else {
        piGPIO_pulse(handle, PWM_GPIO, 1500); // Hysteresis
    }
}

void log_event(const char* message) {
    time_t now = time(NULL);
    char time_str[80];
    sprintf(time_str, "%s", ctime(&now));

    FILE* log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    fprintf(log_file, "%s - %s\n", time_str, message);
    fclose(log_file);
}

int main(int argc, char* argv[]) {
    init_i2c();
    setup_pi();

    set_timing_budget(0x0000);  // Default timing budget
    start_range();

    while (1) {
        uint16_t distance = read_distance();
        if (distance == -1) {
            break;
        }
        control_gate(distance);
        log_event("Gate opened/closed");
        usleep(100000);  // Adjust sleep time as needed
    }

    piGPIO_close(handle);
    close(i2c_fd);
    pigpio_terminate(1000);  // Terminate pigpio with a 1-second timeout

    log_event("Program terminated");
    return 0;
}

