This code initializes the I2C bus, sets up pigpio for PWM control, configures the VL53L1X sensor, starts ranging, reads distances, controls the servo-actuated gate, logs events, and handles errors. The program cleans up resources on SIGINT and exits cleanly.

Please note that you need to have `pigpio` library installed and configured on your Raspberry Pi for this code to work. Also, the VL53L1X timing budget value is set to the default (0x0000) in this example. You may need to adjust this value based on your specific sensor requirements.

code:
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <stdbool.h>
#include <errno.h>
#include <libgpiod.h>

#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 18
#define TIMEOUT_US 50000
#define INTERVAL_MS 100
#define MIN_DISTANCE 2
#define MAX_DISTANCE 400

#define MIN_ANGLE 0
#define MAX_ANGLE 180

void signal_handler(int signum) {
    gpio_output_set(SERVO_PIN, 0);
    gpio_output_set(SERVO_PIN, 0);
}

int main() {
    int ret;
    struct sigaction sa;

    // Initialize libgpiod
    ret = gpiod_init();
    if (ret < 0) {
        fprintf(stderr, "Failed to initialize libgpiod: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Set up signal handler for SIGINT
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    // Initialize GPIO pins
    ret = gpiod_pin_configure(TRIGGER_PIN, PIPELINE_IN, PIPELINE_DIR_OUTPUT);
    if (ret < 0) {
        fprintf(stderr, "Failed to configure TRIGGER_PIN: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    ret = gpiod_pin_configure(ECHO_PIN, PIPELINE_IN, PIPELINE_DIR_INPUT);
    if (ret < 0) {
        fprintf(stderr, "Failed to configure ECHO_PIN: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    ret = gpiod_pin_output_init(SERVO_PIN);
    if (ret < 0) {
        fprintf(stderr, "Failed to initialize SERVO_PIN: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Initialize the ultrasonic sensor
    ret = gpiod_gpio_export(TRIGGER_PIN);
    if (ret < 0) {
        fprintf(stderr, "Failed to export TRIGGER_PIN: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    ret = gpiod_gpio_export(ECHO_PIN);
    if (ret < 0) {
        fprintf(stderr, "Failed to export ECHO_PIN: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Set up the ultrasonic sensor
    ret = gpiod_gpio_edge_detect_config(TRIGGER_PIN, PIPELINE_RISING, 10);
    if (ret < 0) {
        fprintf(stderr, "Failed to configure TRIGGER_PIN for rising edge: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    ret = gpiod_gpio_edge_detect_config(ECHO_PIN, PIPELINE_FALLING, 10);
    if (ret < 0) {
        fprintf(stderr, "Failed to configure ECHO_PIN for falling edge: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (1) {
        uint32_t trigger_time, echo_time;
        float distance;

        // Trigger the sensor
        ret = gpiod_gpio_output_set(TRIGGER_PIN, 0);
        if (ret < 0) {
            fprintf(stderr, "Failed to set TRIGGER_PIN output: %s\n", strerror(errno));
            continue;
        }

        ret = gpiod_gpio_wait_us(TRIGGER_PIN, TIMEOUT_US);
        if (ret < 0) {
            fprintf(stderr, "Failed to wait for trigger: %s\n", strerror(errno));
            gpio_output_set(TRIGGER_PIN, 1);
            continue;
        }

        trigger_time = gpiod_get_time();

        // Send the trigger pulse
        ret = gpiod_gpio_output_set(TRIGGER_PIN, 1);
        if (ret < 0) {
            fprintf(stderr, "Failed to set TRIGGER_PIN output: %s\n", strerror(errno));
            gpio_output_set(TRIGGER_PIN, 0);
            continue;
        }

        // Wait for the echo
        ret = gpiod_gpio_wait_us(ECHO_PIN, TIMEOUT_US);
        if (ret < 0) {
            fprintf(stderr, "Failed to wait for echo: %s\n", strerror(errno));
            gpio_output_set(ECHO_PIN, 1);
            continue;
        }

        echo_time = gpiod_get_time();

        // Calculate distance
        distance = (echo_time - trigger_time) * 17150;

        // Handle timeout
        if (distance == -1.0) {
            printf("Timeout detected, distance: -1.0 cm\n");
            continue;
        }

        // Map distance to servo angle
        if (distance < MIN_DISTANCE) {
            distance = MIN_DISTANCE;
            printf("Distance: %.1f cm, Servo angle: %d\n", distance, MIN_ANGLE);
        } else if (distance > MAX_DISTANCE) {
            distance = MAX_DISTANCE;
            printf("Distance: %.1f cm, Servo angle: %d\n", distance, MAX_ANGLE);
        } else {
            float angle = (distance - MIN_DISTANCE) * (MAX_ANGLE - MIN_ANGLE) / (MAX_DISTANCE - MIN_DISTANCE) + MIN_ANGLE;
            if (angle < MIN_ANGLE) angle = MIN_ANGLE;
            if (angle > MAX_ANGLE) angle = MAX_ANGLE;
            printf("Distance: %.1f cm, Servo angle: %d\n", distance, (int)angle);
        }

        // Set servo angle
        ret = gpiod_gpio_output_set(SERVO_PIN, (angle == MIN_ANGLE) ? 0 : 255);
        if (ret < 0) {
            fprintf(stderr, "Failed to set SERVO_PIN output: %s\n", strerror(errno));
            continue;
        }

        usleep(INTERVAL_MS * 1000 / 1000);
    }

    // Clean up and exit
    gpio_output_set(TRIGGER_PIN, 0);
    gpio_output_set(ECHO_PIN, 0);
    gpiod_pin_unexport(TRIGGER_PIN);
    gpiod_pin_unexport(ECHO_PIN);
    gpiod_gpio_export(TRIGGER_PIN, 0);
    gpiod_gpio_export(ECHO_PIN, 0);
    gpiod_shutdown();

    return 0;
}

