        distance = (echo_time - trigger_time) * 17150;

        // Handle timeout
        if (distance == -1.0) {
            printf("Timeout detected, distance: -1.0 cm\n");
            continue;
        }

        // Map distance to servo angle
        if (distance < MIN_DISTANCE) {
            distance = MIN_DISTANCE;
            printf("Distance: %.1f cm, Servo angle: %d\n", distance, MIN_ANGLE);
        } else if (distance > MAX_DISTANCE) {
            distance = MAX_DISTANCE;
            printf("Distance: %.1f cm, Servo angle: %d\n", distance, MAX_ANGLE);
        } else {
            float angle = (distance - MIN_DISTANCE) * (MAX_ANGLE - MIN_ANGLE) / (MAX_DISTANCE - MIN_DISTANCE) + MIN_ANGLE;
            if (angle < MIN_ANGLE) angle = MIN_ANGLE;
            if (angle > MAX_ANGLE) angle = MAX_ANGLE;
            printf("Distance: %.1f cm, Servo angle: %d\n", distance, (int)angle);
        }

        // Set servo angle
        ret = gpiod_gpio_output_set(SERVO_PIN, (angle == MIN_ANGLE) ? 0 : 255);
        if (ret < 0) {
            fprintf(stderr, "Failed to set SERVO_PIN output: %s\n", strerror(errno));
            continue;
        }

        usleep(INTERVAL_MS * 1000 / 1000);
    }

    // Clean up and exit
    gpio_output_set(TRIGGER_PIN, 0);
    gpio_output_set(ECHO_PIN, 0);
    gpiod_pin_unexport(TRIGGER_PIN);
    gpiod_pin_unexport(ECHO_PIN);
    gpiod_gpio_export(TRIGGER_PIN, 0);
    gpiod_gpio_export(ECHO_PIN, 0);
    gpiod_shutdown();

    return 0;
}
```

This code initializes the GPIO pins, sets up the ultrasonic sensor, and continuously measures distances with an HC-SR04 sensor connected to GPIO23 (TRIGGER) and GPIO24 (ECHO). It maps the measured distances to servo angles using an SG90 servo connected to GPIO18 (SERVO), with specific rules for distances below 20 cm and above 200 cm. The program handles errors, uses a SIGINT handler to stop the servo gracefully, and cleans up resources before exiting.

