#define WHO_AM_I_REGISTER 0x2A
#define ACCEL_X_REGISTER 0x31
#define ACCEL_Y_REGISTER 0x32
#define ACCEL_Z_REGISTER 0x33
#define GYRO_X_REGISTER 0x34
#define GYRO_Y_REGISTER 0x35
#define GYRO_Z_REGISTER 0x36
#define TEMP_REGISTER 0x43
#define DATA_OUT_REGISTER 0x39
#define DATA_IN_REGISTER 0x38
#define FIFO_REG 0x1A
#define FIFO_SIZE 16

int mpu6050_read_data(int fd, uint16_t *data) {
    uint8_t buffer[6];
    ssize_t bytes_read = read(fd, buffer, 6);
    if (bytes_read != 6) {
        perror("Failed to read from MPU-6050");
        return -1;
    }
    data[0] = (buffer[0] << 8) | buffer[1];
    data[1] = (buffer[2] << 8) | buffer[3];
    data[2] = (buffer[4] << 8) | buffer[5];
    return 0;
}

int main() {
    int fd, ret;
    struct i2c_client *client;
    uint16_t data[14];

    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Failed to open i2c bus");
        exit(EXIT_FAILURE);
    }

    client = i2c_alloc(fd);
    if (!client) {
        perror("Failed to allocate i2c client");
        close(fd);
        exit(EXIT_FAILURE);
    }

    ret = i2c_setup(client, MPU6050_ADDRESS);
    if (ret < 0) {
        perror("Failed to set up i2c address");
        i2c_free(client);
        close(fd);
        exit(EXIT_FAILURE);
    }

    ret = mpu6050_read_data(fd, data);
    if (ret < 0) {
        perror("Failed to read from MPU-6050");
        i2c_free(client);
        close(fd);
        exit(EXIT_FAILURE);
    }

    // Verify WHO_AM_I register
    if (data[0] != 0x01) {
        fprintf(stderr, "MPU-6050 not found.\n");
        i2c_free(client);
        close(fd);
        exit(EXIT_FAILURE);
    }

    while (1) {
        ret = mpu6050_read_data(fd, data);
        if (ret < 0) {
            perror("Failed to read from MPU-6050");
            break;
        }

        // Parse and print accelerometer data
        int16_t ax = (data[2] << 8) | data[3];
        int16_t ay = (data[4] << 8) | data[5];
        int16_t az = (data[6] << 8) | data[7];
        printf("Accelerometer: x=%d m/s^2, y=%d m/s^2, z=%d m/s^2\n", ax, ay, az);

        // Parse and print gyroscope data
        int16_t gx = (data[8] << 8) | data[9];
        int16_t gy = (data[10] << 8) | data[11];
        int16_t gz = (data[12] << 8) | data[13];
        printf("Gyroscope: x=%d deg/s, y=%d deg/s, z=%d deg/s\n", gx, gy, gz);

        usleep(100000); // 100ms delay
    }

    i2c_free(client);
    close(fd);

    pigpio_stop();
    return 0;
}

