#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SHT40_ADDR 0x40
#define CRC_POLYNOMIAL 0x07

#define LOG_INTERVAL 5000 // 5 seconds in milliseconds

void log_reading(float temperature, float humidity) {
    static int count = 0;
    if (count % 10 == 0) {
        printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
    }
    count++;
}

int read_sht40(uint8_t *data) {
    int file;
    char cmd[3] = {0x43, 0x48, 0x54}; // Command to trigger high-repeatability measurement
    int bytes_to_read = 6;

    file = open("/dev/i2c-1", O_RDWR);
    if (file == -1) {
        perror("open /dev/i2c-1");
        return -1;
    }

    if (ioctl(file, I2C_SLAVE, SHT40_ADDR) == -1) {
        perror("ioctl I2C_SLAVE");
        close(file);
        return -1;
    }

    if (write(file, cmd, 3) != 3) {
        perror("write to I2C bus");
        close(file);
        return -1;
    }

    if (read(file, data, bytes_to_read) != bytes_to_read) {
        perror("read from I2C bus");
        close(file);
        return -1;
    }

    if (data[0] != 0x48 || data[1] != 0x40 || data[2] != 0x00 ||
        data[3] != 0x00 || data[4] != 0x00 || data[5] != 0x00) {
        printf("CRC failure, re-opening I2C bus...\n");
        close(file);
        return -1;
    }

    return 0;
}

int main(int argc, char *argv[]) {
    uint8_t temp_low, temp_high, humidity_low, humidity_high, crc;
    float temperature, humidity;

    pigpio_init(1); // Initialize pigpio for I2C operations

    while (1) {
        log_reading(temperature, humidity);

        if (read_sht40(NULL) == 0) {
            // Extract temperature and humidity from the 6-byte response
            temperature = (float)((data[0] << 8) | data[1]) / 100.0f;
            humidity = (float)((data[2] << 8) | data[3]) / 100.0f;
        }

        usleep(LOG_INTERVAL / 1000); // Wait for LOG_INTERVAL milliseconds
    }

    pigpio_terminate(1); // Terminate pigpio on exit
    return 0;
}

