#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS 1
#define MLX90614_ADDRESS 0x5A
#define LOG_FILE "temperature_log.csv"
#define LOG_INTERVAL 5

void read_temperature(int *ambient, int *object) {
    int file;
    char buffer[100];

    file = open(LOG_FILE, "a");
    if (file == -1) {
        perror("Error opening log file");
        return;
    }

    // Get current timestamp
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    sprintf(buffer, "%ld,%ld", tm->tm_hour, tm->tm_min);

    // Read temperature data
    *ambient = pigpio_get_i2c_register(file, MLX90614_ADDRESS, 0x00);
    *object = pigpio_get_i2c_register(file, MLX90614_ADDRESS, 0x01);

    // Format and write to file
    if (fputs(buffer, file) == EOF) {
        perror("Error writing to log file");
        close(file);
        return;
    }
    fputs("Ambient,Object\n", file);
    fputs(std::to_string(*ambient).c_str(), file);
    fputs(std::to_string(*object).c_str(), file);
    fputs("\n", file);

    close(file);
}

int main(int argc, char *argv[]) {
    int ambient_temp, object_temp;
    int i2c_fd;

    if (pigpio_init() < 0) {
        perror("Failed to initialize pigpio");
        return 1;
    }

    i2c_fd = open(LOG_FILE, "a");
    if (i2c_fd == -1) {
        perror("Error opening log file");
        pigpio_shutdown();
        return 1;
    }

    while (1) {
        read_temperature(&ambient_temp, &object_temp);
        usleep(LOG_INTERVAL * 1000000); // Sleep for LOG_INTERVAL seconds
    }

    pigpio_shutdown();
    close(i2c_fd);
    return 0;
}

