    if (err_fd < 0) {
        perror("Error opening error log file");
        return;
    }
    fprintf(err_fd, "%s", msg);
    close(err_fd);
}

void log_temperature(float temp) {
    char timestamp[20];
    time_t now = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        log_error("Failed to open log file for writing");
        return;
    }
    fprintf(log_file, "%s: %f\n", timestamp, temp);
    fclose(log_file);
}

int main(int argc, char *argv[]) {
    pigpio_init(5); // Initialize pigpio with 5 available pins (I2C on Raspberry Pi)

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        log_error("Failed to open log file for writing");
        return 1;
    }

    while (1) {
        float temperature;
        int result = pigpio_begin_i2c(I2C_BUS, I2C_ADDR);
        if (result < 0) {
            log_error("Failed to start I2C communication");
            fprintf(stderr, "Failed to start I2C communication\n");
            fclose(log_file);
            return 1;
        }

        result = pigpio_write_i2c_byte(I2C_BUS, I2C_ADDR, 0x00); // Command to read temperature
        if (result < 0) {
            log_error("Failed to write to I2C address");
            fprintf(stderr, "Failed to write to I2C address\n");
            pigpio_end_i2c(I2C_BUS);
            fclose(log_file);
            return 1;
        }

        result = pigpio_read_i2c_byte(I2C_BUS, I2C_ADDR);
        if (result < 0) {
            log_error("Failed to read from I2C address");
            fprintf(stderr, "Failed to read from I2C address\n");
            pigpio_end_i2c(I2C_BUS);
            fclose(log_file);
            return 1;
        }

        temperature = (float)(result) / 16.0; // Convert raw byte to temperature in Celsius
        log_temperature(temperature);

        usleep(SAMPLE_INTERVAL * 1000 / 1000); // Wait for the specified interval
    }

    pigpio_end_i2c(I2C_BUS);
    fclose(log_file);
    return 0;
}

