#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x43
#define LOG_FILE "pressure_log.csv"

#define CRC8_POLYNOMIAL 0x07

// Function prototypes
int i2c_open(int fd, const char *bus, int address);
int i2c_write_reg(int fd, uint8_t reg, uint8_t *data, size_t len);
int i2c_read_reg(int fd, uint8_t reg, uint8_t *data, size_t len);
int i2c_close(int fd);
void write_log_entry(const char *timestamp, double pressure, double temperature);

// Sensor configuration
#define SENSOR_CONFIG_REG 0x00
#define SENSOR_CONFIG_DATA [0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08]

// Measurement configuration
#define MEASUREMENT_REG 0x02

// Scale factors
#define PRESSURE_SCALE_FACTOR 0x01
#define TEMPERATURE_SCALE_FACTOR 0x02

// CRC8 calculation
uint8_t crc8(uint8_t crc, uint8_t data) {
    crc = crc ^ data;
    for (int i = 0; i < 8; i++) {
        if ((crc & 0x01)) {
            crc = (crc >> 1) ^ 0x07;
        } else {
            crc >>= 1;
        }
    }
    return crc;
}

// Read 9-byte data frame from sensor
int read_sensor_data(uint8_t *data) {
    int ret = i2c_read_reg(fd, SENSOR_CONFIG_REG, data, sizeof(SENSOR_CONFIG_DATA));
    if (ret != sizeof(SENSOR_CONFIG_DATA)) {
        perror("Failed to read sensor configuration");
        return -1;
    }
    return 0;
}

// Validate CRC8
int validate_crc8(uint8_t crc, uint8_t *data) {
    for (int i = 0; i < 9; i++) {
        if (crc != crc8(crc, data[i])) {
            return -1;
        }
    }
    return 0;
}

// Convert raw values to pressure and temperature
void convert_values(double *pressure, double *temperature) {
    *pressure = ((data[6] << 8) | data[7]) / (data[4] << 8 | data[5]);
    *temperature = ((data[2] << 8) | data[3]) / (data[0] << 8 | data[1]);
}

// Write to log file
void write_log(const char *entry) {
    int fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (fd == -1) {
        perror("Failed to open log file");
        return;
    }
    if (write(fd, entry, strlen(entry)) == -1) {
        perror("Failed to write to log file");
        close(fd);
        exit(EXIT_FAILURE);
    }
    close(fd);
}

// Main function
int main(int argc, char *argv[]) {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int fd = i2c_open(fd, I2C_BUS, I2C_ADDR);
    if (fd == -1) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (read_sensor_data(NULL) == -1) {
        i2c_close(fd);
        return EXIT_FAILURE;
    }

    while (1) {
        double pressure, temperature;
        convert_values(&pressure, &temperature);

        char timestamp[32];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", localtime(&now));

        write_log_entry(timestamp, pressure, temperature);

        usleep(1000000); // Wait for 1ms
    }

    i2c_close(fd);
    return EXIT_SUCCESS;
}

// Signal handler
void signal_handler(int signum) {
    printf("Received signal %d, exiting gracefully...\n", signum);
    exit(signum == SIGINT || signum == SIGTERM ? EXIT_SUCCESS : EXIT_FAILURE);
}

// I2C operations
int i2c_open(int *fd, int bus, int address) {
    *fd = open("/dev/i2c-1", O_RDWR | O_SYNC);
    if (*fd == -1) {
        perror("Failed to open I2C device");
        return -1;
    }
    if (ioctl(*fd, I2C_SLAVE, address) == -1) {
        perror("Failed to set I2C slave address");
        close(*fd);
        return -1;
    }
    return *fd;
}

int i2c_write_reg(int fd, uint8_t reg, uint8_t *data, size_t len) {
    return write(fd, &reg, 1) == 1 && write(fd, data, len) == len;
}

int i2c_read_reg(int fd, uint8_t reg, uint8_t *data, size_t len) {
    return read(fd, &reg, 1) == 1 && read(fd, data, len) == len;
}

int i2c_close(int fd) {
    close(fd);
    return 0;
}

