#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <pthread.h>
#include <time.h>

#define I2C_BUS 1
#define SDA_PIN 2
#define SCL_PIN 3
#define SHT40_ADDR 0x40
#define CRC_POLYNOMIAL 0x07

#define LOG_FILE "sht40_log.txt"

typedef struct {
    int fd;
    struct i2c_client *client;
} I2C_Context;

void *read_and_log(void *arg) {
    I2C_Context *ctx = (I2C_Context *)arg;
    char buffer[6];
    int result;

    while (1) {
        result = ioctl(ctx->fd, I2C_SLAVE, SHT40_ADDR);
        if (result < 0) {
            perror("ioctl I2C_SLAVE");
            sleep(5);
            continue;
        }

        result = ioctl(ctx->fd, I2C_MEMREAD, SHT40_ADDR | 0x00);
        if (result < 0) {
            perror("ioctl I2C_MEMREAD");
            sleep(5);
            continue;
        }

        memcpy(buffer, ctx->client->data, 6);
        uint16_t temp_msb = ntohl((uint16_t)buffer[0]);
        uint16_t temp_lsb = ntohl((uint16_t)buffer[1]);
        uint8_t humidity_msb = buffer[2];
        uint8_t humidity_lsb = buffer[3];
        uint8_t crc = buffer[4];
        uint8_t crc_valid = buffer[5];

        if (crc_valid == 0) {
            fprintf(ctx->fd, "CRC error, skipping reading\n");
            continue;
        }

        if (crc != (crc_valid & 0x01)) {
            fprintf(ctx->fd, "CRC mismatch, skipping reading\n");
            continue;
        }

        time_t now = time(NULL);
        char timestamp[20];
        sprintf(timestamp, "%d-%d-%d %d:%d:%d", now / 3600, (now % 3600) / 60, now % 60, temp_msb, temp_lsb, humidity_msb, humidity_lsb);

        FILE *log_file = fopen(LOG_FILE, "a");
        if (!log_file) {
            perror("fopen");
            continue;
        }
        fprintf(log_file, "%s\n", timestamp);
        fclose(log_file);

        sleep(5);
    }

    close(ctx->fd);
    close(ctx->client->fd);
    remove(LOG_FILE);
    exit(0);
}

int main(int argc, char *argv[]) {
    int i2c_fd, ret;
    struct i2c_client *client;

    i2c_fd = open("/dev/i2c-1", O_RDWR | O_SYNC);
    if (i2c_fd < 0) {
        perror("open /dev/i2c-1");
        exit(EXIT_FAILURE);
    }

    ret = ioctl(i2c_fd, I2C_SLAVE, SHT40_ADDR);
    if (ret < 0) {
        perror("ioctl I2C_SLAVE");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    client = &i2c_fd.i2c_client;
    client->write(client, 0x00, 0x00); // High-repeatability measurement command

    pthread_t thread;
    I2C_Context ctx = {i2c_fd, client};
    int status;

    if (pthread_create(&thread, NULL, read_and_log, &ctx) != 0) {
        perror("pthread_create");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    if (pthread_join(thread, NULL) != 0) {
        perror("pthread_join");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    close(i2c_fd);
    return 0;
}

