        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    if (pthread_join(thread, NULL) != 0) {
        perror("pthread_join");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    close(i2c_fd);
    return 0;
}
