volatile sig_atomic_t quit = 0;

void sigint_handler(int sig) {
    global_signal_set(SIGINT, SIG_IGN);
    global_signal_set(SIGTERM, SIG_IGN);
    quit = 1;
}

void cleanup() {
    close(logfd);
    pigpio_terminate(1);
}

int main(int argc, char *argv[]) {
    int logfd;
    pigpio_init(1);

    if (signal(SIGINT, sigint_handler) == SIG_IGN || signal(SIGTERM, sigint_handler) == SIG_IGN) {
        fprintf(stderr, "Failed to set signal handlers.\n");
        return 1;
    }

    logfd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (logfd == -1) {
        perror("Failed to open log file");
        cleanup();
        return 1;
    }

    while (!quit) {
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        double timestamp = (ts.tv_sec - 0) * 1e9 + (ts.tv_nsec / 1e6);

        int ret = 0;
        for (int i = 0; i < MAX_RETRIES; ++i) {
            ret = i2c_write_byte(logfd, 0x00); // Trigger measurement
            if (ret == -1) {
                ret = i2c_write_byte(logfd, 0x01); // Retry with exponential backoff
                if (ret == -1) {
                    fprintf(stderr, "I2C write failed after retries.\n");
                    continue;
                }
            }
            break;
        }

        if (ret == -1) {
            fprintf(stderr, "I2C write failed.\n");
            continue;
        }

        ret = i2c_read_byte(logfd);
        if (ret == -1) {
            fprintf(stderr, "I2C read failed.\n");
            continue;
        }

        uint8_t pressure_msb = ret & 0x7F;
        uint8_t pressure_lsb = ret >> 7;
        uint8_t crc = ret & 0x0F;
        uint8_t temp_msb = (ret >> 5) & 0x3F;
        uint8_t temp_lsb = ret >> 3;
        uint8_t temp_crc = ret >> 6;

        double pressure_pa = (pressure_msb << 8) | pressure_lsb;
        double temperature_c = ((temp_msb << 6) | temp_lsb) - 69; // Convert to Celsius

        char log_entry[100];
        sprintf(log_entry, "%.9f,%.2f\n", pressure_pa, temperature_c);
        write(logfd, log_entry, strlen(log_entry));

        usleep(SAMPLE_INTERVAL_MS * 1000 / 1000); // Adjust for 100ms interval
    }

    close(logfd);
    pigpio_terminate(1);
    cleanup();

    return 0;
}

int i2c_write_byte(int fd, uint8_t byte) {
    uint8_t buf[2];
    buf[0] = 0x20; // I2C write command
    buf[1] = byte;
    return write(fd, buf, 2);
}

int i2c_read_byte(int fd) {
    uint8_t buf[2];
    int ret = read(fd, buf, 2);
    if (ret == -1) {
        perror("i2c_read_byte");
        return -1;
    }
    return buf[0] << 8 | buf[1];
}

