#include <fcntl.h>
#include <errno.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SILICON_LABS_ID 0x40
#define SILICON_LABS_ADDRESS 0x40
#define SILICON_LABS_CMD_TEMP 0x0C
#define SILICON_LABS_CMD_HUMID 0x0D
#define SILICON_LABS_DATA_LENGTH 2
#define LOG_FILE "sensor_data.txt"

int i2c_fd;

void log_data(const char *timestamp, int temperature, int humidity) {
    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        fprintf(stderr, "Error opening file: %s\n", strerror(errno));
        return;
    }
    fprintf(file, "%s, %d, %d\n", timestamp, temperature, humidity);
    fclose(file);
}

int main() {
    int ret;
    struct i2c_client i2c_client;

    // Initialize pigpio
    if (piGPIO_init() < 0) {
        fprintf(stderr, "Error initializing pigpio: %s\n", strerror(errno));
        return 1;
    }

    // Initialize I2C
    i2c_fd = open("/dev/i2c-1", O_RDWR | O_NOCTTY);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        piGPIO_cleanup();
        return 1;
    }

    // Set I2C client
    memset(&i2c_client, 0, sizeof(i2c_client));
    i2c_client.device = SILICON_LABS_ADDRESS;
    i2c_client.bus = I2C_BUS;

    // Initialize I2C
    if (i2c_open_device(&i2c_client, i2c_fd) < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        close(i2c_fd);
        piGPIO_cleanup();
        return 1;
    }

    // Read temperature
    char temp_buf[SILICON_LABS_DATA_LENGTH];
    ret = i2c_read(i2c_fd, SILICON_LABS_CMD_TEMP, 1, temp_buf);
    if (ret < 0) {
        fprintf(stderr, "Error reading temperature: %s\n", strerror(errno));
        i2c_close(i2c_fd);
        piGPIO_cleanup();
        return 1;
    }
    int temperature = (temp_buf[0] << 8) | temp_buf[1];

    // Read humidity
    char hum_buf[SILICON_LABS_DATA_LENGTH];
    ret = i2c_read(i2c_fd, SILICON_LABS_CMD_HUMID, 1, hum_buf);
    if (ret < 0) {
        fprintf(stderr, "Error reading humidity: %s\n", strerror(errno));
        i2c_close(i2c_fd);
        piGPIO_cleanup();
        return 1;
    }
    int humidity = (hum_buf[0] << 8) | hum_buf[1];

    // Log data
    char timestamp[32];
    time_t now = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    log_data(timestamp, temperature, humidity);
    printf("Temperature: %d°C, Humidity: %d%%\n", temperature, humidity);

    // Sleep for 5 seconds
    usleep(50000000);

    // Repeat
    return 0;
}

