#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <errno.h>
#include <pthread.h>

#define I2C_BUS "/dev/i2c-1"
#define SENSOR_ADDRESS 0x4B
#define LOG_INTERVAL_MS 100
#define LOG_FILE "airflow_data.txt"

typedef struct {
    int fd;
    unsigned char command[3];
    unsigned char data[9];
} I2C_SDP800_Context;

void log_data(const char *timestamp, double pressure, double temperature) {
    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        perror("Failed to open log file");
        return;
    }
    fprintf(file, "%s,%.2f,%.2f\n", timestamp, pressure, temperature);
    fclose(file);
}

void read_sensor_data(I2C_SDP800_Context *context) {
    unsigned char crc[3];
    context->data[8] = context->data[9] = 0; // Ensure CRC is correctly calculated

    // Send the continuous measurement trigger command
    memcpy(context->command, {0x00, 0x00, 0x00}, 3);
    if (write(context->fd, context->command, 3) != 3) {
        perror("Failed to write command to I2C device");
        return;
    }

    // Wait for approximately 45ms
    usleep(45000);

    // Read nine bytes from the sensor
    if (read(context->fd, context->data, 9) != 9) {
        perror("Failed to read from I2C device");
        return;
    }

    // Validate CRC-8 words
    crc[0] = context->data[8] ^ context->data[7] << 2;
    crc[1] = context->data[9] ^ context->data[6] << 2;
    crc[2] = context->data[10] ^ context->data[5] << 2;

    if (crc[0] != context->data[8] || crc[1] != context->data[9] || crc[2] != context->data[10]) {
        fprintf(stderr, "CRC validation failed\n");
        return;
    }

    // Process pressure and temperature values
    double pressure = (context->data[3] << 8) | context->data[2];
    double temperature = (context->data[6] << 8) | context->data[5];

    // Log data
    char timestamp[32];
    time_t now = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    log_data(timestamp, pressure, temperature);
}

int main(int argc, char *argv[]) {
    I2C_SDP800_Context context;
    context.fd = open(I2C_BUS, O_RDWR | O_SYNC);
    if (context.fd == -1) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    context.command[0] = 0x00;
    context.command[1] = 0x00;
    context.command[2] = 0x00;

    // Start reading data in a separate thread
    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, (void *(*)(void *))read_sensor_data, &context) != 0) {
        perror("Failed to create thread");
        close(context.fd);
        return EXIT_FAILURE;
    }

    // Main loop, sleeping for LOG_INTERVAL_MS before reading again
    while (1) {
        usleep(LOG_INTERVAL_MS * 1000);
    }

    // Terminate the reading thread and clean up
    pthread_join(thread_id, NULL);
    close(context.fd);

    return EXIT_SUCCESS;
}

