#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <time.h>
#include <stdlib.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x40
#define SAMPLES_PER_SECOND 5
#define LOG_FILE "enclosure_temp_log.txt"
#define ERROR_LOG "error_log.txt"

void log_error(const char *msg) {
    time_t now = time(NULL);
    char timestamp[80];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    FILE *error_file = fopen(ERROR_LOG, "a");
    if (error_file) {
        fprintf(error_file, "%s - %s\n", timestamp, msg);
        fclose(error_file);
    }
}

void log_success(const char *msg) {
    time_t now = time(NULL);
    char timestamp[80];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file) {
        fprintf(log_file, "%s - %s\n", timestamp, msg);
        fclose(log_file);
    }
}

int main() {
    pigpio_init(5); // Initialize pigpio with 5 I2C busses

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        log_error("Failed to open log file.");
        return -1;
    }

    while (1) {
        struct timespec start, end;
        clock_gettime(CLOCK_REALTIME, &start);

        int sensor_address = I2C_ADDR;
        char command[2] = {0x43, 0x00}; // Single-shot high-repeatability measurement command
        int response_size = 3; // Two data bytes and one CRC byte

        int response_fd = i2c_open_channel(I2C_BUS, sensor_address);
        if (response_fd < 0) {
            log_error("Failed to open I2C channel.");
            continue;
        }

        if (i2c_transfer(response_fd, command, 2, &end) < 0) {
            log_error("Failed to write command to sensor.");
            i2c_close(response_fd);
            continue;
