#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <pthread.h>

#define SHT40_ADDRESS 0x43
#define CRC_POLYNOMIAL 0x07
#define CRC_INIT_VALUE 0x00

typedef struct {
    int fd;
    struct i2c_rdwr_ctx ctx;
} sht40_i2c_ctx;

static int sht40_read_data(int fd, void *buf, size_t size) {
    return read(fd, buf, size);
}

static int sht40_write(int fd, const void *buf, size_t size) {
    return write(fd, buf, size);
}

static int sht40_crc8(uint8_t crc, uint8_t data) {
    crc ^= data;
    for (int i = 0; i < 8; i++) {
        if ((crc & 0x01) == 1) {
            crc >>= 1;
        } else {
            crc >>= 1;
            crc ^= 0x07;
        }
    }
    return crc;
}

static int sht40_validate_data(uint8_t t_crc, uint8_t t_lsb, uint8_t t_msb,
                             uint8_t r_crc, uint8_t r_lsb, uint8_t r_lsb) {
    uint8_t calculated_crc = sht40_crc8(CRC_INIT_VALUE, t_msb | t_lsb);
    calculated_crc = sht40_crc8(calculated_crc, r_lsb | r_lsb);
    return calculated_crc == t_crc;
}

void *sht40_read_thread(void *arg) {
    sht40_i2c_ctx *ctx = (sht40_i2c_ctx *)arg;
    char response[7];
    uint8_t t_msb, t_lsb, t_crc, r_msb, r_lsb, r_crc;

    while (1) {
        int ret = sht40_read_data(ctx->fd, response, 6);
        if (ret < 0) {
            perror("sht40_read_data");
            return NULL;
        }

        t_msb = response[0];
        t_lsb = response[1];
        t_crc = response[2];
        r_msb = response[3];
        r_lsb = response[4];
        r_crc = response[5];

        if (sht40_validate_data(t_crc, t_lsb, t_msb, r_crc, r_lsb, r_lsb)) {
            uint64_t temperature = (uint64_t)t_msb << 8 | t_lsb;
            uint8_t humidity = (uint8_t)(r_lsb << 6 | r_lsb);

            FILE *log_file = fopen("sht40_log.txt", "a");
            if (!log_file) {
                perror("fopen");
                exit(EXIT_FAILURE);
            }

            time_t now = time(NULL);
            char timestamp[80];
            sprintf(timestamp, "%llu %d:%d:%d", (long double)temperature / 100.0,
                    now / 3600, now % 3600);
            fprintf(log_file, "%s: Temperature = %.1f°C, Humidity = %d%%\n",
                    timestamp, temperature / 100.0, humidity);
            fclose(log_file);
        } else {
            fprintf(stderr, "CRC validation failed, skipping reading\n");
        }

        usleep(5000000); // 5 seconds
    }

    return NULL;
}

int main(int argc, char *argv[]) {
    int fd, ret;
    struct i2c_dev *dev;
    sht40_i2c_ctx ctx;

    fd = open("/dev/i2c-1", O_RDWR | O_SYNC);
    if (fd < 0) {
        perror("open /dev/i2c-1");
        exit(EXIT_FAILURE);
    }

    dev = i2c_alloc(fd);
    if (!dev) {
        perror("i2c_alloc");
        close(fd);
        exit(EXIT_FAILURE);
    }

    ctx.fd = fd;
    ret = i2c_setup(dev, SHT40_ADDRESS);
    if (ret < 0) {
        perror("i2c_setup");
        i2c_free(dev);
        close(fd);
        exit(EXIT_FAILURE);
    }

    ctx.ctx.write_reg = sht40_write;
    ctx.ctx.read_reg = sht40_read_data;
    ctx.ctx.crc_validate = sht40_validate_data;

    pthread_t read_thread;
    int ret_thread = pthread_create(&read_thread, NULL, sht40_read_thread, &ctx);
    if (ret_thread != 0) {
        perror("pthread_create");
        i2c_free(dev);
        close(fd);
        exit(EXIT_FAILURE);
    }

    // Simulate SIGINT by waiting for 5 seconds
    sleep(5);
    kill(getpid(), SIGINT);

    pthread_join(read_thread, NULL);
    i2c_free(dev);
    close(fd);

    return 0;
}

