    uint8_t temp_data[2];

    for (int retry = 0; retry < RETRY_COUNT; retry++) {
        if (i2c_write_byte(fd, 0x00, &temp_data[0]) == 1 &&
            i2c_write_byte(fd, 0x01, &temp_data[1]) == 1) {
            break;
        }

        if (errno == EIO) {
            usleep(10000); // wait for 10ms
        } else {
            return -1;
        }
