#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <pthread.h>
#include <time.h>

#define SCD40_ADDRESS 0x43
#define I2C_BUS 1
#define I2C_ADDR 0x18
#define LOG_FILE "air_quality.log"
#define POLL_INTERVAL 5000 // 5 seconds

#define CRC8_POLYNOMIAL 0x07
#define CRC8_INIT 0x00

typedef struct {
    int fd;
    unsigned char data[9];
} SCD40_context;

static int i2c_open(const char *bus, int addr, struct i2c_rdwr *rdwr) {
    int ret;
    ret = open("/dev/i2c-" #bus, O_RDWR);
    if (ret < 0) {
        perror("Failed to open I2C bus");
        return ret;
    }
    ret = ioctl(ret, I2C_SLAVE, addr);
    if (ret < 0) {
        perror("Failed to set I2C address");
        close(ret);
        return ret;
    }
    return ret;
}

static int i2c_write(int fd, unsigned char *buf, size_t count) {
    return write(fd, buf, count);
}

static int i2c_read(int fd, unsigned char *buf, size_t count) {
    return read(fd, buf, count);
}

static int scd40_read_data(SCD40_context *ctx) {
    unsigned char cmd[1] = {0x44}; // Stop Periodic Measurement
    int ret = i2c_write(ctx->fd, cmd, 1);
    if (ret < 0) {
        perror("Failed to send Stop Periodic Measurement command");
        return ret;
    }

    ret = i2c_read(ctx->fd, ctx->data, 9);
    if (ret < 0) {
        perror("Failed to read data from SCD40");
        return ret;
    }

    // Verify CRC8
    unsigned char crc = 0;
    for (int i = 0; i < 9; i++) {
        crc ^= ctx->data[i];
        for (int j = 0; j < 8; j++) {
            crc <<= 1;
            if (crc & 0x80) {
                crc = crc >> 1;
                break;
            }
        }
    }
    if (crc != CRC8_INIT) {
        fprintf(stderr, "CRC verification failed\n");
        return -1;
    }

    // Extract CO₂, Temperature, and Humidity
    ctx->data[6] = (ctx->data[6] << 8) | ctx->data[7]; // Combine 2-byte words
    ctx->data[6] ^= CRC8_POLYNOMIAL;
    ctx->data[6] &= 0xFF; // Extract raw CO₂ value

    ctx->data[7] = (ctx->data[7] << 8) | ctx->data[8]; // Combine 2-byte words
    ctx->data[7] ^= CRC8_POLYNOMIAL;
    ctx->data[7] &= 0xFF; // Extract Temperature in °C

    ctx->data[8] = (ctx->data[8] << 8) | ctx->data[9]; // Combine 2-byte words
    ctx->data[8] ^= CRC8_POLYNOMIAL;
    ctx->data[8] &= 0xFF; // Extract Humidity in %

    return 0;
}

void *poll_and_log(void *arg) {
    SCD40_context *ctx = (SCD40_context *)arg;
    while (!feof(stdin)) {
        int ret = scd40_read_data(ctx);
        if (ret < 0) {
            break;
        }
        time_t now = time(NULL);
        char timestamp[20] = " ";
        strftime(timestamp + strlen(timestamp), sizeof(timestamp) - 1, "%Y-%m-%d %H:%M:%S", localtime(&now));
        fprintf(stdout, "%s%f,%.f,%.1f\n", timestamp, ctx->data[6] / 100.0, ctx->data[7] - 273.15, ctx->data[8]);
        fflush(stdout);
        usleep(POLL_INTERVAL * 1000);
    }
    return NULL;
}

int main(int argc, char *argv[]) {
    SCD40_context ctx;
    int fd = i2c_open(I2C_BUS, SCD40_ADDRESS, NULL);
    if (fd < 0) {
        return EXIT_FAILURE;
    }

    // Wait at least one second before the first read
    usleep(1000000);

    pthread_t poll_thread;
    int ret = pthread_create(&poll_thread, NULL, poll_and_log, &ctx);
    if (ret < 0) {
        close(fd);
        perror("Failed to create poll thread");
        return EXIT_FAILURE;
    }

    // Send Stop Periodic Measurement command
    unsigned char cmd[1] = {0x44};
    ret = i2c_write(fd, cmd, 1);
    if (ret < 0) {
        close(fd);
        fprintf(stderr, "Failed to send Stop Periodic Measurement command\n");
        return EXIT_FAILURE;
    }

    // Join the poll thread
    pthread_join(poll_thread, NULL);

    // Close I2C handle
    close(fd);

    // Terminate the driver
    return 0;
}

