#include <sys/time.h>
#include <signal.h>
#include <pthread.h>

#define SCD40_ADDR 0x43
#define BUFFER_SIZE 20
#define LED_PIN 17

typedef struct {
    int read_buf[2];
    int index;
} CircularBuffer;

CircularBuffer buffer;

void i2c_init(int fd) {
    if (ioctl(fd, I2C_SLAVE, SCD40_ADDR) < 0) {
        perror("I2C slave address not found");
        exit(EXIT_FAILURE);
    }
}

int i2c_read(int fd, unsigned char reg, unsigned char *data) {
    if (read(fd, data, 2) != 2) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

int i2c_write(int fd, unsigned char reg, unsigned char data) {
    if (write(fd, &data, 1) != 1) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

int validate_crc8(unsigned char data[2]) {
    unsigned char crc = 0;
    for (int i = 0; i < 2; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            crc <<= 1;
            if (crc & 0x1) {
                crc = crc >> 1;
                if (crc == 0) return 0;
            }
        }
    }
    return crc != 0;
}

void read_sensor(int fd) {
    unsigned char reg_read[2];
    if (i2c_read(fd, 0x00, reg_read) < 0) return;

    if (validate_crc8(reg_read) == 0) {
        printf("Invalid CRC, skipping data.\n");
        return;
    }

    buffer.read_buf[buffer.index] = reg_read[0];
    buffer.read_buf[1] = reg_read[1];
    buffer.index = (buffer.index + 1) % BUFFER_SIZE;

    if (buffer.index == 0) {
        printf("CO2: %d ppm, Temp: %d, Humidity: %d\n", buffer.read_buf[0], buffer.read_buf[1], 0);
    } else {
        printf("CO2: %d ppm, Temp: %d, Humidity: %d\n", buffer.read_buf[0], buffer.read_buf[1], buffer.read_buf[1]);
    }

    if (buffer.read_buf[0] > 1000) {
        gpio_set_led_state(LED_PIN, 1);
    } else {
        gpio_set_led_state(LED_PIN, 0);
