int validate_crc8(unsigned char data[2]) {
    unsigned char crc = 0;
    for (int i = 0; i < 2; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            crc <<= 1;
            if (crc & 0x1) {
