#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <libgpiod.h>

#define GPIO_PIN 7
#define POLLING_INTERVAL_MS 5000
#define TIMEOUT_MS 50
#define TEMP_MIN -40
#define TEMP_MAX 150

int main(int argc, char *argv[]) {
    int fd;
    struct stat sb;
    gpiod_context_t ctx;
    gpiod_button_t button;
    gpiod_button_init(&ctx, GPIO_PIN, GPIOD_IN, NULL);
    gpiod_button_enable(&ctx, GPIOD_BUTTON_DEbounce_COUNT_INFINITE);

    fd = open("temperature_log.txt", O_APPEND | O_CREAT | O_WRONLY, 0644);
    if (fd == -1) {
        perror("Error opening log file");
        return EXIT_FAILURE;
    }

    while (1) {
        time_t now = time(NULL);
        char timestamp[32];
        sprintf(timestamp, "%08d-%02d-%02d %02d:%02d:%02d",
            (now / 24) % 100, (now / 1440) % 100, (now / 86400) % 100,
            now % 24, now % 60, now % 60);

        int low_time, high_time;
        gpiod_get_btn_value(&ctx, &button, &low_time, &high_time);

        if (low_time == 0) {
            fprintf(fd, "ERROR: Low pulse time is zero\n");
            continue;
        }

        double temperature = (double)(high_time - low_time) * 1000.0 / (double)(1024.0 * 1000.0);

        if (temperature < TEMP_MIN || temperature > TEMP_MAX) {
            fprintf(fd, "ERROR: Temperature out of range\n");
            continue;
        }

        char log_entry[128];
        sprintf(log_entry, "Temperature: %.2f°C\tTimestamp: %s\n", temperature, timestamp);
        fprintf(fd, log_entry);

        if (strcmp(log_entry, "ERROR: Temperature out of range\n") == 0) {
            // Three consecutive errors, write "SENSOR MALFUNCTION"
            fprintf(fd, "SENSOR MALFUNCTION\n");
        }

        usleep(POLLING_INTERVAL_MS * 1000 / HRTIME_PER_SEC);
    }

    close(fd);
    gpiod_button_disable(&ctx);
    gpiod_context_destroy(&ctx);

    return EXIT_SUCCESS;
}

