#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>
#include <math.h>

#define I2C_BUS 1
#define SHT35_ADDRESS 0x43
#define LOG_FILE "environmental_data.txt"
#define LOG_INTERVAL 5000 // 5 seconds in milliseconds
#define RETRY_COUNT 3
#define DELAY_MS 1000

#define CRC_CHECK_SIZE 8

// SHT35 register addresses
#define SHT35_TEMP_REG 0x00
#define SHT35_HUMID_REG 0x01
#define SHT35_CRC_REG 0x02

// SHT35 default values
#define SHT35_TEMP_DEFAULT 0x00
#define SHT35_HUMID_DEFAULT 0x00
#define SHT35_CRC_DEFAULT 0x00

// Greenhouse offset
#define GREENHOUSE_OFFSET_TEMP 2.0
#define GREENHOUSE_OFFSET_HUMID 5.0

// Function to read I2C data with CRC check
int read_sht35(int file, unsigned char *data) {
    int retries = RETRY_COUNT;
    unsigned char crc = 0;
    unsigned char buffer[6];

    while (retries > 0) {
        if (read(file, buffer, 6) != 6) {
            if (errno == EIO || errno == EAGAIN) {
                retries--;
                usleep(DELAY_MS);
                continue;
            } else {
                fprintf(stderr, "Error reading from I2C bus\n");
                return -1;
            }
        }

        crc = buffer[5] ^ buffer[4] ^ buffer[3] ^ buffer[2] ^ buffer[1] ^ buffer[0];
        if (crc != SHT35_CRC_DEFAULT) {
            fprintf(stderr, "CRC check failed\n");
            retries--;
            usleep(DELAY_MS);
            continue;
        }

        data[0] = buffer[0];
        data[1] = buffer[1];
        data[2] = buffer[2];
        data[3] = buffer[3];
        data[4] = buffer[4];
        data[5] = buffer[5];
        break;
    }

    if (retries == 0) {
        fprintf(stderr, "Failed to read after retries\n");
        data[0] = 0xFF; // NaN value
    }

    return 0;
}

// Function to convert raw SHT35 values to Celsius and humidity percentage
void convert_sht35_values(unsigned char *data) {
    int temp = (data[0] << 8) | data[1];
    int humidity = (data[2] << 8) | data[3];

    double temp_c = (temp - SHT35_TEMP_DEFAULT) * 100.0 / 256.0 + 273.15;
    double humidity_percent = (humidity - SHT35_HUMID_DEFAULT) * 100.0 / 256.0;

    temp_c += GREENHOUSE_OFFSET_TEMP;
    humidity_percent += GREENHOUSE_OFFSET_HUMID;
}

// Function to log data with timestamp
void log_data(const char *data) {
    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        perror("Error opening log file");
        return;
    }

    time_t now = time(NULL);
    char timestamp[8];
    sprintf(timestamp, "%04d-%02d-%02d %02d:%02d:%02d",
            (now / 24) % 100, (now / 1440) % 100, (now / 86400) % 100,
            now % 24, now % 60, now % 60);

    fprintf(file, "%s,%f,%f\n", timestamp, data[0], data[1]);
    fclose(file);
}

int main() {
    int i2c_fd;
    int ret;

    // Initialize pigpio
    if (piGPIOInit() < 0) {
        perror("Failed to initialize pigpio");
        return EXIT_FAILURE;
    }

    // Open I2C bus
    ret = i2cSetup(I2C_BUS, 0x43);
    if (ret < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    // Create log file
    i2c_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (i2c_fd < 0) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        unsigned char data[6];
        ret = read_sht35(i2c_fd, data);
        if (ret < 0) {
            // Retry logic here
        }

        convert_sht35_values(data);
        log_data((double)data[0]); // Assuming data[0] is temperature

        usleep(LOG_INTERVAL * 1000 / 1000); // Sleep for LOG_INTERVAL ms
    }

    // Close I2C and log file
    close(i2c_fd);
    piGPIOExit();

    return EXIT_SUCCESS;
}

