#include <string.h>
#include <sht3x.h>

#define I2C_BUS 1
#define SHT35_ADDRESS 0x40
#define LOG_FILE "environment.csv"
#define SAMPLE_INTERVAL 5000 // 5 seconds

void log_entry(const char *entry) {
    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        perror("Failed to open file for appending");
        return;
    }
    fprintf(file, "%s", entry);
    fclose(file);
}

void handle_error(const char *msg) {
    fprintf(stderr, "Error: %s\n", msg);
    exit(EXIT_FAILURE);
}

int main() {
    sht3x_context ctx;
    struct i2c_client *client;
    char log_entry[100];

    // Initialize sht3x library
    if (sht3x_init(&ctx) < 0) {
        handle_error("Failed to initialize sht3x library");
    }

    // Open I2C bus
    client = i2c_open(I2C_BUS, "SHT3x");
    if (!client) {
        handle_error("Failed to open I2C bus");
    }

    // Check for CRC-8 checksum validation
    if (sht3x_check_crc(&ctx, 0) < 0) {
        handle_error("CRC validation failed");
    }

    // Initialize sensor
    if (sht3x_init(&ctx, SHT35_ADDRESS) < 0) {
        handle_error("Failed to initialize SHT35 sensor");
    }

    // Open log file
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        handle_error("Failed to open log file");
    }

    // Write header if file is empty or doesn't exist
    if (fseek(log_file, 0, SEEK_END) == 0) {
        long file_size = ftell(log_file);
        if (file_size == 0) {
            fprintf(log_file, "timestamp,temperature,humidity\n");
        }
    }
    rewind(log_file);

    while (1) {
        // Read temperature and humidity
        int result = sht3x_read_temperature_humidity(&ctx);
        if (result < 0) {
            handle_error("Failed to read sensor data");
        }

        // Convert to Celsius and percentage
        double temperature = result[0];
        double humidity = (double)result[1] / 100.0;

        // Format log entry
        time_t now = time(NULL);
        strftime(log_entry, sizeof(log_entry), "%Y-%m-%dT%H:%M:%S", localtime(&now));
        sprintf(log_entry + strlen(log_entry), "%s,%.1f,%.1f\n", log_entry, temperature, humidity);

        // Write to log file
        fprintf(log_file, log_entry);

        // Wait for next sample
        usleep(SAMPLE_INTERVAL * 1000000 / 1000);
    }

    // Clean shutdown
    i2c_close(client);
    sht3x_shutdown(&ctx);
    sht3x_exit(&ctx);

    return 0;
}

