#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <poll.h>
#include <time.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/epoll.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <sys/wait.h>
#include <sigaction.h>

#define I2C_BUS 1
#define I2C_ADDR 0x40
#define POLL_TIMEOUT 100
#define LOG_INTERVAL 5
#define CSV_FILE "environment.log"
#define RESET_COMMAND {0x40, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00}

typedef struct {
    int fd;
    struct i2c_rdwr_ctx ctx;
} i2c_handle_t;

static int i2c_open(const char *path, int bus, int addr, struct i2c_rdwr_req *req) {
    int ret;
    ret = open(path, O_RDWR | O_SYNC);
    if (ret < 0) {
        perror("open");
        return ret;
    }
    ret = ioctl(ret, I2C_SLAVE, addr);
    if (ret < 0) {
        perror("ioctl");
        close(ret);
        return ret;
    }
    return ret;
}

static int i2c_read(int fd, uint8_t *buf, size_t len) {
    return read(fd, buf, len);
}

static int i2c_write(int fd, const uint8_t *buf, size_t len) {
    return write(fd, buf, len);
}

static int i2c_close(int fd) {
    close(fd);
    return 0;
}

static int i2c_poll(int fd, struct i2c_rdwr_req *req, int timeout) {
    struct timeval tv;
    tv.tv_sec = timeout / 1000;
    tv.tv_usec = (timeout % 1000) * 1000;

    int ret = poll((struct pollent *) &tv, 1, timeout);
    if (ret == -1) {
        perror("poll");
        return -1;
    }
    if (ret == 0) {
        return -1; // Timeout
    }
    return req->res;
}

static int crc8(uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if ((crc & 0x01) != 0) {
                crc >>= 1;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static int si7021_read_temperature(i2c_handle_t *handle) {
    uint8_t buf[3];
    int ret = i2c_read(handle->fd, buf, 3);
    if (ret == -1) {
        perror("i2c_read");
        return -1;
    }
    if (buf[0] == 0xFF && buf[1] == 0x00 && buf[2] == 0x00) {
        // Reset command sent, retry
        ret = i2c_write(handle->fd, RESET_COMMAND, 8);
        if (ret == -1) {
            perror("i2c_write");
            return -1;
        }
        return si7021_read_temperature(handle);
    }
    uint8_t crc = buf[2];
    if (crc != 0x00) {
        fprintf(stderr, "CRC error\n");
        return -1;
    }
    uint16_t temp = (buf[0] << 8) | buf[1];
    if (temp > 0x7FFFF) {
        fprintf(stderr, "Temperature overflow\n");
        return -1;
    }
    return temp;
}

static int si7021_read_humidity(i2c_handle_t *handle) {
    uint8_t buf[3];
    int ret = i2c_read(handle->fd, buf, 3);
    if (ret == -1) {
        perror("i2c_read");
        return -1;
    }
    if (buf[0] == 0xFF && buf[1] == 0x00 && buf[2] == 0x00) {
        // Reset command sent, retry
        ret = i2c_write(handle->fd, RESET_COMMAND, 8);
        if (ret == -1) {
            perror("i2c_write");
            return -1;
        }
        return si7021_read_humidity(handle);
    }
    uint8_t crc = buf[2];
    if (crc != 0x00) {
        fprintf(stderr, "CRC error\n");
        return -1;
    }
    uint16_t hum = (buf[0] << 8) | buf[1];
    if (hum > 0x7FFFF) {
        fprintf(stderr, "Humidity overflow\n");
        return -1;
    }
    return hum;
}

int main(int argc, char *argv[]) {
    sigset_t sigset;
    memset(&sigset, 0, sizeof(sigset));
    sigaddset(&sigset, SIGINT);
    sigaddset(&sigset, SIGTERM);
    sigprocmask(SIG_BLOCK, &sigset, NULL);

    i2c_handle_t handle;
    handle.fd = i2c_open("/dev/i2c-1", I2C_BUS, I2C_ADDR, NULL);
    if (handle.fd == -1) {
        perror("i2c_open");
        exit(EXIT_FAILURE);
    }

    struct i2c_rdwr_req req_temp = {
        .start = (void *)0x44,
        .len = 3,
        .data = (void *)RESET_COMMAND
    };
    struct i2c_rdwr_req req_hum = {
        .start = (void *)0x46,
        .len = 3,
        .data = (void *)RESET_COMMAND
    };

    int ret;
    while (1) {
        ret = i2c_poll(handle.fd, &req_temp, POLL_TIMEOUT);
        if (ret == -1) {
            perror("i2c_poll");
            break;
        }
        if (ret == 0) {
            fprintf(stderr, "Timeout reading temperature\n");
            continue;
        }
        int temp = si7021_read_temperature(&handle);
        if (temp == -1) {
            continue;
        }
        ret = i2c_poll(handle.fd, &req_hum, POLL_TIMEOUT);
        if (ret == -1) {
            perror("i2c_poll");
            break;
        }
        if (ret == 0) {
            fprintf(stderr, "Timeout reading humidity\n");
            continue;
        }
        int hum = si7021_read_humidity(&handle);
        if (hum == -1) {
            continue;
        }

        time_t now = time(NULL);
        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", localtime(&now));

        FILE *fp = fopen(CSV_FILE, "a");
        if (!fp) {
            perror("fopen");
            continue;
        }
        fprintf(fp, "%s,%d,%d\n", timestamp, temp, hum);
        fclose(fp);

        usleep(LOG_INTERVAL * 1000000);
    }

    i2c_close(handle.fd);
    return 0;
}

