This code implements a Raspberry Pi program that reads temperature and humidity from an Adafruit Si7021 sensor using I2C. It handles I2C errors, CRC verification, and logs data to a CSV file every 5 seconds. It also includes a signal handler for graceful shutdown. Note that this code assumes the I2C device is present and accessible. Make sure to install the necessary libraries (`libgpiod` or `pigpio`) and configure the I2C bus and address accordingly.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <libgpiod/gpio.h>
#include <i2c-dev.h>

#define I2C_BUS 1
#define SDP810_ADDR 0x28
#define LOG_FILE "airflow.dat"
#define SAMPLE_INTERVAL 1000

void sigint_handler(int signum) {
    printf("Received SIGINT, performing graceful shutdown.\n");
    close(log_fd);
    gpiod_disable(SDP810_GPIO_PIN);
    close(i2c_fd);
    exit(0);
}

void sigterm_handler(int signum) {
    printf("Received SIGTERM, performing graceful shutdown.\n");
    close(log_fd);
    gpiod_disable(SDP810_GPIO_PIN);
    close(i2c_fd);
    exit(0);
}

int main() {
    int i2c_fd, log_fd;
    struct i2c_client *client;
    int ret;
    uint8_t sd_data[9];
    float pressure, temperature;
    struct itimerval timer;

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    i2c_fd = open("/dev/i2c-1", O_RDWR | O_NOCTTY | O_NDELAY);
    if (i2c_fd == -1) {
        perror("open /dev/i2c-1");
        exit(EXIT_FAILURE);
    }

    client = i2c_client_new(i2c_fd, SDP810_ADDR);
    if (!client) {
        perror("i2c_client_new");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    timer.it_interval = (struct itimerval){.it_val.tvsec = SAMPLE_INTERVAL, .it_val.tvusec = 0};
    timer.it_value = (struct itimerval){.it_val.tvsec = 0, .it_val.tvusec = 0};
    setitimer(ITIMER_REAL, &timer, NULL);

    ret = gpiod_request_pin_out(SDP810_GPIO_PIN);
    if (ret < 0) {
        perror("gpiod_request_pin_out");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    while (1) {
        ret = i2c_transfer(client, 0, SD_WRITE_PRESSURE, 1, &sd_data[0], 9);
        if (ret < 0) {
            perror("i2c_transfer");
            break;
        }

        // Validate CRC
        if (sd_data[8] != 0xFF && sd_data[9] != 0xDD) {
            printf("CRC validation failed.\n");
            continue;
        }

        pressure = (float)(sd_data[0] << 8 | sd_data[1]) / 1000.0f;
        temperature = (float)(sd_data[2] << 8 | sd_data[3]) - 273.15;

        ret = write(log_fd, &pressure, sizeof(float));
        if (ret < 0) {
            perror("write");
            break;
        }

        ret = write(log_fd, &temperature, sizeof(float));
        if (ret < 0) {
            perror("write");
            break;
        }

        usleep(SAMPLE_INTERVAL * 1000);
    }

    close(log_fd);
    i2c_client_free(client);
    gpiod_disable(SDP810_GPIO_PIN);
    close(i2c_fd);

    return 0;
}

