#include <sys/stat.h>
#include <pthread.h>

#define I2C_BUS 1
#define SDP800_ADDR 0x28
#define CONVERSION_TIME_MS 45000
#define LOG_INTERVAL_S 5
#define LOG_FILE "pressure_log.txt"

#define CRC8_POLYNOMIAL 0x07

typedef struct {
    int fd;
    unsigned char data[9];
} SDP800_Context;

void log_pressure(const char *timestamp, int pressure) {
    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        perror("Failed to open log file");
        return;
    }
    time_t now = time(NULL);
    fprintf(file, "%s %d\n", ctime(&now), pressure);
    fclose(file);
}

int read_pressure(SDP800_Context *ctx) {
    int ret;
    ret = ioctl(ctx->fd, I2C_SLAVE, SDP800_ADDR);
    if (ret < 0) {
        perror("Failed to set I2C slave address");
        return -1;
    }

    ctx->data[0] = 0x00;
    ctx->data[1] = 0x00;
    ctx->data[2] = 0x00;

    ret = ioctl(ctx->fd, I2C_MEM_READ, &ctx->data[0]);
    if (ret < 0) {
        perror("Failed to read from sensor");
        return -1;
    }

    // CRC calculation and validation (simplified for brevity)
    unsigned int crc = 0;
    for (int i = 0; i < 3; i++) {
        crc = (crc << 8) + ctx->data[i + 3];
    }
    if (crc != ctx->data[9]) {
        fprintf(stderr, "CRC validation failed\n");
        return -1;
    }

    log_pressure(ctime(NULL), ctx->data[2]);
    return 0;
}

int main(int argc, char *argv[]) {
    pthread_t thread;
    SDP800_Context ctx;
    int fd;

    if (argc != 2) {
        fprintf(stderr, "Usage: %s <log_interval_seconds>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    ctx.fd = open(LOG_FILE, O_WRONLY | O_CREAT, S_IRUSR | S_IWUSR);
    if (ctx.fd == -1) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    ctx.data[0] = 0x00;
    ctx.data[1] = 0x00;
    ctx.data[2] = 0x00;

    fd = open(LOG_FILE, O_RDWR | O_CREAT, S_IRUSR | S_IWUSR);
    if (fd == -1) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    ctx.fd = fd;

    // Start a separate thread to log pressure readings
    if (pthread_create(&thread, NULL, log_thread, &ctx) != 0) {
        perror("Failed to create log thread");
        close(fd);
        exit(EXIT_FAILURE);
    }

    while (1) {
        int ret = read_pressure(&ctx);
        if (ret < 0) {
            perror("Failed to read pressure");
            break;
        }
        usleep(CONVERSION_TIME_MS * 1000 / 1000); // Convert ms to microseconds
    }

    pthread_join(thread, NULL);
    close(ctx.fd);
    fclose(stdout);
    return 0;
}

void *log_thread(void *arg) {
    SDP800_Context *ctx = (SDP800_Context *)arg;
    while (1) {
        read_pressure(ctx);
        usleep(LOG_INTERVAL_S * 1000 * 1000 / 1000); // Convert seconds to microseconds
    }
    return NULL;
}

