    fprintf(log_file, "%s: %s\n", timestamp, msg);
    fclose(log_file);
}

void write_to_log_file(const char *msg) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        log_error("Failed to open log file for writing");
        return;
    }
    fprintf(log_file, "%s", msg);
    fclose(log_file);
}

int main() {
    int i2c_fd;
    struct i2c_client *client;
    struct lps33hw_context context;
    double pressure, temperature;

    gpioInit(); // Initialize GPIO library (if needed)

    i2c_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (i2c_fd == -1) {
        log_error("Failed to open log file: %s");
        return 1;
    }

    client = i2c_client_new(I2C_BUS, I2C_ADDRESS);
    if (!client) {
        log_error("Failed to create I2C client");
        close(i2c_fd);
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) == -1) {
        log_error("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    if (lps33hw_init(client, &context) != LPS33HW_OK) {
        log_error("Failed to initialize LPS33HW sensor");
        close(i2c_fd);
        return 1;
    }

    while (!graceful_exit) {
        lps33hw_get_pressure(&context, &pressure);
        lps33hw_get_temperature(&context, &temperature);

        time_t now = time(NULL);
        struct tm *local_time = localtime(&now);
        char timestamp[80];
        sprintf(timestamp, "%04d-%02d-%02d %02d:%02d:%02d",
                local_time->tm_year + 1900, local_time->tm_mon + 1,
                local_time->tm_mday, local_time->tm_hour, local_time->tm_min, local_time->tm_sec);

        write_to_log_file(printf("YYYY-MM-DD HH:MM:SS, Pressure: %.2f hPa, Temperature: %.2f °C\n", pressure, temperature));

        usleep(1000000); // Sleep for 1 second
    }

    close(i2c_fd);
    lps33hw_free(&context);
    gpioDeinit(); // Initialize GPIO library (if needed)

    write_to_log_file("Graceful exit initiated.\n");
    fsync(i2c_fd); // Ensure all data is written to disk
    close(i2c_fd);
    remove(LOG_FILE);

    log_error("Exiting gracefully.");
    return 0;
}
