#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define BUFFER_SIZE 10
#define LED_PIN 17
#define TEMP_SENSOR_ADDRESS 0x40

typedef struct {
    float temperatures[BUFFER_SIZE];
    int head;
    int tail;
} CircularBuffer;

CircularBuffer buffer;

void init_pigpio() {
    if (piGPIO_init() < 0) {
        perror("piGPIO init failed");
        exit(EXIT_FAILURE);
    }
}

int open_i2c_bus() {
    int file = open("/dev/i2c-1", O_RDWR);
    if (file < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(file, I2C_SLAVE, TEMP_SENSOR_ADDRESS) < 0) {
        close(file);
        perror("Failed to set I2C slave address");
        return -1;
    }

    return file;
}

float read_temperature() {
    unsigned char buffer[2];
    read(open_i2c_bus(), buffer, 2);
    return ((buffer[0] << 8) | buffer[1]) / 10.0;
}

void update_buffer(float temp) {
    buffer.temperatures[buffer.head] = temp;
    buffer.head = (buffer.head + 1) % BUFFER_SIZE;
    buffer.tail = (buffer.tail + 1) % BUFFER_SIZE;
}

float compute_average() {
    float sum = 0;
    for (int i = buffer.head; i != buffer.tail; i = (i + 1) % BUFFER_SIZE) {
        sum += buffer.temperatures[i];
    }
    return sum / BUFFER_SIZE;
}

void drive_led(float avg_temp) {
    if (avg_temp > 28.0) {
        gpioOutput(LED_PIN, 1);
    } else {
        gpioOutput(LED_PIN, 0);
    }
}

void cleanup() {
    close(open_i2c_bus);
    pigpio_terminate(8000);
}

int main(int argc, char *argv[]) {
    init_pigpio();

    while (1) {
        float temp = read_temperature();
        update_buffer(temp);
        float avg_temp = compute_average();
        drive_led(avg_temp);
        usleep(1000000); // Sleep for 1 second
    }

    cleanup();
    return 0;
}

