#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <pthread.h>
#include <time.h>
#include <iso646.h>
#include <libgpiod/gpio.h>
#include <scd30.h>

#define LOG_FILE "air_quality.log"
#define SAMPLE_INTERVAL_SEC 5.0
#define SCD30_I2C_ADDRESS 0x4B
#define SCD30_REG_CO2 0x00
#define SCD30_REG_TEMP 0x01
#define SCD30_REG_HUM 0x02

typedef struct {
    int fd;
    struct timespec timestamp;
} log_entry;

static log_entry log_entries[100];
static int log_entries_count = 0;
static int log_file_fd = -1;

static void log_entry(const char *timestamp, int co2, float temp, float hum) {
    log_entry log_entry_to_write = {log_file_fd, *timestamp};
    strftime(log_entry_to_write.timestamp.tv_sec, 10, "%Y-%m-%dT%H:%M:%S", localtime(&log_entry_to_write.timestamp.tv_sec));
    strftime(log_entry_to_write.timestamp.tv_nsec, 10, "%09ld", (long)((log_entry_to_write.timestamp.tv_sec) - 11644473600000000ULL);
    write(log_file_fd, "iso8601,co2,temp,humidity\n", 36);
    write(log_file_fd, "%s,%f,%f,%f\n", strftime("%Y-%m-%T", NULL), co2, temp, hum);
    log_entries[log_entries_count++] = log_entry_to_write;
    if (log_entries_count >= 100) {
        log_entries_count = 0;
    }
}

static void flush_log() {
    if (log_file_fd != -1) {
        write(log_file_fd, "\n", 1);
        fsync(log_file_fd);
        log_entries_count = 0;
    }
}

static void ventilation_control(int co2) {
    if (co2 < 800) {
        printf("CO2: %d ppm - Ventilation: OFF\n", co2);
    } else if (co2 >= 800 && co2 < 1200) {
        printf("CO2: %d ppm - Ventilation: LOW\n", co2);
    } else {
        printf("CO2: %d ppm - Ventilation: HIGH\n", co2);
    }
}

static void *read_sensor(void *arg) {
    scd30_t *sensor = (scd30_t *)arg;
    int co2, temp, hum;
    struct timespec timestamp;

    while (1) {
        if (scd30_read(sensor, SCD30_REG_CO2, &co2) != SCD30_OK ||
            scd30_read(sensor, SCD30_REG_TEMP, &temp) != SCD30_OK ||
            scd30_read(sensor, SCD30_REG_HUM, &hum) != SCD30_OK) {
            perror("Failed to read sensor data");
            return NULL;
        }

        log_entry(&timestamp, co2, temp, hum);
        ventilation_control(co2);
        flush_log();

        usleep(SAMPLE_INTERVAL_SEC * 1000000);
    }

    return NULL;
}

int main(int argc, char *argv[]) {
    int ret;
    pthread_t sensor_thread;

    if (argc < 2) {
        printf("Usage: %s <scd30_i2c_address>\n", argv[0]);
        return EXIT_FAILURE;
    }

    int scd30_fd = open(argv[1], O_RDWR | O_NOCTTY | O_NDELAY);
    if (scd30_fd == -1) {
        perror("Failed to open SCD30 I2C device");
        return EXIT_FAILURE;
    }

    ret = libgpiod_init(SCD30_I2C_ADDRESS);
    if (ret < 0) {
        perror("Failed to initialize SCD30 GPIO library");
        close(scd30_fd);
        return EXIT_FAILURE;
    }

    ret = libgpiod_set_mode(scd30_fd, libgpiod_mode_output);
    if (ret < 0) {
        perror("Failed to set SCD30 GPIO mode to output");
        libgpiod_cleanup();
        close(scd30_fd);
        return EXIT_FAILURE;
    }

    log_file_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_file_fd == -1) {
        perror("Failed to open log file");
        libgpiod_cleanup();
        close(scd30_fd);
        return EXIT_FAILURE;
    }

    ret = pthread_create(&sensor_thread, NULL, read_sensor, (void *)scd30_fd);
    if (ret != 0) {
        perror("Failed to create sensor reading thread");
        libgpiod_cleanup();
        close(scd30_fd);
        close(log_file_fd);
        return EXIT_FAILURE;
    }

    sigset_t sigset;
    pthread_sigmask(SIG_SETMASK, &sigset, 0);
    sigaddset(&sigset, SIGINT);
    sigaddset(&sigset, SIGTERM);

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sa.sa_handler = sigterm_handler;
    sigaction(SIGTERM, &sa, NULL);

    while (1) {
        usleep(1000000);
    }

    pthread_join(sensor_thread, NULL);
    libgpiod_cleanup();
    close(scd30_fd);
    close(log_file_fd);

    return EXIT_SUCCESS;
}

static void sigint_handler(int signum) {
    printf("Received SIGINT, stopping sensor reading...\n");
    pthread_join(sensor_thread, NULL);
    libgpiod_cleanup();
    close(scd30_fd);
    close(log_file_fd);
    exit(0);
}

static void sigterm_handler(int signum) {
    printf("Received SIGTERM, stopping sensor reading...\n");
    pthread_join(sensor_thread, NULL);
    libgpiod_cleanup();
    close(scd30_fd);
    close(log_file_fd);
    exit(0);
}

