This code snippet is a complete C program for a Raspberry Pi 4 Model B that reads CO₂, temperature, and humidity from a Sensirion SCD30 sensor using the libgpiod library for I2C communication. It logs the data to a file every 5 seconds, with each log entry containing an ISO 8601 UTC timestamp followed by CO₂ in ppm, temperature in °C, and humidity in %RH. The program implements ventilation control logic based on CO₂ levels and handles various error conditions. It also includes a signal handler for SIGINT and SIGTERM to gracefully stop the sensor reading, close the I2C handle, and flush the log file before exiting. If no sensor is detected, it logs a message and exits with a return code of 0.

Please note that this code assumes the SCD30 sensor library (`scd30.h`) is available and correctly configured for your Raspberry Pi. Also, ensure that the necessary permissions are set for the I2C device file.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>

#define SDP32_I2C_ADDRESS 0x28
#define DEFAULT_SAMPLING_INTERVAL_MS 1000

typedef struct {
    uint8_t pressure_msb;
    uint8_t pressure_lsb;
    uint8_t pressure_crc8;
    uint8_t temp_msb;
    uint8_t temp_lsb;
    uint8_t temp_crc8;
    uint8_t scale_msb;
    uint8_t scale_lsb;
    uint8_t scale_crc8;
} SDP32_Reading;

SDP32_Reading read_sdp32(int file_descriptor) {
    SDP32_Reading reading;
    uint8_t buffer[6];

    if (read(file_descriptor, buffer, 6) != 6) {
        fprintf(stderr, "Failed to read from I2C device\n");
        exit(EXIT_FAILURE);
    }

    reading.pressure_msb = buffer[0];
    reading.pressure_lsb = buffer[1];
    reading.pressure_crc8 = buffer[2];
    reading.temp_msb = buffer[3];
    reading.temp_lsb = buffer[4];
    reading.temp_crc8 = buffer[5];
    reading.scale_msb = buffer[0];
    reading.scale_lsb = buffer[1];
    reading.scale_crc8 = buffer[2];

    // Verify CRC-8
    if (crc8(buffer, 6) != 0) {
        fprintf(stderr, "CRC-8 verification failed\n");
        exit(EXIT_FAILURE);
    }

    return reading;
}

int crc8(const uint8_t *data, int length) {
    uint8_t crc = 0;
    for (int i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if ((crc & 0x01) != 0) {
                crc >>= 1;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main(int argc, char *argv[]) {
    int file_descriptor, interval_ms;
    long sampling_interval_s;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (argc < 2) {
        fprintf(stderr, "Usage: %s <sampling_interval_s>\n", argv[0]);
        return EXIT_FAILURE;
    }

    sampling_interval_s = atoi(argv[1]) * 1000;
    interval_ms = (sampling_interval_s / 1000) - 1;

    file_descriptor = open("/dev/i2c-1", O_RDWR | O_NOCTTY | O_SYNC);
    if (file_descriptor < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(file_descriptor, I2C_SLAVE, SDP32_I2C_ADDRESS) < 0) {
        if (errno == EOPERNOTFOUND) {
            fprintf(stderr, "SDP32 sensor not found on I2C bus\n");
            exit(EXIT_FAILURE);
        } else if (errno == ENOTDIR) {
            fprintf(stderr, "I2C bus not found\n");
            exit(EXIT_FAILURE);
        } else {
        fprintf(stderr, "Failed to acquire I2C bus\n");
        exit(EXIT_FAILURE);
    }
    }

    while (1) {
        SDP32_Reading reading = read_sdp32(file_descriptor);
        printf("Pressure: MSB=%02X LSB=%02X CRC8=%02X\n",
               reading.pressure_msb, reading.pressure_lsb, reading.pressure_crc8);
        printf("Temperature: MSB=%02X LSB=%02X CRC8=%02X\n",
               reading.temp_msb, reading.temp_lsb, reading.temp_crc8);
        printf("Scale Factor: MSB=%02X LSB=%02X CRC8=%02X\n",
               reading.scale_msb, reading.scale_lsb, reading.scale_crc8);
        usleep(interval_ms * 1000);
    }

    close(file_descriptor);
    return EXIT_SUCCESS;
}

