#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/wait.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SDA_PIN 2
#define SCL_PIN 3
#define DATA_SIZE 9
#define CRC_POLYNOMIAL 0x07

typedef struct {
    int fd;
    uint8_t address;
} i2c_handle_t;

static int i2c_open(const char *path, int *fd) {
    int ret;
    *fd = open(path, O_RDWR | O_SYNC);
    if (*fd < 0) {
        perror("open");
        return -1;
    }
    ret = ioctl(*fd, I2C_SLAVE, I2C_BUS);
    if (ret == -1) {
        perror("ioctl");
        close(*fd);
        return -1;
    }
    return *fd;
}

static int i2c_close(int fd) {
    close(fd);
    return 0;
}

static int i2c_read(int fd, uint8_t *buffer) {
    ssize_t ret = read(fd, buffer, DATA_SIZE);
    if (ret < 0) {
        perror("read");
        return -1;
    }
    return ret == DATA_SIZE;
}

static int i2c_write(int fd, const uint8_t *buffer) {
    ssize_t ret = write(fd, buffer, DATA_SIZE);
    if (ret < 0) {
        perror("write");
        return -1;
    }
    return ret == DATA_SIZE;
}

static int validate_crc(const uint8_t *data) {
    uint32_t crc = 0xFFFF;
    for (int i = 0; i < 3; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            crc <<= 1;
            if ((crc & 0x01) == 1) {
                crc ^= CRC_POLYNOMIAL;
            }
        }
    }
    return crc == 0;
}

static void handle_sensor_error(i2c_handle_t *handle) {
    fprintf(stderr, "Sensor error: CRC mismatch or sensor absent\n");
    i2c_close(handle->fd);
    handle->fd = -1;
}

int main(int argc, char *argv[]) {
    i2c_handle_t handle;
    int fd;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    fd = i2c_open("/dev/i2c-1", &handle);
    if (fd < 0) {
        return EXIT_FAILURE;
    }

    handle.address = 0x18; // SDP810-125Pa default address

    uint8_t buffer[DATA_SIZE];
    uint8_t crc[3];

    while (1) {
        if (!i2c_read(fd, buffer)) {
            memcpy(crc, buffer + 2, 3); // CRC words are at offset 2
            if (!validate_crc(crc)) {
                handle_sensor_error(&handle);
                continue;
            }

            // Assuming pressure and temperature are at offsets 0 and 1 respectively
            uint16_t pressure = (buffer[0] << 8) | buffer[1];
            uint16_t temperature = buffer[2];

            printf("Pressure: %d Pa, Temperature: %d °C\n", pressure, temperature);
        }

        usleep(45000000); // Wait for 45ms
    }

    i2c_close(fd);
    return EXIT_SUCCESS;

signal_handler:
{
    fprintf(stderr, "Received signal, cleaning up...\n");
    i2c_close(handle.fd);
    handle.fd = -1;
    return 0;
}
}

