#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SDA_PIN 2
#define SCL_PIN 3

#define TEMP_CONVERSION_DELAY 20000  // 20ms
#define LOG_INTERVAL 5000           // 5s

int i2c_fd;

int main(int argc, char *argv[]) {
    int ret;
    struct i2c_client i2c_client;
    char buffer[16];

    // Initialize wiringPi
    if (wiringPiSetup() < 0) {
        perror("wiringPiSetup");
        exit(EXIT_FAILURE);
    }

    // Initialize pigpio for DRDY pin (not used in this case, but included for completeness)
    if (piGPIOInit() < 0) {
        perror("piGPIOInit");
        exit(EXIT_FAILURE);
    }

    // Open I2C bus
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("open /dev/i2c-1");
        exit(EXIT_FAILURE);
    }

    // Set I2C mode
    ioctl(i2c_fd, I2C_SET_SPEED(1000000));

    // Create i2c_client structure
    memset(&i2c_client, 0, sizeof(i2c_client));
    i2c_client.device = (u8)I2C_BUS;
    i2c_client.address = 0x40;

    // Initialize HDC1000 sensor
    if (wiringPiI2CBegin(i2c_fd, SDA_PIN, SCL_PIN) < 0) {
        perror("wiringPiI2CBegin");
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (1) {
        ret = wiringPiI2CRead(i2c_fd, 0x00, 2, buffer);
        if (ret < 0) {
            perror("wiringPiI2CRead");
            fprintf(stderr, "Error reading from HDC1000\n");
            continue;
        }

        // Check for sensor presence (ACK)
        if (buffer[0] == 0x00 && buffer[1] == 0x00) {
            fprintf(stderr, "HDC1000 sensor not detected.\n");
            continue;
        }

        // Wait for conversion to complete
        usleep(TEMP_CONVERSION_DELAY);

        // Read temperature and humidity
        ret = wiringPiI2CRead(i2c_fd, 0x01, 2, buffer);
        if (ret < 0) {
            perror("wiringPiI2CRead");
            fprintf(stderr, "Error reading from HDC1000\n");
            continue;
        }

        // Convert bytes to float
        float temperature = (float)(buffer[0] << 8) / 100.0f;
        float humidity = (float)(buffer[1] << 8) / 100.0f;

        // Log the values
        printf("Temperature: %.2f C, Humidity: %.2f %%n", temperature, humidity);

        // Sleep before next log
        usleep(LOG_INTERVAL * 1000000);
    }

    // Clean up and exit
    close(i2c_fd);
    wiringPiI2CClose(i2c_fd);
    piGPIOExit();

    return 0;
}

