#include <pigpio.h>

#define I2C_BUS 1
#define SDA_PIN 2
#define SCL_PIN 3

#define TEMP_READ_INTERVAL_SECS 5

int main(int argc, char *argv[]) {
    int i2c_fd, temp_reg, data;
    struct i2c_client *client;
    struct si7051_reg_t temp_reg_data;

    // Initialize pigpio for GPIO control
    if (piGPIO_init() < 0) {
        perror("Failed to initialize pigpio");
        return EXIT_FAILURE;
    }

    // Initialize I2C communication
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        piGPIO_shutdown();
        return EXIT_FAILURE;
    }

    client = i2c_client_new(i2c_fd, 0x40); // Silicon Labs Si7051 I2C address
    if (!client) {
        perror("Failed to create I2C client");
        close(i2c_fd);
        piGPIO_shutdown();
        return EXIT_FAILURE;
    }

    // Read temperature register address
    temp_reg = SDA_PIN;
    if (ioctl(i2c_fd, I2C_SLAVE, client->addr) < 0) {
        perror("Failed to set I2C slave address");
        i2c_client_free(client);
        close(i2c_fd);
        piGPIO_shutdown();
        return EXIT_FAILURE;
    }

    // Read temperature register data
    if (ioctl(i2c_fd, WHO_AM_I, &temp_reg_data, sizeof(temp_reg_data)) < 0) {
        perror("Failed to read who am I");
        i2c_client_free(client);
        close(i2c_fd);
        piGPIO_shutdown();
        return EXIT_FAILURE;
    }

    if (temp_reg_data.reg_addr != 0x40) {
        fprintf(stderr, "Si7051 not found at 0x40\n");
        i2c_client_free(client);
        close(i2c_fd);
        piGPIO_shutdown();
        return EXIT_FAILURE;
    }

    // Start reading temperature
    temp_reg = SCL_PIN;
    if (ioctl(i2c_fd, I2C_MEM_READ, client, &temp_reg, &temp_reg_data, sizeof(temp_reg_data)) < 0) {
        perror("Failed to read temperature");
        i2c_client_free(client);
        close(i2c_fd);
        piGPIO_shutdown();
        return EXIT_FAILURE;
    }

    // Convert temperature from 100ths of a degree Celsius to degrees Celsius
    data = (temp_reg_data.data & 0x07) * 0.01;

    // Log temperature to console
    printf("Temperature: %.2f°C\n", data);

    // Sleep for the specified interval
    usleep(TEMP_READ_INTERVAL_SECS * 1000000);

    // Repeat until SIGINT or SIGTERM is received
    while (1) {
        sleep(TEMP_READ_INTERVAL_SECS);
    }

    // Clean up resources
    i2c_client_free(client);
    close(i2c_fd);
    piGPIO_shutdown();

    return EXIT_SUCCESS;
}

