    // Sleep for the specified interval
    usleep(TEMP_READ_INTERVAL_SECS * 1000000);

    // Repeat until SIGINT or SIGTERM is received
    while (1) {
        sleep(TEMP_READ_INTERVAL_SECS);
    }

    // Clean up resources
    i2c_client_free(client);
    close(i2c_fd);
    piGPIO_shutdown();

    return EXIT_SUCCESS;
}
