#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <stdlib.h>
#include <libgpiod/gpio.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x77
#define TEMP_REG 0x00
#define PRESS_REG 0x01
#define TEMP_SCALE 0.01
#define PRESS_SCALE 100

#define UPDATE_INTERVAL_SEC 5.0
#define LOG_FORMAT "Temperature: %fC, Pressure: %fPa"

void sigint_handler(int sig) {
    pigpio_stop();
    fprintf(stderr, "Received SIGINT, cleaning up and exiting.\n");
    exit(0);
}

void sigterm_handler(int sig) {
    pigpio_stop();
    fprintf(stderr, "Received SIGTERM, cleaning up and exiting.\n");
    exit(0);
}

void setup_i2c() {
    int fd = gpio_i2c_open(I2C_BUS);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (gpio_i2c_init(fd, 100000) < 0) {
        perror("Failed to initialize I2C bus");
        gpio_i2c_close(fd);
        exit(EXIT_FAILURE);
    }
}

void teardown_i2c() {
    gpio_i2c_close(I2C_BUS);
}

void read_sensor_data() {
    int temp_reg = TEMP_REG;
    int press_reg = PRESS_REG;
    int temp_data;
    int press_data;

    if (gpio_i2c_read_byte(I2C_BUS, I2C_ADDRESS, &temp_reg) < 0) {
        fprintf(stderr, "Error reading temperature register\n");
        return;
    }

    if (gpio_i2c_read_byte(I2C_BUS, I2C_ADDRESS, &press_reg) < 0) {
        fprintf(stderr, "Error reading pressure register\n");
        return;
    }

    temp_data = gpio_i2c_read_byte(I2C_BUS, I2C_ADDRESS);
    press_data = gpio_i2c_read_byte(I2C_BUS, I2C_ADDRESS);

    if (temp_data < 0 || press_data < 0) {
        fprintf(stderr, "Sensor not present or error reading data\n");
        return;
    }

    temp_data *= TEMP_SCALE;
    press_data *= PRESS_SCALE;

    printf("%s %s\n",
           __DATE__ " " __TIME__,
           LOG_FORMAT " %fC, %fPa\n",
           temp_data, press_data);
}

int main() {
    setup_i2c();

    while (1) {
        read_sensor_data();
        usleep(100000000 - 1000000); // 7ms delay
        sleep(UPDATE_INTERVAL_SEC);
    }

    teardown_i2c();

    // Register signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    return 0;
}

