#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>

#define I2C_BUS 1
#define I2C_ADDR 0x53
#define SAMPLE_INTERVAL 1000

typedef struct {
    int fd;
    long long last_read_time;
} sensor_data;

void i2c_read(int fd, unsigned char *reg, unsigned char *value, size_t len) {
    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        return;
    }

    if (read(fd, value, len) != len) {
        perror("read from I2C");
        return;
    }
}

sensor_data get_sensor_data() {
    sensor_data data;
    unsigned char reg_value[2];

    data.fd = open("/dev/i2c-1", O_RDWR | O_SYNC);
    if (data.fd < 0) {
        perror("open /dev/i2c-1");
        return data;
    }

    i2c_read(data.fd, 0x1A, reg_value, 2); // Read pressure data register

    data.last_read_time = time(NULL);

    close(data.fd);
    return data;
}

void handle_interrupt(int sig) {
    if (data.fd >= 0) {
        close(data.fd);
        data.fd = -1;
    }
}

int main() {
    signal(SIGINT, handle_interrupt);
    signal(SIGTERM, handle_interrupt);

    sensor_data data = get_sensor_data();

    while (true) {
        sensor_data new_data = get_sensor_data();

        if (new_data.fd < 0) {
            fprintf(stderr, "Failed to read sensor data.\n");
            continue;
        }

        if (new_data.last_read_time < data.last_read_time + SAMPLE_INTERVAL) {
            usleep(SAMPLE_INTERVAL * 1000);
            continue;
        }

        printf("Pressure: %d\n", new_data.reg_value[0]);
        data = new_data;

        // Reset last_read_time for the next interval
        data.last_read_time = time(NULL);
    }

    return 0;
}

