#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <pthread.h>

#define SDA_PIN 2
#define SCL_PIN 3
#define I2C_BUS 1
#define I2C_ADDR 0x4B
#define LOG_FILE "pressure_log.txt"

#define CRC8_POLYNOMIAL 0x07

typedef struct {
    int fd;
    struct i2c_client *client;
} i2c_context;

void i2c_write(int fd, uint8_t *buf, size_t len) {
    ssize_t ret = write(fd, buf, len);
    if (ret != len) {
        perror("i2c_write");
        exit(EXIT_FAILURE);
    }
}

void i2c_read(int fd, uint8_t *buf, size_t len) {
    ssize_t ret = read(fd, buf, len);
    if (ret != len) {
        perror("i2c_read");
        exit(EXIT_FAILURE);
    }
}

int validate_crc8(uint8_t *data, size_t len) {
    uint8_t crc = 0;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            crc <<= 1;
            if (crc & 0x01) {
                crc = 0x07 - crc;
            }
        }
    }
    return crc == 0;
}

void log_pressure_data(const char *timestamp, double pressure, double temperature) {
    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
    fprintf(file, "%s,%f,%f\n", timestamp, pressure, temperature);
    fclose(file);
}

int main(int argc, char *argv[]) {
    pthread_t thread;
    i2c_context i2c_ctx;

    if (argc < 2) {
        fprintf(stderr, "Usage: %s <temperature_sensor_address>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    i2c_ctx.fd = open(I2C_BUS, "i2c-dev");
    if (i2c_ctx.fd < 0) {
        perror("open i2c-dev");
        exit(EXIT_FAILURE);
    }

    i2c_ctx.client = i2c_get_device(i2c_ctx.fd, I2C_ADDR);
    if (!i2c_ctx.client) {
        perror("i2c_get_device");
        close(i2c_ctx.fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_ctx.fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(i2c_ctx.fd);
        exit(EXIT_FAILURE);
    }

    // Initialize sensor (not implemented here, should be done before program execution)

    while (1) {
        // Trigger measurement
        i2c_write(i2c_ctx.fd, (uint8_t *)"MEASURE", 5);

        // Read 9 bytes (3 words + CRC8)
        uint8_t data[9];
        i2c_read(i2c_ctx.fd, data, 9);

        // Validate CRC8
        if (!validate_crc8(data, 9)) {
            fprintf(stderr, "Invalid CRC8\n");
            continue;
        }

        // Process data (pressure and temperature extraction)
        double pressure = (data[0] << 8) | data[1];
        double temperature = (data[2] << 8) | data[3];

        // Log data
        char timestamp[32];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        log_pressure_data(timestamp, pressure, temperature);

        // Sleep for 45ms
        usleep(45000000);
    }

    close(i2c_ctx.fd);
    pthread_cancel(thread);
    pthread_join(thread, NULL);

    return 0;
}

