#include <fcntl.h>
#include <pthread.h>
#include <time.h>

#define SDP800_ADDRESS 0x28
#define CRCPOL 8
#define CRCIV 0x00

#define LOG_FILE "airflow_log.csv"

typedef struct {
    int file;
    time_t timestamp;
} LogEntry;

static pthread_t log_thread;
static LogEntry log_entries[100];
static int log_entries_count = 0;

static int open_log_file() {
    int file = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (file == -1) {
        return errno;
    }
    return 0;
}

static int close_log_file() {
    close(log_entries[0].file);
    return 0;
}

static int log_entry(double pressure) {
    time_t now = time(NULL);
    LogEntry entry = {log_entries[0].file, now};
    entry.timestamp = now;
    entry.pressure = pressure;
    log_entries[log_entries_count++] = entry;
    return 0;
}

static int write_log_file() {
    int result = 0;
    FILE *file = fopen(LOG_FILE, "a");
    if (file) {
        for (int i = 0; i < log_entries_count; i++) {
            fprintf(file, "%ld,%f\n", log_entries[i].timestamp, log_entries[i].pressure);
        }
        fclose(file);
        log_entries_count = 0;
        result = 0;
    }
    return result;
}

static int init_i2c() {
    int file = open("/dev/i2c-1", O_RDWR);
    if (file == -1) {
        return errno;
    }

    if (ioctl(file, I2C_SLAVE, SDP800_ADDRESS) == -1) {
        close(file);
        return errno;
    }

    return 0;
}

static int read_pressure() {
    unsigned char data[3];
    int result = read(file, data, 3);
    if (result != 3) {
        return errno;
    }

    // Verify CRC-8
    unsigned char crc = 0;
    for (int i = 0; i < 2; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            crc <<= 1;
            if (crc & 0x80) {
                crc = crc >> 1;
            } else {
                break;
            }
        }
    }
    if (crc != CRCIV) {
        return -1; // CRC mismatch
    }

    double pressure = ((data[0] << 8) | data[1]) / 1000.0; // Convert to Pascals
    return pressure;
}

static void* read_thread(void* arg) {
    while (1) {
        double pressure = read_pressure();
        if (pressure == -1) {
            break;
        }
        log_entry(pressure);
        write_log_file();
        sleep(8); // Wait at least 8ms
    }
    return NULL;
}

int main(int argc, char* argv[]) {
    int file = open_log_file();
    if (file == -1) {
        return 1;
    }

    if (init_i2c() == -1) {
        close(file);
        return 1;
    }

    pthread_create(&log_thread, NULL, read_thread, NULL);

    // Wait for SIGINT or SIGTERM
    int sigint_mask = SIGINT;
    int sigterm_mask = SIGTERM;
    while (1) {
        int result = pthread_join(log_thread, NULL);
        if (result == 0) {
            if (access(LOG_FILE, F_OK) == 0) {
                if (write_log_file() == -1) {
                    close(file);
                    return 1;
                }
            } else {
                log_entries_count = 0;
                close_log_file();
                open_log_file();
            }
        }
        if (signal(SIGINT) == SIG_IGN || signal(SIGTERM) == SIG_IGN) {
            break;
        }
    }

    close(file);
    close_log_file();
    return 0;
}

