This code sets up a Raspberry Pi 4 Model B to continuously read pressure data from a Sensirion SDP800-500Pa sensor via I2C. It logs the timestamped pressure values to a file named `airflow_log.csv`, ensuring that a header row is added only when the file is newly created. The program handles errors on every I2C call, detects and handles sensor-absent or bus-error conditions, and ensures all resources are cleanly released on normal termination or receipt of SIGINT or SIGTERM.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <libgpiod/gpio.h>
#include <pigpio.h>

#define I2C_BUS 1
#define MLX90821_ADDRESS 0x5A
#define LOG_FILE "pressure_log.csv"
#define SAFE_PRESSURE_RANGE 200.0, 250.0

void sigint_handler(int sig) {
    close_i2c_handle();
    close_log_file();
    printf("Received SIGINT, exiting...\n");
    exit(0);
}

void sigterm_handler(int sig) {
    close_i2c_handle();
    close_log_file();
    printf("Received SIGTERM, exiting...\n");
    exit(0);
}

int main(int argc, char *argv[]) {
    int i2c_fd, log_fd;
    struct i2c_client *client;
    gpio_adrc_config_t adrc_config;
    double pressure;

    // Initialize signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Initialize libpigpio
    if (pigpio_init() < 0) {
        perror("Failed to initialize pigpio");
        return EXIT_FAILURE;
    }

    // Open I2C bus
    if ((i2c_fd = open(LOG_FILE, O_WRONLY | O_CREAT, 0644)) < 0) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    client = i2c_open_dev(I2C_BUS, MLX90821_ADDRESS);
    if (!client) {
        perror("Failed to open I2C client");
        return EXIT_FAILURE;
    }

    // Check if the file is newly created
    if (fstat(i2c_fd, NULL) == -1 || lseek(i2c_fd, 0, SEEK_END) == -1) {
        if (write("timestamp,pressure_kPa\n", 16, 1) == -1) {
            perror("Failed to write header");
            return EXIT_FAILURE;
        }
    }

    while (1) {
        // Read pressure from the sensor
        if (i2c_write_reg(client, MLX90821_ADDRESS, 0x00) == -1 ||
            i2c_read_byte(client, MLX90821_ADDRESS, 0x01) == -1) {
            perror("Failed to read from sensor");
            close_i2c_handle();
            close_log_file();
            continue;
        }

        pressure = (double)i2c_read_byte(client, MLX90821_ADDRESS, 0x01) * 0.0299;

        // Check if pressure is outside the safe range
        if (pressure < SAFE_PRESSURE_RANGE[0] || pressure > SAFE_PRESSURE_RANGE[1]) {
            fprintf(stderr, "Warning: Pressure out of safe range (%.1f kPa)\n", pressure);
        }

        // Append data to the log file
        if (write(i2c_fd, ",%.1f\n", pressure) == -1) {
            perror("Failed to write to log file");
            close_i2c_handle();
            close_log_file();
            continue;
        }

        // Flush and close the log file
        if (fflush(i2c_fd) == -1 || close(i2c_fd) == -1) {
            perror("Failed to flush and close log file");
            close_i2c_handle();
            return EXIT_FAILURE;
        }

        // Sleep for one second
        usleep(1000000);
    }

    // Close I2C handle and log file
    close_i2c_handle();
    close_log_file();

    return EXIT_SUCCESS;
}

// Helper functions
int close_i2c_handle(void) {
    i2c_close(client);
    close(i2c_fd);
    return 0;
}

int close_log_file(void) {
    close(i2c_fd);
    return 0;
}

