#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x19
#define LOG_FILE "environmental_data.log"
#define TRUNCATE_SIZE 1024 * 1024  // 1 MB

int open_log_file(const char *filename) {
    int fd = open(filename, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (fd == -1) {
        perror("Error opening log file");
        return -1;
    }
    struct stat sb;
    if (fstat(fd, &sb) == -1) {
        close(fd);
        perror("Error getting file stats");
        return -1;
    }
    if (sb.st_size >= TRUNCATE_SIZE) {
        if (truncate(filename, 0) == -1) {
            perror("Error truncating log file");
            close(fd);
            return -1;
        }
    }
    return fd;
}

void write_log(const char *data) {
    int fd = open_log_file(LOG_FILE);
    if (fd == -1) {
        return;
    }
    char timestamp[32];
    time_t now = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%T", localtime(&now));
    write(fd, timestamp, strlen(timestamp));
    write(fd, data, strlen(data));
    close(fd);
}

int main(int argc, char *argv[]) {
    int fd, ret;
    struct i2c_client *client;
    char log_data[100];

    fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (fd == -1) {
        perror("Error opening log file");
        return 1;
    }

    client = i2c_open(I2C_BUS, I2C_ADDR);
    if (client == NULL) {
        perror("Error opening I2C bus");
        close(fd);
        return 1;
    }

    while (1) {
        ret = i2c_transfer(client, 0x19, 0x00, 1, log_data, sizeof(log_data) - 1);
        if (ret < 0) {
            perror("I2C transfer failed");
            write_log("I2C error");
            continue;
        }
        log_data[ret] = '\0';
        write_log(log_data);

        // Wait for 40 ms
        usleep(40000);

        // Read sensor data
        ret = i2c_transfer(client, 0x19, 0x00, 2, &temp, sizeof(temp));
        if (ret < 0) {
            perror("I2C transfer failed");
            write_log("I2C error");
            continue;
        }
        temp = (int)temp;

        ret = i2c_transfer(client, 0x19, 0x00, 2, &humidity, sizeof(humidity));
        if (ret < 0) {
            perror("I2C transfer failed");
            write_log("I2C error");
            continue;
        }
        humidity = (int)humidity;

        // Check sensor status bits
        if ((client->status & 0x80) == 0) {
            write_log("Sensor not present");
            break;
        }

        // Write data to log file
        write_log("Temperature: %d C, Humidity: %d%%\n", temp, humidity);

        // Sleep for 5 seconds
        usleep(50000000);
    }

    i2c_close(client);
    close(fd);
    return 0;
}

