#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <pthread.h>
#include <libgpiod.h>

#define SENT_TICK_TIME 3e-6  // 3 microseconds
#define SENT_SYNC_PULSE 56   // 56 ticks
#define SENT_DATA_WIDTH 3    // 3 data nibbles
#define SENT_STATUS_WIDTH 1   // 1 status nibble

#define BUFFER_SIZE 1024

typedef struct {
    int fd;
    gpiopin *gpio;
    gpiopin *sync;
    gpiopin *data;
    gpiopin *status;
    pthread_t thread;
    char log_file[20];
    FILE *log_fp;
    time_t last_read_time;
} sensor_context;

void read_sensor(sensor_context *ctx) {
    unsigned int data[SENT_DATA_WIDTH + SENT_STATUS_WIDTH];
    unsigned int sync_pulse = 0;
    unsigned int status_nibble = 0;
    unsigned int data_nibbles[SENT_DATA_WIDTH];

    // Wait for synchronization pulse
    while (sync_pulse == 0) {
        usleep((uint32_t)(SENT_TICK_TIME * 500));
        sync_pulse = gdinput(ctx->sync, 1);
    }

    // Read data nibbles
