    // Check for checksum
    if (status_nibble != 0x00) {
        fprintf(stderr, "Checksum mismatch\n");
        return;
    }

    // Convert nibbles to integer
    int brake_pressure = 0;
    for (int i = 0; i < SENT_DATA_WIDTH; i++) {
        brake_pressure = (brake_pressure << 8) | data_nibbles[i];
