#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <errno.h>
#include <pthread.h>

#define I2C_BUS 1
#define I2C_ADDR 0x43
#define LOG_FILE "greenhouse_temps.dat"
#define LOG_INTERVAL 60

typedef struct {
    int fd;
    struct i2c_client *client;
} i2c_handle_t;

void log_temperature(float temp) {
    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        perror("Failed to open log file");
        return;
    }
    fwrite(&temp, sizeof(float), 1, file);
    fclose(file);
}

void init_i2c() {
    int file = open("/dev/i2c-1", O_RDWR);
    if (file < 0) {
        perror("Failed to open i2c bus");
        exit(EXIT_FAILURE);
    }

    struct i2c_client *client;
    if (ioctl(file, I2C_CLIENT, &client) < 0) {
        perror("Failed to get i2c client");
        close(file);
        exit(EXIT_FAILURE);
    }

    if (client->address != I2C_ADDR) {
        fprintf(stderr, "I2C device at address 0x%02x is not the TMP117\n", client->address);
        close(file);
        exit(EXIT_FAILURE);
    }
}

void setup_logging() {
    int flags = O_CREAT | O_APPEND | O_WRONLY;
    int mode = S_IRUSR | S_IWUSR;
    int fd = open(LOG_FILE, flags, mode);
    if (fd < 0) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
}

void cleanup() {
    close(fd);
    fclose(stdout);
    close(stdin);
    close(stdout);
    close(stderr);
    close(file);
    free(client);
    free(i2c_handle);
}

int main(int argc, char *argv[]) {
    pthread_t thread_id;
    i2c_handle_t i2c_handle;

    init_i2c();
    setup_logging();

    i2c_handle.fd = open(LOG_FILE, O_WRONLY | O_CREAT, S_IRUSR | S_IWUSR);
    if (i2c_handle.fd < 0) {
        perror("Failed to open log file for writing");
        cleanup();
        exit(EXIT_FAILURE);
    }
    i2c_handle.client = i2c_get_client(I2C_BUS, I2C_ADDR);
    if (!i2c_handle.client) {
        perror("Failed to get i2c client");
        close(i2c_handle.fd);
        cleanup();
        exit(EXIT_FAILURE);
    }

    while (1) {
        float temp;
        int result = i2c_transfer(i2c_handle.client, 0x48, 0, 1, &temp, 1);
        if (result < 0) {
            fprintf(stderr, "I2C transfer failed: %s\n", strerror(errno));
            usleep(LOG_INTERVAL * 1000000); // Sleep for the interval
            continue;
        }

        log_temperature(temp);
        usleep(LOG_INTERVAL * 1000000); // Sleep for the interval
    }

    cleanup();
    return 0;
}

int i2c_transfer(struct i2c_client *client, uint8_t reg, uint8_t cmd, uint8_t len, void *buf, size_t len_buf) {
    int ret = i2c_msg(client, reg, cmd, buf, len_buf);
    if (ret < 0) {
        perror("I2C transfer failed");
        return ret;
    }
    return 0;
}

