#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <libgpiod/gpio.h>

#define I2C_BUS 1
#define SHT40_ADDRESS 0x40
#define LOG_FILE "environmental_data.txt"
#define SAMPLE_INTERVAL 5000 // 5 seconds in milliseconds
#define CRC_POLYNOMIAL 0x07

// Function to read data from SHT40 sensor
int read_sht40(uint8_t *temp, uint8_t *humidity) {
    uint8_t cmd[2] = {0x43, 0x00}; // Read temperature and humidity
    uint8_t crc[1];

    // Write command to SHT40
    if (gpiod_write_i2c_mem_addr(I2C_BUS, SHT40_ADDRESS, cmd, 2) < 0) {
        perror("Failed to write to SHT40");
        return -1;
    }

    // Read data
    if (gpiod_read_i2c_mem_addr(I2C_BUS, SHT40_ADDRESS, temp, 2) < 0) {
        perror("Failed to read from SHT40");
        return -1;
    }

    if (gpiod_read_i2c_mem_addr(I2C_BUS, SHT40_ADDRESS, crc, 1) < 0) {
        perror("Failed to read CRC from SHT40");
        return -1;
    }

    // Validate CRC
    if (crc_validate(crc, temp, 2) == 0) {
        return -1; // CRC failed
    }

    // Read humidity
    if (gpiod_read_i2c_mem_addr(I2C_BUS, SHT40_ADDRESS, humidity, 1) < 0) {
        perror("Failed to read humidity from SHT40");
        return -1;
    }

    return 0;
}

// Function to validate CRC-8
int crc_validate(const uint8_t *crc, const uint8_t *data, int length) {
    uint32_t crc_value = 0;
    for (int i = 0; i < length; i++) {
        crc_value = (crc_value << 8) ^ data[i];
        for (int j = 0; j < 8; j++) {
            if ((crc_value & 0x80) != 0) {
                crc_value = (crc_value << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc_value <<= 1;
            }
        }
    }
    return (crc_value == *crc);
}

// Function to write data to file
int write_to_file(const char *data) {
    int fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (fd < 0) {
        perror("Failed to open file");
        return -1;
    }

    if (write(fd, data, strlen(data)) < 0) {
        perror("Failed to write to file");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Signal handler for SIGINT
void signal_handler(int signum) {
    if (read_sht40(temp, humidity) < 0) {
        fprintf(stderr, "Error reading from SHT40\n");
    }

    // Clean up and exit
    close_sht40();
    close_log_file();
    exit(signum == SIGINT ? 0 : 1);
}

int main() {
    sigset_t sigset;
    memset(&sigset, 0, sizeof(sigset));
    sigaddset(&sigset, SIGINT);
    sigprocmask(SIG_BLOCK, &sigset, NULL);

    // Initialize libgpiod
    if (libgpiod_init() < 0) {
        fprintf(stderr, "Failed to initialize libgpiod\n");
        return 1;
    }

    // Open I2C interface
    if (gpiod_open_i2c_bus(I2C_BUS) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    // Initialize SHT40 sensor
    if (gpiod_init_device(I2C_BUS, SHT40_ADDRESS) < 0) {
        fprintf(stderr, "Failed to initialize SHT40\n");
        return 1;
    }

    // Main loop
    while (1) {
        uint8_t temp[2], humidity[1];
        if (read_sht40(temp, humidity) < 0) {
            fprintf(stderr, "Failed to read from SHT40\n");
            continue;
        }

        // Append data to file
        char timestamp[20] = "Current Date: ";
        time_t now = time(NULL);
        strftime(timestamp + strlen(timestamp), sizeof(timestamp) - 1, "%Y-%m-%d %H:%M:%S", localtime(&now));
        char data_str[50] = "Temperature: ";
        sprintf(data_str + strlen(data_str), "%d°C, Humidity: %d%%", temp[0], humidity[0]);
        write_to_file(data_str);

        // Wait for next sample
        usleep(SAMPLE_INTERVAL / 1000);
    }

    // Clean up
    close_sht40();
    close_log_file();
    return 0;
}

// Close SHT40 device
void close_sht40() {
    gpiod_close_device(I2C_BUS, SHT40_ADDRESS);
    gpiod_close_bus(I2C_BUS);
    libgpiod_cleanup();
}

// Close log file
void close_log_file() {
    close(fildes);
}

