    if (read_sht40(temp, humidity) < 0) {
        fprintf(stderr, "Error reading from SHT40\n");
    }

    // Clean up and exit
    close_sht40();
    close_log_file();
    exit(signum == SIGINT ? 0 : 1);
}

int main() {
    sigset_t sigset;
    memset(&sigset, 0, sizeof(sigset));
    sigaddset(&sigset, SIGINT);
    sigprocmask(SIG_BLOCK, &sigset, NULL);

    // Initialize libgpiod
    if (libgpiod_init() < 0) {
        fprintf(stderr, "Failed to initialize libgpiod\n");
        return 1;
    }

    // Open I2C interface
    if (gpiod_open_i2c_bus(I2C_BUS) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    // Initialize SHT40 sensor
    if (gpiod_init_device(I2C_BUS, SHT40_ADDRESS) < 0) {
        fprintf(stderr, "Failed to initialize SHT40\n");
        return 1;
    }

    // Main loop
    while (1) {
        uint8_t temp[2], humidity[1];
        if (read_sht40(temp, humidity) < 0) {
            fprintf(stderr, "Failed to read from SHT40\n");
            continue;
        }

        // Append data to file
        char timestamp[20] = "Current Date: ";
        time_t now = time(NULL);
        strftime(timestamp + strlen(timestamp), sizeof(timestamp) - 1, "%Y-%m-%d %H:%M:%S", localtime(&now));
        char data_str[50] = "Temperature: ";
        sprintf(data_str + strlen(data_str), "%d°C, Humidity: %d%%", temp[0], humidity[0]);
        write_to_file(data_str);

        // Wait for next sample
        usleep(SAMPLE_INTERVAL / 1000);
    }

    // Clean up
    close_sht40();
    close_log_file();
    return 0;
}

// Close SHT40 device
void close_sht40() {
    gpiod_close_device(I2C_BUS, SHT40_ADDRESS);
    gpiod_close_bus(I2C_BUS);
    libgpiod_cleanup();
}

// Close log file
void close_log_file() {
    close(fildes);
}
