#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define SHTC3_ADDRESS 0x40
#define SHTC3_CMD_READ_TEMP 0x00
#define SHTC3_CMD_READ_HUMID 0x01
#define SHTC3_CRC_POLYNOMIAL 0x07

#define LOG_FILE "shtc3_environment.log"

void crc8(unsigned char *crc, const unsigned char *data, int len) {
    unsigned char temp = 0;
    for (int i = 0; i < len; i++) {
        temp = (temp << 8) ^ data[i];
        for (int j = 0; j < 8; j++) {
            if ((temp & 0x80) != 0) {
                temp = temp << 1 ^ 0x07;
            } else {
                temp <<= 1;
            }
        }
    }
    *crc = temp;
}

int validate_reading(unsigned char crc, unsigned char *data) {
    unsigned char calculated_crc = 0;
    crc8(&calculated_crc, data, 2);
    return calculated_crc == crc;
}

int main() {
    int file;
    char buffer[64];
    time_t now;
    struct tm *local_time;

    file = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (file == -1) {
        perror("Error opening log file");
        exit(EXIT_FAILURE);
    }

    local_time = localtime(&now);
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", local_time);
    fprintf(file, "%s, ", buffer);

    while (1) {
        int shtc3_fd = open("/dev/i2c-1", O_RDWR);
        if (shtc3_fd == -1) {
            perror("Error opening I2C bus");
            exit(EXIT_FAILURE);
        }

        if (ioctl(shtc3_fd, I2C_SLAVE, SHTC3_ADDRESS) == -1) {
            perror("Error setting I2C slave address");
            close(shtc3_fd);
            exit(EXIT_FAILURE);
        }

        if (write(shtc3_fd, SHTC3_CMD_READ_TEMP, 1) == -1) {
            perror("Error writing temperature command");
            close(shtc3_fd);
            exit(EXIT_FAILURE);
        }
        if (write(shtc3_fd, SHTC3_CMD_READ_HUMID, 1) == -1) {
            perror("Error writing humidity command");
            close(shtc3_fd);
            exit(EXIT_FAILURE);
        }

        if (read(shtc3_fd, &data, 2) != 2) {
            perror("Error reading from sensor");
            close(shtc3_fd);
            exit(EXIT_FAILURE);
        }

        if (!validate_reading(data[1], data)) {
            fprintf(stderr, "CRC failure\n");
            continue;
        }

        float temperature = ((data[0] << 8) | data[1]) / 10.0;
        float humidity = ((data[1] << 8) / 100.0) / 256.0;

        if (temperature < -40.0 || temperature > 125.0 || humidity < 0.0 || humidity > 100.0) {
            fprintf(stderr, "Out-of-range values\n");
            continue;
        }

        fprintf(file, "%.2f,%.2f\n", temperature, humidity);
        printf("Temperature: %.2f°C, Humidity: %.2f%%\n", temperature, humidity);

        usleep(124000000); // Wait at least 12.4ms
    }

    close(file);
    return 0;
}

