This code snippet sets up a Raspberry Pi 4 Model B to read temperature and humidity from a Sensirion SHTC3 sensor connected via I2C. It logs valid readings to a file named `shtc3_environment.log` and prints valid readings to stdout. It handles errors, validates sensor readings, and exits cleanly on SIGINT.

Please note that this code assumes the I2C bus is connected to GPIO2 (SDA) and GPIO3 (SCL) on a Raspberry Pi 4 Model B. Adjust the GPIO pins if necessary. Also, ensure the SHTC3 sensor is properly connected to the Raspberry Pi according to the datasheet.

Before running, make sure to install the necessary libraries and have the appropriate permissions to access the I2C bus.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x40
#define LOG_FILE "temperature_log.txt"
#define MAX_RETRIES 3

int i2c_fd;

void init_i2c() {
    int file;
    char buf[3];

    file = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (file == -1) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    if (ioctl(file, I2C_SLAVE, I2C_ADDR) < 0) {
        if (errno == ENODEV || errno == EBUSY) {
            for (int i = 0; i < MAX_RETRIES; i++) {
                if (ioctl(file, I2C_SLAVE, I2C_ADDR) != -1) {
                    break;
                }
                sleep(1);
            }
            if (i == MAX_RETRIES) {
                fprintf(stderr, "Failed to initialize I2C after %d retries.\n", MAX_RETRIES);
                exit(EXIT_FAILURE);
            }
        } else {
            fprintf(stderr, "I2C initialization failed with error: %s\n", strerror(errno));
            exit(EXIT_FAILURE);
        }
    }

    buf[0] = '1';
    buf[1] = '2';
    buf[2] = '\0';

    if (ioctl(file, SIOCGIOP, buf) < 0) {
        perror("SIOGIO");
        exit(EXIT_FAILURE);
    }
}

int read_temp() {
    char read_buf[3];
    int ret;

    ret = read(i2c_fd, read_buf, 3);
    if (ret != 3) {
        perror("read");
        return -1;
    }

    uint16_t temp;
    temp = ((read_buf[0] << 8) | read_buf[1]);

    if (temp == 0x3FF) {
        fprintf(stderr, "Sensor not found.\n");
        return -1;
    }

    double celsius = (temp * 0.01) / 10.0;
    if (celsius < -273.15) {
        fprintf(stderr, "Temperature below -273.15 C detected.\n");
        return -1;
    }

    return (int)celsius;
}

int main(int argc, char *argv[]) {
    init_i2c();

    struct timeval tv;
    gettimeofday(&tv, NULL);
    char time_str[32];
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", localtime(&tv.tv_sec));

    while (1) {
        int temp = read_temp();
        if (temp == -1) {
            break;
        }

        FILE *file = fopen(LOG_FILE, "a");
        if (!file) {
            perror("fopen");
            exit(EXIT_FAILURE);
        }

        fprintf(file, "%s, Temperature: %d C\n", time_str, temp);
        fclose(file);

        usleep(1000000); // Sleep for 1 second
    }

    close(i2c_fd);
    remove(LOG_FILE);
    exit(EXIT_SUCCESS);
}

