            fprintf(stderr, "I2C initialization failed with error: %s\n", strerror(errno));
            exit(EXIT_FAILURE);
        }
    }

    buf[0] = '1';
    buf[1] = '2';
    buf[2] = '\0';

    if (ioctl(file, SIOCGIOP, buf) < 0) {
        perror("SIOGIO");
        exit(EXIT_FAILURE);
    }
}

int read_temp() {
    char read_buf[3];
    int ret;

    ret = read(i2c_fd, read_buf, 3);
    if (ret != 3) {
        perror("read");
        return -1;
    }

    uint16_t temp;
    temp = ((read_buf[0] << 8) | read_buf[1]);

    if (temp == 0x3FF) {
        fprintf(stderr, "Sensor not found.\n");
        return -1;
    }

    double celsius = (temp * 0.01) / 10.0;
    if (celsius < -273.15) {
        fprintf(stderr, "Temperature below -273.15 C detected.\n");
        return -1;
    }

    return (int)celsius;
}

int main(int argc, char *argv[]) {
    init_i2c();

    struct timeval tv;
    gettimeofday(&tv, NULL);
    char time_str[32];
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", localtime(&tv.tv_sec));

    while (1) {
        int temp = read_temp();
        if (temp == -1) {
            break;
        }

        FILE *file = fopen(LOG_FILE, "a");
        if (!file) {
            perror("fopen");
            exit(EXIT_FAILURE);
        }

        fprintf(file, "%s, Temperature: %d C\n", time_str, temp);
        fclose(file);

        usleep(1000000); // Sleep for 1 second
    }

    close(i2c_fd);
    remove(LOG_FILE);
    exit(EXIT_SUCCESS);
}
```

