#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x1A
#define LOG_FILE "flow_log.txt"
#define SAMPLE_INTERVAL 1000

#define READ_SIZE 4
#define STALE_COUNT 2

void log_measurement(long timestamp, int slpm, float celsius) {
    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        perror("Failed to open file for appending");
        return;
    }
    fprintf(file, "%ld,%.1f,%.1f\n", timestamp, slpm, celsius);
    fclose(file);
}

int main() {
    int i2c_fd;
    int ret;
    long timestamp;
    int slpm, celsius;
    int stale_count = 0;

    pigpio_init(I2C_BUS);

    while (1) {
        timestamp = microsecond();

        ret = i2c_read_block_device(i2c_fd, I2C_ADDR, 0x00, READ_SIZE, (uint8_t *)&slpm);
        if (ret < 0) {
            fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
            stale_count++;
            if (stale_count >= STALE_COUNT) {
                stale_count = 0;
                continue;
            }
        }

        ret = i2c_read_block_device(i2c_fd, I2C_ADDR, 0x01, READ_SIZE, (uint8_t *)&celsius);
        if (ret < 0) {
            fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
            stale_count++;
            if (stale_count >= STALE_COUNT) {
                stale_count = 0;
                continue;
            }
        }

        if (ret != READ_SIZE) {
            fprintf(stderr, "I2C read returned unexpected number of bytes: %d\n", ret);
            stale_count++;
            if (stale_count >= STALE_COUNT) {
                stale_count = 0;
                continue;
            }
        }

        if (ret == 0) {
            fprintf(stderr, "Sensor not found, retrying...\n");
            ret = i2c_open(i2c_fd, I2C_BUS, I2C_ADDR);
            if (ret < 0) {
                fprintf(stderr, "Failed to re-open I2C handle: %s\n", strerror(errno));
                continue;
            }
        }

        log_measurement(timestamp, slpm, celsius);

        usleep(SAMPLE_INTERVAL * 1000000);
    }

    pigpio_terminate(1000);
    fclose(stdout);
    return 0;
}

