#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/stat.h>
#include <time.h>
#include <libgpiod.h>

#define DHT11_PIN 7
#define START_LOW_TIME_MS 18000
#define RESPONSE_LOW_TIME_US 80
#define DATA_LOW_TIME_US 50
#define DATA_HIGH_TIME_US 26
#define CHECKSUM_TIME_US 10
#define CHECKSUM_LENGTH 4
#define DHT11_READING_SIZE 12
#define READING_INTERVAL_S 2.0

#define LOG_FILE "dht11_readings.txt"

static int dht11_gpio_fd;
static gpiod_dt_output_t dht11_gpio_out;

static int dht11_read_data(void) {
    uint32_t start_time = get_current_time();

    // Generate start signal
    gpio_output_set(dht11_gpio_fd, 0);
    sleep_ms(START_LOW_TIME_MS / 1000.0);
    gpio_output_set(dht11_gpio_fd, 1);

    // Wait for response
    sleep_ms(RESPONSE_LOW_TIME_US / 1000.0);
    gpio_output_set(dht11_gpio_fd, 0);
    sleep_ms(CHECKSUM_TIME_US / 1000.0);

    // Read data
    uint8_t data[DHT11_READING_SIZE];
    for (int i = 0; i < DHT11_READING_SIZE; i++) {
        sleep_ms(DATA_LOW_TIME_US / 1000.0);
        gpio_output_set(dht11_gpio_fd, 0);
        sleep_ms(DATA_HIGH_TIME_US / 1000.0);
        gpio_output_set(dht11_gpio_fd, 1);
        data[i] = gpio_read(dht11_gpio_fd);
    }

    // Check checksum
    uint32_t checksum = 0;
    for (int i = 0; i < DHT11_READING_SIZE; i++) {
        checksum += data[i];
    }
    if (checksum != 0) {
        return -1; // Checksum failed
    }

    // Decode data
    uint16_t humidity = (data[0] << 8) | data[1];
    uint16_t temperature = data[2];

    // Log reading
    time_t now = time(NULL);
    char timestamp[80];
    sprintf(timestamp, "%04d-%02d-%02d %02d:%02d:%02d",
            now / 3600000, now % 3600000 / 3600, now % 3600 / 60,
            now % 60, 0, 0);
    char log_entry[128];
    sprintf(log_entry, "{%s,%d,%d}", timestamp, humidity, temperature);
    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        fprintf(stderr, "Error opening file: %s\n", strerror(errno));
        return -1;
    }
    fprintf(file, "%s\n", log_entry);
    fclose(file);

    return 0;
}

static void cleanup(void) {
    if (dht11_gpio_fd >= 0) {
        gpio_output_disable(dht11_gpio_fd);
        close(dht11_gpio_fd);
        dht11_gpio_fd = -1;
    }
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <interval_seconds>\n", argv[0]);
        return EXIT_FAILURE;
    }

    int interval_s = atoi(argv[1]);
    if (interval_s < 1) {
        fprintf(stderr, "Interval must be at least 1 second\n");
        return EXIT_FAILURE;
    }

    dht11_gpio_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (dht11_gpio_fd < 0) {
        perror("Error opening log file");
        return EXIT_FAILURE;
    }

    // Configure GPIO
    gpiod_dt_config_t config = GPIOD_DT_CONFIG_DEFAULT();
    gpiod_dt_output_init(&config, dht11_gpio_fd, 0);
    gpiod_dt_output_set_drive_strength(&config, GPIOD_DT_DRIVE_STRENGTH_1M);
    if (gpiod_dt_configure(&config) != 0) {
        perror("Failed to configure GPIO");
        return EXIT_FAILURE;
    }

    gpiod_dt_output_t dht11_gpio_out;
    if (gpiod_dt_output_get(dht11_gpio_fd, &dht11_gpio_out) != 0) {
        perror("Failed to get GPIO output");
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        int result = dht11_read_data();
        if (result == -1) {
            fprintf(stderr, "DHT11 timeout\n");
            // Log timeout
        } else {
            // Log successful reading
        }
        usleep(interval_s * 1000000); // Sleep for interval seconds
    }

    cleanup();
    return EXIT_SUCCESS;
}

