#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define SDA_PIN 2
#define SCL_PIN 3
#define I2C_BUS 1
#define LOG_FILE "sht31d_data.log"
#define TEMP_BYTES 2
#define HUM_BYTES 2
#define CRC_BYTES 2
#define MAX_RETRIES 3

#define CRC8_POLYNOMIAL 0x07
#define CRC8_INIT 0x00

void log_data(const char *timestamp, float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *timeinfo = localtime(&now);
    char time_str[80];
    sprintf(time_str, "%04d-%02d-%02d %02d:%02d:%02d",
            timeinfo->tm_year + 1900, timeinfo->tm_mon + 1, timeinfo->tm_day,
            timeinfo->tm_hour, timeinfo->tm_min, timeinfo->tm_sec);
    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return;
    }
    fprintf(file, "%s,%f,%f\n", time_str, temperature, humidity);
    fclose(file);
}

int read_sht31d(uint8_t *data) {
    int ret = 0;
    int i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    struct i2c_rdwr_ctx ctx;
    ctx.addr = 0x40; // SHT31-D I2C address
    ctx.flags = I2C_M_READ | I2C_M_RANK_1;
    ctx.buf = data;
    ctx.len = TEMP_BYTES + HUM_BYTES + CRC_BYTES;

    while (ret < MAX_RETRIES) {
        ret = i2c_rdwr(i2c_fd, &ctx, 1);
        if (ret < 0) {
            perror("I2C read failed");
            if (errno == EIO || errno == EBUSY) {
                usleep(15000); // Wait for 15ms
                continue;
            } else {
                fprintf(stderr, "I2C read failed after retries: %s\n", strerror(errno));
                return -1;
            }
        }
        break;
    }

    if (ret < 0) {
        fprintf(stderr, "I2C read failed after retries: %s\n", strerror(errno));
        return -1;
    }

    // Validate CRC8
    uint8_t crc = 0;
    for (int j = 0; j < CRC_BYTES; j++) {
        crc = (crc << 8) ^ data[j];
    }
    if (crc != 0xFF) {
        fprintf(stderr, "CRC validation failed\n");
        return -1;
    }

    return 1;
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <temperature_file>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    FILE *log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    pigpio_init(1); // Initialize pigpio with 1 as the number of available pins

    while (1) {
        uint8_t temp_data[TEMP_BYTES], hum_data[HUM_BYTES], crc_data[CRC_BYTES];
        if (read_sht31d(temp_data) && read_sht31d(hum_data) && read_sht31d(crc_data)) {
            float temperature = *(float *)temp_data;
            float humidity = *(float *)hum_data;
            log_data(
                strftime("%Y-%m-%d %H:%M:%S", NULL),
                temperature, humidity
            );
        }

        usleep(5000000); // Wait for 5 seconds
    }

    pigpio_terminate(1); // Terminate pigpio
    fclose(log_file);
    return 0;
}

