#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x5A
#define LOG_FILE "pressure_log.txt"

#define READ_INTERVAL_SEC 2.0

typedef struct {
    long long timestamp;
    float pressure;
    float temperature;
} LogEntry;

static int i2c_fd;
static LogEntry *log_entries = NULL;
static int log_entries_count = 0;

void init_i2c() {
    i2c_fd = open(LOG_FILE, O_WRONLY | O_CREAT, 0644);
    if (i2c_fd == -1) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    log_entries = (LogEntry *)malloc(sizeof(LogEntry) * 1000);
    if (log_entries == NULL) {
        perror("Failed to allocate memory for log entries");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    log_entries_count = 0;
}

void cleanup_i2c() {
    free(log_entries);
    close(i2c_fd);
}

void log_entry(const LogEntry *entry) {
    if (log_entries_count >= 1000) {
        // Rotate log file if it's full
        close(i2c_fd);
        unlink(LOG_FILE);
        i2c_fd = open(LOG_FILE, O_WRONLY | O_CREAT, 0644);
        if (i2c_fd == -1) {
            perror("Failed to open log file");
            exit(EXIT_FAILURE);
        }

        log_entries = (LogEntry *)realloc(log_entries, sizeof(LogEntry) * 1000);
        if (log_entries == NULL) {
            perror("Failed to resize log entries array");
            close(i2c_fd);
            exit(EXIT_FAILURE);
        }

        log_entries_count = 0;
    }

    if (write(i2c_fd, &entry->timestamp, sizeof(long long)) != sizeof(long long)) {
        perror("Failed to write to log file");
        exit(EXIT_FAILURE);
    }

    if (write(i2c_fd, &entry->pressure, sizeof(float)) != sizeof(float)) {
        perror("Failed to write to log file");
        exit(EXIT_FAILURE);
    }

    if (write(i2c_fd, &entry->temperature, sizeof(float)) != sizeof(float)) {
        perror("Failed to write to log file");
        exit(EXIT_FAILURE);
    }

    log_entries_count++;
}

void read_sensor_data() {
    struct mlx90824_data_t data;
    int read_bytes;

    if (pigpio_begin_i2c(i2c_fd, I2C_BUS) < 0) {
        perror("Failed to initialize I2C");
        return;
    }

    if (pigpio_mlx90824_read_data(i2c_fd, I2C_ADDRESS, &data, sizeof(data)) < 0) {
        if (errno == EIO) {
            fprintf(stderr, "Sensor not present or I2C error\n");
            log_entry({.timestamp = get_timestamp(), .pressure = -1.0, .temperature = -1.0});
        } else {
            fprintf(stderr, "Failed to read from sensor\n");
            log_entry({.timestamp = get_timestamp(), .pressure = -1.0, .temperature = -1.0});
        }
        return;
    }

    float pressure = data.pressure;
    float temperature = data.temperature;

    if (log_entries_count >= 1000) {
        // Rotate log file if it's full
        close(i2c_fd);
        unlink(LOG_FILE);
        i2c_fd = open(LOG_FILE, O_WRONLY | O_CREAT, 0644);
        if (i2c_fd == -1) {
            perror("Failed to open log file");
            exit(EXIT_FAILURE);
        }

        log_entries = (LogEntry *)realloc(log_entries, sizeof(LogEntry) * 1000);
        if (log_entries == NULL) {
            perror("Failed to resize log entries array");
            close(i2c_fd);
            exit(EXIT_FAILURE);
        }

        log_entries_count = 0;
    }

    LogEntry entry = {get_timestamp(), pressure, temperature};
    log_entry(&entry);
}

void get_timestamp(long long *timestamp) {
    *timestamp = clock64();
}

int main() {
    init_i2c();

    while (1) {
        read_sensor_data();
        usleep(READ_INTERVAL_SEC * 1000000);
    }

    cleanup_i2c();
    return 0;
}

