#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define BUFFER_SIZE 60
#define FAN_GPIO 18
#define LM75B_ADDRESS 0x40

typedef struct {
    long int timestamp;
    float temperature;
} DataPoint;

DataPoint buffer[BUFFER_SIZE];
int buffer_index = 0;

int i2c_fd;

void init_i2c() {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open i2c bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, LM75B_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

float read_temperature() {
    long int reg_address = 0x00;
    unsigned char data[2];

    if (read(i2c_fd, &reg_address, 1) != 1) {
        perror("Failed to read register address");
        return -1.0;
    }

    if (read(i2c_fd, data, 2) != 2) {
        perror("Failed to read temperature data");
        return -1.0;
    }

    return ((data[0] << 8) | data[1]) / 10.0;
}

void write_fan_gpio(int state) {
    if (pigpio_write_i2c_data(i2c_fd, FAN_GPIO, state) < 0) {
        perror("Failed to write to fan GPIO");
    }
}

void log_error(const char *msg) {
    fprintf(stderr, "Error: %s\n", msg);
}

int main(int argc, char *argv[]) {
    pigpio_init(5);

    init_i2c();

    while (1) {
        float avg_temp = 0.0;
        int num_samples = 0;

        for (int i = 0; i < BUFFER_SIZE; i++) {
            if (buffer_index < BUFFER_SIZE) {
                avg_temp += buffer[buffer_index].temperature;
                buffer_index++;
                num_samples++;
            } else {
                break;
            }
        }

        avg_temp /= num_samples;

        if (avg_temp > 28.0) {
            write_fan_gpio(1);
        } else if (avg_temp < 26.0) {
            write_fan_gpio(0);
        }

        log_error(NULL);
        usleep(1000000); // Sleep for 1 second
    }

    pigpio_cleanup();
    close(i2c_fd);
    return 0;
}

