        close(log_fd);
        exit(EXIT_FAILURE);
    }

    client = i2c_client_new(i2c_fd, SENSOR_ADDRESS);
    if (!client) {
        perror("Failed to create I2C client");
        close(log_fd);
        exit(EXIT_FAILURE);
    }

    while (1) {
        // Delay after the first command
        usleep(DELAY_AFTER_COMMAND);

        // Read from the sensor
        if (i2c_transfer(client, SDP810_READ_PRESSURE, BUFFER_SIZE, buffer) < 0) {
            fprintf(stderr, "I2C read failed\n");
            continue;
        }

        // Validate CRC
        unsigned int crc = 0;
        for (int i = 0; i < BUFFER_SIZE; i++) {
            crc ^= buffer[i];
            for (int j = 0; j < 8; j++) {
                crc <<= 1;
                if (crc & 0x80) crc = crc >> 1;
            }
        }
        if (crc != 0x07) {
            fprintf(stderr, "CRC mismatch, invalid data\n");
            continue;
        }

        // Convert bytes to pressure and temperature
        pressure = (float)buffer[0] * 0.0001 + (float)buffer[1] * 0.000001;
        temperature = (float)buffer[2] * 0.01;

        // Log the reading
        time_t current_time = time(NULL);
        log_reading(current_time - last_timestamp, pressure, temperature);
        last_timestamp = current_time;

        // Print warning if pressure exceeds 5.0 Pa
        if (pressure > 5.0) {
            fprintf(stderr, "Warning: Pressure exceeds 5.0 Pa\n");
        }

        // Sleep for the sample interval
        usleep(SAMPLE_INTERVAL);
    }

    // Clean up
    i2c_client_free(client);
    close(i2c_fd);
