#include <sys/stat.h>
#include <sys/wait.h>
#include <signal.h>
#include <sys/epoll.h>

#define I2C_BUS 1
#define I2C_ADDR 0x40
#define LED_PIN 17

#define TEMP_THRESHOLD_HIGH 28.0
#define TEMP_THRESHOLD_LOW 27.0

int i2c_fd;
int led_fd;

struct i2c_client *i2c_client;

double read_temperature() {
    char command[3];
    sprintf(command, "t%d", I2C_ADDR);
    return *(double *)ioctl(i2c_fd, I2C_READ, command);
}

void setup_led() {
    int mode = fctl(led_fd, LED_MODE);
    if (mode < 0) {
        perror("Failed to set LED mode");
        exit(EXIT_FAILURE);
    }
}

void toggle_led(int state) {
    int result = fctl(led_fd, state ? LED_ON : LED_OFF);
    if (result < 0) {
        perror("Failed to set LED state");
        exit(EXIT_FAILURE);
    }
}

void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Exiting...\n");
        close(i2c_fd);
        close(led_fd);
        fctl(led_fd, LED_OFF);
        exit(0);
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    i2c_fd = open("/dev/i2c-1", O_RDWR | O_NOCTTY);
    if (i2c_fd == -1) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    i2c_client = i2c_alloc(i2c_fd);
    if (!i2c_client) {
        perror("Failed to allocate I2C client");
        exit(EXIT_FAILURE);
    }

    setup_led();

    while (1) {
        double temp = read_temperature();
        if (temp < TEMP_THRESHOLD_LOW) {
            printf("Temperature: %f°C, Turning LED off\n", temp);
            toggle_led(0);
        } else if (temp > TEMP_THRESHOLD_HIGH) {
            printf("Temperature: %f°C, Turning LED on\n", temp);
            toggle_led(1);
        } else {
            printf("Temperature: %f°C\n", temp);
        }
        usleep(1000000); // Sleep for 1 second
    }

    i2c_free(i2c_client);
    close(i2c_fd);
    close(led_fd);

    return 0;
}

