#include <errno.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/epoll.h>
#include <sys/select.h>
#include <time.h>
#include <libgpiod.h>

#define I2C_BUS 1
#define I2C_ADDR 0x40
#define LOG_FILE "environment.log"
#define MAX_RETRIES 3
#define LOG_INTERVAL 60000 // 60 seconds in milliseconds

#define SI7021_NO_HOLD 0x30
#define SI7021_TEMP_CMD 0x01
#define SI7021_RH_CMD 0x02
#define SI70021_READ_TEMP_RH 0x00
#define SI7021_READ_TEMP_NO_RH 0x02

#define SI7021_ID_REG 0x00
#define SI7021_REV_REG 0x01

#define LOG_ENTRY "%s,%.1f,%.1f\n"

int i2c_fd;

int check_sensor_presence() {
    uint8_t id_reg_value;
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0 ||
        read(i2c_fd, &id_reg_value, 1) != 1 ||
        id_reg_value != 0x43) { // Assuming ID is 0x43 for Adafruit Si7021
        return 1;
    }
    return 0;
}

int read_si7021_data(uint8_t *temp, uint8_t *humidity) {
    uint8_t cmd = SI7021_TEMP_CMD;
    for (int retries = 0; retries < MAX_RETRIES; retries++) {
        if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0 ||
            write(i2c_fd, &cmd, 1) != 1 ||
            read(i2c_fd, temp, 2) != 2) {
            return -1;
        }
        break;
    }

    cmd = SI7021_RH_CMD;
    for (int retries = 0; retries < MAX_RETRIES; retries++) {
        if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0 ||
            write(i2c_fd, &cmd, 1) != 1 ||
            read(i2c_fd, humidity, 2) != 2) {
            return -1;
        }
        break;
    }

    return 0;
}

int main() {
    int ret;
    struct timeval tv;
    struct timespec ts;

    if (check_sensor_presence() == 1) {
        printf("Adafruit Si7021 sensor detected.\n");
    } else {
        printf("Adafruit Si7021 sensor not detected. Exiting.\n");
