#include <sys/wait.h>
#include <time.h>
#include <tglib/tglib.h>

#define I2C_BUS 1
#define I2C_ADDR 0x40
#define LOG_FILE "enviro_log.txt"
#define LOG_INTERVAL 5000 // 5 seconds in milliseconds
#define WAIT_TIME 20000 // 20 milliseconds

typedef struct {
    int file;
    int i2c_fd;
    struct i2c_client *client;
} HDC1080_context;

static int i2c_open(HDC1080_context *ctx) {
    ctx->i2c_fd = open(ctx->file, O_RDWR);
    if (ctx->i2c_fd < 0) {
        perror("open");
        return -1;
    }
    ctx->client = i2c_alloc_client(ctx->i2c_fd, I2C_ADDR);
    if (!ctx->client) {
        close(ctx->i2c_fd);
        return -1;
    }
    return 0;
}

static int i2c_close(HDC1080_context *ctx) {
    i2c_free_client(ctx->client);
    close(ctx->i2c_fd);
    return 0;
}

static int read_hdc1080(HDC1080_context *ctx, uint8_t *data) {
    return i2c_transfer(ctx->client, 0x00, 0x01, data, 6);
}

static int get_temperature(HDC1080_context *ctx, float *temp) {
    uint8_t data[6];
    if (read_hdc1080(ctx, data) < 0) {
        return -1;
    }
    *temp = (data[0] << 8) | data[1];
    return 0;
}

static int get_humidity(HDC1080_context *ctx, float *hum) {
    uint8_t data[6];
    if (read_hdc1080(ctx, data) < 0) {
        return -1;
    }
    *hum = (data[2] << 8) | data[3];
    return 0;
}

static void log_entry(HDC1080_context *ctx, const char *timestamp, float temp, float hum) {
    time_t now = time(NULL);
    struct tm *local_time = localtime(&now);
    char time_str[80];
    sprintf(time_str, "%04d-%02d-%02d %02d:%02d:%02d",
            local_time->tm_year + 1900, local_time->tm_mon + 1, local_time->tm_mday,
            local_time->tm_hour, local_time->tm_min, local_time->tm_sec);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen");
        return;
    }
    fprintf(log_file, "%s, %f, %f\n", time_str, temp, hum);
    fclose(log_file);
}

int main(int argc, char *argv[]) {
    HDC1080_context ctx;
    ctx.file = open("/dev/i2c-1", O_RDWR);
    if (ctx.file < 0) {
        perror("open /dev/i2c-1");
        return 1;
    }

    if (i2c_open(&ctx) < 0) {
        i2c_close(&ctx);
        return 1;
    }

    while (1) {
        float temp, hum;
        if (get_temperature(&ctx, &temp) < 0) {
            printf("Failed to read temperature\n");
            continue;
        }
        if (get_humidity(&ctx, &hum) < 0) {
            printf("Failed to read humidity\n");
            continue;
        }

        log_entry(&ctx, " ", temp, hum);

        usleep(WAIT_TIME);
    }

    i2c_close(&ctx);
    return 0;
}

