#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x40
#define LOG_FILE "temperature_log.txt"
#define SAMPLE_INTERVAL 5000 // 5 seconds in milliseconds
#define CRC_POLYNOMIAL 0x07

// Function to verify CRC8
unsigned char crc8_check(unsigned char crc, unsigned char data[3]) {
    unsigned char i, result = 0;
    for (i = 0; i < 3; i++) {
        result ^= data[i];
        for (i = 0; i < 8; i++) {
            if ((result & 0x01)) {
                result = result >> 1;
            } else {
                result = result << 1;
            }
        }
    }
    return (crc ^ result);
}

int main() {
    int fd, ret;
    struct i2c_client *client;
    unsigned char data[3];
    time_t now;
    struct tm *timeinfo;
    char log_msg[100];

    // Initialize the I2C bus
    fd = open(LOG_FILE, O_WRONLY | O_CREAT, 0644);
    if (fd == -1) {
        perror("Error opening log file");
        exit(EXIT_FAILURE);
    }

    client = i2c_alloc(fd, I2C_BUS);
    if (!client) {
        perror("Failed to allocate I2C client");
        close(fd);
        exit(EXIT_FAILURE);
    }

    ret = ioctl(fd, I2C_SLAVE, I2C_ADDR);
    if (ret < 0) {
        perror("Failed to set I2C slave address");
        i2c_free(client);
        close(fd);
        exit(EXIT_FAILURE);
    }

    while (1) {
        // Read from the sensor
        ret = read(client->fd, data, 3);
        if (ret != 3) {
            fprintf(stderr, "Failed to read from I2C device\n");
            i2c_free(client);
            close(fd);
            exit(EXIT_FAILURE);
        }

        // Verify CRC
        unsigned char calculated_crc = crc8_check(0, data);
        if (calculated_crc != 0x00) {
            fprintf(stderr, "CRC mismatch, sensor data may be corrupted\n");
            i2c_free(client);
            close(fd);
            exit(EXIT_FAILURE);
        }

        // Get current time
        now = time(NULL);
        timeinfo = localtime(&now);
        strftime(log_msg, sizeof(log_msg), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

        // Write to the log file
        if (write(fd, log_msg, strlen(log_msg)) != (size_t)strlen(log_msg)) {
            perror("Failed to write to log file");
            i2c_free(client);
            close(fd);
            exit(EXIT_FAILURE);
        }

        // Sample and log temperature
        double temperature = (data[0] << 8) | data[1];
        fprintf(fd, "%s: %f\n", log_msg, temperature);

        // Wait for the next sample
        usleep(SAMPLE_INTERVAL / 1000);
    }

    // Clean up
    i2c_free(client);
    close(fd);

    return 0;
}

