#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define SENSOR_ADDRESS 0x4B
#define LOG_FILE "hvac_pressure_log.txt"
#define SAMPLE_INTERVAL_MS 1000

#define CRC_POLYNOMIAL 0x07
#define CRC_INIT_VALUE 0x00

void write_i2c_byte(int file, uint8_t data) {
    if (write(file, &data, 1) != 1) {
        perror("write_i2c_byte");
        exit(EXIT_FAILURE);
    }
}

uint8_t read_i2c_byte(int file) {
    uint8_t data;
    if (read(file, &data, 1) != 1) {
        perror("read_i2c_byte");
        exit(EXIT_FAILURE);
    }
    return data;
}

int validate_crc8(uint8_t crc, uint8_t data[9]) {
    uint8_t calculated_crc = 0;
    for (int i = 0; i < 9; i++) {
        calculated_crc = (calculated_crc << 1) ^ data[i];
    }
    return calculated_crc == crc;
}

void log_sample(const char *timestamp, uint16_t pressure, float temperature, float scale_factor) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file\n");
        exit(EXIT_FAILURE);
    }
    fprintf(log_file, "%s,%f,%f,%f\n", timestamp, pressure, temperature, scale_factor);
    fclose(log_file);
}

int main() {
    int i2c_fd;
    pigpio_init(5);

    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("open /dev/i2c-1");
        pigpio_cleanup();
        exit(EXIT_FAILURE);
    }

    if (set_i2c_address(i2c_fd, SENSOR_ADDRESS) < 0) {
        perror("set_i2c_address");
        close(i2c_fd);
        pigpio_cleanup();
        exit(EXIT_FAILURE);
    }

    if (start_i2c_transactions(i2c_fd) < 0) {
        perror("start_i2c_transactions");
        close(i2c_fd);
        pigpio_cleanup();
        exit(EXIT_FAILURE);
    }

    while (1) {
        uint8_t data[9];
        if (read_i2c_byte(i2c_fd) == 0x00) {
            fprintf(stderr, "I2C read failed\n");
            break;
        }

        data[0] = read_i2c_byte(i2c_fd);
        data[1] = read_i2c_byte(i2c_fd);
        data[2] = read_i2c_byte(i2c_fd);
        data[3] = read_i2c_byte(i2c_fd);
        data[4] = read_i2c_byte(i2c_fd);
        data[5] = read_i2c_byte(i2c_fd);
        data[6] = read_i2c_byte(i2c_fd);
        data[7] = read_i2c_byte(i2c_fd);
        data[8] = read_i2c_byte(i2c_fd);

        if (!validate_crc8(data[8], data)) {
            fprintf(stderr, "CRC validation failed\n");
            break;
        }

        uint16_t pressure = (data[0] << 8) | data[1];
        float temperature = (float)data[2] / 10.0;
        float scale_factor = data[8] / 100.0;

        log_sample(get_timestamp(), pressure, temperature, scale_factor);

        usleep(SAMPLE_INTERVAL_MS / 1000);
    }

    close(i2c_fd);
    pigpio_cleanup();

    return 0;
}

int set_i2c_address(int fd, uint8_t address) {
    uint8_t command[2];
    command[0] = 0x20;
    command[1] = address;
