#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <pthread.h>
#include <libgpiod/gpio.h>
#include <i2c-dev.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <time.h>
#include <errno.h>
#include <stdbool.h>

#define BUFFER_SIZE 100
#define CSV_FILE "/var/log/scd40_data/scd40_data.csv"
#define ERROR_LOG "/var/log/scd40_error.log"
#define PERIODIC_INTERVAL_SEC 5.0
#define START_MEASUREMENT_COMMAND 0x43
#define CRC_POLYNOMIAL 0x07

typedef struct {
    time_t timestamp;
    float co2;
    float temperature;
    float humidity;
} DataPoint;

typedef struct {
    DataPoint data[BUFFER_SIZE];
    int head;
    int tail;
} CircularBuffer;

CircularBuffer buffer;
volatile sig_atomic_t stop_flag = 0;
pthread_t logging_thread;

void i2c_init() {
    int file = open("/dev/i2c-1", O_RDWR);
    if (file < 0) {
        perror("i2c-1 open failed");
        exit(EXIT_FAILURE);
    }

    if (ioctl(file, I2C_SLAVE, 0x18) < 0) {
        perror("i2c-1 set slave address failed");
        close(file);
        exit(EXIT_FAILURE);
    }
}

void i2c_write(uint8_t cmd) {
    write(open("/dev/i2c-1", O_WRONLY), &cmd, 1);
}

void i2c_read(uint8_t *readbuf, int len) {
    read(open("/dev/i2c-1", O_RDONLY), readbuf, len);
}

void start_measurement() {
    i2c_write(START_MEASUREMENT_COMMAND);
}

void read_sensor_data() {
    uint8_t cmd[1];
    cmd[0] = 0x00; // Read CRC8
    i2c_write(cmd[0]);

    uint8_t crc8[1];
    i2c_read(crc8, 1);

    // Validate CRC8
    if (crc8[0] != 0x07) {
        fprintf(ERROR_LOG, "CRC8 validation failed, skipping reading\n");
        return;
    }

    // Read CO2, Temperature, Humidity
    cmd[0] = 0x01; // Read CO2
    i2c_write(cmd[0]);
    i2c_read(&cmd[1], 1);
    buffer.co2 = (float)cmd[1] / 1000.0;

    cmd[0] = 0x02; // Read Temperature
    i2c_write(cmd[0]);
    i2c_read(&cmd[1], 2);
    buffer.temperature = (float)(cmd[1] << 8) / 100.0 + (float)cmd[2] / 1000.0;

    cmd[0] = 0x03; // Read Humidity
    i2c_write(cmd[0]);
    i2c_read(&cmd[1], 2);
    buffer.humidity = (float)(cmd[1] << 8) / 100.0 + (float)cmd[2] / 1000.0;

    // Buffer data
    if (buffer.head == BUFFER_SIZE - 1) {
        buffer.tail = 0;
    } else {
        buffer.tail++;
    }
    buffer.data[buffer.head] = (DataPoint){buffer.timestamp, buffer.co2, buffer.temperature, buffer.humidity};
    buffer.head++;
}

void *logging_thread_func(void *arg) {
    while (!stop_flag) {
        // Wait for 60 seconds
        sleep(60);

        // Write to CSV
        FILE *csv_file = fopen(CSV_FILE, "a");
        if (!csv_file) {
            fprintf(ERROR_LOG, "Failed to open CSV file for writing\n");
            continue;
        }

        // Write header if it's the first record
        if (fseek(csv_file, 0, SEEK_END) == 0) {
            long file_size = ftell(csv_file);
            rewind(csv_file);

            if (file_size == 0) {
                fprintf(csv_file, "timestamp,co2,temperature,humidity\n");
            }
        }

        // Write current record
        fprintf(csv_file, "%ld,%f,%f,%f\n", buffer.data[buffer.tail].timestamp, buffer.data[buffer.tail].co2, buffer.data[buffer.tail].temperature, buffer.data[buffer.tail].humidity);
        fclose(csv_file);
    }
    pthread_join(logging_thread, NULL);
}

void handle_sigint() {
    stop_flag = 1;
}

int main() {
    sigset_t mask;
    pthread_t logging_thread;

    sigprocmask(SIG_BLOCK, &mask, 0);

    i2c_init();
    start_measurement();

    pthread_create(&logging_thread, NULL, logging_thread_func, NULL);

    while (!stop_flag) {
        read_sensor_data();
        usleep(1000000); // Wait at least one second after starting measurements
    }

    pthread_join(logging_thread, NULL);
    close(open("/dev/i2c-1", O_WRONLY));
    fclose(stdout);
    fclose(stderr);
    return 0;
}

int handle_sigint(int sig) {
    handle_sigint();
    return 0;
}

int main_handler(int sig) {
    return handle_sigint(sig);
}

int signal(int signum, int (*sigfunc)(int));

int main(int argc, char *argv[]) {
    signal(SIGINT, main_handler);
    return main(argc, argv);
}

