#include <sys/stat.h>
#include <pthread.h>

#define I2C_BUS 1
#define I2C_ADDR 0x4B
#define LOG_FILE "sdp810_log.txt"
#define SAMPLE_INTERVAL 1000000  // 1 second in microseconds
#define CRC_POLYNOMIAL 0x07

typedef struct {
    unsigned char data[9];
} SDP810_DATA;

void write_to_log(const char *timestamp, int pressure_Pa, float temperature_C) {
    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        perror("Failed to open log file");
        return;
    }
    time_t now = time(NULL);
    fprintf(file, "%ld,%f,%f\n", now, pressure_Pa, temperature_C);
    fclose(file);
}

void read_sensor(SDP810_DATA *data) {
    int file;
    file = open(LOG_FILE, O_WRONLY | O_CREAT, S_IRUSR | S_IWUSR);
    if (file == -1) {
        perror("Failed to open log file");
        return;
    }

    while (1) {
        struct i2c_rdwr_ctx ctx;
        int ret = i2c_alloc_device(I2C_BUS, I2C_ADDR);
        if (ret < 0) {
            perror("Failed to allocate I2C device");
            i2c_free(I2C_BUS, I2C_ADDR);
            return;
        }

        ret = i2c_setup(I2C_BUS, I2C_ADDR, 0x4B, 0x00, 0, 0, 9, &ctx);
        if (ret < 0) {
            perror("Failed to prepare I2C transfer");
            i2c_free(I2C_BUS, I2C_ADDR);
            return;
        }

        ret = i2c_mem_read_bw(I2C_BUS, I2C_ADDR, data, 9, &ctx);
        if (ret < 0) {
            perror("Failed to read from I2C device");
            i2c_free(I2C_BUS, I2C_ADDR);
            return;
        }

        if (ret == 9) {
            // CRC validation (simplified for demonstration)
            unsigned int crc = 0;
            for (int i = 0; i < 9; i++) {
                crc ^= data[i];
                for (int j = 0; j < 8; j++) {
                    crc <<= 1;
                    if (crc & 0x8000) {
                        crc = crc >> 1;
                    } else {
                        break;
                    }
                }
            }
            if (crc != 0x07) {
                write_to_log(time(NULL), -1, -1); // Log error
                i2c_free(I2C_BUS, I2C_ADDR);
                return;
            }

            // Process pressure, temperature, and scale factor
            int pressure_Pa = (data[0] << 8) | data[1];
            float temperature_C = (data[3] << 8) / 100.0;
            int scale_factor = (data[5] << 8) | data[6];

            write_to_log(time(NULL), pressure_Pa, temperature_C);
        }

        i2c_free(I2C_BUS, I2C_ADDR);
        usleep(SAMPLE_INTERVAL / 1000000);
    }
}

void sigint_handler(int signum) {
    write_to_log(time(NULL), -1, -1); // Log error
    i2c_free(I2C_BUS, I2C_ADDR);
    close(fildes);
    fclose(stdout);
    exit(signum > 0);
}

