    pthread_t thread;
    sigset_t sigset;
    int sig = 0;

    sigaddset(&sigset, SIGINT);
    sigprocmask(SIG_BLOCK, &sigset, NULL);

    read_sensor(&SDP810_DATA);

    pthread_create(&thread, NULL, sigint_handler, (void *)0);
    pthread_join(thread, NULL);

    return 0;
}

