        perror("Error writing to file");
        return;
    }
    sprintf(buffer, "%d", temperature);
    if (write(fd, buffer, strlen(buffer)) == -1) {
        perror("Error writing to file");
        return;
    }

    printf("Pressure: %d, Temperature: %d\n", pressure, temperature);
}

