#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <errno.h>
#include <signal.h>
#include <wiringPi.h>

#define I2C_BUS 1
#define I2C_ADDR 0x77
#define GPIO_LED 17

#define POLL_INTERVAL_MS 1000
#define LOW_PRESSURE_INTERVAL_MS 500

#define CRC_CHECK_BYTES 3

// Function to handle SIGINT (Ctrl+C)
void sigint_handler(int sig) {
    close(i2c_fd);
    wpiGpioSetMode(GPIO_LED, WPI_GPIO_OUTPUT);
    wpiGpioWrite(GPIO_LED, 0);
    exit(0);
}

// Function to read data from I2C device
int read_i2c_data(int fd, uint8_t *buffer) {
    ssize_t bytes_read = read(fd, buffer, sizeof(buffer) - CRC_CHECK_BYTES);
    if (bytes_read < 0) {
        perror("read_i2c_data: failed to read from I2C device");
        return -1;
    }
    if (bytes_read < sizeof(buffer) - CRC_CHECK_BYTES) {
        return -2; // Sensor absent or bus error
    }
    return 0;
}

// Function to verify CRC
int verify_crc(const uint8_t *data) {
    uint32_t crc = 0;
    for (int i = 0; i < CRC_CHECK_BYTES; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if ((crc & 1) != 0) {
                crc = crc >> 1;
            } else {
                crc = crc >> 1;
                crc ^= 0x07;
            }
        }
    }
    return crc == 0;
}

// Function to process sensor data
void process_sensor_data(const uint8_t *data) {
    uint16_t pressure = (data[0] << 8) | data[1];
    uint16_t temp = (data[2] << 8) | data[3];
    if (verify_crc(data)) {
        // Process data as needed
        printf("Pressure: %d Pa, Temperature: %d Pa\n", pressure, temp);

        // Check for low pressure condition
        if (pressure < 95000) {
            wpiGpioSetMode(GPIO_LED, WPI_GPIO_OUTPUT);
            wpiGpioWrite(GPIO_LED, 1);
            usleep(LOW_PRESSURE_INTERVAL_MS / 2);
            wpiGpioWrite(GPIO_LED, 0);
        }
    }
}

int main() {
    int i2c_fd, gpio_fd;
    wpiConfigGpio(GPIO_LED, WPI_GPIO_OUTPUT);

    // Initialize wiringPi
    if (wiringPiSetup() != 0) {
        fprintf(stderr, "wiringPi setup failed\n");
        exit(1);
    }

    // Initialize I2C
    i2c_fd = open("/dev/i2c-1", O_RDWR | O_NOCTTY);
    if (i2c_fd == -1) {
        perror("open /dev/i2c-1");
        exit(1);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) == -1) {
        perror("ioctl I2C_SLAVE");
        close(i2c_fd);
        exit(1);
    }

    // Set I2C write register and data
    uint8_t reg_write = 0x00;
    uint8_t data_to_read[6];

    // Read sensor data
    if (read_i2c_data(i2c_fd, data_to_read) == 0) {
        process_sensor_data(data_to_read);
    } else if (read_i2c_data(i2c_fd, data_to_read) == -2) {
        // Handle sensor absent or bus error
        printf("Sensor absent or bus error\n");
    }

    // Polling loop
    while (1) {
        usleep(POLL_INTERVAL_MS / 2);
        sigint_handler(SIGINT);
    }

    close(i2c_fd);
    wpiGpioDisable(GPIO_LED);
    return 0;
}

