This code sets up a Raspberry Pi 4 Model B to continuously read data from a TDK ICP-10125 barometric pressure sensor over I2C. It checks for errors during I2C syscalls, handles sensor-absent or bus-error conditions, and verifies the CRC on each sensor read. The program polls the sensor once per second, with a 20ms delay between polls.

The sensor data is processed, and if the measured pressure falls below 95000 Pa, the warning LED connected to GPIO17 (BCM) blinks at a 5Hz pattern (100ms on, 100ms off). Under normal conditions, the LED blinks at 1Hz (500ms on, 500ms off).

A SIGINT handler is installed to safely close the I2C file descriptor and release the GPIO line before exiting the program.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/wait.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x5A
#define FAN_GPIO 18
#define LOG_FILE "temperature_log.txt"
#define TEMP_READ_INTERVAL 2000000  // 2 seconds in microseconds
#define TEMP_ON_THRESHOLD 30
#define TEMP_OFF_THRESHOLD 28
#define MAX_RETRIES 3
#define DELAY_BETWEEN_RETRIES 10000

#define MAX_LOG_SIZE 1024

// Structure to hold temperature data
typedef struct {
    long timestamp;
    float ambient_temp;
    float object_temp;
} TempData;

// Global variables
static int i2c_fd;
static int fan_gpio;
static TempData log_data[MAX_LOG_SIZE];
static int log_data_index = 0;
static pthread_t log_thread;

// Function prototypes
static int i2c_open(void);
static int i2c_close(void);
static int i2c_read(void *buffer, size_t length, int offset);
static int i2c_write(const void *buffer, size_t length, int offset);
static void log_temperature(float temp);
static void control_fan(float temp);
static void* log_thread_func(void* arg);

// Signal handlers
void sigint_handler(int sig) {
    printf("Received SIGINT, shutting down...\n");
    i2c_close();
    control_fan(0);
    kill(getpid(), SIGTERM);
    exit(0);
}

void sigterm_handler(int sig) {
    printf("Received SIGTERM, shutting down...\n");
    i2c_close();
    control_fan(0);
    exit(0);
}

int main(int argc, char *argv[]) {
    if (signal(SIGINT, sigint_handler) == SIG_IGN ||
        signal(SIGTERM, sigterm_handler) == SIG_IGN) {
        perror("Failed to set signal handlers");
        exit(1);
    }

    if (pigpio_init() < 0) {
        perror("Failed to initialize pigpio");
        exit(1);
    }

    if (i2c_open() < 0) {
        perror("Failed to open I2C bus");
        exit(1);
    }

    control_fan(0);

    // Start logging thread
    if (pthread_create(&log_thread, NULL, log_thread_func, NULL) != 0) {
        perror("Failed to create logging thread");
        i2c_close();
        pigpio_terminate();
        exit(1);
    }

    while (1) {
        float ambient_temp, object_temp;

        // Read temperature data
        if (i2c_read(&ambient_temp, sizeof(ambient_temp), 0) < 0) {
            if (errno == EIO || errno == E2BIG) {
                printf("I2C read failed, retrying...\n");
                for (int i = 0; i < MAX_RETRIES; i++) {
                    usleep(DELAY_BETWEEN_RETRIES);
                    if (i2c_read(&ambient_temp, sizeof(ambient_temp), 0) == 0) {
                        break;
                    }
                }
                if (i == MAX_RETRIES) {
                    printf("I2C read failed after retries, skipping logging.\n");
                }
            } else {
                printf("Unexpected error during I2C read: %s\n", strerror(errno));
                exit(1);
            }
        }

        // Read object temperature
        if (i2c_read(&object_temp, sizeof(object_temp), 1) < 0) {
            if (errno == EIO || errno == E2BIG) {
                printf("I2C read failed, retrying...\n");
                for (int i = 0; i < MAX_RETRIES; i++) {
                    usleep(DELAY_BETWEEN_RETRIES);
                    if (i2c_read(&object_temp, sizeof(object_temp), 1) == 0) {
                        break;
                    }
                }
                if (i == MAX_RETRIES) {
                    printf("I2C read failed after retries, skipping logging.\n");
                }
            } else {
                printf("Unexpected error during I2C read: %s\n", strerror(errno));
                exit(1);
            }
        }

        // Log temperature data
        if (log_data_index < MAX_LOG_SIZE) {
            log_data[log_data_index].timestamp = time(NULL);
            log_data[log_data_index].ambient_temp = ambient_temp;
            log_data[log_data_index].object_temp = object_temp;
            log_data_index++;
        }

        // Control fan
        control_fan(object_temp);

        // Sleep before next reading
        usleep(TEMP_READ_INTERVAL / 2);
    }

    // Close I2C bus and pigpio
    i2c_close();
    pigpio_terminate();

    return 0;
}

// I2C operations
static int i2c_open(void) {
    int file = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (file < 0) {
        return errno;
    }
    close(file);

    i2c_fd = open("/dev/i2c-1", O_RDWR | O_NOCTTY);
    if (i2c_fd < 0) {
        return errno;
    }

    return 0;
}

static int i2c_close(void) {
    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
    }

    if (log_data_index > 0) {
        close(fildes(fileno(log_data)));
        log_data_index = 0;
    }

    return 0;
}

static int i2c_read(void *buffer, size_t length, int offset) {
    int ret = read(i2c_fd, buffer, length);
    if (ret < 0) {
        return errno;
    }
    return ret - offset;
}

static int i2c_write(const void *buffer, size_t length, int offset) {
    int ret = write(i2c_fd, buffer, length);
    if (ret < 0) {
        return errno;
    }
    return ret - offset;
}

// Logging function
static void log_temperature(float temp) {
    char timestamp[32];
    time_t now = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        perror("Failed to open log file");
        return;
    }

    fprintf(file, "%s: ambient_temp=%.1f, object_temp=%.1f\n", timestamp, ambient_temp, object_temp);
    fclose(file);
}

// Fan control function
static void control_fan(float temp) {
    static int fan_state = 0;

    if (temp > TEMP_ON_THRESHOLD) {
        if (fan_state == 0) {
            fan_state = 1;
            gpioSetMode(fan_gpio, PI_OUTPUT);
        }
    } else if (temp < TEMP_OFF_THRESHOLD) {
        if (fan_state == 1) {
            fan_state = 0;
            gpioSetMode(fan_gpio, PI_OUTPUT);
        }
    }
}

// Logging thread function
static void* log_thread_func(void* arg) {
    while (1) {
        for (int i = 0; i < log_data_index; i++) {
            log_temperature(log_data[i].object_temp);
        }
        usleep(100000);
    }
    return NULL;
}

