#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <pthread.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>
#include <http.h>

#define I2C_BUS 1
#define SHT40_ADDRESS 0x40
#define TEMP_REG 0x00
#define HUMID_REG 0x01
#define DATA_LEN 6

#define HTTP_SERVER "http://localhost:8080"
#define HTML_FILE "index.html"

void* read_sensor(void* arg) {
    int fd, ret;
    struct i2c_rdwr_cfg cfg;
    char buffer[DATA_LEN];
    int16_t temp, humid;

    fd = open(HTTP_SERVER, O_WRONLY | O_CREAT, 0644);
    if (fd < 0) {
        perror("Failed to open HTTP server");
        return NULL;
    }

    cfg.device = I2C_BUS;
    cfg.address = SHT40_ADDRESS;
    cfg.flags = I2C_M_READ;
    cfg.len = DATA_LEN;
    cfg.buf = buffer;

    while (1) {
        ret = ioctl(fd, I2C_SLAVE, cfg.address);
        if (ret < 0) {
            perror("Failed to set I2C slave address");
            return NULL;
        }

        ret = pigpio_i2c_transfer(fd, &cfg, DATA_LEN, buffer);
        if (ret < 0) {
            perror("Failed to read from sensor");
            return NULL;
        }

        temp = (buffer[0] << 8) | buffer[1];
        humid = (buffer[2] << 8) | buffer[3];

        if (temp < 0 || humid < 0) {
            fprintf(stderr, "Invalid sensor data, retrying...\n");
            sleep(1);
            continue;
        }

        http_send_request(fd, HTTP_SERVER, HTML_FILE, "GET", "Content-Type: text/html\r\n\r\n",
                         "<html><body><h1>Temperature: %d°C</h1><h2>Humidity: %d%%</h2></body></html>");
        http_send_data(fd, buffer, temp, humid);

        sleep(1);
    }

    close(fd);
    return NULL;
}

int main(int argc, char* argv[]) {
    pthread_t sensor_thread;

    if (pthread_create(&sensor_thread, NULL, read_sensor, NULL) != 0) {
        perror("Failed to create sensor thread");
        exit(EXIT_FAILURE);
    }

    // Handle SIGINT and SIGTERM signals
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Keep the main thread alive
    while (1);

    return 0;

signal_handler:
    fprintf(stderr, "Received signal, exiting...\n");
    pthread_join(sensor_thread, NULL);
    exit(EXIT_SUCCESS);
}

