#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <stdint.h>
#include <time.h>
#include <stdlib.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define TMP102_ADDRESS 0x40
#define LOG_FILE "temperature_log.csv"
#define LOG_FORMAT "YYYY-MM-DD HH:MM:SS,XX.XX"
#define LOG_INTERVAL 5000 // 5 seconds in milliseconds

// Function to read temperature from TMP102
int read_temperature(int file_descriptor) {
    char buffer[13];
    int result = read(file_descriptor, buffer, 12);
    if (result == -1) {
        perror("read");
        return -1;
    }
    buffer[result] = '\0';
    return atoi(buffer);
}

int main(int argc, char *argv[]) {
    int file_descriptor;
    pigpio_init(5); // Initialize pigpio with 5 available pins (I2C on Raspberry Pi 4)
    if (pigpio_setup_i2c() < 0) {
        perror("pigpio_setup_i2c");
        return EXIT_FAILURE;
    }

    file_descriptor = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (file_descriptor == -1) {
        perror("open");
        pigpio_shutdown();
        return EXIT_FAILURE;
    }

    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), LOG_FORMAT, localtime(&ts.tv_sec));

    while (1) {
        int result = pigpio_write_i2c_reg(file_descriptor, TMP102_ADDRESS, 0x48, 0x00);
        if (result < 0) {
            fprintf(stderr, "Error writing to TMP102\n");
            continue;
        }

        result = pigpio_read_i2c_byte(file_descriptor, TMP102_ADDRESS, 0x00);
        if (result < 0) {
            fprintf(stderr, "Error reading from TMP102\n");
            continue;
        }

        int temperature = result;
        if (read_temperature(file_descriptor) < 0) {
            fprintf(stderr, "Failed to parse temperature\n");
            continue;
        }

        // Write temperature to log file
        char log_entry[20];
        sprintf(log_entry, "%s,%.2f\n", timestamp, temperature);
        write(file_descriptor, log_entry, strlen(log_entry));

        usleep(LOG_INTERVAL * 1000 / 1000); // Convert milliseconds to microseconds
    }

    pigpio_shutdown();
    close(file_descriptor);
    return EXIT_SUCCESS;
}

