#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x43
#define POLL_TIMEOUT_MS 500
#define MAX_RETRY 3

volatile sig_atomic_t shutdown_requested = 0;

void i2c_init() {
    int file = open("/dev/i2c-1", O_RDWR);
    if (file == -1) {
        perror("open /dev/i2c-1");
        exit(EXIT_FAILURE);
    }

    if (ioctl(file, I2C_SLAVE, I2C_ADDR) == -1) {
        perror("ioctl I2C_SLAVE");
        close(file);
        exit(EXIT_FAILURE);
    }
}

int read_measurement_config(uint8_t *config) {
    int retries = 0;
    uint8_t data[2];

    while (1) {
        int ret = read(file, data, 2);
        if (ret == -1) {
            if (errno == EIO || errno == EBUSY) {
                if (--retries < MAX_RETRY) {
                    printf("I2C bus error, retrying...\n");
                    usleep(100000); // 100ms delay
                } else {
                    printf("Max retries reached. Giving up.\n");
                    return -1;
                }
            } else {
                printf("I2C read error, exiting...\n");
                return -1;
            }
        }

        if (data[0] & 0x01) { // bit 0 set, sensor is busy
            usleep(100000); // wait for a short period
            continue;
        }

        *config = data[0];
        break;
    }

    return 0;
}

void handle_sensor_data(float *temp, float *humidity) {
    if (*config & 0x02) { // MEASUREMENT_CONFIG register bit 1 set
        *temp = ((data[1] << 8) | data[0]) * 0.01; // convert to Celsius
        *humidity = ((data[1] << 8) / 100) * 100; // convert to percentage
    } else {
        printf("No valid data received.\n");
    }
}

void signal_handler(int signum) {
    shutdown_requested = 1;
}

int main() {
    sigset_t sigset;
    int sig;

    // Set up signal handler for Ctrl+C
    sigaddset(&sigset, SIGINT);
    sigprocmask(SIG_BLOCK, &sigset, NULL);

    i2c_init();

    uint8_t config;
    float temp, humidity;

    while (!shutdown_requested) {
        if (read_measurement_config(&config) < 0) {
            break;
        }

        handle_sensor_data(&temp, &humidity);

        printf("Temperature: %.2f °C, Humidity: %.2f %%\n", temp, humidity);

        usleep(500000); // wait for 500ms before next reading
    }

    // Clean shutdown
    close(file);
    pigpio_terminate(NULL);

    return 0;
}

