#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <w1/master.h>
#include <pigpio.h>
#include <math.h>

#define SETPOINT 25.0
#define Kp 1.0
#define Ki 0.1
#define Kd 0.0
#define LOG_FILE "greenhouse.log"
#define TEMP_READ_INTERVAL 5000
#define RELAY_PIN 17
#define PWM_PIN 18
#define TEMP_SENSOR_PIN 4

typedef struct {
    float setpoint;
    float Kp;
    float Ki;
    float Kd;
    float error;
    float integral;
    float last_error;
    float derivative;
} pid_t;

pid_t pid_controller;

void initialize_w1(void) {
    int fd = open("/sys/bus/w1/devices/28-0000049f8f0f", W1_NO_DELAY);
    if (fd < 0) {
        perror("Failed to open w1 device");
        exit(EXIT_FAILURE);
    }

    struct w1_master *master = malloc(sizeof(struct w1_master));
    if (!master) {
        perror("Failed to allocate memory for w1_master");
        close(fd);
        exit(EXIT_FAILURE);
    }

    if (w1_read_css(master, 0x80) != 0) {
        perror("Failed to read device CSS");
        free(master);
        close(fd);
        exit(EXIT_FAILURE);
    }

    if (w1_reset_request(master, 0x00) != 0) {
        perror("Failed to reset device");
        free(master);
        close(fd);
        exit(EXIT_FAILURE);
    }

    while (1) {
        int temp_reg = w1_read_temp_raw(master);
        if (temp_reg == -1) {
            perror("Failed to read temperature");
            break;
        }

        float temperature = (float)temp_reg * 0.01;
        pid_controller.error = SETPOINT - temperature;
        pid_controller.integral += pid_controller.error;
        pid_controller.derivative = (pid_controller.error - pid_controller.last_error) / TEMP_READ_INTERVAL;
        pid_controller.last_error = pid_controller.error;

        float output = Kp * pid_controller.error + Ki * pid_controller.integral + Kd * pid_controller.derivative;

        if (output > 1.0) {
            output = 1.0;
        } else if (output < 0.0) {
            output = 0.0;
        }

        int duty = (int)(output * 255);
        gpioOutput(PWM_PIN, duty);

        if (output > pid_controller.error) {
            gpioWrite(RELAY_PIN, HIGH);
        } else {
            gpioWrite(RELAY_PIN, LOW);
        }

        pid_controller.error = 0.0;
        pid_controller.integral = 0.0;
        pid_controller.derivative = 0.0;

        usleep(TEMP_READ_INTERVAL * 1000 / 1000);
    }

    free(master);
    close(fd);
}

void log_temperature(const char *timestamp) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    fprintf(log_file, "%s %f %f %f %f\n", timestamp, pid_controller.error, SETPOINT, pid_controller.output, gpioRead(PWM_PIN));
    fclose(log_file);
}

int main(int argc, char *argv[]) {
    pid_t p;
    p.setpoint = SETPOINT;
    p.Kp = Kp;
    p.Ki = Ki;
    p.Kd = Kd;

    if (argc < 2) {
        fprintf(stderr, "Usage: %s <setpoint> <Kp> <Ki> <Kd>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    p.setpoint = atof(argv[1]);
    p.Kp = atof(argv[2]);
    p.Ki = atof(argv[3]);
    p.Kd = atof(argv[4]);

    initialize_w1();

    while (1) {
        log_temperature(strftime(NULL, 0, "%Y-%m-%d %H:%M:%S", localtime()));
        sleep(1);
    }

    gpioWrite(RELAY_PIN, LOW);
    gpioWrite(PWM_PIN, 0);
    fclose(stdout);
    fclose(stderr);
    close(stdout);
    close(stderr);
    close(LOG_FILE);
    pigpio_terminate();
    return 0;
}

