#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/wait.h>
#include <signal.h>
#include <pthread.h>

#define I2C_BUS 1
#define AHT20_ADDR 0x4B
#define DEHUMIDIFIER_GPIO 17
#define POLL_INTERVAL 5000 // 5 seconds
#define RETRY_COUNT 3
#define RETRY_DELAY 10000 // 10 ms

typedef struct {
    int file;
    int retries;
} i2c_context;

int i2c_open(i2c_context *ctx) {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("open /dev/i2c-1");
        return -1;
    }
    ctx->file = fd;
    return 0;
}

int i2c_close(i2c_context *ctx) {
    close(ctx->file);
    ctx->file = 0;
    return 0;
}

int i2c_write(i2c_context *ctx, uint8_t cmd, size_t len) {
    uint8_t buf[6];
    int ret = copy_to_user(ctx->buf, &cmd, len);
    if (ret != 0) {
        return -1;
    }
    ret = ioctl(ctx->file, I2C_SLAVE, AHT20_ADDR);
    if (ret < 0) {
        perror("ioctl I2C_SLAVE");
        return -1;
    }
    ret = write(ctx->file, ctx->buf, len);
    if (ret != len) {
        perror("write");
        return -1;
    }
    return 0;
}

int i2c_read(i2c_context *ctx, uint8_t *buf, size_t len) {
    int ret = read(ctx->file, ctx->buf, len);
    if (ret != len) {
        perror("read");
        return -1;
    }
    return 0;
}

int i2c_status(uint8_t *status) {
    int ret = read(ctx->file, status, 1);
    if (ret != 1) {
        perror("read status");
        return -1;
    }
