void log_error(const char *msg, int line) {
    syslog(LOG_ERR, "%s [%d] ", msg, line);
}

void log_info(const char *msg, int line) {
    syslog(LOG_INFO, "%s [%d] ", msg, line);
}

int i2c_open(int fd, const char *addr) {
    int ret = i2c_open(fd, I2C_BUS, addr);
    if (ret < 0) {
        log_error("Failed to open I2C bus", __LINE__);
        return -1;
    }
    return ret;
}

int i2c_write(int fd, uint8_t *buf, size_t len) {
    int ret = i2c_write(fd, buf, len);
    if (ret < 0) {
        log_error("Failed to write to I2C device", __LINE__);
        return -1;
    }
    return ret;
}

int i2c_read(int fd, uint8_t *buf, size_t len) {
    int ret = i2c_read(fd, buf, len);
    if (ret < 0) {
        log_error("Failed to read from I2C device", __LINE__);
        return -1;
    }
    return ret;
}

int http_post(const char *url) {
    int sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) {
        log_error("Failed to create socket", __LINE__);
        return -1;
    }

    struct sockaddr_in serv_addr;
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_port = htons(80);
    serv_addr.sin_addr.s_addr = inet_addr(HTTP_HOST);

    if (connect(sock, (struct sockaddr *)&serv_addr, sizeof(serv_addr)) < 0) {
        log_error("Failed to connect to server", __LINE__);
        close(sock);
        return -1;
    }

    char request[256];
    sprintf(request, "POST /humidity HTTP/1.1\r\nHost: %s\r\nContent-Type: application/json\r\n\r\n{\"humidity\": %f}\r\n\r\n", HTTP_HOST, htu21d_get_humidity());

    if (send(sock, request, strlen(request), 0) < 0) {
        log_error("Failed to send HTTP request", __LINE__);
        close(sock);
        return -1;
    }

    close(sock);
    return 0;
}

int main(int argc, char *argv[]) {
    int sockfd, i2c_fd;
    struct itimerval timer;
    htu21d_context ctx;
    double humidity;

    if (argc != 2) {
        log_error("Usage: %s <http_host>", argv[0]);
        exit(EXIT_FAILURE);
    }

    syslog(LOG_INFO, "Starting HTU21D sensor reader...");

    i2c_fd = i2c_open(0, I2C_ADDR);
    if (i2c_fd < 0) {
        log_error("Failed to open I2C bus", __LINE__);
        exit(EXIT_FAILURE);
    }

    htu21d_init(&ctx);
    if (htu21d_calibrate(&ctx) < 0) {
        log_error("Failed to calibrate HTU21D", __LINE__);
        i2c_close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    while (1) {
        timer.timerrval.tv_sec = 0;
        timer.timerrval.tv_usec = POLL_INTERVAL * 1000;
        if (setitimer(ITIMER_REAL, &timer, NULL) < 0) {
            log_error("Failed to set timer", __LINE__);
            break;
        }

        humidity = htu21d_get_humidity(&ctx);
        if (htu21d_get_status(&ctx) != HTU21D_OK) {
            log_error("HTU21D sensor error", __LINE__);
            continue;
        }

        if (http_post(HTTP_HOST) < 0) {
            log_error("Failed to post HTTP request", __LINE__);
        }

        usleep(POLL_INTERVAL * 1000);
    }

    syslog(LOG_INFO, "Exiting...");
    return 0;
}

