#include <i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x77
#define LOG_FILE "pressure_log.txt"
#define SAMPLE_INTERVAL_MS 2000
#define MAX_PRESSURE_THRESHOLD 1020.0
#define MIN_PRESSURE_THRESHOLD 980.0

#define MAX_RETRIES 3

void sigint_handler(int sig) {
    printf("Received SIGINT, shutting down...\n");
    close(log_fd);
    exit(0);
}

void sigterm_handler(int sig) {
    printf("Received SIGTERM, shutting down...\n");
    close(log_fd);
    exit(0);
}

int setup_i2c(int fd) {
    int ret;
    for (int i = 0; i < MAX_RETRIES; i++) {
        ret = i2c_open(fd, I2C_BUS);
        if (ret < 0) {
            printf("I2C open failed, retrying...\n");
            ret = i2c_open(fd, I2C_BUS);
            if (ret < 0) {
                perror("I2C open failed");
                return -1;
            }
        } else {
            break;
        }
    }
    if (ret < 0) {
        return -1;
    }

    ret = i2c_write_byte(fd, 0x77); // Write chip select
    if (ret < 0) {
        i2c_close(fd);
        return -1;
    }

    ret = i2c_read_byte(fd, 0x00); // Read chip ID
    if (ret < 0) {
        i2c_close(fd);
        return -1;
    }

    if (ret != 0x77) {
        printf("Chip ID mismatch, retrying...\n");
        ret = i2c_close(fd);
        if (ret < 0) {
            perror("I2C close failed");
            return -1;
        }

        ret = i2c_open(fd, I2C_BUS);
        if (ret < 0) {
            perror("I2C open failed");
            return -1;
        }

        ret = i2c_write_byte(fd, 0x77); // Write chip select
        if (ret < 0) {
            i2c_close(fd);
            return -1;
        }

        ret = i2c_read_byte(fd, 0x00); // Read chip ID
        if (ret < 0) {
            i2c_close(fd);
            return -1;
        }

        if (ret == 0x77) {
            printf("Chip ID verified.\n");
            break;
        }
    }

    return 0;
}

