#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define TMP117_I2C_ADDR 0x40
#define AHT20_I2C_ADDR 0x48
#define PIR_GPIO 4

#define LOG_FILE "sensor_log.csv"
#define SAMPLE_INTERVAL 60000000  // 1 second in microseconds
#define MAX_RETRIES 3
#define BACKOFF_MS 10000

void log_data(const char *data) {
    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        perror("Failed to open log file");
        return;
    }
    fprintf(file, "%s", data);
    fclose(file);
}

void init_gpio() {
    if (gpio_init() < 0) {
        perror("Failed to initialize pigpio");
        exit(EXIT_FAILURE);
    }
}

void init_i2c() {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Failed to open i2c bus");
        exit(EXIT_FAILURE);
    }

    struct i2c_client client;
    memset(&client, 0, sizeof(client));
    client.device = 0x40; // TMP117
    if (ioctl(fd, I2C_SLAVE, client.device) < 0) {
        perror("Failed to set i2c slave address for TMP117");
        exit(EXIT_FAILURE);
    }

    client.device = 0x48; // AHT20
    if (ioctl(fd, I2C_SLAVE, client.device) < 0) {
        perror("Failed to set i2c slave address for AHT20");
        exit(EXIT_FAILURE);
    }

    close(fd);
}

int read_tmp117() {
    int ret = 0;
    for (int i = 0; i < 3; i++) {
        ret = ioctl(1, WHO_AM_I, &tmp117_reg_addr);
        if (ret == 0) {
            break;
        }
        if (ret == -EIO) {
            usleep(BACKOFF_MS * i);
        } else {
            perror("Failed to read from TMP117");
            return -1;
        }
    }
    if (ret == 0) {
        return ioctl(1, TMP117_REG_TEMP, &tmp117_temp);
    }
    return -1;
}

int read_aht20() {
    int ret = 0;
    for (int i = 0; i < 3; i++) {
        ret = ioctl(1, WHO_AM_I, &aht20_reg_addr);
        if (ret == 0) {
            break;
        }
        if (ret == -EIO) {
            usleep(BACKOFF_MS * i);
        } else {
            perror("Failed to read from AHT20");
            return -1;
        }
    }
    if (ret == 0) {
        return ioctl(1, AHT20_REG_TEMP, &aht20_temp);
    }
    return -1;
}

int read_pir() {
    int state = 0;
    if (gpio_get_level(PIR_GPIO) == 0) {
        state = 1;
    }
    return state;
}

void setup_logging() {
    time_t now = time(NULL);
    struct tm *local_time = localtime(&now);
    char time_str[80];
    sprintf(time_str, "%04d-%02d-%02d %02d:%02d:%02d",
            local_time->tm_year + 1900, local_time->tm_mon + 1,
            local_time->tm_mday, local_time->tm_hour, local_time->tm_min,
            local_time->tm_sec);

    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
    fprintf(file, "%s", "Timestamp,Temperature(C),Humidity(%),MotionDetected\n");
    fclose(file);
}

void cleanup_resources() {
    gpio_terminate();
    close(1);
    close(2);
    close(6);
    close(9);
    close(10);
    close(11);
    close(13);
    close(14);
    close(15);
    close(17);
}

int main() {
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    init_gpio();
    init_i2c();

    setup_logging();

    while (1) {
        int tmp117_temp = -1;
        int aht20_temp = -1;
        int pir_motion = read_pir();

        if (read_tmp117() < 0) {
            log_data("Sensor not present\n");
            continue;
        }
        tmp117_temp = read_tmp117();

        if (read_aht20() < 0) {
            log_data("Sensor not present\n");
            continue;
        }
        aht20_temp = read_aht20();

        log_data(",%d,%d,%d\n", time(NULL), tmp117_temp, aht20_temp, pir_motion);
        usleep(SAMPLE_INTERVAL);
    }

    cleanup_resources();
    return 0;
}

void sigint_handler(int signum) {
    log_data("Received SIGINT, exiting gracefully\n");
    exit(0);
}

void sigterm_handler(int signum) {
    log_data("Received SIGTERM, exiting gracefully\n");
    exit(0);
}

