#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <string.h>
#include <errno.h>
#include <pigpio.h>

#define SENSOR_PIN 17
#define MOTOR_FWD_EN 22
#define MOTOR_FWD_IN1 23
#define MOTOR_FWD_IN2 24
#define POLL_INTERVAL 2000
#define MOTOR_STOP_TIME 5000

void log_message(const char *message) {
    time_t now = time(NULL);
    char time_str[80];
    sprintf(time_str, "%s %d", ctime(&now), (int)POLL_INTERVAL);
    fprintf(stdout, "[%s] %s\n", time_str, message);
}

void signal_handler(int signum) {
    log_message("Receiving SIGINT or SIGTERM, stopping motor...");
    gpioInitialise();
    gpioOutput(MOTOR_FWD_EN, 0);
    gpioOutput(MOTOR_FWD_IN1, 0);
    gpioOutput(MOTOR_FWD_IN2, 0);
    exit(0);
}

int main(int argc, char *argv[]) {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int gpio_carrys[3] = {0};
    int sensor_state = 0;
    int motor_running = 0;

    gpioSetup(SENSOR_PIN, GPIO_INPUT, 0);
    gpioSetup(MOTOR_FWD_EN, GPIO_OUTPUT, 0);
    gpioSetup(MOTOR_FWD_IN1, GPIO_OUTPUT, 0);
    gpioSetup(MOTOR_FWD_IN2, GPIO_OUTPUT, 0);

    while (1) {
        log_message("Polling rain sensor...");
        sensor_state = gpioRead(SENSOR_PIN);

        if (sensor_state == 0) {
            log_message("Rain detected!");
            motor_running = 1;
            gpioOutput(MOTOR_FWD_EN, 1);
            gpioOutput(MOTOR_FWD_IN1, 1);
            gpioOutput(MOTOR_FWD_IN2, 1);
            usleep(MOTOR_STOP_TIME * 1000 / HRTIME_PER_SEC);
            gpioOutput(MOTOR_FWD_EN, 0);
            motor_running = 0;
            log_message("Motor stopped.");
        }

        usleep(POLL_INTERVAL * 1000 / HRTIME_PER_SEC);
    }

    gpioTerminate();
    return 0;
}

