#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <arpa/inet.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>
#include <gpiod.h>

#define I2C_ADDR 0x77
#define SDA_PIN 2
#define SCL_PIN 5
#define UDP_HOST "192.168.1.100"
#define UDP_PORT 5000
#define JSON_FORMAT "{\"temperature\":%f,\"pressure\":%f}"

struct BMP280_DATA {
    float temperature;
    float pressure;
};

void handle_sigint(int sig) {
    gpiod_disable(SDA_PIN);
    gpiod_disable(SCL_PIN);
    gpiod_clear_args(SDA_PIN);
    gpiod_clear_args(SCL_PIN);
    gpiod_output_default_value(SDA_PIN);
    gpiod_output_default_value(SCL_PIN);
    close(3); // close the I2C handle
    close(4); // close the UDP socket
    exit(0);
}

void handle_sigterm(int sig) {
    handle_sigint(sig);
}

int main() {
    pid_t pid;
    sigset_t sigset;

    // Initialize signal handlers
    sigset_init(&sigset);
    sigaddset(&sigset, SIGINT);
    sigaddset(&sigset, SIGTERM);
    setgid(0);
    seteuid(0);
    sigprocmask(SIG_BLOCK, &sigset, NULL);

    // Initialize I2C
    int i2c_fd = gpiod_open_device(SDA_PIN, SCL_PIN, 0);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    // Initialize BMP280
    struct BMP280_DATA data;
    data.temperature = -1.0;
    data.pressure = -1.0;

    while (1) {
        // Read temperature and pressure
        if (gpiod_get_value(SDA_PIN) == 0 && gpiod_get_value(SCL_PIN) == 0) {
            // I2C communication
            int result = gpiod_write_pin(SDA_PIN, 1);
            if (result < 0) {
                perror("Failed to set SDA high");
                exit(EXIT_FAILURE);
            }

            result = gpiod_write_pin(SCL_PIN, 1);
            if (result < 0) {
                perror("Failed to set SCL high");
                exit(EXIT_FAILURE);
            }

            result = gpiod_read_pin(SDA_PIN);
            if (result < 0) {
                perror("Failed to read SDA");
                exit(EXIT_FAILURE);
            }

            result = gpiod_read_pin(SCL_PIN);
            if (result < 0) {
                perror("Failed to read SCL");
                exit(EXIT_FAILURE);
            }

            result = gpiod_clear_args(SDA_PIN);
            if (result < 0) {
                perror("Failed to clear SDA args");
                exit(EXIT_FAILURE);
            }

            result = gpiod_clear_args(SCL_PIN);
            if (result < 0) {
                perror("Failed to clear SCL args");
                exit(EXIT_FAILURE);
            }

            // Send I2C command to BMP280
            result = gpiod_write_pin(SDA_PIN, 0);
            if (result < 0) {
                perror("Failed to set SDA low");
                exit(EXIT_FAILURE);
            }

            result = gpiod_write_pin(SCL_PIN, 1);
            if (result < 0) {
                perror("Failed to set SCL high");
                exit(EXIT_FAILURE);
            }

            result = gpiod_write_mem(I2C_ADDR, 0x6B, 1); // Start temperature conversion
            if (result < 0) {
                perror("Failed to write to BMP280");
                exit(EXIT_FAILURE);
            }

            result = gpiod_write_mem(I2C_ADDR, 0x43, 1); // Start pressure conversion
            if (result < 0) {
                perror("Failed to write to BMP280");
                exit(EXIT_FAILURE);
            }

            result = gpiod_read_mem(I2C_ADDR, 0x7B); // Read temperature
            if (result < 0) {
                perror("Failed to read temperature");
                exit(EXIT_FAILURE);
            }

            result = gpiod_read_mem(I2C_ADDR, 0x7C); // Read pressure
            if (result < 0) {
                perror("Failed to read pressure");
                exit(EXIT_FAILURE);
            }

            result = gpiod_write_pin(SDA_PIN, 1);
            if (result < 0) {
                perror("Failed to set SDA low");
                exit(EXIT_FAILURE);
            }

            result = gpiod_write_pin(SCL_PIN, 0);
            if (result < 0) {
                perror("Failed to set SCL low");
                exit(EXIT_FAILURE);
            }

            // Wait for conversions to complete
            usleep(10000);
        }

        // Format data into JSON string
        char json_buffer[1024];
        sprintf(json_buffer, JSON_FORMAT, data.temperature, data.pressure);

        // Send JSON via UDP
        struct sockaddr_in addr;
        addr.sin_family = AF_INET;
        addr.sin_port = htons(UDP_PORT);
        addr.sin_addr.s_addr = inet_addr(UDP_HOST);

        int sock = socket(AF_INET, SOCK_DGRAM, 0);
        if (sock < 0) {
            perror("Failed to create UDP socket");
            exit(EXIT_FAILURE);
        }

        sendto(sock, json_buffer, strlen(json_buffer), 0, (struct sockaddr *)&addr, sizeof(addr));
        close(sock);

        // Sleep for 5 seconds
        usleep(50000000);
    }

    // Clean up and exit
    gpiod_disable(SDA_PIN);
    gpiod_disable(SCL_PIN);
    gpiod_clear_args(SDA_PIN);
    gpiod_clear_args(SCL_PIN);
    close(3); // close the I2C handle
    close(4); // close the UDP socket
    exit(0);
}

