            result = gpiod_write_pin(SCL_PIN, 1);
            if (result < 0) {
                perror("Failed to set SCL high");
                exit(EXIT_FAILURE);
            }

            result = gpiod_read_pin(SDA_PIN);
            if (result < 0) {
                perror("Failed to read SDA");
                exit(EXIT_FAILURE);
            }

            result = gpiod_read_pin(SCL_PIN);
            if (result < 0) {
                perror("Failed to read SCL");
                exit(EXIT_FAILURE);
            }

            result = gpiod_clear_args(SDA_PIN);
            if (result < 0) {
                perror("Failed to clear SDA args");
                exit(EXIT_FAILURE);
            }

            result = gpiod_clear_args(SCL_PIN);
            if (result < 0) {
                perror("Failed to clear SCL args");
                exit(EXIT_FAILURE);
            }

            // Send I2C command to BMP280
            result = gpiod_write_pin(SDA_PIN, 0);
            if (result < 0) {
                perror("Failed to set SDA low");
                exit(EXIT_FAILURE);
            }

            result = gpiod_write_pin(SCL_PIN, 1);
            if (result < 0) {
                perror("Failed to set SCL high");
                exit(EXIT_FAILURE);
            }

            result = gpiod_write_mem(I2C_ADDR, 0x6B, 1); // Start temperature conversion
            if (result < 0) {
                perror("Failed to write to BMP280");
                exit(EXIT_FAILURE);
            }

            result = gpiod_write_mem(I2C_ADDR, 0x43, 1); // Start pressure conversion
            if (result < 0) {
                perror("Failed to write to BMP280");
                exit(EXIT_FAILURE);
            }

            result = gpiod_read_mem(I2C_ADDR, 0x7B); // Read temperature
            if (result < 0) {
                perror("Failed to read temperature");
                exit(EXIT_FAILURE);
            }

            result = gpiod_read_mem(I2C_ADDR, 0x7C); // Read pressure
            if (result < 0) {
                perror("Failed to read pressure");
                exit(EXIT_FAILURE);
            }

            result = gpiod_write_pin(SDA_PIN, 1);
            if (result < 0) {
                perror("Failed to set SDA low");
                exit(EXIT_FAILURE);
            }

            result = gpiod_write_pin(SCL_PIN, 0);
            if (result < 0) {
                perror("Failed to set SCL low");
                exit(EXIT_FAILURE);
            }

            // Wait for conversions to complete
            usleep(10000);
        }

        // Format data into JSON string
        char json_buffer[1024];
        sprintf(json_buffer, JSON_FORMAT, data.temperature, data.pressure);

        // Send JSON via UDP
        struct sockaddr_in addr;
        addr.sin_family = AF_INET;
        addr.sin_port = htons(UDP_PORT);
        addr.sin_addr.s_addr = inet_addr(UDP_HOST);

        int sock = socket(AF_INET, SOCK_DGRAM, 0);
        if (sock < 0) {
            perror("Failed to create UDP socket");
            exit(EXIT_FAILURE);
        }

        sendto(sock, json_buffer, strlen(json_buffer), 0, (struct sockaddr *)&addr, sizeof(addr));
        close(sock);

        // Sleep for 5 seconds
        usleep(50000000);
    }

    // Clean up and exit
    gpiod_disable(SDA_PIN);
    gpiod_disable(SCL_PIN);
    gpiod_clear_args(SDA_PIN);
    gpiod_clear_args(SCL_PIN);
    close(3); // close the I2C handle
    close(4); // close the UDP socket
    exit(0);
}
```

This code uses `libgpiod` for I2C communication and `libpcap` for UDP transmission. It includes error handling for I2C operations, sensor readings, and UDP transmission. The program also handles SIGINT and SIGTERM signals to cleanly release resources.

Please note that you need to install `libgpiod` and `libpcap` on your Raspberry Pi before compiling and running this code.

To compile the code, use:

```bash
gcc -o bmp280_sensor bmp280_sensor.c -lgpiod -lpcap
```

To run the program, use:

```bash
sudo ./bmp280_sensor
```

This code assumes that the BMP280 sensor is connected to the I2C bus (SDA=GPIO2/pin 3, SCL=GPIO3/pin 5) and that the Raspberry Pi's network interface is configured with the correct IP address and port for UDP transmission. Adjust these values as necessary for your setup.

