#define MAX_BUFFER_SIZE 20
#define FAN_GPIO 18
#define MAX_TEMP_ERROR 10
#define SPI_CHANNEL 0
#define SPI_SPEED 500000

#define BUFFER_FILE "fan_buffer.dat"

typedef struct {
    unsigned int timestamp;
    float temperature;
    int duty_cycle;
} DataEntry;

typedef struct {
    DataEntry buffer[MAX_BUFFER_SIZE];
    int head;
    int tail;
} CircularBuffer;

void init_spi(int channel, int speed) {
    int file = open(BUFFER_FILE, O_WRONLY | O_CREAT, S_IRUSR | S_IWUSR | 0644);
    if (file == -1) {
        perror("Error opening buffer file");
        exit(EXIT_FAILURE);
    }

    struct statfs buf;
    if (fstatfs(file, &buf) == -1) {
        perror("Error getting file stats");
        close(file);
        exit(EXIT_FAILURE);
    }

    if (buf.f_bsize < 4) {
        perror("Buffer size too small");
        close(file);
        exit(EXIT_FAILURE);
    }

    if (ioctl(file, SPC_SET_SPEED, speed) == -1) {
        perror("Error setting SPI speed");
        close(file);
        exit(EXIT_FAILURE);
    }

    if (ioctl(file, SPC_SET_MODE, channel) == -1) {
        perror("Error setting SPI mode");
        close(file);
        exit(EXIT_FAILURE);
    }

    close(file);
}

int open_fan_gpio(int *gpio) {
    if (*gpio == -1) {
        *gpio = pigpio_open(FAN_GPIO);
        if (*gpio == -1) {
            perror("Error opening fan GPIO");
            return -1;
        }
    }
    return 0;
}

int close_fan_gpio(int gpio) {
    if (gpio == -1) return -1;
    pigpio_close(gpio);
    return 0;
}

int read_max31855_temp(float *temp) {
    if (*temp == -1) {
        char buffer[10];
        int len = read(SPI_CHANNEL, buffer, sizeof(buffer) - 1);
        if (len == -1) {
            perror("Error reading from MAX31855");
            return -1;
        }
        buffer[len] = '\0';
        *temp = atof(buffer);
    }
    return 0;
}

int set_pwm_duty(int duty) {
    if (duty < 0 || duty > 255) {
        perror("Duty cycle out of range");
        return -1;
    }
    return pigpio_set_pwm(FAN_GPIO, 0, duty);
}

int main(int argc, char *argv[]) {
    int fan_gpio, spi_channel, max31855_ce, max31855_data;
    CircularBuffer cb;
    int head = 0, tail = 0;
    float temp;
    int duty_cycle;
    FILE *buffer_file = fopen(BUFFER_FILE, "rb+");

    if (open_fan_gpio(&fan_gpio) != 0) {
        fprintf(stderr, "Failed to open fan GPIO\n");
        return -1;
    }

    init_spi(SPI_CHANNEL, SPI_SPEED);

    if (read_max31855_temp(&temp) != 0) {
        fprintf(stderr, "Failed to read temperature from MAX31855\n");
        return -1;
    }

    cb.head = 0;
    cb.tail = 0;

    while (1) {
        cb.buffer[cb.head].timestamp = micros();
        cb.buffer[cb.head].temperature = temp;
        cb.buffer[cb.head].duty_cycle = 0;
        cb.head++;

        if (cb.head == MAX_BUFFER_SIZE) {
            cb.head = 0;
        }

        if (tail == cb.head) {
            fprintf(stderr, "Buffer overflow\n");
            continue;
        }

        tail++;

        int duty_cycle_calc = 0;
        if (temp < 25) {
            duty_cycle_calc = 0;
        } else if (temp >= 25 && temp < 40) {
            duty_cycle_calc = (int)(50 * (temp - 25));
        } else if (temp >= 40 && temp < 60) {
            duty_cycle_calc = (int)(200 * (temp - 40));
        } else {
            duty_cycle_calc = 255;
        }

        if (set_pwm_duty(duty_cycle_calc) != 0) {
            fprintf(stderr, "Failed to set PWM duty cycle\n");
        }

        if (read_max31855_temp(&temp) != 0) {
            fprintf(stderr, "Failed to read temperature from MAX31855\n");
            continue;
        }

        if (temp < 25) {
            duty_cycle_calc = 0;
        } else if (temp >= 25 && temp < 40) {
            duty_cycle_calc = (int)(50 * (temp - 25));
        } else if (temp >= 40 && temp < 60) {
            duty_cycle_calc = (int)(200 * (temp - 40));
        } else {
            duty_cycle_calc = 255;
        }

        if (set_pwm_duty(duty_cycle_calc) != 0) {
            fprintf(stderr, "Failed to set PWM duty cycle\n");
        }

        if (fwrite(&cb.buffer[cb.tail], sizeof(DataEntry), 1, buffer_file) != 1) {
            perror("Error writing to buffer file");
            continue;
        }

        cb.tail++;

        if (cb.tail == MAX_BUFFER_SIZE) {
            cb.tail = 0;
        }

        if (cb.head == cb.tail) {
            fprintf(stderr, "Buffer underflow\n");
            continue;
        }

        if (pigpio_poll() == -1) {
            perror("Error polling pigpio");
            continue;
        }

        usleep(1000000 / 1000); // 1 second delay
    }

    fclose(buffer_file);
    close_fan_gpio(&fan_gpio);
    close(SPI_CHANNEL);
    pigpio_terminate();

    printf("Buffer contents:\n");
    DataEntry entry;
    while (fread(&entry, sizeof(DataEntry), 1, buffer_file) == 1) {
        printf("Timestamp: %lu, Temperature: %.1f, Duty Cycle: %d\n", entry.timestamp, entry.temperature, entry.duty_cycle);
    }

    return 0;
}

