#include <pigpio.h>

#define I2C_BUS 1
#define BMP180_ADDR 0x77
#define GPIO_PIN 2
#define OSS 3
#define LOG_FILE "altitude_log.txt"
#define LOG_INTERVAL 1000

void gpio_init(void);
void i2c_init(void);
void log_data(const char *data);
void toggle_logging(void);
void read_sensor(void);

int main(int argc, char *argv[]) {
    int i2c_fd, gpio_pin;
    struct i2c_client *client;
    int gpio_config;

    gpio_init();
    i2c_init();

    while (1) {
        if (toggle_logging()) {
            read_sensor();
        }
        usleep(LOG_INTERVAL * 1000);
    }

    close(i2c_fd);
    pigpio_terminate(1000);
    close(GPIO_PIN);
    fclose(stdout);
    return 0;
}

void gpio_init(void) {
    gpio_pin = GPIO_PIN;
    gpioConfiguration(gpio_pin, PI_MODE_INPUT, PI_ATTEN(0, 0));
    gpioSetPull(gpio_pin, PI_PULLUP);
}

void i2c_init(void) {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open i2c bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BMP180_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

void toggle_logging(void) {
    static int logging = 0;
    logging = !logging;
    if (logging) {
        log_data("logging_on");
    } else {
        log_data("logging_off");
    }
    return logging;
}

void log_data(const char *data) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    fprintf(log_file, "%s,%.1f,%.1f\n", get_timestamp(), read_sensor_temperature(), read_sensor_pressure());
    fclose(log_file);
}

void read_sensor(void) {
    struct bmp180_register_s reg_data;
    int read_bytes;

    read_bytes = i2c_read_block_data(i2c_fd, BMP180_ADDR, sizeof(reg_data), &reg_data);
    if (read_bytes != sizeof(reg_data)) {
        perror("Failed to read from BMP180");
        return;
    }

    if (reg_data.reg_status & 0x01) {
        if (reg_data.reg_status & 0x02) {
            // Calibration data read successfully
            float temperature = reg_data.temperature * 0.01;
            float pressure = reg_data.pressure * 100.0;
            log_data("on,");
            log_data(temperature);
            log_data(pressure);
        } else {
            perror("Calibration data read failed");
        }
    } else {
        perror("BMP180 register read failed");
    }
}

float read_sensor_temperature(void) {
    // This function should be implemented to read the temperature from the BMP180 sensor
    // For simplicity, we're just returning a placeholder value
    return 25.0;
}

float read_sensor_pressure(void) {
    // This function should be implemented to read the pressure from the BMP180 sensor
    // For simplicity, we're just returning a placeholder value
    return 1013.25;
}

