#include <math.h>

#define CE_PIN 8
#define SPI_SPEED 1000000
#define RTD_PIN 4
#define LOG_FILE "rtd_log.csv"
#define LOG_INTERVAL 5

#define CALLENDER_VAN_DUSEN_A 1.000000
#define CALLENDER_VAN_DUSEN_B 4.898581
#define CALLENDER_VAN_DUSEN_C 1.000000E-3
#define CALLENDER_VAN_DUSEN_D -5.775E-7

void log_temperature(float temperature) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }
    time_t now = time(NULL);
    char timestamp[80];
    sprintf(timestamp, "%ld-%02d-%02d %02d:%02d:%02d",
            (long)now / 86400, (long)now % 86400 / 24,
            (long)now % 24, now % 24 / 1440,
            now % 1440 / 60, now % 60);
    fprintf(log_file, "%s, %f\n", timestamp, temperature);
    fclose(log_file);
}

int main() {
    int spi_fd, rtd_data;
    struct spidev_dev *dev;

    spi_fd = spidev_open(0, 0);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return EXIT_FAILURE;
    }

    dev = spidev_get_device(spi_fd);
    if (!dev) {
        perror("Failed to get device information");
        spidev_close(spi_fd);
        return EXIT_FAILURE;
    }

    // Set up SPI communication
    ioctl(spi_fd, SPI_RDWR_ADDRESS, (u32)0x20); // Set address to 0x20 for MAX31865
    ioctl(spi_fd, SPI_RDWR_MODE, (u32)SPI_MODE0); // Set mode to 0 (CPOL = 0)
    ioctl(spi_fd, SPI_RDWR_BITS, (u32)8); // Set bits per word to 8
    ioctl(spi_fd, SPI_RDWR_SPEED, (u32)SPI_SPEED); // Set speed to 1 MHz

    // Configure CE pin as output
    ioctl(spi_fd, SPI_CTS, 0); // Clear CTS (CE low)
    ioctl(spi_fd, SPI_RTS, 1); // Set RTS (CE high)

    // Initialize temperature reading
    rtd_data = 0;
    while (1) {
        // Set CE low to enable communication
        ioctl(spi_fd, SPI_CTS, 1);

        // Send command to read temperature
        uint8_t command[1] = {0x01}; // Read temperature command
        spidev_write_cd(dev, command);

        // Wait for the response
        uint8_t response[2];
        spidev_read_cd(dev, response);

        // Check for fault status
        if (response[0] & 0x02) { // Fault status bit set
            fprintf(stderr, "SPI communication fault\n");
            rtd_data = -1;
            break;
        }

        // Read temperature data
        rtd_data = response[1];

        // Check for sensor absent
        if (rtd_data == 0xFF) {
            fprintf(stderr, "Sensor absent\n");
            rtd_data = -1;
            break;
        }

        // Compute temperature using Callendar-Van Dusen equation
        float resistance = (float)rtd_data * 0.01; // Convert to ohms
        float temperature = 1.0 / (CALLENDER_VAN_DUSEN_A +
                CALLENDER_VAN_DUSEN_B * log(resistance) +
                CALLENDER_VAN_DUSEN_C / resistance +
                CALLENDER_VAN_DUSEN_D * resistance * log(resistance));

        // Log the temperature
        log_temperature(temperature);

        // Wait for LOG_INTERVAL seconds before next read
        usleep(LOG_INTERVAL * 1000000);
    }

    // Graceful shutdown
    spidev_close(spi_fd);
    fclose(stdout);
    return EXIT_SUCCESS;
}

