#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define BMP180_ADDR 0x77
#define BUFFER_SIZE 60 * 60 * 1000 / 1000000  // 60 seconds in milliseconds
#define TIMER_INTERVAL_MS 50
#define GPIO24 23

typedef struct {
    long timestamp;
    float pressure;
} PressureSample;

PressureSample buffer[BUFFER_SIZE];
int buffer_index = 0;

int i2c_fd;

void setup_i2c() {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BMP180_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

void setup_gpio() {
    if (gpioInitialise() < 0) {
        perror("Failed to initialise pigpio");
        exit(EXIT_FAILURE);
    }
    gpioSetMode(GPIO24, GPIO_OUTPUT);
}

void read_bmp180(PressureSample *sample) {
    uint8_t buf[6];

    if (read_i2c_block(i2c_fd, BMP180_ADDR, 0x6B, 1, buf, 6) < 0) {
        perror("Failed to read BMP180 data");
        return;
    }

    sample->pressure = (float)(buf[0] << 8 | buf[1]) / 10;
    sample->timestamp = current_time();
}

void timer_callback() {
    read_bmp180(&buffer[buffer_index]);
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;

    float pressure_avg = 0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        pressure_avg += buffer[i].pressure;
    }
    pressure_avg /= BUFFER_SIZE;

    if (fabs(buffer[buffer_index].pressure - pressure_avg) > 5.0) {
        fprintf(stderr, "ALERT: Pressure deviation detected!\n");
        gpioWrite(GPIO24, 1);
    }
}

int main(int argc, char *argv[]) {
    setup_i2c();
    setup_gpio();

    while (1) {
        timer_callback();
        usleep(TIMER_INTERVAL_MS * 1000 / HRTIME_PER_SEC);
    }

    close(i2c_fd);
    gpioTerminate();
    return 0;
}

