#define TEMP_REG 0x2A
#define PRESS_REG 0x2B
#define OSS_VAL 0x00

#define LOG_FILE "bmp180_log.txt"

void sigint_handler(int signum) {
    printf("Received SIGINT, cleaning up and exiting.\n");
    close(logfd);
    exit(0);
}

void sigterm_handler(int signum) {
    printf("Received SIGTERM, cleaning up and exiting.\n");
    close(logfd);
    exit(0);
}

int main(int argc, char *argv[]) {
    int logfd;
    int i2c_fd;
    struct i2c_client *client;
    int result;
    int temp_c, press_pa;
    uint8_t oss_reg, oss_val;
    char log_entry[64];

    logfd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (logfd == -1) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    result = gpiod_init();
    if (result < 0) {
        perror("gpiod_init");
        exit(EXIT_FAILURE);
    }

    result = gpiod_device_add_from_name("/dev/i2c-1");
    if (result < 0) {
        perror("gpiod_device_add_from_name");
        exit(EXIT_FAILURE);
    }

    result = gpiod_channel_add(I2C_BUS, 0, "i2c");
    if (result < 0) {
        perror("gpiod_channel_add");
        exit(EXIT_FAILURE);
    }

    client = gpiod_channel_get_client(I2C_BUS, 0);
    if (!client) {
        perror("gpiod_channel_get_client");
        exit(EXIT_FAILURE);
    }

    oss_reg = OSS_REG;
    oss_val = OSS_VAL;

    result = gpiod_channel_set_config(client, GPIOD_MODE_MASTER, 0);
    if (result < 0) {
        perror("gpiod_channel_set_config");
        exit(EXIT_FAILURE);
    }

    result = gpiod_channel_enable(client);
    if (result < 0) {
        perror("gpiod_channel_enable");
        exit(EXIT_FAILURE);
    }

    result = gpiod_channel_write(client, &oss_reg, 1);
    if (result < 0) {
        perror("gpiod_channel_write");
        exit(EXIT_FAILURE);
    }

    result = gpiod_channel_write(client, &oss_val, 1);
    if (result < 0) {
        perror("gpiod_channel_write");
        exit(EXIT_FAILURE);
    }

    result = gpiod_device_enable(result);
    if (result < 0) {
        perror("gpiod_device_enable");
        exit(EXIT_FAILURE);
    }

    while (1) {
        result = gpiod_poll(client, 1000, 100000);
        if (result < 0) {
            perror("gpiod_poll");
            exit(EXIT_FAILURE);
        }

        if (result == 0) {
            printf("I2C communication timeout.\n");
            continue;
        }

        result = gpiod_channel_read(client, &temp_c, 1);
        if (result < 0) {
            perror("gpiod_channel_read");
            exit(EXIT_FAILURE);
        }

        result = gpiod_channel_read(client, &press_pa, 1);
        if (result < 0) {
            perror("gpiod_channel_read");
            exit(EXIT_FAILURE);
        }

        if (result != 2) {
            perror("gpiod_channel_read");
            exit(EXIT_FAILURE);
        }

        sprintf(log_entry, "Time: %ld ms, Temperature: %.2f°C, Pressure: %.2f Pa\n",
            (long)result, temp_c, press_pa);
        result = write(logfd, log_entry, sizeof(log_entry));
        if (result != sizeof(log_entry)) {
            perror("write");
            exit(EXIT_FAILURE);
        }

        // Calibration check (assuming default values are correct)
        if (result != 2) {
            printf("Calibration check failed, skipping data.\n");
        }

        usleep(500000);
    }

    close(logfd);
    gpiod_device_disable(I2C_BUS, 0);
    gpiod_channel_disable(I2C_BUS, 0);
    gpiod_cleanup();

    return 0;
}
