#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define PWM_FREQUENCY 25000
#define PWM_MAX_Duty 255
#define PWM_MIN_Duty 0

#define LOG_INTERVAL 5

void sigint_handler(int sig) {
    printf("Received SIGINT, stopping fan...\n");
    pwm_stop(PWM_PIN);
    close(logfd);
    exit(0);
}

void sigterm_handler(int sig) {
    printf("Received SIGTERM, stopping fan...\n");
    pwm_stop(PWM_PIN);
    close(logfd);
    exit(0);
}

int main() {
    int logfd, pwm_fd;
    struct stat temp_stat;
    char temp_str[10];
    int pwm_duty;

    logfd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (logfd == -1) {
        perror("Error opening log file");
        exit(EXIT_FAILURE);
    }

    pwm_fd = open("/dev/pwm0", O_WRONLY | O_CREAT | O_EXCL, 0644);
    if (pwm_fd == -1) {
        perror("Error opening PWM device");
        close(logfd);
        exit(EXIT_FAILURE);
    }

    while (1) {
        if (read(TEMP_FILE, &temp_str, sizeof(temp_str)) == -1) {
            perror("Error reading temperature from /sys/class/thermal/thermal_zone0/temp");
            pwm_duty = PWM_MIN_Duty; // Default to 0% duty if temperature cannot be read
        } else {
            temp_str[strcspn(temp_str, "\n")] = 0; // Null-terminate the string
            pwm_duty = map_temp_to_pwm(atoi(temp_str));
            if (pwm_duty < PWM_MIN_Duty) {
                pwm_duty = PWM_MIN_Duty;
            } else if (pwm_duty > PWM_MAX_Duty) {
                pwm_duty = PWM_MAX_Duty;
            }
        }

        pwm_write(pwm_fd, pwm_duty);

        // Log the current timestamp, temperature, and duty cycle
        char timestamp[20];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        fprintf(logfd, "Timestamp: %s, Temperature: %d°C, Duty Cycle: %d%%\n", timestamp, temp_str[0], pwm_duty);

        usleep(PWM_FREQUENCY * 1000 / 1000); // Delay for 25kHz
    }

    close(logfd);
    close(pwm_fd);

    pwm_stop(PWM_PIN);
    printf("Fan stopped, cleaning up resources...\n");

    // Install signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    return 0;
}

int map_temp_to_pwm(int temp) {
    int range = PWM_MAX_Duty - PWM_MIN_Duty;
    int mapped_duty = (temp - 25) * (range / (70 - 40));
    return mapped_duty;
}

