#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <time.h>

#define I2C_BUS 1
#define SDA_PIN 3
#define SCL_PIN 5
#define BMP280_ADDRESS 0x77

#define LOG_FILE "weather_data.txt"

void log_data(const char *timestamp, double temperature, double pressure) {
    time_t now = time(NULL);
    struct tm *local_time = localtime(&now);
    char buffer[100];
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", local_time);
    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        fprintf(stderr, "Error opening file: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
    fprintf(file, "%s, Temperature: %.2f °C, Pressure: %.2f hPa\n", buffer, temperature, pressure);
    fclose(file);
}

int main() {
    int i2c_fd;
    struct i2c_client *client;
    int16_t ctrl_meas;
    int16_t temp_raw, press_raw;
    double temperature, pressure;

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open i2c bus");
        exit(EXIT_FAILURE);
    }

    client = i2c_client_new(i2c_fd, BMP280_ADDRESS);
    if (!client) {
        perror("Failed to create i2c client");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    ctrl_meas = 0x00; // Force a measurement
    while (1) {
        // Rewrite ctrl_meas to trigger a new measurement
        ioctl(i2c_fd, I2C_SLAVE, client->addr);
        ioctl(i2c_fd, I2C_READ, BMP280_REG_CTRL_MEAS);
        client->data = &ctrl_meas;
        ioctl(i2c_fd, I2C_WRITE, client->addr);

        // Read temperature and pressure
        ioctl(i2c_fd, I2C_SLAVE, client->addr);
        ioctl(i2c_fd, I2C_READ, BMP280_REG_TEMP_RAW);
        client->data = &temp_raw;
        ioctl(i2c_fd, I2C_WRITE, client->addr);

        ioctl(i2c_fd, I2C_SLAVE, client->addr);
        ioctl(i2c_fd, I2C_READ, BMP280_REG_PRESS_RAW);
        client->data = &press_raw;
        ioctl(i2c_fd, I2C_WRITE, client->addr);

        // Apply Bosch 64-bit compensation formulas
        temperature = (press_raw >> 16) * 0.00008336 + (press_raw & 0x3fff) * 0.00000075 + 29.3;
        pressure = (press_raw >> 16) * 100.0 + (press_raw & 0x3fff);

        // Log data
        log_data(get_timestamp(), temperature, pressure);

        // Wait for 5 seconds
        usleep(50000000);
    }

    // Close I2C file descriptor and any open files
    close(i2c_fd);

    // Handle SIGINT and SIGTERM
    if (signal(SIGINT) == SIG_IGN || signal(SIGTERM) == SIG_IGN) {
        fprintf(stderr, "Received SIGINT or SIGTERM, exiting gracefully.\n");
        exit(0);
    }

    // Wait for child processes to finish
    waitpid(0, NULL, 0);

    return 0;
}

