#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <pthread.h>
#include <libgpiop.h>
#include <i2c-dev.h>

#define BUFFER_SIZE 60
#define I2C_BUS 1
#define GPIO_LED 18

typedef struct {
    gpiopic_t pic;
    gpiopic_handle_t handle;
    pthread_t background_thread;
    pthread_mutex_t mutex;
    int buffer_index;
    int buffer_capacity;
    float temperature_readings[BUFFER_SIZE];
    float running_average;
} LM75_Context;

static int i2c_open(const char *device, int *fd) {
    int ret;
    *fd = open("/dev/i2c-1", O_RDWR);
    if (*fd < 0) {
        perror("i2c_open");
        return -1;
    }
    ret = ioctl(*fd, I2C_SLAVE, (u_int8_t)0x40);
    if (ret < 0) {
        perror("i2c_open");
        close(*fd);
        return -1;
    }
    return *fd;
}

static int i2c_close(int fd) {
    close(fd);
    return 0;
}

static int gpio_init(void) {
    int ret;
    ret = gpiopic_init(&pic);
    if (ret < 0) {
        perror("gpio_init");
        return -1;
    }
    ret = gpiopic_output_init(pic, GPIO_LED);
    if (ret < 0) {
        perror("gpio_init");
        gpiopic_cleanup(&pic);
        return -1;
    }
    return 0;
}

static void gpio_cleanup(void) {
    gpiopic_output_cleanup(&pic);
}

static int background_thread_func(void *arg) {
    LM75_Context *context = (LM75_Context *)arg;
    while (1) {
        int ret;
        ret = pthread_mutex_lock(&context->mutex);
        if (ret != 0) {
            fprintf(stderr, "Error in background_thread_func: pthread_mutex_lock failed\n");
            continue;
        }

        if (context->buffer_index < context->buffer_capacity) {
            context->temperature_readings[context->buffer_index] = context->running_average;
            context->buffer_index++;
        } else {
            context->running_average = context->temperature_readings[0];
        }

        ret = i2c_read_byte_dt(context->fd, 0x40, &context->temperature_readings[context->buffer_index % context->buffer_capacity]);
        if (ret < 0) {
            fprintf(stderr, "Error in background_thread_func: i2c_read_byte_dt failed\n");
            pthread_mutex_unlock(&context->mutex);
            continue;
        }

        if (context->temperature_readings[context->buffer_index % context->buffer_capacity] > 28.0) {
            pthread_mutex_unlock(&context->mutex);
            gpio_output_set(context->handle, 1);
        } else {
            pthread_mutex_unlock(&context->mutex);
            gpio_output_set(context->handle, 0);
        }

        pthread_mutex_unlock(&context->mutex);
        usleep(1000000); // Sleep for 1 second
    }
    return 0;
}

int main(void) {
    int fd, ret;
    LM75_Context context;
    pthread_t background_thread;

    fd = LM75_Context_init(&context);
    if (fd < 0) {
        perror("LM75_Context_init");
        exit(EXIT_FAILURE);
    }

    if (gpio_init() < 0) {
        LM75_Context_destroy(&context);
        i2c_close(fd);
        exit(EXIT_FAILURE);
    }

    background_thread = pthread_create(&background_thread, NULL, background_thread_func, &context);
    if (background_thread == NULL) {
        perror("pthread_create");
        LM75_Context_destroy(&context);
        i2c_close(fd);
        exit(EXIT_FAILURE);
    }

    while (1) {
        usleep(1000000000); // Sleep for 1 second
    }

    LM75_Context_destroy(&context);
    i2c_close(fd);
    gpio_cleanup();
    return 0;
}

