#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <pthread.h>
#include <json-c/json.h>
#include <pigpio.h>

#define MAX_TEMP_ERROR 10
#define HEATER_GPIO 18
#define MAX_SPI_TRANSFER_SIZE 64
#define PID_TICKS_PER_SECOND 100
#define MAX_TEMP_TARGET 25
#define Kp 1.0
#define Ki 0.1
#define Kd 0.01
#define REF_RES 430.0
#define NORM_RES 100.0
#define SPI_INTERFACE 0
#define MAX_SPI_TRANSFER_ATTEMPTS 5

typedef struct {
    double target_temp;
    double pid_kp;
    double pid_ki;
    double pid_kd;
    int fault_detected;
} pid_config_t;

pid_config_t pid_config = {
    .target_temp = MAX_TEMP_TARGET,
    .pid_kp = Kp,
    .pid_ki = Ki,
    .pid_kd = Kd,
    .fault_detected = 0
};

int spi_transfer(const uint8_t *data, size_t len, int *transfer_size) {
    int ret;
    int buffer[MAX_SPI_TRANSFER_SIZE];
    *transfer_size = 0;

    while (*transfer_size < len) {
        ret = pigpio_spi_transfer(SPI_INTERFACE, 0, data, *transfer_size, buffer);
        if (ret < 0) {
            perror("SPI transfer failed");
            return -1;
        }
        *transfer_size += ret;
    }

    return 0;
}

double read_pt100_temperature() {
    uint8_t data[2];
    int transfer_size;

    if (spi_transfer(NULL, 0, &transfer_size) != 0) {
        return -1.0;
    }

    if (transfer_size < 2) {
        return -1.0;
    }

    data[0] = 0x00;
    data[1] = 0x00;

    if (spi_transfer(data, 2, &transfer_size) != 0) {
        return -1.0;
    }

    double raw_value = (data[1] << 8) | data[0];
    double temp = (raw_value - 163.84) * 0.01;

    double rtd_temp = temp / (100.0 - REF_RES);
    double nominal_temp = rtd_temp * NORM_RES;

    if (nominal_temp > 80.0) {
        pid_config.fault_detected = 1;
        return 80.0;
    }

    return nominal_temp;
}

int set_heater_duty(int duty) {
    if (gpioSetMode(HEATER_GPIO, GPIO_OUTPUT) < 0) {
        perror("Failed to set GPIO mode");
        return -1;
    }

    if (gpioWrite(HEATER_GPIO, duty) < 0) {
        perror("Failed to set GPIO duty cycle");
        return -1;
    }

    return 0;
}

int pid_control(double error, double integral, double last_error, double *derivative) {
    double derivative_term = *derivative;

    double output = pid_config.pid_kp * error + pid_config.pid_ki * integral + pid_config.pid_kd * derivative_term;

    if (output > 1.0) {
        output = 1.0;
    } else if (output < 0.0) {
        output = 0.0;
    }

    *derivative = error + last_error;

    return output;
}

int main(int argc, char *argv[]) {
    pid_config_t config;
    int ret;

    if (argc < 2) {
        fprintf(stderr, "Usage: %s <json_config_file>\n", argv[0]);
        return EXIT_FAILURE;
    }

    FILE *fp = fopen(argv[1], "r");
    if (!fp) {
        perror("Failed to open configuration file");
        return EXIT_FAILURE;
    }

    json_object *jobj = json_object_from_file(fp);
    json_object *target_temp_obj = json_object_object_get(jobj, "target_temp");
    json_object *kp_obj = json_object_object_get(jobj, "kp");
    json_object *ki_obj = json_object_object_get(jobj, "ki");
    json_object *kd_obj = json_object_object_get(jobj, "kd");

    if (!target_temp_obj || !kp_obj || !ki_obj || !ki_obj || !kd_obj) {
        pid_config.target_temp = MAX_TEMP_TARGET;
        pid_config.pid_kp = Kp;
        pid_config.pid_ki = Ki;
        pid_config.pid_kd = Kd;
    } else {
        pid_config.target_temp = json_object_get_double(target_temp_obj);
        pid_config.pid_kp = json_object_get_double(kp_obj);
        pid_config.pid_ki = json_object_get_double(ki_obj);
        pid_config.pid_kd = json_object_get_double(kd_obj);
    }

    json_object_delete(jobj);
    fclose(fp);

    if (pid_config.target_temp < 0) {
        pid_config.target_temp = MAX_TEMP_TARGET;
    }

    if (pid_config.pid_kp < 0 || pid_config.pid_ki < 0 || pid_config.pid_kd < 0) {
        pid_config.pid_kp = Kp;
        pid_config.pid_ki = Ki;
        pid_config.pid_kd = Kd;
    }

    pid_config.fault_detected = 0;

    while (1) {
        double temp = read_pt100_temperature();

        if (temp > 80.0) {
            pid_config.fault_detected = 1;
            set_heater_duty(0);
            break;
        }

        double last_error = temp - pid_config.target_temp;
        double integral = 0.0;

        if (pid_config.fault_detected) {
            break;
        }

        double duty = pid_control(temp - pid_config.target_temp, integral, last_error, &integral);
        set_heater_duty(duty * 100);

        usleep(PID_TICKS_PER_SECOND * 1000 / 1000);
    }

    pigpio_terminate(1000);
    return EXIT_SUCCESS;
}

