#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <pthread.h>
#include <libgpiod/gpio.h>
#include <pigpio.h>

#define I2C_BUS "/dev/i2c-1"
#define BMP180_ADDRESS 0x77
#define SAMPLE_INTERVAL_S 1.0
#define BREACH_TEMP_THRESHOLD 30.0
#define BREACH_PRESSURE_THRESHOLD 950.0
#define BREACH_LOG_FILE "breach_log.txt"

#define MAX_RETRIES 3

void write_to_log(const char *timestamp, int temperature, int pressure) {
    FILE *file = fopen(BREACH_LOG_FILE, "a");
    if (!file) {
        perror("Failed to open breach_log.txt");
        return;
    }
    fprintf(file, "%s: Temp: %d, Press: %d\n", timestamp, temperature, pressure);
    fclose(file);
}

void calibrate_bmp180(int *temperature, int *pressure) {
    int i, j, k, temp_avg, press_avg;
    *temperature = 0;
    *pressure = 0;

    for (i = 0; i < 10; i++) {
        gpioOutput(BMP180_ADDRESS, 0);
        delay(100);
        gpioOutput(BMP180_ADDRESS, 1);
        delay(100);

        gpioRead(BMP180_ADDRESS, 0);
        int raw_temp = gpioRead(BMP180_ADDRESS, 0);
        int raw_press = gpioRead(BMP180_ADDRESS, 1);

        *temperature += raw_temp;
        *pressure += raw_press;
    }

    *temperature /= 10;
    *pressure /= 10;

    // Integer arithmetic for calibration
    int temp_diff = *temperature - 1000;
    int press_diff = *pressure - 1013.25;

    // Adjust temperature
    if (temp_diff > 0) {
        *temperature -= temp_diff;
    } else {
        *temperature += temp_diff;
    }

    // Adjust pressure
    if (press_diff < 0) {
        *pressure += press_diff;
    } else {
        *pressure -= press_diff;
    }
}

int main(int argc, char *argv[]) {
    int i2c_fd, ret;
    int temperature, pressure;
    char timestamp[20];
    FILE *log_file = fopen(BREACH_LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open breach_log.txt");
        return 1;
    }

    pthread_t thread_id;
    pthread_create(&thread_id, NULL, sensor_thread, NULL);

    while (1) {
        ret = pigpio_init(1);
        if (ret < 0) {
            fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpio_strerror(ret));
            exit(1);
        }

        ret = gpioSetup(I2C_BUS, BMP180_ADDRESS, PI_OUTPUT);
        if (ret < 0) {
            fprintf(stderr, "Failed to set up I2C bus for BMP180: %s\n", pigpio_strerror(ret));
            pigpio_terminate();
            exit(1);
        }

        ret = gpioWrite(BMP180_ADDRESS, 0);
        if (ret < 0) {
            fprintf(stderr, "Failed to write to BMP180: %s\n", pigpio_strerror(ret));
            pigpio_terminate();
            exit(1);
        }

        ret = gpioRead(BMP180_ADDRESS, 0);
        if (ret < 0) {
            fprintf(stderr, "Failed to read from BMP180: %s\n", pigpio_strerror(ret));
            pigpio_terminate();
            exit(1);
        }

        calibrate_bmp180(&temperature, &pressure);

        if (temperature > BREACH_TEMP_THRESHOLD || pressure < BREACH_PRESSURE_THRESHOLD) {
            sprintf(timestamp, "%s", ctime(&gpioRead(BMP180_ADDRESS, 0)));
            write_to_log(timestamp, temperature, pressure);
        }

        gpioWrite(BMP180_ADDRESS, 0);
        gpioWrite(BMP180_ADDRESS, 1);
        usleep(SAMPLE_INTERVAL_S * 1000000); // Convert seconds to microseconds
    }

    pthread_join(thread_id, NULL);
    pigpio_terminate();
    fclose(log_file);
    return 0;
}

void *sensor_thread(void *arg) {
    while (1) {
        // No action needed in this thread, just sleep
    }
    return NULL;
}

