#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS 1
#define BMP180_ADDR 0x77
#define BUFFER_SIZE 60
#define SAMPLE_INTERVAL_MS 500
#define FAN_GPIO 18

typedef struct {
    long timestamp;
    float temperature;
    float pressure;
} SensorReading;

SensorReading read_calibration_table(void) {
    SensorReading reading;
    // Assuming calibration table is at offset 0x00 in register 0x00
    reading.timestamp = readl(BMP180_ADDR | 0x00);
    reading.temperature = readl(BMP180_ADDR | 0x01);
    reading.pressure = readl(BMP180_ADDR | 0x02);
    return reading;
}

void write_calibration_table(SensorReading reading) {
    // Assuming calibration table is at offset 0x00 in register 0x00
    writel(reading.timestamp, BMP180_ADDR | 0x00);
    writel(reading.temperature, BMP180_ADDR | 0x01);
    writel(reading.pressure, BMP180_ADDR | 0x02);
}

void fan_control(float temperature) {
    if (temperature > 30.0) {
        gpioSetMode(FAN_GPIO, PI_OUTPUT);
        gpioWrite(FAN_GPIO, 1);
    } else {
        gpioSetMode(FAN_GPIO, PI_OUTPUT);
        gpioWrite(FAN_GPIO, 0);
    }
}

int main(int argc, char *argv[]) {
    int i2c_fd, fan_gpio;
    SensorReading readings[BUFFER_SIZE];
    int read_index = 0;
    int buffer_written = 0;
    struct itimerspec timer_interval;
    timer_init(&timer_interval, SAMPLE_INTERVAL_MS / 1000);

