#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define BMP180_ADDRESS 0x77
#define GPIO27 27
#define LOG_FILE "pressure_log.txt"
#define DEBOUNCE_TIME 200

#define BOSCH_CALIBRATION_DATA 0x00
#define BOSCH_CALIBRATION_OFFSET 0x01
#define BOSCH_CALIBRATION_SCALE 0x02
#define BOSCH_CALIBRATION_TEMPERATURE 0x03

#define LOG_INTERVAL 2000000  // 2 seconds in microseconds

int main(int argc, char *argv[]) {
    int i2c_fd, gpio_fd;
    struct i2c_client *client;
    int bmp180_address;
    int gpio_number;
    int gpio_value;
    long timestamp;
    float pressure;
    char log_entry[100];

    if (argc != 2) {
        fprintf(stderr, "Usage: %s <log_toggle>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    // Initialize pigpio
    if (piGPIO_init() < 0) {
        perror("Failed to initialize pigpio");
        exit(EXIT_FAILURE);
    }

    // Initialize I2C
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        piGPIO_shutdown();
        exit(EXIT_FAILURE);
    }

    bmp180_address = BMP180_ADDRESS;
    client = i2c_client_new(i2c_fd, bmp180_address);
    if (!client) {
        perror("Failed to create I2C client");
        piGPIO_shutdown();
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    gpio_fd = open(argv[1], O_WRLCK | O_CREAT | O_APPEND, 0666);
    if (gpio_fd < 0) {
        perror("Failed to open GPIO file for writing lock");
        piGPIO_shutdown();
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    gpio_number = fileno(gpio_fd);
    gpio_mode(gpio_number, PI_OUTPUT);
    gpio_write(gpio_number, 0);

    // Set up debounce timer
    struct timespec debounce_timeout;
    debounce_timeout.tv_sec = 0;
    debounce_timeout.tv_nsec = DEBOUNCE_TIME * 1000000;
    setitimer(ITIMER_REAL, &debounce_timeout, NULL);

    // Main loop
    while (1) {
        // Read BMP180 calibration data
        if (i2c_transfer(client, BMP180_ADDRESS, BOSCH_CALIBRATION_DATA, 1, 0) < 0) {
            perror("Failed to read calibration data");
            break;
        }

        // Read BMP180 calibration offset and scale
        if (i2c_transfer(client, BMP180_ADDRESS, BOSCH_CALIBRATION_OFFSET, 1, 0) < 0) {
            perror("Failed to read calibration offset");
            break;
        }

        if (i2c_transfer(client, BMP180_ADDRESS, BOSCH_CALIBRATION_SCALE, 1, 0) < 0) {
            perror("Failed to read calibration scale");
            break;
        }

        // Read temperature
        if (i2c_transfer(client, BMP180_ADDRESS, BOSCH_CALIBRATION_TEMPERATURE, 1, 0) < 0) {
            perror("Failed to read temperature");
            break;
        }

        // Compute pressure
        pressure = (1048.0 * (i2c_read(client, BMP180_ADDRESS, 0x00) / 4095.0 - 74021.0) *
                    (1.0 + (i2c_read(client, BMP180_ADDRESS, 0x01) / 20000.0) * 0.003908) +
                    29024.0);

        // Check for falling edge on GPIO27
        if (gpio_get(gpio_number) == 0) {
            // Toggle logging
            if (piGPIO_get(GPIO27) == 0) {
                piGPIO_put(GPIO27, 1);
                printf("Logging enabled\n");
            } else {
                piGPIO_put(GPIO27, 0);
                printf("Logging disabled\n");
            }
        }

        // Log pressure with timestamp
        timestamp = microtime();
        sprintf(log_entry, "%lu %f\n", timestamp, pressure);
        if (write(log_fd, log_entry, strlen(log_entry)) < 0) {
            perror("Failed to write to log file");
            break;
        }

        // Debounce
        if (microtime() - start_time > debounce_timeout.tv_sec) {
            start_time = microtime();
        }

        usleep(LOG_INTERVAL / 1000000);
    }

    // Clean up
    piGPIO_shutdown();
    close(i2c_fd);
    close(gpio_fd);
    close(log_fd);
    i2c_client_free(client);

    return 0;
}

