#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/epoll.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

#define SPI_BUS 0
#define SPI_DEVICE 0
#define SPI_SPEED 20000000
#define MAX_TEMP_ERROR 10
#define MAX_DUTY_CYCLE 80
#define LOG_FILE "heater_log.csv"

#define MAX_LOG_ENTRIES 1000

typedef struct {
    time_t timestamp;
    float temperature;
    int duty_cycle;
} LogEntry;

static LogEntry log_entries[MAX_LOG_ENTRIES];
static int log_entries_written = 0;
static int log_file_fd = -1;

void log_entry(const LogEntry entry) {
    if (log_entries_written < MAX_LOG_ENTRIES) {
        log_entries[log_entries_written].timestamp = time(NULL);
        log_entries[log_entries_written].temperature = entry.temperature;
        log_entries[log_entries_written].duty_cycle = entry.duty_cycle;
        log_entries_written++;
        if (log_file_fd != -1) {
            write(log_file_fd, "timestamp,temperature,duty_cycle\n", 33);
            write(log_file_fd, "%llu,%f,%d\n", (long long)log_entries[log_entries_written - 1].timestamp,
                log_entries[log_entries_written - 1].temperature, log_entries[log_entries_written - 1].duty_cycle);
        }
    } else {
        printf("Log file is full, cannot add new entry.\n");
    }
}

void init_log_file() {
    log_file_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, S_IRUSR | S_IWUSR);
    if (log_file_fd == -1) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
}

void close_log_file() {
    if (log_file_fd != -1) {
        close(log_file_fd);
        log_file_fd = -1;
    }
}

void handle_spi_error(const char *msg) {
    log_entry({.temperature = -1.0, .duty_cycle = 0});
    printf("SPI Error: %s\n", msg);
}

void handle_max31855_fault(const char *msg) {
    log_entry({.temperature = -1.0, .duty_cycle = 0});
    printf("MAX31855 Fault: %s\n", msg);
}

int main(int argc, char *argv[]) {
    int spi_fd, gpio_channel;
    struct spi_ioc_transfer spi_transfer[2] = {
        {SPI_IOC_MESSAGE(1), (void *)0, SPI_IOC_MSG_LEN(0), (void *)NULL},
        {SPI_IOC_MESSAGE(2), (void *)0, SPI_IOC_MSG_LEN(16), (void *)NULL}
    };

    if (spi_fd = spidev_open(SPI_BUS, 0)) {
        perror("Failed to open SPI device");
        return EXIT_FAILURE;
    }

    gpio_channel = gpio_newchannel(GPIO_ANY, 8); // GPIO8 as chip select
    if (gpio_newchannel(GPIO_ANY, 9) == -1 || gpio_newchannel(GPIO_ANY, 10) == -1 ||
        gpio_newchannel(GPIO_ANY, 11) == -1) {
        perror("Failed to initialize GPIO pins");
        return EXIT_FAILURE;
    }

    pigpio_init(1);

    init_log_file();

    while (1) {
        spi_transfer[0].t_msge = (void *)0;
        spi_transfer[0].t_len = SPI_IOC_MESSAGE(1);
        if (spidev_transfer(spi_fd, &spi_transfer[0], 1, 1000) < 0) {
            handle_spi_error("SPI Transfer failed");
        }

        int16_t temp;
        if (spidev_recv(spi_fd, (uint8_t *)&temp, 2, 1000) < 0) {
            handle_spi_error("SPI Receive failed");
        }

        float duty_cycle = 0.0;
        if (gpio_get(gpio_channel) == 0) {
            duty_cycle = 0.0;
        } else {
            duty_cycle = 100.0 - (int)temp * 0.01;
            if (duty_cycle > MAX_DUTY_CYCLE) {
                duty_cycle = MAX_DUTY_CYCLE;
            }
        }

        if (duty_cycle > 0) {
            if (gpio_set_level(gpio_channel, 1) == -1) {
                handle_max31855_fault("Failed to set GPIO level for heater control");
            }
        } else {
            if (gpio_set_level(gpio_channel, 0) == -1) {
                handle_max31855_fault("Failed to set GPIO level for heater control");
            }
        }

        log_entry({.temperature = temp, .duty_cycle = duty_cycle});

        usleep(100000); // Adjust as needed for desired sampling rate
    }

    close_log_file();
    pigpio_terminate(pigpio_get_errno());
    spidev_close(spi_fd);
    return EXIT_SUCCESS;
}

