#define DHT22_PIN 7
#define RETRY_COUNT 3

typedef struct {
    int retries;
    int success;
} DHT22Result;

DHT22Result dht22_read(void) {
    DHT22Result result;
    result.retries = RETRY_COUNT;
    result.success = 0;

    // Initialize pigpio
    if (piGPIO_init() < 0) {
        perror("Failed to initialize pigpio");
        return result;
    }

    // Start signal: pull DHT22_PIN low for at least 1ms
    gpioSetMode(DHT22_PIN, PI_OUTPUT);
    usleep(1000);
    gpioWrite(DHT22_PIN, 0);
    usleep(100);
    gpioWrite(DHT22_PIN, 1);

    // Read 40-bit response
    int response = gpioRead(DHT22_PIN);
    if (response == 0) {
        result.success = 1;
        return result;
    }

    // Checksum validation
    int checksum = 0;
    for (int i = 0; i < 8; i++) {
        checksum += response & 0x01;
        response >>= 1;
    }
    if (checksum != response & 0xFF) {
        result.success = 1;
        return result;
    }

    result.retries--;
    if (result.retries == 0) {
        result.success = 1;
        return result;
    }

    // Wait before next attempt
    usleep(100000);
    return result;
}

void http_post(const char *url, const char *data) {
    FILE *fp = fopen(url, "w");
    if (!fp) {
        perror("Error opening file");
        return;
    }
