    if (argc != 2) {
        fprintf(stderr, "Usage: %s <http_server_url>\n", argv[0]);
        return 1;
    }

    http_post(argv[1], "{\"humidity\": %d, \"temperature\": %d}\n",
              (int)(dht22_read().success ? 1 : 0), (int)(dht22_read().success ? 1 : 0));

    return 0;
}

void signal_handler(int signum) {
    printf("Received signal %d, shutting down...\n", signum);
    piGPIO_shutdown();
    exit(0);
}

int main_thread(void *arg) {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        DHT22Result result = dht22_read();
        if (result.success) {
            printf("DHT22 read successful\n");
        } else {
            printf("DHT22 read failed, retrying...\n");
        }
        usleep(1000000); // Wait before next attempt
    }

    return 0;
}

int main(int argc, char *argv[]) {
    pthread_t thread;
    if (pthread_create(&thread, NULL, main_thread, NULL) != 0) {
        perror("Failed to create thread");
        return 1;
    }

    // Wait for the thread to finish
    pthread_join(thread, NULL);

    return 0;
}

