#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS 1
#define BMP180_ADDR 0x77
#define OSS 3
#define LOG_INTERVAL 2000000  // 2 seconds in microseconds
#define CONVERSION_DELAY 26   // in milliseconds
#define BUTTON_GPIO 4
#define BUTTON_EDGE falling

#define LOG_FILE "pressure_log.txt"

int i2c_fd;
int button_fd;

void i2c_init() {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }
    if (ioctl(i2c_fd, I2C_SLAVE, BMP180_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        exit(EXIT_FAILURE);
    }
}

void gpio_init() {
    button_fd = open("/dev/gpiomem", O_RDWR);
    if (button_fd < 0) {
        perror("Failed to open GPIO memory file");
        exit(EXIT_FAILURE);
    }
    if (ioctl(button_fd, GPIOPINGET, &BUTTON_GPIO) < 0) {
        perror("Failed to get GPIO pin configuration");
        exit(EXIT_FAILURE);
    }
    if (ioctl(button_fd, GPIOPINSET, BUTTON_GPIO) < 0) {
        perror("Failed to set GPIO pin as input with internal pull-up");
        exit(EXIT_FAILURE);
    }
}

void i2c_write(uint8_t reg, uint8_t data) {
    if (write(i2c_fd, &reg, 1) != 1) {
        perror("Failed to write to I2C bus");
        exit(EXIT_FAILURE);
    }
    if (write(i2c_fd, &data, 1) != 1) {
        perror("Failed to write to I2C bus");
        exit(EXIT_FAILURE);
    }
}

uint8_t i2c_read(uint8_t reg) {
    uint8_t data;
    if (read(i2c_fd, &data, 1) != 1) {
        perror("Failed to read from I2C bus");
        exit(EXIT_FAILURE);
    }
    return data;
}

void i2c_calibrate() {
    uint8_t oss_reg = 0x00;
    uint8_t cal_reg = 0x00;

    i2c_write(OSS, OSS);  // Set OSS to 3
    i2c_write(cal_reg, 0x00);  // Apply integer-only compensation

    uint8_t status;
    while ((status = i2c_read(0x6B)) != 0x00) {
        if (status & 0x01) {
            fprintf(stderr, "Invalid calibration data received\n");
            exit(EXIT_FAILURE);
        }
    }
}

void button_interrupt_handler(int event) {
    static unsigned long last_debounce_time = 0;
    unsigned long current_time = microtime_us();
    static int button_state = 0;

    if (event & 1) {  // Falling edge detected
        if ((current_time - last_debounce_time) > 200000) {  // Debounce delay
            button_state = 1;
            last_debounce_time = current_time;
        }
    } else {
        button_state = 0;
    }

    if (button_state) {
        if (i2c_calibrate() == 0) {
            printf("Calibration successful\n");
        } else {
            fprintf(stderr, "Calibration failed\n");
            exit(EXIT_FAILURE);
        }
    }
}

void start_logging() {
    while (1) {
        if (i2c_calibrate() == 0) {
            uint16_t pressure = i2c_read(0x68);  // Read pressure data
            uint32_t timestamp = microtime_us();

            if (write(i2c_fd, &pressure, 2) != 2) {
                perror("Failed to write pressure data to I2C bus");
                exit(EXIT_FAILURE);
            }

            char log_entry[32];
            sprintf(log_entry, "%llu %d\n", (long double)pressure / 100.0, timestamp / 1000);
            FILE *fp = fopen(LOG_FILE, "a");
            if (!fp) {
                perror("Failed to open pressure_log.txt for appending");
                exit(EXIT_FAILURE);
            }
            fprintf(fp, log_entry);
            fclose(fp);
            printf("Pressure logged: %f hPa\n", (float)pressure / 100.0);
        } else {
            printf("Logging disabled\n");
        }
        usleep(LOG_INTERVAL);
    }
}

int main(int argc, char *argv[]) {
    pigpio_init(5);

    i2c_init();
    gpio_init();

    pigpio_set_mode(BUTTON_GPIO, PI_OUTPUT);
    pigpio_write(BUTTON_GPIO, 0);  // Set initial button state

    pigpio_set_deadtime(10);  // Set GPIO deadtime

    pigpio_set_edge_mode(BUTTON_GPIO, PI_EDGE_FALLING);

    pigpio_set_interrupt(BUTTON_GPIO, button_interrupt_handler, true);

    start_logging();

    pigpio_cleanup();
    close(i2c_fd);
    close(button_fd);
    return 0;
}

