#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define FAN_FILE "/sys/class/thermal/cooling_device0/cur_state"
#define LOG_FILE "/var/log/fan_control.log"
#define POLL_INTERVAL_SECS 5

enum FanState {
    OFF = 0,
    STATE1,
    STATE2,
    STATE3
};

enum FanSpeedMap {
    THERMAL_THRESHOLD_OFF = 45,
    THERMAL_THRESHOLD_STATE1 = 55,
    THERMAL_THRESHOLD_STATE2 = 65,
    THERMAL_THRESHOLD_MAX = 65
};

void log_message(const char *message) {
    int fd = open(LOG_FILE, O_APPEND | O_CREAT, S_IRUSR | S_IWUSR);
    if (fd == -1) {
        perror("Failed to open log file");
        return;
    }
    fprintf(fd, "%s", message);
    close(fd);
}

int get_temperature() {
    int temp;
    if (read(TEMP_FILE, &temp, 4) != 4) {
        perror("Failed to read temperature from sysfs");
        return -1;
    }
    return temp;
}

int get_fan_state() {
    int state;
    if (read(FAN_FILE, &state, 1) != 1) {
        perror("Failed to read fan state from sysfs");
        return -1;
    }
    return state;
}

int set_fan_state(int state) {
    if (state < 0 || state > 3) {
        return -1; // Invalid fan state
    }
    if (write(FAN_FILE, &state, 1) != 1) {
        perror("Failed to write fan state to sysfs");
        return -1;
    }
    return 0;
}

int main(int argc, char *argv[]) {
    int fan_state = OFF;
    int current_temp;
    int max_state = 3;

    while (1) {
        current_temp = get_temperature();
        if (current_temp == -1) {
            log_message("Failed to read temperature, retrying...");
            continue;
        }

        log_message("Current temperature: %d°C\n", current_temp);

        int current_fan_state = get_fan_state();
        if (current_fan_state == -1) {
            log_message("Failed to read fan state, retrying...");
            continue;
        }

        log_message("Current fan state: %d\n", current_fan_state);

        if (current_temp < THERMAL_THRESHOLD_OFF) {
            fan_state = OFF;
        } else if (current_temp < THERMAL_THRESHOLD_STATE1) {
            fan_state = STATE1;
        } else if (current_temp < THERMAL_THRESHOLD_STATE2) {
            fan_state = STATE2;
        } else {
            fan_state = STATE3;
        }

        if (set_fan_state(fan_state) == -1) {
            log_message("Failed to set fan state, retrying...");
            continue;
        }

        log_message("Fan state set to: %d\n", fan_state);

        usleep(POLL_INTERVAL_SECS * 1000000); // Convert seconds to microseconds
    }

    log_message("Fan control program shutting down gracefully.\n");
    set_fan_state(OFF); // Set fan to off on shutdown
    close(LOG_FILE);
    return 0;
}

