#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/statfs.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>
#include <math.h>

#define MAX31855_CS GPIO8
#define MAX31855_CLK GPIO11
#define MAX31855_DO GPIO9
#define PID_Kp 1.0
#define PID_Ki 0.1
#define PID_Kd 0.01
#define TARGET_TEMP 50.0
#define PWM_FREQ 1000
#define DUTY_CYCLE_MAX 100
#define DUTY_CYCLE_MIN 0
#define LOG_INTERVAL 1000

#define MAX_LOG_SIZE 1024
char log_file[MAX_LOG_SIZE];

int heater_gpio = 18;

int max31855_fd;
spi_device max31855_device;

void spi_init() {
    max31855_fd = open("/dev/spidev0.0", O_RDWR);
    if (max31855_fd < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(max31855_fd, SPI_IOC_DEVICE, 0) < 0) {
        perror("Failed to set SPI device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(max31855_fd, SPI_IOC_SPEED_HIGH, 1000000) < 0) {
        perror("Failed to set SPI speed");
        exit(EXIT_FAILURE);
    }

    if (ioctl(max31855_fd, SPI_IOC_MODE, SPI_MODE0) < 0) {
        perror("Failed to set SPI mode");
        exit(EXIT_FAILURE);
    }
}

int read_max31855() {
    uint8_t data[4];
    if (read(max31855_fd, data, 4) != 4) {
        perror("Failed to read from MAX31855");
        return -1;
    }

    // Process the 4 bytes to get the temperature
    // This is a placeholder for the actual MAX31855 reading logic
    int temp = (data[0] << 8) | data[1];
    temp |= (data[2] << 4) | data[3];
    return temp;
}

void pid_control(float setpoint, float actual, float prev_error, float time_error, float integral) {
    float derivative = time_error;
    float output = PID_Kp * prev_error + PID_Ki * integral + PID_Kd * derivative;

    if (actual > TARGET_TEMP) {
        output = 0;
    } else if (actual < TARGET_TEMP) {
        output = DUTY_CYCLE_MAX;
    }

    // Apply output to PWM duty cycle
    // This is a placeholder for the actual PWM control logic
    int duty_cycle = (int)(output * DUTY_CYCLE_MAX);
    if (duty_cycle < DUTY_CYCLE_MIN) {
        duty_cycle = DUTY_CYCLE_MIN;
    } else if (duty_cycle > DUTY_CYCLE_MAX) {
        duty_cycle = DUTY_CYCLE_MAX;
    }

    // Update PID state
    integral += time_error;
    prev_error = actual - setpoint;
}

int main(int argc, char *argv[]) {
    pid_t pid = pigpio_init(1);
    if (pid == -1) {
        perror("Failed to initialize pigpio");
        exit(EXIT_FAILURE);
    }

    spi_init();

    // Initialize heater GPIO
    if (gpioSetup(heater_gpio, GPIO_OUTPUT) == -1) {
        perror("Failed to set heater GPIO as output");
        pigpio_terminate(pid);
        exit(EXIT_FAILURE);
    }

    // Initialize logging
    open(log_file, O_WRONLY | O_CREAT | O_APPEND, S_IRUSR | S_IWUSR);
    if (log_file == -1) {
        perror("Failed to open log file");
        pigpio_terminate(pid);
        exit(EXIT_FAILURE);
    }

    // PID state
    float prev_error = 0;
    float integral = 0;
    float time_error = 0;

    // Main loop
    while (1) {
        int temp = read_max31855();
        if (temp == -1) {
            fprintf(stderr, "Failed to read from MAX31855\n");
            break;
        }

        // Error handling for MAX31855 fault bits
        if (temp & 0x80) { // Open circuit
            fprintf(stderr, "Open circuit detected\n");
            pid_control(TARGET_TEMP, 0, prev_error, 0, integral);
            gpioWrite(heater_gpio, 0); // Disable heater
            break;
        } else if (temp & 0x40) { // Short to GND
            fprintf(stderr, "Short to GND detected\n");
            pid_control(TARGET_TEMP, 0, prev_error, 0, integral);
            gpioWrite(heater_gpio, 0); // Disable heater
            break;
        } else if (temp & 0x20) { // Short to VCC
            fprintf(stderr, "Short to VCC detected\n");
            pid_control(TARGET_TEMP, 0, prev_error, 0, integral);
            gpioWrite(heater_gpio, 0); // Disable heater
            break;
        }

        // Failsafe logic
        if (temp > 100) {
            fprintf(stderr, "Temperature exceeds 100°C\n");
            pid_control(TARGET_TEMP, 0, prev_error, 0, integral);
            gpioWrite(heater_gpio, 0); // Disable heater
        } else if (temp < 0) {
            fprintf(stderr, "Temperature falls below 0°C\n");
            pid_control(TARGET_TEMP, 0, prev_error, 0, integral);
            gpioWrite(heater_gpio, 0); // Disable heater
        }

        // PID control
        pid_control(TARGET_TEMP, temp, prev_error, time_error, integral);

        // Log data
        time_t now = time(NULL);
        char time_str[10];
        sprintf(time_str, "%02d:%02d:%02d", now / 3600, (now % 3600) / 60, now % 60);
        fprintf(log_file, "%s: Temp: %.1f°C, Duty Cycle: %d%%, PID Output: %.2f\n", time_str, temp, (int)duty_cycle, output);

        // Update time_error for next iteration
        time_error = temp - TARGET_TEMP;

        // Sleep for log interval
        usleep(LOG_INTERVAL * 1000);
    }

    // Clean up and exit
    gpioWrite(heater_gpio, 0); // Turn off heater
    close(log_file);
    pigpio_terminate(pid);
    exit(EXIT_SUCCESS);
}

