        perror("Failed to initialize pigpio");
        exit(EXIT_FAILURE);
    }

    spi_init();

    // Initialize heater GPIO
    if (gpioSetup(heater_gpio, GPIO_OUTPUT) == -1) {
        perror("Failed to set heater GPIO as output");
        pigpio_terminate(pid);
        exit(EXIT_FAILURE);
    }

    // Initialize logging
    open(log_file, O_WRONLY | O_CREAT | O_APPEND, S_IRUSR | S_IWUSR);
    if (log_file == -1) {
        perror("Failed to open log file");
        pigpio_terminate(pid);
        exit(EXIT_FAILURE);
    }

    // PID state
    float prev_error = 0;
    float integral = 0;
    float time_error = 0;

    // Main loop
    while (1) {
        int temp = read_max31855();
        if (temp == -1) {
            fprintf(stderr, "Failed to read from MAX31855\n");
            break;
        }

        // Error handling for MAX31855 fault bits
        if (temp & 0x80) { // Open circuit
            fprintf(stderr, "Open circuit detected\n");
            pid_control(TARGET_TEMP, 0, prev_error, 0, integral);
            gpioWrite(heater_gpio, 0); // Disable heater
            break;
        } else if (temp & 0x40) { // Short to GND
            fprintf(stderr, "Short to GND detected\n");
            pid_control(TARGET_TEMP, 0, prev_error, 0, integral);
            gpioWrite(heater_gpio, 0); // Disable heater
            break;
        } else if (temp & 0x20) { // Short to VCC
            fprintf(stderr, "Short to VCC detected\n");
            pid_control(TARGET_TEMP, 0, prev_error, 0, integral);
            gpioWrite(heater_gpio, 0); // Disable heater
            break;
        }

        // Failsafe logic
        if (temp > 100) {
            fprintf(stderr, "Temperature exceeds 100°C\n");
            pid_control(TARGET_TEMP, 0, prev_error, 0, integral);
            gpioWrite(heater_gpio, 0); // Disable heater
        } else if (temp < 0) {
            fprintf(stderr, "Temperature falls below 0°C\n");
            pid_control(TARGET_TEMP, 0, prev_error, 0, integral);
            gpioWrite(heater_gpio, 0); // Disable heater
        }

        // PID control
        pid_control(TARGET_TEMP, temp, prev_error, time_error, integral);

        // Log data
        time_t now = time(NULL);
        char time_str[10];
        sprintf(time_str, "%02d:%02d:%02d", now / 3600, (now % 3600) / 60, now % 60);
        fprintf(log_file, "%s: Temp: %.1f°C, Duty Cycle: %d%%, PID Output: %.2f\n", time_str, temp, (int)duty_cycle, output);

        // Update time_error for next iteration
        time_error = temp - TARGET_TEMP;

        // Sleep for log interval
        usleep(LOG_INTERVAL * 1000);
    }

    // Clean up and exit
    gpioWrite(heater_gpio, 0); // Turn off heater
    close(log_file);
    pigpio_terminate(pid);
    exit(EXIT_SUCCESS);
}
