#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS 1
#define FLOW_LOG "flow_log.txt"
#define MAX_RETRIES 3

typedef struct {
    int sensor_address;
    int retries;
} sensor_data;

int i2c_open(const char *bus, int addr) {
    int fd;
    fd = open(bus, O_RDWR | O_SYNC);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }
    ioctl(fd, I2C_SLAVE, addr);
    if (ioctl(fd, WHO_IS_HERE) == -1) {
        close(fd);
        return -1;
    }
    return fd;
}

int i2c_write(int fd, uint8_t *buf, size_t len) {
    return write(fd, buf, len);
}

int i2c_read(int fd, uint8_t *buf, size_t len) {
    return read(fd, buf, len);
}

int i2c_close(int fd) {
    close(fd);
    return 0;
}

int read_flow_data(int fd, sensor_data *data) {
    uint8_t data_buf[3];
    int ret = 0;

    for (int i = 0; i < MAX_RETRIES; i++) {
        ret = i2c_read(fd, data_buf, 3);
        if (ret == 3) {
            // Read successful
            data->sensor_address = ntohl(data_buf[0]);
            data->retries = i;
            memcpy(&data_buf[1], &data_buf[2], 2); // Extract data bytes
            data->data_bytes[0] = ntohl(data_buf[1]);
            data->data_bytes[1] = ntohl(data_buf[2]);

            // Validate CRC-8 checksum
            uint8_t crc = 0;
            for (int j = 0; j < 3; j++) {
                crc ^= data_buf[j];
                for (int k = 0; k < 8; k++) {
                    crc <<= 1;
                    if (crc & 1) {
                        crc = crc >> 1;
                        break;
                    }
                }
            }

            if (crc == 0) {
                // CRC check passed
                return 0;
            }
        } else if (ret == -1) {
            // Handle I2C error
            perror("I2C read failed");
            if (i == MAX_RETRIES - 1) {
                return -1; // Give up after retries
            }
        }
    }
    return -1; // Retry limit exceeded
}

void log_flow_data(const char *timestamp, uint16_t flow1, uint16_t flow2) {
    FILE *fp = fopen(FLOW_LOG, "a");
    if (!fp) {
        perror("Failed to open flow_log.txt");
        return;
    }
    fprintf(fp, "%s, %u, %u\n", timestamp, flow1, flow2);
    fclose(fp);
}

int main() {
    int fd1, fd2;
    sensor_data data1, data2;

    fd1 = i2c_open(I2C_BUS, 0x70); // Replace 0x70 with actual sensor address
    fd2 = i2c_open(I2C_BUS, 0x71); // Replace 0x71 with actual sensor address

    if (fd1 < 0 || fd2 < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return EXIT_FAILURE;
    }

    while (1) {
        int ret1 = read_flow_data(fd1, &data1);
        int ret2 = read_flow_data(fd2, &data2);

        if (ret1 < 0 || ret2 < 0) {
            // Handle errors
            if (ret1 == -1) {
                fprintf(stderr, "Error reading from sensor 1\n");
            }
            if (ret2 == -1) {
                fprintf(stderr, "Error reading from sensor 2\n");
            }
            continue;
        }

        // Append data to log file
        char timestamp[20];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        log_flow_data(timestamp, data1.data_bytes[0], data2.data_bytes[0]);

        // Sleep for one second
        usleep(1000000);
    }

    i2c_close(fd1);
    i2c_close(fd2);
    return EXIT_SUCCESS;
}

