    int fd, ret;
    struct stat sb;
    gpiod_context_t ctx_a, ctx_b;
    gpiod_button_t btn_a, btn_b;
    uint32_t state_a, state_b, last_state_a, last_state_b;
    uint32_t position_a, position_b, prev_position_a, prev_position_b;
    double timestamp_a, timestamp_b;
    char log_entry[1024];

    if (argc != 2) {
        fprintf(stderr, "Usage: %s <command>\n", argv[0]);
        exit(1);
    }

    if (strcmp(argv[1], "start") == 0) {
        start_encoder();
    } else if (strcmp(argv[1], "stop") == 0) {
        stop_encoder();
    } else {
        fprintf(stderr, "Invalid command. Use 'start' or 'stop'.\n");
        exit(1);
    }

    return 0;

start_encoder:
    fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (fd == -1) {
        perror("open");
        exit(1);
    }

    ret = gpiod_channel_init(GPIO_A, GPIONO_OUTPUT, &ctx_a);
    if (ret < 0) {
        perror("gpiod_channel_init");
        close(fd);
        exit(1);
    }

    ret = gpiod_channel_init(GPIO_B, GPIONO_OUTPUT, &ctx_b);
    if (ret < 0) {
        perror("gpiod_channel_init");
        close(fd);
        exit(1);
    }

    ret = gpiod_button_init(GPIO_A, GPIONO_INPUT, &btn_a, 0);
    if (ret < 0) {
        perror("gpiod_button_init");
        close(fd);
        exit(1);
    }

    ret = gpiod_button_init(GPIO_B, GPIONO_INPUT, &btn_b, 0);
    if (ret < 0) {
        perror("gpiod_button_init");
        close(fd);
        exit(1);
    }

    while (1) {
        ret = gpiod_button_get(&btn_a, &state_a);
        if (ret < 0) {
            perror("gpiod_button_get");
            break;
        }

        ret = gpiod_button_get(&btn_b, &state_b);
        if (ret < 0) {
            perror("gpiod_button_get");
            break;
        }

        if (state_a != state_b) {
            timestamp_a = get_timestamp();
            timestamp_b = get_timestamp();

            position_a = (state_a & 0x01) ? 1 : 0;
            position_b = (state_b & 0x01) ? 1 : 0;

            prev_position_a = prev_position_b = position_a;
            prev_position_b = position_b;

            if (position_a != prev_position_a) {
                position_a = (position_a == 1) ? 0 : 1;
                prev_position_a = position_a;
            }

            if (position_b != prev_position_b) {
                position_b = (position_b == 1) ? 0 : 1;
                prev_position_b = position_b;
            }

            double angle_a = (position_a * ENCODER_REVS_PER_MIN) / ENCODER_SAMPLES_PER_REV;
            double angle_b = (position_b * ENCODER_REVS_PER_MIN) / ENCODER_SAMPLES_PER_REV;

            double angular_position = (angle_a - angle_b) * 180.0 / M_PI;

            if (angular_position < 0) {
                angular_position += 360.0;
            }

            snprintf(log_entry, sizeof(log_entry), "Time: %f, Position A: %f, Position B: %f, Angular Position: %f\n",
                    timestamp_a, angle_a, angle_b, angular_position);

            if (write(fd, log_entry, sizeof(log_entry)) == -1) {
                perror("write");
                break;
            }
        }

        usleep(100000); // Adjust as needed for your application
    }

    close(fd);
    gpiod_channel_destroy(&ctx_a);
    gpiod_channel_destroy(&ctx_b);
    gpiod_button_destroy(&btn_a);
    gpiod_button_destroy(&btn_b);

    return 0;
}

