#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>
#include <signal.h>
#include <linux/gpio.h>
#include <linux/module.h>
#include <linux/kernel.h>
#include <linux/init.h>
#include <sys/epoll.h>
#include <sys/stat.h>
#include <fcntl.h>

#define GPIO_PIN 18
#define PULSE_COUNTER_FILE "rpm_log.txt"
#define MAX_RPM_VALUE 1000000
#define LOG_BUFFER_SIZE 1024

#define ERR_LOG_BUF_OPEN -1
#define ERR_GPIO_OPEN -2
#define ERR_MUTEX_INIT -3
#define ERR_ISR_REGISTER -4
#define ERR_LOG_FILE_OPEN -5

#define SIGNAL_HANDLER SIGINT

typedef struct {
    pthread_mutex_t pulse_mutex;
    long long rpm_counter;
    struct timespec last_timestamp;
    FILE *log_file;
} rpm_data;

static int gpio_fd;
static int epoll_fd;
static pthread_t isr_thread;
static rpm_data rpm_data_instance;

static int isr_handler(int signum, siginfo_t *info, void *context) {
    rpm_data_instance.rpm_counter = 0;
    rpm_data_instance.last_timestamp = current_time();
    return 0;
}

static int init_module(void) {
    int ret;

    ret = register_interrupt(ISR(SIGINT, isr_handler, NULL));
    if (ret < 0) {
        printk(KERN_ERR "Failed to register signal handler\n");
        return ret;
    }

    rpm_data_instance.rpm_counter = 0;
    rpm_data_instance.last_timestamp = current_time();

    rpm_data_instance.log_file = fopen(PULSE_COUNTER_FILE, "a");
    if (rpm_data_instance.log_file == NULL) {
        printk(KERN_ERR "Failed to open log file\n");
        return ERR_LOG_BUFFER_OPEN;
    }

    rpm_data_instance.pulse_mutex = pthread_mutex_init(NULL, NULL);
    if (rpm_data_instance.pulse_mutex == NULL) {
        printk(KERN_ERR "Failed to initialize mutex\n");
        return ERR_MUTEX_INIT;
    }

    ret = gpio_request(GPIO_PIN, "melexis_mlx90254");
    if (ret < 0) {
        printk(KERN_ERR "Failed to request GPIO pin\n");
        return ret;
    }

    ret = gpio_direction_input(GPIO_PIN);
    if (ret < 0) {
        printk(KERN_ERR "Failed to set GPIO pin direction\n");
        return ret;
    }

    ret = gpio_set_pull_up_down(GPIO_PIN, GPIO_PULL_DOWN);
    if (ret < 0) {
        printk(KERN_ERR "Failed to set pull-down resistor\n");
        return ret;
    }

    ret = epoll_ctl(epoll_fd, EPOLL_CTL_ADD, gpio_fd, &rpm_data_instance.epoll_event, 1);
    if (ret < 0) {
        printk(KERN_ERR "Failed to add GPIO pin to epoll\n");
        return ret;
    }

    return 0;
}

static void cleanup_module(void) {
    close(rpm_data_instance.log_file);
    pthread_mutex_destroy(rpm_data_instance.pulse_mutex);
    epoll_ctl(epoll_fd, EPOLL_CTL_DEL, gpio_fd, NULL, 1);
    close(epoll_fd);
    unregister_interrupt(ISR(SIGINT, isr_handler, NULL));

    if (rpm_data_instance.epoll_event.data.fd != -1) {
        close(rpm_data_instance.epoll_event.data.fd);
    }

    if (rpm_data_instance.isr_thread != THRESHOLD_NO_THREAD) {
        pthread_join(rpm_data_instance.isr_thread, NULL);
    }
}

static int handle_epoll_event(int fd, short event, void *data) {
    rpm_data_instance.epoll_event.data.fd = fd;
    rpm_data_instance.epoll_event.event = event;
    return 0;
}

static int main_isr_thread(void *arg) {
    int ret;
    rpm_data_instance.rpm_counter = 0;

    while (1) {
        ret = epoll_wait(epoll_fd, &rpm_data_instance.epoll_event, 1, -1);
        if (ret == -1) {
            printk(KERN_ERR "Error in epoll_wait\n");
            break;
        }

        if (rpm_data_instance.epoll_event.data.fd == gpio_fd) {
            ret = read(gpio_fd, &rpm_data_instance.pulse_mutex, sizeof(rpm_data_instance.pulse_mutex));
            if (ret == -1) {
                printk(KERN_ERR "Error reading from GPIO\n");
                break;
            }

            if (ret == 0) {
                printk(KERN_ERR "GPIO is not ready\n");
                break;
            }

            pthread_mutex_lock(&rpm_data_instance.pulse_mutex);
            rpm_data_instance.rpm_counter++;
            rpm_data_instance.last_timestamp = current_time();
            pthread_mutex_unlock(&rpm_data_instance.pulse_mutex);
        }
    }

    return 0;
}

static int main_thread(void) {
    int ret;

    rpm_data_instance.rpm_counter = 0;
    rpm_data_instance.last_timestamp = current_time();

    while (1) {
        ret = pthread_mutex_lock(&rpm_data_instance.pulse_mutex);
        if (ret != 0) {
            printk(KERN_ERR "Mutex lock failed\n");
            break;
        }

        double rpm = (rpm_data_instance.rpm_counter * 60.0) / rpm_data_instance.last_timestamp.tv_sec;
        if (rpm == 0.0) {
            printk(KERN_INFO "No pulses detected, logging 0.00 RPM\n");
        } else {
            printk(KERN_INFO "RPM: %.2f\n", rpm);
        }

        rpm_data_instance.rpm_counter = 0;
        rpm_data_instance.last_timestamp = current_time();

        ret = pthread_mutex_unlock(&rpm_data_instance.pulse_mutex);
        if (ret != 0) {
            printk(KERN_ERR "Mutex unlock failed\n");
            break;
        }

        usleep(1000000);
    }

    return 0;
}

static int __init rpm_module_init(void) {
    int ret;

    ret = init_module();
    if (ret) {
        printk(KERN_ERR "Module initialization failed\n");
        return ret;
    }

    signal(SIGNAL_HANDLER, SIG_IGN);
    signal(SIGINT, rpm_module_exit);
    signal(SIGTERM, rpm_module_exit);

    printk(KERN_INFO "RPM module loaded\n");
    return 0;
}

static void __exit rpm_module_exit(void) {
    cleanup_module();
    printk(KERN_INFO "RPM module unloaded\n");
}

module_init(rpm_module_init);
module_exit(rpm_module_exit);

