#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS "/dev/i2c-1"
#define LED_GPIO 17
#define SAMPLE_INTERVAL_MS 100
#define THRESHOLD 2000
#define LOG_FILE "adpd144ri_log.txt"

int i2c_fd;
piGPIO_handle handle;

void init_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, 0x50) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

void setup_gpio() {
    handle = piGPIO_open(LED_GPIO);
    if (!handle) {
        perror("Failed to open GPIO");
        exit(EXIT_FAILURE);
    }
    piGPIO_setMode(handle, PI_OUTPUT);
}

void log_reading(const char *timestamp) {
    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
    fprintf(file, "%s, %d\n", timestamp, get_sensor_reading());
    fclose(file);
}

int get_sensor_reading() {
    char buffer[6];
    ssize_t read_bytes = read(i2c_fd, buffer, sizeof(buffer));
    if (read_bytes < 0) {
        perror("Failed to read from I2C bus");
        return -1;
    }

    if (read_bytes == 0) {
        return -1; // Sensor not found
    }

    // Assuming the sensor returns a 16-bit value, split into high and low bytes
    uint16_t reading = (buffer[0] << 8) | buffer[1];
    return reading;
}

void check_threshold_and_trigger_led() {
    uint16_t reading = get_sensor_reading();
    if (reading > THRESHOLD) {
        piGPIO_write(handle, LED_GPIO, 1); // Turn on LED
    }
}

int main(int argc, char *argv[]) {
    piGPIO_init();

    init_i2c();
    setup_gpio();

    while (1) {
        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(NULL));
        log_reading(timestamp);
        check_threshold_and_trigger_led();
        usleep(SAMPLE_INTERVAL_MS * 1000 / 1000); // Convert ms to us
    }

    piGPIO_cleanup();
    close(i2c_fd);
    unlink(LOG_FILE); // Remove log file on exit
    exit(EXIT_SUCCESS);
}

