#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <libgpiod.h>

#define GPIO_OUT 18
#define GPIO_IN 17
#define SAMPLE_INTERVAL_MS 10
#define LOG_FILE "audio_log.txt"

void signal_handler(int signum) {
    printf("Received signal %d, exiting gracefully...\n", signum);
    exit(0);
}

int main() {
    pid_t pid;

    // Initialize libgpiod
    if (libgpiod_init(NULL) != 0) {
        perror("libgpiod_init failed");
        exit(EXIT_FAILURE);
    }

    // Set up GPIO pins
    if (libgpiod_gpio_set_mode(GPIO_OUT, GPIO_OUT) != 0) {
        perror("libgpiod_gpio_set_mode failed");
        exit(EXIT_FAILURE);
    }
    if (libgpiod_gpio_set_drive(GPIO_OUT, 0) != 0) {
        perror("libgpiod_gpio_set_drive failed");
        exit(EXIT_FAILURE);
    }

    if (libgpiod_gpio_set_mode(GPIO_IN, GPIO_IN) != 0) {
        perror("libgpiod_gpio_set_mode failed");
        exit(EXIT_FAILURE);
    }

    // Open the log file
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Start a new process group
    pid = fork();
    if (pid == 0) {
        // Child process
        // Close standard file descriptors
        close(STDIN_FILENO);
        close(STDOUT_FILENO);
        close(STDERR_FILENO);

        // Redirect stdout to the log file
        if (dup2(fileno(log_file), STDOUT_FILENO) == -1) {
            perror("dup2 failed");
            exit(EXIT_FAILURE);
        }

        // Redirect stderr to the log file
        if (dup2(fileno(log_file), STDERR_FILENO) == -1) {
            perror("dup2 failed");
            exit(EXIT_FAILURE);
        }

        // Run the main loop
        while (1) {
            // Read the state of GPIO18 (GAIN select pin)
            int gain_state = libgpiod_gpio_get_value(GPIO_OUT);

            // Set the gain to 60 dB
            if (gain_state == 0) {
                libgpiod_gpio_set_value(GPIO_OUT, 1);
            } else {
                libgpiod_gpio_set_value(GPIO_OUT, 0);
            }

            // Read the analog input from GPIO17 (OUT pin)
            int audio_level = libgpiod_gpio_get_value(GPIO_IN);

            // Check for rising edges
            if (audio_level == 1 && libgpiod_gpio_get_value(GPIO_IN) == 0) {
                // Log the event
                char timestamp[32];
                time_t now = time(NULL);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
                fprintf(log_file, "%s 1\n", timestamp);
                printf("Detected peak sound event: %s\n", timestamp);
            }

            // Sleep for the specified interval
            usleep(SAMPLE_INTERVAL_MS * 1000 / HRTIME_PER_SEC);
        }
    } else {
        // Parent process
        waitpid(pid, NULL, 0);
    }

    // Clean up libgpiod
    libgpiod_cleanup();

    return 0;
}

