#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SENSIRION_SLF3S_4000B_ADDRESS 0x28
#define LOG_FILE "flow_log.csv"
#define LOG_FORMAT "%Y-%m-%d %H:%M:%S,flow_rate_uL_min"
#define READ_INTERVAL 1000

#define CRC_POLYNOMIAL 0x07

// Function to validate CRC-8
unsigned char crc8(unsigned char crc, unsigned char data) {
    crc = crc ^ data;
    for (int i = 0; i < 8; i++) {
        if ((crc & 0x80) != 0) {
            crc = (crc << 1) ^ CRC_POLYNOMIAL;
        } else {
            crc = crc << 1;
        }
    }
    return crc;
}

// Function to read data from I2C
int read_i2c(int file, unsigned char *buffer, int count) {
    int ret = read(file, buffer, count);
    if (ret < 0) {
        perror("read_i2c");
        return -1;
    }
    return ret;
}

// Function to write data to I2C
int write_i2c(int file, const unsigned char *buffer, int count) {
    int ret = write(file, buffer, count);
    if (ret < 0) {
        perror("write_i2c");
        return -1;
    }
    return ret;
}

int main(int argc, char *argv[]) {
    int i2c_fd, log_fd;
    struct i2c_client i2c_client;
    unsigned char buffer[3];
    unsigned char crc;
    unsigned int raw_value;
    time_t now;
    struct tm *time_info;
    char log_entry[50];

    // Initialize pigpio
    if (pigpio_init() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open I2C bus
    i2c_fd = open(LOG_FILE, O_WRONLY | O_CREAT, 0644);
    if (i2c_fd < 0) {
        perror("open I2C file");
        return 1;
    }

    // Open I2C device
    memset(&i2c_client, 0, sizeof(i2c_client));
    i2c_client.device = SENSIRION_SLF3S_4000B_ADDRESS;
    i2c_client.bus = I2C_BUS;

    if (i2c_fd(i2c_fd, &i2c_client) < 0) {
        perror("i2c_fd");
        return 1;
    }

    // Read data from sensor
    while (1) {
        // Write command to read raw value
        if (write_i2c(i2c_fd, (unsigned char *)"READ\0", 2) < 0) {
            fprintf(stderr, "Failed to write command\n");
            continue;
        }

        // Read three bytes (MSB-first)
        if (read_i2c(i2c_fd, buffer, 3) < 0) {
            fprintf(stderr, "Failed to read data\n");
            continue;
        }

        // Validate CRC
        crc = buffer[2];
        for (int i = 0; i < 3; i++) {
            crc = crc8(crc, buffer[i]);
        }
        if (crc != 0x00) {
            fprintf(stderr, "CRC validation failed\n");
            continue;
        }

        // Extract raw value
        raw_value = (buffer[0] << 8) | buffer[1];

        // Convert raw value to flow rate (Sensirion documentation provides conversion factor)
        // Assuming 1 byte = 1000 units, and the conversion factor is provided in the documentation
        // For this example, let's assume 1000 units per byte
        unsigned int flow_rate_uL_min = raw_value * 1000;

        // Log the measurement
        now = time(NULL);
        time_info = localtime(&now);
        sprintf(log_entry, LOG_FORMAT, time_info->tm_year + 1900, time_info->tm_mon + 1, time_info->tm_mday,
                time_info->tm_hour, time_info->tm_min, time_info->tm_sec);
        if (write(i2c_fd, log_entry, strlen(log_entry)) < 0) {
            fprintf(stderr, "Failed to write to log file\n");
        }

        // Flush and close the log file after each write
        if (fflush(i2c_fd) < 0) {
            perror("fflush");
        }

        // Sleep before the next reading
        usleep(READ_INTERVAL * 1000);
    }

    // Clean up and exit
    close(i2c_fd);
    close(log_fd);
    pigpio_terminate(1000);

    return 0;
}

