#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <pthread.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x4B
#define LOG_FILE "air_quality_log.csv"
#define LOG_INTERVAL 5

typedef struct {
    int tco2;
    int tvoc;
} IAQ_DATA;

static int i2c_fd;
static IAQ_DATA iaq_data;
static FILE *log_file;
static pthread_t log_thread;

void i2c_init() {
    int file = open("/dev/i2c-1", O_RDWR);
    if (file < 0) {
        perror("open /dev/i2c-1");
        exit(EXIT_FAILURE);
    }

    if (ioctl(file, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(file);
        exit(EXIT_FAILURE);
    }

    i2c_fd = file;
}

void i2c_close() {
    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

void sigint_handler(int signum) {
    printf("Received SIGINT, cleaning up...\n");
    i2c_close();
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    exit(EXIT_SUCCESS);
}

void *log_thread_func(void *arg) {
    while (1) {
        sleep(LOG_INTERVAL);
        iaq_data.tco2 = read_tco2();
        iaq_data.tvoc = read_tvoc();
        if (log_file != NULL) {
            if (fputs(std::to_string(iaq_data.tco2) + "," + std::to_string(iaq_data.tvoc) + "\n", log_file) < 0) {
                perror("log_thread_func: Failed to write to log file");
                exit(EXIT_FAILURE);
            }
        }
    }
}

int read_tco2() {
    char command[2] = {0x43, 0x00}; // Read TCO2 register
    write(i2c_fd, command, 2);
    if (read(i2c_fd, &iaq_data.tco2, 1) != 1) {
        perror("read_tco2: Failed to read TCO2");
        return -1;
    }
    return iaq_data.tco2;
}

int read_tvoc() {
    char command[2] = {0x44, 0x00}; // Read TVOC register
    write(i2c_fd, command, 2);
    if (read(i2c_fd, &iaq_data.tvoc, 1) != 1) {
        perror("read_tvoc: Failed to read TVOC");
        return -1;
    }
    return iaq_data.tvoc;
}

int main() {
    signal(SIGINT, sigint_handler);

    i2c_init();

    if (log_file = fopen(LOG_FILE, "a")) {
        pthread_t thread = pthread_create(&log_thread, NULL, log_thread_func, NULL);
        if (thread != NULL) {
            pthread_join(thread, NULL);
        }
        fclose(log_file);
    }

    i2c_close();

    return 0;
}

