#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>
#include <linux/gpio-edged.h>

#define TTP223_PIN 11
#define POLL_INTERVAL_MS 100
#define INTRUSION_THRESHOLD_SEC 5

int main(int argc, char *argv[]) {
    int fd;
    struct timespec timeout;
    long long start_time;
    int ttp223_state;

    fd = open("/dev/gpiochip", O_RDWR);
    if (fd < 0) {
        perror("open /dev/gpiochip");
        exit(EXIT_FAILURE);
    }

    timeout.tv_sec = 0;
    timeout.tv_nsec = 0;

    start_time = clock64();

    while (1) {
        timeout.tv_sec = INTRUSION_THRESHOLD_SEC * 1000;
        timeout.tv_nsec = 0;

        if (ioctl(fd, GPIOPOLL, &timeout) < 0) {
            perror("ioctl GPIOPOLL");
            exit(EXIT_FAILURE);
        }

        for (int i = 0; i < 2; ++i) {
            ttp223_state = read(fd, &ttp223_pin);
            if (ttp223_state < 0) {
                perror("read from /dev/gpiochip");
                exit(EXIT_FAILURE);
            }

            if (ttp223_state & GPIO_INPUT_HIGH) {
                if (start_time == 0) {
                    start_time = clock64();
                }

                long long elapsed = clock64() - start_time;
                if (elapsed > INTRUSION_THRESHOLD_SEC * 1000 * 1000) {
                    printf("Intrusion detected!\n");
                    start_time = 0;
                }
            }
        }
    }

    close(fd);
    return 0;
}

