#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <errno.h>
#include <libgpiod.h>

#define GPIO_SENSOR 4
#define GPIO_FAN 18
#define DEBOUNCE_TIME 50
#define FAN_FREQ 100
#define LOG_FILE "flame_log.txt"
#define LOG_FORMAT "%Y-%m-%dT%H:%M:%S"

void signal_handler(int signum) {
    printf("Received signal %d, shutting down...\n", signum);
    gpio_output_set(GPIO_FAN, 0);
    gpio_output_set(GPIO_SENSOR, 0);
    close(logfd);
    exit(0);
}

int main(int argc, char *argv[]) {
    int logfd;
    struct stat sb;
    char timestamp[20];

    // Initialize libgpiod
    if (libgpiod_init() < 0) {
        perror("libgpiod_init");
        return EXIT_FAILURE;
    }

    // Open log file
    logfd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (logfd == -1) {
        perror("open");
        return EXIT_FAILURE;
    }

    // Initialize GPIO
    if (libgpiod_gpio_init(GPIO_SENSOR) < 0) {
        perror("libgpiod_gpio_init");
        return EXIT_FAILURE;
    }

    // Set GPIO4 as input with pull-up
    if (libgpiod_gpio_direction_input_with_pullup(GPIO_SENSOR) < 0) {
        perror("libgpiod_gpio_direction_input_with_pullup");
        return EXIT_FAILURE;
    }

    // Set GPIO18 as output
    if (libgpiod_gpio_output_init(GPIO_FAN) < 0) {
        perror("libgpiod_gpio_output_init");
        return EXIT_FAILURE;
    }

    // Set PWM frequency
    if (libgpiod_gpio_pwm_frequency_set(GPIO_FAN, FAN_FREQ) < 0) {
        perror("libgpiod_gpio_pwm_frequency_set");
        return EXIT_FAILURE;
    }

    // Initialize debounce timer
    clock_gettime(CLOCK_REALTIME, &start_time);
    int debounce_count = 0;
    while (1) {
        // Read sensor input
        int sensor_state = lbgpiod_gpio_read(GPIO_SENSOR);
        if (sensor_state == -1) {
            perror("lbgpiod_gpio_read");
            break;
        }

        // Debounce
        if (debounce_count < DEBOUNCE_TIME) {
            debounce_count++;
            usleep(1000 / DEBOUNCE_TIME);
        } else {
            debounce_count = 0;
        }

        // Check for flame detection
        if (sensor_state == 0) {
            // Log flame detection
            time_t now = time(NULL);
            strftime(timestamp, sizeof(timestamp), LOG_FORMAT, &now);
            fprintf(logfd, "%s, Flame Detected\n", timestamp);

            // Start PWM for fan
            lbgpiod_gpio_pwm_set_level(GPIO_FAN, 1);
            usleep(1000 / FAN_FREQ); // Wait for PWM cycle
            lbgpiod_gpio_pwm_set_level(GPIO_FAN, 0);

            // Log flame end
            fprintf(logfd, "%s, Flame End\n", timestamp);
        }

        // Sleep for 50ms
        usleep(50000);
    }

    // Clean up
    gpio_output_set(GPIO_FAN, 0);
    gpio_output_set(GPIO_SENSOR, 0);
    close(logfd);
    lbgpiod_gpio_cleanup(GPIO_SENSOR);
    lbgpiod_gpio_cleanup(GPIO_FAN);
    lbgpiod_cleanup();

    // Handle SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    return EXIT_SUCCESS;
}

