#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>

#define GPIO_PIN 20
#define POLL_INTERVAL_MS 100
#define FLAME_LOG_FILE "flame_log.txt"

typedef struct {
    int file;
    char timestamp[32];
} LogEntry;

static int gpio_fd;
static LogEntry *log_entries = NULL;
static int log_entries_count = 0;

void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        close(gpio_fd);
        exit(0);
    }
}

void init_gpio() {
    int ret;

    gpio_fd = open(FLAME_LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (gpio_fd == -1) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    ret = ioctl(gpio_fd, GPIOPINGET, &GPIO_PIN);
    if (ret < 0) {
        perror("ioctl");
        close(gpio_fd);
        exit(EXIT_FAILURE);
    }

    ret = ioctl(gpio_fd, GPIOPULLUP, &GPIO_UP);
    if (ret < 0) {
        perror("ioctl");
        close(gpio_fd);
        exit(EXIT_FAILURE);
    }
}

void cleanup() {
    if (log_entries) {
        for (LogEntry *entry = log_entries; entry != NULL; entry++) {
            write(gpio_fd, entry->timestamp, strlen(entry->timestamp));
            write(gpio_fd, "\n", 1);
            free(entry);
        }
        free(log_entries);
    }
    close(gpio_fd);
}

void process_sensor_data() {
    int current_state = -1;
    int last_state = -1;

    while (1) {
        int ret = read(gpio_fd, &current_state, 1);
        if (ret < 0) {
            perror("read");
            break;
        }

        if (current_state != last_state) {
            if (last_state == 0) {
                sprintf(log_entries[log_entries_count].timestamp, "%s000", ctime(nullptr));
            } else {
                sprintf(log_entries[log_entries_count].timestamp, "%s100", ctime(nullptr));
            }
            log_entries_count++;
            last_state = current_state;
        }

        usleep(POLL_INTERVAL_MS * 1000 / HRTIME_PER_SEC);
    }
}

int main(int argc, char *argv[]) {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    init_gpio();

    process_sensor_data();

    cleanup();

    return 0;
}

