#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS 1
#define OPT3001_ADDRESS 0x5A
#define CONVERSION_TIME_MS 100
#define LOG_FILE "light_data.txt"

#define BUFFER_SIZE 1024
char buffer[BUFFER_SIZE];

int i2c_fd;

void init_i2c() {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }
}

void close_i2c() {
    close(i2c_fd);
}

int opt3001_read(uint8_t reg) {
    char command[3] = {0x40, reg, 0x00};
    ssize_t bytes_read = write(i2c_fd, command, 3);
    if (bytes_read != 3) {
        perror("Failed to write to I2C device");
        return -1;
    }

    bytes_read = read(i2c_fd, buffer, BUFFER_SIZE);
    if (bytes_read < 0) {
        perror("Failed to read from I2C device");
        return -1;
    }

    if (bytes_read == 0) {
        return -1; // Sensor not found
    }

    return bytes_read;
}

int main(int argc, char *argv[]) {
    init_i2c();

    pigpio_init(5); // Initialize pigpio with 5 seconds timeout

    while (1) {
        int lux_value = opt3001_read(0x28); // Read lux value from register 0x28

        if (lux_value < 0) {
            fprintf(stderr, "Error reading from OPT3001\n");
            continue;
        }

        // Append timestamp and lux value to the file
        time_t now = time(NULL);
        struct tm *local_time = localtime(&now);
        strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%SZ", local_time);
        strcat(buffer, ".");
        strcat(buffer, (char *) &lux_value);

        FILE *file = fopen(LOG_FILE, "a");
        if (!file) {
            perror("Failed to open file for appending");
            continue;
        }

        if (fputs(buffer, file) == EOF) {
            perror("Failed to write to file");
            fclose(file);
            continue;
        }

        fclose(file);
    }

    close_i2c();
    pigpio_terminate(1000); // Terminate pigpio with 1 second timeout
    return 0;
}

