#include <signal.h>
#include <stdbool.h>
#include <libgpiod.h>

#define GPIO_LINE 17
#define IR_SENSOR_PIN 0

volatile sig_atomic_t quit = 0;

void signal_handler(int signum) {
    global_signal_set(SIGINT, signum);
    quit = 1;
}

int main() {
    int ret;

    // Initialize gpiod
    ret = gpiod_init();
    if (ret < 0) {
        perror("Failed to initialize gpiod");
        exit(EXIT_FAILURE);
    }

    // Set up GPIO line as input with pull-up
    ret = gpiod_gpio_request(GPIO_LINE, "flame_sensor");
    if (ret < 0) {
        perror("Failed to request GPIO line");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_edge_detect_config_default(GPIO_LINE, GPIOD_EDGE_FALLING);
    if (ret < 0) {
        perror("Failed to configure edge detection");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_gpio_edge_detect_enable(GPIO_LINE);
    if (ret < 0) {
        perror("Failed to enable edge detection");
        exit(EXIT_FAILURE);
    }

    // Install signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!quit) {
        int sensor_value = gpiod_get_value(GPIO_LINE);

        if (sensor_value == 0) {
            printf("YYYY-MM-DD HH:MM:SS\tFlame Detected: YES\n");
        } else {
            printf("YYYY-MM-DD HH:MM:SS\tFlame Detected: NO\n");
        }

        usleep(1000000); // Sleep for 1 second
    }

    // Cleanup
    gpiod_gpio_disable(GPIO_LINE);
    gpiod_gpio_request_remove(GPIO_LINE);
    gpiod_cleanup();

    return 0;
}

