#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define LEFT_PIN 17
#define CENTER_PIN 18
#define RIGHT_PIN 27

int main(int argc, char *argv[]) {
    gpiod_context_t ctx;
    gpiod_button_t buttons[3];

    if (signal(SIGINT, signal_handler) == SIG_IGN || signal(SIGTERM, signal_handler) == SIG_IGN) {
        perror("Failed to register signal handlers");
        exit(EXIT_FAILURE);
    }

    if (gpiod_init() < 0) {
        perror("Failed to initialize gpiod");
        exit(EXIT_FAILURE);
    }

    if (gpiod_button_init(&ctx, 3, buttons) < 0) {
        perror("Failed to initialize button pins");
        exit(EXIT_FAILURE);
    }

    if (gpiod_button_add_edge(buttons, LEFT_PIN, GPIO_INPUT) < 0) {
        perror("Failed to add left button");
        exit(EXIT_FAILURE);
    }

    if (gpiod_button_add_edge(buttons, CENTER_PIN, GPIO_INPUT) < 0) {
        perror("Failed to add center button");
        exit(EXIT_FAILURE);
    }

    if (gpiod_button_add_edge(buttons, RIGHT_PIN, GPIO_INPUT) < 0) {
        perror("Failed to add right button");
        exit(EXIT_FAILURE);
    }

    while (1) {
        int left_state = gpiod_get_value(&ctx, buttons, LEFT_PIN);
        int center_state = gpiod_get_value(&ctx, buttons, CENTER_PIN);
        int right_state = gpiod_get_value(&ctx, buttons, RIGHT_PIN);

        printf("Left: %d, Center: %d, Right: %d\n", left_state, center_state, right_state);
        usleep(50000); // Sleep for 50ms
    }

    gpiod_button_del(&ctx, buttons, LEFT_PIN);
    gpiod_button_del(&ctx, buttons, CENTER_PIN);
    gpiod_button_del(&ctx, buttons, RIGHT_PIN);
    gpiod_cleanup(&ctx);

    return 0;
