#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <string.h>
#include <libgpiod/libgpiod.h>

#define SAMPLING_INTERVAL_US 100000
#define TOUCH_SENSOR_PINS {2, 3, 4, 5, 6, 7, 8, 9}

void signal_handler(int signum) {
    printf("Received signal %d, exiting gracefully...\n", signum);
    gpiod_disable();
    exit(0);
}

int main() {
    struct gpiod_descriptor desc;
    int ret;

    // Initialize libgpiod
    ret = gpiod_init();
    if (ret < 0) {
        fprintf(stderr, "Failed to initialize libgpiod: %s\n", gpiod_strerror(ret));
        exit(EXIT_FAILURE);
    }

    // Configure touch sensor pins as inputs with pull-down
    for (int i = 0; i < sizeof(TOUCH_SENSOR_PINS) / sizeof(TOUCH_SENSOR_PINS[0]); i++) {
        desc.mode = GPIOD_MODE_INPUT;
        desc.pull = GPIOD_PULL_DOWN;
        desc.pin_num = TOUCH_SENSOR_PINS[i];
        ret = gpiod_descriptor_add(&desc);
        if (ret < 0) {
            fprintf(stderr, "Failed to add pin %d: %s\n", TOUCH_SENSOR_PINS[i], gpiod_strerror(ret));
            exit(EXIT_FAILURE);
        }
    }

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Read and print sensor data in a loop
    while (1) {
        ret = gpiod_get_all_values(&desc);
        if (ret < 0) {
            fprintf(stderr, "Failed to read GPIO values: %s\n", gpiod_strerror(ret));
            continue;
        }

        printf("Sampling interval: %lu us\n", SAMPLING_INTERVAL_US / 1000);
        for (int i = 0; i < sizeof(TOUCH_SENSOR_PINS) / sizeof(TOUCH_SENSOR_PINS[0]); i++) {
            printf("[+%lu ms] CH%d=%d\n", (unsigned long)(SAMPLING_INTERVAL_US / 1000000), i + 1, ret.values.bit_field[i]);
        }
        usleep(SAMPLING_INTERVAL_US / 1000);
    }

    // Clean up and exit
    gpiod_disable();
    return EXIT_SUCCESS;
}

