#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define TTP_PINS {2, 3, 4, 17, 27, 22, 10, 9}
#define POLL_INTERVAL_MS 50

void sigint_handler(int signum) {
    printf("\nGracefully shutting down...\n");
    pigpio_stop();
    exit(0);
}

int main() {
    int fd, ret;
    struct i2c_client *client;
    char timestamp[32];
    int sensor_states[8];

    signal(SIGINT, sigint_handler);

    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Failed to open i2c bus");
        exit(EXIT_FAILURE);
    }

    ret = ioctl(fd, I2C_SLAVE, 0x20);
    if (ret < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        exit(EXIT_FAILURE);
    }

    client = i2c_alloc(fd);
    if (!client) {
        perror("Failed to allocate i2c client");
        close(fd);
        exit(EXIT_FAILURE);
    }

    while (1) {
        memset(sensor_states, 0, sizeof(sensor_states));

        ret = i2c_transfer(client, 0x20, 0x00, 8, sensor_states);
        if (ret < 0) {
            perror("Failed to read from TTP226");
            usleep(POLL_INTERVAL_MS * 1000 / 50);
            continue;
        }

        strftime(timestamp, sizeof(timestamp), "%Y-%m-%T", localtime(NULL));
        printf("%s: ", timestamp);

        for (int i = 0; i < 8; i++) {
            printf("%d ", sensor_states[i] ? 1 : 0);
        }
        printf("\n");

        usleep(POLL_INTERVAL_MS * 1000 / 50);
    }

    i2c_free(client);
    close(fd);
    return 0;
}

