#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <libgpiod/gpio.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <i2c-dev.h>

#define I2C_BUS 1
#define I2C_ADDR 0x77  // Silicon Labs Si1145
#define LOG_FILE "uv_als_log.csv"
#define SAMPLE_INTERVAL 1000  // in milliseconds

// Silicon Labs Si1145 register addresses
#define UV_INDEX_REG 0x00
#define ALS_VISIBLE_REG 0x01

// Function to read data from I2C device
int read_i2c_device(int file_descriptor, unsigned char *reg_address, unsigned char *data) {
    int read_bytes;
    read(file_descriptor, data, 1);
    if (read(file_descriptor, data + 1, 1) != 1) {
        return -1;
    }
    return 0;
}

// Function to write data to I2C device
int write_i2c_device(int file_descriptor, unsigned char *reg_address, unsigned char *data) {
    return write(file_descriptor, data, 1);
}

// Function to initialize I2C communication
int init_i2c(int bus, int address) {
    int file_descriptor = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (file_descriptor < 0) {
        perror("Error opening log file");
        return -1;
    }

    if (ioctl(file_descriptor, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        close(file_descriptor);
        return -1;
    }

    int i2c_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        close(file_descriptor);
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        close(file_descriptor);
        return -1;
    }

    return i2c_fd;
}

// Function to read UV index and ALS visible light
int read_sensor_data(int i2c_fd) {
    unsigned char uv_index, als_visible;

    read_i2c_device(i2c_fd, UV_INDEX_REG, &uv_index);
    read_i2c_device(i2c_fd, ALS_VISIBLE_REG, &als_visible);

    return uv_index;
}

// Function to log sensor data
void log_sensor_data(int i2c_fd, int uv_index, int als_visible) {
    char timestamp[32];
    time_t now = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        return;
    }

    fprintf(log_file, "%s, %d, %d\n", timestamp, uv_index, als_visible);
    fclose(log_file);
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signum) {
    printf("Received signal %d, shutting down...\n", signum);
    close(log_file);
    close(i2c_fd);
    exit(signum == SIGINT ? 0 : 1);
}

int main() {
    sigset_t sigset;
    memset(&sigset, 0, sizeof(sigset));
    sigaddset(&sigset, SIGINT);
    sigaddset(&sigset, SIGTERM);
