#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <string.h>
#include <time.h>
#include <libgpiod.h>

#define BUFFER_SIZE 100
#define SAMPLE_INTERVAL_MS 50
#define SENSOR_PIN 7

typedef struct {
    time_t timestamp;
    int state;
} BufferEntry;

BufferEntry buffer[BUFFER_SIZE];
int head = 0;
int tail = 0;

void signal_handler(int signum) {
    printf("Received SIGINT, releasing resources and dumping buffer.\n");
    gpiod_disable(SENSOR_PIN);
    for (int i = tail; i < BUFFER_SIZE; i++) {
        if (buffer[i].state) {
            printf("Detection at %llu: %d\n", buffer[i].timestamp, buffer[i].state);
        }
    }
    for (int i = 0; i < BUFFER_SIZE; i++) {
        buffer[i] = (BufferEntry){0, 0};
    }
    head = tail;
    tail = 0;
    exit(0);
}

int main() {
    int ret;

    ret = gpiod_device_init();
    if (ret < 0) {
        fprintf(stderr, "Failed to initialize gpiod: %s\n", gpiod_strerror(ret));
        exit(EXIT_FAILURE);
    }

    ret = gpiod_device_enable(SENSOR_PIN);
    if (ret < 0) {
        fprintf(stderr, "Failed to enable GPIO pin %d: %s\n", SENSOR_PIN, gpiod_strerror(ret));
        exit(EXIT_FAILURE);
    }

    ret = gpiod_edge_output_init(SENSOR_PIN, GPIOD_OUTPUT_HIGH);
    if (ret < 0) {
        fprintf(stderr, "Failed to initialize edge output on GPIO %d: %s\n", SENSOR_PIN, gpiod_strerror(ret));
        exit(EXIT_FAILURE);
    }

    struct itimerspec timerspec;
    timerspec.timerspec_sec = 0;
    timerspec.timerspec_nsec = SAMPLE_INTERVAL_MS / 1000;

    signal(SIGINT, signal_handler);

    while (1) {
        ret = gpiod_edge_output_get_value(SENSOR_PIN, &buffer[tail].timestamp, &buffer[tail].state);
        if (ret < 0) {
            fprintf(stderr, "Failed to read GPIO %d: %s\n", SENSOR_PIN, gpiod_strerror(ret));
            break;
        }

        tail = (tail + 1) % BUFFER_SIZE;

        if (buffer[head].state) {
            // Handle potential race condition if detection happens during read
            while (tail >= head) {
                if (buffer[head].state) {
                    printf("Detection at %llu: %d\n", buffer[head].timestamp, buffer[head].state);
                    buffer[head] = (BufferEntry){0, 0};
                    head = (head + 1) % BUFFER_SIZE;
                } else {
                    break;
                }
            }
        }

        usleep(timerspec.timerspec_sec * 1000000 + timerspec.timerspec_nsec / 1000);
    }

    gpiod_device_disable(SENSOR_PIN);
    gpiod_edge_output_disable(SENSOR_PIN);
    gpiod_device_uninit();

    return EXIT_SUCCESS;
}

