#include <unistd.h>
#include <signal.h>
#include <string.h>
#include <errno.h>
#include <pigpio.h>

#define SENSOR1_GPIO 23
#define SENSOR2_GPIO 24
#define LED_GPIO 25

int main(int argc, char *argv[]) {
    pigpio_init(5); // Initialize pigpio with 5-second timeout

    if (pigpio_init(5) != 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", strerror(errno));
        return 1;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT); // Set GPIO25 as output
    gpioSetMode(SENSOR1_GPIO, PI_INPUT); // Set GPIO23 as input for sensor 1
    gpioSetMode(SENSOR2_GPIO, PI_INPUT); // Set GPIO24 as input for sensor 2

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO25 as output: %s\n", strerror(errno));
        pigpio_terminate(1000); // Terminate pigpio with 1 second timeout
        return 1;
    }

    if (gpioSetup(SENSOR1_GPIO, PI_PULLUP) != 0) {
        fprintf(stderr, "Failed to set pull-up resistor on GPIO23: %s\n", strerror(errno));
        pigpio_terminate(1000);
        return 1;
    }

    if (gpioSetup(SENSOR2_GPIO, PI_PULLUP) != 0) {
        fprintf(stderr, "Failed to set pull-up resistor on GPIO24: %s\n", strerror(errno));
        pigpio_terminate(1000);
        return 1;
    }

    while (1) {
        int sensor1 = gpioRead(SENSOR1_GPIO);
        int sensor2 = gpioRead(SENSOR2_GPIO);

        if (sensor1 == PI_INPUT_LOW || sensor2 == PI_INPUT_LOW) {
            gpioWrite(LED_GPIO, PI_OUTPUT); // Turn LED on
            printf("Obstacle detected on sensor 1 or 2\n");
        } else {
            gpioWrite(LED_GPIO, PI_OUTPUT_OFF); // Turn LED off
            printf("No obstacle detected, both sensors are HIGH\n");
        }

        usleep(100000); // Sleep for 100ms
    }

    pigpio_terminate(1000); // Terminate pigpio with 1 second timeout
    return 0;
}

// Signal handlers for SIGINT and SIGTERM
void signal_handler(int signum) {
    printf("Received signal %d, shutting down...\n", signum);
    pigpio_terminate(1000); // Terminate pigpio with 1 second timeout
}

int main(int argc, char *argv[]) {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Rest of the main function as shown above

    return 0;
}

