#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <errno.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_SENSOR1 17
#define GPIO_SENSOR2 18
#define STALL_TIMEOUT_SEC 2
#define LOG_FILE "stall_log.txt"

int sensor1_fd;
int sensor2_fd;

void signal_handler(int signum) {
    printf("Received signal %d, exiting gracefully...\n", signum);
    close(sensor1_fd);
    close(sensor2_fd);
    exit(0);
}

void setup_gpio(void) {
    int ret;

    ret = gpiod_resource_init(NULL, 1);
    if (ret < 0) {
        perror("Failed to initialize gpiod");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_resource_create_phys_file_gpio(NULL, GPIO_SENSOR1, GPIOD_MODE_INPUT, NULL);
    if (ret < 0) {
        perror("Failed to create GPIO17 resource");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_resource_create_phys_file_gpio(NULL, GPIO_SENSOR2, GPIOD_MODE_INPUT, NULL);
    if (ret < 0) {
        perror("Failed to create GPIO18 resource");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_resource_enable(GPIO_SENSOR1);
    if (ret < 0) {
        perror("Failed to enable GPIO17");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_resource_enable(GPIO_SENSOR2);
    if (ret < 0) {
        perror("Failed to enable GPIO18");
        exit(EXIT_FAILURE);
    }
}

void read_sensors(void) {
    static unsigned long last_stall_time = 0;
    unsigned long current_time = micros();

    if (current_time - last_stall_time >= STALL_TIMEOUT_SEC * 1000000) {
        if (gpio_get_level(GPIO_SENSOR1) == GPIOD_INPUT_LOW && gpio_get_level(GPIO_SENSOR2) == GPIOD_INPUT_LOW) {
            printf("Stall detected at %llu\n", current_time);
            FILE *log_file = fopen(LOG_FILE, "a");
            if (log_file == NULL) {
                perror("Failed to open stall_log.txt for appending");
                return;
            }

            char timestamp[32];
            time_t now = current_time / 1000000;
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
            fprintf(log_file, "%s: %s\n", timestamp, (gpio_get_level(GPIO_SENSOR1) == GPIOD_INPUT_LOW && gpio_get_level(GPIO_SENSOR2) == GPIOD_INPUT_LOW) ? "Stall" : "No Stall");
            fclose(log_file);
        }
        last_stall_time = current_time;
    }
}

int main(int argc, char *argv[]) {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    setup_gpio();

    sensor1_fd = open(GPIO_SENSOR1, O_RDONLY | O_NONBLOCK);
    if (sensor1_fd < 0) {
        perror("Failed to open GPIO17");
        return EXIT_FAILURE;
    }

    sensor2_fd = open(GPIO_SENSOR2, O_RDONLY | O_NONBLOCK);
    if (sensor2_fd < 0) {
        perror("Failed to open GPIO18");
        close(sensor1_fd);
        return EXIT_FAILURE;
    }

    while (1) {
        read_sensors();
        usleep(100000); // Check every second
    }

    close(sensor1_fd);
    close(sensor2_fd);
    return EXIT_SUCCESS;
}

