#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <libgpiod.h>

#define SEN0193_PIN 23
#define POLL_INTERVAL_SEC 2.0
#define REINIT_DELAY_SEC 60.0
#define LOG_FILE "flood_log.txt"

void signal_handler(int signum) {
    printf("Received signal %d, cleaning up and exiting.\n", signum);
    close(LOG_FILE);
    exit(0);
}

int main() {
    struct sigaction sa;
    sigfillset(&sa.sa_mask);
    sa.sa_handler = signal_handler;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    gpiod_context ctx;
    int ret = gpiod_context_init(&ctx);
    if (ret < 0) {
        perror("gpiod_context_init");
        exit(EXIT_FAILURE);
    }

    gpiod_direction_output(ctx, SEN0193_PIN);
    gpiod_output_t output;
    ret = gpiod_output_get(ctx, SEN0193_PIN, &output);
    if (ret < 0) {
        perror("gpiod_output_get");
        exit(EXIT_FAILURE);
    }

    while (1) {
        ret = gpiod_event_wait(&ctx, &output);
        if (ret < 0) {
            perror("gpiod_event_wait");
            fprintf(stderr, "Error: %s\n", gpiod_strerror(ret));
            // Re-initialize after 60 seconds
            struct timespec reinit_ts = {REINIT_DELAY_SEC, 0};
            nanosleep(&reinit_ts, NULL);
            continue;
        }

        if (output) {
            printf("ALERT: Water detected at %d\n", gettimeofday(&ret->timestamp));
            FILE *log_file = fopen(LOG_FILE, "a");
            if (!log_file) {
                perror("fopen");
                exit(EXIT_FAILURE);
            }
            fprintf(log_file, "%s", "ALERT: Water detected\n");
            fclose(log_file);
        }

        // Keep the line low when dry
        gpiod_output_set(ctx, SEN0193_PIN, 0);
        usleep(100000); // Poll interval
    }

    return 0;
}

