#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <libgpgid.h>
#include <pigpio.h>

#define SENSOR_PIN 4
#define LOG_FILE "rpm_log.txt"
#define SAMPLE_INTERVAL 1000  // in milliseconds

int main(int argc, char *argv[]) {
    int gpio_pin = SENSOR_PIN;
    int gpio_mode = GPIO_MODE_INPUT;
    int gpio_pullup = GPIO_PULLUP_ENABLE;
    int pulse_count = 0;
    long long rpm = 0;
    struct tm now;
    char log_line[64];

    if (pigpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio library\n");
        exit(EXIT_FAILURE);
    }

    if (gpioSetup(gpio_pin, gpio_mode, gpio_pullup) < 0) {
        fprintf(stderr, "Failed to configure GPIO pin %d\n", gpio_pin);
        pigpioTerminate();
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, signalHandler);
    signal(SIGTERM, signalHandler);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        pigpioTerminate();
        exit(EXIT_FAILURE);
    }

    while (1) {
        if (gpioChange(gpio_pin, GPIO_INPUT) < 0) {
            fprintf(stderr, "Failed to change GPIO pin %d to input\n", gpio_pin);
            fclose(log_file);
            pigpioTerminate();
            exit(EXIT_FAILURE);
        }

        if (gpioRead(gpio_pin) == GPIO_INPUT_HIGH) {
            pulse_count++;
        }

        if (pulse_count > 1000) {
            rpm = (pulse_count * 60) / SAMPLE_INTERVAL;
            pulse_count = 0;

            if (rpm > 0) {
                sprintf(log_line, "%ld", rpm);
                strftime(now, sizeof(now), "%Y-%m-%d %H:%M:%S", localtime(&now.tm_time));
                fprintf(log_file, "%s %s\n", log_line, strerror(errno));
                fprintf(stdout, "%s %s\n", log_line, strerror(errno));
            } else {
                sprintf(log_line, "0");
                strftime(now, sizeof(now), "%Y-%m-%d %H:%M:%S", localtime(&now.tm_time));
                fprintf(log_file, "%s %s\n", log_line, strerror(errno));
                fprintf(stdout, "%s %s\n", log_line, strerror(errno));
            }
        }

        usleep(SAMPLE_INTERVAL * 1000 / HRTIME_PER_SEC);
    }

    fclose(log_file);
    pigpioTerminate();
    return 0;
}

void signalHandler(int signum) {
    gpioChange(SENSOR_PIN, GPIO_OUTPUT);
    gpioWrite(SENSOR_PIN, GPIO_LOW);
    fclose(stdout);
    fclose(stderr);
    pigpioTerminate();
}

