#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>
#include <linux/gpio-src.h>
#include <syslog.h>
#include <signal.h>

#define SENSOR_PIN 23
#define LED_PIN 18
#define POLL_INTERVAL 50

void log_startup(const char *msg) {
    syslog(LOG_INFO, "%s", msg);
}

void log_shutdown(const char *msg) {
    syslog(LOG_INFO, "%s", msg);
}

void log_touch_event(const char *msg) {
    syslog(LOG_INFO, "%s", msg);
}

void log_error(const char *msg) {
    syslog(LOG_ERR, "%s", msg);
}

void sigint_handler(int sig) {
    log_shutdown("Received SIGINT, performing graceful shutdown");
    turn_off_led();
    close_gpio_chip();
    exit(0);
}

void sigterm_handler(int sig) {
    log_shutdown("Received SIGTERM, performing graceful shutdown");
    turn_off_led();
    close_gpio_chip();
    exit(0);
}

int main() {
    log_startup("Starting TTP223B touch sensor monitoring program");

    int sensor_fd, led_fd;
    struct gpio_info info;

    log_touch_event("Initializing GPIO");
    sensor_fd = open("/dev/gpiochip", O_RDWR);
    if (sensor_fd == -1) {
        log_error("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    log_touch_event("Initializing LED");
    led_fd = open("/dev/mem", O_RDWR | O_SYNC);
    if (led_fd == -1) {
        close_gpio_chip(sensor_fd);
        log_error("Failed to open LED");
        exit(EXIT_FAILURE);
    }

    log_touch_event("Requesting GPIO chip info");
    if (ioctl(sensor_fd, GPIOD_GETINFO, &info) == -1) {
        close_gpio_chip(sensor_fd);
        log_error("Failed to get GPIO chip info");
        exit(EXIT_FAILURE);
    }

    log_touch_event("Requesting LED address");
    unsigned long led_address = info.gpio_base + LED_PIN;

    log_touch_event("Setting up GPIO for LED");
    if (ioctl(led_fd, WRITE, led_address) == -1) {
        close_gpio_chip(sensor_fd);
        log_error("Failed to set up LED");
        exit(EXIT_FAILURE);
    }

    log_touch_event("Setting up GPIO for sensor");
    if (ioctl(sensor_fd, GPIOD_SETDIR(GPIO_IN), GPIO_IN) == -1) {
        close_gpio_chip(led_fd);
        log_error("Failed to set GPIO for sensor");
        exit(EXIT_FAILURE);
    }

    log_touch_event("Setting up GPIO interrupt");
    if (ioctl(sensor_fd, GPIOD_SETINT(GPIO_INPUT, GPIO_PIN(SENSOR_PIN), GPIO_DIR_INPUT, GPIO_PIN(SENSOR_PIN), 0)) == -1) {
        close_gpio_chip(led_fd);
        log_error("Failed to set GPIO interrupt");
        exit(EXIT_FAILURE);
    }

    log_touch_event("Setting up GPIO output");
