#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <string.h>
#include <errno.h>
#include <pigpio.h>

#define GPIO_LED 18
#define GPIO_TOUCH 17
#define DEBOUNCE_MS 50

void touch_event_handler(const struct gpio_vec_event *e) {
    if (e->type == GPIO_RISING) {
        gpioToggleLED();
    }
}

void gpioToggleLED() {
    gpioSetMode(GPIO_LED, GPIO_OUTPUT);
    gpioWrite(GPIO_LED, !gpioGet(GPIO_LED));
}

int main(int argc, char *argv[]) {
    pigpio_init(5); // Initialize pigpio with a timeout of 5 seconds

    if (pigpio_setup_line_event(GPIO_TOUCH, touch_event_handler, NULL, 0) < 0) {
        fprintf(stderr, "Failed to set up line event: %s\n", pigpio_strerror(pigpio_last_error()));
        pigpio_shutdown();
        exit(EXIT_FAILURE);
    }

    gpioSetMode(GPIO_LED, GPIO_OUTPUT);
    gpioWrite(GPIO_LED, 0); // Initialize LED as output, LOW at startup

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        usleep(DEBOUNCE_MS * 1000 / HRTIME_PER_SEC); // Wait for debounce period
    }

    pigpio_shutdown();
    exit(EXIT_SUCCESS);
}

void signal_handler(int signum) {
    fprintf(stderr, "Received signal %d, shutting down...\n", signum);
    pigpio_shutdown();
    exit(signum == SIGINT ? EXIT_SUCCESS : EXIT_FAILURE);
}

