#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <errno.h>
#include <libgpgid.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define POLL_INTERVAL 500
#define LOG_FILE "/var/log/rain_events.log"

void log_event(const char *event) {
    int fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (fd == -1) {
        perror("Failed to open log file");
        return;
    }
    fprintf(fd, "%s", event);
    close(fd);
}

int main(int argc, char *argv[]) {
    pid_t pi_pid;
    int gpio_pin = GPIO_PIN;
    struct itimerspec timerspec;
    timerspec.timerspec_sec = 0;
    timerspec.timerspec_nsec = POLL_INTERVAL * 1000;

    // Initialize pigpio
    if (pigpioInitialise() < 0) {
        perror("Failed to initialize pigpio");
        return EXIT_FAILURE;
    }

    // Set up GPIO pin with internal pull-up resistor
    if (gpioSetup(gpio_pin, PIGIO_INPUT, PIGIO_PULLUP) < 0) {
        perror("Failed to set up GPIO pin");
        pigpioTerminate();
        return EXIT_FAILURE;
    }

    // Start a separate process to monitor the log file for SIGINT and SIGTERM
    pi_pid = fork();
    if (pi_pid == 0) { // Child process
        while (1) {
            if (waitpid(pi_pid, NULL, 0) == -1) {
                perror("Failed to wait for child process");
                exit(EXIT_FAILURE);
            }
            log_event("Gracefully shutting down...");
            close(LOG_FILE);
            pigpioTerminate();
            exit(EXIT_SUCCESS);
        }
    } else {
        // Parent process, start the polling loop
        if (piggpioSetMode(gpio_pin, PIGIO_OUTPUT) < 0) {
            perror("Failed to set GPIO pin mode");
            return EXIT_FAILURE;
        }

        while (1) {
            int current_state = piggpioGet(gpio_pin);
            if (current_state == PIGIO_INPUT_LOW) {
                log_event("Rain Detected");
            } else {
                log_event("No Rain");
            }
            usleep(POLL_INTERVAL * 1000);
        }
    }

    return EXIT_SUCCESS;
}

