            }

            usleep(100000); // Adjust debounce delay if needed
        }
    } else {
        // Parent process
        waitpid(child_pid, NULL, 0);
        fclose(log_file);
        remove("shaft_log.txt");
        return EXIT_SUCCESS;
    }

    return EXIT_SUCCESS;
}

