#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <time.h>
#include <libgpiod/gpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x28  // Si1182 default I2C address
#define LOG_FILE "biometric_log.txt"

void sigint_handler(int signum) {
    int i2c_fd;
    char buffer[100];

    printf("Shutting down...\n");
    fflush(stdout);

    // Close I2C handle
    i2c_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (i2c_fd < 0) {
        perror("Error opening log file");
        exit(EXIT_FAILURE);
    }

    // Flush and close I2C handle
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
    if (write(i2c_fd, buffer, strlen(buffer)) < 0) {
        perror("Error writing to log file");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
    if (fclose(i2c_fd) < 0) {
        perror("Error closing log file");
        exit(EXIT_FAILURE);
    }

    // Close I2C device
    if (close(i2c_fd) < 0) {
        perror("Error closing I2C device");
        exit(EXIT_FAILURE);
    }

    // Terminate libgpiod
    gpiod_disable();
    gpiod_exit();

    exit(EXIT_SUCCESS);
}

int main() {
    int i2c_fd, ret;
    struct i2c_client *client;
    struct si1182_data_t si1182_data;
    time_t now;
    struct tm *timeinfo;

    // Initialize signal handler
    signal(SIGINT, sigint_handler);

    // Initialize I2C device
    i2c_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (i2c_fd < 0) {
        perror("Error opening log file");
        exit(EXIT_FAILURE);
    }

    client = i2c_open(I2C_BUS, I2C_ADDR);
    if (!client) {
        perror("Error opening I2C device");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    while (1) {
        ret = i2c_transfer(client, 0x20, 0x00, 1, &si1182_data, sizeof(si1182_data));
        if (ret < 0) {
            perror("I2C read failed");
            sleep(1);
            continue;
        }

        // Process heart rate and SpO2 data
        // (Assuming you have functions to extract heart rate and SpO2 from si1182_data)
        int heart_rate = si1182_data.hr;
        int spo2 = si1182_data.spo2;

        // Format and write to log file
        now = time(NULL);
        timeinfo = localtime(&now);
        sprintf(buffer, "%d-%02d-%02d %02d:%02d:%02d, Heart Rate: %d BPM, SpO2: %d%%",
                timeinfo->tm_year + 1900, timeinfo->tm_mon + 1, timeinfo->tm_mday,
                timeinfo->tm_hour, timeinfo->tm_min, timeinfo->tm_sec);
        if (write(i2c_fd, buffer, strlen(buffer)) < 0) {
            perror("Error writing to log file");
            sleep(1);
            continue;
        }

        // Flush the file
        if (fflush(i2c_fd) < 0) {
            perror("Error flushing log file");
            sleep(1);
            continue;
        }

        // Sleep for one second
        usleep(1000000);
    }

    // Close I2C handle, log file, and driver library
    i2c_close(client);
    close(i2c_fd);
    gpiod_disable();
    gpiod_exit();

    return EXIT_SUCCESS;
}

