#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <pigpio.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 18
#define ALARM_GPIO 27
#define LOG_FILE "bridge_integrity.log"
#define POLL_INTERVAL_MS 100
#define HIGH_THRESHOLD_MS 2000

void log_event(const char *event_type, const char *timestamp) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
    time_t now = time(NULL);
    struct tm *time_info = localtime(&now);
    fprintf(log_file, "%s%s", ISO8601_time(time_info), "\n");
    fprintf(log_file, "%s: %s\n", timestamp, event_type);
    fclose(log_file);
}

void setup_gpio() {
    if (piGPIO_init() < 0) {
        fprintf(stderr, "Error initializing pigpio: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
}

void cleanup_gpio() {
    piGPIO_shutdown();
}

void monitor_sensors() {
    while (1) {
        int sensor1_state = pigpio_get(SENSOR_1_GPIO);
        int sensor2_state = pigpio_get(SENSOR_2_GPIO);
        int alarm_state = pigpio_get(ALARM_GPIO);

        if (sensor1_state || sensor2_state) {
            log_event("tilt_start", ISO8601_time(localtime(NULL)));
        }

        if (sensor1_state && sensor2_state) {
            if (alarm_state == 0) {
                log_event("tilt_end", ISO8601_time(localtime(NULL)));
                alarm_state = 1;
            }
        } else if (sensor1_state || sensor2_state) {
            if (alarm_state == 0) {
                log_event("threshold_exceeded", ISO8601_time(localtime(NULL)));
                alarm_state = 1;
            }
        } else {
            if (alarm_state == 1) {
                log_event("tilt_end", ISO8601_time(localtime(NULL)));
                alarm_state = 0;
            }
        }

        usleep(POLL_INTERVAL_MS / 1000);
    }
}

int main(int argc, char *argv[]) {
    setup_gpio();

    // Initialize log file
    int log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, S_IRUSR | S_IWUSR);
    if (log_fd == -1) {
        perror("Error opening log file");
        cleanup_gpio();
        exit(EXIT_FAILURE);
    }

    // Start monitoring sensors
    pthread_t monitor_thread;
    if (pthread_create(&monitor_thread, NULL, monitor_sensors, NULL) != 0) {
        perror("Error creating monitor thread");
        close(log_fd);
        cleanup_gpio();
        exit(EXIT_FAILURE);
    }

    // Handle SIGINT and SIGTERM for clean shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Wait for signals
    pthread_join(monitor_thread, NULL);

    // Clean up
    cleanup_gpio();
    close(log_fd);

    return 0;

signal_handler:
{
    log_event("shutdown", "SIGINT/SIGTERM received");
    pigpio_shutdown();
    return 0;
}
}

