#define I2C_BUS 1
#define SDA_PIN 2
#define SCL_PIN 3
#define ALERT_LED 17
#define THRESHOLD 500
#define LOG_FILE "seismic_events.log"
#define POLL_INTERVAL 100

void log_event(const char *timestamp, double peak_vibration) {
    time_t now = time(NULL);
    struct tm *timeinfo = localtime(&now);
    char time_str[80];
    sprintf(time_str, "%04d-%02d-%02d %02d:%02d:%02d",
            timeinfo->tm_year + 1900, timeinfo->tm_mon + 1, timeinfo->tm_mday,
            timeinfo->tm_hour, timeinfo->tm_min, timeinfo->tm_sec);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file.\n");
        return;
    }
    fprintf(log_file, "%s, %f\n", time_str, peak_vibration);
    fclose(log_file);
}

int main(int argc, char *argv[]) {
    int i2c_fd, alert_led_fd;
    pigpio_t *pi;
    int sensor_present = 0;
    int retries = 3;
    int peak_vibration = 0;

    pi = pigpio_init(I2C_BUS);
    if (pi == NULL) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    // Initialize sensor
    for (retries = 0; retries < 3; ++retries) {
        if (pigpio_digital_read(pi, SDA_PIN) == 0 &&
            pigpio_digital_read(pi, SCL_PIN) == 0) {
            sensor_present = 1;
