#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <string.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <linux/gpio.h>
#include <pigpio.h>

#define GPIO_BUS 2
#define LED_PIN 18
#define SENSORS_PINS {4, 17, 27, 22}
#define POLL_INTERVAL 50

int gpio_fd;
int led_state = 0;

void handle_signal(int signum) {
    printf("Received signal, cleaning up and exiting...\n");
    gpio_close(gpio_fd);
    close(gpio_fd);
    exit(0);
}

void setup_gpio(int gpio_fd) {
    if (gpio_fd < 0) {
        perror("Failed to open /dev/gpiobus");
        exit(EXIT_FAILURE);
    }

    if (gpio_setup(gpio_fd, GPIO_BUS) < 0) {
        perror("Failed to set up GPIO bus");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < sizeof(SENSORS_PINS) / sizeof(int); i++) {
        if (gpio_request(SENSORS_PINS[i], "keywish_ky032") < 0) {
            perror("Failed to request GPIO line");
            exit(EXIT_FAILURE);
        }

        if (gpio_setmode(SENSORS_PINS[i], GPIO_IN) < 0) {
            perror("Failed to set GPIO line as input");
            exit(EXIT_FAILURE);
        }

        if (gpio_setdirection(SENSORS_PINS[i], GPIO_IN) < 0) {
            perror("Failed to set GPIO line direction");
            exit(EXIT_FAILURE);
        }
    }

    if (gpio_setmode(LED_PIN, GPIO_OUTPUT) < 0) {
        perror("Failed to set GPIO LED direction");
        exit(EXIT_FAILURE);
    }

    gpio_write(LED_PIN, led_state);
}

void read_sensors() {
    int sensor_states = 0;
    for (int i = 0; i < sizeof(SENSORS_PINS) / sizeof(int); i++) {
        sensor_states |= gpio_get(SENSORS_PINS[i]);
    }

    led_state = sensor_states != 0;
    gpio_write(LED_PIN, led_state);
}

int main(int argc, char *argv[]) {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    gpio_fd = open("/dev/gpiomem", O_RDWR);
    if (gpio_fd < 0) {
        perror("Failed to open /dev/gpiomem");
        return EXIT_FAILURE;
    }

    setup_gpio(gpio_fd);

    while (1) {
        read_sensors();
        usleep(POLL_INTERVAL * 100000); // Convert 50ms to microseconds
    }

    gpio_close(gpio_fd);
    close(gpio_fd);

    return EXIT_SUCCESS;
}

