#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <syslog.h>
#include <time.h>
#include <stdbool.h>
#include <gpiod.h>

#define CHIP_PATH "/dev/gpiochip"
#define LOG_FILE "/var/log/flame_events.log"
#define NUM_SENSORS 5
#define PIN_2 2
#define PIN_3 3
#define PIN_4 4
#define PIN_17 17
#define PIN_27 27

typedef struct {
    int pin;
    gpiod_t *gpio_fd;
    FILE *log_file;
    sig_atomic_t debounced;
} SensorData;

SensorData sensors[NUM_SENSORS] = {
    { PIN_2, NULL, NULL, 0 },
    { PIN_3, NULL, NULL, 0 },
    { PIN_4, NULL, NULL, 0 },
    { PIN_17, NULL, NULL, 0 },
    { PIN_27, NULL, NULL, 0 }
};

void setup_sensors(void) {
    int i;
    for (i = 0; i < NUM_SENSORS; i++) {
        sensors[i].gpio_fd = gpiod_open_chip(CHIP_PATH);
        if (!sensors[i].gpio_fd) {
            syslog(LOG_ERR, "Failed to open GPIO chip");
            exit(EXIT_FAILURE);
        }
        sensors[i].log_file = fopen(LOG_FILE, "a");
        if (!sensors[i].log_file) {
            syslog(LOG_ERR, "Failed to open log file");
            gpiod_close(sensors[i].gpio_fd);
            exit(EXIT_FAILURE);
        }
    }
}

void debouncer(SensorData *sensor) {
    static time_t last_debounce_time = 0;
    time_t current_time = time(NULL);
    if (current_time - last_debounce_time > 5) {
        sensor->debounced = 0;
        last_debounce_time = current_time;
    }
}

void read_sensor(SensorData *sensor) {
    int value = gpiod_get_value(sensor->gpio_fd, sensor->pin);
    if (value != sensors[sensor->pin - PIN_2].debounced) {
        syslog(LOG_INFO, "Flame detected: Sensor %d (GPIO %d)", sensor->pin - PIN_2, sensor->pin);
        sensors[sensor->pin - PIN_2].debounced = value;
        flock(fileno(sensors[sensor->pin - PIN_2].log_file), LOCK_EX);
        fprintf(sensors[sensor->pin - PIN_2].log_file, "%s - Sensor %d (GPIO %d) - Flame Detected\n", ctime(time(NULL)), sensor->pin - PIN_2, sensor->pin);
        fflush(sensors[sensor->pin - PIN_2].log_file);
    }
}

void loop(void) {
    for (int i = 0; i < NUM_SENSORS; i++) {
        debouncer(&sensors[i]);
        read_sensor(&sensors[i]);
    }
    usleep(1000000);
}

void signal_handler(int sig) {
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (sensors[i].gpio_fd) {
            gpiod_disable(sensors[i].gpio_fd);
        }
    }
    syslog(LOG_INFO, "Flame monitor shutdown");
    exit(0);
}

int main(void) {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    setup_sensors();
    loop();

    closelog();
    return 0;
}

