#define TOUCH_PINS {5, 6, 13, 19, 26, 12, 16, 20}
#define POLL_INTERVAL_MS 50

void log_touch_event(int index, int pin, int state) {
    time_t now = time(NULL);
    struct tm *local_time = localtime(&now);
    char timestamp[80];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", local_time);

    printf("Touch Event: %s [%s] State: %d\n", timestamp, (char *)((int *)local_time + 6), state);
}

int main() {
    int n_touch_pins = sizeof(TOUCH_PINS) / sizeof(TOUCH_PINS[0]);
    int ret;
    struct gpiod_chip *chip;
    struct gpiod_line *lines[n_touch_pins];

    ret = gpiod_chip_create(&chip, GPIOD_CHIP_DEFAULT);
    if (ret < 0) {
        perror("Failed to create gpiod chip");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < n_touch_pins; i++) {
        ret = gpiod_line_new(chip, TOUCH_PINS[i], GPIOD_LINE_IN, NULL);
        if (ret < 0) {
            perror("Failed to create line for pin");
            exit(EXIT_FAILURE);
        }
        lines[i] = gpiod_line_get(chip, TOUCH_PINS[i]);
    }

    while (1) {
        ret = gpiod_line_read(lines, n_touch_pins);
        if (ret < 0) {
            perror("Failed to read lines");
            exit(EXIT_FAILURE);
        }

        for (int i = 0; i < n_touch_pins; i++) {
            int current_state = gpiod_line_get_value(lines[i]);
            int prev_state = -1;

            if (i > 0) {
                prev_state = gpiod_line_get_value(lines[i - 1]);
            }

            if (current_state != prev_state) {
                log_touch_event(i, TOUCH_PINS[i], current_state);
            }
        }

        usleep(POLL_INTERVAL_MS * 1000 / HRTIME_PER_SEC);
    }

    for (int i = 0; i < n_touch_pins; i++) {
        gpiod_line_destroy(lines[i]);
    }
    gpiod_chip_destroy(chip);

    return 0;
}

