#include <fcntl.h>
#include <sys/stat.h>
#include <signal.h>
#include <libgpiod/gpio.h>

#define TOUCH_SENSOR_PINS {2, 3, 4, 5, 6, 7, 8, 9}
#define LED_PIN 17
#define TOUCH_LOG_FILE "touch_log.txt"
#define DEBOUNCE_DELAY 50

int main(int argc, char *argv[]) {
    int sensor_pins[8], led_pin;
    gpiod_ctx_t ctx;
    gpiod_button_t button;
    FILE *touch_log_file;
    struct sigaction sa;

    if (libgpiod_init() < 0) {
        fprintf(stderr, "Failed to initialize libgpiod\n");
        exit(EXIT_FAILURE);
    }

    led_pin = GPIO_PIN_0;
    for (int i = 0; i < 8; i++) {
        sensor_pins[i] = GPIO_PIN_2 + i;
    }

    if (libgpiod_button_init(&button, sensor_pins, 8, GPIO_MODE_INPUT_PULLDOWN) < 0) {
        fprintf(stderr, "Failed to initialize buttons\n");
        libgpiod_exit();
        exit(EXIT_FAILURE);
    }

    touch_log_file = fopen(TOUCH_LOG_FILE, "a");
    if (!touch_log_file) {
        fprintf(stderr, "Failed to open touch_log.txt for appending\n");
        libgpiod_button_destroy(&button);
        libgpiod_exit();
        exit(EXIT_FAILURE);
    }

    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install signal handler for SIGINT\n");
        libgpiod_button_destroy(&button);
        fclose(touch_log_file);
        libgpiod_exit();
        exit(EXIT_FAILURE);
    }

    sa.sa_handler = handle_sigterm;
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install signal handler for SIGTERM\n");
        libgpiod_button_destroy(&button);
        fclose(touch_log_file);
        libgpiod_exit();
        exit(EXIT_FAILURE);
    }

    while (1) {
        int button_state = lgi_get_value(&button);
        if (button_state & LI_TOUCH_PRESSED) {
            int channel = lgi_get_channel(&button);
            if (channel < 0) {
                fprintf(stderr, "Invalid channel\n");
                continue;
            }

            // Debounce logic (simplified, can be improved)
            int last_state = lgi_get_value(&button);
            if (last_state & LI_TOUCH_PRESSED && button_state & LI_TOUCH_PRESSED) {
                // Single press, log it
                time_t now = time(NULL);
                struct tm *timeinfo = localtime(&now);
                fprintf(touch_log_file, "%d-%d-%d %d:%d:%d – Channel %d Touched\n",
                        timeinfo->tm_year + 1900, timeinfo->tm_mon + 1, timeinfo->tm_mday,
                        timeinfo->tm_hour, timeinfo->tm_min, timeinfo->tm_sec, channel + 1);

                // Turn on LED if any channel is touched
                int led_state = lgi_get_value(&button) & LI_TOUCH_PRESSED;
                if (led_state) {
                    lgi_set_value(led_pin, LI_TOUCH_ON);
                } else {
                    lgi_set_value(led_pin, LI_TOUCH_OFF);
                }
            }
        }

        // Debounce delay
        usleep(DEBOUNCE_DELAY * 1000 / 1000);
    }

    libgpiod_button_destroy(&button);
    libgpiod_exit();
    fclose(touch_log_file);
    return 0;
}

void handle_sigint(int signum, siginfo_t *info, void *context) {
    fprintf(stderr, "Received SIGINT, turning off LED and exiting gracefully\n");
    lgi_set_value(LED_PIN, LI_TOUCH_OFF);
    exit(EXIT_SUCCESS);
}

void handle_sigterm(int signum, siginfo_t *info, void *context) {
    fprintf(stderr, "Received SIGTERM, turning off LED and exiting gracefully\n");
    lgi_set_value(LED_PIN, LI_TOUCH_OFF);
    exit(EXIT_SUCCESS);
}

