#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <pigpio.h>
#include <sys/stat.h>
#include <sys/types.h>

#define SENSOR_GPIO 4
#define ALERT_GPIO 17
#define POLL_INTERVAL 500
#define LOG_FILE "fire_events.log"

void log_event(const char *event_type);
void setup_gpio(void);
void cleanup_gpio(void);

int main(int argc, char *argv[]) {
    setup_gpio();

    pigpio_init(5); // Initialize pigpio with 5 seconds timeout

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return 1;
    }

    while (1) {
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        int sensor_state = pigpio_get_gpio(SENSOR_GPIO);

        if (sensor_state == -1) {
            fprintf(stderr, "Error reading sensor GPIO: %s\n", strerror(errno));
            continue;
        }

        if (sensor_state == 0) { // Flame detected (sensor output LOW)
            log_event("FLAME_DETECTED");
            pigpio_put_gpio(ALERT_GPIO, 1);
            usleep(1000000); // 1 second delay
            pigpio_put_gpio(ALERT_GPIO, 0);
        }

        // Log the current state
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
        fprintf(log_file, "%s: Sensor state: %d\n", timestamp, sensor_state);

        usleep(POLL_INTERVAL * 1000); // Wait for next poll
    }

    cleanup_gpio();
    pigpio_terminate();
    fclose(log_file);
    return 0;
}

void log_event(const char *event_type) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }
    fprintf(log_file, "%s: %s\n", strftime(NULL, 0, localtime(), "%Y-%m-%d %H:%M:%S"), event_type);
    fclose(log_file);
}

void setup_gpio(void) {
    if (pigpio_init(5) != 0) {
        fprintf(stderr, "Error initializing pigpio: %s\n", strerror(errno));
        exit(1);
    }

    if (open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, S_IRUSR | S_IWUSR) == -1) {
        fprintf(stderr, "Error creating or opening log file: %s\n", strerror(errno));
        exit(1);
    }
}

void cleanup_gpio(void) {
    if (pigpio_terminate() != 0) {
        fprintf(stderr, "Error terminating pigpio: %s\n", strerror(errno));
    }
    if (fclose(log_file) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
    }
}

