#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <libgpiod/gpio.h>

#define GPIO_PIN 4
#define DEBOUNCE_INTERVAL_MS 50
#define LOG_FILE "touch_log.txt"

void signal_handler(int signum) {
    printf("Received signal %d, releasing GPIO line and closing log file.\n", signum);
    gpio_set_dir(GPIO_PIN, GPIO_OUT);
    gpio_set_level(GPIO_PIN, 0);
    fclose(log_file);
    exit(signum);
}

int main(int argc, char *argv[]) {
    int log_fd;
    struct stat sb;
    gpio_init();

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal");
        exit(EXIT_FAILURE);
    }

    if (signal(SIGTERM, signal_handler) == SIG_ERR) {
        perror("signal");
        exit(EXIT_FAILURE);
    }

    log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd == -1) {
        perror("open");
        gpio_cleanup();
        exit(EXIT_FAILURE);
    }

    gpio_set_pull_up_down(GPIO_PIN, GPIO_PULLDOWN);

    while (1) {
        int now = millis();
        if (now - last_touch_time > DEBOUNCE_INTERVAL_MS / 1000) {
            last_touch_time = now;

            int current_state = gpio_get_level(GPIO_PIN);
            if (current_state == GPIO_HIGH) {
                if (gpio_get_level(GPIO_PIN) == GPIO_LOW) {
                    fprintf(log_fd, "%s", "YYYY-MM-DD HH:MM:SS: Touch Released\n");
                } else {
                    fprintf(log_fd, "%s", "YYYY-MM-DD HH:MM:SS: Touch Detected\n");
                }
            }
        }
    }

    gpio_cleanup();
    close(log_fd);
    return 0;
}

