#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x50
#define CRC_POLYNOMIAL 0x07
#define MIN_FLOW_RATE 0.0
#define MAX_FLOW_RATE 100.0

#define LOG_FILE "cooling_log.csv"

int i2c_fd;

void log_data(const char *data) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Failed to open log file");
        return;
    }
    fprintf(fp, "%s", data);
    fclose(fp);
}

void init_i2c() {
    int file = open("/dev/i2c-1", O_RDWR);
    if (file < 0) {
        perror("Failed to open i2c bus");
        exit(EXIT_FAILURE);
    }

    ioctl(file, I2C_SLAVE, I2C_ADDR);

    i2c_fd = fileno(file);
}

int read_i2c(uint8_t *buffer) {
    if (read(i2c_fd, buffer, 3) != 3) {
        perror("Failed to read from I2C bus");
        return -1;
    }
    return 0;
}

int validate_crc(uint8_t *buffer) {
    uint16_t crc = 0xFFFF;
    for (int i = 0; i < 3; i++) {
        crc ^= buffer[i];
        for (int j = 0; j < 8; j++) {
            crc <<= 1;
            if ((crc & 0x01) == 1) {
                crc = crc >> 1;
            } else {
                crc = crc >> 1;
                crc ^= CRC_POLYNOMIAL;
            }
        }
    }
    return crc == 0;
}

float read_flow_rate(uint8_t *buffer) {
    uint16_t flow = (buffer[0] << 8) | buffer[1];
    if (flow > MAX_FLOW_RATE || flow < MIN_FLOW_RATE) {
        return NAN; // INVALID
    }
    return (float)flow / 1000.0; // Convert to ml/min
}

int main(int argc, char *argv[]) {
    init_i2c();

    while (1) {
        uint8_t buffer[3];
        if (read_i2c(buffer) == -1) {
            log_data("ERROR\n");
            log_data("I2C read failed, re-initializing...\n");
            init_i2c();
            continue;
        }

        if (!validate_crc(buffer)) {
            log_data("ERROR\n");
            log_data("CRC validation failed, re-initializing...\n");
            init_i2c();
            continue;
        }

        float flow_rate = read_flow_rate(buffer);
        if (isnan(flow_rate)) {
            log_data("INVALID\n");
        } else {
            char status[20];
            snprintf(status, sizeof(status), "OK");
            log_data("%f,%.2f,%s\n", clock(), flow_rate, status);
        }

        usleep(2000000); // Wait 2 ms before the first read
    }

    log_data("Exiting...\n");
    close(i2c_fd);
    remove(LOG_FILE);
    return 0;
}

