#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <stdbool.h>
#include <pigpio.h>

#define LEFT_GPIO 17
#define MIDDLE_GPIO 27
#define RIGHT_GPIO 22
#define SAMPLE_INTERVAL 50  // milliseconds
#define LOG_FILE "path_log.csv"

void init_gpio(void) {
    if (piGPIOInit() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        exit(EXIT_FAILURE);
    }
}

void release_gpio(void) {
    piGPIODefault();
}

void init_log_file(void) {
    int fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (fd == -1) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
}

void close_log_file(void) {
    close(fildes);
}

void write_to_log(const char *timestamp, int left, int middle, int right) {
    char log_entry[100];
    sprintf(log_entry, "%s,%d,%d,%d\n", timestamp, left, middle, right);
    if (write(fildes, log_entry, strlen(log_entry)) == -1) {
        perror("Failed to write to log file");
        exit(EXIT_FAILURE);
    }
}

void read_sensors(void) {
    static int last_timestamp = 0;
    int left, middle, right;

    while (1) {
        int left_value = piGPIORead(LEFT_GPIO);
        int middle_value = piGPIORead(MIDDLE_GPIO);
        int right_value = piGPIORead(RIGHT_GPIO);

        int current_timestamp = microsecond();
        if (current_timestamp < last_timestamp) {
            usleep(100000 - (current_timestamp - last_timestamp));
        }
        last_timestamp = current_timestamp;

        write_to_log(get_iso8601_timestamp(current_timestamp), left_value, middle_value, right_value);

        usleep(SAMPLE_INTERVAL * 1000 / 1000);
    }
}

int main(int argc, char *argv[]) {
    init_gpio();
    init_log_file();

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("Failed to register signal handler");
        release_gpio();
        close_log_file();
        exit(EXIT_FAILURE);
    }

    read_sensors();

    release_gpio();
    close_log_file();
    return 0;

signal_handler:
{
    piGPIODefault();
    close_log_file();
    release_gpio();
    return 0;
}

