#define GPIO_PIN 4
#define FLAME_EVENT_FILE "flame_events.txt"

void handle_flame_event(const char *message) {
    FILE *file = fopen(FLAME_EVENT_FILE, "a");
    if (file == NULL) {
        fprintf(stderr, "Failed to open flame_events.txt for appending.\n");
        return;
    }
    fprintf(file, "%s", message);
    fclose(file);
}

void signal_handler(int signum) {
    handle_flame_event("Received signal, exiting...");
    exit(signum);
}

int main() {
    struct gpio_req req;
    int fd;
    char message[100];

    // Initialize GPIO
    req.pin = GPIO_PIN;
    req.mode = GPIO_MODE_INPUT;
    req.pull_up_en = 0; // Active low, so no pull-up

    fd = open(gpio_get_name(req.pin), O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd < 0) {
        perror("Failed to open GPIO file descriptor");
        return EXIT_FAILURE;
    }

    if (ioctl(fd, GPIO_SET_PIN, &req) < 0) {
        perror("Failed to set GPIO pin mode");
        close(fd);
        return EXIT_FAILURE;
    }

    while (1) {
        int value = read(fd, &message[0], 1);
        if (value == -1) {
            perror("Failed to read from GPIO");
            break;
        }

        if (value == 0) { // Flame detected (0 indicates flame)
            handle_flame_event("Flame detected at ");
            time_t now = time(NULL);
            struct tm *tm = localtime(&now);
            strftime(message, sizeof(message), "at %02d:%02d:%02d", tm->tm_hour, tm->tm_min, tm->tm_sec);
            handle_flame_event(message);
        }

        usleep(100000); // Check every second
    }

    close(fd);
    return EXIT_SUCCESS;
}

