#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_CHIP 4
#define TOUCH_PIN 23
#define LED_PIN 24
#define LOG_FILE "touch_log.txt"
#define POLL_TIMEOUT_S 1

void signal_handler(int signum) {
    close(LOG_FILE);
    gpiod_disable(GPIO_CHIP);
    gpiod_exit(0);
    exit(signum);
}

int main(int argc, char *argv[]) {
    int log_fd;
    struct stat sb;

    // Initialize libgpiod
    if (gpiod_init() < 0) {
        perror("Failed to initialize libgpiod");
        return EXIT_FAILURE;
    }

    // Set up GPIO chip
    if (gpiod_chip_init(GPIO_CHIP, 4) < 0) {
        perror("Failed to initialize GPIO chip");
        return EXIT_FAILURE;
    }

    // Configure GPIO pins
    if (gpiod_pin_new(GPIO_CHIP, TOUCH_PIN, GPIOD_OUT) < 0) {
        perror("Failed to configure touch sensor pin");
        return EXIT_FAILURE;
    }
    if (gpiod_pin_new(GPIO_CHIP, LED_PIN, GPIOD_IN) < 0) {
        perror("Failed to configure LED pin");
        return EXIT_FAILURE;
    }

    // Open log file
    log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd == -1) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    // Initialize timestamp
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[80];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%T", tm);

    // Main loop
    while (1) {
        // Poll for touch events
        int touch_event = gpiod_poll(GPIO_CHIP, TOUCH_PIN, GPIOD_IN, POLL_TIMEOUT_S, 0);
        if (touch_event < 0) {
            perror("Failed to poll touch sensor");
            break;
        }

        if (touch_event & GPIOD_EVENT_RISING) {
            // Touch detected, toggle LED
            if (gpiod_pin_write(GPIO_CHIP, LED_PIN, 1) < 0) {
                perror("Failed to toggle LED");
                break;
            }

            // Log touch event
            char log_msg[256];
            sprintf(log_msg, "Timestamp: %s, Touch: Yes, LED: %s\n", timestamp, touch_event ? "On" : "Off");
            if (write(log_fd, log_msg, strlen(log_msg)) == -1) {
                perror("Failed to write to log file");
                break;
            }
        }

        // Sleep for a short period to avoid busy-waiting
        usleep(10000);
    }

    // Clean up resources
    gpiod_pin_del(GPIO_CHIP, LED_PIN);
    gpiod_pin_del(GPIO_CHIP, TOUCH_PIN);
    gpiod_chip_destroy(GPIO_CHIP);
    gpiod_exit(0);

    // Close log file
    if (log_fd != -1) {
        close(log_fd);
    }

    return EXIT_SUCCESS;
}

// Register signal handlers
signal(SIGINT, signal_handler);
signal(SIGTERM, signal_handler);

