#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <stdlib.h>
#include <gpiod.h>

#define FLAME_SENSOR_GPIO 17
#define BUZZER_GPIO 18
#define POLL_INTERVAL_MS 100
#define BUZZER_DURATION_MS 2000
#define LOG_FILE "alert_log.txt"

void log_flame_detected(const char *timestamp) {
    time_t now = time(NULL);
    char time_str[80];
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", localtime(&now));
    FILE *file = fopen(LOG_FILE, "a");
    if (file) {
        fprintf(file, "%s: FLAME DETECTED\n", time_str);
        fclose(file);
    }
}

void buzzer_on() {
    writel(1, BUZZER_GPIO);
}

void buzzer_off() {
    writel(0, BUZZER_GPIO);
}

void flame_detected_handler(const struct gpiod_event *event, void *user_data) {
    log_flame_detected(ctime(NULL));
    buzzer_on();
    usleep(BUZZER_DURATION_MS * 1000 / HRTIME_PER_SEC);
    buzzer_off();
}

int main() {
    int flame_sensor_gpio = FLAME_SENSOR_GPIO;
    int buzzer_gpio = BUZZER_GPIO;

    if (gpiod_setup(NULL, 1, [flame_sensor_gpio] = GPIOD_OUT) < 0) {
        perror("gpiod_setup failed");
        exit(EXIT_FAILURE);
    }

    if (gpiod_export_pin(flame_sensor_gpio) < 0) {
        perror("gpiod_export_pin failed");
        exit(EXIT_FAILURE);
    }

    if (gpiod_export_pin(buzzer_gpio) < 0) {
        perror("gpiod_export_pin failed");
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, flame_detected_handler);
    signal(SIGTERM, flame_detected_handler);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen failed");
        exit(EXIT_FAILURE);
    }

    printf("System started\n");
    while (1) {
        int sensor_state = gpiod_get_value(flame_sensor_gpio);
        if (sensor_state == GPIOD_INPUT_LOW) {
            log_flame_detected(ctime(NULL));
            buzzer_on();
            usleep(POLL_INTERVAL_MS * 1000 / HRTIME_PER_SEC);
        }
        usleep(POLL_INTERVAL_MS * 1000 / HRTIME_PER_SEC);
    }

    fclose(log_file);
    gpiod_export_pin(flame_sensor_gpio);
    gpiod_export_pin(buzzer_gpio);
    gpiod_unexport_pin(flame_sensor_gpio);
    gpiod_unexport_pin(buzzer_gpio);
    gpiod_free(NULL);

    printf("System stopped\n");
    return 0;
}

