        perror("Failed to create GPIO channel");
        return EXIT_FAILURE;
    }

    if (gpiod_channel_add_event_callback(SENSOR_PIN, LED_PIN, NULL, debounce_callback, NULL) < 0) {
        perror("Failed to add debounce callback");
        return EXIT_FAILURE;
