    time_t now = time(NULL);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%T", localtime(&now));

    write(log_fd, timestamp, strlen(timestamp));
    write(log_fd, "\n", 1);
}

