#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod/gpio.h>

// Function to handle SIGINT and SIGTERM signals
void signal_handler(int signum) {
    fprintf(stderr, "Received signal %d, performing clean shutdown...\n", signum);
    close(1); // Close stdout
    close(2); // Close stderr
    close(0); // Close stdin
    gpio_set_mode(GPIO_OUTPUT, 4); // Ensure GPIO4 is output
    gpio_set_drive(GPIO_OUTPUT, 0); // Set GPIO4 as output with 0
    gpio_set_drive(GPIO_OUTPUT, 1); // Set GPIO4 as output with 1
    gpio_set_level(GPIO_OUTPUT, 1); // Set GPIO4 as high
    exit(0);
}

int main() {
    // Initialize gpiod
    if (gpio_init() < 0) {
        fprintf(stderr, "Failed to initialize gpiod\n");
        return EXIT_FAILURE;
    }

    // Configure GPIO pins as inputs with internal pull-up
    if (gpio_pin_config_default(4) < 0 ||
        gpio_pin_config_default(17) < 0 ||
        gpio_pin_config_default(27) < 0) {
        fprintf(stderr, "Failed to configure GPIO pins\n");
        return EXIT_FAILURE;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the log file
    FILE *log_file = fopen("magnet_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        return EXIT_FAILURE;
    }

    // Initial state recording
    int sensor1_state = -1, sensor2_state = -1, sensor3_state = -1;
    time_t initial_timestamp = time(NULL);
    fprintf(log_file, "Initial state: %s, %s, %s\n",
        (sensor1_state == 0) ? "LOW" : "HIGH",
        (sensor2_state == 0) ? "LOW" : "HIGH",
        (sensor3_state == 0) ? "LOW" : "HIGH");

    while (1) {
        // Read sensor states
        int sensor1_read = gpio_get_level(4);
        int sensor2_read = gpio_get_level(17);
        int sensor3_read = gpio_get_level(27);

        // Check for errors
        if (sensor1_read < 0 || sensor2_read < 0 || sensor3_read < 0) {
            fprintf(stderr, "Error reading sensor data\n");
            continue;
        }

        // Log state changes
        time_t current_timestamp = time(NULL);
        if (sensor1_read != sensor1_state) {
            fprintf(log_file, "%s, %s, %s\n",
                (sensor1_read == 0) ? "LOW" : "HIGH",
                (sensor2_read == 0) ? "LOW" : "HIGH",
                (sensor3_read == 0) ? "LOW" : "HIGH");
            sensor1_state = sensor1_read;
        }

        if (sensor2_read != sensor2_state) {
            fprintf(log_file, "%s, %s, %s\n",
                (sensor2_read == 0) ? "LOW" : "HIGH",
                (sensor1_read == 0) ? "LOW" : "HIGH",
                (sensor3_read == 0) ? "LOW" : "HIGH");
            sensor2_state = sensor2_read;
        }

        if (sensor3_read != sensor3_state) {
            fprintf(log_file, "%s, %s, %s\n",
                (sensor3_read == 0) ? "LOW" : "HIGH",
                (sensor1_read == 0) ? "LOW" : "HIGH",
                (sensor2_read == 0) ? "LOW" : "HIGH");
            sensor3_state = sensor3_read;
        }

        // Wait for 100ms
        usleep(100000);
    }

    // Clean shutdown
    gpio_set_mode(GPIO_OUTPUT, 4);
    gpio_set_drive(GPIO_OUTPUT, 0);
    gpio_set_level(GPIO_OUTPUT, 1);
    fclose(log_file);
    return EXIT_SUCCESS;
}

