#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x28  // Si1182_A_GM
#define SAMPLE_COUNT 5
#define LOG_FILE "heart_rate.csv"
#define EXPECTED_PART_ID 0x11223344
#define EXPECTED_HW_REV 0x01

int i2c_fd;

void init_i2c() {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

void close_i2c() {
    if (close(i2c_fd) < 0) {
        perror("Failed to close I2C bus");
        exit(EXIT_FAILURE);
    }
}

void read_sensor_data() {
    uint8_t part_id[8], hw_rev[2];
    ssize_t read_bytes;

    read_bytes = read(i2c_fd, part_id, sizeof(part_id));
    if (read_bytes != sizeof(part_id)) {
        if (errno == EIO) {
            // Retry transient I2C read errors
            read_bytes = read(i2c_fd, part_id, sizeof(part_id));
            if (read_bytes != sizeof(part_id)) {
                fprintf(stderr, "Transient I2C read error, retrying...\n");
                return;
            }
        } else {
            fprintf(stderr, "Failed to read PART_ID\n");
            exit(EXIT_FAILURE);
        }
    }

    read_bytes = read(i2c_fd, hw_rev, sizeof(hw_rev));
    if (read_bytes != sizeof(hw_rev)) {
        if (errno == EIO) {
            // Retry transient I2C read errors
            read_bytes = read(i2c_fd, hw_rev, sizeof(hw_rev));
            if (read_bytes != sizeof(hw_rev)) {
                fprintf(stderr, "Transient I2C read error, retrying...\n");
                return;
            }
        } else {
            fprintf(stderr, "Failed to read HW_REV\n");
            exit(EXIT_FAILURE);
        }
    }

    if (memcmp(part_id, EXPECTED_PART_ID, sizeof(part_id)) != 0 ||
        memcmp(hw_rev, EXPECTED_HW_REV, sizeof(hw_rev)) != 0) {
        fprintf(stderr, "Sensor not present or wrong revision\n");
        exit(EXIT_FAILURE);
    }

    // Configure sensor
    if (piGPIO_write(I2C_ADDR, 0x00, 1) < 0) {
        fprintf(stderr, "Failed to write configuration\n");
        exit(EXIT_FAILURE);
    }

    // Read raw heart rate
    uint16_t raw_bpm;
    read_bytes = read(i2c_fd, &raw_bpm, sizeof(raw_bpm));
    if (read_bytes != sizeof(raw_bpm)) {
        fprintf(stderr, "Failed to read raw heart rate\n");
        exit(EXIT_FAILURE);
    }

    // Apply moving average filter
    uint16_t filtered_bpm[SAMPLE_COUNT];
    int count = 0;
    for (int i = 0; i < SAMPLE_COUNT; i++) {
        filtered_bpm[i] = raw_bpm;
        count++;
    }

    for (int i = 1; i < SAMPLE_COUNT; i++) {
        filtered_bpm[i] = (filtered_bpm[i - 1] + filtered_bpm[i]) / 2;
    }

    // Validate BPM
    double avg_bpm = (double)filtered_bpm[SAMPLE_COUNT - 1] / SAMPLE_COUNT;
    if (avg_bpm < 30 || avg_bpm > 220) {
        fprintf(stderr, "Invalid BPM value: %f\n", avg_bpm);
        exit(EXIT_FAILURE);
    }

    // Append to log file
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    time_t now = time(NULL);
    char timestamp[8];
    sprintf(timestamp, "%d-%02d-%02d %02d:%02d:%02d",
            now / 24, now % 24, now % 12, now % 60, now % 60, 0);
    fprintf(log_file, "%s,%.2f\n", timestamp, avg_bpm);
    fclose(log_file);
}

int main(int argc, char *argv[]) {
    init_i2c();

    while (1) {
        read_sensor_data();
        usleep(1000000);  // Sleep for 1 second
    }

    close_i2c();
    return 0;
}

