#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_PIN 17
#define POLL_INTERVAL 100
#define LOG_FILE "flame_log.txt"

int main() {
    int fd_log, ret;
    gpiod_ctx_t ctx;
    gpiod_button_attr_t button_attr = GPIOD_BUTTON_ATTR_DEFAULT;
    button_attr.edge = GPIOD_BUTTON_EDGE_FALLING;
    button_attr.pull_up = 1;
    button_attr.pull_down = 0;

    // Initialize libgpiod
    if (libgpiod_init(NULL) < 0) {
        perror("libgpiod_init");
        exit(EXIT_FAILURE);
    }

    // Open the log file
    fd_log = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (fd_log < 0) {
        perror("open");
        libgpiod_cleanup();
        exit(EXIT_FAILURE);
    }

    // Configure GPIO17 as input with pull-up
