#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/epoll.h>
#include <gpiod.h>

#define TOUCH_PINS {5, 6, 7, 8, 9, 10, 11, 12}
#define COUNTER_PIN {17, 18, 19, 20, 21, 22, 23, 24}
#define LOG_FILE "touch_log.txt"
#define STABILIZATION_DELAY 200000
#define POLL_INTERVAL 100000

void log_event(const char *channel, int counter) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", localtime(&ts.tv_sec));
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }
    fprintf(log_file, "%s, Channel: %d, Counter: %d\n", timestamp, channel, counter);
    fclose(log_file);
}

void update_output_pins(int channel) {
    for (int i = 0; i < 8; i++) {
        if (channel >= i && i < 8) {
            gpiod_output_t output;
            gpiod_output_init(COUNTER_PIN[channel], &output);
            gpiod_output_set_level(output, 1);
        } else {
            gpiod_output_init(COUNTER_PIN[channel], &output);
            gpiod_output_set_level(output, 0);
        }
    }
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <gpio_driver_api>\n", argv[0]);
        return 1;
    }

    gpiod_context ctx;
    gpiod_init(&ctx);

    int epoll_fd = epoll_create1(0);
    if (epoll_fd == -1) {
        perror("epoll_create1");
        return 1;
    }

    struct epoll_event events[8];
    for (int i = 0; i < 8; i++) {
        events[i].events = EPOLLIN;
        events[i].data.fd = TOUCH_PINS[i];
    }
    if (epoll_ctl(epoll_fd, EPOLL_CTL_ADD, TOUCH_PINS[0], events[0]) == -1) {
        perror("epoll_ctl");
        return 1;
    }

    int stabilization_delay_ns = STABILIZATION_DELAY * 1000000;
    int poll_interval_ns = POLL_INTERVAL * 1000000;

    while (1) {
        int ret = epoll_wait(&ctx, events, 8, stabilization_delay_ns);
        if (ret < 0) {
            perror("epoll_wait");
            break;
        }

        for (int i = 0; i < ret; i++) {
            int pin = events[i].data.fd;
            int value = gpiod_get_level(&ctx, pin);
            if (value == 0) {
                int counter = 0;
                for (int j = 0; j < 8; j++) {
                    if (TOUCH_PINS[j] == pin) {
                        counter++;
                        if (counter == 256) {
                            counter = 0;
                        }
                        update_output_pins(j);
                        log_event(j, counter);
                        printf("Touch on channel %d | Counter: %d\n", j, counter);
                    }
                }
            }
        }
    }

    for (int i = 0; i < 8; i++) {
        gpiod_output_init(COUNTER_PIN[i], &gpiod_output_t{0});
    }

    close(epoll_fd);
    gpiod_destroy(&ctx);

    if (access(LOG_FILE, F_OK) == 0) {
        printf("Log file already exists, cleaning up...\n");
        unlink(LOG_FILE);
    }

    for (int i = 0; i < 8; i++) {
        gpiod_output_init(COUNTER_PIN[i], &gpiod_output_t{0});
    }

    return 0;
}

