#define GPIO_18 18
#define GPIO_27 27
#define GPIO_22 22
#define POLL_INTERVAL 100
#define LOG_FILE "tracking_log.csv"

void sigint_handler(int signum) {
    printf("Received SIGINT, performing graceful shutdown...\n");
    pioClose();
    close(stdout);
    close(stderr);
    fclose(stdout);
    fclose(stderr);
    printf("Shutdown complete.\n");
    exit(0);
}

void sigterm_handler(int signum) {
    printf("Received SIGTERM, performing graceful shutdown...\n");
    pioClose();
    close(stdout);
    close(stderr);
    fclose(stdout);
    fclose(stderr);
    printf("Shutdown complete.\n");
    exit(0);
}

int main(int argc, char *argv[]) {
    pioInit();

    if (pioSetupSharedMode(1) < 0) {
        perror("pioSetupSharedMode");
        exit(EXIT_FAILURE);
    }

    int gpioPins[] = {GPIO_17, GPIO_18, GPIO_27, GPIO_22};
    int sensorReadings[4];

    FILE *logFile = fopen(LOG_FILE, "a");
    if (!logFile) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }

    fprintf(logFile, "timestamp,sensor1,sensor2,sensor3,sensor4\n");

    while (1) {
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        long long timestamp = ts.tv_sec * 1000000 + ts.tv_nsec / 1000;

        for (int i = 0; i < 4; i++) {
            sensorReadings[i] = pioGetReadiness(gpioPins[i]) & 1;
            if (sensorReadings[i] == 0) {
                fprintf(logFile, "%ld,%d,%d,%d,%d\n", timestamp, sensorReadings[0], sensorReadings[1], sensorReadings[2], sensorReadings[3]);
            }
        }

        usleep(POLL_INTERVAL * 1000);
    }

    pioClose();
    fclose(logFile);
    remove(LOG_FILE);

    pioExit();

    return 0;
}

