#include <sys/types.h>
#include <errno.h>
#include <libgpiod.h>

#define GPIO17 11
#define GPIO18 12
#define DEBOUNCE_MS 50
#define POLL_MS 100

void log_event(int sensor_id, int state) {
    char timestamp[20];
    time_t now = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    char log_entry[100];
    sprintf(log_entry, "%s, Sensor %d tilted\n", timestamp, sensor_id);
    int log_file = open("/var/log/tilt_events.log", O_WRONLY | O_CREAT | O_APPEND, S_IRUSR | S_IWUSR);
    if (log_file == -1) {
        perror("Error opening log file");
        exit(EXIT_FAILURE);
    }
    write(log_file, log_entry, strlen(log_entry));
    close(log_file);
}

int main() {
    int gpio_fd;
    int sensor1_state = 1;
    int sensor2_state = 1;

    gpio_fd = gpiod_request_channel_by_name("D7E-5");
    if (gpio_fd < 0) {
        fprintf(stderr, "Failed to open GPIO channel\n");
        return EXIT_FAILURE;
    }

    gpiod_set_direction(gpio_fd, GPIO_IN, 2);
    gpiod_set_bias_pull_up(gpio_fd, 1);

    gpiod_edge_detect_config_t config = {
        .debounce_ms = DEBOUNCE_MS,
        .edge_detect_mode = GPIOD_EDGE_BOTH_EDGE
    };
    if (gpiod_edge_detect_config(gpio_fd, &config) < 0) {
        fprintf(stderr, "Failed to configure edge detection\n");
        return EXIT_FAILURE;
    }

    while (1) {
        int sensor1_read = gpiod_get_edge_count(gpio_fd);
        int sensor2_read = gpiod_get_edge_count(gpio_fd);

        if (sensor1_read > 0 && sensor1_state == 1) {
            sensor1_state = 0;
            log_event(1, 0);
        }

        if (sensor2_read > 0 && sensor2_state == 1) {
            sensor2_state = 0;
            log_event(2, 0);
        }

        usleep(POLL_MS * 1000 / HRTIME_PER_SEC);
    }

    gpiod_free_channel(gpio_fd);
    return EXIT_SUCCESS;
}

