#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <libgpiod.h>

#define SENSOR1_GPIO 17
#define SENSOR2_GPIO 27
#define LED_GPIO 22

#define LOG_FILE "obstacle_log.csv"
#define LOG_INTERVAL 100

int main(int argc, char *argv[]) {
    int sensor1, sensor2, led;
    struct tm tm;
    char timestamp[32];
    FILE *log_file;

    if (gpio_init() < 0) {
        perror("Failed to initialize gpiod");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpio_cleanup();
        return EXIT_FAILURE;
    }

    while (1) {
        gpio_set_dir(SENSOR1_GPIO, GPIO_OUT);
        gpio_set_dir(SENSOR2_GPIO, GPIO_OUT);
        gpio_set_dir(LED_GPIO, GPIO_OUT);

        gpio_output_harness(SENSOR1_GPIO, GPIO_OUT);
        gpio_output_harness(SENSOR2_GPIO, GPIO_OUT);
        gpio_output_harness(LED_GPIO, GPIO_OUT);

        gpio_set_level(SENSOR1_GPIO, 0);
        gpio_set_level(SENSOR2_GPIO, 0);

        gpio_read_pin(SENSOR1_GPIO, &sensor1);
        gpio_read_pin(SENSOR2_GPIO, &sensor2);

        if (sensor1 == 0 && sensor2 == 0) {
            gpio_set_level(LED_GPIO, 1);
        }

        if (fwrite(timestamp, sizeof(char), 19, log_file) != 19) {
            perror("Failed to write to log file");
            gpio_cleanup();
            fclose(log_file);
            return EXIT_FAILURE;
        }

        tm_gettime(&tm);
