#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <linux/gpio.h>
#include <pigpio.h>

#define GPIO_PIN 7
#define LED_PIN 11
#define SAMPLE_PERIOD_US 125
#define SAMPLE_RATE_HZ 8000

volatile sig_atomic_t quit = {0};

void signal_handler(int signum) {
    printf("Received SIGINT, cleaning up...\n");
    gpioOutput(LED_PIN, 0);
    pigpio_stop();
    exit(0);
}

int main() {
    int led_fd;
    int gpio_fd;
    struct sigaction sa;

    // Initialize signal handler
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    // Initialize pigpio
    gpioInitialise();
    if (pigpioInitialise() < 0) {
        perror("Failed to initialize pigpio");
        return EXIT_FAILURE;
    }

    // Initialize GPIO
    led_fd = open("/dev/gpiomem", O_RDWR);
    if (led_fd < 0) {
        perror("Failed to open /dev/gpiomem");
        return EXIT_FAILURE;
    }
    gpioSetMode(LED_PIN, PI_OUTPUT);

    gpioInitialise();
    if (gpioInitialise() < 0) {
        perror("Failed to initialize pigpio");
        return EXIT_FAILURE;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetup(GPIO_PIN, PI_ACTIVE_HIGH);

    // Set up timer for sampling
    struct itimerspec timer_spec;
    timer_spec.it_value.tv_sec = 0;
    timer_spec.it_value.tv_nsec = SAMPLE_PERIOD_US / 1000;
    timer_spec.it_repeat.ns = -1;
    if (timer_settimer(timer_fd, &timer_spec) < 0) {
        perror("Failed to set up timer");
        return EXIT_FAILURE;
    }
    timer_fd = timer_gettimer(timer_fd);

    while (!quit) {
        int reading = gpioRead(GPIO_PIN);
        if (reading == PI_INPUT_HIGH) {
            printf("Sound peak detected at %lu ms\n", (unsigned long)timer_gettime(timer_fd, NULL)->tv_sec * 1000000 + (unsigned long)timer_gettime(timer_fd, NULL)->tv_nsec / 1000000000);
            gpioWrite(LED_PIN, 1);
            usleep(100000); // Turn LED on for 100ms
        }
        usleep(SAMPLE_PERIOD_US / 1000); // Sleep for 125µs
    }

    // Clean up
    gpioStop();
    close(led_fd);
    close(gpio_fd);
    pigpioStop();
    return EXIT_SUCCESS;
}

