#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SILICON_LABS_ID 0x1A
#define SILICON_LABS_ADDR 0x5A
#define SILICON_LABS_REG_LSB 0x00
#define SILICON_LABS_REG_MSB 0x01
#define SILICON_LABS_DATA_WIDTH 16

#define LOG_INTERVAL 100 // ms

int main(int argc, char *argv[]) {
    int file;
    long result;
    struct i2c_rdwr_cfg cfg;
    uint8_t read_buf[2];
    uint16_t raw_data;

    // Initialize pigpio for GPIO control
    if (piGPIOInit() < 0) {
        perror("Failed to initialize pigpio");
        return EXIT_FAILURE;
    }

    // Initialize I2C bus
    file = open("/dev/i2c-1", O_RDWR);
    if (file == -1) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    cfg.device = SILICON_LABS_ADDR;
    cfg.flags = I2C_MSC_READ | I2C_MSC_DATA_16;
    result = ioctl(file, I2C_RD, &cfg);
    if (result < 0) {
        perror("Failed to configure I2C read");
        close(file);
        return EXIT_FAILURE;
    }

    // Check if sensor is present
    result = ioctl(file, I2C_MESSAGE, &cfg);
    if (result < 0) {
        perror("Failed to check sensor presence");
        close(file);
        return EXIT_FAILURE;
    }

    // Read LSB and MSB registers
    result = read(file, read_buf, 2);
    if (result != 2) {
        perror("Failed to read sensor data");
        close(file);
        return EXIT_FAILURE;
    }

    raw_data = (read_buf[0] << 8) | read_buf[1];

    // Log the raw sensor data
    printf("Raw light sensor data: 0x%04X\n", raw_data);

    // Continue reading every LOG_INTERVAL ms
    while (1) {
        usleep(LOG_INTERVAL * 1000 / 1000); // Sleep for LOG_INTERVAL ms
        // Read LSB and MSB registers again
        result = read(file, read_buf, 2);
        if (result != 2) {
            perror("Failed to read sensor data");
            break;
        }

        raw_data = (read_buf[0] << 8) | read_buf[1];
        printf("Raw light sensor data: 0x%04X\n", raw_data);
    }

    // Clean up and release resources
    piGPIOExit();
    close(file);

    return EXIT_SUCCESS;
}

