    pioInit();

    signal(SIGINT, sigint_handler);

    while (1) {
        int left, middle, right;

        // Initialize GPIO pins
        if (pioSetup(GPIO_LEFT, PIO_OUTPUT) < 0) {
            perror("Failed to initialize GPIO_LEFT");
            continue;
        }
        if (pioSetup(GPIO_MIDDLE, PIO_OUTPUT) < 0) {
            perror("Failed to initialize GPIO_MIDDLE");
            continue;
        }
        if (pioSetup(GPIO_RIGHT, PIO_OUTPUT) < 0) {
            perror("Failed to initialize GPIO_RIGHT");
            continue;
        }

        // Read sensor values
        if (pioGetMode(GPIO_LEFT) < 0) {
            perror("Failed to get mode for GPIO_LEFT");
            continue;
        }
        if (pioGetMode(GPIO_MIDDLE) < 0) {
            perror("Failed to get mode for GPIO_MIDDLE");
            continue;
        }
        if (pioGetMode(GPIO_RIGHT) < 0) {
            perror("Failed to get mode for GPIO_RIGHT");
            continue;
        }

        if (pioSetMode(GPIO_LEFT, PIO_INPUT) < 0) {
            perror("Failed to set GPIO_LEFT to input mode");
            continue;
        }
        if (pioSetMode(GPIO_MIDDLE, PIO_INPUT) < 0) {
            perror("Failed to set GPIO_MIDDLE to input mode");
            continue;
        }
        if (pioSetMode(GPIO_RIGHT, PIO_INPUT) < 0) {
            perror("Failed to set GPIO_RIGHT to input mode");
            continue;
        }

        // Read sensor values
        if (pioGet(GPIO_LEFT) < 0) {
            perror("Failed to read GPIO_LEFT");
            continue;
        }
        left = pioGet(GPIO_LEFT) ? 1 : 0;

        if (pioGet(GPIO_MIDDLE) < 0) {
            perror("Failed to read GPIO_MIDDLE");
            continue;
        }
        middle = pioGet(GPIO_MIDDLE) ? 1 : 0;

        if (pioGet(GPIO_RIGHT) < 0) {
            perror("Failed to read GPIO_RIGHT");
            continue;
        }
        right = pioGet(GPIO_RIGHT) ? 1 : 0;

        // Log sensor values
        printf("L:%d M:%d R:%d\n", left, middle, right);

        // Sleep for the specified interval
        usleep(POLL_INTERVAL * 1000);
    }

    pioClose();
    return 0;
}

