    int i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        gpiod_disable_input_pin_event(gpio_fd, GPIO_INPUT);
        close(gpio_fd);
        exit(EXIT_FAILURE);
    }

    struct i2c_client *client = i2c_client_new(i2c_fd, TTP226_I2C_ADDRESS);
    if (!client) {
        perror("Failed to create I2C client");
        close(i2c_fd);
        gpiod_disable_input_pin_event(gpio_fd, GPIO_INPUT);
        exit(EXIT_FAILURE);
    }

    // Initialize TTP226
    if (gpiod_try_set_input_pin_event(gpio_fd, TTP226_GPIO_PINS, GPIO_INPUT, 0) < 0) {
        perror("Failed to set input pin event");
        i2c_client_free(client);
        close(i2c_fd);
        gpiod_disable_input_pin_event(gpio_fd, GPIO_INPUT);
        exit(EXIT_FAILURE);
    }

    // Monotonic clock for timestamping
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);

    while (1) {
        // Read capacitive touch sensor data
        int sensor_data[8];
        if (gpiod_get_value(gpio_fd, sensor_data) < 0) {
            perror("Failed to read GPIO values");
            break;
        }

        // Timestamp
        long timestamp = (long)(ts.tv_sec - 1e-9) * 1000000 + ts.tv_nsec / 1000;

        // Output formatted data
        char output[1024];
        sprintf(output, "[%ld.000s] CH1=%d CH2=%d CH3=%d CH4=%d CH5=%d CH6=%d CH7=%d CH8=%d",
                (double)timestamp / 1000000, timestamp % 1000, sensor_data[0], sensor_data[1],
                sensor_data[2], sensor_data[3], sensor_data[4], sensor_data[5], sensor_data[6]);
        printf("%s", output);

        // Sleep before next read
        usleep(POLL_INTERVAL_MS * 1000 / 1000);
    }

    // Release resources
    gpiod_disable_input_pin_event(gpio_fd, GPIO_INPUT);
    i2c_client_free(client);
    close(i2c_fd);
    close(gpio_fd);

    return 0;
