#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>
#include <syslog.h>
#include <fcntl.h>
#include <errno.h>
#include <time.h>
#include <stdlib.h>
#include <stdbool.h>
#include <pigpio.h>

#define LED_RED 17
#define LED_GREEN 18
#define LED_BLUE 27
#define PWM_FREQ 1000
#define INTERVAL_STEPS 50
#define INTERVAL_SECONDS 5

void log_error(const char *msg) {
    syslog(LOG_ERR, "%s", msg);
}

void handle_sigint(int sig) {
    log_error("Received SIGINT, shutting down...");
    pigpio_stop();
    closelog();
    exit(0);
}

void handle_sigterm(int sig) {
    log_error("Received SIGTERM, shutting down...");
    pigpio_stop();
    closelog();
    exit(0);
}

int main() {
    int led_gpio = LED_RED;
    int red_channel = 0;
    int green_channel = 1;
    int blue_channel = 2;
    int pwm_gpio = led_gpio;

    pigpio_init(5); // Initialize pigpio with 5-127 GPIOs
    if (pigpio_init(5) == -1) {
        log_error("Failed to initialize pigpio");
        return 1;
    }

    // Seed random number generator from /dev/urandom
    srand(time(NULL));

    // Set up PWM for the LED
    pigpio_set_mode(pwm_gpio, PIGPIO_OUTPUT);
    pigpio_set_pwm_range(pwm_gpio, 0, 255);
    pigpio_set_pwm_freq(pwm_gpio, PWM_FREQ);

    while (1) {
        // Generate random hue values
        int hue_red = rand() % 256;
        int hue_green = rand() % 256;
        int hue_blue = rand() % 256;

        // Perform 50-step linear interpolation over 5 seconds
        for (int i = 0; i < INTERVAL_STEPS; i++) {
            int t = i * (1.0 / INTERVAL_STEPS);
            int red = hue_red + t * (255 - hue_red);
            int green = hue_green + t * (255 - hue_green);
            int blue = hue_blue + t * (255 - hue_blue);

            // Clamp values to 0-255 range
            red = constrain(red, 0, 255);
            green = constrain(green, 0, 255);
            blue = constrain(blue, 0, 255);

            // Set PWM values for the LED
            pigpio_set_duty_cycle(pwm_gpio, red);
            pigpio_set_duty_cycle(pwm_gpio + 1, green);
            pigpio_set_duty_cycle(pwm_gpio + 2, blue);

            usleep(100000); // Sleep for 100 milliseconds
        }
    }

    pigpio_stop();
    closelog();
    syslog(LOG_CLOSE_ALL, "syslog closed");

    return 0;
}

