#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define BH1750_ADDRESS 0x40
#define WS2812B_PIN 18
#define PWM_FREQUENCY 500
#define PWM_PERIOD_US (1000000 / PWM_FREQUENCY)
#define LED_COUNT 10

#define I2C_BUS "/dev/i2c-1"
#define PI_BUS "/dev/piGPIO"

int i2c_fd;
int gpio_fd;

int read_bh1750(uint8_t *lux) {
    char command[3] = {0x43, 0x00, 0x00}; // Read command
    write(i2c_fd, command, 3);
    delay(180); // Wait for sensor to respond
    read(i2c_fd, lux, 1);
    return 0;
}

int map_lux_to_brightness(uint16_t lux, uint8_t *brightness) {
    *brightness = (uint8_t)((lux / 100.0) * 255);
    return 0;
}

void set_ws2812b_brightness(uint8_t *brightness) {
    for (int i = 0; i < LED_COUNT; i++) {
        gpio_write(WS2812B_PIN, brightness[i]);
    }
}

int main(int argc, char *argv[]) {
    int ret;
    int i;
    uint8_t brightness[LED_COUNT];

    pigpio_init(PI_BUS);
    if ((ret = pigpio_setup(WS2812B_PIN, PWM_FREQUENCY, 50)) != 0) {
        fprintf(stderr, "Failed to setup GPIO for WS2812B\n");
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd == -1) {
        perror("Failed to open I2C bus");
        return 1;
    }

    while (1) {
        uint8_t lux;
        if (read_bh1750(&lux) != 0) {
            fprintf(stderr, "Failed to read from BH1750\n");
            continue;
        }

        map_lux_to_brightness(lux, brightness);

        if (pigpio_write_register(WS2812B_PIN, 0) != 0) {
            fprintf(stderr, "Failed to write to WS2812B\n");
            continue;
