#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/wait.h>
#include <signal.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x40
#define GPIO_PIN 18
#define BLINK_FREQ 800000
#define RETRY_COUNT 3
#define RETRY_DELAY 100000

#define VEML7700_REG_DATA 0x00
#define VEML7700_REG_STATUS 0x01
#define VEML7700_REG_CONFIG 0x02
#define VEML7700_REG_LUX 0x03

#define WS2812_PIN 5

int i2c_fd;
int gpio_pin;

static void sigint_handler(int sig) {
    printf("Received SIGINT, turning off LEDs and exiting...\n");
    gpio_output(0);
    close(i2c_fd);
    exit(0);
}

static void sigterm_handler(int sig) {
    printf("Received SIGTERM, turning off LEDs and exiting...\n");
    gpio_output(0);
    close(i2c_fd);
    exit(0);
}

void gpio_init() {
    if (open("/dev/gpiomem", O_RDWR) < 0) {
        perror("Failed to open /dev/gpiomem");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, WDEV_SET_MODE, I2C_SLAVE_ONLY) < 0) {
        perror("Failed to set I2C mode");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE_GAIN, I2C_SLAVE_GAIN_1) < 0) {
        perror("Failed to set I2C slave gain");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE_ENABLE, I2C_ADDR) < 0) {
        perror("Failed to enable I2C slave");
        exit(EXIT_FAILURE);
    }

    gpio_pin = GPIO_PIN;
    if (ioctl(i2c_fd, I2C_SMBUS_WRITE_ONE_REG, VEML7700_ADDR | VEML7700_REG_CONFIG) < 0) {
        perror("Failed to write to VEML7700_REG_CONFIG");
        exit(EXIT_FAILURE);
    }
    if (ioctl(i2c_fd, I2C_SMBUS_WRITE_BYTE_DATA, 0x00) < 0) {
        perror("Failed to write to VEML7700_REG_CONFIG");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SMBUS_WRITE_ONE_REG, VEML7700_ADDR | VEML7700_REG_STATUS) < 0) {
        perror("Failed to write to VEML7700_REG_STATUS");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SMBUS_WRITE_BYTE_DATA, 0x00) < 0) {
        perror("Failed to write to VEML7700_REG_STATUS");
        exit(EXIT_FAILURE);
    }
}

int gpio_output(int state) {
    if (state == 0) {
        if (write(GPIO_PIN, LOW) < 0) {
            perror("Failed to set GPIO pin low");
            return -1;
        }
    } else {
        if (write(GPIO_PIN, HIGH) < 0) {
            perror("Failed to set GPIO pin high");
            return -1;
        }
    }
    return 0;
}

int read_veml7700_lux() {
    int ret = 0;
    int data;
    for (int i = 0; i < 10; i++) {
        ret = ioctl(i2c_fd, I2C_SMBUS_READ_BYTE_DATA, VEML7700_ADDR | VEML7700_REG_LUX);
        if (ret < 0) {
            if (errno == EIO || errno == E2BIG) {
                ret = 0;
