#define BH1750_ADDRESS 0x40
#define LED_PIN 17
#define BUFFER_SIZE 60
#define MIN_FREQ_LUX 0.5
#define MAX_FREQ_LUX 5.0

typedef struct {
    int lux;
    struct timespec timestamp;
} LightReading;

typedef struct {
    LightReading buffer[BUFFER_SIZE];
    int head;
    int tail;
} LightBuffer;

LightBuffer buffer;
int buffer_size = BUFFER_SIZE;
int led_file = -1;

void i2c_init() {
    int file = open("/dev/i2c-1", O_RDWR);
    if (file < 0) {
        perror("Failed to open i2c bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(file, I2C_SLAVE, BH1750_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(file);
        exit(EXIT_FAILURE);
    }
}

void led_init() {
    led_file = open("/dev/gpiomem", O_RDWR | O_CREAT | OWNER | O_SYNC, 0666);
    if (led_file < 0) {
        perror("Failed to open GPIO memory file");
        exit(EXIT_FAILURE);
    }

    if (ioctl(led_file, GPFSEL, LED_PIN) < 0) {
        perror("Failed to set GPIO pin direction");
        close(led_file);
        exit(EXIT_FAILURE);
    }

    if (ioctl(led_file, GPFOUT, LED_PIN) < 0) {
        perror("Failed to set GPIO output");
        close(led_file);
        exit(EXIT_FAILURE);
    }
}

void blink_led(double avg_lux) {
    long period = (long)(1.0 / (avg_lux / 1000.0 * MAX_FREQ_LUX));
    struct itimerspec timer_req;
    timer_req.it_value.tv_sec = 0;
    timer_req.it_value.tv_nsec = period * 1000000;
    timer_req.it_interval.tv_sec = 0;
    timer_req.it_interval.tv_nsec = 0;

    if (timer_settimer(timer_file, &timer_req) < 0) {
        perror("Failed to set timer");
        exit(EXIT_FAILURE);
    }
}

void* read_light_sensor(void* arg) {
    while (1) {
        int result = readl(led_file + 0);
        if (result == -ENOTTY) {
            perror("Failed to access GPIO");
            continue;
        }

        if (result == 0) {
            blink_led(0.0);
        } else {
            blink_led(result / 100.0);
        }

        int lux = readl(led_file + 1);
        if (lux == -EIO) {
            perror("Failed to read light sensor");
            continue;
        }

        LightReading reading;
        reading.lux = lux;
        reading.timestamp = current_time();

        pthread_mutex_lock(&mutex);
        if (buffer.head == buffer.tail) {
            buffer.tail++;
        }
        buffer.buffer[buffer.head] = reading;
        buffer.head++;
        pthread_mutex_unlock(&mutex);
    }
    return NULL;
}

double compute_average_lux(void) {
    double sum = 0.0;
    int count = 0;
    for (int i = 0; i < buffer_size; i++) {
        sum += buffer.buffer[i].lux;
        count++;
    }
    return sum / count;
}

int main(int argc, char* argv[]) {
    signal(SIGINT, signal_handler);

    i2c_init();
    led_init();

    int timer_file = open("2", O_WRONLY | O_CREAT | OWNER | O_SYNC, 0666);
    if (timer_file < 0) {
        perror("Failed to open timer file");
        exit(EXIT_FAILURE);
    }

    pthread_t thread;
    if (pthread_create(&thread, NULL, read_light_sensor, NULL) != 0) {
        perror("Failed to create thread");
        close(timer_file);
        exit(EXIT_FAILURE);
    }

    while (1) {
        double avg_lux = compute_average_lux();
        blink_led(avg_lux);
        usleep(100000);
    }

    pthread_join(thread, NULL);
    close(timer_file);
    close(led_file);
    close(file);

    return 0;
}

void signal_handler(int signum) {
    printf("Received signal %d, cleaning up and exiting...\n", signum);
    pthread_join(read_light_sensor_thread, NULL);
    close(file);
    close(led_file);
    exit(0);
}

timespec current_time(void) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    return ts;
}

