    timer_req.it_interval.tv_sec = 0;
    timer_req.it_interval.tv_nsec = 0;

    if (timer_settimer(timer_file, &timer_req) < 0) {
        perror("Failed to set timer");
        exit(EXIT_FAILURE);
    }
}

void* read_light_sensor(void* arg) {
    while (1) {
        int result = readl(led_file + 0);
        if (result == -ENOTTY) {
            perror("Failed to access GPIO");
            continue;
        }

        if (result == 0) {
            blink_led(0.0);
        } else {
            blink_led(result / 100.0);
        }

        int lux = readl(led_file + 1);
        if (lux == -EIO) {
            perror("Failed to read light sensor");
            continue;
        }

        LightReading reading;
        reading.lux = lux;
        reading.timestamp = current_time();

        pthread_mutex_lock(&mutex);
        if (buffer.head == buffer.tail) {
            buffer.tail++;
        }
        buffer.buffer[buffer.head] = reading;
        buffer.head++;
        pthread_mutex_unlock(&mutex);
    }
    return NULL;
}

double compute_average_lux(void) {
    double sum = 0.0;
    int count = 0;
    for (int i = 0; i < buffer_size; i++) {
        sum += buffer.buffer[i].lux;
        count++;
    }
    return sum / count;
}

int main(int argc, char* argv[]) {
    signal(SIGINT, signal_handler);

    i2c_init();
    led_init();

    int timer_file = open("2", O_WRONLY | O_CREAT | OWNER | O_SYNC, 0666);
    if (timer_file < 0) {
        perror("Failed to open timer file");
        exit(EXIT_FAILURE);
    }

    pthread_t thread;
    if (pthread_create(&thread, NULL, read_light_sensor, NULL) != 0) {
        perror("Failed to create thread");
        close(timer_file);
        exit(EXIT_FAILURE);
    }

    while (1) {
        double avg_lux = compute_average_lux();
        blink_led(avg_lux);
        usleep(100000);
    }

    pthread_join(thread, NULL);
    close(timer_file);
    close(led_file);
    close(file);

    return 0;
}

void signal_handler(int signum) {
    printf("Received signal %d, cleaning up and exiting...\n", signum);
    pthread_join(read_light_sensor_thread, NULL);
    close(file);
    close(led_file);
    exit(0);
}

timespec current_time(void) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    return ts;
}
```

This code initializes the I2C bus and GPIO, sets up a circular buffer for storing light readings, and a function to blink an LED based on the average lux. It reads the light sensor every second, computes the average lux, and adjusts the LED blink frequency accordingly. If a sensor read fails, it skips the sample and attempts a new read on the next iteration. The program cleansly handles SIGINT (Ctrl+C) by joining the sensor reading thread, closing file descriptors, and exiting.

