#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/statfs.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <errno.h>
#include <string.h>
#include <libgpiod.h>

#define GPIO_DATA 17
#define GPIO_CLOCK 18
#define GPIO_LATCH 27
#define SEGMENT_A 0
#define SEGMENT_B 1
#define SEGMENT_C 2
#define SEGMENT_D 3
#define SEGMENT_E 4
#define SEGMENT_F 5
#define SEGMENT_G 6
#define SEGMENT_DP 7

int main() {
    int fd;
    struct statfs statb;

    // Open /dev/mem for writing
    fd = open("/dev/mem", O_RDWR | O_SYNC);
    if (fd == -1) {
        perror("open /dev/mem");
        exit(EXIT_FAILURE);
    }

    // Get the size of the memory region
    if (fstatfs(fd, &statb) == -1) {
        perror("fstatfs");
        close(fd);
        exit(EXIT_FAILURE);
    }

    // Map the memory region for writing
    if (mmap(NULL, statb.f_bsize, PROT_WRITE, MAP_SHARED, fd, 0) == MAP_FAILED) {
        perror("mmap");
        close(fd);
        exit(EXIT_FAILURE);
    }

    // Initialize GPIO pins
    gpio_init(GPIO_DATA, GPIO_OUTPUT);
    gpio_init(GPIO_CLOCK, GPIO_OUTPUT);
    gpio_init(GPIO_LATCH, GPIO_OUTPUT);

    // Set up 74HC595 shift register pins
    gpio_set_level(GPIO_DATA, 0);
    gpio_set_level(GPIO_CLOCK, 0);
    gpio_set_level(GPIO_LATCH, 0);

    // Shift out the digit '5'
    for (int i = 0; i < 8; i++) {
        gpio_set_level(GPIO_DATA, 1);
        gpio_pulse_short(GPIO_CLOCK, 1000);
        gpio_pulse_short(GPIO_LATCH, 1000);
        gpio_set_level(GPIO_DATA, 0);
        gpio_pulse_short(GPIO_CLOCK, 1000);
        gpio_pulse_short(GPIO_LATCH, 1000);
    }

    // Blink the digit '5'
    while (1) {
        // Turn on the digit
        gpio_set_level(GPIO_DATA, 1);
        gpio_pulse_short(GPIO_CLOCK, 500);
        gpio_pulse_short(GPIO_LATCH, 500);

        // Wait for 500ms
        usleep(500000);

        // Turn off the digit
        gpio_set_level(GPIO_DATA, 0);
        gpio_pulse_short(GPIO_CLOCK, 500);
        gpio_pulse_short(GPIO_LATCH, 500);

        // Wait for 500ms
        usleep(500000);
    }

    // Release resources and close the file descriptor
    munmap(NULL, statb.f_bsize);
    close(fd);

    // Cleanly exit
    return 0;
}

