#define LED_PIN 11
#define BUTTON_PIN 12

int main() {
    int led_fd, button_fd;
    struct gpiod_digital_out_attr led_attr = GPIOD_DIGITAL_OUT_TYPE_ALT(0);
    struct gpiod_digital_in_attr button_attr = GPIOD_DIGITAL_IN_TYPE_ALT(0, GPIOD_DIGITAL_IN_PULLUP);

    led_fd = gpiod_open(LED_PIN, &led_attr);
    if (led_fd < 0) {
        perror("Failed to open LED GPIO");
        exit(EXIT_FAILURE);
    }

    button_fd = gpiod_open(BUTTON_PIN, &button_attr);
    if (button_fd < 0) {
        perror("Failed to open button GPIO");
        gpiod_close(led_fd);
        exit(EXIT_FAILURE);
    }

    gpiod_digital_out_write(led_fd, 0); // Initially turn LED off

    gpiod_edge_detect_enable(button_fd, GPIOD_EDGE_FALLING);

    gpiod_chip_init(0);
    gpiod_chip_open(0);

    while (1) {
        int result = gpiod_get_value(button_fd);
        if (result < 0) {
            perror("Failed to read button state");
            break;
        }

        if (result == 0) { // Falling edge detected
            gpiod_digital_out_write(led_fd, 1); // Turn LED on
            printf("Button pressed, LED ON\n");
            usleep(1000000); // Wait for 1 second
            gpiod_digital_out_write(led_fd, 0); // Turn LED off
            gpiod_chip_close(0);
            gpiod_close(button_fd);
            gpiod_close(led_fd);
            exit(0);
        }

        usleep(1000000); // Wait for 1 second
    }

    gpiod_chip_close(0);
    gpiod_close(led_fd);
    gpiod_close(button_fd);

    return 0;
}

