#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define LED_PIN 29
#define DELAY_MS 750

void signal_handler(int signum) {
    gpioOutput(LED_PIN, 0);
    pigiosync();
    exit(0);
}

int main(int argc, char *argv[]) {
    int led_gpio = LED_PIN;
    int state = 1;

    // Initialize pigpio library
    if (piGPIOInit() < 0) {
        perror("Failed to initialize pigpio library");
        exit(EXIT_FAILURE);
    }

    // Set up signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Blink LED
    while (1) {
        gpioWrite(led_gpio, state);
        printf("LED ON\n");
        fflush(stdout);
        state = !state;
        printf("LED OFF\n");
        fflush(stdout);
        sleep(DELAY_MS / 1000.0); // Use time_sleep equivalent
    }

    // Clean up and exit
    pigEOF();
    return EXIT_SUCCESS;
}

