#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>
#include <errno.h>

#define GPIO_LED 24
#define GPIO_BUTTON 15

int main(int argc, char *argv[]) {
    int fd;
    struct gpio_req req;
    int value;

    fd = open("/dev/gpioctl", O_RDWR);
    if (fd == -1) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    req.direction = GPIO_OUT;
    req.pin = GPIO_LED;
    if (ioctl(fd, GPIOPINGET, &req) == -1) {
        perror("GPIOPINGET");
        close(fd);
        exit(EXIT_FAILURE);
    }

    req.direction = GPIO_IN;
    req.pin = GPIO_BUTTON;
    req.mode = GPIO_MODE_INPUT;
    req.pull = GPIO_PULLDOWN;
    if (ioctl(fd, GPIOPINGET, &req) == -1) {
        perror("GPIOPINGET");
        close(fd);
        exit(EXIT_FAILURE);
    }

    while (1) {
        value = read(fd, &req);
        if (value == -1) {
            perror("read");
            exit(EXIT_FAILURE);
        }

        if (value & GPIO_INPUT_PIN) {
            // Button is pressed
            write(fd, &req, sizeof(req));
            req.direction = GPIO_OUT;
            req.pin = GPIO_LED;
            req.value = 1;
            if (ioctl(fd, GPIOPUT, &req) == -1) {
                perror("GPIOPUT");
                exit(EXIT_FAILURE);
            }
            usleep(500 * 1000 / HRTIME_FREQ); // 500ms on
        } else {
            // Button is released
            write(fd, &req, sizeof(req));
            req.direction = GPIO_OUT;
            req.pin = GPIO_LED;
            req.value = 0;
            if (ioctl(fd, GPIOPUT, &req) == -1) {
                perror("GPIOPUT");
                exit(EXIT_FAILURE);
            }
        }
    }

    close(fd);
    return 0;
}

