#define GPIO_BASE 0x20208000
#define GPIO_COUNT 3
#define PWM_FREQ 100
#define PWM_PERIOD (1000000 / PWM_FREQ)
#define PWM_TIMER_ID 0
#define PWM_CHANNEL_COUNT 3

#define PIN_RED 24
#define PIN_GREEN 23
#define PIN_BLUE 12

void signal_handler(int signum) {
    int i;
    for (i = 0; i < GPIO_COUNT; i++) {
        gpioSetMode(GPIO_BASE + i, GPIO_MODE_OUTPUT);
    }
    for (i = 0; i < GPIO_COUNT; i++) {
        gpioSetDrive(GPIO_BASE + i, 0);
    }
}

void pwm_init(void) {
    int ret;
    ret = ppi_init(GPIO_BASE, GPIO_COUNT);
    if (ret < 0) {
        perror("ppi_init");
        exit(EXIT_FAILURE);
    }
}

void pwm_set_period(unsigned long period) {
    int ret;
    ret = ppi_set_period(GPIO_BASE, period);
    if (ret < 0) {
        perror("ppi_set_period");
        exit(EXIT_FAILURE);
    }
}

void pwm_set_freq(unsigned long freq) {
    int ret;
    ret = ppi_set_freq(GPIO_BASE, freq);
    if (ret < 0) {
        perror("ppi_set_freq");
        exit(EXIT_FAILURE);
    }
}

void pwm_set_channel(int channel, int value) {
    int ret;
    ret = ppi_set_channel(GPIO_BASE, channel, value);
    if (ret < 0) {
        perror("ppi_set_channel");
        exit(EXIT_FAILURE);
    }
}

void pwm_start(void) {
    int ret;
    ret = ppi_start(GPIO_BASE, PWM_TIMER_ID);
    if (ret < 0) {
        perror("ppi_start");
        exit(EXIT_FAILURE);
    }
}

void pwm_stop(void) {
    int ret;
    ret = ppi_stop(GPIO_BASE, PWM_TIMER_ID);
    if (ret < 0) {
        perror("ppi_stop");
        exit(EXIT_FAILURE);
    }
}

void random_color(int *red, int *green, int *blue) {
    srand(time(NULL));
    *red = rand() % 101;
    *green = rand() % 101;
    *blue = rand() % 101;
}

void change_color(int *red, int *green, int *blue) {
    int temp;
    temp = *red;
    *red = *green;
    *green = *blue;
    *blue = temp;
}

int main(void) {
    int red, green, blue;
    int i;

    signal(SIGINT, signal_handler);

    pwm_init();
    pwm_set_period(PWM_PERIOD);
    pwm_set_freq(PWM_FREQ);
