#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>
#include <errno.h>

#define I2C_BUS 1
#define I2C_ADDR 0x68  // LSM303DLHC default I2C address
#define LOG_FILE "impact_log.txt"
#define THRESHOLD 2.0
#define POLL_INTERVAL_US 10000  // 10 Hz
#define PULSE_DURATION_MS 50

int i2c_fd;
int gpio_pin = 17;

void log_data(const char *timestamp, double ax, double ay, double az) {
    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        perror("Failed to open log file");
        return;
    }
    time_t now = time(NULL);
    fprintf(file, "%llu %f %f %f\n", now, ax, ay, az);
    fclose(file);
}

void impact_interrupt() {
    gpioWrite(gpio_pin, HIGH);
    sleep(0.05);
    gpioWrite(gpio_pin, LOW);
}

int main(int argc, char *argv[]) {
    int i2c_result;
    int gpio_result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("Failed to initialize pigpio");
        return EXIT_FAILURE;
    }

    // Open I2C bus
    i2c_result = open("/dev/i2c-1", O_RDWR);
    if (i2c_result < 0) {
        perror("Failed to open I2C bus");
        gpioDeinitialise();
        return EXIT_FAILURE;
    }

    // Set I2C bus parameters
    ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR);

    // Check if sensor is present
    if (ioctl(i2c_fd, I2C_MESSAGE, "A2 01 00 00 00 00 00 00 00 00", 16) < 0) {
        perror("Sensor not present or error reading from sensor");
        close(i2c_fd);
        gpioDeinitialise();
        return EXIT_FAILURE;
    }

    // Configure GPIO pin as output
    gpioSetMode(gpio_pin, PI_OUTPUT);

    // Main loop
    while (1) {
        // Read accelerometer data
        uint8_t buffer[6];
        i2c_result = read(i2c_fd, buffer, 6);
        if (i2c_result < 0) {
            perror("I2C read failed");
            break;
        }

        // Compute G-force magnitude
        double ax = buffer[0] << 8 | buffer[1];
        double ay = buffer[2] << 8 | buffer[3];
        double az = buffer[4] << 8 | buffer[5];
        double g_force = sqrt(ax * ax + ay * ay + az * az);

        // Log data
        log_data(time(NULL), ax, ay, az);

        // Check for impact threshold
        if (g_force > THRESHOLD) {
            impact_interrupt();
        }

        // Poll delay
        usleep(POLL_INTERVAL_US / 1000);
    }

    // Clean up resources
    close(i2c_fd);
    gpioDeinitialise();

    return EXIT_SUCCESS;
}

