#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <sys/epoll.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>

#define I2C_BUS 1
#define ALS_ADDRESS 0x5A
#define LED_PIN 18
#define LOG_FILE "color_log.csv"
#define SAMPLE_INTERVAL 500
#define LED_PWM_CHANNEL 0

#define MAX_LOG_ENTRIES 1000

typedef struct {
    struct timespec timestamp;
    uint16_t als;
    uint16_t red;
    uint16_t green;
    uint16_t blue;
} LogEntry;

static LogEntry log_entries[MAX_LOG_ENTRIES];
static int log_entries_written = 0;
static int log_file_fd = -1;

static pthread_t log_thread;
static int log_thread_running = 1;

static struct epoll_event ev, ev_read;
static struct i2c_rdwr_t *i2c_handle;

void handle_signal(int signum) {
    if (log_thread_running) {
        log_thread_running = 0;
        epoll_ctl(epoll_base, EPOLLIN, log_file_fd, &ev_read);
    }
    close(log_file_fd);
    pigpio_terminate();
    exit(0);
}

void signal_handler(int signum) {
    handle_signal(signum);
}

void init_i2c() {
    int file_fd = open("/dev/i2c-1", O_RDWR);
    if (file_fd < 0) {
        perror("open /dev/i2c-1");
        exit(EXIT_FAILURE);
    }

    if (ioctl(file_fd, I2C_SLAVE, ALS_ADDRESS) < 0) {
        perror("ioctl I2C_SLAVE");
        close(file_fd);
        exit(EXIT_FAILURE);
    }

    i2c_handle = i2c_rdwr_open(file_fd, 0x5A);
    if (!i2c_handle) {
        perror("i2c_rdwr_open");
        close(file_fd);
        exit(EXIT_FAILURE);
    }
}

void log_entry(uint16_t als, uint16_t red, uint16_t green, uint16_t blue) {
    struct timespec now;
    clock_gettime(CLOCK_REALTIME, &now);

    LogEntry *entry = &log_entries[log_entries_written];
    entry->timestamp = now;
    entry->als = als;
    entry->red = red;
    entry->green = green;
    entry->blue = blue;
    log_entries_written++;

    if (log_entries_written >= MAX_LOG_ENTRIES) {
        log_entries_written = 0;
    }

    if (log_file_fd < 0) {
        log_file_fd = open(LOG_FILE, "a");
        if (log_file_fd < 0) {
            perror("open color_log.csv");
            exit(EXIT_FAILURE);
        }
    }

    if (write(log_file_fd, "timestamp,ALS,Red,Green,Blue\n", 16) < 0) {
        perror("write to color_log.csv");
        exit(EXIT_FAILURE);
    }

    if (write(log_file_fd, "%,u,%u,%u,%u\n", entry->timestamp.tv_sec, entry->als, entry->red, entry->green, entry->blue) < 0) {
        perror("write to color_log.csv");
        exit(EXIT_FAILURE);
    }
}

void read_sensor() {
    uint16_t als_lsb, als_msb;
    ssize_t read_bytes = i2c_rdwr_read(i2c_handle, &als_lsb, 1);
    if (read_bytes < 1) {
        perror("i2c_rdwr_read failed");
        return;
    }

    read_bytes = i2c_rdwr_read(i2c_handle, &als_msb, 1);
    if (read_bytes < 1) {
        perror("i2c_rdwr_read failed");
        return;
    }

    uint16_t als = (uint16_t)als_lsb | (uint16_t)als_msb << 8;
    log_entry(als, 0, 0, 0);

    // Control LED brightness based on ambient light
    uint8_t brightness = (uint8_t)((als / 1000.0) * 255);
    pigpio_set_duty_cycle(LED_PWM_CHANNEL, brightness);
}

void setup_led_pwm() {
    if (pigpio_init(5) < 0) {
        perror("pigpio_init");
        exit(EXIT_FAILURE);
    }

    pigpio_set_mode(LED_PWM_CHANNEL, PIGIO_OUTPUT);
}

void cleanup() {
    if (log_file_fd >= 0) {
        close(log_file_fd);
    }

    if (i2c_handle) {
        i2c_rdwr_close(i2c_handle);
    }

    pigpio_terminate();
}

int main() {
    init_i2c();
    setup_led_pwm();

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_thread = pthread_create(&log_thread, NULL, log_thread_func, NULL);
    if (log_thread < 0) {
        perror("pthread_create");
        exit(EXIT_FAILURE);
    }

    while (1) {
        read_sensor();
        usleep(SAMPLE_INTERVAL * 1000 / 1000);
    }

    cleanup();
    return 0;
}

void *log_thread_func(void *arg) {
    while (log_thread_running) {
        read_sensor();
    }

    log_thread_running = 0;
    epoll_ctl(epoll_base, EPOLLIN, -1, NULL);

    return NULL;
}

