#define I2C_BUS 1
#define I2C_ADDR 0x68  // Adafruit FXOS8700CQ default I2C address
#define WHO_AM_ID "WHO_AM_I"
#define IMPACT_THRESHOLD 2.0
#define LOG_FILE "impact_log.txt"
#define LOG_FORMAT "%Y-%m-%d %H:%M:%S,x,y,z,magnitude"
#define LOG_LINE_LENGTH 40
#define LOG_FILE_BUFFER_SIZE 1024

int i2c_fd;

void init_i2c() {
    int file;
    file = open("/dev/i2c-1", O_RDWR);
    if (file < 0) {
        perror("open /dev/i2c-1");
        exit(EXIT_FAILURE);
    }

    if (ioctl(file, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        exit(EXIT_FAILURE);
    }

    i2c_fd = file;
}

int verify_who_am_i() {
    char who_am_id_buf[10];
    ssize_t ret = read(i2c_fd, who_am_id_buf, sizeof(who_am_id_buf));
    if (ret == -1) {
        perror("read from I2C slave");
        return -1;
    }
    if (strcmp(who_am_id, who_am_id_buf) != 0) {
        fprintf(stderr, "Error: WHO_AM_ID mismatch\n");
        exit(EXIT_FAILURE);
    }
    return 0;
}

int configure_sensor() {
    // Configure sensor for ±2g range and 200Hz output
    // This step is specific to the library used and might vary
    // Here, we assume a function 'fxos8700_set_config' exists
    if (fxos8700_set_config(i2c_fd, FXOS8700_RANGE_2G, FXOS8700_OUTPUT_RATE_200Hz) < 0) {
        fprintf(stderr, "Error configuring sensor\n");
        return -1;
    }
    return 0;
}

void log_impact(const char *timestamp, double x, double y, double z, double magnitude) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening impact_log.txt\n");
        return;
    }

    struct timeval tv;
    gettimeofday(&tv, NULL);
    char timestamp_str[LOG_LINE_BUFFER_SIZE];
    sprintf(timestamp_str, "%04d-%02d-%02d %02d:%02d:%02d",
            tv.tv_year + 1900, tv.tv_mon + 1, tv.tv_day,
            tv.tv_hour, tv.tv_min, tv.tv_sec);

    fprintf(log_file, LOG_FORMAT, timestamp_str, x, y, z, magnitude);
    fclose(log_file);
}

int main(int argc, char *argv[]) {
    int ret;
