#define I2C_BUS 1
#define I2C_ADDR 0x68  // GY-50 L3G4200D gyroscope I2C address
#define LOG_FILE "gyro_log.txt"
#define CALIBRATION_SAMPLES 100
#define LOG_RATE 20  // 20 Hz, 50 ms period
#define LOG_PERIOD 50  // 50 ms

#define OFFSET_CALIBRATION_SAMPLES 10

typedef struct {
    int calibrated_x;
    int calibrated_y;
    int calibrated_z;
} CalibratedGyro;

int main(int argc, char *argv[]) {
    int i2c_fd, cal_x, cal_y, cal_z;
    struct timespec ts;
    CalibratedGyro calibrated_values;
    char log_entry[100];

    if (argc != 2) {
        fprintf(stderr, "Usage: %s <command> [start|stop|status]\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    if (strcmp(argv[1], "start") == 0) {
        start_calibration();
    } else if (strcmp(argv[1], "stop") == 0) {
        stop_calibration();
    } else if (strcmp(argv[1], "status") == 0) {
        status_check();
    }

    close(i2c_fd);
    return 0;

start_calibration:
    i2c_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (i2c_fd == -1) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    cal_x = 0;
    cal_y = 0;
    cal_z = 0;

    while (cal_x < OFFSET_CALIBRATION_SAMPLES) {
        if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
            perror("ioctl");
            exit(EXIT_FAILURE);
        }

        if (ioctl(i2c_fd, I2C_MEM_READ, 0x24) < 0) {
            perror("ioctl");
            exit(EXIT_FAILURE);
        }

        calibrated_values.calibrated_x = readl(i2c_fd);
        calibrated_values.calibrated_y = readl(i2c_fd);
        calibrated_values.calibrated_z = readl(i2c_fd);

        cal_x++;
        if (cal_x >= OFFSET_CALIBRATION_SAMPLES) {
            break;
        }
    }

    calibrated_values.calibrated_x -= readl(i2c_fd);
    calibrated_values.calibrated_y -= readl(i2c_fd);
    calibrated_values.calibrated_z -= readl(i2c_fd);

    while (1) {
        ts.tv_sec = 0;
        ts.tv_nsec = 1000000000;  // ISO 8601 timestamp

        if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
            perror("ioctl");
            exit(EXIT_FAILURE);
        }

        if (ioctl(i2c_fd, I2C_MEM_READ, 0x2C) < 0) {
            perror("ioctl");
            exit(EXIT_FAILURE);
        }

        int16_t raw_x = readl(i2c_fd);
        int16_t raw_y = readl(i2c_fd);
        int16_t raw_z = readl(i2c_fd);

        raw_x -= calibrated_values.calibrated_x;
        raw_y -= calibrated_values.calibrated_y;
        raw_z -= calibrated_values.calibrated_z;

        snprintf(log_entry, sizeof(log_entry), "%s%0.3f;%0.3f;%0.3f;%s",
                (cal_x >= OFFSET_CALIBRATION_SAMPLES) ? "ALERT: " : "",
                raw_x / 100.0,
                raw_y / 100.0,
                raw_z / 100.0,
                (cal_x >= OFFSET_CALIBRATION_SAMPLES) ? "ALERT" : "");

        if (write(i2c_fd, log_entry, strlen(log_entry)) < 0) {
            perror("write");
            exit(EXIT_FAILURE);
        }

        cal_x++;
        if (cal_x >= CALIBRATION_SAMPLES) {
            cal_x = 0;
        }

        usleep(LOG_PERIOD * 1000000 / 20);  // 50 ms period
    }

    close(i2c_fd);
    return 0;

stop_calibration:
    close(i2c_fd);
    return 0;

status_check:
    close(i2c_fd);
    return 0;
}

int verify_sensor_presence() {
    int who_am_i;
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("ioctl");
        return -1;
