        log_data(fmod(timestamp, 1000000) / 1000000.0);
        toggle_led(0); // Check all axes
        usleep(100000); // Sleep for 100ms
    }

    close(i2c_fd);
    piGPIO_remove(handle);
    fclose(stdout);
    return 0;
}

void init_i2c() {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        log_error("Failed to open i2c bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_ADDR) < 0) {
        log_error("Failed to set I2C slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

void init_gpio() {
    handle = piGPIO_open(LED_PIN);
    if (!handle) {
        log_error("Failed to initialize GPIO");
        exit(EXIT_FAILURE);
    }
}

void read_adxl345() {
    uint8_t buffer[6];
    ret = read(i2c_fd, buffer, 6);
    if (ret != 6) {
        log_error("Failed to read from ADXL345");
        return;
    }

    if (buffer[0] != 0x29) { // Device ID should be 0x29
        log_error("ADXL345 device ID mismatch");
        return;
    }

    check_range();

    // Read acceleration data (x, y, z) in 16-bit little-endian format
    ret = read(i2c_fd, buffer + 2, 2);
    if (ret != 2) {
        log_error("Failed to read acceleration data");
        return;
    }

    int16_t ax = (buffer[0] << 8) | buffer[1];
    int16_t ay = (buffer[2] << 8) | buffer[3];
    int16_t az = (buffer[4] << 8) | buffer[5];

    float x = (float)ax / 16384.0 * G_PER_UNIT;
    float y = (float)ay / 16384.0 * G_PER_UNIT;
    float z = (float)az / 16384.0 * G_PER_UNIT;

    // Log data
    timestamp = microsecond();
    log_data(fmod(timestamp, 1000000) / 1000000.0);
    toggle_led(abs(x) > 2.0 || abs(y) > 2.0 || abs(z) > 2.0);
}

void check_device_id() {
    uint8_t buffer[1];
    read(i2c_fd, buffer, 1);
    if (buffer[0] != 0x29) {
        log_error("ADXL345 device ID mismatch");
    }
}

void check_range() {
    uint8_t buffer[1];
    read(i2c_fd, buffer, 1);
    if (buffer[0] & 0x20) {
        log_warning("ADXL345 range is set to ±2g");
    } else {
        log_error("ADXL345 range is not set to ±2g");
    }
}

void toggle_led(int axis) {
    if (axis) {
        piGPIO_write(handle, LED_PIN, 1);
    } else {
        piGPIO_write(handle, LED_PIN, 0);
    }
}

void log_data(const char *data) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        log_error("Failed to open log file");
        return;
    }
    fprintf(fp, "%s", data);
    fclose(fp);
}

void log_error(const char *msg) {
    fprintf(stderr, "%s\n", msg);
}

void log_warning(const char *msg) {
    fprintf(stderr, "WARNING: %s\n", msg);
}

void read_adxl345_error(const char *msg) {
    fprintf(stderr, "ERROR: %s\n", msg);
}

void handle_signal(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        log_warning("Exiting...");
        close(i2c_fd);
        piGPIO_remove(handle);
        fclose(stdout);
        exit(0);
    }
}

int main(int argc, char *argv[]) {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // ... (rest of the code remains the same)
}
