#include <fcntl.h>
#include <errno.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x68  // GY-51 LSM303DLHC default I2C address
#define SAMPLE_INTERVAL_MS 100
#define LOG_FILE "compass_log.txt"

typedef struct {
    int16_t ax, ay, az;
    int16_t gx, gy, gz;
    int16_t mx, my, mz;
} SensorData;

void log_data(const SensorData &data) {
    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        perror("Failed to open log file");
        return;
    }

    fprintf(file, "%d,%f,%f,%f,%f,%f\n",
            (int)(time(NULL) % 1000000),
            data.ax / 100, data.ay / 100, data.az / 100,
            data.gx / 100, data.gy / 100, data.gz / 100,
            data.mx, data.my, data.mz);

    fclose(file);
}

int main() {
    int i2c_fd;
    SensorData data;

    // Initialize pigpio
    if (piGPIO_init() < 0) {
        perror("Failed to initialize pigpio");
        return EXIT_FAILURE;
    }

    // Open I2C bus
    i2c_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (i2c_fd < 0) {
        perror("Failed to open log file");
        piGPIO_shutdown();
        return EXIT_FAILURE;
    }

    // Initialize I2C communication
    if (i2c_open(i2c_fd, I2C_BUS) < 0) {
        perror("Failed to open I2C bus");
        close(i2c_fd);
        piGPIO_shutdown();
        return EXIT_FAILURE;
    }

    // Read sensor data
    if (i2c_read_byte_data(i2c_fd, I2C_ADDR, 0x2A) < 0) {
        perror("Failed to read accelerometer data");
        i2c_close(i2c_fd);
        close(i2c_fd);
        piGPIO_shutdown();
        return EXIT_FAILURE;
    }

    data.ax = i2c_read_byte_data(i2c_fd, I2C_ADDR, 0x2B) << 8 | i2c_read_byte_data(i2c_fd, I2C_ADDR, 0x2C);
    data.ay = i2c_read_byte_data(i2c_fd, I2C_ADDR, 0x2D) << 8 | i2c_read_byte_data(i2c_fd, I2C_ADDR, 0x2E);
    data.az = i2c_read_byte_data(i2c_fd, I2C_ADDR, 0x2F) << 8 | i2c_read_byte_data(i2c_fd, I2C_ADDR, 0x30);

    if (i2c_read_byte_data(i2c_fd, I2C_ADDR, 0x31) < 0) {
        perror("Failed to read magnetometer data");
        i2c_close(i2c_fd);
        close(i2c_fd);
        piGPIO_shutdown();
        return EXIT_FAILURE;
    }

    data.mx = i2c_read_byte_data(i2c_fd, I2C_ADDR, 0x32) << 8 | i2c_read_byte_data(i2c_fd, I2C_ADDR, 0x33);
    data.my = i2c_read_byte_data(i2c_fd, I2C_ADDR, 0x34) << 8 | i2c_read_byte_data(i2c_fd, I2C_ADDR, 0x35);
    data.mz = i2c_read_byte_data(i2c_fd, I2C_ADDR, 0x36) << 8 | i2c_read_byte_data(i2c_fd, I2C_ADDR, 0x37);

    // Log data
    log_data(data);

    // Sleep for the specified interval
    usleep(SAMPLE_INTERVAL_MS * 1000);

    // Graceful shutdown
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to set SIGINT handler");
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to set SIGTERM handler");
    }

    // Close I2C handles and terminate pigpio
    i2c_close(i2c_fd);
    close(i2c_fd);
    piGPIO_shutdown();

    return EXIT_SUCCESS;
}

void sigint_handler(int signum) {
    fprintf(stderr, "Received SIGINT, performing graceful shutdown...\n");
    // Add any cleanup actions here if needed
    exit(signum == SIGINT ? EXIT_SUCCESS : EXIT_FAILURE);
}

