    int fd;
    pigpio_init(5); // Initialize pigpio with a timeout of 5 seconds
    if (pigpio_init(5) < 0) {
        perror("pigpio_init");
        return 1;
    }

    init_i2c();

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
