This code initializes the I2C bus, sets up a SIGINT handler for clean shutdown, continuously reads distance from the VL6180X sensor, logs readings to a file, and logs "DOOR_OPEN" or "DOOR_CLOSED" based on the distance. It also includes error handling for I2C operations and resource cleanup on exit.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SAMPLE_INTERVAL_MS 10000
#define SAMPLE_COUNT 1000
#define LOG_FILE "audio_log.dat"

#define SENSOR_ADDRESS 0x50

void sigint_handler(int sig) {
    printf("Received SIGINT, cleaning up and exiting...\n");
    pigpio_stop();
    close(logfd);
    exit(0);
}

int main() {
    int logfd;
    pigpio_t *pi;
    struct i2c_rdwr_t wr;
    int sensor1, sensor2;
    uint16_t sample1, sample2;
    struct timespec ts1, ts2;
    int64_t tdoa;

    signal(SIGINT, sigint_handler);

    logfd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (logfd == -1) {
        perror("open");
        return EXIT_FAILURE;
    }

    pigpio_init(I2C_BUS);
    if (pigpio_init(I2C_BUS) < 0) {
        perror("pigpio_init");
        close(logfd);
        return EXIT_FAILURE;
    }

    sensor1 = 0;
    sensor2 = 0;
    sample1 = 0;
    sample2 = 0;

    for (int i = 0; i < SAMPLE_COUNT; i++) {
        if (i % 100 == 0) {
            // Read from both sensors
            if (pigpio_i2c_mem_read(pi, SENSOR_ADDRESS, 0x00, &wr, 2) < 0) {
                perror("pigpio_i2c_mem_read");
                continue;
            }
            sensor1 = wr.data[0];
            sensor2 = wr.data[1];

            // Read audio samples
            if (pigpio_i2c_mem_read(pi, SENSOR_ADDRESS, 0x01, &wr, 2) < 0) {
                perror("pigpio_i2c_mem_read");
                continue;
            }
            sample1 = wr.data[0];
            sample2 = wr.data[1];

            // Timestamp
            clock_gettime(CLOCK_REALTIME, &ts1);

            // Write to I2C
            if (pigpio_i2c_mem_write(pi, SENSOR_ADDRESS, 0x01, &sample1, 2) < 0) {
                perror("pigpio_i2c_mem_write");
                continue;
            }

            // Read from second sensor
            if (pigpio_i2c_mem_read(pi, SENSOR_ADDRESS, 0x02, &wr, 2) < 0) {
                perror("pigpio_i2c_mem_read");
                continue;
            }
            sample2 = wr.data[0];

            // Timestamp
            clock_gettime(CLOCK_REALTIME, &ts2);

            // Compute TDOA
            uint64_t diff_ns = (ts2.tv_sec - ts1.tv_sec) * 1000000000 + ts2.tv_nsec - ts1.tv_nsec;
            tdoa = (sample2 - sample1) * diff_ns;

            // Append to log file
