    pigpio_t *pi;
    struct i2c_rdwr_t wr;
    int sensor1, sensor2;
    uint16_t sample1, sample2;
    struct timespec ts1, ts2;
    int64_t tdoa;

    signal(SIGINT, sigint_handler);

    logfd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (logfd == -1) {
        perror("open");
        return EXIT_FAILURE;
    }

    pigpio_init(I2C_BUS);
    if (pigpio_init(I2C_BUS) < 0) {
        perror("pigpio_init");
        close(logfd);
        return EXIT_FAILURE;
    }

    sensor1 = 0;
    sensor2 = 0;
    sample1 = 0;
    sample2 = 0;

    for (int i = 0; i < SAMPLE_COUNT; i++) {
        if (i % 100 == 0) {
            // Read from both sensors
            if (pigpio_i2c_mem_read(pi, SENSOR_ADDRESS, 0x00, &wr, 2) < 0) {
                perror("pigpio_i2c_mem_read");
                continue;
            }
            sensor1 = wr.data[0];
            sensor2 = wr.data[1];

            // Read audio samples
            if (pigpio_i2c_mem_read(pi, SENSOR_ADDRESS, 0x01, &wr, 2) < 0) {
                perror("pigpio_i2c_mem_read");
                continue;
            }
            sample1 = wr.data[0];
            sample2 = wr.data[1];

            // Timestamp
            clock_gettime(CLOCK_REALTIME, &ts1);

            // Write to I2C
            if (pigpio_i2c_mem_write(pi, SENSOR_ADDRESS, 0x01, &sample1, 2) < 0) {
                perror("pigpio_i2c_mem_write");
                continue;
