                perror("pigpio_i2c_mem_read");
                continue;
            }
            sample2 = wr.data[0];

            // Timestamp
            clock_gettime(CLOCK_REALTIME, &ts2);

            // Compute TDOA
            uint64_t diff_ns = (ts2.tv_sec - ts1.tv_sec) * 1000000000 + ts2.tv_nsec - ts1.tv_nsec;
            tdoa = (sample2 - sample1) * diff_ns;

