                continue;
            }
            fprintf(logfd, "%ld,%ld,%d,%d,%lld\n", ts1.tv_sec, ts1.tv_nsec, sensor1, sensor2, tdoa);
        }
        usleep(SAMPLE_INTERVAL_MS / 1000);
    }

    pigpio_stop(pi);
    close(logfd);
    return EXIT_SUCCESS;
}
