#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <sys/epoll.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

#define SPI_DEVICE 0
#define SPI_SPEED 100000000
#define SPI_POLARITY 1
#define SPI_PHASE 1
#define IMU_ADDRESS 0x50
#define IMU_REG_BASE 0x00
#define STALL_TIME_US 40000
#define SAMPLE_INTERVAL_MS 100
#define LOG_FILE "imu_data.csv"

#define BUFFER_SIZE 1024

int spi_fd;
int imu_fd;
char buffer[BUFFER_SIZE];
char timestamp[32];

void cleanup() {
    close(spi_fd);
    close(imu_fd);
    pigpio_terminate(1000);
    remove(LOG_FILE);
}

void signal_handler(int signum) {
    fprintf(stderr, "Received signal %d, shutting down...\n", signum);
    exit(signum == SIGINT || signum == SIGTERM ? 0 : 1);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    spi_fd = open("/dev/spidev0.0", O_RDWR | O_NOCTTY | O_NDELAY);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        cleanup();
        exit(1);
    }

    imu_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (imu_fd < 0) {
        perror("Failed to open log file");
        cleanup();
        exit(1);
    }

    pigpio_init(1000);

    while (1) {
        usleep(SAMPLE_INTERVAL_MS * 1000 * 1000 / 1000); // Delay for 100ms

        // Check for stall condition
        if (usleep(STALL_TIME_US / 2) < 0) {
            fprintf(stderr, "Stall condition detected, skipping sample\n");
            continue;
        }

        // Read IMU data
        imu_write_command(imu_fd, IMU_REG_BASE | 0x00); // Command word with MSB 0
        imu_read_data(imu_fd, buffer);

        // Convert raw values to degrees/g
        int16_t gyro_x = buffer[2] << 8 | buffer[3];
        int16_t gyro_y = buffer[4] << 8 | buffer[5];
        int16_t gyro_z = buffer[6] << 8 | buffer[7];
        int16_t accel_x = buffer[8] << 8 | buffer[9];
        int16_t accel_y = buffer[10] << 8 | buffer[11];
        int16_t accel_z = buffer[12] << 8 | buffer[13];

        // Apply sensitivities
        gyro_x *= 0.005;
        gyro_y *= 0.005;
        gyro_z *= 0.005;
        accel_x *= 0.00025;
        accel_y *= 0.00025;
        accel_z *= 0.00025;

        // Format timestamp
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

        // Write to log file
        fprintf(imu_fd, "%s,%ld,%ld,%ld,%ld,%ld,%ld\n", timestamp, gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z);
    }

    pigpio_stop(1000);
    close(imu_fd);
    close(spi_fd);
    return 0;
}

void imu_write_command(int fd, uint16_t command) {
    write(fd, &command, sizeof(command));
}

void imu_read_data(int fd, char *buffer) {
    read(fd, buffer, BUFFER_SIZE);
}

