#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <linux/spi/spidev-dev.h>

#define CS_PIN 8
#define SPI_MODE 3
#define MAX_CLOCK_HZ 1000000
#define REG_ADDR 0x20
#define GYRO_SCALE 0.02
#define ACCEL_SCALE 0.00025

#define BUFFER_SIZE 16

int spi_fd;

void spi_init(void) {
    int file = open("/dev/spidev0.0", O_RDWR);
    if (file == -1) {
        perror("open /dev/spidev0.0");
        exit(EXIT_FAILURE);
    }

    struct spi_fd_info info;
    if (ioctl(file, SPI_IOC_RDWR_CONTROL, &info) == -1) {
        perror("ioctl SPI_IOC_RDWR_CONTROL");
        close(file);
        exit(EXIT_FAILURE);
    }

    info.mode = SPI_MODE;
    info.max_speed_hz = MAX_CLOCK_HZ;

    if (ioctl(file, SPI_IOC_RDWR_MODE, &info) == -1) {
        perror("ioctl SPI_IOC_RDWR_MODE");
        close(file);
        exit(EXIT_FAILURE);
    }

    spi_fd = file;
}

void spi_write_register(uint16_t addr, uint8_t data) {
    if (write(spi_fd, &addr, sizeof(addr)) != sizeof(addr)) {
        perror("write to SPI");
        exit(EXIT_FAILURE);
    }

    if (write(spi_fd, &data, sizeof(data)) != sizeof(data)) {
        perror("write to SPI");
        exit(EXIT_FAILURE);
    }
}

uint16_t spi_read_register(void) {
    uint16_t data;
    if (read(spi_fd, &data, sizeof(data)) != sizeof(data)) {
        perror("read from SPI");
        exit(EXIT_FAILURE);
    }

    return data;
}

void read_imu_data(void) {
    uint8_t gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z;

    spi_write_register(REG_ADDR, 0x00); // Start of gyroscope data
    spi_write_register(REG_ADDR, 0x01); // Gyroscope X
    spi_write_register(REG_ADDR, 0x02); // Gyroscope Y
    spi_write_register(REG_ADDR, 0x03); // Gyroscope Z

    spi_write_register(REG_ADDR, 0x10); // Start of accelerometer data
    spi_write_register(REG_ADDR, 0x11); // Accelerometer X
    spi_write_register(REG_ADDR, 0x12); // Accelerometer Y
    spi_write_register(REG_ADDR, 0x13); // Accelerometer Z

    usleep(100000); // Wait for 100ms

    spi_write_register(REG_ADDR, 0x00); // End of gyroscope data
    spi_write_register(REG_ADDR, 0x00); // End of accelerometer data

    gyro_x = spi_read_register() * GYRO_SCALE;
    gyro_y = spi_read_register() * GYRO_SCALE;
    gyro_z = spi_read_register() * GYRO_SCALE;

    accel_x = spi_read_register() * ACCEL_SCALE;
    accel_y = spi_read_register() * ACCEL_SCALE;
    accel_z = spi_read_register() * ACCEL_SCALE;

    printf("Gyroscope: X=%.3f dps, Y=%.3f dps, Z=%.3f dps\n", gyro_x, gyro_y, gyro_z);
    printf("Accelerometer: X=%.3f g, Y=%.3f g, Z=%.3f g\n", accel_x, accel_y, accel_z);
}

int main(int argc, char *argv[]) {
    spi_init();

    while (1) {
        read_imu_data();
    }

    close(spi_fd);
    return 0;
}

