#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define GPIO_PIN 8
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define GYRO_X_LSB 0
#define GYRO_Y_LSB 4
#define GYRO_Z_LSB 8
#define ACC_X_LSB 12
#define ACC_Y_LSB 16
#define ACC_Z_LSB 20

#define READ_COMMAND 0x20
#define DUMMY_VALUE 0x0000

#define STALL_TIME_US 40000

void spi_init(void);
void imu_read(void);
void error_handling(const char *msg);

int main(int argc, char *argv[]) {
    int spi_fd, imu_fd;
    struct spi_fd_info spi_info;
    struct imu_config imu_config;

    spi_init();

    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd == -1) {
        error_handling("Failed to open SPI device");
        return EXIT_FAILURE;
    }

    imu_config.chip_select = GPIO_PIN;
    imu_config.cs_active_low = 1;
    imu_config.bus_width = 16;
    imu_config.read_command = READ_COMMAND;
    imu_config.dummy_value = DUMMY_VALUE;

    imu_fd = pigpio_open_device("/dev/pi3spidev", imu_config);
    if (imu_fd == -1) {
        error_handling("Failed to open IMU device");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    while (1) {
        imu_read();
        usleep(100000); // 100ms delay
    }

    pigpio_close(imu_fd);
    close(spi_fd);
    return EXIT_SUCCESS;
}

void spi_init(void) {
    spi_info.device = SPI_DEVICE;
    spi_info.mode = SPI_MODE;
    spi_info.speed = SPI_SPEED;

    if (spidev_open(&spi_info, 0) == -1) {
        perror("spidev_open");
        exit(EXIT_FAILURE);
    }
}

void imu_read(void) {
    uint16_t data[2];

    // Send read command
    data[0] = READ_COMMAND;
    data[1] = 0;
    if (spidev_write(&spi_info, data) == -1) {
        error_handling("Failed to write to IMU");
        return;
    }

    // Wait for stall time
    usleep(STALL_TIME_US / 1000);

    // Send dummy value
    data[0] = DUMMY_VALUE;
    if (spidev_write(&spi_info, data) == -1) {
        error_handling("Failed to write to IMU");
        return;
    }

    // Read 16-bit data
    data[0] = spidev_read(&spi_info, 2);
    data[1] = spidev_read(&spi_info, 2);

    // Scale gyroscope values
    int gyro_x = (data[0] >> GYRO_X_LSB) * 0.05;
    int gyro_y = (data[0] >> GYRO_Y_LSB) * 0.05;
    int gyro_z = (data[0] >> GYRO_Z_LSB) * 0.05;

    // Scale accelerometer values
    int acc_x = (data[1] >> ACC_X_LSB) * 0.00025;
    int acc_y = (data[1] >> ACC_Y_LSB) * 0.00025;
    int acc_z = (data[1] >> ACC_Z_LSB) * 0.00025;

    printf("Gyro X: %.2f deg/s, Y: %.2f deg/s, Z: %.2f deg/s\n", gyro_x, gyro_y, gyro_z);
    printf("Accel X: %.3f g, Y: %.3f g, Z: %.3f g\n", acc_x, acc_y, acc_z);
}

void error_handling(const char *msg) {
    fprintf(stderr, "Error: %s\n", msg);
    pigpio_close(imu_fd);
    close(spi_fd);
    exit(EXIT_FAILURE);
}

