    *ax = -1;
    *ay = -1;
    *az = -1;
    *gx = -1;
    *gy = -1;
    *gz = -1;
}

int read_i2c_word(int reg) {
    int file;
    char buf[2];

    file = open("/dev/i2c-1", O_RDWR);
    if (file == -1) {
        perror("open /dev/i2c-1");
        return -1;
    }

    if (ioctl(file, I2C_SLAVE, I2C_ADDR) == -1) {
        perror("ioctl I2C_SLAVE");
        close(file);
        return -1;
    }

    buf[0] = reg >> 8;
    buf[1] = reg & 0xFF;

    int ret = read(file, buf, 2);
