#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS 1
#define ADXL345_ADDRESS 0x53
#define LED_GPIO 17
#define LOG_FILE "impact_log.txt"
#define LOG_INTERVAL_MS 10
#define THRESHOLD_MAG 2.5
#define LOG_FORMAT "%lu:%lu:%lu:%lu:%lu\n"

#define CHECK_DEVICE_ID(reg) do { \
    uint8_t id; \
    readl(ADXL345_ADDRESS, reg, &id, 1); \
    if (id != 0x49) { \
        fprintf(stderr, "Device ID mismatch, expected 0x49, got 0x%02X\n", id); \
        exit(EXIT_FAILURE); \
    } \
} while (0)

void log_impact(int mag_x, int mag_y, int mag_z) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    fprintf(fp, LOG_FORMAT, now, mag_x, mag_y, mag_z);
    fclose(fp);
}

int main(int argc, char *argv[]) {
    int i2c_fd, led_gpio;
    pigpio_init(5);

    if (pigpio_init(5) < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return EXIT_FAILURE;
    }

    if (open(LOG_FILE, O_WRONLY | O_CREAT, S_IRUSR | S_IWUSR) < 0) {
        perror("Failed to open log file");
        pigpio_terminate(5);
        return EXIT_FAILURE;
    }

    i2c_fd = open(LOG_FILE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open log file for writing");
        pigpio_terminate(5);
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_ADDRESS) < 0) {
        perror("Failed to acquire I2C bus access");
        close(i2c_fd);
        pigpio_terminate(5);
        return EXIT_FAILURE;
    }

    led_gpio = LED_GPIO;

    while (1) {
        uint16_t x, y, z;
        Check_ADXL345_Data(&x, &y, &z);

        int total_mag = (int)(0.5 * sqrt(x * x + y * y + z * z));

        if (total_mag > THRESHOLD_MAG) {
            log_impact(total_mag, x, y, z);
            gpioWrite(led_gpio, 1);
            sleep(500 / 1000); // 0.5 seconds
            gpioWrite(led_gpio, 0);
        }

        Check_Device_ID(ADXL345_ADDRESS, 0x00);

        Check_ADXL345_Data(&x, &y, &z);
    }

    close(i2c_fd);
    pigpio_terminate(5);
    return EXIT_SUCCESS;
}

void Check_ADXL345_Data(uint16_t *x, uint16_t *y, uint16_t *z) {
    *x = readl(ADXL345_ADDRESS, 0x2A, 2, LSBFIRST);
    *y = readl(ADXL345_ADDRESS, 0x2C, 2, LSBFIRST);
    *z = readl(ADXL345_ADDRESS, 0x2E, 2, LSBFIRST);
    CHECK_DEVICE_ID(0x2A);
    CHECK_DEVICE_ID(0x2C);
    CHECK_DEVICE_ID(0x2E);
}

void Check_Device_ID(uint8_t reg, uint8_t id) {
    uint8_t value;
    readl(ADXL345_ADDRESS, reg, &value, 1);
    if (value != id) {
        fprintf(stderr, "Device ID mismatch, expected 0x%02X, got 0x%02X\n", id, value);
        exit(EXIT_FAILURE);
    }
}

