#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <libgpiod.h>

#define I2C_BUS 1
#define SAMPLE_RATE_HZ 10
#define SAMPLE_INTERVAL_MS 100
#define FILE_NAME "imu_log.csv"

void signal_handler(int signum) {
    gpiod_disable(I2C_BUS);
    close(I2C_BUS);
    fclose(stdout);
    fclose(stderr);
    printf("Exiting gracefully...\n");
    exit(0);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    int i2c_fd, ret;
    struct i2c_client *client;
    char buffer[6];
    long accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z;
    time_t now;
    struct tm *tm_info;
    char *log_file = FILE_NAME;

    i2c_fd = open("/dev/i2c-1", O_RDWR | O_NOCTTY | O_NDELAY);
    if (i2c_fd == -1) {
        perror("open /dev/i2c-1");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_request_active_active_channel(I2C_BUS, 0, 1);
    if (ret < 0) {
        perror("gpiod_request_active_active_channel");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    client = gpiod_get_active_channel(I2C_BUS, 0);
    if (!client) {
        perror("gpiod_get_active_channel");
        gpiod_release_active_channel(I2C_BUS, 0);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    while (1) {
        now = time(NULL);
        tm_info = localtime(&now);

        ret = read(client->fd, buffer, 6);
        if (ret < 0) {
            fprintf(stderr, "Error reading from I2C bus: %s\n", strerror(errno));
            continue;
        }

        accel_x = (buffer[0] << 8) | buffer[1];
        accel_y = (buffer[2] << 8) | buffer[3];
        accel_z = (buffer[4] << 8) | buffer[5];
        gyro_x = (buffer[6] << 8) | buffer[7];
        gyro_y = (buffer[8] << 8) | buffer[9];
        gyro_z = (buffer[10] << 8) | buffer[11];

        fprintf(stdout, "Sample %lu: x=%ld, y=%ld, z=%ld, ax=%ld, ay=%ld, az=%ld, gx=%ld, gy=%ld, gz=%ld\n",
                (unsigned long)now, accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z);

        if (write(log_file, "Sample %lu, x=%ld, y=%ld, z=%ld, ax=%ld, ay=%ld, az=%ld, gx=%ld, gy=%ld, gz=%ld\n",
                (unsigned long)now, accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z, 0, 0, 0) < 0) {
            perror("write to imu_log.csv");
        }

        usleep(SAMPLE_INTERVAL_MS * 1000 / SAMPLE_RATE_HZ);
    }

    gpiod_release_active_channel(I2C_BUS, 0);
    close(client->fd);
    close(i2c_fd);

    return 0;
}

