    uint16_t x, y, z;
    read_i2c_register(I2C_ADDR, 0x28, 2, x);
    read_i2c_register(I2C_ADDR, 0x2C, 2, y);
    read_i2c_register(I2C_ADDR, 0x30, 2, z);

    int magnitude = (int)(x * 1000 + y * 1000 + z * 1000) / COUNTS_PER_G;
    if (magnitude > MAGNITUDE_THRESHOLD) {
