    close(fd_log);
    fprintf(stderr, "Exiting...\n");
    exit(signum);
}

int setup_i2c(int fd_i2c) {
    struct i2c_client *client;
    int ret;

    client = i2c_alloc(fd_i2c, I2C_BUS);
    if (!client) {
        perror("i2c_alloc");
        return -1;
    }

    ret = i2c_config(client, I2C_SLAVE_ADDR, 0);
    if (ret < 0) {
        i2c_free(client);
        perror("i2c_config");
        return -1;
    }

    return 0;
}

int setup_log(int fd_log) {
    FILE *fp;
    char *header = "timestamp,mag_x,mag_y,mag_z\n";

    fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen");
        return -1;
    }

    if (fputs(header, fp) < sizeof(header)) {
        perror("fputs");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

