    int fd_i2c, fd_log;
    struct itimerval timer;
    sigset_t sigset;
    char buffer[BUFFER_SIZE];

    if (signal(SIGINT, sigint_handler) == SIG_IGN ||
        signal(SIGTERM, sigterm_handler) == SIG_IGN) {
        perror("signal");
        return -1;
    }

    sigset_t copy;
    memset(&copy, 0, sizeof(copy));
    sigaddset(&copy, SIGINT);
    sigaddset(&copy, SIGTERM);

    sigemptyset(&sigset);
    sigprocmask(SIG_BLOCK, &copy, NULL);

    fd_i2c = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (fd_i2c < 0) {
        perror("open");
        return -1;
