    setup_i2c(fd_i2c);
    setup_log(fd_i2c);

    timer.it_value.tv_sec = 0;
    timer.it_value.tv_usec = SAMPLE_INTERVAL / 1000;
    timer.it_interval.tv_sec = 0;
    timer.it_interval.tv_usec = 0;

    if (epoll_ctl(epfd, EPOLLIN, fd_i2c, NULL) == -1) {
        perror("epoll_ctl");
        return -1;
    }

    while (1) {
        struct timespec timeout;
        timeout.tv_sec = 0;
        timeout.tv_nsec = SAMPLE_INTERVAL / 1000;

        int ret = select(fd_i2c + 1, NULL, &timer, NULL, &timeout);
        if (ret == -1) {
            perror("select");
            break;
        }

        if (ret == 0) {
            continue;
        }

        if (read(fd_i2c, buffer, BUFFER_SIZE) < 0) {
            perror("read");
            break;
        }

        // Process the magnetic field data from buffer
        // This part requires the TMAG5273 datasheet to correctly interpret the data

        write_to_log("current_timestamp,mag_x,mag_y,mag_z\n");
    }

    close(fd_i2c);
    close(fd_log);
    epoll_ctl(epfd, EPOLL_CTL_DEL, fd_i2c, NULL);
    epoll_wait(epfd, NULL, 1, -1);
    epoll_ctl(epfd, EPOLL_CTL_DEL, fd_i2c, NULL);

    return 0;
}

