code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <sys/epoll.h>
#include <sys/poll.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>

#define I2C_BUS 1
#define ADXL345_ADDRESS 0x52
#define INT1_GPIO 17
#define LOG_FILE "freefall_log.csv"

#define BUFFER_SIZE 1024

// Function prototypes
int init_i2c(int fd);
int init_gpio(void);
int init_adxl345(void);
void free_resources(void);
void handle_interrupt(int fd, short int value);
void write_to_log(double x, double y, double z);
void signal_handler(int sig);

int main(int argc, char *argv[]) {
    int i2c_fd, gpio_fd, adxl_fd;
    int poll_fd;
    struct pollfd pollfds;
    int sigint_handler_fd;
    pthread_t interrupt_thread;

    // Initialize I2C, GPIO, and ADXL345
    if (init_i2c(i2c_fd) < 0 || init_gpio() < 0 || init_adxl345() < 0) {
        fprintf(stderr, "Failed to initialize components.\n");
        return EXIT_FAILURE;
    }

    // Set up epoll for interrupt handling
    poll_fd = poll_create(BUFFER_SIZE, 1);
    if (poll_fd < 0) {
        fprintf(stderr, "Failed to create epoll instance.\n");
        free_resources();
        return EXIT_FAILURE;
    }

    pollfds.fd_count = 1;
    pollfds.data.fd = adxl_fd;
    pollfds.events = POLLIN;

    // Start listening for interrupts
    if (poll_wait(pollfds, BUFFER_SIZE) < 0) {
        fprintf(stderr, "Failed to start interrupt listening.\n");
        free_resources();
        return EXIT_FAILURE;
    }

    // Start the interrupt handling thread
    if (pthread_create(&interrupt_thread, NULL, handle_interrupt, (void *)adxl_fd) < 0) {
        fprintf(stderr, "Failed to create interrupt handling thread.\n");
        free_resources();
        return EXIT_FAILURE;
    }

    // Set up signal handler for SIGINT and SIGTERM
    sigint_handler_fd = signal(SIGINT, signal_handler);
    if (sigint_handler_fd == SIG_IGN) {
        fprintf(stderr, "Failed to set up SIGINT handler.\n");
        free_resources();
        return EXIT_FAILURE;
    }
    if (signal(SIGTERM, signal_handler) == SIG_IGN) {
        fprintf(stderr, "Failed to set up SIGTERM handler.\n");
        free_resources();
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        // Poll for interrupts
        int result = poll_wait(pollfds, BUFFER_SIZE);
        if (result < 0) {
            fprintf(stderr, "Error in poll_wait.\n");
            break;
        }

        // Handle interrupt events
        if (pollfds.revents & POLLIN) {
            handle_interrupt(adxl_fd, 0);
        }
    }

    // Disable interrupts, close resources, and exit
    free_resources();
    return EXIT_SUCCESS;
}

int init_i2c(int *fd) {
    int ret;
    *fd = open("/dev/i2c-1", O_RDWR);
    if (*fd < 0) {
        perror("Failed to open i2c bus");
        return -1;
    }

    ret = ioctl(*fd, I2C_SLAVE, ADXL345_ADDRESS);
    if (ret < 0) {
        perror("Failed to set I2C slave address");
        close(*fd);
        *fd = -1;
        return -1;
    }

    return *fd;
}

int init_gpio(void) {
    int fd = open("/dev/gpio*, O_RDWR);
    if (fd < 0) {
        perror("Failed to open GPIO file descriptor");
        return -1;
    }

    // Configure GPIO17 as input with pull-up resistor
    if (write(fd, "17,u", 3) != 3) {
        perror("Failed to configure GPIO17");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

int init_adxl345(void) {
    int fd = init_i2c(&adxl_fd);
    if (fd < 0) {
        return fd;
    }

