#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <libgpiod.h>

#define I2C_BUS 1
#define SDA_PIN 2
#define SCL_PIN 3
#define FALL_THRESHOLD_G 0.2
#define IMPACT_THRESHOLD_G 2.5
#define DETECTION_WINDOW_S 1.0
#define OUTPUT_RATE_HZ 104
#define ACCEL_RANGE_G 2
#define GYRO_RANGE_DPS 250

#define LOG_FILE "motion_log.txt"

struct i2c_client *client;

int fall_state = 0;
int impact_state = 0;

void imu_read_data(void *data) {
    int reg_addr = 0x6B; // LSM6DSR register address for accel/gyro data
    int16_t ax, ay, az;
    int16_t gx, gy, gz;

    if (libgpiod_get_gpio_value(SDA_PIN) == 0) {
        // Sensor not present, handle error
        fprintf(stderr, "Error: Sensor not present\n");
        return;
    }

    if (libgpiod_get_gpio_value(SCL_PIN) == 0) {
        // SCL line not active, handle error
        fprintf(stderr, "Error: SCL line not active\n");
        return;
    }

    if (ioctl(client->fd, I2C_SLAVE, (u32)I2C_BUS) < 0) {
        fprintf(stderr, "Error: Failed to acquire I2C bus\n");
        return;
    }

    if (read(client->fd, &reg_addr, 1) != 1) {
        fprintf(stderr, "Error: Failed to read register address\n");
        return;
    }

    if (read(client->fd, &ax, 2) != 2) {
        fprintf(stderr, "Error: Failed to read accel data\n");
        return;
    }
    ax = (int16_t)ax;
    ay = (int16_t)(ax >> 8);

    if (read(client->fd, &gx, 2) != 2) {
        fprintf(stderr, "Error: Failed to read gyro data\n");
        return;
    }
    gx = (int16_t)gx;
    gy = (int16_t)(gx >> 8);

    if (read(client->fd, &az, 2) != 2) {
        fprintf(stderr, "Error: Failed to read accel data\n");
        return;
    }
    az = (int16_t)az;
    az = (az >> 8);

    if (read(client->fd, &gz, 2) != 2) {
        fprintf(stderr, "Error: Failed to read accel data\n");
        return;
    }
    gz = (int16_t)gz;
    gz = (gz >> 8);

    // Scale and convert to g
    ax *= 0.004;
    ay *= 0.004;
    az *= 0.004;
    gx *= 0.0001;
    gy *= 0.0001;
    gz *= 0.0001;

    // Apply range limits
    ax = fminf(fmaxf(ax, -ACCEL_RANGE_G), ACCEL_RANGE_G);
    ay = fminf(fmaxf(ay, -ACCEL_RANGE_G), ACCEL_RANGE_G);
    az = fminf(fmaxf(az, -ACCEL_RANGE_G), ACCEL_RANGE_G);
    gx = fminf(fmaxf(gx, -GYRO_RANGE_DPS), GYRO_RANGE_DPS);
    gy = fminf(fmaxf(gy, -GYRO_RANGE_DPS), GYRO_RANGE_DPS);
    gz = fminf(fmaxf(gz, -GYRO_RANGE_DPS), GYRO_RANGE_DPS);

    // Timestamp
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long long timestamp = ts.tv_sec * 1000000000 + ts.tv_nsec / 1000;

    // Log data
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error: Failed to open log file\n");
        return;
    }
    fprintf(fp, "%lld,%lld,%lld,%lld,%lld,%lld\n", timestamp, ax, ay, az, gx, gy, gz);
    fclose(fp);

    // State machine logic
    if (fall_state == 0) {
        if (fmaxf(fmaxf(fminf(ay, az), fminf(ay, az))) < FALL_THRESHOLD_G) {
            fall_state = 1;
            impact_state = 0;
        }
    } else if (fall_state == 1) {
        if (fmaxf(fmaxf(fminf(ay, az))) > IMPACT_THRESHOLD_G) {
            impact_state = 1;
            fall_state = 0;
        }
    }

    // Reset state machine on detection window
    if (impact_state) {
        impact_state = 0;
        fall_state = 0;
    }
}

