#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <pthread.h>
#include <libgpiod.h>

#define SPI_CHANNEL 0
#define CE_PIN 8
#define CPOL 1
#define CPHA 1
#define SPI_CLOCK_HZ 1000000
#define REG_ADDR 0x10
#define WHO_AM_I_REG 0x00
#define SAMPLE_RATE_MS 10
#define SCALE_FACTOR 0.0305

#define LOG_FILE "gyro_log.csv"

int spi_fd;
int gpio_fd;

struct spi_device *spi_dev;

void spi_init(void) {
    spi_fd = spi_open(SPI_CHANNEL, "r+");
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    spi_config_t config;
    spi_config_init(&config);
    spi_config_clock_hz(config, SPI_CLOCK_HZ);
    spi_config_mode(config, SPI_MODE0);
    spi_config_cpol(config, CPOL_1);
    spi_config_cpha(config, CPHA_1);
    spi_config_write_func(spi_dev, spi_write_func, NULL);
    spi_config_read_func(spi_dev, spi_read_func, NULL);
    spi_config_transfer_depth(spi_dev, 2);
    spi_config_transfer_type(spi_dev, SPI_TRANSFER_MODE_2BYTES);
    spi_config_transfer_is_peripheral(spi_dev, true);
    spi_config_transfer_is_automatic_retry(spi_dev, false);
    spi_config_transfer_enable_poll(spi_dev, true);
    spi_config_transfer_enable_polling_interval(spi_dev, 100);
    if (spi_open(spi_dev, &config) < 0) {
        perror("Failed to configure SPI device");
        spi_close(spi_dev);
        exit(EXIT_FAILURE);
    }
}

void gpio_init(void) {
    int ret;
    gpio_fd = open("/dev/gpiomem", O_RDWR);
    if (gpio_fd < 0) {
        perror("Failed to open /dev/gpiomem");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_platform_setup();
    if (ret < 0) {
        perror("Failed to initialize gpiod");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_chip_init(gpio_fd, 1);
    if (ret < 0) {
        perror("Failed to initialize gpiod chip");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_chip_export_all(gpio_fd, 1);
    if (ret < 0) {
        perror("Failed to export all GPIO pins");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_pin_export(gpio_fd, CE_PIN);
    if (ret < 0) {
        perror("Failed to export CE pin");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_pin_direction_output(gpio_fd, CE_PIN);
    if (ret < 0) {
        perror("Failed to set CE pin as output");
        exit(EXIT_FAILURE);
    }
}

void read_who_am_i(void) {
    uint32_t reg_value;
    spi_write_func(spi_fd, REG_ADDR | 0x80); // Send read command
    spi_read_func(spi_fd, &reg_value);

    if (reg_value != 0x0124) {
        fprintf(stderr, "Error: Invalid WHO_AM_I value\n");
        exit(EXIT_FAILURE);
    }
}

void sample_angular_rate(void) {
    uint32_t reg_value;
    uint32_t angular_rate;

    spi_write_func(spi_fd, REG_ADDR | 0x40); // Read angular rate register

    spi_read_func(spi_fd, &reg_value);

    angular_rate = (reg_value >> 16) * SCALE_FACTOR;

    // Append timestamp and angular rate to CSV file
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open gyro_log.csv");
        exit(EXIT_FAILURE);
    }

    time_t now = time(NULL);
    char time_str[80];
    sprintf(time_str, "%ld", now);
    fprintf(log_file, "%s, %lu\n", time_str, (unsigned long)angular_rate);
    fclose(log_file);
}

void *thread_func(void *arg) {
    while (1) {
        read_who_am_i();
        sample_angular_rate();
        usleep(SAMPLE_RATE_MS * 1000 / HRTIME_PER_SEC);
    }
    return NULL;
}

int main(int argc, char *argv[]) {
    spi_init();
    gpio_init();

    pthread_t thread;
    int ret = pthread_create(&thread, NULL, thread_func, NULL);
    if (ret != 0) {
        perror("Failed to create thread");
        spi_close(spi_fd);
        close(gpio_fd);
        exit(EXIT_FAILURE);
    }

    // Handle SIGINT gracefully
    atexit(function_to_exit_on_sigint);

    // Wait for the thread to finish
    pthread_join(thread, NULL);

    spi_close(spi_fd);
    close(gpio_fd);

    return 0;
}

void function_to_exit_on_sigint(int sig) {
    fprintf(stderr, "Exiting on SIGINT\n");
    spi_close(spi_fd);
    close(gpio_fd);
    exit(0);
}
```

This code initializes SPI and GPIO, checks for errors, and performs the required operations. It reads the WHO_AM_I register, samples the angular rate at 10ms intervals, converts the raw value to degrees per second, appends timestamped readings to a CSV file, and handles SIGINT gracefully. The code uses libgpiod for GPIO initialization and SPI operations.

