#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x68  // GY-50 L3G4200D gyroscope I2C address
#define SAMPLE_INTERVAL_MS 10
#define LOG_FILE "gyro_log.csv"
#define SENSITIVITY 8.75  // mdps/LSB
#define SENSITIVITY_FACTOR 1 / 114.285

#define MAX_RETRIES 3

int gyro_read_data(int file_descriptor, int reg_address) {
    char buffer[2] = {0};
    int ret = read(file_descriptor, buffer, 1);
    if (ret == -1) {
        perror("read");
        return -1;
    }
    if (buffer[0] != 'W') {
        return -1;  // Sensor not present
    }
    return 0;
}

int main(int argc, char *argv[]) {
    int file_descriptor, i2c_fd;
    char log_header[] = "Timestamp,X,Y,Z\n";
    char timestamp_str[38];
    int ret;

    file_descriptor = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (file_descriptor == -1) {
        perror("open");
        return EXIT_FAILURE;
    }

    i2c_fd = open(fmt_i2c_device(I2C_BUS, I2C_ADDR), O_RDWR);
    if (i2c_fd == -1) {
        perror("open");
        close(file_descriptor);
        return EXIT_FAILURE;
    }

    ret = gyro_read_data(file_descriptor, 0x26);
    if (ret != 0) {
        close(i2c_fd);
        close(file_descriptor);
        return EXIT_FAILURE;
    }

    ret = gpioInitialise();
    if (ret != 0) {
        close(i2c_fd);
        close(file_descriptor);
        return EXIT_FAILURE;
    }

    for (int retry = 0; retry < MAX_RETRIES; retry++) {
        ret = pigpio_setup(i2c_fd, 100000);
        if (ret == 0) {
            break;
        }
        if (errno == EAGAIN || errno == EWOULDBLOCK) {
            usleep(10000);  // Wait for a bit
        } else {
            perror("pigpio_setup");
            return EXIT_FAILURE;
        }
    }
    if (retry == MAX_RETRIES) {
        close(i2c_fd);
        close(file_descriptor);
        return EXIT_FAILURE;
    }

    while (1) {
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        snprintf(timestamp_str, sizeof(timestamp_str), "%llu", (long long)ts.tv_sec * 1000000000 + ts.tv_nsec);
        ret = pigpio_write_i2c_mem(i2c_fd, 0x2A, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00);
        if (ret != 0) {
            perror("pigpio_write_i2c_mem");
            break;
        }

        ret = pigpio_read_i2c_mem(i2c_fd, 0x2C, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00);
        if (ret == -1) {
            perror("pigpio_read_i2c_mem");
            break;
        }

        int16_t x, y, z;
        memcpy(&x, (void *)((uint8_t *)ret + 0x02), 2);
        memcpy(&y, (void *)((uint8_t *)ret + 0x04), 2);
        memcpy(&z, (void *)((uint8_t *)ret + 0x06), 2);

        double raw_x = (double)x;
        double raw_y = (double)y;
        double raw_z = (double)z;

        double gyro_x = raw_x * SENSITIVITY_FACTOR;
        double gyro_y = raw_y * SENSITIVITY_FACTOR;
        double gyro_z = raw_z * SENSITIVITY_FACTOR;

        char log_entry[68];
        snprintf(log_entry, sizeof(log_entry), "%s,%f,%f,%f\n", timestamp_str, gyro_x, gyro_y, gyro_z);
        write(file_descriptor, log_entry, strlen(log_entry));

        usleep(SAMPLE_INTERVAL_MS * 1000 / 1000000);  // Convert ms to microseconds
    }

    pigpio_cleanup();
    close(i2c_fd);
    close(file_descriptor);

    return EXIT_SUCCESS;
}

