#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define POLL_INTERVAL 500
#define LOG_FILE "flame_events.log"

void signal_handler(int signum) {
    sigset_t set;
    sigaddset(&set, SIGINT);
    pthread_sigmask(SIG_BLOCK, &set, NULL);
    flame_detected = 0;
}

int main() {
    int flame_detected = 0;
    sigset_t set;
    pthread_t sigint_thread;

    // Initialize pigpio
    if (pigpioInitialise() < 0) {
        perror("Failed to initialize pigpio");
        return EXIT_FAILURE;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);
    pthread_create(&sigint_thread, NULL, signal_handler_thread, NULL);

    // Open log file
    int log_fd = open(LOG_FILE, O_APPEND | O_CREAT | O_WRONLY, S_IRUSR | S_IWUSR);
    if (log_fd == -1) {
        perror("Failed to open log file");
        pigpioTerminate();
        return EXIT_FAILURE;
    }

    // Enable internal pull-up resistor
    gpioSetMode(GPIO_PIN, PI_OUTPUT_ACTIVE);
    gpioOutput(GPIO_PIN, 0);

    while (1) {
        int sensor_state = gpioRead(GPIO_PIN);

        if (sensor_state == PI_INPUT_LOW) {
            flame_detected = 1;
            printf("FLAME DETECTED!\n");
            fprintf(log_fd, "YYYY-MM-DD HH:MM:SS – Flame detected: YES\n");
        } else {
            flame_detected = 0;
            fprintf(log_fd, "YYYY-MM-DD HH:MM:SS – Flame detected: NO\n");
        }

        if (flame_detected) {
            printf("Flame detected!\n");
        }

        usleep(POLL_INTERVAL * 1000);
    }

    // Clean up
    close(log_fd);
    pigpioTerminate();
    pthread_join(sigint_thread, NULL);
    return EXIT_SUCCESS;
}

void signal_handler_thread(void *arg) {
    while (1) {
        usleep(1000000);
    }
}

