#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x5A  // Omron D7S-0001 sensor I2C address
#define SAMPLE_INTERVAL_MS 100
#define LOG_FILE "vibration_log.csv"

#define BUFFER_SIZE 128
char buffer[BUFFER_SIZE];

int i2c_fd;

void init_i2c() {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open i2c bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

void write_to_log(const char *timestamp, int x, int y, int z) {
    time_t now = time(NULL);
    struct tm *time_info = localtime(&now);

    sprintf(buffer, "%s,%d,%d,%d\n",
        asctime(time_info), x, y, z);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    fputs(buffer, log_file);
    fclose(log_file);
}

void read_sensor_data() {
    struct i2c_rdwr_cmd cmd = {
        .addr = I2C_ADDR,
        .flags = I2C_M_READ,
        .len = sizeof(int32_t) * 3,
        .buf = (void *) &x_value,
    };

    if (ioctl(i2c_fd, I2C_RDWR, &cmd) < 0) {
        if (errno == EIO || errno == EBUSY) {
            fprintf(stderr, "Sensor not present or I2C bus busy\n");
            return;
        }
        perror("Failed to read from sensor\n");
        return;
    }

    write_to_log(
        strftime("%Y-%m-%dT%H:%M:%SZ", NULL),
        x_value, y_value, z_value);
}

int main() {
    init_i2c();

    int x_value, y_value, z_value;
    while (1) {
        read_sensor_data();
        usleep(SAMPLE_INTERVAL_MS / 1000);
    }

    close(i2c_fd);
    return 0;
}

