#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x52  // GY-45 MMA8452Q I2C address
#define WHO_AM_I_REG 0x1A
#define CONTROL_REG 0x20
#define DATA_RATE_REG 0x21
#define STANDBY_REG 0x22
#define DATA_REG 0x23
#define X_DATA_REG 0x24
#define Y_DATA_REG 0x25
#define Z_DATA_REG 0x26
#define TILT_THRESHOLD 45
#define LOG_FILE "fall_log.txt"
#define LOG_INTERVAL_MS 10000  // 100 Hz
#define LOG_LINE_LENGTH 20

int i2c_fd;

void signal_handler(int signum) {
    close(i2c_fd);
    fclose(log_fd);
    exit(0);
}

void install_signal_handlers() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);
}

int verify_sensor() {
    unsigned char who_am_i[1];
    read(i2c_fd, who_am_i, sizeof(who_am_i));
    if (who_am_i[0] != 0x49) {
        fprintf(stderr, "Error: Incorrect sensor identity, expected 0x49, got 0x%02x\n", who_am_i[0]);
        exit(1);
    }
    return 0;
}

int init_device() {
    unsigned char control[1];
    write(i2c_fd, &CONTROL_REG, sizeof(CONTROL_REG));
    read(i2c_fd, control, sizeof(control));
    if (!(control[0] & 0x02)) {
        fprintf(stderr, "Error: Control register does not have standby bit set\n");
        return -1;
    }

    write(i2c_fd, &DATA_RATE_REG, sizeof(DATA_RATE_REG));
    read(i2c_fd, control, sizeof(control));
    if (!(control[0] & 0x01)) {
        fprintf(stderr, "Error: Data rate not set to 100Hz\n");
        return -1;
    }

    write(i2c_fd, &STANDBY_REG, sizeof(STANDBY_REG));
    read(i2c_fd, control, sizeof(control));
    if (!(control[0] & 0x01)) {
        fprintf(stderr, "Error: Sensor not placed in standby mode\n");
        return -1;
    }

    return 0;
}

int read_data() {
    unsigned char data[6];
    read(i2c_fd, data, sizeof(data));

    int x = (data[0] << 8) | data[1];
    int y = (data[2] << 8) | data[3];
    int z = (data[4] << 8) | data[5];

    return x | (y << 8) | z << 16;
}

void log_tilt(int x, int y, int z) {
    time_t now = time(NULL);
    char timestamp[LOG_LINE_LENGTH];
    sprintf(timestamp, "%ld", now);

    char log_line[LOG_LINE_LENGTH + 10];
    sprintf(log_line, "%s: X=%d, Y=%d, Z=%d\n", timestamp, x, y, z);
    write(log_fd, log_line, strlen(log_line));
}

int main() {
    install_signal_handlers();

    int log_fd = open(LOG_FILE, O_APPEND | O_CREAT, 0644);
    if (log_fd == -1) {
        perror("Error opening log file");
        exit(1);
    }

    if ((i2c_fd = open(I2C_BUS, O_RDWR)) == -1) {
        perror("Error opening I2C bus");
        exit(1);
    }

    if (verify_sensor() < 0) {
        exit(1);
    }

    if (init_device < 0) {
        close(i2c_fd);
        fclose(log_fd);
        exit(1);
    }

    while (1) {
        int raw_values = read_data();
        int x = raw_values & 0xFF;
        int y = (raw_values >> 8) & 0xFF;
        int z = (raw_values >> 16) & 0xFF;

        if (abs(x) > TILT_THRESHOLD || abs(y) > TILT_THRESHOLD || abs(z) > TILT_THRESHOLD) {
            log_tilt(x, y, z);
        }

        usleep(LOG_INTERVAL_MS / 1000);
    }

    close(i2c_fd);
    fclose(log_fd);
    return 0;
}

