#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <pthread.h>
#include <libgpiod.h>

#define I2C_BUS 1
#define I2C_ADDR 0x68  // LIS3MDL magnetometer I2C address
#define CALIBRATION_OFFSET 0.001  // Calibration offset in mG
#define SENSITIVITY 0.146  // Sensitivity in mG/LSB
#define LOG_FILE "magnetic_log.txt"
#define MAX_READ_ATTEMPTS 3

#define BUFFER_SIZE 100

// Function prototypes
int i2c_open(int fd, const char *bus, int address);
int i2c_write_reg(int fd, uint8_t reg, uint8_t data);
uint16_t i2c_read_reg(int fd, uint8_t reg);
void calibrate_data(uint16_t x, uint16_t y, uint16_t z);
void write_to_log(const char *data);
void* sensor_thread(void* arg);

int main(int argc, char* argv[]) {
    int i2c_fd, log_fd;
    pthread_t sensor_thread_id;
    int ret;

    // Initialize libgpiod
    if (gpio_init() < 0) {
        perror("Failed to initialize libgpiod");
        exit(EXIT_FAILURE);
    }

    // Open I2C bus
    i2c_fd = i2c_open(i2c_fd, I2C_BUS, I2C_ADDR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    // Open log file
    log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    // Initialize sensor data buffer
    char buffer[BUFFER_SIZE];
    pthread_create(&sensor_thread_id, NULL, sensor_thread, NULL);

    // Main loop
    while (1) {
        // Read sensor data
        uint16_t x, y, z;
        ret = i2c_read_reg(i2c_fd, 0x3B);  // Register for X, Y, Z data
        if (ret < 0) {
            if (errno == EIO || errno == E2BIG) {
                // Retry up to MAX_READ_ATTEMPTS times
                for (int i = 0; i < MAX_READ_ATTEMPTS; i++) {
                    sleep(1);
                    ret = i2c_read_reg(i2c_fd, 0x3B);
                    if (ret >= 0)
                        break;
                }
                if (ret < 0) {
                    perror("Failed to read sensor data after retries");
                    exit(EXIT_FAILURE);
                }
            } else {
                perror("Unexpected error reading sensor data");
                exit(EXIT_FAILURE);
            }
        }

        // Calibrate data
        calibrate_data(x, y, z);

        // Check for metal-detector alert
        if (x * x + y * y + z * z > 800.0) {
            fprintf(stderr, "Metal detector alert: %f, %f, %f\n", x, y, z);
        }

        // Write to log file
        snprintf(buffer, BUFFER_SIZE, "%f, %f, %f\n", x, y, z);
        write_to_log(buffer);

        // Sleep for 10ms
        usleep(10000);
    }

    // Clean up and exit
    close(log_fd);
    close(i2c_fd);
    pthread_join(sensor_thread_id, NULL);
    libgpiod_cleanup();
    return 0;
