#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <errno.h>
#include <libgpiod.h>

#define SPI_CHANNEL 0
#define CE0_GPIO 8
#define SPI_CLOCK_FREQ 1000000
#define LOG_FILE "vibration_log.txt"
#define LOG_INTERVAL 0.1  // 100ms

#define RESET_REG 0x00
#define POWER_CONTROL_REG 0x01
#define STATUS_REG 0x02
#define PARTID 0x00000001

int main(int argc, char *argv[]) {
    int spi_fd, log_fd;
    struct stat sb;
    char log_msg[100];

    // Initialize libgpiod
    if (gpiod_init() < 0) {
        perror("libgpiod init failed");
        exit(EXIT_FAILURE);
    }

    // Configure SPI channel 0 CE0 on GPIO8 (BCM)
    if (gpiod_gpio_set_mode(CE0_GPIO, GPIOD_MODE_OUTPUT) < 0) {
        perror("Failed to set CE0 GPIO mode");
        exit(EXIT_FAILURE);
    }

    if (gpiod_gpio_output_init(CE0_GPIO, 0) < 0) {
        perror("Failed to initialize CE0 GPIO output");
        exit(EXIT_FAILURE);
    }

    // Configure SPI clock
    if (gpiod_gpio_set_drive(CE0_GPIO, 1) < 0) {
        perror("Failed to set CE0 GPIO drive");
        exit(EXIT_FAILURE);
    }

    // Open SPI device
    spi_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (spi_fd < 0) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    // Open SPI channel
    if (gpiod_spi_channel_init(SPI_CHANNEL, CE0_GPIO) < 0) {
        perror("Failed to initialize SPI channel");
        exit(EXIT_FAILURE);
    }

    // Reset sequence
    if (gpiod_gpio_write(CE0_GPIO, 1) < 0) {
        perror("Failed to reset GPIO");
        exit(EXIT_FAILURE);
    }
    usleep(100000); // Wait 1ms

    if (gpiod_gpio_write(CE0_GPIO, 0) < 0) {
        perror("Failed to clear RUN bit");
        exit(EXIT_FAILURE);
    }

    while (!(gpiod_gpio_read(CE0_GPIO) & (1 << 6))) {
        usleep(100000); // Wait until STABLE bit is set
    }

    if (gpiod_gpio_write(CE0_GPIO, 1) < 0) {
        perror("Failed to set RUN bit");
        exit(EXIT_FAILURE);
    }

    // Verify sensor presence
    if (gpiod_spi_channel_read_32(SPI_CHANNEL, RESET_REG) != RESET_REG) {
        fprintf(spi_fd, "Failed to reset sensor\n");
        exit(EXIT_FAILURE);
    }

    // Read acceleration data
    while (1) {
        int x, y, z;
        if (gpiod_spi_channel_read_32(SPI_CHANNEL, PARTID) != PARTID) {
            fprintf(spi_fd, "Failed to read PARTID\n");
            continue;
        }

        x = gpiod_spi_channel_read_32(SPI_CHANNEL, STATUS_REG >> 2);
        y = gpiod_spi_channel_read_32(SPI_CHANNEL, STATUS_REG);
        z = gpiod_spi_channel_read_32(SPI_CHANNEL, STATUS_REG >> 8);

        snprintf(log_msg, sizeof(log_msg), "Time: %lu, X: %d, Y: %d, Z: %d\n", (unsigned long)time(NULL), x, y, z);
        if (write(spi_fd, log_msg, strlen(log_msg)) < 0) {
            perror("Failed to write to log file");
            exit(EXIT_FAILURE);
        }

        usleep(LOG_INTERVAL * 100000); // Wait for next log interval
    }

    // Graceful shutdown
    if (signal(SIGINT) == SIG_IGN || signal(SIGTERM) == SIG_IGN) {
        fprintf(spi_fd, "Shutdown initiated\n");
        close(spi_fd);
        close(log_fd);
        gpiod_spi_channel_deinit(SPI_CHANNEL);
        gpiod_gpio_output_deinit(CE0_GPIO);
        gpiod_init();
        exit(0);
    }

    return 0;
}

