#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod/gpio.h>

#define SENSOR_PIN 17
#define CHIP_ID 4

void signal_handler(int signum) {
    printf("Self-parking sequence received SIGINT, shutting down...\n");
    gpio_line_disable(CHIP_ID, SENSOR_PIN);
    exit(0);
}

int main() {
    struct sigaction sa;

    // Initialize signal handler
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    // Initialize libgpiod
    if (libgpiod_init() < 0) {
        perror("libgpiod_init failed");
        exit(EXIT_FAILURE);
    }

    // Open the GPIO line
    int line_fd = libgpiod_open_chip(CHIP_ID);
    if (line_fd < 0) {
        perror("libgpiod_open_chip failed");
        exit(EXIT_FAILURE);
    }

    // Request the GPIO line
    if (libgpiod_request_line(line_fd, SENSOR_PIN) < 0) {
        perror("libgpiod_request_line failed");
        libgpiod_close_chip(line_fd);
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (1) {
        int sensor_value = libgpiod_get_value(line_fd, SENSOR_PIN);

        if (sensor_value == 0) {
            time_t now = time(NULL);
            printf("Self-parking sequence started at %s\n", asctime(localtime(&now)));
        }

        usleep(1000000); // Sleep for 1 second
    }

    // Clean up and exit
    gpio_line_disable(CHIP_ID, SENSOR_PIN);
    libgpiod_close_chip(line_fd);
    libgpiod_exit();

    return 0;
}

