#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>
#include <errno.h>
#include <pigpio.h>

#define SENSOR1_GPIO 17
#define SENSOR2_GPIO 27
#define POLL_INTERVAL_MS 100

int main(int argc, char *argv[]) {
    pigpio_setup(1); // Initialize pigpio library
    if (pigpio_init() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    gpioSetMode(SENSOR1_GPIO, PI_OUTPUT);
    gpioSetMode(SENSOR2_GPIO, PI_OUTPUT);

    while (1) {
        int sensor1_state = gpioRead(SENSOR1_GPIO);
        int sensor2_state = gpioRead(SENSOR2_GPIO);

        if (sensor1_state == 0 && sensor2_state == 0) {
            printf("Path clear at %lu ms\n", (unsigned long)usleep(POLL_INTERVAL_MS * 1000));
        } else if (sensor1_state == 1 || sensor2_state == 1) {
            printf("Obstacle detected at %lu ms\n", (unsigned long)usleep(POLL_INTERVAL_MS * 1000));
        } else {
            printf("Unknown state at %lu ms\n", (unsigned long)usleep(POLL_INTERVAL_MS * 1000));
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    pigpio_cleanup(); // Release resources on exit
    return 0;
}

