    if (ioctl(spi_fd, SPI_SET_MODE, SPI_MODE3) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_SET_BITS per_chip, 8) < 0) {
        perror("Failed to set bits per chip");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_SET_CLOCK_POLARITY, 0) < 0) {
        perror("Failed to set clock polarity");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_SET_CLOCK_PHASE, 1) < 0) {
        perror("Failed to set clock phase");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }
}

int read_gyro_data() {
    unsigned int address = ADDRESS | 0x80; // Set MSB
    write(spi_fd, &address, sizeof(address));

    if (read(spi_fd, spi_buffer, TRANSFER_SIZE) != TRANSFER_SIZE) {
        perror("Failed to read from SPI");
        return -1;
    }

    return spi_buffer[1]; // Read 2-byte data
}

void process_gyro_data(unsigned int data) {
    int x, y, z;

    x = (data & 0xFF00) * SCALE_FACTOR;
    y = (data & 0x00FF) * SCALE_FACTOR;
    z = 0; // Assuming Z is not available

    printf("X: %.2f deg/s, Y: %.2f deg/s, Z: %.2f deg/s\n", x, y, z);
}

int main() {
    spi_init();

    while (1) {
        unsigned int data = read_gyro_data();
        if (data == -1) {
            perror("Failed to read gyro data");
            break;
        }
        process_gyro_data(data);
        usleep(100000); // 100 ms delay
    }

    close(spi_fd);
    return 0;
}
```

This code initializes the SPI device, sets the SPI mode, bits per chip, clock polarity, and clock phase. It then defines a function to read the gyroscope data using a two-transfer read protocol. The `process_gyro_data` function applies the scale factor to convert the raw data into angular rates and logs them to the console. The main function runs in an infinite loop, reading the gyroscope data every 100 ms and handling any errors that occur during the process. Upon exit, it closes the SPI device file descriptor.

