#define I2C_BUS 1
#define I2C_ADDR 0x68  // LSM6DSR IMU default I2C address
#define SAMPLE_INTERVAL_MS 100

// Function to handle SIGINT (Ctrl+C)
void sigint_handler(int signum) {
    printf("\nExiting on SIGINT...\n");
    gpiod_disable(I2C_BUS);
    close(I2C_FILE);
    exit(EXIT_SUCCESS);
}

int main() {
    int I2C_FILE;
    struct i2c_client *client;
    uint8_t buffer[6];
    int read_bytes;

    // Initialize signal handler
    signal(SIGINT, sigint_handler);

    // Initialize libgpiod for I2C bus control
    if (libgpiod_init(I2C_BUS) != 0) {
        perror("libgpiod_init");
        exit(EXIT_FAILURE);
    }

    // Open I2C bus
    client = gpiod_open_client(I2C_BUS, 0);
    if (client == NULL) {
        perror("gpiod_open_client");
        exit(EXIT_FAILURE);
    }

    // Set I2C bus frequency (default is 100kHz)
    if (libgpiod_set_bus_freq(client, 100000) != 0) {
        perror("libgpiod_set_bus_freq");
        gpiod_close_client(client);
        exit(EXIT_FAILURE);
    }

    // Check WHO_AM_I register to ensure correct device is addressed
    if (libgpiod_write_byte(client, 0x00) != 0) {
        perror("libgpiod_write_byte");
        gpiod_close_client(client);
        exit(EXIT_FAILURE);
    }

    // Open I2C device
    client = gpiod_open_client(I2C_BUS, I2C_ADDR);
    if (client == NULL) {
        perror("gpiod_open_client");
        gpiod_close_all_clients(client);
        exit(EXIT_FAILURE);
    }

    // Read 6 bytes (X, Y, Z for accelerometer and gyroscope)
    read_bytes = gpiod_read_burst(client, buffer, 6, 1);
    if (read_bytes < 6) {
        if (read_bytes == -1) {
            perror("gpiod_read_burst");
        } else {
            fprintf(stderr, "Error reading from LSM6DSR IMU\n");
            exit(EXIT_FAILURE);
        }
    }

    // Process the read data
    for (int i = 0; i < 6; i++) {
        printf("%d ", buffer[i]);
    }
    printf("\n");

    // Close I2C device
    gpiod_close_client(client);
    gpiod_close_all_clients();

    return 0;
}

