#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SDA_PIN 2
#define SCL_PIN 3

#define FXOS8700_ID_REG 0x2A
#define FXOS8700_REG_STATUS 0x3A
#define FXOS8700_REG_ACCEL_X 0x3B
#define FXOS8700_REG_ACCEL_Y 0x3C
#define FXOS8700_REG_ACCEL_Z 0x3D
#define FXOS8700_REG_MAG_X 0x3E
#define FXOS8700_REG_MAG_Y 0x3F
#define FXOS8700_REG_MAG_Z 0x40

int i2c_fd;

int open_i2c(int bus, int address) {
    char device_path[16];
    snprintf(device_path, sizeof(device_path), "/dev/i2c-%d-%d", bus, address);

    i2c_fd = open(device_path, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, address) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return -1;
    }

    return i2c_fd;
}

int read_i2c(int fd, uint8_t *buffer, size_t len) {
    return read(fd, buffer, len);
}

int write_i2c(int fd, uint8_t *buffer, size_t len) {
    return write(fd, buffer, len);
}

int close_i2c(int fd) {
    close(fd);
    return 0;
}

int main(int argc, char *argv[]) {
    int status;
    uint8_t fxos8700_id[2];
    uint16_t accel_x, accel_y, accel_z, mag_x, mag_y, mag_z;

    if (argc != 2) {
        fprintf(stderr, "Usage: %s <address>\n", argv[0]);
        exit(1);
    }

    status = open_i2c(I2C_BUS, atoi(argv[1]));
    if (status < 0) {
        return EXIT_FAILURE;
    }

    // Read device ID
    status = read_i2c(i2c_fd, fxos8700_id, sizeof(fxos8700_id));
    if (status != sizeof(fxos8700_id)) {
        fprintf(stderr, "Failed to read device ID\n");
        close_i2c(i2c_fd);
        return EXIT_FAILURE;
    }

    if (fxos8700_id[0] != 0x19 || fxos8700_id[1] != 0x01) {
        fprintf(stderr, "Device is not FXOS8700\n");
        close_i2c(i2c_fd);
        return EXIT_FAILURE;
    }

    // Initialize sensor
    write_i2c(i2c_fd, 0x6B, 0x00); // Command to initialize the sensor

    // Read 12-byte block
    uint8_t data[12];
    status = read_i2c(i2c_fd, data, sizeof(data));
    if (status != sizeof(data)) {
        fprintf(stderr, "Failed to read 12-byte block\n");
        close_i2c(i2c_fd);
        return EXIT_FAILURE;
    }

    // Extract accelerometer data
    accel_x = (data[0] << 8) | data[1];
    accel_y = (data[2] << 8) | data[3];
    accel_z = (data[4] << 8) | data[5];

    // Extract magnetometer data
    mag_x = (data[6] << 8) | data[7];
    mag_y = (data[8] << 8) | data[9];
    mag_z = data[10];

    // Print data
    printf("Accelerometer: X=%d, Y=%d, Z=%d\n", accel_x, accel_y, accel_z);
    printf("Magnetometer: X=%d, Y=%d, Z=%d\n", mag_x, mag_y, mag_z);

    // Clean up and exit
    close_i2c(i2c_fd);
    return EXIT_SUCCESS;
}

