#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/wait.h>
#include <errno.h>
#include <pthread.h>

#define I2C_ADDRESS 0x68 // ADXL345 I2C address
#define TILT_THRESHOLD 30.0
#define SAMPLE_INTERVAL_MS 100 // in milliseconds
#define LOG_FILE "/var/log/tilt_events.log"

typedef struct {
    int file;
    char *filename;
} LogFile;

LogFile log_file = { -1, LOG_FILE };

void log_tilt_event(const char *timestamp) {
    log_file.file = open(log_file.filename, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_file.file == -1) {
        perror("Failed to open log file");
        return;
    }
    fprintf(log_file.file, "%s\n", timestamp);
    close(log_file.file);
}

void *read_accel_data(void *arg) {
    int file = -1;
    int i2c_fd;
    struct i2c_client *client;
    uint8_t reg_addr[1];
    uint16_t data[3];

    reg_addr[0] = I2C_ADDRESS;

    file = open(log_file.filename, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (file == -1) {
        perror("Failed to open log file");
        return NULL;
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd == -1) {
        perror("Failed to open I2C bus");
        close(file);
        return NULL;
    }

    client = i2c_client_new(i2c_fd, "adxl345");
    if (!client) {
        perror("Failed to create I2C client");
        close(i2c_fd);
        close(file);
        return NULL;
    }

    if (i2c_mem_read(client, reg_addr, 1, &reg_addr[0]) < 0) {
        perror("Failed to read register address");
        i2c_client_free(client);
        close(i2c_fd);
        close(file);
        return NULL;
    }

    if (i2c_mem_read(client, 0x2A, 2, data) < 0) {
        perror("Failed to read acceleration data");
        i2c_client_free(client);
        close(i2c_fd);
        close(file);
        return NULL;
    }

    close(client);
    i2c_client_free(client);
    close(i2c_fd);

    // Calculate tilt angle
    float x = (data[0] << 8) / 16.0;
    float y = (data[1] << 8) / 16.0;
    float z = (data[2] << 8) / 16.0;
    float tilt_rad = atan2(sqrt(x*x + y*y), z) * 180 / M_PI;

    if (tilt_rad > TILT_THRESHOLD) {
        log_tilt_event(strftime(NULL, 0, "%Y-%m-%d %H:%M:%S", localtime(NULL)));
    }

    return NULL;
}

int main(int argc, char *argv[]) {
    if (pthread_create(&thread_id, NULL, read_accel_data, NULL) != 0) {
        perror("Failed to create thread");
        return EXIT_FAILURE;
    }

    while (1) {
        usleep(SAMPLE_INTERVAL_MS * 1000 / 1000);
    }

    pthread_join(thread_id, NULL);
    close(log_file.file);
    return EXIT_SUCCESS;
}

