#include <pthread.h>
#include <gpiod.h>

#define GPIO_A 17
#define GPIO_B 27
#define RELAY_VOLTAGE 5
#define RELAY_PIN_HIGH 1
#define CODE_RANGE 100000
#define CODE_LENGTH 6
#define ACCESS_LOG_FILE "access_log.txt"

volatile sig_atomic_t quit = 0;

void signal_handler(int signum) {
    global_var.quit = 1;
}

void setup_gpio(void) {
    int fd = gpiod_request_pin_out(GPIO_A);
    if (fd < 0) {
        perror("Failed to request GPIO pin");
        exit(EXIT_FAILURE);
    }

    int ret = gpiod_pin_configure(fd, 0);
    if (ret < 0) {
        perror("Failed to configure GPIO pin");
        exit(EXIT_FAILURE);
    }

    fd = gpiod_request_pin_out(GPIO_B);
    if (fd < 0) {
        perror("Failed to request GPIO pin");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_pin_output_initial_value(fd, RELAY_PIN_HIGH);
    if (ret < 0) {
        perror("Failed to set GPIO pin initial value");
        exit(EXIT_FAILURE);
    }
}

void generate_code(unsigned int *code) {
    srand(time(NULL));
    *code = rand() % (999999 - 100000 + 1) + 100000;
}

void print_code(const unsigned int *code) {
    printf("Access code: %06u\n", *code);
}

void read_code(unsigned int *code) {
    char c;
    while ((c = getchar()) && (!isdigit(c) || c == '\n')) {
        putchar(' ');
    }

    if (c == '\n') {
        putchar(' ');
        getchar();
    }

    if (scanf("%u", code) != 1) {
        fprintf(stderr, "Invalid input, please enter a six-digit number.\n");
        exit(EXIT_FAILURE);
    }
}

void log_access(const char *timestamp, const unsigned int code) {
    time_t rawtime;
    struct tm * timeinfo;
    char buffer[80];

    time ( &rawtime );
    timeinfo = localtime ( &rawtime );

    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);

    FILE *fp = fopen(ACCESS_LOG_FILE, "a");
    if (!fp) {
        perror("Failed to open access log file");
        exit(EXIT_FAILURE);
    }

    fprintf(fp, "%s, %u\n", buffer, code);
    fclose(fp);
}

int main(int argc, char *argv[]) {
    unsigned int code_a, code_b;
    setup_gpio();

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (argc < 2) {
        fprintf(stderr, "Usage: %s [code_a] [code_b]\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    code_a = atoi(argv[1]);
    code_b = atoi(argv[2]);

    print_code(&code_a);
    read_code(&code_b);

    if (code_a == code_b) {
        log_access(NULL, code_a);
        printf("Access granted\n");
    } else {
        printf("Access denied\n");
    }

    gpiod_pin_output_disable(GPIO_A);
    gpiod_pin_output_disable(GPIO_B);

    fclose(stdout);
    fclose(stderr);

    return 0;
}

