#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/wait.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x23  // BH1750FVI sensor address
#define LOG_FILE "light_log.txt"
#define CONVERSION_TIMEOUT_MS 180000  // 180 seconds
#define LOG_INTERVAL_SEC 5

void handle_signal(int signum) {
    printf("Received signal, exiting gracefully...\n");
    pioStop();
    close(logfd);
    exit(0);
}

int main() {
    int logfd;
    struct i2c_client i2c_client;
    int ret;
    char timestamp[32];
    long lux_value;

    // Initialize pigpio for GPIO control
    if (piGPIO_init() < 0) {
        perror("Failed to initialize pigpio");
        return EXIT_FAILURE;
    }

    // Initialize I2C bus
    memset(&i2c_client, 0, sizeof(i2c_client));
    i2c_client.device = I2C_BUS;
    i2c_client.address = I2C_ADDR;

    // Open the log file
    logfd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (logfd < 0) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    // Set up signal handler for SIGINT
    signal(SIGINT, handle_signal);

    // Start I2C communication
    if (ioctl(i2c_client.bus, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C address");
        return EXIT_FAILURE;
    }

    // Read illuminance data
    struct i2c_msg msg;
    msg.function = I2C_READ_BYTE;
    msg.len = 1;
    msg.data = &lux_value;

    ret = ioctl(i2c_client.fd, I2C_MSG_READ, &msg);
    if (ret < 0) {
        if (errno == ETIMEDOUT) {
            printf("Timeout reading from sensor, retrying...\n");
            usleep(CONVERSION_TIMEOUT_MS / 1000);
            ret = ioctl(i2c_client.fd, I2C_MSG_READ, &msg);
        } else {
            perror("Failed to read from sensor");
            return EXIT_FAILURE;
        }
    }

    // Check for sensor error
    if (ret != msg.len) {
        perror("Failed to read sensor data");
        return EXIT_FAILURE;
    }

    // Log the reading
    time_t now = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    fprintf(logfd, "%s: %ld, Lux: %ld\n", timestamp, (long)lux_value, (long)lux_value);

    // Wait for LOG_INTERVAL_SEC seconds before the next reading
    usleep(LOG_INTERVAL_SEC * 1000000);

    // Clean up and exit
    pioStop();
    close(logfd);
    return EXIT_SUCCESS;
}

