#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x77  // HMC5883L default I2C address
#define BUFFER_SIZE 100
#define PRINT_INTERVAL 500  // milliseconds

int i2c_fd;
unsigned char buffer[6];
int raw_x, raw_y, raw_z;
int offset_x, offset_y, offset_z;
int sample_count = 0;

void handle_i2c_error(const char *msg) {
    fprintf(stderr, "I2C error: %s\n", msg);
}

void setup_i2c() {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        handle_i2c_error("Failed to set I2C slave address");
        exit(EXIT_FAILURE);
    }
}

void read_magnetometer() {
    memset(buffer, 0, sizeof(buffer));

    if (read(i2c_fd, buffer, 6) != 6) {
        handle_i2c_error("Failed to read from I2C device");
        return;
    }

    raw_x = buffer[0] << 8 | buffer[1];
    raw_y = buffer[2] << 8 | buffer[3];
    raw_z = buffer[4] << 8 | buffer[5];

    sample_count++;
}

void compute_offsets() {
    static int offset_x_sum = 0, offset_y_sum = 0, offset_z_sum = 0;
    static int offset_x_count = 0, offset_y_count = 0, offset_z_count = 0;

    offset_x_sum += raw_x;
    offset_y_sum += raw_y;
    offset_z_sum += raw_z;

    offset_x_count++;
    offset_y_count++;
    offset_z_count++;

    if (offset_x_count > BUFFER_SIZE) {
        offset_x = (offset_x_sum / offset_x_count) - (raw_x / BUFFER_SIZE);
        offset_y = (offset_y_sum / offset_y_count) - (raw_y / BUFFER_SIZE);
        offset_z = (offset_z_sum / offset_z_count) - (raw_z / BUFFER_SIZE);
    }
}

void print_corrected_data() {
    if (sample_count >= BUFFER_SIZE) {
        printf("Offset-corrected X: %d, Y: %d, Z: %d\n", raw_x - offset_x, raw_y - offset_y, raw_z - offset_z);
    }
}

int main(int argc, char *argv[]) {
    setup_i2c();

    while (1) {
        read_magnetometer();
        compute_offsets();
        print_corrected_data();
        usleep(PRINT_INTERVAL * 1000 / HRTIME_PER_SEC);
    }

    close(i2c_fd);
    return 0;
}

