#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define BUFFER_SIZE 64
#define ACCEL_ADDR 0x19
#define INT1_GPIO 23
#define INT1_PIN 16
#define SENSITIVITY 0.061
#define THRESHOLD 2000
#define DURATION 0

#define LOG_FILE "/tmp/lsm303d_mon.log"

typedef struct {
    int16_t x[3];
    int16_t y[3];
    int16_t z[3];
} AccelData;

typedef struct {
    AccelData buffer;
    int head;
    int tail;
} CircularBuffer;

int init_lsm303d(CircularBuffer *cb) {
    int file;
    char identity_reg[2];

    file = open(LOG_FILE, O_WRONLY | O_CREAT, S_IRUSR | S_IWUSR);
    if (file == -1) {
        perror("Failed to open log file");
        return -1;
    }

    // Read identity register to verify device
    if (read(file, identity_reg, 2) != 2) {
        fprintf(stderr, "Failed to read identity register\n");
        close(file);
        return -1;
    }

    if (identity_reg[0] != 0x3A || identity_reg[1] != 0x00) {
        fprintf(stderr, "LSM303D identity register mismatch\n");
        close(file);
        return -1;
    }

    close(file);

    // Initialize I2C
    if (piod_init() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return -1;
    }

    // Open I2C bus
    if (piod_open_bus(0) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        piod_close_bus(0);
        return -1;
    }

    // Configure LSM303D
    if (piod_set_slave_addr(ACCEL_ADDR) < 0) {
        fprintf(stderr, "Failed to set LSM303D slave address\n");
        piod_close_bus(0);
        return -1;
    }

    if (piod_write(ACCEL_ADDR, 0x20, 2) < 0) {
        fprintf(stderr, "Failed to write control register\n");
        piod_close_bus(0);
        return -1;
    }

    if (piod_write(ACCEL_ADDR, 0x0F, 0x00) < 0) {
        fprintf(stderr, "Failed to configure interrupt threshold\n");
        piod_close_bus(0);
        return -1;
    }

    if (piod_write(ACCEL_ADDR, 0x21, 0x00) < 0) {
        fprintf(stderr, "Failed to configure interrupt duration\n");
        piod_close_bus(0);
        return -1;
    }

    if (piod_write(ACCEL_ADDR, 0x22, 0x00) < 0) {
        fprintf(stderr, "Failed to configure interrupt sensitivity\n");
        piod_close_bus(0);
        return -1;
    }

    // Enable INT1 interrupt
    if (piod_set_interrupt_enable(ACCEL_ADDR, 1, INT1_GPIO) < 0) {
        fprintf(stderr, "Failed to enable INT1 interrupt\n");
        piod_close_bus(0);
        return -1;
    }

    // Start I2C transaction
    if (piod_start_transaction(ACCEL_ADDR) < 0) {
        fprintf(stderr, "Failed to start I2C transaction\n");
        piod_close_bus(0);
        return -1;
    }

    cb->head = 0;
    cb->tail = 0;
    return 0;
}

void interrupt_handler(int signo) {
    if (signo == SIGINT) {
        // Disable LSM303D
        if (piod_write(ACCEL_ADDR, 0x00, 0x00) < 0) {
            fprintf(stderr, "Failed to disable LSM303D\n");
        }

        // Close I2C bus
        if (piod_close_bus(0) < 0) {
            fprintf(stderr, "Failed to close I2C bus\n");
        }

        exit(0);
    }
}

int main(int argc, char *argv[]) {
    CircularBuffer cb;
    piod_init();

    if (init_lsm303d(&cb) < 0) {
        return EXIT_FAILURE;
    }

    while (1) {
        // Read acceleration data
        if (piod_read(ACCEL_ADDR, cb.buffer.x, 3) != 3) {
            fprintf(stderr, "Failed to read acceleration data\n");
        }

        // Store in circular buffer
        cb.buffer.x[cb.head] = cb.buffer.x[cb.head] * SENSITIVITY;
        cb.buffer.y[cb.head] = cb.buffer.y[cb.head] * SENSITIVITY;
        cb.buffer.z[cb.head] = cb.buffer.z[cb.head] * SENSITIVITY;
        cb.head = (cb.head + 1) % BUFFER_SIZE;

        // Check for rising edge on INT1
        if (cb.buffer.x[cb.tail] > THRESHOLD) {
            fprintf(stderr, "INT1 edge detected\n");
            // Dump last ten samples
            for (int i = cb.tail - 9; i <= cb.tail - 1; i++) {
                printf("%d: x=%d, y=%d, z=%d\n", (int)time(NULL), cb.buffer.x[i], cb.buffer.y[i], cb.buffer.z[i]);
            }
        }

        // Sleep for 10ms
        usleep(10000);
    }

    piod_set_interrupt_disable(ACCEL_ADDR, 1);
    piod_close_bus(0);
    pigpio_terminate(1);

    return EXIT_SUCCESS;
}

int pigpio_main(int argc, char *argv[]) {
    return main(argc, argv);
}

