#define SERIAL0_PORT 14
#define SERIAL1_PORT 15
#define RELAY_GPIO1 17
#define RELAY_GPIO2 27
#define EXPECTED_CODE "123456"
#define READ_TIMEOUT 5000
#define BAUD_RATE 9600

void log_error(const char *msg) {
    peros(stderr, "[ERROR] %s\n", msg);
}

void handle_signal(int signum) {
    gpioWrite(RELAY_GPIO1, 0);
    gpioWrite(RELAY_GPIO2, 0);
    close(serial0_fd);
    close(serial1_fd);
    pigpioClose();
    exit(EXIT_SUCCESS);
}

int main(int argc, char *argv[]) {
    int serial0_fd, serial1_fd, ret;
    struct termios options;
    char input_buffer[6];
    char code1[6], code2[6];

    // Initialize pigpio
    if (pigpioInit() < 0) {
        log_error("Failed to initialize pigpio library");
        return EXIT_FAILURE;
    }

    // Set up UART ports
    ret = serialPortOpen(SERIAL0_PORT, &options);
    if (ret < 0) {
        log_error("Failed to open UART port /dev/serial0");
        return EXIT_FAILURE;
    }
    ret = serialPortOpen(SERIAL1_PORT, &options);
    if (ret < 0) {
        log_error("Failed to open UART port /dev/serial1");
        return EXIT_FAILURE;
    }

    // Configure UART settings
    cfmakeraw(&options);
    options.c_cflag = BAUD_RATE | CS8 | CLOCAL | CREAD;
    options.c_iflag = IGNPAR;
    options.c_oflag = 0;
    options.c_lflag = 0;
    if (serialPortSetMode(&options) < 0) {
        log_error("Failed to configure UART port settings");
        return EXIT_FAILURE;
    }

    // Read codes from UART ports
    while (1) {
        ret = serialRead(serial0_fd, input_buffer, 6);
        if (ret < 0) {
            log_error("Read timeout on /dev/serial0");
            usleep(READ_TIMEOUT);
            continue;
        }
        input_buffer[ret] = '\0';
        if (strncmp(input_buffer, EXPECTED_CODE, 6) == 0) {
            code1[0] = input_buffer[0];
            code1[1] = input_buffer[1];
            code1[2] = input_buffer[2];
            code1[3] = input_buffer[3];
            code1[4] = input_buffer[4];
            code1[5] = input_buffer[5];

            ret = serialRead(serial1_fd, input_buffer, 6);
            if (ret < 0) {
                log_error("Read timeout on /dev/serial1");
                usleep(READ_TIMEOUT);
                continue;
            }
            input_buffer[ret] = '\0';
            if (strncmp(input_buffer, EXPECTED_CODE, 6) == 0) {
                code2[0] = input_buffer[0];
                code2[1] = input_buffer[1];
                code2[2] = input_buffer[2];
                code2[3] = input_buffer[3];
                code2[4] = input_buffer[4];
                code2[5] = input_buffer[5];

                if (strcmp(code1, code2) == 0) {
                    gpioWrite(RELAY_GPIO1, 1);
                    gpioWrite(RELAY_GPIO2, 1);
                    usleep(2000000);
                    gpioWrite(RELAY_GPIO1, 0);
                    gpioWrite(RELAY_GPIO2, 0);
                }
            }
        }
        free(input_buffer);
    }

    // Handle SIGINT and SIGTERM signals
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        log_error("Failed to install SIGINT handler");
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        log_error("Failed to install SIGTERM handler");
    }

    // Clean shutdown
    gpioWrite(RELAY_GPIO1, 1);
    gpioWrite(RELAY_GPIO2, 1);
    close(serial0_fd);
    close(serial1_fd);
    pigpioClose();

    return EXIT_SUCCESS;
}

