#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <syslog.h>
#include <fcntl.h>
#include <errno.h>
#include <linux/gpio.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>

#define GPIO_PIN 4
#define RELAY_PIN 17
#define POLL_INTERVAL 50
#define CONTINUOUS_TIMEOUT 10000

#define LOG_FACILITY LOG_USER
#define LOG_LEVEL LOG_WARNING

void log_message(const char *format, ...) {
    va_list args;
    va_start(args, format);
    vsyslog(LOG_FACILITY, LOG_LEVEL, format, args);
    va_end(args);
}

int main(int argc, char *argv[]) {
    int gpio4_fd, relay_fd;
    struct i2c_client *client;
    int ret;

    // Initialize syslog
    openlog("pi_motion_detector", LOG_PID | LOG_PERR, LOG_USER);

    // Open GPIO4 line
    gpio4_fd = open("/dev/gpiomem", O_RDWR);
    if (gpio4_fd == -1) {
        log_message(LOG_ERR, "Failed to open /dev/gpiomem: %m");
        exit(EXIT_FAILURE);
    }

    // Set GPIO4 as output
    ret = ioctl(gpio4_fd, GPIOPIN_OUTPUT, 4);
    if (ret < 0) {
        log_message(LOG_ERR, "Failed to set GPIO4 as output: %m");
        close(gpio4_fd);
        exit(EXIT_FAILURE);
    }

    // Open relay line
    client = i2c_alloc_client(0, "12345678"); // Replace with actual I2C address
    if (!client) {
        log_message(LOG_ERR, "Failed to allocate I2C client");
        close(gpio4_fd);
        exit(EXIT_FAILURE);
    }

    ret = i2c_transfer(client, 0x00, 0x01, 0x00, 0x00, 0x00, 1000); // Assuming 1000ms for relay control
    if (ret < 0) {
        log_message(LOG_ERR, "Failed to communicate with I2C relay: %m");
        i2c_free_client(client);
        close(gpio4_fd);
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (1) {
        // Poll PIR sensor
        int pir_state = gpio_get_level(gpio4_fd);
        if (pir_state == 1) {
            log_message(LOG_INFO, "Motion detected on GPIO%d", GPIO_PIN);

            // Activate relay for 1 second
            ret = i2c_transfer(client, 0x00, 0x01, 0x00, 0x00, 0xFF, 1000);
            if (ret < 0) {
                log_message(LOG_ERR, "Failed to control relay: %m");
                i2c_free_client(client);
                close(gpio4_fd);
                exit(EXIT_FAILURE);
            }

            log_message(LOG_INFO, "Relay activated for 1 second");

            // Deactivate relay
            ret = i2c_transfer(client, 0x00, 0x01, 0x00, 0x00, 0x00, 1000);
            if (ret < 0) {
                log_message(LOG_ERR, "Failed to control relay: %m");
                i2c_free_client(client);
                close(gpio4_fd);
                exit(EXIT_FAILURE);
            }

            log_message(LOG_INFO, "Relay deactivated");
        }

        // Check for continuous motion
        if (pir_state == 1) {
            // Start timer for continuous motion detection
            struct timespec start_time, end_time;
            clock_gettime(CLOCK_REALTIME, &start_time);

            while (1) {
                clock_gettime(CLOCK_REALTIME, &end_time);
                uint64_t elapsed_time = (end_time.tv_sec - start_time.tv_sec) * 1000000000 + (end_time.tv_nsec - start_time.tv_nsec);

                if (elapsed_time > CONTINUOUS_TIMEOUT) {
                    log_message(LOG_WARNING, "Potential malfunction detected. De-energizing relay.");
                    ret = i2c_transfer(client, 0x00, 0x01, 0x00, 0x00, 0x00, 1000);
                    if (ret < 0) {
                        log_message(LOG_ERR, "Failed to control relay: %m");
                        i2c_free_client(client);
                        close(gpio4_fd);
                        exit(EXIT_FAILURE);
                    }

                    log_message(LOG_INFO, "Relay de-energized due to continuous motion");
                    break;
                }

                usleep(100000); // Sleep for 100ms
            }
        }

        usleep(POLL_INTERVAL * 1000); // Sleep for 50ms
    }

    // Clean shutdown
    close(gpio4_fd);
    i2c_free_client(client);
    log_message(LOG_INFO, "Exiting cleanly");

    // Log shutdown event
    syslog(LOG_INFO, "Program exited cleanly");

    closelog();
    return 0;
}

