        read_buf[0] = 0x33;
        ret = ioctl(fd, I2C_RD, read_buf);
        if (ret < 0) {
            perror("Failed to read from MPU6050");
            close(fd);
            return NULL;
        }

        buffer[buffer_index].timestamp = __get_cpu_time();
        buffer[buffer_index].x = (int)read_buf[1];
        buffer[buffer_index].y = (int)read_buf[2];
        buffer[buffer_index].z = (int)read_buf[3];

