#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <errno.h>
#include <libgpiod.h>

#define KY038_PIN 17
#define RELAY_PIN 27
#define POLLING_INTERVAL_MS 100
#define DEBOUNCE_TIME_MS 50
#define RELAY_ON_TIME_S 3

#define LOG_FILE "alarm_log.txt"

int relay_file_fd;

void log_event(const char *timestamp) {
    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        perror("Failed to open log file");
        return;
    }
    fprintf(file, "%s\n", timestamp);
    fclose(file);
}

void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        log_event("Exiting gracefully...");
        gpio_set_dir(RELAY_PIN, GPIO_OUT);
        gpio_write(RELAY_PIN, 0);
        exit(0);
    }
}

int main() {
    int ret;

    // Initialize libgpiod
    ret = gpiod_init();
    if (ret < 0) {
        perror("Failed to initialize libgpiod");
        return ret;
    }

    // Set up GPIO pins
    ret = gpio_request(KY038_PIN, "sound_sensor");
    if (ret < 0) {
        perror("Failed to request KY-038 pin");
        return ret;
    }
    gpio_set_direction(KY038_PIN, GPIO_IN);

    ret = gpio_request(RELAY_PIN, "relay");
    if (ret < 0) {
        perror("Failed to request relay pin");
        return ret;
    }
    gpio_set_direction(RELAY_PIN, GPIO_OUT);
    gpio_write(RELAY_PIN, 0); // Relays off initially

    // Set up signal handlers
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Open log file
    relay_file_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (relay_file_fd < 0) {
        perror("Failed to open log file");
        return -1;
    }

    // Main loop
    while (1) {
        char timestamp[32];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

        // Check for sound event
        int sound_event = gpio_get_level(KY038_PIN);
        if (sound_event == GPIO_INPUT_HIGH) {
            // Activate relay
            gpio_write(RELAY_PIN, 1);
            printf("Sound detected, activating relay...\n");

            // Debounce/cooldown mechanism
            usleep(DEBOUNCE_TIME_MS / 1000); // Convert to seconds
            gpio_write(RELAY_PIN, 0); // Deactivate relay
            usleep(RELAY_ON_TIME_S * 1000 / 1000); // Convert to milliseconds
            gpio_write(RELAY_PIN, 1); // Reactivate relay

            // Log the event
            log_event(timestamp);
        }

        // Polling interval
        usleep(POLLING_INTERVAL_MS / 1000); // Convert to seconds
    }

    // Deinitialize libgpiod
    gpio_free(RELAY_PIN);
    gpio_free(KY038_PIN);
    gpiod_disable();

    // Close log file
    fclose(relay_file_fd);
    close(relay_file_fd);

    return 0;
}

