#include <errno.h>
#include <pthread.h>

#define I2C_BUS 1
#define I2C_ADDR 0x68  // MPU-6050 I2C address
#define BUFFER_SIZE 100

typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} gyro_data_t;

typedef struct {
    gyro_data_t data[BUFFER_SIZE];
    int head;
    int tail;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
    int threshold = 50.0;
} gyro_buffer_t;

void* read_gyro(void* arg) {
    gyro_buffer_t* buffer = (gyro_buffer_t*)arg;
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("open");
        return NULL;
    }

    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        close(fd);
        perror("ioctl");
        return NULL;
    }

    char command[4] = {0x43, 0x00, 0x00, 0x00};  // Read Gyro data
    write(fd, command, 4);

    if (read(fd, buffer->data, sizeof(gyro_data_t)) != sizeof(gyro_data_t)) {
        close(fd);
        perror("read");
        return NULL;
    }

    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    notify_callback();

    close(fd);
    return NULL;
}

void notify_callback(void* arg) {
    gyro_buffer_t* buffer = (gyro_buffer_t*)arg;
    gyro_data_t data = buffer->data[buffer->head];

    double magnitude = sqrt(data.x * data.x + data.y * data.y + data.z * data.z);
    if (magnitude > buffer->threshold) {
        printf("Absolute angular velocity exceeded threshold: %f degrees/s\n", magnitude);
    }
}

int main(int argc, char* argv[]) {
    gyro_buffer_t buffer;
    pthread_t thread;

    if (pthread_mutex_init(&buffer.mutex, NULL) != 0 ||
        pthread_cond_init(&buffer.cond, NULL) != 0) {
        perror("pthread_mutex_init");
        return EXIT_FAILURE;
    }

    if (open("/dev/i2c-1", O_RDWR) < 0) {
        perror("open");
        return EXIT_FAILURE;
    }

    if (ioctl(open("/dev/i2c-1", O_RDWR), I2C_SLAVE, I2C_ADDR) < 0) {
        close(open("/dev/i2c-1", O_RDWR));
        perror("ioctl");
        return EXIT_FAILURE;
    }

    if (pthread_create(&thread, NULL, read_gyro, &buffer) != 0) {
        perror("pthread_create");
        close(open("/dev/i2c-1", O_RDWR));
        return EXIT_FAILURE;
    }

    printf("Gyroscope reading started...\n");

    // Wait for SIGINT (Ctrl+C)
    if (signal(SIGINT) != SIG_IGN) {
        printf("Gyroscope reading stopped by user.\n");
        pthread_join(thread, NULL);
        close(open("/dev/i2c-1", O_RDWR));
        return EXIT_SUCCESS;
    }

    pthread_join(thread, NULL);
    close(open("/dev/i2c-1", O_RDWR));
    pthread_mutex_destroy(&buffer.mutex);
    pthread_cond_destroy(&buffer.cond);

    return EXIT_SUCCESS;
}

