#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <time.h>
#include <libthe/libthe.h>
#include <rt/rt.h>

#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE 9600
#define TXD_PIN 14
#define RXD_PIN 15
#define COMMAND_SEQUENCE "0x01 0x02 0x03 0x04 0x05 0x06 0x07 0x08 0x09"
#define CHECKSUM_OFFSET 8
#define ERROR_LOG "co2_error.log"
#define LOG_FILE "co2_log.json"
#define SAMPLE_INTERVAL 5000

typedef struct {
    time_t timestamp;
    int ppm;
    int error;
} Co2Reading;

int main() {
    int uart_fd, check_fd;
    struct itimerval timer;
    Co2Reading reading;

    uart_fd = open(UART_DEVICE, O_RDWR | O_NOCTTY | O_NDELAY);
    if (uart_fd == -1) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    itinit(&timer, 0, 0);

    while (1) {
        time(&reading.timestamp);
        reading.ppm = 0;
        reading.error = 0;

        // Send command sequence
        write(uart_fd, COMMAND_SEQUENCE, strlen(COMMAND_SEQUENCE));

        // Read response
        char response[9];
        read(uart_fd, response, 9);
        if (response[CHECKSUM_OFFSET] != COMMAND_SEQUENCE[CHECKSUM_OFFSET]) {
            reading.error = 1;
            continue;
        }

        // Calculate checksum
        int checksum = 0;
        for (int i = 0; i < 9; i++) {
            checksum += response[i];
        }
        if (checksum != COMMAND_SEQUENCE[CHECKSUM_OFFSET]) {
            reading.error = 1;
            continue;
        }

        // Parse ppm value
        reading.ppm = response[8] << 4 | response[7];
        reading.ppm |= response[6] << 2 | response[5];
        reading.ppm |= response[4] << 0 | response[3];
        reading.ppm |= response[2] >> 4;
        reading.ppm |= response[1] >> 2;
        reading.ppm |= response[0] >> 0;

        // Write to log file
        check_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
        if (check_fd == -1) {
            perror("open");
            exit(EXIT_FAILURE);
        }
        char json_str[256];
        snprintf(json_str, sizeof(json_str), "{\"timestamp\": %lu, \"ppm\": %d, \"error\": %d}",
                 (long)reading.timestamp, reading.ppm, reading.error);
        write(check_fd, json_str, strlen(json_str));
        close(check_fd);

        // Print to stdout
        printf("%s", json_str);

        // Sleep with timer
        timer.it_value.tv_sec = 0;
        timer.it_value.tv_usec = SAMPLE_INTERVAL * 1000;
        select(check_fd, NULL, NULL, NULL, &timer);
    }

    close(uart_fd);
    close(check_fd);

    return 0;
}

