#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x77
#define BUFFER_SIZE 100
#define SAMPLE_INTERVAL_MS 100
#define TARGET_HEADING 90.0
#define HARD_IRON_OFFSETS {100, -50}

typedef struct {
    int16_t heading;
    int8_t timestamp;
} CompensatedHeading;

CompensatedHeading buffer[BUFFER_SIZE];
int head_index = 0;

void i2c_init() {
    int file = open("/dev/i2c-1", O_RDWR);
    if (file < 0) {
        perror("open /dev/i2c-1");
        exit(EXIT_FAILURE);
    }

    if (ioctl(file, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        exit(EXIT_FAILURE);
    }
}

int i2c_read(int reg, unsigned char *data) {
    return write(fileno(file), &reg, 1) == 1 && read(fileno(file), data, 2) == 2;
}

int i2c_write(int reg, unsigned char data) {
    return write(fileno(file), &reg, 1) == 1 && write(fileno(file), &data, 1) == 1;
}

int compensate_heading(int16_t raw_heading) {
    int16_t compensated_x = raw_heading - HARD_IRON_OFFSETS[0];
    int16_t compensated_y = raw_heading + HARD_IRON_OFFSETS[1];

    int16_t magnitude = (int16_t)sqrt(compensated_x * compensated_x + compensated_y * compensated_y);
    if (magnitude > 0) {
        compensated_x /= magnitude;
        compensated_y /= magnitude;
    }

    return (int16_t)atan2(compensated_y, compensated_x) * 180 / M_PI;
}

void write_to_gpio(int pin) {
    if (piGPIO_open(1) < 0) {
        perror("piGPIO_open");
        exit(EXIT_FAILURE);
    }

    if (piGPIO_write(1, pin) < 0) {
        perror("piGPIO_write");
        exit(EXIT_FAILURE);
    }

    piGPIO_close(1);
}

int main(int argc, char *argv[]) {
    i2c_init();

    while (1) {
        int raw_x, raw_y;
        if (i2c_read(0x68, &raw_x) && i2c_read(0x69, &raw_y)) {
            int compensated_heading = compensate_heading(raw_x);

            if (head_index >= BUFFER_SIZE) {
                head_index = 0;
            }

            buffer[head_index].heading = compensated_heading;
            buffer[head_index].timestamp = usleep(SAMPLE_INTERVAL_MS * 1000 / 1000);
            head_index++;

            if (head_index == BUFFER_SIZE) {
                // Circular buffer full, overwrite oldest entry
                buffer[0].heading = compensated_heading;
                buffer[0].timestamp = usleep(SAMPLE_INTERVAL_MS * 1000 / 1000);
            }

            // Check for heading deviation from target
            if (abs(buffer[head_index - 1].heading - TARGET_HEADING) > 10) {
                write_to_gpio(1);
            }
        }

        usleep(SAMPLE_INTERVAL_MS / 1000);
    }

    return 0;
}

