#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <string.h>
#include <errno.h>
#include <pigpio.h>

#define MOTOR_A_IN1 17
#define MOTOR_A_IN2 18
#define MOTOR_B_IN3 22
#define MOTOR_B_IN4 23

#define PWM_FREQUENCY 1000
#define PWM_DUTY_RANGE 0, 255

void motor_control(int motor_a_pin, int motor_b_pin, int distance) {
    int pwm_duty;

    if (distance < 50) {
        pwm_duty = (int)((255 * (50 - distance)) / 50);
    } else {
        pwm_duty = 0;
    }

    gpioOutput(motor_a_pin, 1);
    gpioOutput(motor_a_pin, 0);
    gpioOutput(motor_b_pin, 1);
    gpioOutput(motor_b_pin, 0);

    gpioPWM(motor_a_pin, motor_a_pin, PWM_FREQUENCY, pwm_duty);
    gpioPWM(motor_b_pin, motor_b_pin, PWM_FREQUENCY, pwm_duty);
}

void signal_handler(int signum) {
    printf("Received signal %d, exiting gracefully...\n", signum);
    gpioOutput(MOTOR_A_IN1, 0);
    gpioOutput(MOTOR_A_IN2, 0);
    gpioOutput(MOTOR_B_IN3, 0);
    gpioOutput(MOTOR_B_IN4, 0);
    pigpio_stop();
    exit(0);
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <distance_motor_a> <distance_motor_b>\n", argv[0]);
        return EXIT_FAILURE;
    }

    int distance_motor_a = atoi(argv[1]);
    int distance_motor_b = atoi(argv[2]);

    if (distance_motor_a < 10 || distance_motor_a > 100 || distance_motor_b < 10 || distance_motor_b > 100) {
        fprintf(stderr, "Distance values must be between 10 and 100 cm.\n");
        return EXIT_FAILURE;
    }

    if (pigpioInit() != 0) {
        fprintf(stderr, "Failed to initialize pigpio library.\n");
        return EXIT_FAILURE;
    }

    gpioSetup(MOTOR_A_IN1, PIGIO_OUTPUT);
    gpioSetup(MOTOR_A_IN2, PIGIO_OUTPUT);
    gpioSetup(MOTOR_B_IN3, PIGIO_OUTPUT);
    gpioSetup(MOTOR_B_IN4, PIGIO_OUTPUT);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        motor_control(MOTOR_A_IN1, MOTOR_B_IN3, distance_motor_a);
        motor_control(MOTOR_A_IN2, MOTOR_B_IN4, distance_motor_b);
        usleep(100000); // 100 ms delay
    }

    pigpioTerminate();
    return EXIT_SUCCESS;
}

