#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/statfs.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <string.h>
#include <errno.h>
#include <libgpiod.h>

#define GPIO_IN1 17
#define GPIO_IN2 18
#define GPIO_IN3 27
#define GPIO_IN4 22
#define LOCK_BUTTON 24
#define UNLOCK_BUTTON 23
#define STEPS_PER_STEP 512
#define INTER_STEP_DELAY 2000

int main(int argc, char *argv[]) {
    int fd;
    void *addr;
    ssize_t size;
    struct statfs statb;

    fd = open("/dev/mem", O_RDWR);
    if (fd < 0) {
        perror("open /dev/mem");
        exit(EXIT_FAILURE);
    }

    addr = mmap(NULL, 4096, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (addr == MAP_FAILED) {
        perror("mmap");
        close(fd);
        exit(EXIT_FAILURE);
    }

    size = statb(addr);
    if (size == -1) {
        perror("statb");
        munmap(addr, size);
        close(fd);
        exit(EXIT_FAILURE);
    }

    // Configure GPIOs as outputs for L293D and inputs for buttons
    if (gpiod_setup_gpio_export(GPIO_IN1, GPIOD_OUTPUT) < 0) {
        perror("gpiod_setup_gpio_export GPIO_IN1");
        munmap(addr, size);
        close(fd);
        exit(EXIT_FAILURE);
    }
    if (gpiod_setup_gpio_export(GPIO_IN2, GPIOD_OUTPUT) < 0) {
        perror("gpiod_setup_gpio_export GPIO_IN2");
        munmap(addr, size);
        close(fd);
        exit(EXIT_FAILURE);
    }
    if (gpiod_setup_gpio_export(GPIO_IN3, GPIOD_OUTPUT) < 0) {
        perror("gpiod_setup_gpio_export GPIO_IN3");
        munmap(addr, size);
        close(fd);
        exit(EXIT_FAILURE);
    }
    if (gpiod_setup_gpio_export(GPIO_IN4, GPIOD_OUTPUT) < 0) {
        perror("gpiod_setup_gpio_export GPIO_IN4");
        munmap(addr, size);
        close(fd);
        exit(EXIT_FAILURE);
    }
    if (gpiod_setup_gpio_export(LOCK_BUTTON, GPIOD_INPUT) < 0) {
        perror("gpiod_setup_gpio_export LOCK_BUTTON");
        munmap(addr, size);
        close(fd);
        exit(EXIT_FAILURE);
    }
    if (gpiod_setup_gpio_export(UNLOCK_BUTTON, GPIOD_INPUT) < 0) {
        perror("gpiod_setup_gpio_export UNLOCK_BUTTON");
        munmap(addr, size);
        close(fd);
        exit(EXIT_FAILURE);
    }

    // Initialize L293D driver
    if (gpiod_try_set_gpio_direction(GPIO_IN1, GPIOD_OUTPUT) < 0) {
        perror("gpiod_try_set_gpio_direction GPIO_IN1");
        munmap(addr, size);
        close(fd);
        exit(EXIT_FAILURE);
    }
    if (gpiod_try_set_gpio_direction(GPIO_IN2, GPIOD_OUTPUT) < 0) {
        perror("gpiod_try_set_gpio_direction GPIO_IN2");
        munmap(addr, size);
        close(fd);
        exit(EXIT_FAILURE);
    }
    if (gpiod_try_set_gpio_direction(GPIO_IN3, GPIOD_OUTPUT) < 0) {
        perror("gpiod_try_set_gpio_direction GPIO_IN3");
        munmap(addr, size);
        close(fd);
        exit(EXIT_FAILURE);
    }
    if (gpiod_try_set_gpio_direction(GPIO_IN4, GPIOD_OUTPUT) < 0) {
        perror("gpiod_try_set_gpio_direction GPIO_IN4");
        munmap(addr, size);
        close(fd);
        exit(EXIT_FAILURE);
    }
    if (gpiod_try_set_gpio_direction(LOCK_BUTTON, GPIOD_INPUT) < 0) {
        perror("gpiod_try_set_gpio_direction LOCK_BUTTON");
        munmap(addr, size);
        close(fd);
        exit(EXIT_FAILURE);
    }
    if (gpiod_try_set_gpio_direction(UNLOCK_BUTTON, GPIOD_INPUT) < 0) {
        perror("gpiod_try_set_gpio_direction UNLOCK_BUTTON");
        munmap(addr, size);
        close(fd);
        exit(EXIT_FAILURE);
    }

    // Initialize L293D driver
    if (gpiod_try_set_gpio_output_initial_value(GPIO_IN1, 0) < 0) {
        perror("gpiod_try_set_gpio_output_initial_value GPIO_IN1");
        munmap(addr, size);
        close(fd);
        exit(EXIT_FAILURE);
    }
    if (gpiod_try_set_gpio_output_initial_value(GPIO_IN2, 0) < 0) {
        perror("gpiod_try_set_gpio_output_initial_value GPIO_IN2");
        munmap(addr, size);
        close(fd);
        exit(EXIT_FAILURE);
    }
    if (gpiod_try_set_gpio_output_initial_value(GPIO_IN3, 0) < 0) {
        perror("gpiod_try_set_gpio_output_initial_value GPIO_IN3");
        munmap(addr, size);
        close(fd);
        exit(EXIT_FAILURE);
    }
    if (gpiod_try_set_gpio_output_initial_value(GPIO_IN4, 0) < 0) {
        perror("gpiod_try_set_gpio_output_initial_value GPIO_IN4");
        munmap(addr, size);
        close(fd);
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (1) {
        int lock_pressed = read(fd, &addr[1]) == -1 || (addr[0] & 0x01);
        int unlock_pressed = read(fd, &addr[1]) == -1 || !(addr[0] & 0x01);

        if (lock_pressed) {
            // Lock
            for (int i = 0; i < STEPS_PER_STEP; i++) {
                gpiod_try_set_gpio_output(GPIO_IN1, 1);
                gpiod_try_set_gpio_output(GPIO_IN2, 0);
                gpiod_try_set_gpio_output(GPIO_IN3, 1);
                gpiod_try_set_gpio_output(GPIO_IN4, 0);
                usleep(INTER_STEP_DELAY * 1000);
                gpiod_try_set_gpio_output(GPIO_IN1, 0);
                gpiod_try_set_gpio_output(GPIO_IN2, 1);
                gpiod_try_set_gpio_output(GPIO_IN3, 0);
                gpiod_try_set_gpio_output(GPIO_IN4, 1);
                usleep(INTER_STEP_DELAY * 1000);
            }
            printf("Door locked.\n");
        } else if (unlock_pressed) {
            // Unlock
            for (int i = 0; i < STEPS_PER_STEP; i++) {
                gpiod_try_set_gpio_output(GPIO_IN1, 0);
                gpiod_try_set_gpio_output(GPIO_IN2, 1);
                gpiod_try_set_gpio_output(GPIO_IN3, 0);
                gpiod_try_set_gpio_output(GPIO_IN4, 1);
                usleep(INTER_STEP_DELAY * 1000);
                gpiod_try_set_gpio_output(GPIO_IN1, 1);
                gpiod_try_set_gpio_output(GPIO_IN2, 0);
                gpiod_try_set_gpio_output(GPIO_IN3, 1);
                gpiod_try_set_gpio_output(GPIO_IN4, 0);
                usleep(INTER_STEP_DELAY * 1000);
            }
            printf("Door unlocked.\n");
        }

        // Prevent re-triggering while a button remains held
        if (!lock_pressed && !unlock_pressed) {
            sleep(0.1);
        }
    }

    // Exit cleanly
    printf("Exiting...\n");
    munmap(addr, size);
    close(fd);
    return 0;
}

