#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <linux/gpio.h>
#include <pigpio.h>
#include <signal.h>

#define RELAY_GPIO_4 4
#define RELAY_GPIO_17 17
#define RELAY_GPIO_27 27
#define RELAY_GPIO_22 22

#define SCHEDULE_FILE "lighting_schedule.txt"
#define PWM_FREQUENCY 100
#define FADE_DURATION_SECONDS 30
#define RELAY_COUNT 4

int gpios[RELAY_COUNT];

void sigint_handler(int sig) {
    for (int i = 0; i < RELAY_COUNT; i++) {
        gpioWrite(gpios[i], 0);
    }
    pigpioStop();
    exit(0);
}

void sigterm_handler(int sig) {
    sigint_handler(sig);
}

void init_gpio() {
    int err = pigpioSetup();
    if (err != 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpioErrorStr());
        exit(EXIT_FAILURE);
    }

    gpios[0] = RELAY_GPIO_4;
    gpios[1] = RELAY_GPIO_17;
    gpios[2] = RELAY_GPIO_27;
    gpios[3] = RELAY_GPIO_22;

    for (int i = 0; i < RELAY_COUNT; i++) {
        gpioSetMode(gpios[i], PI_OUTPUT);
    }
}

void read_schedule() {
    FILE *file = fopen(SCHEDULE_FILE, "r");
    if (!file) {
        fprintf(stderr, "Failed to open schedule file: %s\n", strerror(errno));
        return;
    }

    char line[100];
    while (fgets(line, sizeof(line), file)) {
        char *token = strtok(line, ",");
        if (token == NULL) {
            fprintf(stderr, "Invalid schedule entry: %s\n", line);
            fclose(file);
            return;
        }

        int hour, minute, second, relay_num, state;
        sscanf(token, "%d:%d:%d,%d,%s", &hour, &minute, &second, &relay_num, state);

        if (hour < 0 || hour > 23 || minute < 0 || minute > 59 || second < 0 || second > 59 ||
            relay_num < 1 || relay_num > RELAY_COUNT || state != "on" && state != "off") {
            fprintf(stderr, "Invalid schedule entry: %s\n", line);
            fclose(file);
            return;
        }

        if (state == "on") {
            gpioWrite(relay_num - 1, 1);
        } else {
            gpioWrite(relay_num - 1, 0);
        }
    }

    fclose(file);
}

void fade_light(int relay_num) {
    int duty_cycle = 0;
    int max_duty_cycle = 100;
    int current_duty_cycle = 0;

    for (int i = 0; i <= FADE_DURATION_SECONDS * PWM_FREQUENCY; i++) {
        duty_cycle = (int)(max_duty_cycle * (i / FADE_DURATION_SECONDS * PWM_FREQUENCY));
        current_duty_cycle = duty_cycle;
        gpioPWM(relay_num - 1, duty_cycle);
        usleep(100000); // 100 microseconds per step
    }
}

int main() {
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    init_gpio();

    while (1) {
        read_schedule();
        fade_light(rand() % RELAY_COUNT + 1);
        usleep(1000000); // Sleep for 1 second
    }

    pigpioStop();
    return 0;
}

