#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>
#include <errno.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define BUZZER_PIN 18
#define MIN_GAP_MS 60000
#define FREQ_MIN 100
#define FREQ_MAX 2000
#define FREQ_STEP 10

#define PWM_FREQ_MIN 500
#define PWM_FREQ_MAX 2000
#define PWM_FREQ_STEP 10

#define BUZER_PWM_PERIOD_US 1000000 / PWM_FREQ_MAX

void init_gpio(pigpio_t *pi) {
    if (pigpio_init() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        exit(EXIT_FAILURE);
    }

    if (pigpio_setup(pi, TRIGGER_PIN, PIGIO_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set %s as output\n", gpio_pin_to_string(TRIGGER_PIN));
        exit(EXIT_FAILURE);
    }

    if (pigpio_setup(pi, ECHO_PIN, PIGIO_INPUT) < 0) {
        fprintf(stderr, "Failed to set %s as input\n", gpio_pin_to_string(ECHO_PIN));
        exit(EXIT_FAILURE);
    }

    if (pigpio_setup(pi, BUZZER_PIN, PIGIO_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set %s as output\n", gpio_pin_to_string(BUZZER_PIN));
        exit(EXIT_FAILURE);
    }
}

double read_distance(pigpio_t *pi) {
    uint32_t echo_time;
    pigpio_void_t result;

    pigpio_void_t timeout = pigpio_timeout(1000); // 1 second timeout

    result = pigpio_pulsein(ECHO_PIN, 0, 10, timeout);
    if (result < 0) {
        fprintf(stderr, "Timeout reading echo\n");
        return -1.0;
    }

    echo_time = pigpio_get_pulsein_result(result);
    double distance = (echo_time * 0.000001) / 2; // Convert to meters

    return distance;
}

void set_buzzer_frequency(pigpio_t *pi, double freq) {
    int freq_int = (int)(freq * 1000);
    pigpio_set_pattern(BUZZER_PIN, freq_int, 0);
}

int main(int argc, char *argv[]) {
    pigpio_t *pi;
    double last_distance = -1.0;
    double current_distance;
    double freq;

    pi = pigpio_init();
    if (!pi) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return EXIT_FAILURE;
    }

    init_gpio(pi);

    while (1) {
        current_distance = read_distance(pi);

        if (current_distance == -1.0) {
            fprintf(stderr, "Sensor not detected\n");
            break;
        }

        double time_since_last_measurement = time(NULL) - last_distance;
        if (time_since_last_measurement < MIN_GAP_MS / 1000.0) {
            usleep(BUZER_PWM_PERIOD_US * 1000 / PWM_FREQ_MAX);
            continue;
        }

        freq = (current_distance / 100.0) * PWM_FREQ_MAX;
        freq = fmin(fmax(freq, FREQ_MIN), FREQ_MAX);

        set_buzzer_frequency(pi, freq);
        last_distance = current_distance;

        usleep(BUZER_PWM_PERIOD_US / PWM_FREQ_MAX);
    }

    pigpio_cleanup(pi);
    return 0;
}

