#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <string.h>
#include <errno.h>
#include <pigpio.h>

#define LED_RED 17
#define LED_GREEN 22
#define LED_BLUE 27
#define PWM_FREQUENCY 1000
#define PROXIMITY_MAX 1.0
#define PROXIMITY_MIN 0.0

void sigint_handler(int signum) {
    gpioReset(LED_RED);
    gpioReset(LED_GREEN);
    gpioReset(LED_BLUE);
    pigpioStop();
    printf("Program received SIGINT, exiting gracefully.\n");
    exit(0);
}

int main(int argc, char *argv[]) {
    if (signal(SIGINT, sigint_handler) == SIG_IGN) {
        perror("signal");
        exit(1);
    }

    if (gpioInit() < 0) {
        fprintf(stderr, "Failed to initialize GPIO: %s\n", strerror(errno));
        exit(1);
    }

    gpioSetMode(LED_RED, PI_OUTPUT);
    gpioSetMode(LED_GREEN, PI_OUTPUT);
    gpioSetMode(LED_BLUE, PI_OUTPUT);

    gpioSetPWMfrequency(LED_RED, PWM_FREQUENCY);
    gpioSetPWM(LED_RED, 0, 0);
    gpioSetPWM(LED_GREEN, 0, 0);
    gpioSetPWM(LED_BLUE, 0, 0);

    double proximity = 0.5; // Simulated proximity value
    double t = 0.0;

    while (1) {
        t += 0.01;
        proximity = sin(t * 2 * M_PI); // Simulated proximity wave
        proximity = clamp(proximity, PROXIMITY_MIN, PROXIMITY_MAX);

        int red = int(proximity * 255);
        int green = int((1 - proximity) * 255);
        int blue = 0;

        gpioSetPWM(LED_RED, red, 0);
        gpioSetPWM(LED_GREEN, green, 0);
        gpioSetPWM(LED_BLUE, blue, 0);

        usleep(100000); // Adjust delay as needed
    }

    gpioStop();
    pigpioExit();
    return 0;
}

int gpioInit() {
    int r = pigpioSetup(LED_RED);
    if (r < 0) {
        return r;
    }

    int g = pigpioSetup(LED_GREEN);
    if (g < 0) {
        pigpioExit();
        return g;
    }

    int b = pigpioSetup(LED_BLUE);
    if (b < 0) {
        pigpioExit();
        return b;
    }

    return 0;
}

int gpioSetPWM(int pin, int dutyCycle, int frequency) {
    int result = pigpioPWM(pin, dutyCycle, frequency);
    if (result < 0) {
        fprintf(stderr, "Failed to set PWM: %s\n", strerror(errno));
        return result;
    }
    return 0;
}

int gpioReset(int pin) {
    int result = pigpioSetMode(pin, PI_OUTPUT);
    if (result < 0) {
        fprintf(stderr, "Failed to set pin as output: %s\n", strerror(errno));
        return result;
    }

    result = pigpioPWM(pin, 0, 0);
    if (result < 0) {
        fprintf(stderr, "Failed to set PWM to 0%: %s\n", strerror(errno));
        return result;
    }

    return 0;
}

int clamp(double x, double a, double b) {
    if (x < a) return a;
    if (x > b) return b;
    return x;
}

