#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <pthread.h>

#define I2C_BUS 1
#define I2C_ADDR 0x68  // MPU-6050 device address
#define SDA_PIN 2
#define SCL_PIN 3
#define LOG_FILE "gyro_log.txt"
#define SAMPLE_INTERVAL 100  // milliseconds

typedef struct {
    int fd;
    struct i2c_client *client;
} i2c_context_t;

void* read_gyro_data(void* arg) {
    i2c_context_t* context = (i2c_context_t*)arg;
    unsigned char reg_address[2];
    unsigned char data[6];
    long int value;

    while (1) {
        // Read I2C device address
        if (ioctl(context->fd, I2C_SLAVE, I2C_ADDR) < 0) {
            perror("ioctl: I2C_SLAVE");
            exit(EXIT_FAILURE);
        }

        // Read gyroscope data
        reg_address[0] = 0x3B;  // Register address for gyroscope data
        reg_address[1] = 0x00;  // Read raw data mode

        if (ioctl(context->fd, I2C_MEMREAD, &reg_address[0], 2, data, sizeof(data)) < 0) {
            perror("ioctl: I2C_MEMREAD");
            exit(EXIT_FAILURE);
        }

        value = ((data[1] << 8) | data[0]);

        // Convert raw data to angular velocity (degrees per second)
        // Assuming the MPU-6050 provides 256-LSB / deg/s
        // Note: This conversion is approximate and may need calibration
        context->gyro_data = (float)value / 256.0;

        // Append to log file
        char timestamp[20];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        FILE* file = fopen(LOG_FILE, "a");
        if (!file) {
            perror("fopen");
            exit(EXIT_FAILURE);
        }
        fprintf(file, "%s %f %f %f\n", timestamp, context->gyro_data, context->gyro_data, context->gyro_data);
        fclose(file);

        // Sleep before next sample
        usleep(SAMPLE_INTERVAL * 1000 / 1000);
    }
}

int main(int argc, char* argv[]) {
    int i2c_fd, ret;
    struct i2c_client *client;
    pthread_t thread_id;

    i2c_fd = open("/dev/i2c-1", O_RDWR | O_SYNC);
    if (i2c_fd < 0) {
        perror("open /dev/i2c-1");
        exit(EXIT_FAILURE);
    }

    client = i2c_alloc(i2c_fd);
    if (!client) {
        perror("i2c_alloc");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    ret = ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR);
    if (ret < 0) {
        perror("ioctl: I2C_SLAVE");
        i2c_free(client);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Initialize gyro context
    i2c_context_t context = { .fd = i2c_fd, .client = client };

    // Start reading data in a separate thread
    pthread_create(&thread_id, NULL, read_gyro_data, &context);

    // Wait for SIGINT or SIGTERM
    while (1) {
        usleep(100000);
    }

    // Clean up
    pthread_join(thread_id, NULL);
    i2c_free(client);
    close(i2c_fd);

    return 0;
}

