#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/poll.h>
#include <linux/gpio.h>
#include <pigpio.h>
#include <errno.h>
#include <signal.h>

#define BUTTON_PIN 17
#define BUZZER_PIN 18
#define DEBOUNCE_DELAY 50000
#define MELODY_LENGTH 10
#define BUZZER_FREQUENCY 2940  // A4 note

#define BUZZER_TABLE_SIZE 10
const uint8_t melody[MELODY_LENGTH] = {
    0b00000100, 0b00001000, 0b00010000, 0b00100000,
    0b01000000, 0b01001000, 0b01010000, 0b01100000,
    0b10000000, 0b10001000, 0b10010000, 0b10100000
};

volatile sig_t button_pressed = 0;

void button_isr(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        gpioOutput(BUZZER_PIN, 0);
        pigpio_stop();
        exit(0);
    }

    gpioRead(BUTTON_PIN) & ~(1 << 0) ? button_pressed = 1 : button_pressed = 0;
}

void play_melody(void) {
    uint8_t i;
    for (i = 0; i < MELODY_LENGTH; i++) {
        gpioWrite(BUZZER_PIN, melody[i]);
        usleep(BUZZER_FREQUENCY * 1000000 / BUZZER_TABLE_SIZE);
    }
    gpioWrite(BUZZER_PIN, 0);
}

int main(int argc, char *argv[]) {
    int buzzer_fd, ret;
    struct sigaction sa;

    sigaction(&sa, NULL, NULL);
    sa.sa_handler = button_isr;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    buzzer_fd = pigpioInit();
    if (buzzer_fd < 0) {
        perror("Failed to initialize pigpio");
        return EXIT_FAILURE;
    }

    gpioInit(BUTTON_PIN);
    gpioSetMode(BUTTON_PIN, GPIO_INPUT + GPIO_PULLUP);
    gpioRead(BUTTON_PIN) & ~(1 << 0) ? gpioWrite(BUTTON_PIN, 0) : NULL;

    while (1) {
        if (button_pressed) {
            if (ret = pigpioCall(buzzer_fd, BUZZER_PIN, 0, 0, 0, BUZZER_FREQUENCY, 50)) {
                perror("Failed to play melody");
                break;
            }
            button_pressed = 0;
        }
        usleep(DEBOUNCE_DELAY / 1000);
    }

    pigpioTerminate(buzzer_fd);
    close(buzzer_fd);
    return EXIT_SUCCESS;
}

