#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/epoll.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <poll.h>
#include <libgpiod.h>

#define GPIO_PIN 11
#define POLL_TIMEOUT_MS 1000
#define WINDOW_SIZE 5

typedef struct {
    time_t timestamp;
    int value;
} Event;

static Event events[WINDOW_SIZE];
static int event_count = 0;

static int log_fd = -1;
static int epoll_fd = -1;
static sig_atomic_t exit_flag = 0;

void sigint_handler(int sig) {
    global_data.exit_flag = 1;
}

void sigterm_handler(int sig) {
    global_data.exit_flag = 1;
}

void setup_logging(const char *filename) {
    log_fd = open(filename, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd == -1) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
}

void setup_epoll() {
    epoll_fd = epoll_create1(0);
    if (epoll_fd == -1) {
        fprintf(stderr, "Error creating epoll instance: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
}

void setup_gpio(void) {
    int ret;
    ret = gpiod_create_env_obj(GPIO_PIN);
    if (ret < 0) {
        fprintf(stderr, "Error creating GPIO object: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
    ret = gpiod_output_init(GPIO_PIN, 1);
    if (ret < 0) {
        fprintf(stderr, "Error initializing GPIO output: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
}

void handle_event(int fd, unsigned int event, void *arg) {
    Event e;
    e.timestamp = get_current_time();
    e.value = gpio_get_value(GPIO_PIN);
    if (event & EPOLLIN) {
        if (epoll_ctl(epoll_fd, EPOLLIN, fd, &e)) {
            fprintf(stderr, "Error on epoll: %s\n");
            exit(EXIT_FAILURE);
        }
    }
    if (e.value == 1) {
        event_count++;
        if (event_count >= WINDOW_SIZE) {
            event_count = WINDOW_SIZE;
            if (is_earthquake_alert(events, WINDOW_SIZE)) {
                print_alert();
            }
        }
    }
    if (log_fd != -1) {
        if (write(log_fd, &e, sizeof(Event)) == -1) {
            fprintf(stderr, "Error writing to log file: %s\n");
            exit(EXIT_FAILURE);
        }
        fsync(log_fd);
    }
}

int is_earthquake_alert(Event events[], int count) {
    int count_high = 0;
    for (int i = 0; i < count; i++) {
        if (events[i].value == 1) {
            count_high++;
        }
    }
    return count_high >= 3;
}

void print_alert(void) {
    time_t now = time(NULL);
    char iso_timestamp[40];
    strftime(iso_timestamp, sizeof(iso_timestamp), "%Y-%m-%dT%H:%M:%SZ", localtime(&now));
    printf("EARTHQUAKE ALERT: %s\n", iso_timestamp);
}

int main(int argc, char *argv[]) {
    setup_logging(getenv("LOG_FILE") ? getenv("LOG_FILE") : "vibration_events.log");
    setup_epoll();
    setup_gpio();

    int timeout = POLL_TIMEOUT_MS;
    if (argc > 1) {
        timeout = atoi(argv[1]);
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    while (!exit_flag) {
        struct pollfd fds;
        fds.fd_count = 1;
        fds.data.fd = GPIO_PIN;
        fds.events = EPOLLIN | EPOLLRDBAND | EPOLLRDY;

        int ret = epoll_wait(epoll_fd, &fds, timeout, -1);
        if (ret < 0) {
            fprintf(stderr, "Error in epoll_wait: %s\n");
            exit(EXIT_FAILURE);
        }

        if (fds.data.fd == GPIO_PIN) {
            handle_event(GPIO_PIN, fds.events, &fds);
        }
    }

    close(epoll_fd);
    close(log_fd);

    return 0;
}

