void calibrate_magnetometer(float *x, float *y, float *z) {
    *x -= X_OFFSET;
    *y -= Y_OFFSET;
    *z -= Z_OFFSET;
}

void write_log(float x, float y, float z, float heading) {
    FILE *file = fopen("mag_log.csv", "a");
