#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <json-c/json.h>
#include <pigpio.h>

#define RELAY_GPIO 17
#define TOUCH_GPIO 4
#define DEBOUNCE_DELAY 200000
#define LOG_FILE "relay_log.json"

typedef struct {
    json_object *log;
} relay_logger;

static int log_state_change(const char *state, time_t timestamp) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen");
        return -1;
    }

    json_object *log_entry = json_object_new();
    json_object_set_new(log_entry, "timestamp", json_object_from_timestamp(timestamp));
    json_object_set(log_entry, "relay_state", json_object_from_string(state));
    json_object_to_file(fp, log_entry, 0);
    fclose(fp);
    json_object_put(log_entry);

    return 0;
}

static void setup_gpio(void) {
    if (pigpio_init() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpio_strerror());
        exit(EXIT_FAILURE);
    }

    gpioSetMode(TOUCH_GPIO, PIGO_OUTPUT);
    gpioSetMode(RELAY_GPIO, PIGO_OUTPUT);
    gpioWrite(RELAY_GPIO, 0); // Relays are initially OFF
}

static void setup_debounce(void) {
    struct timespec touch_timeout;
    touch_timeout.tv_sec = 0;
    touch_timeout.tv_nsec = DEBOUNCE_DELAY / 1000000;

    struct timespec last_touch;
    last_touch.tv_sec = 0;
    last_touch.tv_nsec = 0;

    gpioSetPushPullOutput(RELAY_GPIO);
}

static void toggle_relay(void) {
    gpioWrite(RELAY_GPIO, !gpioGet(RELAY_GPIO));
}

static void interrupt_service_routine(const pigpio_event_t *pi) {
    if (pi->evtype == PIGIO_EV_EDGE_UP) {
        if (gpioRead(TOUCH_GPIO) == 0) { // Touch detected
            time_t now = time(NULL);
            char state[10];
            if (gpioRead(RELAY_GPIO) == 0) {
                state[0] = 'O';
            } else {
                state[0] = 'F';
            }
            log_state_change(state, now);
            toggle_relay();
        }
    }
}

int main(void) {
    setup_gpio();
    setup_debounce();

    pigiosync(); // Keep the program responsive

    pigiv(RELAY_GPIO, interrupt_service_routine, NULL);

    char signal_msg[] = "SIGINT received, toggling relay OFF\n";
    signal(SIGINT, (void (*)(int))signal_handler);

    while (1) {
        usleep(100000); // Sleep for 100ms
    }

    gpioDisable(RELAY_GPIO);
    gpioDisable(TOUCH_GPIO);
    pigiosync(); // Ensure all pending events are processed

    log_state_change("OFF", time(NULL)); // Append final OFF state change

    json_object *log_obj = json_object_new();
    json_object_set(log_obj, "relay_log", log_state_change("OFF", time(NULL)));
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp) {
        json_object_to_file(fp, log_obj, 0);
        fclose(fp);
    } else {
        fprintf(stderr, "Failed to open log file for appending\n");
    }
    json_object_put(log_obj);

    pigpio_terminate();
    return 0;
}

