            perror("Failed to clear dirtied state for GPIO pin");
            exit(EXIT_FAILURE);
        }
        ret = gpiod_output_value_try(ctx, RELAY_PINS[i], 1);
        if (ret != 0) {
            perror("Failed to set GPIO pin as output");
            exit(EXIT_FAILURE);
        }
    }
}

void update_moisture_level() {
    moisture_level = rand() % 100;
    if (moisture_level < 30) {
        for (int i = 0; i < sizeof(relay_states) / sizeof(relay_states[0]); i++) {
            if (relay_states[i] == 0) {
                relay_states[i] = 1;
                sleep(RELAY_DELAY_MS / 1000);
                gpiod_output_value(RELAY_PINS[i], 0);
                sleep(RELAY_GAP_MS / 1000);
            }
        }
    }
}

void log_moisture_level(const char *timestamp, int relay_number, int moisture) {
    time_t now = time(NULL);
    struct tm *time_info = localtime(&now);
    char timestamp_str[80];
    sprintf(timestamp_str, "%04d-%02d-%02d %02d:%02d:%02d",
            time_info->tm_year + 1900, time_info->tm_mon + 1, time_info->tm_mday,
            time_info->tm_hour, time_info->tm_min, time_info->tm_sec);

    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        perror("Failed to open log file for appending");
        exit(EXIT_FAILURE);
    }
    fprintf(file, "%s %d %d\n", timestamp_str, relay_number, moisture);
    fclose(file);
}

int main() {
    initialize_gpio();

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    while (1) {
        time_t now = time(NULL);
        if (now - last_update >= 10) {
            update_moisture_level();
            last_update = time(NULL);

            for (int i = 0; i < sizeof(relay_states) / sizeof(relay_states[0]); i++) {
                if (relay_states[i] == 1) {
                    log_moisture_level(
                        (char *)malloc(strlen(LOG_FILE)), RELAY_PINS[i], moisture_level);
                }
            }
        }
        usleep(1000000);
    }

    return 0;
}
