    gpioSetup(VALVE_PIN, PIGIO_OUTPUT);
    gpioWrite(NOZZLE_PIN, 0);
    gpioWrite(VALVE_PIN, 0);
    pigvWrite(0);
    cleanup();
    exit(0);
}

void watering_cycle() {
    int moisture_value = 0;
    int valve_open = 0;
    int nozzle_angle = 0;

    for (int i = 0; i < 5; i++) {
        moisture_value = MOISTURE_CYCLE[i % 5];
        if (moisture_value < WATERING_THRESHOLD) {
            for (int j = 0; j < 3; j++) {
                if (piGpioPulseOut(VALVE_PIN, 1500) == -1) {
