                    pigvWrite(0);
                    cleanup();
                    exit(1);
                }
                if (piGpioPulseOut(NOZZLE_PIN, NOZZLE_ANGLES[nozzle_angle]) == -1) {
                    fprintf(stderr, "Failed to set nozzle angle, aborting cycle.\n");
                    gpioWrite(NOZZLE_PIN, 0);
                    gpioWrite(VALVE_PIN, 0);
                    pigvWrite(0);
                    cleanup();
                    exit(1);
                }
                usleep(NOZZLE_SWEEP_TIME_MS * 1000 / 1000);
                nozzle_angle = (nozzle_angle + 1) % 5;
                usleep(2000000); // 2 seconds delay
            }
            gpioWrite(NOZZLE_PIN, 0);
            gpioWrite(VALVE_PIN, 0);
            pigvWrite(0);
            for (int j = 0; j < 5; j++) {
                if (piGpioPulseOut(NOZZLE_PIN, NOZZLE_ANGLES[j]) == -1) {
                    fprintf(stderr, "Failed to set nozzle angle, aborting cycle.\n");
                    gpioWrite(NOZZLE_PIN, 0);
                    gpioWrite(VALVE_PIN, 0);
                    pigvWrite(0);
                    cleanup();
                    exit(1);
                }
                usleep(2000000); // 2 seconds hold
            }
            gpioWrite(NOZZLE_PIN, 0);
            gpioWrite(VALVE_PIN, 0);
            pigvWrite(0);
            usleep(5000000); // 5 seconds hold
            gpioWrite(NOZZLE_PIN, 0);
            gpioWrite(VALVE_PIN, 0);
            pigvWrite(0);
            usleep(CLOSE_TIME_MS * 1000 / 1000);
            gpioWrite(NOZZLE_PIN, 0);
            gpioWrite(VALVE_PIN, 0);
            pigvWrite(0);
        }
    }
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (piGpioInit() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library.\n");
        return 1;
    }

    while (1) {
        watering_cycle();
        usleep(1000000); // 1 second delay
    }

    pigGpioShutdown();
    cleanup();
    return 0;
}

