#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <libgpiod.h>

#define I2C_BUS 1
#define SDA_PIN 2
#define SCL_PIN 3
#define MPU6050_ADDRESS 0x68
#define SAMPLE_RATE 10
#define LOG_FILE "gyro_log.txt"

#define BUFFER_SIZE 10
char buffer[BUFFER_SIZE];

void handle_interrupt(int sig) {
    close(stdout);
    close(stderr);
    close(logfd);
    exit(0);
}

void handle_term(int sig) {
    close(stdout);
    close(stderr);
    close(logfd);
    exit(0);
}

int main() {
    int logfd;
    struct i2c_client *client;
    int result;

    logfd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (logfd == -1) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    client = i2c_open(I2C_BUS, 0x20);
    if (client == NULL) {
        perror("i2c_open");
        exit(EXIT_FAILURE);
    }

    result = ioctl(client, I2C_SLAVE, MPU6050_ADDRESS);
    if (result < 0) {
        perror("ioctl");
        i2c_close(client);
        close(logfd);
        exit(EXIT_FAILURE);
    }

    while (1) {
        char timestamp[20];
        sprintf(timestamp, "%0.0f", (double)time(NULL) / 1000.0);
        sprintf(buffer, "%s,%.3f,%.3f,%.3f\n", timestamp, get_mpu6050_gyro(client), get_mpu6050_gyro(client), get_mpu6050_gyro(client));
        result = write(logfd, buffer, strlen(buffer));
        if (result < 0) {
            perror("write");
            break;
        }
        usleep(1000000 / SAMPLE_RATE);
    }

    i2c_close(client);
    close(logfd);
    return 0;
}

float get_mpu6050_gyro(int client) {
    struct mpu6050_reg_w_data data;
    data.reg = 0x3B;
    result = i2c_read_byte(client, MPU6050_ADDRESS, &data);
    if (result < 0) {
        perror("i2c_read_byte");
        return 0.0;
    }

    data.reg = 0x38;
    result = i2c_read_byte(client, MPU6050_ADDRESS, &data);
    if (result < 0) {
        perror("i2c_read_byte");
        return 0.0;
    }

    float gyro_x = (data.data & 0x0000007C) * 2.0 / 16384.0;
    float gyro_y = (data.data & 0x00003E00) * 2.0 / 65536.0;
    float gyro_z = (data.data & 0x00007C00) * 2.0 / 65536.0;

    return gyro_x;
}

int install_signal_handlers() {
    signal(SIGINT, handle_interrupt);
    signal(SIGTERM, handle_term);
    return 0;
}

int main_with_handlers() {
    int ret = install_signal_handlers();
    if (ret != 0) {
        perror("signal handlers installation failed");
        return EXIT_FAILURE;
    }

    return main();
}

