#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/statfs.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <string.h>
#include <errno.h>
#include <pigpio.h>

#define GPIO4 24
#define GPIO17 17
#define GPIO27 27
#define GPIO22 22
#define LOCK_BUTTON 23

#define STEPS_PER_ROTATION 512
#define INTER_STEP_DELAY 3000

int main() {
    int gpio_fd;
    int l293d_in1, l293d_in2, l293d_in3, l293d_in4;
    int l293d_enable;
    int button_state;

    gpio_fd = open("/dev/gpiomem", O_RDWR);
    if (gpio_fd == -1) {
        perror("Failed to open /dev/gpiomem");
        exit(EXIT_FAILURE);
    }

    gpio_set_mode(gpio_fd, GPIO_OUTPUT);
    gpio_write(gpio_fd, 0b00000000); // Initialize all GPIO pins as outputs

    l293d_in1 = gpio_read(gpio_fd + 4);
    l293d_in2 = gpio_read(gpio_fd + 17);
    l293d_in3 = gpio_read(gpio_fd + 27);
    l293d_in4 = gpio_read(gpio_fd + 22);
    l293d_enable = gpio_read(gpio_fd + 24);

    if (l293d_enable) {
        gpio_write(gpio_fd + 24, 0); // De-energize all coils
    }

    while (1) {
        button_state = gpio_read(gpio_fd + LOCK_BUTTON);

        if (button_state == 0) { // Lock button pressed
            for (int i = 0; i < STEPS_PER_ROTATION; i++) {
                l293d_in1 = 1;
                l293d_in2 = 0;
                l293d_in3 = 0;
                l293d_in4 = 0;
                gpio_write(gpio_fd + 24, 1); // Energize coils

                usleep(INTER_STEP_DELAY * 1000); // 3ms delay

                l293d_in1 = 0;
                l293d_in2 = 1;
                l293d_in3 = 0;
                l293d_in4 = 0;
                gpio_write(gpio_fd + 24, 0); // De-energize coils

                usleep(INTER_STEP_DELAY * 1000);
            }
            printf("Door LOCKED\n");
        } else if (button_state == 1) { // Unlock button pressed
            for (int i = 0; i < STEPS_PER_ROTATION; i++) {
                l293d_in1 = 0;
                l293d_in2 = 1;
                l293d_in3 = 0;
                l293d_in4 = 0;
                gpio_write(gpio_fd + 24, 1); // Energize coils

                usleep(INTER_STEP_DELAY * 1000); // 3ms delay

                l293d_in1 = 1;
                l293d_in2 = 0;
                l293d_in3 = 0;
                l293d_in4 = 0;
                gpio_write(gpio_fd + 24, 0); // De-energize coils

                usleep(INTER_STEP_DELAY * 1000);
            }
            printf("Door UNLOCKED\n");
        }

        if (button_state == 2) { // Debouncing
            gpio_write(gpio_fd + LOCK_BUTTON, 1);
            usleep(100);
            gpio_write(gpio_fd + LOCK_BUTTON, 0);
        }
    }

    close(gpio_fd);
    return 0;
}

