#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29  // VL53L1X default address
#define RELAY_PIN 18
#define POLL_INTERVAL 100  // milliseconds
#define MIN_DISTANCE 50

int i2c_fd;
int relay_pin;

void init_i2c() {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C address");
        exit(EXIT_FAILURE);
    }
}

void init_gpio() {
    relay_pin = GPIO_SET_MODE(RELAY_PIN, GPIO_OUTPUT);
    if (relay_pin < 0) {
        perror("Failed to set GPIO pin mode");
        exit(EXIT_FAILURE);
    }
}

void set_relay(int state) {
    GPIOset(relay_pin, state);
}

int read_distance(void) {
    struct i2c_rdwr_cmd cmd = {
        .addr = I2C_ADDR,
        .flags = I2C_M_READ,
        .len = 2,
        .data = {0x01, 0x00}  // VL53L1X command for distance measurement
    };

    int ret = ioctl(i2c_fd, I2C_RDWR, &cmd);
    if (ret < 0) {
        perror("Failed to read from VL53L1X");
        return -1;
    }

    uint8_t data[2];
    ret = read(i2c_fd, data, 2);
    if (ret < 0) {
        perror("Failed to read from I2C bus");
        return -1;
    }

    // Assuming the first byte is the status and the second byte is the distance in mm
    if (data[0] == 0x01 && data[1] < 256) {
        return data[1];
    }

    return -1;
}

int main(int argc, char *argv[]) {
    init_i2c();
    init_gpio();

    while (1) {
        int distance = read_distance();
        if (distance == -1) {
            fprintf(stderr, "Error reading from VL53L1X\n");
            continue;
        }

        if (distance <= MIN_DISTANCE) {
            set_relay(1);
        } else {
            set_relay(0);
        }

        usleep(POLL_INTERVAL * 1000 / 1000);
    }

    fprintf(stderr, "Program terminated by SIGINT\n");
    set_relay(0);  // Ensure relay is off on clean exit
    close(i2c_fd);
    pigpio_terminate(1000);  // Terminate pigpio library
    exit(0);
}

