#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define RELAY_PINS {17, 18, 27, 22}
#define POLL_INTERVAL_SECONDS 60
#define CYCLE_INTERVAL_SECONDS 86400

void log_start_time(const char *log_file) {
    time_t now = time(NULL);
    struct tm *local_time = localtime(&now);
    char time_str[80];
    sprintf(time_str, "%04d-%02d-%02d %02d:%02d:%02d",
            local_time->tm_year + 1900, local_time->tm_mon + 1,
            local_time->tm_mday, local_time->tm_hour, local_time->tm_min,
            local_time->tm_sec);
    FILE *log_file_ptr = fopen(log_file, "a");
    if (log_file_ptr) {
        fprintf(log_file_ptr, "%s", time_str);
        fclose(log_file_ptr);
    }
}

void release_resources(void) {
    for (int i = 0; i < sizeof(RELAY_PINS) / sizeof(int); i++) {
        gpiod_pin_t pin = RELAY_PINS[i];
        gpiod_pin_free(&pin);
    }
    exit(0);
}

void signal_handler(int signum) {
    release_resources();
    printf("Exiting...\n");
    exit(signum);
}

int main(int argc, char *argv[]) {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_start_time("watering_log.txt");

    gpiod_context ctx;
    gpiod_init(&ctx);

    gpiod_pin_t *pins = gpiod_pin_new_array(&ctx, sizeof(RELAY_PINS) / sizeof(int), RELAY_PINS);
    if (!pins) {
        perror("Failed to allocate GPIO pins");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < sizeof(RELAY_PINS) / sizeof(int); i++) {
        if (gpiod_pin_direction_get(&ctx, pins[i]) != GPIOD_DIR_OUT) {
            perror("Failed to set GPIO pin direction to output");
            gpiod_pin_free(pins[i]);
            return EXIT_FAILURE;
        }
    }

    while (1) {
        for (int i = 0; i < sizeof(RELAY_PINS) / sizeof(int); i++) {
            gpiod_pin_write(&ctx, pins[i], 0); // Set pin HIGH
            usleep(5000000); // Wait for 5 seconds
            gpiod_pin_write(&ctx, pins[i], 1); // Set pin LOW
        }
        usleep(CYCLE_INTERVAL_SECONDS * 1000000); // Wait for 86400 seconds (24 hours)
        log_start_time("watering_log.txt");
    }

    release_resources();
    return EXIT_SUCCESS;
}

