#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/poll.h>
#include <sys/epoll.h>
#include <sys/wait.h>
#include <errno.h>
#include <pigpio.h>

#define RELAY_PINS {17, 18, 27, 22} // GPIO pins for SRD-05VDC relays
#define PWM_FREQUENCY 1000 // 1 kHz PWM frequency
#define STEPS 30 // Number of steps for the sunrise effect
#define STEP_INTERVAL 1 // Second interval between steps

#define LOG_FILE "smart_lighting.log"

void log_event(const char *message) {
    time_t now = time(NULL);
    char time_str[80];
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", localtime(&now));
    fprintf(fopen(LOG_FILE, "a"), "[%s] %s\n", time_str, message);
}

void signal_handler(int signum) {
    log_event("Received signal, shutting down...");
    pioClose();
    exit(0);
}

int main(int argc, char *argv[]) {
    pioInit();

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the log file
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        pioClose();
        exit(EXIT_FAILURE);
    }

    // Initialize GPIO pins
    for (int i = 0; i < sizeof(RELAY_PINS) / sizeof(int); i++) {
        if (pioSetupPin(RELAY_PINS[i], PIO_OUTPUT) < 0) {
            fprintf(log_file, "Failed to set up GPIO pin %d\n", RELAY_PINS[i]);
            pioClose();
            fclose(log_file);
            exit(EXIT_FAILURE);
        }
    }

    // Initialize PWM
    if (pioSetupOutput(0, PWM_FREQUENCY, 0, 255) < 0) {
        fprintf(log_file, "Failed to initialize PWM\n");
        pioClose();
        fclose(log_file);
        exit(EXIT_FAILURE);
    }

    // Start the sunrise effect
    for (int step = 0; step < STEPS; step++) {
        log_event("Step %d of %d: Starting step", step + 1, STEPS);
        for (int i = 0; i < sizeof(RELAY_PINS) / sizeof(int); i++) {
            pioSetPWM(0, RELAY_PINS[i], step * 10); // Adjust step value as needed
            usleep(1000000); // Delay for 1 second
        }
        log_event("Step %d of %d: Completed\n", step + 1, STEPS);
    }

    // Clean up
    pioClose();
    fclose(log_file);

    return 0;
}

