#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/sysfile.h>
#include <sys/mman.h>
#include <errno.h>
#include <pthread.h>
#include <signal.h>

#define I2C_BUS 1
#define SDA_PIN 2
#define SCL_PIN 3
#define LED_GPIO 17
#define BUFFER_SIZE 100
#define SAMPLE_RATE 20
#define SAMPLE_PERIOD 50

typedef struct {
    long file_descriptor;
    struct i2c_client *client;
    int error_count;
} I2C_Context;

I2C_Context i2c_context;

void i2c_init(I2C_Context *ctx) {
    int file;
    char buf[32];

    file = open("/dev/i2c-1", O_RDWR);
    if (file < 0) {
        perror("open /dev/i2c-1");
        exit(EXIT_FAILURE);
    }

    ioctl(file, I2C_SLAVE, (u_int8_t)0x68); // MPU-6050 address

    if (ioctl(file, I2C_REQUEST, 1) < 0) {
        perror("ioctl I2C_REQUEST");
        exit(EXIT_FAILURE);
    }

    if (ioctl(file, I2C_SMBUS_READ, &ctx->client) < 0) {
        perror("ioctl I2C_SMBUS_READ");
        exit(EXIT_FAILURE);
    }

    close(file);
}

