#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <libgpiod.h>
#include <spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_BAUDRATE 1000000
#define SPI_MODE 0
#define SPI_BITS 8
#define SPI_CS_GPIO 8
#define SPI_CS_GPIO_OFFSET 8
#define LOG_FILE "gyro_log.txt"
#define LOG_INTERVAL 10000000  // 10 ms in nanoseconds
#define MAX_RETRIES 3

void spi_init(int file) {
    struct spidev_dev *dev;
    int ret;

    ret = spidev_open(file, 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to open SPI device: %s\n", spidev_strerror(ret));
        exit(EXIT_FAILURE);
    }

    dev = spidev_get_device(ret);
    if (!dev) {
        fprintf(stderr, "Failed to get device from SPI file: %s\n", spidev_strerror(spidev_last_err(dev)));
        exit(EXIT_FAILURE);
    }

    ret = spidev_setup(dev, SPI_MODE, 8, 0, SPI_CS_GPIO, SPI_CS_GPIO_OFFSET);
    if (ret < 0) {
        fprintf(stderr, "Failed to configure SPI device: %s\n", spidev_strerror(ret));
        exit(EXIT_FAILURE);
    }
}

void spi_close(int file, struct spidev_dev *dev) {
    spidev_put_device(dev);
    spidev_close(file);
}

void gpio_init(int line) {
    int ret;

    ret = gpiod_channel_new(line, GPIOD_OUTPUT);
    if (ret < 0) {
        fprintf(stderr, "Failed to initialize GPIO line: %s\n", gpiod_strerror(ret));
        exit(EXIT_FAILURE);
    }
}

void gpio_close(int line) {
    gpiod_channel_free(line);
}

void log_error(const char *msg) {
    fprintf(stderr, "ERROR: %s\n", msg);
}

void handle_signal(int signum) {
    fprintf(stderr, "Received signal %d, cleaning up and exiting...\n", signum);
    spi_close(SPI_DEVICE, NULL);
    gpio_close(SPI_CS_GPIO);
    close(LOG_FILE);
    exit(EXIT_SUCCESS);
}

void read_mpu9250(int *x_rate, int *y_rate, int *z_rate) {
    unsigned char buffer[6];
    int retries = MAX_RETRIES;
    int ret;

    while (retries > 0) {
        ret = spidev_xfer(dev, buffer, 1, SPI_CS_GPIO);
        if (ret < 0) {
            retries--;
            if (ret == EIO || ret == ENOTTY) {
                log_error("SPI communication error, retrying...");
                continue;
            } else {
                log_error("Persistent SPI failure, logging error and exiting.");
                return;
            }
        }

        if (ret == 1) {
            // Read data from MPU-9250
            *x_rate = buffer[0];
            *y_rate = buffer[1];
            *z_rate = buffer[2];
            break;
        }
    }
}

int main(int argc, char *argv[]) {
    int dev;
    spi_init(SPI_DEVICE);
    gpio_init(SPI_CS_GPIO);

    while (1) {
        unsigned long now = millis();
        char timestamp[32];
        sprintf(timestamp, "%0.9f", (double)now / 1e9);
        sprintf(timestamp + 32, "%09d", (int)(now % 1e9));

        FILE *file = fopen(LOG_FILE, "a");
        if (!file) {
            log_error("Failed to open log file for writing.");
            continue;
        }

        fprintf(file, "%s,%d,%d,%d\n", timestamp, *x_rate, *y_rate, *z_rate);
        fclose(file);

        usleep(LOG_INTERVAL * 1e6);
    }

    spi_close(SPI_DEVICE, dev);
    gpio_close(SPI_CS_GPIO);
    close(LOG_FILE);

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    return 0;
}

