#include <errno.h>
#include <signal.h>

#define BUFFER_SIZE 64
#define SPI_BUS 0
#define SPI_DEVICE 0
#define GPIO_LED 17
#define SPI_SPEED 39000000
#define SPI_MODE 0
#define GPIO_CE0 8

#define LED_ON 1
#define LED_OFF 0

typedef struct {
    unsigned int timestamp;
    float x, y, z;
} gyro_data_t;

typedef struct {
    gyro_data_t buffer[BUFFER_SIZE];
    int head;
    int tail;
} gyro_buffer_t;

gyro_buffer_t buffer;

void spi_init() {
    int file = open("/dev/spidev0.0", O_RDWR);
    if (file == -1) {
        perror("open /dev/spidev0.0");
        exit(EXIT_FAILURE);
    }

    if (ioctl(file, SPI_SET_MODE, SPI_MODE) == -1) {
        perror("ioctl SPI_SET_MODE");
        close(file);
        exit(EXIT_FAILURE);
    }

    if (ioctl(file, SPI_SET_BRIGHTING, 0) == -1) {
        perror("ioctl SPI_SET_BRIGHTING");
        close(file);
        exit(EXIT_FAILURE);
    }

    if (ioctl(file, SPI_SET_CLOCKS(SPI_CLOCK_39MHZ)) == -1) {
        perror("ioctl SPI_SET_CLOCKS");
        close(file);
        exit(EXIT_FAILURE);
    }

    if (ioctl(file, SPI_SELECT(GPIO_CE0)) == -1) {
        perror("ioctl SPI_SELECT");
        close(file);
        exit(EXIT_FAILURE);
    }
}

int spi_read(unsigned int *data) {
    if (ioctl(open("/dev/spidev0.0", O_RDWR), SPI_READ_REG, data) == -1) {
        perror("ioctl SPI_READ_REG");
        return -1;
    }
    return 0;
}

void spi_deinit() {
    close(open("/dev/spidev0.0", O_WRONLY).fildes);
}

void led_blink(int duration) {
    write(GPIO_LED, LED_ON);
    usleep(duration * 100000);
    write(GPIO_LED, LED_OFF);
    usleep(duration * 100000);
}

void signal_handler(int signum) {
    spi_deinit();
    printf("Exiting...\n");
    exit(signum == SIGINT ? 0 : EXIT_FAILURE);
}

int main(int argc, char *argv[]) {
    signal(SIGINT, signal_handler);

    spi_init();

    while (1) {
        unsigned int data[6];
        if (spi_read(data) == 0) {
            // InvenSense MPU-6050 register map:
            // 0x3B: X-axis raw data (16-bit)
            // 0x3C: Y-axis raw data (16-bit)
            // 0x3D: Z-axis raw data (16-bit)
            // 0x3E: X-axis bias (16-bit)
            // 0x3F: Y-axis bias (16-bit)
            // 0x40: Z-axis bias (16-bit)
            // 0x41: X-axis temperature (16-bit)
            // 0x42: Y-axis temperature (16-bit)
            // 0x43: Z-axis temperature (16-bit)

            // Check for valid data (non-zero)
            if (data[0] == 0 && data[1] == 0 && data[2] == 0 && data[3] == 0 && data[4] == 0 && data[5] == 0) {
                continue;
            }

            // Process the data
            int timestamp = micros();
            buffer.timestamp = timestamp;
            buffer.x = (float)data[2] / 16384.0;
            buffer.y = (float)data[3] / 16384.0;
            buffer.z = (float)data[4] / 16384.0;

            // Check for axis exceeding ±200 deg/s
            if (abs(buffer.x) > 200.0 || abs(buffer.y) > 200.0 || abs(buffer.z) > 200.0) {
                led_blink(500);
            }
        }
    }

    spi_deinit();

    // Print the circular buffer as CSV
    for (int i = 0; i < BUFFER_SIZE; i++) {
        if (buffer.head <= i || i == buffer.tail) {
            continue;
        }
        printf("%d,%f,%f,%f\n", buffer.buffer[i].timestamp, buffer.buffer[i].x, buffer.buffer[i].y, buffer.buffer[i].z);
    }

    return 0;
}

