#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <errno.h>
#include <signal.h>
#include <pthread.h>

#define I2C_BUS 1
#define SI1145_ADDRESS 0x1A
#define LED_PIN 17
#define LOG_FILE "biometric_log.txt"
#define RETRY_ATTEMPTS 3
#define RETRY_DELAY 10

#define AMBIENT_LIGHT_REG 0x00
#define PROXIMITY_REG 0x01

#define LOG_FORMAT "YYYY-MM-DD HH:MM:SS,AmbientLight:XXXX,Proximity:XXXX"

// Function prototypes
void i2c_read(int file, unsigned short reg, bool *ambient_light, int *proximity);
void log_data(const char *data);
void handle_signal(int signum);
void* read_sensor(void* arg);

int main(int argc, char* argv[]) {
    int i2c_fd, log_fd;
    struct i2c_client i2c_client;
    pthread_t thread_id;
    sigset_t sigset, old_sigset;

    // Initialize signal handlers
    sigset_t sigset;
    pthread_sigset_t sigset_t;
    pthread_sigmask(SIG_SETMASK, &sigset, &old_sigset);
    sigaddset(&sigset, SIGINT);
    sigaddset(&sigset, SIGTERM);
    pthread_sigmask(SIG_SETMASK, &sigset, NULL);

    // Open I2C bus and log file
    i2c_fd = open(LOG_FILE, O_WRONLY | O_CREAT, 0644);
    if (i2c_fd == -1) {
        perror("Error opening log file");
        exit(EXIT_FAILURE);
    }

    // Initialize i2c_client
    memset(&i2c_client, 0, sizeof(i2c_client));
    i2c_client.device = I2C_BUS;

    // Initialize LED
    if (open("/dev/gpio17", O_WRLCK | O_CREAT, 0644) == -1) {
        perror("Error opening GPIO17");
        exit(EXIT_FAILURE);
    }

    // Start reading sensor data
    if (pthread_create(&thread_id, NULL, read_sensor, NULL) != 0) {
        perror("Error creating thread");
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (1) {
        // Read sensor data with retries
        int ambient_light = 0, proximity = 0;
        int ret = 0;
        for (int attempt = 0; attempt < RETRY_ATTEMPTS; attempt++) {
            ret = i2c_read(i2c_fd, SI1145_ADDRESS, &ambient_light, &proximity);
            if (ret == 0) {
                break;
            }
            usleep(RETRY_DELAY * 1000);
        }

        if (ret != 0) {
            fprintf(stderr, "Failed to read sensor data after %d attempts.\n", RETRY_ATTEMPTS);
            continue;
        }

        // Log data
        char log_line[512];
        snprintf(log_line, sizeof(log_line), LOG_FORMAT,
                 (int)(ambient_light >> 8), (int)(ambient_light & 0xFF),
                 (int)(proximity >> 8), (int)(proximity & 0xFF));
        write(i2c_fd, log_line, strlen(log_line));

        // Check proximity and control LED
        if (proximity > 100) {
            // Turn on LED
            if (write(LED_PIN, 1) == -1) {
                perror("Error setting GPIO17");
            }
        } else {
            // Turn off LED
            if (write(LED_PIN, 0) == -1) {
                perror("Error setting GPIO17");
            }
        }

        // Sleep for 100ms
        usleep(100 * 1000);
    }

    // Close resources on exit
    close(i2c_fd);
    close(log_fd);
    pthread_join(thread_id, NULL);
    close(LED_PIN);

    // Signal handlers
    handle_signal(SIGINT);
    handle_signal(SIGTERM);

    return 0;
}

void i2c_read(int file, unsigned short reg, bool *ambient_light, int *proximity) {
    struct i2c_msg msg;
    msg.addr = I2C_BUS;
    msg.len = 2;
    msg.data = {reg, 0};

    int ret = ioctl(file, I2C_SLAVE, msg.addr);
    if (ret < 0) {
        perror("I2C read error");
        return;
    }

    ret = ioctl(file, I2C_MEMREAD, &msg);
    if (ret < 0) {
        perror("I2C read error");
        return;
    }

    *ambient_light = (bool)(msg.data[0] & (1 << 7));
    *proximity = msg.data[1];
}

void log_data(const char *data) {
    write(fileno(i2c_fd), data, strlen(data));
}

void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        // Close I2C file descriptor
        close(i2c_fd);

        // Close log file
        close(fileno(i2c_fd));

        // Turn off LED
        if (write(LED_PIN, 0) == -1) {
            perror("Error setting GPIO17");
        }

        // Exit
        exit(0);
    }
}

void* read_sensor(void* arg) {
    while (1) {
        // Read sensor data with retries
        int ambient_light = 0, proximity = 0;
        int ret = 0;
        for (int attempt = 0; attempt < RETRY_ATTEMPTS; attempt++) {
            ret = i2c_read(i2c_fd, SI1145_ADDRESS, &ambient_light, &proximity);
            if (ret == 0) {
                break;
            }
            usleep(RETRY_DELAY * 1000);
        }

        if (ret != 0) {
            fprintf(stderr, "Failed to read sensor data after %d attempts.\n", RETRY_ATTEMPTS);
            continue;
        }

        // Log data
        char log_line[512];
        snprintf(log_line, sizeof(log_line), LOG_FORMAT,
                 (int)(ambient_light >> 8), (int)(ambient_light & 0xFF),
                 (int)(proximity >> 8), (int)(proximity & 0xFF));
        log_data(log_line);

        // Sleep for 100ms
        usleep(100 * 1000);
    }

    return NULL;
}

