#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <sys/stat.h>
#include <sys/types.h>

#define SPI_CHANNEL 0
#define GPIO_PIN 8
#define SPI_SPEED 100000000
#define CPOL 0
#define CPHA 0
#define SAMPLE_RATE 100
#define DELAY_MS 10000
#define LOG_FILE "gyro_data.csv"

#define REG_X_RATE 0x20
#define REG_Y_RATE 0x24

#define BUFFER_SIZE 2

void spi_init(int fd) {
    struct spi_fd *spi;
    int ret;

    spi = (struct spi_fd *)fd;
    ret = ioctl(spi->fd, SPI_SET_MODE, &spi->mode);
    if (ret < 0) {
        perror("ioctl(SPI_SET_MODE)");
        exit(EXIT_FAILURE);
    }

    ret = ioctl(spi->fd, SPI_SET_BRIGHTING, 0);
    if (ret < 0) {
        perror("ioctl(SPI_SET_BRIGHTING)");
        exit(EXIT_FAILURE);
    }

    ret = ioctl(spi->fd, SPI_SET_CASCADED, 1);
    if (ret < 0) {
        perror("ioctl(SPI_SET_CASCADED)");
        exit(EXIT_FAILURE);
    }
}

int spi_read_registers(int fd, uint16_t reg_addr, uint8_t dummy) {
    uint8_t buffer[BUFFER_SIZE];
    int ret;

    ret = write(fd, &reg_addr | dummy, 2);
    if (ret < 0) {
        perror("write(SPI_READ_REGISTER)");
        return -1;
    }

    ret = read(fd, buffer + 1, BUFFER_SIZE - 1);
    if (ret < 0) {
        perror("read(SPI_READ_REGISTER)");
        return -1;
    }

    buffer[1] = 0; // Null-terminate the buffer
    return ret;
}

void spi_error_handling(int fd) {
    int retries = 3;
    while (retries > 0) {
        int ret = spi_read_registers(fd, REG_X_RATE, 0xFF);
        if (ret == 0) {
            ret = spi_read_registers(fd, REG_Y_RATE, 0xFF);
            if (ret == 0) {
                return;
            } else {
                printf("Error reading X-axis rate\n");
            }
        } else {
            printf("SPI read failed, retrying...\n");
            retries--;
        }
    }
    fprintf(stderr, "Failed to read gyroscope data after %d retries\n", retries);
    exit(EXIT_FAILURE);
}

void signal_handler(int signum) {
    spi_error_handling(spi_fd);
    close(spi_fd);
    close(log_fd);
    fclose(log_file);
    exit(signum == SIGINT ? 0 : EXIT_FAILURE);
}

int main() {
    sigset_t sigset;
    int sigmask;
    int spi_fd, log_fd;
    struct stat sb;

    signal(SIGINT, signal_handler);
    sigset_t copy;
    memset(&copy, 0, sizeof(copy));
    sigaddset(&copy, SIGINT);
    sigprocmask(SIG_BLOCK, &copy, NULL);

    spi_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (spi_fd == -1) {
        perror("open(gyro_data.csv)");
        exit(EXIT_FAILURE);
    }

    log_fd = open("/dev/spidev0.0", O_RDWR | O_NOCTTY | O_NDELAY);
    if (log_fd == -1) {
        perror("open(/dev/spidev0.0)");
        exit(EXIT_FAILURE);
    }

    struct spi_fd *spi = (struct spi_fd *)log_fd;
    spi_init(log_fd);

    while (1) {
        uint16_t x_rate, y_rate;
        int ret;

        ret = spi_read_registers(log_fd, REG_X_RATE, 0xFF);
        if (ret == 0) {
            ret = spi_read_registers(log_fd, REG_Y_RATE, 0xFF);
            if (ret == 0) {
                struct timespec ts;
                clock_gettime(CLOCK_REALTIME, &ts);
                char timestamp[32];
                sprintf(timestamp, "%lu.%09lu", ts.tv_sec, ts.tv_nsec / 1000000);

                ret = write(log_fd, timestamp, strlen(timestamp));
                if (ret < 0) {
                    perror("write(timestamp)");
                    exit(EXIT_FAILURE);
                }

                ret = write(log_fd, &x_rate, 2);
                if (ret < 0) {
                    perror("write(X-axis rate)");
                    exit(EXIT_FAILURE);
                }

                ret = write(log_fd, &y_rate, 2);
                if (ret < 0) {
                    perror("write(Y-axis rate)");
                    exit(EXIT_FAILURE);
                }

                usleep(DELAY_MS * 1000 / SAMPLE_RATE);
            } else {
                fprintf(stderr, "Error reading Y-axis rate\n");
            }
        } else {
            fprintf(stderr, "Error reading X-axis rate\n");
        }
    }

    return 0;
}

