#include <libgpiod.h>

#define SENSOR1_GPIO 23
#define SENSOR2_GPIO 24
#define ALERT_GPIO 17
#define LOG_FILE "seismic_events.txt"

void signal_handler(int signum) {
    printf("Received signal %d, performing cleanup...\n", signum);
    close(ALERT_GPIO);
    gpio_set_dir(ALERT_GPIO, GPIO_OUT);
    gpio_set_level(ALERT_GPIO, 0);
    gpiod_exit();
    exit(0);
}

void sensor_callback(const struct gpio_callback_info *info) {
    static unsigned long last_time = 0;
    static int count = 0;

    unsigned long current_time = gpio_get_last_read_time(info->gpio);
    unsigned long elapsed_time = current_time - last_time;

    if (elapsed_time >= 500) {
        count = 0;
        last_time = current_time;
        printf("Seismic event detected!\n");
        gpio_set_level(ALERT_GPIO, 1);
        sleep(2);
        gpio_set_level(ALERT_GPIO, 0);
    } else {
        count++;
        if (count >= 10) {
            printf("Seismic event detected!\n");
            gpio_set_level(ALERT_GPIO, 1);
            sleep(2);
            gpio_set_level(ALERT_GPIO, 0);
            count = 0;
        }
    }

    // Log the event
    char timestamp[32];
    time_t now = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }
    fprintf(log_file, "%s - Seismic event detected!\n", timestamp);
    fclose(log_file);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpiod_init() != 0) {
        perror("Failed to initialize gpiod");
        return EXIT_FAILURE;
    }

    if (gpio_create_pattern_match(SENSOR1_GPIO, GPIO_INPUT, GPIO_DIR_IN, GPIO_PIN_TO_NUMBER(0)) < 0) {
        perror("Failed to configure GPIO23");
        return EXIT_FAILURE;
    }

    if (gpio_create_pattern_match(SENSOR2_GPIO, GPIO_INPUT, GPIO_DIR_IN, GPIO_PIN_TO_NUMBER(0)) < 0) {
        perror("Failed to configure GPIO24");
        return EXIT_FAILURE;
    }

    if (gpio_add_event_input(SENSOR1_GPIO, GPIO_EVENT_RISING | GPIO_EVENT_FALLING, sensor_callback, NULL) < 0) {
        perror("Failed to register sensor callback for GPIO23");
        return EXIT_FAILURE;
    }

    if (gpio_add_event_input(SENSOR2_GPIO, GPIO_EVENT_RISING | GPIO_EVENT_FALLING, sensor_callback, NULL) < 0) {
        perror("Failed to register sensor callback for GPIO24");
        return EXIT_FAILURE;
    }

    if (gpio_set_level(ALERT_GPIO, 0) < 0) {
        perror("Failed to set initial state of ALERT_GPIO");
        return EXIT_FAILURE;
    }

    if (gpio_export(ALERT_GPIO) < 0) {
        perror("Failed to export ALERT_GPIO");
        return EXIT_FAILURE;
    }

    if (open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, S_IRUSR | S_IWUSR) < 0) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    printf("Monitoring started. Press Ctrl+C to exit.\n");
    while (1) {
        usleep(1000000); // Sleep for 1 second
    }

    return EXIT_SUCCESS;
}

