#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <pthread.h>
#include <signal.h>
#include <errno.h>
#include <linux/spi/spidev.h>
#include <time.h>

#define BUFFER_SIZE 100
#define SPI_DEVICE 0
#define SPI_SPEED 10000000
#define CE_PIN 8
#define SCLK_PIN 11
#define MOSI_PIN 10
#define MISO_PIN 9
#define LED_PIN 17
#define READ_ADDRESS 0x00
#define REG_OFFSET 0x20

typedef struct {
    timespec timestamp;
    float rate;
} gyro_data_t;

typedef struct {
    gyro_data_t *buffer;
    pthread_mutex_t mutex;
    int buffer_index;
} gyro_buffer_t;

gyro_buffer_t gyro_buffer;

void spi_init(int fd) {
    if (spi_init(fd, SPI_SPEED) < 0) {
        perror("spi_init");
        exit(EXIT_FAILURE);
    }
}

int spi_transfer(int fd, const void *src, size_t len, void *dst) {
    return spi_xfer(fd, src, len, dst);
}

float read_gyro_rate() {
    int fd = open("/dev/spidev0.0", O_RDWR);
    if (fd < 0) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    spi_init(fd);

    uint8_t address[2] = {0x00, (REG_OFFSET >> 8) & 0xFF};
    uint8_t command[1] = {0x01}; // Set MSB to 1 for read

    int ret = spi_transfer(fd, address, 2, command);
    if (ret < 0) {
        perror("spi_transfer");
        exit(EXIT_FAILURE);
    }

    uint32_t reg_addr = (address[0] << 8) | address[1];
    uint32_t data;

    ret = spi_transfer(fd, &reg_addr, 2, &data);
    if (ret < 0) {
        perror("spi_transfer");
        exit(EXIT_FAILURE);
    }

    float rate = (float)data >> 16; // Assuming 16-bit signed data

    gyro_data_t gyro_data = {
        .timestamp = time(NULL),
        .rate = rate
    };

    pthread_mutex_lock(&gyro_buffer.mutex);
    gyro_buffer.buffer[gyro_buffer.buffer_index] = gyro_data;
    gyro_buffer.buffer_index = (gyro_buffer.buffer_index + 1) % BUFFER_SIZE;
    pthread_mutex_unlock(&gyro_buffer.mutex);

    return rate;
}

void warning_led_on() {
    write(LED_PIN, 1);
}

void warning_led_off() {
    write(LED_PIN, 0);
}

void signal_handler(int signum) {
    warning_led_off();
    close(fd);
    exit(0);
}

int main(int argc, char *argv[]) {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int fd = open("/dev/spidev0.0", O_RDWR);
    if (fd < 0) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    spi_init(fd);

    gyro_buffer_t gyro_buffer;
    pthread_mutex_init(&gyro_buffer.mutex, NULL);
    gyro_buffer.buffer = malloc(BUFFER_SIZE * sizeof(gyro_data_t));
    if (!gyro_buffer.buffer) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }

    while (1) {
        float rate = read_gyro_rate();

        for (int i = 0; i < BUFFER_SIZE; i++) {
            if (gyro_buffer.buffer[i].rate > 20.0) {
                warning_led_on();
                break;
            }
        }

        usleep(100000); // Adjust as needed
    }

    pthread_mutex_destroy(&gyro_buffer.mutex);
    close(fd);

    return 0;
}

