#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/mman.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <errno.h>
#include <pigpio.h>

#define RELAY_PINS {11, 12, 13} // GPIO17, GPIO18, GPIO27
#define PWM_FREQUENCY 100
#define PWM_RANGE 0-255
#define DEFAULT_DURATION 3600

void signal_handler(int signum) {
    for (int i = 0; i < 3; i++) {
        piSetupWild(RELAY_PINS[i]);
        piWrite(RELAY_PINS[i], 0);
    }
    printf("Sunset simulator terminated.\n");
    exit(0);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <duration in seconds>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    int duration = atoi(argv[1]);
    if (duration < 1 || duration > DEFAULT_DURATION) {
        fprintf(stderr, "Duration must be between 1 and %d seconds.\n", DEFAULT_DURATION);
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    pigpio_init(5); // Initialize pigpio with 5 seconds timeout

    for (int i = 0; i < 3; i++) {
        piSetupWild(RELAY_PINS[i]);
        piWrite(RELAY_PINS[i], 255); // Set initial lamps to full brightness
    }

    printf("Starting sunset simulator for %d seconds...\n", duration);
    for (int t = 0; t < duration; t += 10) { // Fade over 10ms intervals
        for (int i = 0; i < 3; i++) {
            int duty_cycle = PWM_RANGE * (t / duration); // Linear fade
            piWrite(RELAY_PINS[i], duty_cycle);
            printf("Lamp %d: %d%%\r", i + 1, duty_cycle);
            usleep(100000); // Sleep for 100ms
        }
    }

    printf("\nSunset simulator completed.\n");
    for (int i = 0; i < 3; i++) {
        piWrite(RELAY_PINS[i], 0); // Turn off all lamps
    }

    pigpio_cleanup();
    return 0;
}

