        for (int i = 0; i < 4; i++) {
            pioSetMode(i, PIOPIN_OUTPUT);
        }

        // Red phase
        pioWrite(GPIO_RED, 0);
        usleep(10000000); // 10 seconds

        // Red + Yellow phase
        pioWrite(GPIO_RED, 1);
        pioWrite(GPIO_YELLOW, 1);
        usleep(2000000); // 2 seconds

        // Green phase
        pioWrite(GPIO_GREEN, 0);
        usleep(10000000); // 10 seconds

        // Yellow phase
        pioWrite(GPIO_YELLOW, 1);
        usleep(3000000); // 3 seconds

