#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <signal.h>
#include <pthread.h>
#include <time.h>

#define I2C_BUS 1
#define MPR121_ADDRESS 0x50
#define RELAY_GPIO 17
#define TOUCH_DEBOUNCE_MS 100
#define TOUCH_READ_INTERVAL_MS 10

#define LOG_FILE "touch_relay.log"

typedef struct {
    int fd;
    struct i2c_client *client;
} i2c_context;

void log_error(const char *msg) {
    time_t now = time(NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    fprintf(LOG_FILE, "[%s] ERROR: %s\n", timestamp, msg);
}

void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        close(fd_i2c);
        close(fd_relay);
        fprintf(LOG_FILE, "Received signal, exiting gracefully.\n");
        exit(0);
    }
}

void *read_touch_status(void *arg) {
    i2c_context *ctx = (i2c_context *)arg;
    int status;
    while (1) {
        status = i2c_transfer(ctx->fd, MPR121_ADDRESS, 0x12, 2, 0);
        if (status < 0) {
            log_error("Failed to read from MPR121: %s");
            return NULL;
        }

        // Debounce touch events
        int touch_state = ctx->client->read_reg(ctx->fd, 0x00);
        if (touch_state & 0x01) {
            pthread_mutex_lock(&mutex_touch);
            while (pthread_mutex_trylock(&mutex_touch) == EAGAIN) {}
            // Toggle relay
            write_relay(ctx->client, RELAY_GPIO);
            pthread_mutex_unlock(&mutex_touch);
        }

        usleep(TOUCH_READ_INTERVAL_MS * 1000 / HRTIME_PER_SEC);
    }
    return NULL;
}

void write_relay(struct i2c_client *client, int pin) {
    int fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (fd < 0) {
        log_error("Failed to open log file for relay state.");
        return;
    }

    char msg[20];
    sprintf(msg, "Relay %d state: %s\n", pin, (client->read_reg(client->fd, 0x00) & 0x01) ? "ON" : "OFF");
    write(fd, msg, strlen(msg));
    close(fd);
}

int main(int argc, char *argv[]) {
    int fd_i2c, fd_relay;
    struct i2c_client *client;
    pthread_t touch_thread;
    pthread_mutex_t mutex_touch;

    if (signal(SIGINT, handle_signal) == SIG_IGN || signal(SIGTERM, handle_signal) == SIG_IGN) {
        fprintf(stderr, "Failed to register signal handler.\n");
        return 1;
    }

    fd_i2c = open(LOG_FILE, O_RDWR | O_CREAT | O_APPEND, 0644);
    if (fd_i2c < 0) {
        log_error("Failed to open log file.");
        return 1;
    }

    client = i2c_alloc(fd_i2c, I2C_BUS);
    if (!client) {
        log_error("Failed to allocate i2c client.");
        close(fd_i2c);
        return 1;
    }

    if (ioctl(fd_i2c, I2C_SLAVE, MPR121_ADDRESS) < 0) {
        log_error("Failed to set MPR121 address.");
        i2c_free(client);
        close(fd_i2c);
        return 1;
    }

    if (ioctl(fd_i2c, I2C_REQUEST, 1) < 0) {
        log_error("Failed to request I2C transfer.");
        i2c_free(client);
        close(fd_i2c);
        return 1;
    }

    pthread_mutex_init(&mutex_touch, NULL);

    i2c_context ctx = {fd_i2c, client};

    if (pthread_create(&touch_thread, NULL, read_touch_status, &ctx) != 0) {
        log_error("Failed to create touch reading thread.");
        i2c_free(client);
        close(fd_i2c);
        pthread_mutex_destroy(&mutex_touch);
        return 1;
    }

    // Keep the main thread alive
    usleep(1000000);

    pthread_join(touch_thread, NULL);

    i2c_free(client);
    close(fd_i2c);
    pthread_mutex_destroy(&mutex_touch);
    fclose(fd_relay);

    return 0;
}

