#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <errno.h>
#include <libgpiod.h>

#define GPIO17 17
#define GPIO18 18
#define GPIO23 23
#define LOG_FILE "flame_log.txt"
#define DELAY_MS 50
#define CONSECUTIVE_COUNT 3

int main(int argc, char *argv[]) {
    int gpio17_fd, gpio18_fd, led_fd, buzzer_fd;
    gpiod_ctx_t ctx;
    gpiod_button_t button;
    struct stat sb;
    char *log_file_path = LOG_FILE;
    char timestamp[32];
    char flame_detected[20];

    if (gpiod_init() < 0) {
        perror("Failed to initialize gpiod");
        exit(EXIT_FAILURE);
    }

    gpio17_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (gpio17_fd < 0) {
        perror("Failed to open log file");
        gpiod_ctx_destroy(&ctx);
        exit(EXIT_FAILURE);
    }

    gpiod_button_init(&button, GPIO17);
    if (gpiod_button_get(&button, &ctx) < 0) {
        perror("Failed to initialize button for GPIO17");
        close(gpio17_fd);
        gpiod_ctx_destroy(&ctx);
        exit(EXIT_FAILURE);
    }

    gpiod_button_set_edge(button, GPIOD_EDGE_FALLING);
    if (gpiod_button_enable(&button, &ctx) < 0) {
        perror("Failed to enable button for GPIO17");
        close(gpio17_fd);
        gpiod_ctx_destroy(&ctx);
        exit(EXIT_FAILURE);
    }

    gpiod_button_set_callback(&button, flame_detected_callback, NULL);

    gpiod_button_get_state(&button, &ctx);
    while (1) {
        if (gpiod_button_get_state(&button, &ctx) == GPIOD_BUTTON_LOW) {
            if (gettimeoflastaccess(timestamp, NULL) > DELAY_MS) {
                write(gpio17_fd, flame_detected, strlen(flame_detected));
                write(gpio18_fd, "1", 1); // Assuming GPIO18 is a buzzer
                write(gpio23_fd, "1", 1); // Assuming GPIO23 is an LED
                usleep(DELAY_MS * 1000); // Delay for 1 second
                gpiod_button_disable(&button, &ctx);
                gpiod_button_set_callback(&button, NULL, NULL);
            }
        } else {
            gpiod_button_enable(&button, &ctx);
        }
    }

    close(gpio17_fd);
    close(gpio18_fd);
    close(led_fd);
    close(buzzer_fd);

    gpiod_ctx_destroy(&ctx);

    if (ftruncate(fileno(gpio17_fd), 0) < 0) {
        perror("Failed to truncate log file");
    }

    if (fclose(gpio17_fd) < 0) {
        perror("Failed to close log file");
    }

    if (remove(log_file_path) < 0) {
        perror("Failed to remove log file");
    }

    exit(EXIT_SUCCESS);
}

void flame_detected_callback(gpiod_button_t *button, gpiod_state_t prev_state, gpiod_state_t curr_state) {
    static int consecutive_low = 0;
    static time_t last_low_time = 0;

    if (curr_state == GPIOD_BUTTON_LOW) {
        if (prev_state == GPIOD_BUTTON_HIGH) {
            consecutive_low++;
        }
    } else {
        consecutive_low = 0;
        last_low_time = time(NULL);
    }

    if (consecutive_low >= CONSECUTIVE_COUNT &&
        (time(NULL) - last_low_time) >= DELAY_MS) {
        char timestamp[32];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        sprintf(flame_detected, "Flame Detected\nTimestamp: %s", timestamp);
        write(fileno(stdout), flame_detected, strlen(flame_detected));
        write(gpio18_fd, "1", 1); // Activate buzzer
        write(gpio23_fd, "1", 1); // Activate LED
    }
    consecutive_low = 0;
}

