#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/time.h>
#include <fcntl.h>
#include <errno.h>
#include <libgpiod.h>

#define SOLENOID1_GPIO 17
#define SOLENOID2_GPIO 27
#define DISPENSE_INTERVAL 1000
#define LOG_FILE "dispense_log.txt"

void sigint_handler(int signum) {
    printf("\nGracefully deactivating solenoids and exiting...\n");
    gpiod_disable_channel(GPIO_CHANNEL_0);
    gpiod_disable_channel(GPIO_CHANNEL_1);
    close(LOG_FILE);
    exit(0);
}

int main() {
    int fd_log;
    struct itimerspec timer_spec;
    timespec start_time;
    timespec end_time;
    char timestamp[20];

    // Initialize libgpiod
    if (gpiod_init() != 0) {
        perror("Failed to initialize libgpiod");
        return 1;
    }

    // Register SIGINT handler
    signal(SIGINT, sigint_handler);

    // Open log file
    fd_log = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (fd_log == -1) {
        perror("Failed to open log file");
        return 1;
    }

    // Initialize timer
    timer_spec.timerspec.tv_sec = 0;
    timer_spec.timerspec.tv_nsec = DISPENSE_INTERVAL * 1000;

    // Start timer
    if (gpiod_timer_init(fd_log, &timer_spec, timer_spec.timerspec.tv_sec, timer_spec.timerspec.tv_nsec) != 0) {
        perror("Failed to initialize timer");
        return 1;
    }

    // Dispense loop
    while (1) {
        // Log start of dispense
        snprintf(timestamp, sizeof(timestamp), "%s", ctime(&start_time.tv_sec));
        write(fd_log, timestamp, strlen(timestamp));
        write(fd_log, "Solenoid1, Solenoid2, 0\n", 18);

        // Activate solenoid 1
        gpiod_channel_output_set(GPIO_CHANNEL_0, 1);
