#define PID_K_I 0.0
#define PID_K_D 0.0
#define PID_SAMPLE_TIME 0.05 // 50ms
#define MAX_MOTOR_SPEED 255

typedef struct {
    double tilt_error;
    double distance;
    int motor_a_speed;
    int motor_b_speed;
} log_entry;

int main(int argc, char *argv[]) {
    int motor_a_forward = GPIO_SET_DIGITAL(GPIO_A17, PI_OUTPUT);
    int motor_a_backward = GPIO_SET_DIGITAL(GPIO_A18, PI_OUTPUT);
    int motor_b_forward = GPIO_SET_DIGITAL(GPIO_A22, PI_OUTPUT);
    int motor_b_backward = GPIO_SET_DIGITAL(GPIO_A23, PI_OUTPUT);
    int ena = GPIO_SET_DIGITAL(GPIO_ENA, PI_OUTPUT);
    int enb = GPIO_SET_DIGITAL(GPIO_ENB, PI_OUTPUT);

    if (ena == -1 || enb == -1 || motor_a_forward == -1 || motor_a_backward == -1 || motor_b_forward == -1 || motor_b_backward == -1) {
        fprintf(stderr, "Failed to initialize GPIO pins.\n");
        return 1;
    }

    pigpio_init(50000); // Initialize pigpio with 50000 microseconds (50ms) resolution

    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file.\n");
        pigpio_terminate(1000); // Terminate pigpio on error
        return 1;
    }

    while (1) {
        // Simulate tilt error and distance
        double tilt_error = (double)rand() / RAND_MAX * 20.0 - 10.0;
        double distance = (double)rand() / RAND_MAX * 380.0 + 2.0;

        if (distance < 20.0) {
            // Obstacle detected, reverse motors at 50% speed
            motor_a_backward = GPIO_SET_DIGITAL(motor_a_forward, PI_OUTPUT);
            motor_b_backward = GPIO_SET_DIGITAL(motor_b_forward, PI_OUTPUT);
            motor_a_speed = motor_b_speed = MAX_MOTOR_SPEED;
        } else {
            // PID control loop
            int motor_a_speed_setpoint = 128;
            int motor_b_speed_setpoint = 128;

            // Calculate error
            double error = tilt_error;

            // Integral term
            double integral = 0.0;

            // Derivative term
            double derivative = 0.0;

            // PID calculation
            double pid_output = PID_K_P * error + PID_K_I * integral + PID_K_D * derivative;

            // Clamp output to motor speed limits
            pid_output = CLIP(pid_output, -MAX_MOTOR_SPEED, MAX_MOTOR_SPEED);

            // Update integral term
            integral += error;

            // Update motor speeds
            motor_a_speed = motor_a_speed_setpoint + pid_output;
            motor_b_speed = motor_b_speed_setpoint + pid_output;

            // Clamp motor speeds
            motor_a_speed = CLIP(motor_a_speed, -MAX_MOTOR_SPEED, MAX_MOTOR_SPEED);
            motor_b_speed = CLIP(motor_b_speed, -MAX_MOTOR_SPEED, MAX_MOTOR_SPEED);
        }

        // Write log entry
        log_entry log_entry;
        log_entry.tilt_error = tilt_error;
        log_entry.distance = distance;
        log_entry.motor_a_speed = motor_a_speed;
        log_entry.motor_b_speed = motor_b_speed;
        fprintf(log_file, "%d %f %f %d %d\n", time(NULL), log_entry.tilt_error, log_entry.distance, log_entry.motor_a_speed, log_entry.motor_b_speed);

        // Sleep for PID sample time
        usleep(PID_SAMPLE_TIME * 1000000);
    }

    // Close log file and terminate pigpio
    fclose(log_file);
    pigpio_terminate(1000);

    return 0;
}

// Helper functions
int CLIP(int value, int min, int max) {
    if (value < min) return min;
    if (value > max) return max;
    return value;
}

