#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <libgpiod.h>

#define SENSOR_PIN 7
#define RELAY_PIN 17
#define DEBOUNCE_DELAY 50

bool touch_detected = false;
bool relay_active = false;

void handle_signal(int signum) {
    printf("Received signal %d, exiting gracefully...\n", signum);
    relay_active = false;
    exit(0);
}

void setup_gpio(void) {
    int ret;

    // Initialize libgpiod
    if (gpiod_init() < 0) {
        fprintf(stderr, "Failed to initialize libgpiod\n");
        exit(EXIT_FAILURE);
    }

    // Set GPIO4 as output for the relay
    ret = gpiod_output_init(RELAY_PIN, 1);
    if (ret < 0) {
        fprintf(stderr, "Failed to initialize GPIO4 as output\n");
        exit(EXIT_FAILURE);
    }

    // Set GPIO4 as input with pull-up enabled for the sensor
    ret = gpiod_pin_config_init(SENSOR_PIN, GPIOD_INPUT);
    if (ret < 0) {
        fprintf(stderr, "Failed to initialize GPIO4 as input with pull-up\n");
        exit(EXIT_FAILURE);
    }
    ret = gpiod_pin_config_add_pull_up_en(SENSOR_PIN);
    if (ret < 0) {
        fprintf(stderr, "Failed to enable pull-up on GPIO4\n");
        exit(EXIT_FAILURE);
    }
}

void debouncing_function(void) {
    static unsigned long last_debounce_time = 0;
    unsigned long current_time = millis();

    if (current_time - last_debounce_time > DEBOUNCE_DELAY) {
        last_debounce_time = current_time;
        touch_detected = true;
    }
}

void relay_control_function(void) {
    if (touch_detected) {
        relay_active = !relay_active;
        if (relay_active) {
            gpio_set_level(RELAY_PIN, 1);
        } else {
            gpio_set_level(RELAY_PIN, 0);
        }
    }
}

int main(int argc, char *argv[]) {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    setup_gpio();

    while (1) {
        debouncing_function();
        relay_control_function();
        usleep(10000); // Sleep for 10ms to avoid busy-waiting
    }

    gpiod_pin_config_del(SENSOR_PIN);
    gpiod_output_free(RELAY_PIN);
    gpiod_cleanup();

    return 0;
}

