#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <alsa/asoundlib.h>
#include <pigpio.h>

#ifdef ALSA_AVAILABLE
#include <asoundlib.h>
#endif

#define SAMPLE_RATE 8000
#define BITS_PER_SAMPLE 16
#define CHANNEL_LAYOUT 1
#define BUFFER_SIZE 1024
#define LED_RED 17
#define LED_GREEN 18
#define LED_BLUE 27
#define LED_PWM_PERIOD 10000
#define SINE_AMPLITUDE 0.5

#define DEFAULT_SENSITIVITY 1.0

#define ERR_PRINT(fmt, args...) do { \
    fprintf(stderr, fmt, ##args); \
} while (0)

#define INFO_PRINT(fmt, args...) do { \
    fprintf(stdout, fmt, ##args); \
} while (0)

int main(int argc, char *argv[]) {
    int led_gpio = LED_RED;
    int r, g, b;
    double rms_amplitude, sensitivity = DEFAULT_SENSITIVITY;
    struct iocb *iocbs[2];
    int iocb_count = 2;
    int ret;
    snd_pcm_t *handle;
    pigpio_t *pi;

    if (argc > 1)
        sensitivity = atoi(argv[1]);

    if (!ALSA_AVAILABLE) {
        INFO_PRINT("ALSA not available, simulating audio input with sine wave.\n");
        // Simulate audio input with sine wave
        for (int i = 0; i < 10000; i++) {
            r = (int)(SINE_AMPLITUDE * sin(2 * M_PI * i / SAMPLE_RATE));
            g = (int)(SINE_AMPLITUDE * sin(2 * M_PI * (i + 1) / SAMPLE_RATE));
            b = (int)(SINE_AMPLITUDE * sin(2 * M_PI * (i + 2) / SAMPLE_RATE));
            pigpio_set_pattern(pi, LED_RED, 0, 255, 0, 0, 100);
            pigpio_set_pattern(pi, LED_GREEN, 0, 0, 255, 0, 100);
            pigpio_set_pattern(pi, LED_BLUE, 0, 0, 0, 255, 100);
            usleep(LED_PWM_PERIOD / 1000);
        }
        return 0;
    }

    if (open("/dev/pcm0", O_RDWR) == -1) {
        ERR_PRINT("Failed to open audio device: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    handle = snd_pcm_open(&pi->device, SND_PCM_STREAM_CAPTURE, 0, -1);
    if (handle == NULL) {
        ERR_PRINT("Failed to open audio handle: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    snd_pcm_setup(handle, SAMPLE_RATE, BITS_PER_SAMPLE, CHANNEL_LAYOUT, SND_PCM_S16_LE, BUFFER_SIZE, 0);
    if (snd_pcm_prepare(handle) == -1) {
        ERR_PRINT("Failed to prepare audio handle: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    ret = snd_pcm_start(handle);
    if (ret == -1) {
        ERR_PRINT("Failed to start audio: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    pigpio_init(1);
    if (pigpio_init(1) == -1) {
        ERR_PRINT("Failed to initialize pigpio: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    while (1) {
        ret = snd_pcm_avail(handle);
        if (ret < 0) {
            ERR_PRINT("Error checking audio availability: %s\n", strerror(errno));
            break;
        }

        ret = snd_pcm_grab(handle, BUFFER_SIZE);
        if (ret < 0) {
            ERR_PRINT("Error grabbing audio buffer: %s\n", strerror(errno));
            break;
        }

        ret = snd_pcm_avail(handle);
        if (ret < BUFFER_SIZE) {
            ERR_PRINT("Buffer overrun, resuming audio.\n");
            snd_pcm_resume(handle);
            continue;
        }

        ret = snd_pcm_avail(handle);
        if (ret < BUFFER_SIZE) {
            ERR_PRINT("Audio suspended, resuming audio.\n");
            snd_pcm_resume(handle);
            continue;
        }

        ret = snd_pcm_readi(handle, (void *)rms_amplitude);
        if (ret < 0) {
            ERR_PRINT("Error reading RMS amplitude: %s\n", strerror(errno));
            break;
        }

        rms_amplitude = (double)rms_amplitude / (double)pow(2, BITS_PER_SAMPLE * 8);

        // Map RMS amplitude to RGB color
        r = (int)(rms_amplitude * sensitivity * 255);
        g = (int)(rms_amplitude * sensitivity * 255);
        b = (int)(rms_amplitude * sensitivity * 255);

        pigpio_set_pattern(pi, LED_RED, 0, r, 0, 0, 100);
        pigpio_set_pattern(pi, LED_GREEN, 0, 0, g, 0, 100);
        pigpio_set_pattern(pi, LED_BLUE, 0, 0, 0, b, 100);
        usleep(LED_PWM_PERIOD / 1000);
    }

    pigpio_cleanup(pi);
    close("/dev/pcm0");
    snd_pcm_close(handle);
    snd_pcm_drain(handle);
    snd_pcm_unlink(handle);

    return EXIT_SUCCESS;
}

