    sigaddset(&set, SIGINT);
    sigprocmask(SIG_BLOCK, &set, NULL);
    sigint_handler(signum);
}

int main(int argc, char *argv[]) {
    int i2c_fd;
    int sensor_value_r, sensor_value_g, sensor_value_b;
    struct timeval tv;
    FILE *csv_file = fopen(CSV_FILE, "a");

    if (!csv_file) {
        perror("fopen");
        return EXIT_FAILURE;
    }

