    signal(SIGTERM, sigterm_handler);

    i2c_fd = piGPIO_open(TCS34725_ADDRESS, PI_OUTPUT);
    if (i2c_fd < 0) {
        perror("piGPIO_open");
        return EXIT_FAILURE;
    }

    piGPIO_write(i2c_fd, 0x10); // Set integration time
    piGPIO_write(i2c_fd, 0x00); // Set integration time

    while (1) {
        tv.tv_sec = 0;
        tv.tv_usec = 0;
        piGPIO_read(i2c_fd, &sensor_value_r, 1);
        piGPIO_read(i2c_fd, &sensor_value_g, 1);
        piGPIO_read(i2c_fd, &sensor_value_b, 1);

        if (piGPIO_read(i2c_fd, &sensor_value_r, 1) == -1) {
            fprintf(stderr, "Error reading sensor value R\n");
            sensor_value_r = 0;
        }
        if (piGPIO_read(i2c_fd, &sensor_value_g, 1) == -1) {
            fprintf(stderr, "Error reading sensor value G\n");
            sensor_value_g = 0;
        }
        if (piGPIO_read(i2c_fd, &sensor_value_b, 1) == -1) {
            fprintf(stderr, "Error reading sensor value B\n");
            sensor_value_b = 0;
        }

        if (fputs(std::to_string(tv.tv_sec) + "," + std::to_string(tv.tv_usec) + "," + std::to_string(sensor_value_r) + "," + std::to_string(sensor_value_g) + "," + std::to_string(sensor_value_b) + "\n", csv_file) < 0) {
            perror("fputs");
            sensor_value_r = 0;
            sensor_value_g = 0;
            sensor_value_b = 0;
