#define RELAY_PIN_15 22
#define RELAY_PIN_17 23

#define SUNRISE_HOURS 1
#define DAYTIME_HOURS 6
#define SUNSET_HOURS 1
#define NIGHTTIME_HOURS 14.4

void signal_handler(int signum) {
    for (int i = RELAY_PIN_11; i <= RELAY_PIN_17; i++) {
        gpioSetPinMode(i, PI_OUTPUT);
    }
    printf("Program received SIGINT or SIGTERM, turning off all relays.\n");
    sleep(1);
    for (int i = RELAY_PIN_11; i <= RELAY_PIN_17; i++) {
        gpioWrite(i, 0);
    }
    pioClose();
    exit(0);
}

void init_gpio() {
    if (pigpioInit() == -1) {
        fprintf(stderr, "Failed to initialize pigpio library.\n");
        exit(EXIT_FAILURE);
    }
}

void setup_relays() {
    gpioSetPinMode(RELAY_PIN_11, PI_OUTPUT);
    gpioSetPinMode(RELAY_PIN_13, PI_OUTPUT);
    gpioSetPinMode(RELAY_PIN_15, PI_OUTPUT);
    gpioSetPinMode(RELAY_PIN_17, PI_OUTPUT);
}

void sunrise() {
    for (int i = 0; i < SUNRISE_HOURS * 3600; i++) {
        for (int j = RELAY_PIN_11; j <= RELAY_PIN_17; j++) {
            gpioWrite(j, 1);
            sleep(0.1);
            gpioWrite(j, 0);
        }
    }
}

void daytime() {
    for (int i = 0; i < DAYTIME_HOURS * 3600; i++) {
        for (int j = RELAY_PIN_11; j <= RELAY_PIN_17; j++) {
            gpioWrite(j, 1);
            sleep(0.1);
            gpioWrite(j, 0);
        }
    }
}

void sunset() {
    for (int i = 0; i < SUNSET_HOURS * 3600; i++) {
        for (int j = RELAY_PIN_11; j <= RELAY_PIN_17; j++) {
            gpioWrite(j, 0);
            sleep(0.1);
            gpioWrite(j, 1);
        }
    }
}

void nighttime() {
    for (int i = 0; i < NIGHTTIME_HOURS * 3600; i++) {
        for (int j = RELAY_PIN_11; j <= RELAY_PIN_17; j++) {
            gpioWrite(j, 1);
            sleep(0.1);
            gpioWrite(j, 0);
        }
    }
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    init_gpio();
    setup_relays();

    while (1) {
        sunrise();
        daytime();
        sunset();
        nighttime();
    }

    pioClose();
    return 0;
}

