#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_PIN 11
#define DEBOUNCE_INTERVAL_MS 200
#define VIDEO_CAPTURE_DURATION_SEC 5
#define LOG_FILE_PATH "/home/pi/logs/motion_log.txt"
#define VIDEO_CAPTURE_PATH "/home/pi/videos/"

int sensor_gpio_fd;

void signal_handler(int signum) {
    close(sensor_gpio_fd);
    printf("Program terminated by user.\n");
    exit(0);
}

void setup_gpio_fd() {
    int ret = gpiod_channel_new_first_available(&sensor_gpio_fd);
    if (ret < 0) {
        perror("Failed to get GPIO channel");
        exit(EXIT_FAILURE);
    }
}

void setup_logging() {
    FILE *log_file = fopen(LOG_FILE_PATH, "a");
    if (!log_file) {
        perror("Failed to open motion log file");
        exit(EXIT_FAILURE);
    }
    time_t now = time(NULL);
    struct tm *time_struct = localtime(&now);
    fprintf(log_file, "%s", asctime(time_struct));
    fclose(log_file);
}

void start_video_capture(const char *filename) {
    char cmd[100];
    sprintf(cmd, "raspivid -o %s -t %d -g 30 -fps 30 -c copy", filename, VIDEO_CAPTURE_DURATION_SEC * 1000);
    system(cmd);
}

void handle_motion_event() {
    static time_t last_motion_time = 0;
    time_t current_time = time(NULL);
    if (current_time - last_motion_time > DEBOUNCE_INTERVAL_MS / 1000) {
        last_motion_time = current_time;
        start_video_capture(VIDEO_CAPTURE_PATH + "motion_" + std::to_string(current_time / 1000) + ".h264");
        FILE *log_file = fopen(LOG_FILE_PATH, "a");
        if (!log_file) {
            perror("Failed to open motion log file");
            exit(EXIT_FAILURE);
        }
        fprintf(log_file, "%s", asctime(localtime(&current_time)));
        fclose(log_file);
    }
}

int main() {
    signal(SIGINT, signal_handler);
    setup_gpio_fd();
    setup_logging();

    while (1) {
        int value = read(sensor_gpio_fd, NULL);
        if (value < 0) {
            perror("Failed to read from GPIO");
            exit(EXIT_FAILURE);
        }
        handle_motion_event();
    }

    return 0;
}

