#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <mpu6050.h>

#define I2C_BUS 1
#define AD0_LOW 1
#define TIMESTAMP_FORMAT "%Y-%m-%d %H:%M:%S"
#define LOG_FILE "gyro_log.csv"
#define SAMPLE_INTERVAL_MS 10000  // 100 Hz
#define MAX_REINITIALIZATION_ATTEMPTS 3

mpu6050 mpu;

void init_mpu6050(int i2c_fd) {
    int ret;
    char command[10];

    // Initialize MPU-6050
    ret = mpu_init(i2c_fd);
    if (ret) {
        fprintf(stderr, "Failed to initialize MPU-6050\n");
        return;
    }

    // Set AD0 for I2C address 0x68
    sprintf(command, "AD0 0");
    ret = mpu_set_config(i2c_fd, command);
    if (ret) {
        fprintf(stderr, "Failed to set AD0\n");
        return;
    }

    // Set gyroscope configuration for 100 Hz
    sprintf(command, "GSEL 0x4");
    ret = mpu_set_gyro_config(i2c_fd, command);
    if (ret) {
        fprintf(stderr, "Failed to set gyro configuration\n");
        return;
    }

    // Set accelerometer configuration for 100 Hz
    sprintf(command, "ACSEL 0x8");
    ret = mpu_set_acc_config(i2c_fd, command);
    if (ret) {
        fprintf(stderr, "Failed to set accel configuration\n");
        return;
    }

    // Enable gyro and accelerometer
    sprintf(command, "GPOSENABLE 1");
    ret = mpu_set_gyro_enable(i2c_fd, command);
    if (ret) {
        fprintf(stderr, "Failed to enable gyro\n");
        return;
    }

    sprintf(command, "ACPOSENABLE 1");
    ret = mpu_set_acc_enable(i2c_fd, command);
    if (ret) {
        fprintf(stderr, "Failed to enable accel\n");
        return;
    }
}

