void log_freefall(const char *timestamp, double x, double y, double z) {
    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        perror("Failed to open log file");
        return;
    }
    time_t now = time(NULL);
    fprintf(file, "%s,%.3f,%.3f,%.3f\n", ctime(&now), x, y, z);
    fclose(file);
}

int main(int argc, char *argv[]) {
    pigpio_init(5);  // Initialize pigpio with 5 available pins (GPIOs 0-4)

    int i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open i2c bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        return EXIT_FAILURE;
    }

    while (1) {
        int16_t x, y, z;
        if (read(i2c_fd, &x, 2) != 2 ||
            read(i2c_fd, &y, 2) != 2 ||
            read(i2c_fd, &z, 2) != 2) {
            fprintf(stderr, "I2C read error\n");
            continue;
        }

        double abs_x = fabs(x);
        double abs_y = fabs(y);
        double abs_z = fabs(z);

        if (abs_x < FALL_THRESHOLD && abs_y < FALL_THRESHOLD && abs_z < FALL_THRESHOLD) {
            double start_time = millis();
            while (millis() - start_time < ALARM_DURATION * 1000) {
                int16_t new_x, new_y, new_z;
                if (read(i2c_fd, &new_x, 2) != 2 ||
                    read(i2c_fd, &new_y, 2) != 2 ||
                    read(i2c_fd, &new_z, 2) != 2) {
                    fprintf(stderr, "I2C read error during alarm\n");
                    break;
                }

                if (fabs(new_x) < FALL_THRESHOLD &&
                    fabs(new_y) < FALL_THRESHOLD &&
                    fabs(new_z) < FALL_THRESHOLD) {
                    break;
                }
            }

            if (millis() - start_time >= ALARM_DURATION * 1000) {
                log_freefall(ctime(NULL), x, y, z);
                gpioWrite(GPIO_ALARM, 1);
                usleep(1000000);
                gpioWrite(GPIO_ALARM, 0);
            }
        }

        gpioWrite(GPIO_ALARM, 0);
        usleep(100000);  // Poll every 100ms
    }

    close(i2c_fd);
    pigpio_terminate(1000);  // Terminate pigpio with a 1 second timeout
    return EXIT_SUCCESS;
}

