#include <linux/gpio.h>
#include <linux/interrupt.h>
#include <pthread.h>
#include <time.h>
#include <errno.h>
#include <stdbool.h>

#define TRIG_GPIO 4
#define ECHO_GPIO 18
#define MAX_DISTANCE 4000
#define MAX_WAIT_TIME 1000000
#define TRIG_PULSE_WIDTH 200000000
#define ECHO_PULSE_WIDTH_MAX 23200000000

#define LOG_FILE "distance_log.txt"

typedef struct {
    pthread_mutex_t mutex;
    int trigger_timer;
    int trigger_count;
    int echo_timer;
    int echo_count;
    struct timespec timestamp;
} sensor_data;

void trigger_callback(int signum, siginfo_t *info, void *context) {
    static sensor_data data;
    data.trigger_count++;
    if (data.trigger_count % 2 == 0) {
        data.trigger_timer = 0;
        data.echo_timer = 0;
        data.timestamp.tv_sec = 0;
        data.timestamp.tv_nsec = 0;
        write_to_log(&data);
    }
}

void echo_callback(int signum, siginfo_t *info, void *context) {
    static sensor_data *data = &data;
    data->echo_count++;
    if (data->echo_count % 2 == 0) {
        data.echo_timer = 0;
        data.timestamp.tv_sec = 0;
        data.timestamp.tv_nsec = 0;
        write_to_log(data);
    }
}

void write_to_log(sensor_data *data) {
    timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    data->timestamp.tv_sec = ts.tv_sec;
    data->timestamp.tv_nsec = ts.tv_nsec;

    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        perror("Failed to open file");
        return;
    }

    char log_entry[100];
    sprintf(log_entry, "%ld_%ld,", data->timestamp.tv_sec, data->timestamp.tv_nsec);
    fprintf(file, "%s", log_entry);
    fprintf(file, "%d,", data->echo_timer);
    fprintf(file, "%d\n", data->trigger_count);

    fclose(file);
}

int main(int argc, char *argv[]) {
    int ret;
    int trig_gpio = TRIG_GPIO;
    int echo_gpio = ECHO_GPIO;
    int trig_mode = GPIO_OUTPUT;
    int echo_mode = GPIO_INPUT;
    int irq_mask = 0;
    int epoll_fd;
    struct epoll_event ev;
    struct epoll_event ev_trigger, ev_echo;
    sensor_data data;
    pthread_t interrupt_thread;

    ret = init_gpio();
    if (ret < 0) {
        perror("Failed to initialize GPIO");
        return ret;
    }

    ret = init_epoll();
    if (ret < 0) {
        perror("Failed to initialize epoll");
        return ret;
    }

    ev.events = EPOLLIN;
    ev.data.fd = trig_gpio;
