#include <sys/wait.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS 1
#define BUZZER_GPIO 17
#define FALL_THRESHOLD 0.2
#define IMPACT_THRESHOLD 1.5
#define RETRY_COUNT 3

int i2c_fd;
int sensor_address = 0x68; // LIS3DH default address

void init_i2c();
void read_accel_data(void);
void detect_free_fall(float magnitude);
void detect_impact(void);
void activate_buzzer(void);

int main(int argc, char *argv[]) {
    int ret;
    pid_t buzzer_pid;

    if (argc > 1 && strcmp(argv[1], "no_free_fall") == 0) {
        IMPACT_THRESHOLD = 0.0;
    }
    if (argc > 2 && strcmp(argv[2], "no_impact") == 0) {
        FALL_THRESHOLD = 0.0;
    }

    init_i2c();

    while (1) {
        read_accel_data();
        detect_free_fall(get_acceleration_magnitude());
        if (detect_impact()) {
            activate_buzzer();
        }
        usleep(100000); // Sleep for 100ms between readings
    }

    return 0;
}

void init_i2c(void) {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open i2c bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, sensor_address) < 0) {
        for (int i = 0; i < RETRY_COUNT; i++) {
            if (ioctl(i2c_fd, I2C_SLAVE, sensor_address) == 0) {
                break;
            }
            printf("Retry %d of %d\n", i + 1, RETRY_COUNT);
        }
        if (i == RETRY_COUNT) {
            perror("Failed to acquire bus ownership after retries");
            exit(EXIT_FAILURE);
        }
    }
}

void read_accel_data(void) {
    uint8_t reg_addr[1];
    reg_addr[0] = 0x3B; // Register address for acceleration data

    if (ioctl(i2c_fd, I2C_READ, reg_addr) < 0) {
        perror("Failed to read from sensor");
        exit(EXIT_FAILURE);
    }

    float x, y, z;
    memcpy(&x, (void*)reg_addr + 1, 2);
    memcpy(&y, (void*)(reg_addr + 3), 2);
    memcpy(&z, (void*)(reg_addr + 5), 2);

    get_acceleration_magnitude(&x, &y, &z, &magnitude);
}

float get_acceleration_magnitude(float *ax, float *ay, float *az, float *magnitude) {
    *magnitude = sqrt(*ax * *ax + *ay * *ay + *az * *az);
}

void detect_free_fall(float magnitude) {
    if (magnitude < FALL_THRESHOLD) {
        printf("Free fall detected!\n");
        activate_buzzer();
    }
}

void detect_impact(void) {
    float current_magnitude = get_acceleration_magnitude(ax, ay, az, &magnitude);
    return current_magnitude > IMPACT_THRESHOLD;
}

void activate_buzzer(void) {
    if (piGPIO_open(BUZZER_GPIO, 0) < 0) {
        perror("Failed to open buzzer GPIO");
        exit(EXIT_FAILURE);
    }

    piGPIO_set_level(BUZZER_GPIO, 1);
    sleep(1);
    piGPIO_set_level(BUZZER_GPIO, 0);

    piGPIO_close(BUZZER_GPIO);
}

int main(int argc, char *argv[]) {
    // ... (same as above)

    piGPIO_init();

    // ... (same as above)

    // Handle SIGINT to cleanly shut down
    atexit(cleanup);

    pid_t buzzer_pid = pidof "pi_buzzer";
    if (buzzer_pid != 0) {
        kill(buzzer_pid);
    }

    piGPIO_close();
    close(i2c_fd);
    return 0;

cleanup:
    piGPIO_close();
    close(i2c_fd);
    return 0;
}

