#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod/gpio.h>

#define GPIO_NUM_PINS 4
#define STEP_DELAY_US 1000
#define STEPS_PER_REV 2048
#define GEAR_RATIO 1/64
#define SQUARE_SIDE 50

void sigint_handler(int sig) {
    gpio_output_enable(GPIO_NUM_PINS);
    gpio_output_set(GPIO_NUM_PINS, 0);
    gpio_output_enable(GPIO_NUM_PINS);
    printf("Stopping motors...\n");
    sleep(1);
    gpio_output_disable(GPIO_NUM_PINS);
    gpio_output_set(GPIO_NUM_PINS, 0);
    gpio_output_disable(GPIO_NUM_PINS);
    printf("Resources released.\n");
    exit(0);
}

int main() {
    struct gpio_desc desc[] = {
        {GPIO_NUM_PINS, GPIO_OUT},
    };

    int ret;

    // Initialize libgpiod
    ret = libgpiod_init(GPIO_NUM_PINS, desc, NULL);
    if (ret < 0) {
        perror("Failed to initialize libgpiod");
        exit(EXIT_FAILURE);
    }

    // Set up signal handler
    signal(SIGINT, sigint_handler);

    // Initialize GPIO pins
    ret = gpio_init(desc);
    if (ret < 0) {
        perror("Failed to initialize GPIO pins");
        exit(EXIT_FAILURE);
    }

    // Configure Motor 1 (X-axis)
    gpio_pin_config(desc, GPIO_NUM_PINS, GPIO_PIN_OUT, 4);
    gpio_pin_config(desc, GPIO_NUM_PINS, GPIO_PIN_OUT, 17);
    gpio_pin_config(desc, GPIO_NUM_PINS, GPIO_PIN_OUT, 27);
    gpio_pin_config(desc, GPIO_NUM_PINS, GPIO_PIN_OUT, 22);

    // Configure Motor 2 (Y-axis)
    gpio_pin_config(desc, GPIO_NUM_PINS, GPIO_PIN_OUT, 5);
    gpio_pin_config(desc, GPIO_NUM_PINS, GPIO_PIN_OUT, 6);
    gpio_pin_config(desc, GPIO_NUM_PINS, GPIO_PIN_OUT, 13);
    gpio_pin_config(desc, GPIO_NUM_PINS, GPIO_PIN_OUT, 19);

    // Calculate steps for a 50mm square
    int steps_x = (SQUARE_SIDE * 2 * GEAR_RATIO) / STEPS_PER_REV;
