#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <libgpiod/gpio.h>
#include <libgpiod/gpio-private.h>
#include <libgpiod/error.h>
#include <libgpiod/gpio-types.h>

#define I2C_BUS "/dev/i2c-1"
#define LIS3DH_ADDR 0x68
#define LIS3DH_REG_CONFIG 0x20
#define LIS3DH_REG_OUTXHIGH 0x21
#define LIS3DH_REG_OUTXLOW 0x22
#define LIS3DH_REG_OUTYHIGH 0x23
#define LIS3DH_REG_OUTYLOW 0x24
#define LIS3DH_REG_OUTZHIGH 0x25
#define LIS3DH_REG_OUTZLOW 0x26
#define LIS3DH_REG_INTCON 0x27
#define LIS3DH_INT_XHIGH 0x01
#define LIS3DH_INT_XLOW 0x02
#define LIS3DH_INT_YHIGH 0x04
#define LIS3DH_INT_YLOW 0x08
#define LIS3DH_INT_ZHIGH 0x10
#define LIS3DH_INT_ZLOW 0x20

#define DEFAULT_THRESHOLD 2.0

int threshold = DEFAULT_THRESHOLD;
int lis3dh_i2c_fd;
int lis3dh_address = LIS3DH_ADDR;

void sigint_handler(int sig) {
    printf("Received SIGINT, shutting down...\n");
    close(lis3dh_i2c_fd);
    libgpiod_exit();
    exit(0);
}

void configure_lis3dh(int address, int threshold) {
    int config_reg = LIS3DH_REG_CONFIG;
    int config_data = (1 << 0) | (1 << 1) | (1 << 2); // ±2g range, 12-bit, 100Hz

    if (ioctl(lis3dh_i2c_fd, I2C_SLAVE, address) < 0) {
        perror("Failed to open I2C bus");
        libgpiod_exit();
        exit(1);
    }

    if (write(lis3dh_i2c_fd, &config_reg, 1) != 1) {
        perror("Failed to write to LIS3DH_REG_CONFIG");
        libgpiod_exit();
        exit(1);
    }

    if (write(lis3dh_i2c_fd, &config_data, 3) != 3) {
        perror("Failed to write to LIS3DH_REG_CONFIG");
        libgpiod_exit();
        exit(1);
    }

    if (ioctl(lis3dh_i2c_fd, I2C_SLAVE, address) < 0) {
        perror("Failed to open I2C bus");
        libgpiod_exit();
        exit(1);
    }

    if (read(lis3dh_i2c_fd, &config_data, 1) != 1) {
        perror("Failed to read LIS3DH_REG_CONFIG");
        libgpiod_exit();
        exit(1);
    }

    if (config_data != config_data) {
        perror("Failed to configure LIS3DH");
        libgpiod_exit();
        exit(1);
    }

    if (threshold > 0) {
        threshold_reg = LIS3DH_REG_INTCON;
        threshold_data = (threshold - 1) << threshold_reg;
        if (write(lis3dh_i2c_fd, &threshold_data, 1) != 1) {
            perror("Failed to write threshold");
            libgpiod_exit();
            exit(1);
        }
    }
}

void read_lis3dh() {
    int xhigh_reg = LIS3DH_REG_OUTXHIGH;
    int xlow_reg = LIS3DH_REG_OUTXLOW;
    int yhigh_reg = LIS3DH_REG_OUTYHIGH;
    int ylow_reg = LIS3DH_REG_OUTYLOW;
    int zhigh_reg = LIS3DH_REG_OUTZHIGH;
    int zlow_reg = LIS3DH_REG_OUTZLOW;

    int xhigh, xlow, yhigh, ylow, zhigh, zlow;

    if (ioctl(lis3dh_i2c_fd, I2C_SLAVE, lis3dh_address) < 0) {
        perror("Failed to open I2C bus");
        libgpiod_exit();
        exit(1);
    }

    if (read(lis3dh_i2c_fd, &xhigh, 1) != 1) {
        perror("Failed to read XHIGH");
        libgpiod_exit();
        exit(1);
    }
    xhigh = ntohl(xhigh);

    if (read(lis3dh_i2c_fd, &xlow, 1) != 1) {
        perror("Failed to read XLOW");
        libgpiod_exit();
        exit(1);
    }
    xlow = ntohl(xlow);

    if (read(lis3dh_i2c_fd, &yhigh, 1) != 1) {
        perror("Failed to read YHIGH");
        libgpiod_exit();
        exit(1);
    }
    yhigh = ntohl(yhigh);

    if (read(lis3dh_i2c_fd, &ylow, 1) != 1) {
        perror("Failed to read YLOW");
        libgpiod_exit();
        exit(1);
    }
    ylow = ntohl(ylow);

    if (read(lis3dh_i2c_fd, &zhigh, 1) != 1) {
        perror("Failed to read ZHIGH");
        libgpiod_exit();
        exit(1);
    }
    zhigh = ntohl(zhigh);

    if (read(lis3dh_i2c_fd, &zlow, 1) != 1) {
        perror("Failed to read ZLOW");
        libgpiod_exit();
        exit(1);
    }
    zlow = ntohl(zlow);

    if (threshold > 0) {
        if (xhigh > threshold || xlow > threshold ||
            yhigh > threshold || ylow > threshold ||
            zhigh > threshold || zlow > threshold) {
            struct tm tm;
            time_t now = time(NULL);
            tm = *localtime(&now);

            char log_msg[100];
            sprintf(log_msg, "Timestamp: %04d-%02d-%02d %02d:%02d:%02d - Acceleration: X: %d, Y: %d, Z: %d",
                    tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_day, tm.tm_hour, tm.tm_min, tm.tm_sec,
                    xhigh, yhigh, zhigh);

            FILE *log_file = fopen("/var/log/high_acceleration.log", "a");
            if (log_file == NULL) {
                perror("Failed to open log file");
                libgpiod_exit();
                exit(1);
            }
            fprintf(log_file, "%s\n", log_msg);
            fclose(log_file);
        }
    }
}

int main(int argc, char *argv[]) {
    int i2c_fd, i2c_result;
    int opt;
    int address = lis3dh_address;
    int threshold = DEFAULT_THRESHOLD;

    while ((opt = getopt(argc, argv, "a:t:")) != -1) {
        switch (opt) {
            case 'a':
                address = strtol(optarg, NULL, 16);
                if (address > 0xFF) {
                    fprintf(stderr, "Error: I2C address out of range. Must be 0x00-0x77.\n");
                    exit(EXIT_FAILURE);
                }
                break;
            case 't':
                threshold = strtol(optarg, NULL, 10);
                if (threshold <= 0) {
                    fprintf(stderr, "Error: Threshold must be greater than 0. Setting to default 2.0.\n");
                    threshold = DEFAULT_THRESHOLD;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s -a <I2C_ADDRESS> -t <THRESHOLD>\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    if (lis3dh_i2c_fd = open(I2C_BUS, O_RDWR)) {
        libgpiod_init();
        configure_lis3dh(address, threshold);

        while (1) {
            read_lis3dh();
            usleep(100000); // 100ms interval
        }
    }

    sigint_handler(SIGINT);
    libgpiod_cleanup();
    return 0;
}

