#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>
#include <errno.h>
#include <pigpio.h>

#define BUFFER_SIZE 5
#define SENSOR_POLL_INTERVAL_MS 10

typedef struct {
    int readings[BUFFER_SIZE];
    int head = 0;
    int tail = 0;
} CircularBuffer;

CircularBuffer buffer;

void init_pigpio() {
    if (piGPIO_init() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(EXIT_FAILURE);
    }
}

void setup_sensors() {
    gpioSetup(4, PI_OUTPUT);
    gpioSetup(17, PI_INPUT);
    gpioSetup(27, PI_INPUT);
    gpioSetup(22, PI_OUTPUT);
}

void read_sensors() {
    int left, center, right;

    left = gpioRead(4);
    center = gpioRead(17);
    right = gpioRead(27);

    if (center == 1) {
        // No line detected, trigger alert
        gpioWrite(22, 1);
        usleep(2000000); // 2 seconds
        gpioWrite(22, 0);
    }
}

void process_sensor_data() {
    int left_reading = gpioRead(4);
    int center_reading = gpioRead(17);
    int right_reading = gpioRead(27);

    // Store sensor readings in circular buffer
    buffer.readings[buffer.head] = left_reading;
    buffer.head = (buffer.head + 1) % BUFFER_SIZE;

    if (buffer.tail == buffer.head) {
        // Buffer is full, overwrite oldest reading
        buffer.tail = (buffer.tail + 1) % BUFFER_SIZE;
    }

    // Check for center sensor "no line" condition
    if (center_reading == 1 && buffer.readings[buffer.tail] == 1) {
        // Trigger alert
        gpioWrite(22, 1);
        usleep(2000000);
        gpioWrite(22, 0);
    }

    // Motor control logic (placeholder)
    // ...
}

int main() {
    init_pigpio();
    setup_sensors();

    while (1) {
        process_sensor_data();
        usleep(SENSOR_POLL_INTERVAL_MS / 1000); // Convert ms to s
    }

    piGPIO_shutdown();
    return 0;
}

