#include <fcntl.h>
#include <errno.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SILICON_LABS_ID 0x40
#define RELAY_GPIO 17
#define MAGNETIC_THRESHOLD 5.0e-3
#define SAMPLE_INTERVAL_MS 100
#define MAGNETIC_EVENTS_FILE "magnetic_events.txt"

#define MAX_ATTEMPTS 50

int i2c_fd;
int relay_state = 0;

void sigint_handler(int signum) {
    piGPIOSetMode(RELAY_GPIO, PI_OUTPUT);
    piGPIOWrite(RELAY_GPIO, 0);
    close(i2c_fd);
    piGPIOSetMode(RELAY_GPIO, PI_INPUT);
    printf("Program terminated by user.\n");
    exit(0);
}

int init_i2c() {
    int file = open("/dev/i2c-1", O_RDWR);
    if (file < 0) {
        perror("open /dev/i2c-1");
        return -1;
    }

    if (ioctl(file, I2C_SLAVE, SILICON_LABS_ID) < 0) {
        perror("ioctl I2C_SLAVE");
        close(file);
        return -1;
    }

    i2c_fd = file;
    return 0;
}

void read_magnetic_field() {
    static unsigned long last_timestamp = 0;
    unsigned long current_timestamp = millis();

    if (current_timestamp - last_timestamp >= SAMPLE_INTERVAL_MS / 1000) {
        last_timestamp = current_timestamp;

        int register_address = 0x40;
        int register_value = 0;

        for (int i = 0; i < MAX_ATTEMPTS; i++) {
            if (readRegister(i2c_fd, register_address, &register_value) == 0) {
                break;
            }
        }

        if (register_value == 0x00000000) {
            printf("Timeout reading from Si7210.\n");
            return;
        }

        double magnetic_field = (double)register_value * 1e-6;

        if (magnetic_field > MAGNETIC_THRESHOLD) {
            relay_state = !relay_state;
            piGPIOWrite(RELAY_GPIO, relay_state);

            char timestamp[32];
            time_t now = time(NULL);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
            FILE *file = fopen(MAGNETIC_EVENTS_FILE, "a");
            if (file) {
                fprintf(file, "%s: Magnetic field exceeded threshold (%f mT), relay state: %d\n", timestamp, magnetic_field, relay_state);
                fclose(file);
            }
        }

        printf("Magnetic field: %.3f mT\n", magnetic_field);
    }
}

int readRegister(int fd, int address, unsigned int *value) {
    unsigned char reg_read[2];
    ssize_t ret = read(fd, reg_read, 2);
    if (ret != 2) {
        perror("readRegister");
        return -1;
    }

    *value = (reg_read[0] << 8) | reg_read[1];
    return 0;
}

int main() {
    if (init_i2c() < 0) {
        return -1;
    }

    piGPIOSetup(RELAY_GPIO, PI_OUTPUT);

    while (1) {
        read_magnetic_field();
        usleep(SAMPLE_INTERVAL_MS / 1000);
    }

    sigint_handler(SIGINT);

    close(i2c_fd);
    piGPIOSetup(RELAY_GPIO, PI_INPUT);
    return 0;
}

