#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <errno.h>
#include <signal.h>
#include <libgpiod/gpio.h>

#define RELAY_GPIO 18
#define LOG_FILE "relay_log.txt"

void sigint_handler(int sig) {
    close(stdout);
    close(stderr);
    close(logfd);
    gpio_set_dir(RELAY_GPIO, GPIO_OUT);
    gpio_set_level(RELAY_GPIO, 0);
    fprintf(logfd, "Received SIGINT, shutting down...\n");
    fprintf(logfd, "Last activation: OFF\n");
    fclose(logfd);
    exit(0);
}

void sigterm_handler(int sig) {
    sigint_handler(sig);
}

int main(int argc, char *argv[]) {
    int logfd, sockfd;
    struct sockaddr_in addr;
    socklen_t addrlen = sizeof(addr);
    char buffer[1024] = {0};
    char command[1024];
    time_t now;

    if (signal(SIGINT, sigint_handler) == SIG_IGN ||
        signal(SIGTERM, sigterm_handler) == SIG_IGN) {
        fprintf(stderr, "Failed to install signal handlers.\n");
        return 1;
    }

    logfd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (logfd == -1) {
        perror("Failed to open relay_log.txt");
        return 1;
    }

    gpio_init();

    addr.sin_family = AF_INET;
    addr.sin_port = htons(5000);
    addr.sin_addr.s_addr = INADDR_ANY;

    if ((sockfd = socket(AF_INET, SOCK_STREAM, 0)) == -1) {
        perror("Failed to create socket");
        return 1;
    }

    if (bind(sockfd, (struct sockaddr *)&addr, sizeof(addr)) == -1) {
        perror("Failed to bind socket");
        return 1;
    }

    if (listen(sockfd, 5) == -1) {
        perror("Failed to listen on socket");
        return 1;
    }

    fprintf(logfd, "Relay server started on port 5000\n");

    while (1) {
        ssize_t recv_len = recv(sockfd, buffer, 1023, 0);
        if (recv_len == -1) {
            perror("Failed to receive data");
            break;
        }
        buffer[recv_len] = '\0';

        if (strcmp(buffer, "ON") == 0 || strcmp(buffer, " off") == 0) {
            strncat(command, buffer, strlen(buffer));
            strncat(command, " ", 1);
            strncat(command, "ON", 3);
            if (gpio_set_level(RELAY_GPIO, 1) == -1) {
                fprintf(stderr, "Failed to set GPIO level\n");
            }
            fprintf(logfd, "Activation: ON\n");
        } else if (strcmp(buffer, "OFF") == 0 || strcmp(buffer, " off") == 0) {
            strncat(command, buffer, strlen(buffer));
            strncat(command, " ", 1);
            strncat(command, "OFF", 4);
            if (gpio_set_level(RELAY_GPIO, 0) == -1) {
                fprintf(stderr, "Failed to set GPIO level\n");
            }
            fprintf(logfd, "Activation: OFF\n");
        } else {
            fprintf(logfd, "Invalid command: %s\n", buffer);
        }

        if (write(logfd, command, strlen(command)) == -1) {
            perror("Failed to write to log file");
            break;
        }
    }

    close(sockfd);
    close(logfd);
    gpio_disable(RELAY_GPIO);
    gpio_set_dir(RELAY_GPIO, GPIO_OUT);
    gpio_set_level(RELAY_GPIO, 0);
    fprintf(logfd, "Shutting down...\n");
    fprintf(logfd, "Last activation: OFF\n");
    fclose(logfd);
    return 0;
}

