#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS 1
#define RELAY_GPIO 18
#define FLOW_LOG "flow_log.txt"
#define CRC_POLYNOMIAL 0x07

#define SENSOR1_ADDR 0x70
#define SENSOR2_ADDR 0x71

int i2c_open(int file) {
    int fd;
    fd = open(file, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }
    return fd;
}

int i2c_write(int fd, uint8_t *buf, size_t len) {
    return write(fd, buf, len);
}

int i2c_read(int fd, uint8_t *buf, size_t len) {
    return read(fd, buf, len);
}

int gpio_init(void) {
    if (piGPIO_init() < 0) {
        perror("Failed to initialize pigpio");
        return -1;
    }
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    return 0;
}

int sensor_read(uint8_t *buf) {
    // Implement CRC-8 check here
    // This is a placeholder for the actual CRC calculation
    uint8_t crc = 0;
    for (int i = 0; i < 3; i++) {
        crc ^= buf[i];
        for (int j = 0; j < 8; j++) {
            if ((crc & 0x01) == 1) {
                crc >>= 1;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc == 0;
}

int main(int argc, char *argv[]) {
    int relay_state = 0;
    int i2c_fd1, i2c_fd2;
    int gpio_rc = gpio_init();
    if (gpio_rc < 0) {
        return EXIT_FAILURE;
    }

    i2c_fd1 = i2c_open(I2C_BUS);
    if (i2c_fd1 < 0) {
        gpio_close(RELAY_GPIO);
        return EXIT_FAILURE;
    }

    i2c_fd2 = i2c_open(I2C_BUS);
    if (i2c_fd2 < 0) {
        gpio_close(RELAY_GPIO);
        close(i2c_fd1);
        return EXIT_FAILURE;
    }

    while (1) {
        uint8_t buf1[3], buf2[3];
        int r1, r2;

        r1 = i2c_read(i2c_fd1, buf1, 3);
        if (r1 < 0) {
            fprintf(stderr, "Failed to read from SENSOR1\n");
            continue;
        }

        r2 = i2c_read(i2c_fd2, buf2, 3);
        if (r2 < 0) {
            fprintf(stderr, "Failed to read from SENSOR2\n");
            continue;
        }

        if (!sensor_read(buf1) || !sensor_read(buf2)) {
            fprintf(stderr, "CRC check failed for SENSOR1 or SENSOR2\n");
            continue;
        }

        if (r1 < 3 || r2 < 3) {
            fprintf(stderr, "Received fewer than 3 bytes from either sensor\n");
            continue;
        }

        // Process flow rates here
        // ...

        // Log flow rates to file
        FILE *fp = fopen(FLOW_LOG, "a");
        if (fp == NULL) {
            perror("Failed to open flow_log.txt");
            continue;
        }
        fprintf(fp, "%llu", (unsigned long long)clock());
        fflush(fp);
        fclose(fp);

        // Control relay based on flow rates
        // ...

        usleep(100000);
    }

    gpio_close(RELAY_GPIO);
    close(i2c_fd1);
    close(i2c_fd2);
    pigpio_terminate(1000);
    printf("Program terminated by user or SIGINT/SIGTERM\n");
    return EXIT_SUCCESS;
}

