#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <syslog.h>
#include <pigpio.h>

#define SENSOR_PIN 17
#define MOTOR_ENA 22
#define MOTOR_IN1 23
#define MOTOR_IN2 24
#define POLL_INTERVAL 200
#define CLOSE_DURATION 5000
#define DRY_CONSEC_COUNT 3

int main(int argc, char *argv[]) {
    pigpio_setup(1); // Initialize pigpio library
    if (pigpio_init() < 0) {
        syslog(LOG_ERR, "Failed to initialize pigpio: %s", pigpio_strerror(pigpio_last_error()));
        exit(EXIT_FAILURE);
    }

    // Configure GPIO pins
    gpioSetMode(MOTOR_ENA, PI_OUTPUT);
    gpioSetMode(MOTOR_IN1, PI_INPUT_PULLUP);
    gpioSetMode(MOTOR_IN2, PI_INPUT_PULLUP);

    // Start logging
