#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define PIR_PIN 7
#define RELAY_PIN 17
#define POLL_INTERVAL_MS 100
#define LED_ON_TIME_SEC 60
#define LOG_FILE "security_log.txt"

void sigint_handler(int sig) {
    pi_stop(); // Stop pigpio
    fprintf(stderr, "Received SIGINT, turning off floodlight and exiting.\n");
    pi_stop();
    exit(0);
}

void sigterm_handler(int sig) {
    pi_stop(); // Stop pigpio
    fprintf(stderr, "Received SIGTERM, turning off floodlight and exiting.\n");
    pi_stop();
    exit(0);
}

int main(int argc, char *argv[]) {
    int pir_state, relay_state;
    time_t now;
    struct tm *time_info;
    FILE *log_file;

    if (signal(SIGINT, sigint_handler) == SIG_IGN ||
        signal(SIGTERM, sigterm_handler) == SIG_IGN) {
        fprintf(stderr, "Failed to install signal handlers.\n");
        return 1;
    }

    if (pi_init() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library.\n");
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file.\n");
        pi_stop();
        return 1;
    }

    while (1) {
        now = time(NULL);
        time_info = localtime(&now);

        if (pi_get_gpio_value(PIR_PIN) == 1) {
            relay_state = pi_gpio_set(RELAY_PIN, 1);
            if (relay_state < 0) {
                fprintf(stderr, "Failed to set relay state.\n");
                pi_stop();
                fclose(log_file);
                return 1;
            }
            fprintf(log_file, "%s", asctime(time_info));
            pi_delay_ms(10000); // Delay for 10ms to avoid race conditions
            pi_gpio_set(RELAY_PIN, 0);
            fprintf(log_file, "\nFloodlight turned off.\n");
            sleep(LED_ON_TIME_SEC * 1000); // Convert seconds to milliseconds
            pi_gpio_set(RELAY_PIN, 0);
            fprintf(log_file, "%s", asctime(time_info));
            pi_delay_ms(10000); // Delay for 10ms to avoid race conditions
        }

        pi_delay_ms(POLL_INTERVAL_MS / 1000); // Convert ms to seconds
    }

    pi_stop();
    fclose(log_file);
    return 0;
}

