int mp121_init(void) {
    int file;
    struct i2c_client *client;
    int result;

    file = open("/dev/i2c-1", O_RDWR);
    if (file == -1) {
        perror("open /dev/i2c-1");
        return -1;
    }

    client = i2c_alloc(file);
    if (!client) {
        close(file);
        perror("i2c_alloc");
        return -1;
    }

    result = i2c_transfer(client, MPR121_ADDRESS, 0x20, 1, NULL, 0);
    if (result < 0) {
        i2c_free(client);
        close(file);
        perror("i2c_transfer");
        return -1;
    }

    i2c_free(client);
    close(file);
    return 0;
}

int mp121_debounce(int electrode) {
    struct timespec start, end;
    int timeout = DEBOUNCE_MS / 1000; // Convert ms to seconds
    int count = 0;

    clock_gettime(CLOCK_REALTIME, &start);

    while (count < timeout) {
        result = libgpiod_get_value(relay_gpio);
        if (result == 0) {
            clock_gettime(CLOCK_REALTIME, &end);
            elapsed = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec);
            if (elapsed >= timeout) {
                return 1;
            }
            count++;
        } else {
            count = 0;
        }
    }

    return 0;
}

int mp121_read_electrode(int electrode) {
    int result;
    struct mp121_config config;

    memset(&config, 0, sizeof(config));
    config.base_filter = MHD;
    config.num_electrodes = 12;
    config.ffi = 1;
    config.sfi = 1;
    config.cdt = 1;
    config.auto_config_range = 1;
    config.num_electrodes_to_enable = 1;

    result = libgpiod_set_config(relay_gpio, &config);
    if (result < 0) {
        perror("libgpiod_set_config");
        return -1;
    }

    result = mp121_read_electrode_data(electrode, &result);
    if (result < 0) {
        perror("mp121_read_electrode_data");
        return -1;
    }

    return result;
}

int mp121_read_electrode_data(int electrode, int *data) {
    int result;
    struct mp121_data data_struct;

    memset(&data_struct, 0, sizeof(data_struct));

    result = libgpiod_read_electrode_data(relay_gpio, electrode, &data_struct);
    if (result < 0) {
        perror("libgpiod_read_electrode_data");
        return -1;
    }

    *data = data_struct.value;
    return 0;
}

