#include <netinet/in.h>
#include <arpa/inet.h>
#include <syslog.h>
#include <time.h>
#include <stdarg.h>
#include <gpiod.h>
#include <pigpio.h>

#define SERVO_PIN 17
#define PIR_PIN 4
#define PORT 5000
#define LOG_FILE "security.log"

void log_event(const char *format, ...) {
    time_t now = time(NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%T", localtime(&now));
    va_list args;
    va_start(args, format);
    vsnprintf(log_message, sizeof(log_message), format, args);
    va_end(args);
    syslog(LOG_USER, "%s - %s", timestamp, log_message);
    write(fileno(LOG_FILE), log_message, strlen(log_message));
    fclose(LOG_FILE);
    log_message[strlen(log_message)++] = '\n';
    write(fileno(LOG_FILE), log_message, strlen(log_message));
    fclose(LOG_FILE);
}

void init_gpio() {
    int servo_gpio = SERVO_PIN;
    int pir_gpio = PIR_PIN;
    int servo_direction = PD_OUTPUT;
    int servo_pulse_width_min = 1;
    int servo_pulse_width_max = 2;
    int servo_pulse_rate = 50;

    if (gpiod_create_led_source(&servo_source, servo_gpio, servo_direction) < 0) {
        log_event("Failed to initialize servo GPIO: %s", gpiod_get_error());
        exit(EXIT_FAILURE);
    }

    if (pigpio_init() < 0) {
        log_event("Failed to initialize pigpio: %s", pigpio_get_error());
        exit(EXIT_FAILURE);
    }

    if (gpioset(servo_gpio, servo_direction) < 0) {
        log_event("Failed to set servo GPIO direction: %s", gpioset_get_error());
        exit(EXIT_FAILURE);
    }

    if (gpioset(pir_gpio, PI_INPUT) < 0) {
        log_event("Failed to set PIR GPIO as input: %s", gpioset_get_error());
        exit(EXIT_FAILURE);
    }
}

void handle_client(int client_socket) {
    char buffer[1024] = {0};
    while (1) {
        int bytes_received = read(client_socket, buffer, 1024);
        if (bytes_received == 0) {
            break;
        }

        if (strcmp(buffer, "PIR") == 0) {
            int pir_state = gpioget(pir_gpio);
            char response[10];
            if (pir_state) {
                sprintf(response, "PIR:1");
            } else {
                sprintf(response, "PIR:0");
            }
            write(client_socket, response, strlen(response));
        } else {
            char command[100];
            sscanf(buffer, "angle%s", command);
            int angle = atoi(command);
            if (angle < 0 || angle > 180) {
                log_event("Invalid angle value: %d", angle);
                write(client_socket, "Invalid angle", strlen("Invalid angle"));
                continue;
            }

            int pulse_width = angle / 90 * 1000 + servo_pulse_width_min;
            if (pulse_width > servo_pulse_width_max) {
                pulse_width = servo_pulse_width_max;
            }

            if (gpiosetpulse(servo_gpio, 0, pulse_width) < 0) {
                log_event("Failed to set servo PWM: %s", gpiosetpulse_get_error());
            }
        }
    }

    close(client_socket);
}

int main() {
    init_gpio();

    int server_socket = socket(AF_INET, SOCK_STREAM, 0);
    if (server_socket < 0) {
        log_event("Failed to create socket: %s", strerror(errno));
        exit(EXIT_FAILURE);
    }

    struct sockaddr_in address;
    address.sin_family = AF_INET;
    address.sin_port = htons(PORT);
    address.sin_addr.s_addr = INADDR_ANY;

    if (bind(server_socket, (struct sockaddr *)&address, sizeof(address)) < 0) {
        log_event("Failed to bind socket: %s", strerror(errno));
        exit(EXIT_FAILURE);
    }

    if (listen(server_socket, 5) < 0) {
        log_event("Failed to listen on socket: %s", strerror(errno));
        exit(EXIT_FAILURE);
    }

    log_event("Server started on port %d", PORT);

    while (1) {
        int client_socket = accept(server_socket, NULL, NULL);
        if (client_socket < 0) {
            log_event("Failed to accept connection: %s", strerror(errno));
            continue;
        }

        if (fork() == 0) {
            handle_client(client_socket);
            exit(0);
        }
    }

    return 0;
}

