#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/wait.h>
#include <pthread.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x1A
#define RELAY_PIN 23
#define LOG_FILE "grow_log.txt"
#define SAMPLE_INTERVAL 2000 // 2 seconds
#define ABSOLUTE_MAX_LUX 150

#define LOG_FORMAT "Timestamp: %s, Lux: %d\n"

// Function to handle I2C communication
int i2c_read_byte(int file, unsigned short address, unsigned char reg) {
    struct i2c_rdwr_ctx ctx;
    ctx.addr = address;
    ctx.flags = I2C_M_READ;
    ctx.buf = &reg;
    ctx.len = sizeof(reg);

    int ret = ioctl(file, I2C_RDWR, &ctx);
    if (ret < 0) {
        perror("I2C read failed");
        return -1;
    }

    return ctx.rbuf[0];
}

// Function to handle the BH1750 sensor reading
int read_lux(int file) {
    unsigned char reg = 0x00;
    int lux;

    do {
        lux = i2c_read_byte(file, I2C_ADDR, reg);
        if (lux < 0) {
            // Handle error: sensor not present or bus error
            perror("I2C read error");
            return -1;
        }
        reg++;
    } while (reg == 0x00);

    // Extract Lux value from the 2-byte result
    lux = (lux << 8) | i2c_read_byte(file, I2C_ADDR, reg);

    return lux;
}

// Function to log the lux value
void log_lux(int lux) {
    char timestamp[64];
    time_t now = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    fprintf(log_file, LOG_FORMAT, timestamp, lux);
    fclose(log_file);
}

// Function to control the relay
void control_relay(int on_off) {
    if (on_off) {
        pigpio_set_mode(RELAY_PIN, PIGPIO_OUTPUT);
        pigpio_write(RELAY_PIN, 1);
    } else {
        pigpio_set_mode(RELAY_PIN, PIGPIO_INPUT);
        pigpio_get_level(RELAY_PIN);
    }
}

int main(int argc, char *argv[]) {
    int i2c_fd, relay_pin;
    int lux;

    // Initialize pigpio for relay control
    relay_pin = 23;
    if (pigpio_init(1) != 0) {
        perror("Failed to initialize pigpio");
        return EXIT_FAILURE;
    }

    // Open I2C bus
    i2c_fd = open("/dev/i2c-1", O_RDWR | O_NOCTTY);
    if (i2c_fd == -1) {
        perror("Failed to open I2C bus");
        pigpio_cleanup();
        return EXIT_FAILURE;
    }

    // Set I2C bus parameters
    if (ioctl(i2c_fd, I2C_SET_ADDRESS, I2C_ADDR) == -1) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        pigpio_cleanup();
        return EXIT_FAILURE;
    }

    // Start a thread to read lux and control the relay
    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, read_lux_thread, (void *)i2c_fd) != 0) {
        perror("Failed to create thread");
        close(i2c_fd);
        pigpio_cleanup();
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        lux = read_lux(i2c_fd);
        if (lux == -1) {
            // Retry on error
            continue;
        }

        log_lux(lux);

        if (lux < ABSOLUTE_MAX_LUX) {
            control_relay(1);
        } else {
            control_relay(0);
        }

        usleep(SAMPLE_INTERVAL * 1000 / 1000); // Convert milliseconds to microseconds
    }

    // Clean up resources
    pthread_join(thread_id, NULL);
    close(i2c_fd);
    pigpio_cleanup();

    return EXIT_SUCCESS;
}

// Thread function to read lux from the sensor
void *read_lux_thread(void *arg) {
    int i2c_fd = *(int *)arg;
    while (1) {
        int lux = read_lux(i2c_fd);
        if (lux == -1) {
            // Retry on error
            continue;
        }
        log_lux(lux);
        control_relay(lux < ABSOLUTE_MAX_LUX);
        usleep(SAMPLE_INTERVAL * 1000 / 1000);
    }
    return NULL;
}

