#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/syslog.h>
#include <arpa/inet.h>
#include <pthread.h>
#include <libgpiod/libgpiod.h>
#include <pigpio.h>

#define RELAY_GPIO 17
#define MQTT_TOPIC "home/lights/control"
#define MQTT_QOS 0
#define MQTT_CLIENT_ID "relay_controller_1"
#define MQTT_CLEAN_SESSION 1
#define MQTT_KEEP_ALIVE_SEC 60
#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883

#define LOG_FACILITY LOG_USER
#define LOG_TAG "mqtt_relay"

void log_message(int priority, const char *format, ...) {
    va_list args;
    va_start(args, format);
    syslog(priority, format, args);
    va_end(args);
}

void mqtt_client_init(void) {
    int ret;
    struct sockaddr_in addr;

    ret = gpioInit();
    if (ret < 0) {
        log_message(LOG_ERR, "Failed to initialize GPIO driver");
        exit(EXIT_FAILURE);
    }

    ret = gpioSetMode(RELAY_GPIO, GPIO_OUTPUT);
    if (ret < 0) {
        log_message(LOG_ERR, "Failed to set GPIO%d as output", RELAY_GPIO);
        exit(EXIT_FAILURE);
    }

    ret = gpioWrite(RELAY_GPIO, 0);
    if (ret < 0) {
        log_message(LOG_ERR, "Failed to set GPIO%d LOW", RELAY_GPIO);
        exit(EXIT_FAILURE);
    }

    ret = pigpioInit(MQTT_KEEP_ALIVE_SEC);
    if (ret < 0) {
        log_message(LOG_ERR, "Failed to initialize pigpio");
        exit(EXIT_FAILURE);
    }

    addr.sin_family = AF_INET;
    addr.sin_port = htons(MQTT_PORT);
    addr.sin_addr.s_addr = inet_addr(MQTT_BROKER);

    ret = piGpioToPigpio(RELAY_GPIO);
    if (ret < 0) {
        log_message(LOG_ERR, "Failed to map GPIO%d to Pigpio", RELAY_GPIO);
        exit(EXIT_FAILURE);
    }

    ret = pigpiod_mqtt_client_new(MQTT_CLIENT_ID, MQTT_QOS, MQTT_CLEAN_SESSION, NULL, NULL);
    if (ret < 0) {
        log_message(LOG_ERR, "Failed to create MQTT client");
        exit(EXIT_FAILURE);
    }

    ret = pigpiod_mqtt_client_connect(pigpiod_mqtt_client_new(), MQTT_BROKER, MQTT_PORT, 0, NULL);
    if (ret < 0) {
        log_message(LOG_ERR, "Failed to connect to MQTT broker");
        exit(EXIT_FAILURE);
    }

    log_message(LOG_INFO, "MQTT client connected");
}

void mqtt_client_loop(void *arg) {
    char msg[256];
    int msg_len, ret;

    while (1) {
        ret = pigpiod_mqtt_client_recv(pigpiod_mqtt_client_new(), msg, sizeof(msg));
        if (ret < 0) {
            log_message(LOG_ERR, "MQTT client received error: %s", pigpiod_strerror(ret));
            usleep(5000000); // Wait for 5 seconds before reconnecting
            continue;
        }

        if (ret == -1) {
            log_message(LOG_ERR, "MQTT client disconnection");
            pigpiod_mqtt_client_disconnect(pigpiod_mqtt_client_new());
            continue;
        }

        if (msg[0] == '\0') {
            log_message(LOG_INFO, "Received empty payload");
            continue;
        }

        if (strcmp(msg, "ON") == 0) {
            log_message(LOG_INFO, "Received command: ON, setting relay HIGH");
            gpioWrite(RELAY_GPIO, 1);
        } else if (strcmp(msg, "OFF") == 0) {
            log_message(LOG_INFO, "Received command: OFF, setting relay LOW");
            gpioWrite(RELAY_GPIO, 0);
        } else {
            log_message(LOG_ERR, "Received invalid payload: %s", msg);
        }
    }
}

void signal_handler(int signum) {
    log_message(LOG_INFO, "Received signal %d, stopping MQTT client and exiting", signum);
    pigpiod_mqtt_client_disconnect(pigpiod_mqtt_client_new());
    gpioWrite(RELAY_GPIO, 0);
    pigpioExit();
    exit(signum == SIGINT || signum == SIGTERM ? 0 : EXIT_FAILURE);
}

int main(int argc, char *argv[]) {
    pthread_t thread;

    if (pthread_mutex_init(&mutex, NULL) != 0) {
        log_message(LOG_ERR, "Failed to initialize mutex");
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, signal_handler) == SIG_IGN || signal(SIGTERM, signal_handler) == SIG_IGN) {
        log_message(LOG_ERR, "Failed to set signal handler for SIGINT and SIGTERM");
        return EXIT_FAILURE;
    }

    if (pthread_create(&thread, NULL, mqtt_client_loop, NULL) != 0) {
        log_message(LOG_ERR, "Failed to create MQTT client thread");
        return EXIT_FAILURE;
    }

    log_message(LOG_INFO, "MQTT client started");

    while (1) {
        usleep(1000000); // Sleep for 1 second
    }

    pthread_join(thread, NULL);
    log_message(LOG_INFO, "MQTT client thread joined");

    pigpioExit();
    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);

    log_message(LOG_INFO, "Exiting");
    return 0;
}

