#define TARGET_PULSE_WIDTHS {1000, 1500, 2000, 500, 2500}

int main() {
    int ret;
    pigpio_init(5); // Initialize pigpio library

    if (pigpio_init(5) != 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_SERVOS; i++) {
        ret = pigpio_set_servo_pulsewidth(SERVO_PINS[i], TARGET_PULSE_WIDTHS[i]);
        if (ret == -1) {
            fprintf(stderr, "Failed to set servo pulse width for pin %d: %s\n", SERVO_PINS[i], strerror(errno));
            return EXIT_FAILURE;
        }
    }

    // Generate PWM signal for 3 seconds
    sleep(3);

    // Stop PWM and release resources
    for (int i = 0; i < NUM_SERVOS; i++) {
        pigpio_set_servo_pulsewidth(SERVO_PINS[i], 0);
    }

    pigpio_cleanup(); // Release all resources

    return EXIT_SUCCESS;
}

