#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define RELAY_PIN 17
#define LOG_FILE "chicken_coop_log.txt"
#define DUSK_THRESHOLD 50
#define DAWN_THRESHOLD 200
#define RELAY_OFF 0
#define RELAY_ON 1
#define POLL_INTERVAL 5000
#define RELAY_WAIT_MS 180

int i2c_fd;
int gpio_fd;

void init_i2c();
void init_gpio();
void setup_log_file();
void log_entry(const char *entry);
void handle_sensor_data(int lux);
void handle_relay_state(int state);
void dusk_activation();
void dawn_deactivation();
void handle_error(const char *msg);

int main(int argc, char *argv[]) {
    int ret;
    pid_t pid;

    setup_log_file();

    init_i2c();
    init_gpio();

    while (1) {
        ret = read_sensor_data();
        if (ret < 0) {
            handle_error("Failed to read from BH1750 sensor");
            continue;
        }
        handle_sensor_data(ret);

        ret = gpio_set_high(RELAY_PIN);
        if (ret < 0) {
            handle_error("Failed to set GPIO pin");
            continue;
        }

        usleep(RELAY_WAIT_MS);

        ret = gpio_get_level(RELAY_PIN);
        if (ret == 1) {
            handle_relay_state(RELAY_ON);
        } else {
            handle_relay_state(RELAY_OFF);
        }

        dusk_activation();
        dawn_deactivation();

        usleep(POLL_INTERVAL * 1000 / 1000);
    }

    close(i2c_fd);
    close(gpio_fd);
    remove(LOG_FILE);
    exit(0);
}

void init_i2c() {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open i2c bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

void init_gpio() {
    gpio_fd = pigpio_open(0);
    if (!gpio_fd) {
        perror("Failed to open pigpio");
        exit(EXIT_FAILURE);
    }
}

void setup_log_file() {
    LOG_FILE = "/tmp/chicken_coop_log.txt";
    open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
}

void log_entry(const char *entry) {
    if (write(gpio_fd, entry, strlen(entry)) < 0) {
        handle_error("Failed to write to log file");
    }
}

void handle_sensor_data(int lux) {
    log_entry(f"YYYY-MM-DD HH:MM:SS: Lux = %d, Relay = %d\n", get_date_time(), (lux < DUSK_THRESHOLD) ? RELAY_OFF : RELAY_ON);
}

void handle_relay_state(int state) {
    log_entry(f"YYYY-MM-DD HH:MM:SS: Relay = %d\n", state);
}

void dusk_activation() {
    log_entry("Dusk activation\n");
    gpio_set_high(RELAY_PIN);
}

void dawn_deactivation() {
    log_entry("Dawn deactivation\n");
    gpio_set_low(RELAY_PIN);
}

void handle_error(const char *msg) {
    fprintf(stderr, "Error: %s\n", msg);
    log_entry(f"YYYY-MM-DD HH:MM:SS: Error - %s\n", get_date_time(), msg);
}

int read_sensor_data() {
    uint8_t buffer[6];
    int ret = read(i2c_fd, buffer, 6);
    if (ret != 6) {
        return -1;
    }

    // BH1750 sensor data format: [Signature, R, G, B, Reserved, Lux]
    if (buffer[0] != 0x23) {
        return -1;
    }

    int lux = buffer[5];
    return lux;
}

int main(int argc, char *argv[]) {
    // ... (rest of the main function as shown above)
}

