#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define SENSOR_PIN 7
#define RELAY_PIN 11
#define DEBOUNCE_DELAY 50
#define LOG_INTERVAL 10

void log_event(const char *event) {
    time_t now = time(NULL);
    char timestamp[80];
    sprintf(timestamp, "%s", ctime(&now));
    fprintf(stderr, "%s: %s\n", timestamp, event);
}

int main() {
    if (piGPIOInit() < 0) {
        perror("Failed to initialize pigpio");
        exit(EXIT_FAILURE);
    }

    gpioSetup(RELAY_PIN, PI_OUTPUT);
    gpioSetup(SENSOR_PIN, PI_INPUT, 10000); // 10k pull-up

    char relay_state = 0;
    char last_sensor_state = 0;

    while (1) {
        int sensor_state = gpioRead(SENSOR_PIN);

        if (sensor_state != last_sensor_state) {
            last_sensor_state = sensor_state;

            if (sensor_state == PI_HIGH) {
                // Start debouncing
                int debounced = 0;
                for (int i = 0; i < DEBOUNCE_DELAY; i++) {
                    usleep(100000); // 100ms delay
                    if (gpioRead(SENSOR_PIN) == PI_HIGH) {
                        debounced++;
                    } else {
                        debounced = 0;
                    }
                    if (debounced == DEBOUNCE_DELAY) {
                        break;
                    }
                }

                if (debounced == DEBOUNCE_DELAY) {
                    relay_state = !relay_state;
                    log_event("Relay toggled");
                }
            }
        }

        // Sleep before next iteration
        usleep(LOG_INTERVAL * 1000000); // 1000ms sleep
    }

    gpioDisable(RELAY_PIN);
    piGPIOExit();

    return 0;
}

