                int debounced = 0;
                for (int i = 0; i < DEBOUNCE_DELAY; i++) {
                    usleep(100000); // 100ms delay
                    if (gpioRead(SENSOR_PIN) == PI_HIGH) {
                        debounced++;
                    } else {
                        debounced = 0;
                    }
                    if (debounced == DEBOUNCE_DELAY) {
                        break;
                    }
                }

                if (debounced == DEBOUNCE_DELAY) {
                    relay_state = !relay_state;
                    log_event("Relay toggled");
                }
            }
        }

        // Sleep before next iteration
        usleep(LOG_INTERVAL * 1000000); // 1000ms sleep
    }

    gpioDisable(RELAY_PIN);
    piGPIOExit();

    return 0;
}
