#define LPM_THRESHOLD_LOW 4.5
#define HYSTERESIS 0.5

typedef struct {
    pthread_mutex_t mutex;
    long long pulse_count;
    long long last_timestamp;
} flow_data;

flow_data flow_data_struct;

void flow_isr(void *arg) {
    static int debounced = 0;
    static unsigned long last_debounce_time = 0;

    unsigned long current_time = gpiod_get_last_value(FLOW_SENSOR_PIN);
    if (current_time != last_debounce_time) {
        last_debounce_time = current_time;
        debounced = 0;
    }
    if (++debounced > 10) {
        gpiod_set_value(FLOW_SENSOR_PIN, 0);
        flow_data_struct.pulse_count = 0;
        flow_data_struct.last_timestamp = current_time;
    }
}

void log_event(const char *event, const char *timestamp) {
    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        perror("Failed to open log file");
        return;
    }
    fprintf(file, "%s %s\n", timestamp, event);
    fclose(file);
}

void solenoid_control(int state) {
    if (state == 0) {
        gpioport_set_dir(SOLENOID_PIN, GPIO_OUTPUT);
    } else {
        gpioport_set_dir(SOLENOID_PIN, GPIO_INPUT);
        gpioport_get_value(SOLENOID_PIN);
    }
}

void *monitor_flow(void *arg) {
    while (1) {
        gpiod_set_callback(FLOW_SENSOR_PIN, flow_isr, NULL);
        sleep(1);

        long long current_time = gpiod_get_last_value(FLOW_SENSOR_PIN);
        flow_data_struct.pulse_count += current_time - flow_data_struct.last_timestamp;
        flow_data_struct.last_timestamp = current_time;

        pthread_mutex_lock(&flow_data_struct.mutex);
        long long lpm = flow_data_struct.pulse_count / 1000000;
        log_event("LPM: ", __date " ");
        log_event("%ld", lpm);
        pthread_mutex_unlock(&flow_data_struct.mutex);

        if (lpm > LPM_THRESHOLD_HIGH) {
            solenoid_control(0);
        } else if (lpm < LPM_THRESHOLD_LOW - HYSTERESIS) {
            solenoid_control(1);
        }

        if (gpioport_get_value(SOLENOID_PIN) == 0) {
            log_event("Solenoid opened\n", __date " ");
        } else {
            log_event("Solenoid closed\n", __date " ");
        }
    }
    return NULL;
}

