        return EXIT_FAILURE;
    }

    if (gpio_direction_output(FLOW_SENSOR_PIN) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", FLOW_SENSOR_PIN);
        close(fd);
        pthread_mutex_destroy(flow_data_struct.mutex);
        return EXIT_FAILURE;
    }

    if (gpio_set_level(FLOW_SENSOR_PIN, 1) != 0) {
        fprintf(stderr, "Failed to set GPIO %d to input\n", FLOW_SENSOR_PIN);
        close(fd);
        pthread_mutex_destroy(flow_data_struct.mutex);
        return EXIT_FAILURE;
    }

    if (gpio_set_callback(FLOW_SENSOR_PIN, flow_isr, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR callback for GPIO %d\n", FLOW_SENSOR_PIN);
        close(fd);
        pthread_mutex_destroy(flow_data_struct.mutex);
        return EXIT_FAILURE;
    }

    if (gpio_set_dir(SOLENOID_PIN, GPIO_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", SOLENOID_PIN);
        close(fd);
        pthread_mutex_destroy(flow_data_struct.mutex);
        return EXIT_FAILURE;
    }

    if (gpio_set_level(SOLENOID_PIN, 1) != 0) {
        fprintf(stderr, "Failed to set GPIO %d to input\n", SOLENOID_PIN);
        close(fd);
        pthread_mutex_destroy(flow_data_struct.mutex);
        return EXIT_FAILURE;
    }

    if (libgpiod_cleanup() != 0) {
        fprintf(stderr, "Failed to clean up libgpiod\n");
        close(fd);
        pthread_mutex_destroy(flow_data_struct.mutex);
        return EXIT_FAILURE;
    }

    if (gpio_cleanup() != 0) {
        fprintf(stderr, "Failed to clean up GPIO\n");
        close(fd);
        pthread_mutex_destroy(flow_data_struct.mutex);
        return EXIT_FAILURE;
    }

    pthread_mutex_destroy(flow_data_struct.mutex);

    return monitor_flow(NULL);
}

