#include <linux/gpio.h>
#include <errno.h>

#define GPIO_TTP 4
#define GPIO_RELAY 17
#define DEFAULT_DEBOUNCE 50000

int ttp_fd;
int relay_fd;
long debounce_ms;

void signal_handler(int signum) {
    printf("Received signal, turning off relay and exiting.\n");
    gpio_set_dir(relay_fd, GPIO_OUT);
    gpio_write(relay_fd, 0);
    exit(0);
}

void setup_gpio(int ttp_pin, int relay_pin, long debounce_ms) {
    ttp_fd = open("/dev/gpioctl", O_RDWR);
    if (ttp_fd < 0) {
        perror("Failed to open /dev/gpioctl");
        exit(EXIT_FAILURE);
    }

    relay_fd = open("/dev/gpioout", O_WRONLY | O_CREAT | OCF_FOP_XOPEN_SHLOCK, 0666);
    if (relay_fd < 0) {
        perror("Failed to open /dev/gpioout");
        close(ttp_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(ttp_fd, GPIOPOLL, &debounce_ms) < 0) {
        perror("Failed to set debounce time");
        close(relay_fd);
        close(ttp_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(relay_fd, GPIOPOLL, 0) < 0) {
        perror("Failed to set relay polling mode");
        close(relay_fd);
        close(ttp_fd);
        exit(EXIT_FAILURE);
    }
}

void toggle_relay() {
    long state;
    do {
        sleep(1); // Polling loop with 1ms interval
        state = gpio_get_level(relay_fd);
        gpio_set_level(relay_fd, !state);
    } while (state);
}

int main(int argc, char *argv[]) {
    int opt;
