#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/epoll.h>
#include <linux/gpio.h>
#include <linux/ppi.h>

#define GPIO_PIN 17
#define DEBOUNCE_WINDOW 2000
#define LOG_FILE "motor_rpm.log"
#define LOG_INTERVAL 5000

#define ERR_MSG "Error: %s\n"

void handle_signal(int signum) {
    printf("Received signal %d, stopping...\n", signum);
    close(GPIO_PIN);
    close(logfd);
    exit(EXIT_SUCCESS);
}

int main(int argc, char *argv[]) {
    int logfd;
    struct epoll_event ev, event;
    struct timespec ts;
    int ret;
    long rpm;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    logfd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (logfd == -1) {
        perror(ERR_MSG);
        exit(EXIT_FAILURE);
    }

    event.events = EPOLLIN;
    event.data.fd = logfd;

    if (epoll_ctl(epoll_create1(), EPOLLIN, logfd, &event) == -1) {
        perror(ERR_MSG);
        exit(EXIT_FAILURE);
    }

    ret = gpio_request(GPIO_PIN, "motor_rpm_sensor");
    if (ret < 0) {
        perror(ERR_MSG);
        exit(EXIT_FAILURE);
    }

    gpio_direction_input(GPIO_PIN);
    gpio_set_pull(GPIO_PIN, GPIO_PULLUP);

    while (1) {
        ts.tv_sec = 0;
        ts.tv_nsec = 0;
        clock_gettime(CLOCK_MONOTONIC, &ts);

        ret = gpio_get_value(GPIO_PIN);
        if (ret < 0) {
            perror(ERR_MSG);
            break;
        }

        if (ret == 1) {
            // Rising edge detected, start debounce timer
            gpio_edge_detect(GPIO_PIN);
            ts.tv_sec = 0;
            ts.tv_nsec = 0;
            clock_gettime(CLOCK_MONOTONIC, &ts);
            while (ts.tv_sec < DEBOUNCE_WINDOW / 1000) {
                ts.tv_sec += 1;
                ts.tv_nsec = 0;
                clock_gettime(CLOCK_MONOTONIC, &ts);
            }
            gpio_edge_dedetect(GPIO_PIN);
        }

        if (ret == 0) {
            // Falling edge detected, count pulse
            gpio_edge_detect(GPIO_PIN);
            ts.tv_sec = 0;
            ts.tv_nsec = 0;
            clock_gettime(CLOCK_MONOTONIC, &ts);
            while (ts.tv_sec < LOG_INTERVAL / 1000) {
                ts.tv_sec += 1;
                ts.tv_nsec = 0;
                clock_gettime(CLOCK_MONOTONIC, &ts);
            }
            gpio_edge_dedetect(GPIO_PIN);
        }

        rpm = (long)(ts.tv_sec * 1000000 + ts.tv_nsec / 1000000);
        rpm /= 2; // Assuming two pulses per revolution

        printf("Current RPM: %.2f\n", rpm);
        fputs(to_string(ts.tv_sec, 10) "\t" to_string(rpm, 2) "\n", logfd);

        usleep(LOG_INTERVAL / 1000);
    }

    close(GPIO_PIN);
    close(logfd);
    epoll_ctl(epoll_create1(), EPOLL_CTL_DEL, logfd, NULL);
    close(epoll_create1());

    return 0;
}

static char *to_string(long n, int len) {
    char *s = malloc(len);
    sprintf(s, "%d", n);
    return s;
}

