#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <stdbool.h>
#include <libgpiod/gpio.h>

#define RELAY_GPIO 17
#define TOUCH_GPIO 4
#define POLL_INTERVAL_MS 50
#define CONTINUOUS_TIMEOUT_SEC 10

bool continuous_touch = false;
bool signal_handler_set = false;

void signal_handler(int signum) {
    global_signal_handler_set = true;
}

void setup_gpio(void) {
    int ret;

    ret = gpio_init();
    if (ret < 0) {
        fprintf(stderr, "Failed to initialize GPIO: %s\n", gpio_strerror());
        exit(EXIT_FAILURE);
    }

    gpio_set_mode(TOUCH_GPIO, GPIO_OUTPUT);
    gpio_set_drive(TOUCH_GPIO, 0);

    gpio_set_mode(RELAY_GPIO, GPIO_OUTPUT);
    gpio_set_drive(RELAY_GPIO, 1);

    ret = gpio_request(RELAY_GPIO, "relay_gpio");
    if (ret < 0) {
        fprintf(stderr, "Failed to request relay GPIO: %s\n", gpio_strerror());
        exit(EXIT_FAILURE);
    }
}

void loop_with_signal_handling(void) {
    while (!signal_handler_set) {
        sleep(1 / POLL_INTERVAL_MS);

        gpio_set_value(RELAY_GPIO, gpio_get_value(RELAY_GPIO) ^ 1);

        int touch_state = gpio_get_value(TOUCH_GPIO);
        if (touch_state == GPIO_INPUT_HIGH) {
            if (!continuous_touch) {
                gpio_set_value(RELAY_GPIO, GPIO_OUTPUT);
                continuous_touch = true;
                printf("Touch detected, toggling relay.\n");
            }
        } else {
            continuous_touch = false;
            gpio_set_value(RELAY_GPIO, gpio_get_value(RELAY_GPIO) ^ 1);
        }

        if (continuous_touch && !global_signal_handler_set) {
            gpio_set_value(RELAY_GPIO, 0);
            printf("Continuous touch detected, toggling relay OFF.\n");
        }
    }
}

int main(int argc, char *argv[]) {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    setup_gpio();

    volatile bool global_signal_handler_set = false;

    loop_with_signal_handling();

    gpio_free(RELAY_GPIO);
    gpio_disable(RELAY_GPIO);

    return 0;
}

