#define KP 1.0

void signal_handler(int signum) {
    close(GPIO_FLOW);
    gpioOutput(GPIO_VALVE, 0);
    gpioOutput(GPIO_ENABLE, 0);
    fprintf(stderr, "Shutting down...\n");
    exit(0);
}

void setup_gpio(void) {
    if (libgpiod_init() < 0) {
        fprintf(stderr, "Failed to initialize libgpiod\n");
        exit(EXIT_FAILURE);
    }

    if (gpioMode(GPIO_VALVE, GPIO_MODE_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_VALVE);
        libgpiod_cleanup();
        exit(EXIT_FAILURE);
    }

    if (gpioMode(GPIO_ENABLE, GPIO_MODE_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_ENABLE);
        libgpiod_cleanup();
        exit(EXIT_FAILURE);
    }

    if (gpioMode(GPIO_FLOW, GPIO_MODE_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", GPIO_FLOW);
        libgpiod_cleanup();
        exit(EXIT_FAILURE);
    }

    gpioSetMode(GPIO_VALVE, GPIO_MODE_OUTPUT);
    gpioSetMode(GPIO_ENABLE, GPIO_MODE_OUTPUT);
    gpioSetMode(GPIO_FLOW, GPIO_MODE_INPUT);

    if (gpioInstallInterrupt(GPIO_FLOW, PIGPIO_INT_RISING, flow_isr, NULL) < 0) {
        fprintf(stderr, "Failed to install interrupt handler for GPIO %d\n", GPIO_FLOW);
        libgpiod_cleanup();
        exit(EXIT_FAILURE);
    }
}

void flow_isr(void *arg) {
    static int count = 0;
    unsigned int flow_rate = gpioRead(GPIO_FLOW);

    if (flow_rate) {
        count++;
        if (count >= 100) {
            count = 0;
            float flow_rate_lpermin = (float)flow_rate * 60.0 / 1000.0;
            float duty_cycle = KP * (target_flow_rate - flow_rate_lpermin);
            duty_cycle = fmin(fmax(duty_cycle, 0.0), 255.0);
            gpioWrite(GPIO_VALVE, duty_cycle);
        }
    }
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <target_flow_rate>L/min\n", argv[0]);
        return EXIT_FAILURE;
    }

    double target_flow_rate = strtod(argv[1], NULL);
    if (target_flow_rate <= 0.0) {
        fprintf(stderr, "Invalid target flow rate: %f %s/min\n", target_flow_rate, FLOW_UNIT);
        return EXIT_FAILURE;
    }

    setup_gpio();

    open(FLOW_LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (flow_log_file == -1) {
        fprintf(stderr, "Failed to open flow log file\n");
        libgpiod_cleanup();
        close(GPIO_FLOW);
        gpioOutput(GPIO_VALVE, 0);
        gpioOutput(GPIO_ENABLE, 0);
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        sleep(1);
    }

    close(flow_log_file);
    libgpiod_cleanup();
    gpioOutput(GPIO_VALVE, 0);
    gpioOutput(GPIO_ENABLE, 0);
    fclose(flow_log_file);
    return 0;
}

