#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/epoll.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>
#include <errno.h>

#define RFID_SPI_CHANNEL 0
#define RFID_SPI_SPEED 100000
#define RFID_BUTTON_GPIO 22
#define LOCK_1_GPIO 17
#define LOCK_2_GPIO 27
#define LOG_FILE "/var/log/door_access.log"
#define TAG_LENGTH 10
#define TAG_VALUE "01234567890123456789"

void log_access(const char *event) {
    time_t now = time(NULL);
    struct tm *timeinfo = localtime(&now);
    char time_str[80];
    sprintf(time_str, "%04d-%02d-%02d %02d:%02d:%02d",
            timeinfo->tm_year + 1900, timeinfo->tm_mon + 1, timeinfo->tm_mday,
            timeinfo->tm_hour, timeinfo->tm_min, timeinfo->tm_sec);
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file.\n");
        exit(EXIT_FAILURE);
    }
    fprintf(log_file, "%s %s\n", ctime_r(timeinfo, time_str), event);
    fclose(log_file);
}

int main(int argc, char *argv[]) {
    int rfid_fd, lock_1_gpio, lock_2_gpio, button_gpio;
    struct spidev_dev *dev;
    pi_setup();

    rfid_fd = spidev_open(0, 0);
    if (rfid_fd < 0) {
        perror("Failed to open SPI device");
        return EXIT_FAILURE;
    }

    lock_1_gpio = GPIO_SET_MODE(LOCK_1_GPIO, GPIO_OUTPUT);
    lock_2_gpio = GPIO_SET_MODE(LOCK_2_GPIO, GPIO_OUTPUT);
    button_gpio = GPIO_SET_MODE(RFID_BUTTON_GPIO, GPIO_INPUT, GPIO_PULL_UP);

    if (lock_1_gpio < 0 || lock_2_gpio < 0 || button_gpio < 0) {
        perror("Failed to set GPIO modes");
        return EXIT_FAILURE;
    }

    epoll_event event;
    event.events = EPOLLIN;
    event.data.fd = rfid_fd;

    int epfd = epoll_create1(0);
    if (epfd < 0) {
        perror("Failed to create epoll instance");
        return EXIT_FAILURE;
    }

    if (epoll_ctl(epfd, EPOLL_INSERT, rfid_fd, &event) < 0) {
        perror("Failed to add RFID reader to epoll");
        return EXIT_FAILURE;
    }

    char tag[TAG_LENGTH + 1];
    while (1) {
        struct timespec timeout;
        timeout.tv_sec = 5;
        timeout.tv_nsec = 0;

        int ret = epoll_wait(epfd, &event, timeout);
        if (ret == -1) {
            perror("epoll_wait");
            return EXIT_FAILURE;
        }

        if (event.data.fd == rfid_fd && event.events & EPOLLIN) {
            if (call_spi_read(rfid_spi_channel, tag, TAG_LENGTH) == TAG_LENGTH) {
                if (memcmp(tag, TAG_VALUE, TAG_LENGTH) == 0) {
                    log_access("RFID read successful");
                    if (GPIO_READ(button_gpio) == 0) {
                        log_access("Button pressed");
                        GPIO_WRITE(lock_1_gpio, 0);
                        GPIO_WRITE(lock_2_gpio, 0);
                        usleep(5000000); // 5 seconds
                        GPIO_WRITE(lock_1_gpio, 1);
                        GPIO_WRITE(lock_2_gpio, 1);
                        log_access("Locks re-engaged");
                    } else {
                        log_access("Invalid button press");
                    }
                } else {
                    log_access("No tag present");
                }
            } else {
                log_access("RFID read failed");
            }
        }
    }

    pi_cleanup();
    close(rfid_fd);
    close(lock_1_gpio);
    close(lock_2_gpio);
    close(button_gpio);

    log_access("Exiting...");
    fclose(log_file);

    return 0;
}

int call_spi_read(int channel, char *buffer, int length) {
    int ret;
    ret = spidev_xfer(dev, &channel, buffer, length, NULL);
    if (ret < 0) {
        perror("SPI transfer failed");
        return -1;
    }
    return ret == length;
}

