#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS 1
#define RELAY_GPIO 17
#define TOUCH_STATUS_INTERVAL 50
#define RELAY_LOG_FILE "relay_log.txt"

#define MPR121_ADDRESS 0x50
#define MPR121_CONFIG_REG 0x00
#define MPR121_FILTER_REG 0x01
#define MPR121_TOUCH_THRESH_REG 0x02
#define MPR121_RELEASE_THRESH_REG 0x03
#define MPR121_RUN_MODE_REG 0x04
#define MPR121_STATUS_REG 0x05

int mpr121_init(void);
void mpr121_config(void);
int mpr121_read_status(void *);
void update_relay_state(int status);
void log_to_file(const char *message);

int main(int argc, char *argv[]) {
    int mpr121_fd, relay_fd;
    struct i2c_client *client;
    int status;
    char log_message[100];

    if (argc != 2) {
        fprintf(stderr, "Usage: %s <signal>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    if (signal(SIGINT, signal_handler) == SIG_IGN) {
        fprintf(stderr, "Failed to set SIGINT handler.\n");
        exit(EXIT_FAILURE);
    }

    mpr121_fd = open(RELAY_LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (mpr121_fd == -1) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    client = i2c_open(I2C_BUS, 0x50);
    if (client == NULL) {
        perror("i2c_open");
        close(mpr121_fd);
        exit(EXIT_FAILURE);
    }

    if (mpr121_init() < 0) {
        i2c_close(client);
        close(mpr121_fd);
        exit(EXIT_FAILURE);
    }

    pigpio_init(1);

    while (1) {
        int status[12];
        mpr121_read_status(status);

        for (int i = 0; i < 12; i++) {
            if (status[i] & (1 << i)) {
                update_relay_state(1);
            } else {
                update_relay_state(0);
            }
        }

        log_to_file("Relay state: %d\n", update_relay_state(0));
        usleep(TOUCH_STATUS_INTERVAL * 1000 / 1000);
    }

    close(client);
    i2c_close(client);
    pigpio_terminate(1);
    close(mpr121_fd);

    return 0;

signal_handler:
    printf("Received SIGINT, shutting down...\n");
    update_relay_state(0);
    close(client);
    i2c_close(client);
    pigpio_terminate(1);
    close(mpr121_fd);
    exit(0);
}

int mpr121_init(void) {
    int ret;
    ret = ioctl(mpr121_fd, I2C_SLAVE, MPR121_ADDRESS);
    if (ret < 0) {
        perror("I2C_SLAVE");
        return -1;
    }

    ret = ioctl(mpr121_fd, I2C_MEM_WRITE, MPR121_ADDRESS | MPR121_CONFIG_REG);
    if (ret < 0) {
        perror("I2C_MEM_WRITE");
        return -1;
    }

    ret = ioctl(mpr121_fd, I2C_MEM_WRITE, MPR121_ADDRESS | MPR121_CONFIG_REG | 0x00);
    if (ret < 0) {
        perror("I2C_MEM_WRITE");
        return -1;
    }

    ret = ioctl(mpr121_fd, I2C_MEM_WRITE, MPR121_ADDRESS | MPR121_FILTER_REG);
    if (ret < 0) {
        perror("I2C_MEM_WRITE");
        return -1;
    }

    ret = ioctl(mpr121_fd, I2C_MEM_WRITE, MPR121_ADDRESS | MPR121_FILTER_REG | 0x00);
    if (ret < 0) {
        perror("I2C_MEM_WRITE");
        return -1;
    }

    ret = ioctl(mpr121_fd, I2C_MEM_WRITE, MPR121_ADDRESS | MPR121_TOUCH_THRESH_REG);
