        perror("libgpiod_gpio_mode_set");
        exit(EXIT_FAILURE);
    }
    if (libgpiod_gpio_mode_set(GPIO_18, LGI_MODE_OUTPUT) != 0) {
        perror("libgpiod_gpio_mode_set");
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (1) {
        // Activate Valve 1
        lgi_gpio_output_set(GPIO_17, 1);
