        fprintf(logfd, "Valve 1 activated at %s\n", ts);

        // Deactivate Valve 1
        lgi_gpio_output_set(GPIO_17, 0);
        usleep(PAUSE_TIME * 1000000000 / 1000); // Convert seconds to nanoseconds

        // Activate Valve 2
        lgi_gpio_output_set(GPIO_18, 1);
        usleep(VALVE_2_DURATION * 1000 / 1000);

        // Log activation event
        timespec_to_iso8601(timers[1].timerspec, &reqs[1]);
        char ts2[64];
        sprintf(ts2, "%sT%ldZ", "2000-01-01T00:00:00Z", (long)reqs[1].tv_sec);
        fprintf(logfd, "Valve 2 activated at %s\n", ts2);

        // Deactivate Valve 2
        lgi_gpio_output_set(GPIO_18, 0);
        usleep(PAUSE_TIME2 * 1000000000 / 1000); // Convert seconds to nanoseconds

        // Wait for next cycle
        timers[0].timerspec.tv_sec += VALVE_1_DURATION * 1000000 / 1000;
        timers[1].timerspec.tv_sec += VALVE_2_DURATION * 1000000 / 1000 + PAUSE_TIME * 1000000 / 1000;
        libgpiod_timer_update(timers, 2);
    }

    // Clean up
    lgi_gpio_output_set(GPIO_17, 0);
    lgi_gpio_output_set(GPIO_18, 0);
    libgpiod_timer_destroy(timers);
    libgpiod_exit();
    close(logfd);

    return 0;
