#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/wait.h>
#include <errno.h>
#include <signal.h>

#define I2C_BUS 1
#define SDA_PIN 2
#define SCL_PIN 3
#define RELAY_PIN 17

#define TOUCH_STABILIZATION_DELAY 100000  // 100ms

int i2c_fd;

void i2c_init() {
    int file = open("/dev/i2c-1", O_RDWR);
    if (file == -1) {
        perror("open /dev/i2c-1");
        exit(EXIT_FAILURE);
    }

    if (ioctl(file, I2C_SLAVE, 0x20) == -1) {
        perror("ioctl I2C_SLAVE");
        close(file);
        exit(EXIT_FAILURE);
    }

    i2c_fd = file;
}

void i2c_close() {
    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

void relay_toggle() {
    if (write(RELAY_PIN, 1) == -1) {
        perror("write to relay pin");
    } else if (write(RELAY_PIN, 0) == -1) {
        perror("write to reset relay pin");
    }
}

void configure_mpr121() {
    uint8_t config[6];

    // Initialize MPR121 in stop mode
    config[0] = 0x3F; // Configuration register 0
    config[1] = 0x00; // Configuration register 1
    config[2] = 0x00; // Configuration register 2
    config[3] = 0x00; // Configuration register 3
    config[4] = 0x00; // Configuration register 4
    config[5] = 0x00; // Configuration register 5

    if (write(i2c_fd, config, 6) != 6) {
        perror("write to MPR121 configuration registers");
        exit(EXIT_FAILURE);
    }

    // Set touch and release thresholds
    config[0] = 0x00; // Threshold register 0
    config[1] = 0x00; // Threshold register 1
    config[2] = 0x00; // Threshold register 2
    config[3] = 0x00; // Threshold register 3
    config[4] = 0x00; // Threshold register 4
    config[5] = 0x00; // Threshold register 5

    if (write(i2c_fd, config, 6) != 6) {
        perror("write to MPR121 threshold registers");
        exit(EXIT_FAILURE);
    }

    // Set filter and charge time
    config[0] = 0x00; // Filter register 0
    config[1] = 0x00; // Filter register 1
    config[2] = 0x00; // Filter register 2
    config[3] = 0x00; // Filter register 3
    config[4] = 0x00; // Filter register 4
    config[5] = 0x00; // Filter register 5

    if (write(i2c_fd, config, 6) != 6) {
        perror("write to MPR121 filter registers");
        exit(EXIT_FAILURE);
    }

    // Set electrode current
    config[0] = 0x00; // Current register 0
    config[1] = 0x00; // Current register 1
    config[2] = 0x00; // Current register 2
    config[3] = 0x00; // Current register 3
    config[4] = 0x00; // Current register 4
    config[5] = 0x00; // Current register 5

    if (write(i2c_fd, config, 6) != 6) {
        perror("write to MPR121 current registers");
        exit(EXIT_FAILURE);
    }

    // Switch to run mode
    config[0] = 0x01; // Mode register 0
    config[1] = 0x00; // Mode register 1
    config[2] = 0x00; // Mode register 2
    config[3] = 0x00; // Mode register 3
    config[4] = 0x00; // Mode register 4
    config[5] = 0x00; // Mode register 5

    if (write(i2c_fd, config, 6) != 6) {
        perror("write to MPR121 mode register");
        exit(EXIT_FAILURE);
    }
}

void read_touch_status() {
    uint8_t status[12];

    if (read(i2c_fd, status, 12) != 12) {
        perror("read from MPR121 touch status");
        exit(EXIT_FAILURE);
    }

    int touch_status = 0;
    for (int i = 0; i < 12; i++) {
        if (status[i] & 0x01) {
            touch_status |= (1 << i);
        }
    }

    if (touch_status > 0) {
        relay_toggle();
        printf("Relay toggled\n");
    }
}

void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Shutting down...\n");
        i2c_close();
        exit(0);
    }
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    i2c_init();

    while (1) {
        read_touch_status();
        usleep(TOUCH_STABILIZATION_DELAY);
    }

    i2c_close();
    return 0;
}

