#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <libgpiod.h>

#define PIR_GPIO 17
#define RELAY_GPIO 18
#define LOG_FILE "door_events.log"
#define POLL_INTERVAL 50
#define UNLOCK_DURATION 500
#define RATE_LIMIT 2000

int pir_fd;
int relay_fd;

void signal_handler(int signum) {
    close(relay_fd);
    gpiod_disable(relay_fd);
    gpiod_disable(pir_fd);
    close(pir_fd);
    close(relay_fd);
    exit(0);
}

int main(int argc, char *argv[]) {
    int ret;
    struct sigaction sa;

    // Initialize signal handler
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    // Initialize GPIO
    ret = gpiod_new_output_pin(RELAY_GPIO, &relay_fd);
    if (ret < 0) {
        perror("Failed to initialize GPIO for relay");
        exit(1);
    }

    ret = gpiod_new_input_pin(PIR_GPIO, &pir_fd, GPIOD_PULLDOWN);
    if (ret < 0) {
        perror("Failed to initialize GPIO for PIR sensor");
        exit(1);
    }

    // Open log file
    relay_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (relay_fd == -1) {
        perror("Failed to open log file");
        exit(1);
    }

    // Main loop
    while (1) {
        // Read timestamp
        time_t now = time(NULL);
        char time_str[32];
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", localtime(&now));

        // Log motion event
        fprintf(relay_fd, "%s %d\n", time_str, now);

        // Check for motion
        int motion_detected = gpiod_get_value(pir_fd);
        if (motion_detected) {
            // Log motion event
            fprintf(relay_fd, "Motion detected\n");

            // Unlock door
            gpiod_output_set_level(relay_fd, 1);
            usleep(UNLOCK_DURATION * 100000); // Convert microseconds to seconds

            // Rate limit
            for (int i = 0; i < RATE_LIMIT; i++) {
                usleep(POLL_INTERVAL * 1000000);
            }

            // Log rate-limited event
            fprintf(relay_fd, "Rate limited\n");
        }

        // Sleep for poll interval
        usleep(POLL_INTERVAL * 1000000);
    }

    // Clean up
    close(relay_fd);
    close(pir_fd);
    gpiod_disable(relay_fd);
    gpiod_disable(pir_fd);
    gpiod_del_output_pin(relay_fd);
    gpiod_del_input_pin(pir_fd);

    return 0;
}

