#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>
#include <linux/pm8000.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <errno.h>
#include <signal.h>
#include <pthread.h>

#define GPIO_MODE_PWM 0
#define GPIO_PIN_17 17
#define GPIO_PIN_27 27
#define MAX_STEPS 15
#define MIN_DUTY_CYCLE 0
#define MAX_DUTY_CYCLE 255
#define MIN_STEP_DURATION 50
#define MAX_STEP_DURATION 200

volatile sig_atomic_t shutdown = 0;

void handle_sigint(int sig) {
    global_data.shutdown = 1;
}

void *generate_patterns(void *arg) {
    struct pm8000_dev *dev;
    int ret;

    dev = pm8000_open("/dev/pm8000", O_RDWR);
    if (!dev) {
        perror("Failed to open /dev/pm8000");
        return NULL;
    }

    pm8000_config(dev, PM8000_CONFIG_MODE_PWM, GPIO_MODE_PWM);
    pm8000_gpio_set_mode(dev, GPIO_PIN_17, PM8000_GPIO_OUTPUT);
    pm8000_gpio_set_mode(dev, GPIO_PIN_27, PM8000_GPIO_OUTPUT);

    srand(time(NULL));

    while (!shutdown) {
        int steps = rand() % (MAX_STEPS - MIN_STEPS + 1) + MIN_STEPS;
        struct pm8000_pwm_config pwm_config;
        pwm_config.period = 1000 / 255; // 1 second period for 0-255 duty cycle
        pwm_config.duty_cycle = 0;

        for (int i = 0; i < steps; i++) {
            pwm_config.duty_cycle = rand() % (MAX_DUTY_CYCLE - MIN_DUTY_CYCLE + 1) + MIN_DUTY_CYCLE;
            pwm_config.period = rand() % (MAX_STEP_DURATION - MIN_STEP_DURATION + 1) + MIN_STEP_DURATION;

            ret = pm8000_pwm_set_config(dev, &pwm_config);
            if (ret < 0) {
                perror("Failed to set PWM configuration");
                break;
            }

            usleep((uint64_t)pwm_config.period * 1000000 / 255);
        }
    }

    pm8000_close(dev);
    return NULL;
}

int main(int argc, char *argv[]) {
    pthread_t thread;

    if (signal(SIGINT, handle_sigint) == SIG_IGN) {
        perror("Failed to register signal handler for SIGINT");
        return 1;
    }

    if (pthread_create(&thread, NULL, generate_patterns, NULL) != 0) {
        perror("Failed to create thread");
        return 1;
    }

    while (!shutdown) {
       usleep(100000); // Sleep for 100ms
    }

    pthread_join(thread, NULL);

    return 0;
}

