#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <errno.h>
#include <libgpiod.h>
#include <time.h>

#define GPIO_HX711_DATA 4
#define GPIO_HX711_CLK 17
#define GPIO_SOLENOID 27
#define READ_INTERVAL_MS 500
#define TIMEOUT_MS 500000
#define CALIBRATION_FILE "calibration.txt"
#define LOG_FILE "weight_log.txt"
#define CALIBRATION_THRESHOLD 10.0

struct timespec start_time;

void read_hx711_data(int *data, int *timeout);
void write_calibration(const char *scale, const char *offset);
void load_calibration(const char *filename);
void save_calibration(const char *filename);
void calibrate_scale(float *scale, float *offset);
void engage_solenoid(void);
void log_reading(const float weight);

int main(int argc, char *argv[]) {
    int hx711_data, timeout;
    float scale, offset;
    FILE *calibration_file = fopen(CALIBRATION_FILE, "r");
    if (!calibration_file) {
        fprintf(stderr, "Error: Could not open calibration file.\n");
        return EXIT_FAILURE;
    }

    load_calibration(CALIBRATION_FILE);

    while (1) {
        calibrate_scale(&scale, &offset);
        read_hx711_data(&hx711_data, &timeout);
        if (timeout == 0) {
            float weight = (float)hx711_data * scale + offset;
            if (weight > CALIBRATION_THRESHOLD) {
                engage_solenoid();
                log_reading(weight);
            }
        }
        usleep((READ_INTERVAL_MS / 1000) * 1000);
    }

    fclose(calibration_file);
    return EXIT_SUCCESS;
}

void read_hx711_data(int *data, int *timeout) {
    struct timespec read_start, read_end;
    ftime(read_start.tv_sec, read_start.tv_micsec);
    gpiod_set_output(GPIO_HX711_CLK, 1);
    gpiod_set_output(GPIO_HX711_DATA, 0);
    usleep(TIMEOUT_MS / 1000);
    gpiod_set_output(GPIO_HX711_CLK, 0);
    gpiod_set_input(GPIO_HX711_DATA, GPIO_INPUT_EDGE_RISING);
    *timeout = 0;
    while (gpiod_get_value(GPIO_HX711_DATA) == 0) {
        usleep(10);
        if (gpiod_get_value(GPIO_HX711_DATA) == 1) {
            *timeout = TIMEOUT_MS / 1000;
            break;
        }
    }
    ftime(read_end.tv_sec, read_end.tv_micsec);
    gpiod_set_output(GPIO_HX711_CLK, 0);
    *data = (int)gpiod_get_value(GPIO_HX711_DATA);
}

void write_calibration(const char *scale, const char *offset) {
    FILE *file = fopen(CALIBRATION_FILE, "w");
    if (!file) {
        fprintf(stderr, "Error: Could not open calibration file for writing.\n");
        return;
    }
    fprintf(file, "scale=%f\n", scale);
    fprintf(file, "offset=%f\n", offset);
    fclose(file);
}

void load_calibration(const char *filename) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        fprintf(stderr, "Error: Could not open calibration file.\n");
        return;
    }
    char line[256];
    while (fgets(line, sizeof(line), file)) {
        if (sscanf(line, "scale=%f", &scale) == 1 && sscanf(line, "offset=%f", &offset) == 1)
            break;
    }
    fclose(file);
}

void save_calibration(const char *filename) {
    FILE *file = fopen(filename, "w");
    if (!file) {
        fprintf(stderr, "Error: Could not open calibration file for writing.\n");
        return;
    }
    fprintf(file, "scale=%f\n", scale);
    fprintf(file, "offset=%f\n", offset);
    fclose(file);
}

void calibrate_scale(float *scale, float *offset) {
    int num_readings = 100;
    *offset = 0.0;
    for (int i = 0; i < num_readings; i++) {
        gpiod_set_output(GPIO_HX711_DATA, 0);
        usleep(100000);
        gpiod_set_output(GPIO_HX711_DATA, 1);
        gpiod_get_value(GPIO_HX711_DATA);
        *offset += gpiod_get_value(GPIO_HX711_DATA);
    }
    *offset /= num_readings;

    *scale = 1.0;
    for (int i = 0; i < num_readings; i++) {
        gpiod_set_output(GPIO_HX711_DATA, 0);
        usleep(100000);
        gpiod_set_output(GPIO_HX711_DATA, 1);
        gpiod_get_value(GPIO_HX711_DATA);
        *scale *= gpiod_get_value(GPIO_HX711_DATA);
    }
    *scale /= num_readings;
}

void engage_solenoid(void) {
    printf("Engaging solenoid...\n");
    gpiod_set_output(GPIO_SOLENOID, 1);
}

void log_reading(const float weight) {
    time_t now = time(NULL);
    struct tm *time_info = localtime(&now);
    char timestamp[80];
    sprintf(timestamp, "%04d-%02d-%02d %02d:%02d:%02d",
            time_info->tm_year + 1900, time_info->tm_mon + 1, time_info->tm_mday,
            time_info->tm_hour, time_info->tm_min, time_info->tm_sec);
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: Could not open weight log file for appending.\n");
        return;
    }
    fprintf(log_file, "%s: %f\n", timestamp, weight);
    fclose(log_file);
}

int main(int argc, char *argv[]) {
    // ... (rest of the main function as provided)
}

