        gpiod_get_value(GPIO_HX711_DATA);
        *offset += gpiod_get_value(GPIO_HX711_DATA);
    }
    *offset /= num_readings;

    *scale = 1.0;
    for (int i = 0; i < num_readings; i++) {
        gpiod_set_output(GPIO_HX711_DATA, 0);
        usleep(100000);
        gpiod_set_output(GPIO_HX711_DATA, 1);
        gpiod_get_value(GPIO_HX711_DATA);
        *scale *= gpiod_get_value(GPIO_HX711_DATA);
    }
    *scale /= num_readings;
}

void engage_solenoid(void) {
