#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <libgpiod.h>
#include <pigpio.h>

#define SENSOR_PIN 4
#define MOTOR_IN1 17
#define MOTOR_IN2 18
#define PWM_EN 27
#define LOG_FILE "/var/log/window_control.log"
#define CHECK_INTERVAL 60000  // 60 seconds
#define CLOSE_DURATION 5000   // 5 seconds
#define DEBOUNCE_INTERVAL 50  // 50ms
#define NUM_READINGS 5
#define RAIN_THRESHOLD 3

void log_event(const char *message) {
    int fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (fd < 0) {
        syslog(LOG_ERR, "Failed to open log file: %s");
        exit(EXIT_FAILURE);
    }
    syslog(LOG_INFO, message);
    write(fd, message, strlen(message));
    close(fd);
}

void motor_control(int state) {
    gpioSetMode(MOTOR_IN1, GPIO_OUTPUT);
    gpioSetMode(MOTOR_IN2, GPIO_OUTPUT);
    gpioSetMode(PWM_EN, GPIO_OUTPUT);

    if (state) {
        gpioWrite(MOTOR_IN1, HIGH);
        gpioWrite(MOTOR_IN2, LOW);
        gpioPwmSetRange(PWM_EN, 0, 255);
        gpioPwmSetDuty(PWM_EN, 150);
        sleep(CLOSE_DURATION / 1000.0);
        gpioPwmSetDuty(PWM_EN, 0);
        gpioWrite(MOTOR_IN1, LOW);
        gpioWrite(MOTOR_IN2, HIGH);
    } else {
        gpioWrite(MOTOR_IN1, LOW);
        gpioWrite(MOTOR_IN2, LOW);
        gpioPwmSetDuty(PWM_EN, 0);
    }
}

int main() {
    pigpio_init(5);

    if (gpioSetup(SENSOR_PIN) < 0) {
        log_event("Failed to initialize GPIO for sensor");
        syslog(LOG_ERR, "Failed to initialize GPIO for sensor");
        exit(EXIT_FAILURE);
    }

    while (1) {
        int sensor_state = 0;
        for (int i = 0; i < NUM_READINGS; i++) {
            sensor_state = gpioGet(SENSOR_PIN);
            if (sensor_state == 0) {
                log_event("Rain detected at %lu", microsecond());
                motor_control(1);
                break;
            }
            usleep(DEBOUNCE_INTERVAL * 1000000 / 50);
        }

        if (sensor_state == 0) {
            log_event("No rain detected");
        }

        usleep(CHECK_INTERVAL * 1000000);
    }

    pigpio_cleanup();
    syslog(LOG_INFO, "Exiting gracefully");
    close(logfd);
    exit(EXIT_SUCCESS);
}

