#include <stdio.hx711.h>
#include <pigpio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>

#define WEIGHT_THRESHOLD 100
#define WEIGHT_CHECK_INTERVAL 1000
#define SOLENOID_GPIO 17
#define DATA_GPIO 23
#define CLOCK_GPIO 24

void log_event(const char *event) {
    time_t now = time(NULL);
    struct tm *timeinfo = localtime(&now);
    char time_str[80];
    sprintf(time_str, "%04d-%02d-%02d %02d:%02d:%02d",
            timeinfo->tm_year + 1900, timeinfo->tm_mon + 1, timeinfo->tm_mday,
            timeinfo->tm_hour, timeinfo->tm_min, timeinfo->tm_sec);
    FILE *file = fopen("stock_events.txt", "a");
    if (file == NULL) {
        fprintf(stderr, "Error opening file for logging\n");
        return;
    }
    fprintf(file, "%s: %s\n", time_str, event);
    fclose(file);
}

int main(int argc, char *argv[]) {
    pigpio_init(5);

    if (pigpio_setup() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    if (gpioInitialise(CLOCK_GPIO) < 0) {
        fprintf(stderr, "Failed to initialize clock line GPIO\n");
        return EXIT_FAILURE;
    }
    if (gpioInitialise(DATA_GPIO) < 0) {
        fprintf(stderr, "Failed to initialize data line GPIO\n");
        return EXIT_FAILURE;
    }

    if (gpioInitialise(SOLENOID_GPIO) < 0) {
        fprintf(stderr, "Failed to initialize solenoid GPIO\n");
        return EXIT_FAILURE;
    }

    while (1) {
        int data_line = digitalRead(DATA_GPIO);
        int clock_line = digitalRead(CLOCK_GPIO);

        if (clock_line == HIGH) {
            if (data_line == LOW) {
                int16_t weight = hx711_read_weight();
                if (weight < WEIGHT_THRESHOLD) {
                    log_event("Weight below threshold, activating solenoid");
                    gpioWrite(SOLENOID_GPIO, HIGH);
                    sleep(5);
                    gpioWrite(SOLENOID_GPIO, LOW);
                    log_event("Solenoid deactivated");
                } else {
                    log_event("Weight within threshold");
                }
            } else {
                log_event("Data line stuck high, retrying...");
            }
        } else {
            log_event("HX711 read timeout, retrying...");
        }

        if (errno != EINTR) {
            log_event("Error during GPIO operation: %s", strerror(errno));
        }

        usleep(WEIGHT_CHECK_INTERVAL * 1000);
    }

    pigpio_terminate(0);
    fclose(stdout);
    return EXIT_SUCCESS;
}

