#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <errno.h>
#include <libgpiod.h>
#include <pigpio.h>

#define GPIO4 27
#define GPIO17 17
#define CALIBRATION_FILE "calibration.txt"
#define LOG_FILE "security.log"
#define THRESHOLD 5000
#define TIMEOUT_MS 100000

#define BIT_BANG_CLOCK_HIGH_US 1000000
#define BIT_BANG_CLOCK_LOW_US 1000

void setup_gpio(void) {
    if (gpio_init() < 0) {
        perror("Failed to initialize GPIO");
        exit(EXIT_FAILURE);
    }

    gpioSetMode(GPIO4, GPIO_OUTPUT);
    gpioSetMode(GPIO17, GPIO_OUTPUT);
    gpioSetDrive(GPIO4, GPIO_OUTPUT);
    gpioSetDrive(GPIO17, GPIO_OUTPUT);
}

void calibrate_load_cell(void) {
    int weight;
    printf("Please place a known weight on the scale: ");
    fgets(weight_str, sizeof(weight_str), stdin);
    weight = atoi(weight_str);

    if (write(CALIBRATION_FILE, "calibration.txt", strlen(weight_str)) < 0) {
        perror("Failed to write calibration factor");
        exit(EXIT_FAILURE);
    }

    printf("Calibration factor saved.\n");
}

void read_load_cell(int *weight) {
    int clock_high = 1, clock_low = 0, data_high = 0, data_low = 0;
    long start_time = 0;

    while (1) {
        start_time = millis();

        gpioOutput(GPIO17, GPIO_HIGH);
        gpioDelayUs(BIT_BANG_CLOCK_HIGH_US);
        gpioOutput(GPIO17, GPIO_LOW);
        gpioDelayUs(BIT_BANG_CLOCK_LOW_US);

        data_high = gpioRead(GPIO4);
        data_low = gpioRead(GPIO4);

        clock_high = gpioRead(GPIO17);
        clock_low = gpioRead(GPIO17);

        long elapsed_us = millis() - start_time;

        if (elapsed_us > TIMEOUT_MS) {
            printf("Communication timeout.\n");
            gpioDelayUs(BIT_BANG_CLOCK_HIGH_US);
            gpioDelayUs(BIT_BANG_CLOCK_LOW_US);
            continue;
        }

        if (data_high == data_low && clock_high == clock_low) {
            *weight = (data_high << 11) | (data_low << 3) - 32768;
            break;
        }
    }

    if (*weight < -32768 || *weight > 32767) {
        printf("Invalid raw data, retrying...\n");
        return;
    }

    printf("Raw weight: %d\n", *weight);
}

void engage_solenoid(void) {
    if (gpioWrite(GPIO27, GPIO_HIGH) < 0) {
        perror("Failed to engage solenoid");
        exit(EXIT_FAILURE);
    }

    usleep(5000000); // 5 seconds

    gpioWrite(GPIO27, GPIO_LOW);
}

void log_event(int weight) {
    time_t now = time(NULL);
    char timestamp[80];
    sprintf(timestamp, "%ld", now);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    fprintf(log_file, "%s: %d kg\n", timestamp, weight);
    fclose(log_file);
}

void sigint_handler(int sig) {
    printf("Exiting gracefully...\n");
    gpioWrite(GPIO27, GPIO_LOW);
    exit(0);
}

int main(int argc, char *argv[]) {
    int weight;
    setup_gpio();

    calibrate_load_cell();

    read_load_cell(&weight);

    if (weight > THRESHOLD) {
        engage_solenoid();
        log_event(weight);
    }

    pigpio_exit();

    return 0;
}

int pigpio_exit(void) {
    pigpio_stop();
    pigpio_terminate();
    return 0;
}

int sigint_handler(int sig) {
    engage_solenoid();
    log_event(weight);
    pigpio_exit();
    return 0;
}

int main(int argc, char *argv[]) {
    signal(SIGINT, sigint_handler);
    main(argc, argv);
}

