#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <libgpiod.h>

#define SENSOR_PIN 16
#define RELAY_PIN 20
#define LOG_FILE "relay_events.log"

void log_event(const char *event_type, const char *relay_state) {
    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        fprintf(stderr, "Error opening file: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
    time_t now = time(NULL);
    char timestamp[80];
    sprintf(timestamp, "%s", ctime(&now));
    fprintf(file, "%s %s\n", timestamp, event_type ? event_type : "NO_CHANGE");
    fprintf(file, "Relay State: %s\n", relay_state ? "ON" : "OFF");
    fclose(file);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <gpio_driver_library>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    gpiod_context ctx;
    int ret = gpiod_context_init(&ctx);
    if (ret < 0) {
        fprintf(stderr, "Failed to initialize gpiod context: %s\n", gpiod_strerror(ret));
        exit(EXIT_FAILURE);
