#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <libgpiod/gpio.h>

#define PIR_PIN 17
#define BUZZER_PIN 18
#define LOG_FILE "motion_log.txt"

void sigint_handler(int sig) {
    printf("Interrupted, turning off buzzer and closing log file.\n");
    gpio_pin_set_dir(BUZZER_PIN, GPIO_OUT);
    gpio_pin_write(BUZZER_PIN, 0);
    close(fildes(LOG_FILE));
    exit(0);
}

void sigterm_handler(int sig) {
    printf("Interrupted, turning off buzzer and closing log file.\n");
    gpio_pin_set_dir(BUZZER_PIN, GPIO_OUT);
    gpio_pin_write(BUZZER_PIN, 0);
    close(fildes(LOG_FILE));
    exit(0);
}

int main() {
    struct sigaction sa;
    sigset_t sigset;

    // Initialize signal handlers
    sigaction(SIGINT, sigint_handler, NULL);
    sigaction(SIGTERM, sigterm_handler, NULL);
    sa.sa_handler = sigterm_handler;
    sigaction(SIGINT, &sa, NULL);

    // Initialize libgpiod
    if (libgpiod_init() < 0) {
        perror("libgpiod_init");
        exit(EXIT_FAILURE);
    }

    // Initialize GPIO pins
    int pir_pin = PIR_PIN;
    int buzzer_pin = BUZZER_PIN;

    if (libgpiod_pin_init(pir_pin, GPIO_INPUT) < 0) {
        perror("libgpiod_pin_init");
        exit(EXIT_FAILURE);
    }
    if (libgpiod_pin_init(buzzer_pin, GPIO_OUTPUT) < 0) {
        perror("libgpiod_pin_init");
        exit(EXIT_FAILURE);
    }

    // Open log file
    int fildes = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (fildes == -1) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (1) {
        int pir_state = libgpiod_pin_get_value(pir_pin);
        if (pir_state == GPIO_INPUT_HIGH) {
            // Motion detected, activate buzzer
            gpio_pin_set_value(buzzer_pin, GPIO_OUTPUT);
            gpio_pin_write(buzzer_pin, 1);
            usleep(2000000); // 2 seconds

            // Log motion detection
            char timestamp[20];
            time_t now = time(NULL);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
            fprintf(fildes, "%s: Motion detected\n", timestamp);
        } else {
            // No motion, deactivate buzzer
            gpio_pin_set_value(buzzer_pin, GPIO_OUTPUT);
            gpio_pin_write(buzzer_pin, 0);
        }

        // Sleep for a short period to avoid CPU overload
        usleep(100000);
    }

    // Clean up and exit
    libgpiod_pin_cleanup(buzzer_pin);
    libgpiod_pin_cleanup(pir_pin);
    libgpiod_cleanup();
    close(fildes);
    return 0;
}

