#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_PIN 18
#define VALVE_ON 1
#define VALVE_OFF 0

volatile sig_atomic_t sig_interrupt_requested = 0;

void sigint_handler(int sig) {
    sig_interrupt_requested = 1;
}

void setup_gpio(void) {
    int fd = gpiod_get_default_file();
    if (fd < 0) {
        perror("Failed to open gpiod default file");
        exit(EXIT_FAILURE);
    }

    if (gpiod_try_to_clear_initial_value(fd, GPIO_PIN) < 0) {
        perror("Failed to clear initial value for GPIO pin");
        exit(EXIT_FAILURE);
    }

    if (gpiod_output_init(fd, GPIO_PIN, VALVE_OFF) < 0) {
        perror("Failed to initialize GPIO pin as output");
        exit(EXIT_FAILURE);
    }
}

void turn_valve_on(void) {
    if (gpiod_output_set_level(fd, GPIO_PIN, VALVE_ON) < 0) {
        perror("Failed to set GPIO pin to ON");
        exit(EXIT_FAILURE);
    }
}

void turn_valve_off(void) {
    if (gpiod_output_set_level(fd, GPIO_PIN, VALVE_OFF) < 0) {
        perror("Failed to set GPIO pin to OFF");
        exit(EXIT_FAILURE);
    }
}

int main(void) {
    setup_gpio();

    FILE *fp = fopen("watering.conf", "r");
    if (!fp) {
        perror("Failed to open watering.conf");
        return EXIT_FAILURE;
    }

    char line[1024];
    if (fgets(line, sizeof(line), fp) == NULL) {
        fclose(fp);
        return EXIT_FAILURE;
    }

    line[strcspn(line, "\n")] = 0; // Remove newline character

    if (strlen(line) == 0) {
        fprintf(stderr, "Error: watering.conf is empty.\n");
        return EXIT_FAILURE;
    }

    int duration = atoi(line);
    if (duration < 1 || duration > 3600) {
        fprintf(stderr, "Error: Invalid watering duration. Must be between 1 and 3600 seconds.\n");
        return EXIT_FAILURE;
    }

    turn_valve_off();
    printf("Turning valve OFF\n");

    sleep_us(1000); // Wait for the valve to fully transition

    turn_valve_on();
    printf("Turning valve ON\n");

    usleep(duration * 1000000); // Wait for the configured duration

    turn_valve_off();
    printf("Turning valve OFF\n");

    sig_atomic_set(sig_interrupt_requested, 1);
    kill(getpid(), SIGUSR1); // Send a signal to the main thread to exit gracefully

    // Wait for the SIGINT/SIGTERM signal
    while (!sig_interrupt_requested)
        usleep(100000);

    turn_valve_off(); // Ensure the valve is off before exiting
    gpiod_disable(fd);
    close(fd);
    fclose(fp);

    return EXIT_SUCCESS;
}

