#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <signal.h>
#include <libgpiod.h>

#define SENSOR_LEFT GPIO4
#define SENSOR_MIDDLE GPIO17
#define SENSOR_RIGHT GPIO27
#define LEFT_MOTOR GPIO22
#define RIGHT_MOTOR GPIO23
#define LEFT_MOTOR_PWM GPIO24
#define RIGHT_MOTOR_PWM GPIO25

#define LOG_FILE "trace_log.txt"
#define LOG_INTERVAL_MS 10
#define PWM_FREQUENCY 1000

#define BASE_SPEED 150
#define HALF_SPEED 87

void log_entry(const char *timestamp, int left_sensor, int right_sensor, int left_speed, int right_speed) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    char iso_timestamp[32];
    strftime(iso_timestamp, sizeof(iso_timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&ts.tv_sec));
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
    fprintf(log_file, "%s %d %d %d %d\n", iso_timestamp, left_sensor, right_sensor, left_speed, right_speed);
    fclose(log_file);
}

void sigint_handler(int signum) {
    log_entry(get_iso_timestamp(), 0, 0, 0, 0);
    stop_motors();
    close_log_file();
    gpiod_disable_callback(GPIO_PIN_TO_NUMBER(LEFT_MOTOR_PWM));
    gpiod_disable_callback(GPIO_PIN_TO_NUMBER(RIGHT_MOTOR_PWM));
    gpiod_disable_callback(GPIO_PIN_TO_NUMBER(LEFT_MOTOR));
    gpiod_disable_callback(GPIO_PIN_TO_NUMBER(RIGHT_MOTOR));
    gpiod_exit();
    exit(EXIT_SUCCESS);
}

void stop_motors() {
    gpiod_set_output_level(GPIO_PIN_TO_NUMBER(LEFT_MOTOR), 0);
    gpiod_set_output_level(GPIO_PIN_TO_NUMBER(RIGHT_MOTOR), 0);
}

void close_log_file() {
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main() {
    int log_file_fd;
    struct stat sb;

    log_file_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_file_fd == -1) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    gpiod_init();
    if (gpiod_create_device_node(SENSOR_LEFT, PIPE_TYPE_GPIO) < 0) {
        perror("Failed to create GPIO device node for left sensor");
        exit(EXIT_FAILURE);
    }
    if (gpiod_create_device_node(SENSOR_MIDDLE, PIPE_TYPE_GPIO) < 0) {
        perror("Failed to create GPIO device node for middle sensor");
        exit(EXIT_FAILURE);
    }
    if (gpiod_create_device_node(SENSOR_RIGHT, PIPE_TYPE_GPIO) < 0) {
        perror("Failed to create GPIO device node for right sensor");
        exit(EXIT_FAILURE);
    }

    if (gpiod_create_output_pin(GPIO_PIN_TO_NUMBER(LEFT_MOTOR)) < 0) {
        perror("Failed to create PWM output pin for left motor");
        exit(EXIT_FAILURE);
    }
    if (gpiod_create_output_pin(GPIO_PIN_TO_NUMBER(RIGHT_MOTOR)) < 0) {
        perror("Failed to create PWM output pin for right motor");
        exit(EXIT_FAILURE);
    }
    if (gpiod_create_output_pin(GPIO_PIN_TO_NUMBER(LEFT_MOTOR_PWM)) < 0) {
        perror("Failed to create PWM output pin for left motor PWM");
        exit(EXIT_FAILURE);
    }
    if (gpiod_create_output_pin(GPIO_PIN_TO_NUMBER(RIGHT_MOTOR_PWM)) < 0) {
        perror("Failed to create PWM output pin for right motor PWM");
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, sigint_handler);

    while (1) {
        int left_sensor = gpiod_get_level(GPIO_PIN_TO_NUMBER(SENSOR_LEFT));
        int right_sensor = gpiod_get_level(GPIO_PIN_TO_NUMBER(SENSOR_RIGHT));
        int middle_sensor = gpiod_get_level(GPIO_PIN_TO_NUMBER(SENSOR_MIDDLE));

        int left_speed = BASE_SPEED;
        int right_speed = BASE_SPEED;

        if (middle_sensor == 0) {
            left_speed = right_speed = BASE_SPEED;
        } else if (left_sensor == 0) {
            left_speed = HALF_SPEED;
            right_speed = BASE_SPEED;
        } else if (right_sensor == 0) {
            left_speed = BASE_SPEED;
            right_speed = HALF_SPEED;
        }

        log_entry(get_iso_timestamp(), left_sensor, right_sensor, left_speed, right_speed);

        gpiod_set_output_level(GPIO_PIN_TO_NUMBER(LEFT_MOTOR), left_speed);
        gpiod_set_output_level(GPIO_PIN_TO_NUMBER(RIGHT_MOTOR), right_speed);

        usleep(LOG_INTERVAL_MS / 1000);
    }

    close_log_file();
    gpiod_exit();
    return 0;
}

