    if (gpiod_create_device_node(SENSOR_MIDDLE, PIPE_TYPE_GPIO) < 0) {
        perror("Failed to create GPIO device node for middle sensor");
        exit(EXIT_FAILURE);
    }
    if (gpiod_create_device_node(SENSOR_RIGHT, PIPE_TYPE_GPIO) < 0) {
        perror("Failed to create GPIO device node for right sensor");
        exit(EXIT_FAILURE);
    }

    if (gpiod_create_output_pin(GPIO_PIN_TO_NUMBER(LEFT_MOTOR)) < 0) {
        perror("Failed to create PWM output pin for left motor");
        exit(EXIT_FAILURE);
    }
    if (gpiod_create_output_pin(GPIO_PIN_TO_NUMBER(RIGHT_MOTOR)) < 0) {
        perror("Failed to create PWM output pin for right motor");
        exit(EXIT_FAILURE);
    }
    if (gpiod_create_output_pin(GPIO_PIN_TO_NUMBER(LEFT_MOTOR_PWM)) < 0) {
        perror("Failed to create PWM output pin for left motor PWM");
        exit(EXIT_FAILURE);
    }
    if (gpiod_create_output_pin(GPIO_PIN_TO_NUMBER(RIGHT_MOTOR_PWM)) < 0) {
        perror("Failed to create PWM output pin for right motor PWM");
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, sigint_handler);

    while (1) {
        int left_sensor = gpiod_get_level(GPIO_PIN_TO_NUMBER(SENSOR_LEFT));
        int right_sensor = gpiod_get_level(GPIO_PIN_TO_NUMBER(SENSOR_RIGHT));
        int middle_sensor = gpiod_get_level(GPIO_PIN_TO_NUMBER(SENSOR_MIDDLE));

        int left_speed = BASE_SPEED;
        int right_speed = BASE_SPEED;

        if (middle_sensor == 0) {
            left_speed = right_speed = BASE_SPEED;
        } else if (left_sensor == 0) {
            left_speed = HALF_SPEED;
            right_speed = BASE_SPEED;
        } else if (right_sensor == 0) {
            left_speed = BASE_SPEED;
            right_speed = HALF_SPEED;
        }

        log_entry(get_iso_timestamp(), left_sensor, right_sensor, left_speed, right_speed);

        gpiod_set_output_level(GPIO_PIN_TO_NUMBER(LEFT_MOTOR), left_speed);
        gpiod_set_output_level(GPIO_PIN_TO_NUMBER(RIGHT_MOTOR), right_speed);

        usleep(LOG_INTERVAL_MS / 1000);
    }

    close_log_file();
    gpiod_exit();
    return 0;
}
