#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS 1
#define RELAY_PIN 23
#define LOG_FILE "grow_log.txt"
#define DELAY_MS 180
#define MIN_LUX 150

#define LOG_FORMAT "%lu:%d:%d:%d\n"

void log_lux_and_relay_state(unsigned long timestamp, int lux, int relay_state) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    fprintf(fopen(LOG_FILE, "a"), LOG_FORMAT, (unsigned long)now, t->tm_hour, t->tm_min, t->tm_sec, relay_state);
}

int main() {
    int i2c_fd, relay_fd;
    int bh1750_address = 0x23; // BH1750 I2C address
    int lux_value = -1;
    int relay_state = 0;

    pigpio_init(5); // Initialize pigpio with default pin numbering

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, bh1750_address) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    while (1) {
        // Read lux value from BH1750
        unsigned char buffer[2];
        read(i2c_fd, buffer, 2);
        if (buffer[0] == 0x00 && buffer[1] == 0x00) {
            lux_value = -1; // Sensor not detected
        } else {
            lux_value = (buffer[1] << 8) | buffer[0]; // Convert to lux
        }

        if (lux_value == -1) {
            log_lux_and_relay_state(time(NULL), lux_value, relay_state);
            continue;
        }

        if (lux_value < MIN_LUX) {
            relay_state = !relay_state;
            log_lux_and_relay_state(time(NULL), lux_value, relay_state);
        }

        usleep(DELAY_MS * 1000 / 1000); // Delay for 180ms
    }

    close(i2c_fd);
    pigpio_terminate(pigpio_get_number()); // Terminate pigpio
    gpioReset(RELAY_PIN); // Turn off the relay
    printf("Program terminated.\n");
    return 0;
}

