#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <stdbool.h>
#include <libgpiod/gpio.h>

#define SERVO_PIN 18
#define LOCK_BUTTON 21
#define UNLOCK_BUTTON 22
#define DEBOUNCE_DELAY 100

bool lock_button_pressed = false;
bool unlock_button_pressed = false;

void button_debounce(bool *button_state) {
    static bool last_state = false;
    static usqueue_t queue;
    static int debounce_timer = 0;

    if (usqueue_enqueue(&queue, button_state) == -1) {
        return;
    }

    while (usqueue_dequeue(button_state) == last_state) {
        usqueue_dequeue(button_state);
        debounce_timer--;
    }

    if (debounce_timer == 0) {
        *button_state = !last_state;
        debounce_timer = 50; // Debounce delay
    }
}

void signal_handler(int signum) {
    printf("Exiting...\n");
    gpio_output_set(SERVO_PIN, 0);
    gpio_output_set(LOCK_BUTTON, 0);
    gpio_output_set(UNLOCK_BUTTON, 0);
    exit(0);
}

int main() {
    int servo_gpio = SERVO_PIN;
    int lock_gpio = LOCK_BUTTON;
    int unlock_gpio = UNLOCK_BUTTON;

    if (libgpiod_init() < 0) {
        fprintf(stderr, "Failed to initialize libgpiod\n");
        return EXIT_FAILURE;
    }

    gpio_request(servo_gpio, "servo");
    gpio_set_direction(servo_gpio, GPIO_OUT);

    gpio_request(lock_gpio, "input");
    gpio_set_mode(lock_gpio, GPIO_PULLUP);
    gpio_output_init_count(lock_gpio, 1);

    gpio_request(unlock_gpio, "input");
    gpio_set_mode(unlock_gpio, GPIO_PULLUP);
    gpio_output_init_count(unlock_gpio, 1);

    signal(SIGINT, signal_handler);

    while (1) {
        bool lock_button_state = gpio_get_level(lock_gpio) == 0;
        bool unlock_button_state = gpio_get_level(unlock_gpio) == 0;

        if (lock_button_state) {
            lock_button_pressed = true;
            gpio_output_set(lock_gpio, 0);
            printf("Lock button pressed\n");
            gpio_output_set(servo_gpio, 1000); // 1000 µs (0°)
        } else if (unlock_button_state) {
            unlock_button_pressed = true;
            gpio_output_set(unlock_gpio, 0);
            printf("Unlock button pressed\n");
            gpio_output_set(servo_gpio, 2000); // 2000 µs (180°)
        } else {
            if (lock_button_pressed) {
                gpio_output_set(lock_gpio, 1);
                lock_button_pressed = false;
                gpio_output_set(servo_gpio, 1000); // Reset to 0°
            } else if (unlock_button_pressed) {
                gpio_output_set(unlock_gpio, 1);
                unlock_button_pressed = false;
                gpio_output_set(servo_gpio, 2000); // Reset to 180°
            }
        }

        button_debounce(&lock_button_pressed);
        button_debounce(&unlock_button_pressed);

        usleep(DEBOUNCE_DELAY);
    }

    libgpiod_cleanup();
    return EXIT_SUCCESS;
}

