#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <string.h>
#include <errno.h>
#include <pigpio.h>

#define GPIO_MOTOR1 17
#define GPIO_MOTOR2 27
#define PULSE_DURATION 200
#define DELAY_DURATION 300

void signal_handler(int signum) {
    pigpio_stop(GPIO_MOTOR1);
    pigpio_stop(GPIO_MOTOR2);
    pigpio_terminate();
    exit(0);
}

int main() {
    pigpio_initialize();

    if (sigset_t sigset = sigset_t_create()) {
        if (sigaddset(&sigset, SIGINT) != 0 ||
            sigaddset(&sigset, SIGTERM) != 0) {
            perror("sigset_t_create");
            pigpio_terminate();
            exit(EXIT_FAILURE);
        }
        if (sigaddset(&sigset, SIG_IGN) != 0) {
            perror("sigaddset");
            pigpio_terminate();
            exit(EXIT_FAILURE);
        }
        if (sigprocmask(SIG_BLOCK, &sigset, NULL) == -1) {
            perror("sigprocmask");
            pigpio_terminate();
            exit(EXIT_FAILURE);
        }
    }

    if (signal(SIGINT, signal_handler) == SIG_IGN) {
        perror("signal");
        pigpio_terminate();
        exit(EXIT_FAILURE);
    }
    if (signal(SIGTERM, signal_handler) == SIG_IGN) {
        perror("signal");
        pigpio_terminate();
        exit(EXIT_FAILURE);
    }

    if (pigpio_init(1) < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        pigpio_terminate();
        exit(EXIT_FAILURE);
    }

    if (pigpio_setup(GPIO_MOTOR1) < 0) {
        fprintf(stderr, "Failed to setup GPIO %d\n", GPIO_MOTOR1);
        pigpio_terminate();
        exit(EXIT_FAILURE);
    }
    if (pigpio_setup(GPIO_MOTOR2) < 0) {
        fprintf(stderr, "Failed to setup GPIO %d\n", GPIO_MOTOR2);
        pigpio_terminate();
        exit(EXIT_FAILURE);
    }

    while (1) {
        pigpio_set_mode(GPIO_MOTOR1, PIGIO_OUTPUT);
        pigpio_set_pulse_width(GPIO_MOTOR1, PULSE_DURATION);
        pigpio_write(GPIO_MOTOR1, 1);
        usleep(PULSE_DURATION * 1000000 / 2); // 200ms pulse

        pigpio_set_mode(GPIO_MOTOR2, PIGIO_OUTPUT);
        pigpio_set_pulse_width(GPIO_MOTOR2, DELAY_DURATION);
        pigpio_write(GPIO_MOTOR2, 1);
        usleep(DELAY_DURATION * 1000000 / 2); // 300ms delay

        pigpio_write(GPIO_MOTOR1, 0);
        pigpio_write(GPIO_MOTOR2, 0);
        usleep(DELAY_DURATION * 1000000 / 2); // 300ms delay
    }

    pigpio_stop(GPIO_MOTOR1);
    pigpio_stop(GPIO_MOTOR2);
    pigpio_terminate();

    return 0;
}

