#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <errno.h>
#include <poll.h>
#include <gpiod.h>

#define GPIO_SOUND_SENSOR 17
#define GPIO_ALARM_LED 27
#define ZEROMQ_TOPIC "SOUND_ALERTS"
#define ZEROMQ_PORT 5555
#define POLL_TIMEOUT 10000

void sound_sensor_mode(void);
void alarm_node_mode(void);

int main(int argc, char *argv[]) {
    int sound_sensor_flag = 1;
    int alarm_node_flag = 0;
    int sound_sensor_gpio = GPIO_SOUND_SENSOR;
    int alarm_led_gpio = GPIO_ALARM_LED;
    int zmq_socket;
    struct sockaddr_in zmq_addr;
    int zmq_fd;
    struct pollfd pollfds[1];
    poll_descriptor_set_t poll_set;
    gpiod_t sound_sensor_gpio_fd;
    gpiod_result_t result;

    if (argc > 1 && strcmp(argv[1], "alarm_node") == 0) {
        alarm_node_flag = 1;
    }

    if (alarm_node_flag) {
        sound_sensor_mode = 0;
    } else {
        sound_sensor_mode = 1;
    }

    if (sound_sensor_flag) {
        sound_sensor_mode();
    } else {
        alarm_node_mode();
    }

    return 0;
}

void sound_sensor_mode(void) {
    gpiod_init(NULL);
    result = gpiod_request_pin_out(&sound_sensor_gpio, "default_config");
    if (result != GPIOD_OK) {
        perror("Failed to initialize GPIO pin");
        exit(EXIT_FAILURE);
    }

    zmq_socket(zmq_fd, ZMQ_PUB);
    memset(&zmq_addr, 0, sizeof(zmq_addr));
    zmq_addr.sin_family = AF_INET;
    zmq_addr.sin_port = htons(ZEROMQ_PORT);
    zmq_addr.sin_addr.s_addr = INADDR_ANY;

    if (zmq_connect(zmq_socket, (struct sockaddr *)&zmq_addr, sizeof(zmq_addr)) < 0) {
        perror("Failed to connect to ZeroMQ socket");
        exit(EXIT_FAILURE);
    }

    while (1) {
        pollfds[0].fd = sound_sensor_gpio, pollfds[0].events = POLLIN;
        poll_set_fd(poll_set, &pollfds[0]);
        poll(poll_set, 1, POLL_TIMEOUT);

        if (pollfds[0].revents & POLLIN) {
            int sound_state = inb(sound_sensor_gpio);
            if (sound_state == 0) {
                // Logic 0 detected, publish alert
                char alert_msg[] = "SOUND DETECTED";
                ssize_t bytes_sent = zmq_send(zmq_socket, alert_msg, strlen(alert_msg), 0);
                if (bytes_sent < 0) {
                    perror("Failed to send message over ZeroMQ");
                    exit(EXIT_FAILURE);
                }
            }
        }
    }
}

void alarm_node_mode(void) {
    gpiod_init(NULL);
    result = gpiod_request_pin_out(&alarm_led_gpio, "default_config");
    if (result != GPIOD_OK) {
        perror("Failed to initialize GPIO pin");
        exit(EXIT_FAILURE);
    }

    zmq_socket(zmq_socket, ZMQ_SUB);
