#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <arpa/inet.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <unistd.h>
#include <signal.h>
#include <pthread.h>
#include <math.h>

#define I2C_BUS 1
#define BH1750_ADDR 0x40
#define LUX_THRESHOLD 100
#define UPDATE_INTERVAL 1000 // 1 second

typedef struct {
    int sensor_id;
    float lux;
} sensor_data;

sensor_data sensor_data_list[4];
int sensor_count = 4;
int termination_flag = 0;

void handle_sigint(int sig) {
    global_data.termination_flag = 1;
}

void handle_sigterm(int sig) {
    global_data.termination_flag = 1;
}

void broadcast_lux_data(const char *data) {
    struct sockaddr_in sockaddr;
    sockaddr.sin_family = AF_INET;
    sockaddr.sin_port = htons(5005);
    sockaddr.sin_addr.s_addr = INADDR_ANY;

    int sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        perror("socket");
        return;
    }

    sendto(sockfd, data, strlen(data), 0, (struct sockaddr *)&sockaddr, sizeof(sockaddr));
    close(sockfd);
}

void read_sensor_data(int sensor_id) {
    int file_descriptor;
    struct i2c_rdwr_config config;
    int read_buffer[2];

    file_descriptor = open("/dev/i2c-1", O_RDWR);
    if (file_descriptor < 0) {
        perror("open /dev/i2c-1");
        return;
    }

    memset(&config, 0, sizeof(config));
    config.len = 2;
    config.freq = 400000;
    config.byte_size = 1;

    if (ioctl(file_descriptor, I2C_MASTER, &config) < 0) {
        perror("ioctl I2C_MASTER");
        close(file_descriptor);
        return;
    }

    if (ioctl(file_descriptor, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(file_descriptor);
        return;
    }

    if (read(file_descriptor, read_buffer, 2) != 2) {
        perror("read from I2C");
        close(file_descriptor);
        return;
    }

    sensor_data_list[sensor_id].lux = (float)read_buffer[0] * 100; // Convert raw value to lux

    if (ioctl(file_descriptor, I2C_READ_BYTE_DISTORTION_REG, 0) < 0) {
        sensor_data_list[sensor_id].lux = NAN; // Set to NaN if error
    }

    close(file_descriptor);
}

void loop() {
    while (!global_data.termination_flag) {
        for (int i = 0; i < sensor_count; i++) {
            read_sensor_data(i);
        }

        char lux_str[100];
        snprintf(lux_str, sizeof(lux_str), "%d,%f", global_data.sensor_id, sensor_data_list[global_data.sensor_id].lux);
        broadcast_lux_data(lux_str);

        usleep(UPDATE_INTERVAL * 1000 / 1000); // Convert ms to microseconds
    }
}

int main(int argc, char *argv[]) {
    global_data.termination_flag = 0;

    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigterm);

    pthread_t thread;
    pthread_create(&thread, NULL, loop, &global_data);
    pthread_join(thread, NULL);

    return 0;
}

