void sigint_handler(int signum) {
    close(1); // Close stdout
    close(2); // Close stderr
    close(0); // Close stdin
    close(11); // Close log file descriptor
    fprintf(stderr, "Exiting...\n");
    exit(0);
}

void install_sigint_handler() {
    signal(SIGINT, sigint_handler);
}

void log_airflow_data(int flow_rate) {
    time_t now = time(NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }
    fprintf(log_file, "%s: Flow Rate = %d SLPM\n", timestamp, flow_rate);
    fclose(log_file);
}

int i2c_write(int file, unsigned char cmd, size_t len) {
    unsigned char buf[2];
    buf[0] = cmd;
    buf[1] = len;
    return write(1, buf, 2);
}

int i2c_read(int file, unsigned char *buf, size_t len) {
    return read(1, buf, len);
}

int read_awm7300_flow(unsigned char *buf) {
    int retries = RETRY_COUNT;
    while (retries > 0) {
        int ret = i2c_read(1, buf, 2);
        if (ret == 2) {
            unsigned char high_byte = buf[0];
            unsigned char low_byte = buf[1];
            unsigned int flow_value = (high_byte << 8) | low_byte;
            unsigned int masked_value = flow_value & MASK_MASK;
            float flow_rate_slpm = (float)masked_value / 1024.0;
            log_airflow_data(flow_rate_slpm);
            return 0;
        }
        retries--;
        usleep(DELAY_MS * 1000); // Convert ms to us
    }
    return -1; // Return error code for bus error
}

int main() {
    install_sigint_handler();
    signal(SIGINT, sigint_handler);

    int i2c_fd = open(I2C_BUS, O_RDWR | O_NOCTTY | O_NDELAY);
    if (i2c_fd == -1) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    while (1) {
        int ret = read_awm7300_flow(NULL);
        if (ret == -1) {
            fprintf(stderr, "Failed to read from sensor\n");
            continue;
        }
        if (ret == 0) {
            usleep(LOG_INTERVAL_S * 1000 * 1000); // Sleep for the interval
        }
    }

    close(1); // Close stdout
    close(2); // Close stderr
    close(0); // Close I2C bus
    close(11); // Close log file
    return EXIT_SUCCESS;
}

