#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS 1
#define DEFAULT_ADDR 0x1A
#define DEFAULT_INTERVAL 1.0
#define DEFAULT_FILENAME "seismic_data.csv"
#define DEFAULT_ERROR_FILENAME "seismic_error.log"

#define BUFFER_SIZE 1024

void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Shutting down...\n");
        close(fd_i2c);
        close(fd_error);
        fclose(fp_csv);
        exit(0);
    }
}

int setup_i2c(int fd_i2c, int addr) {
    int ret;
    ret = open("/dev/i2c-1", O_RDWR);
    if (ret < 0) {
        perror("open /dev/i2c-1");
        return -1;
    }

    ret = ioctl(fd_i2c, I2C_SLAVE, addr);
    if (ret < 0) {
        perror("ioctl I2C_SLAVE");
        close(fd_i2c);
        return -1;
    }

    return fd_i2c;
}

int read_sensor(int fd_i2c, int addr, int *x, int *y, int *z) {
    int ret, count = BUFFER_SIZE;
    static int retries = 3, backoff = 10;

    while (retries > 0) {
        ret = read(fd_i2c, buffer, count);
        if (ret == -1) {
            if (errno == ETIMEDOUT) {
                printf("Transient I2C error, retrying in %d ms...\n", backoff * 1000);
                usleep(backoff * 1000000);
                retries--;
                backoff *= 2;
            } else {
                fprintf(fd_error, "Error: %s\n", strerror(errno));
                return -1;
            }
        } else if (ret != count) {
            fprintf(fd_error, "Error: I2C read failed\n");
            return -1;
        }

        *x = (buffer[0] << 8) | buffer[1];
        *y = (buffer[2] << 8) | buffer[3];
        *z = (buffer[4] << 8) | buffer[5];

        if (*x == 0xFF && *y == 0xFF && *z == 0xFF) {
            fprintf(fd_error, "Sensor not found\n");
            return -1;
        }

        return 0;
    }

    fprintf(fd_error, "Transient error reading sensor data, retrying...\n");
    return -1;
}

void log_data(const char *timestamp, double x, double y, double z) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char time_str[80];
    sprintf(time_str, "%04d-%02d-%02d %02d:%02d:%02d",
            t->tm_year + 1900, t->tm_mon + 1, t->tm_mday,
            t->tm_hour, t->tm_min, t->tm_sec);

    FILE *fp_csv = fopen("seismic_data.csv", "a");
    if (!fp_csv) {
        perror("fopen seismic_data.csv");
        return;
    }

    fprintf(fp_csv, "%s,%.2f,%.2f,%.2f\n", time_str, x, y, z);
    fclose(fp_csv);
}

int main(int argc, char *argv[]) {
    int fd_i2c, fd_error, fd_csv;
    int addr = DEFAULT_ADDR;
    double interval = DEFAULT_INTERVAL;
    char *filename = DEFAULT_FILENAME;
    char *error_filename = DEFAULT_ERROR_FILENAME;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        if (argc > 1) {
            addr = atoi(argv[1]);
        }
        if (argc > 2) {
            interval = atof(argv[2]);
        }
        if (argc > 3) {
            filename = argv[3];
        }
        if (argc > 4) {
            error_filename = argv[4];
        }

        fd_i2c = setup_i2c(fd_i2c, addr);
        if (fd_i2c < 0) {
            fprintf(stderr, "Failed to open I2C bus\n");
            continue;
        }

        fd_csv = fopen(filename, "a");
        if (!fd_csv) {
            perror("fopen seismic_data.csv");
            close(fd_i2c);
            continue;
        }

        while (1) {
            double x, y, z;
            if (read_sensor(fd_i2c, addr, &x, &y, &z) < 0) {
                break;
            }

            log_data(time(NULL), x, y, z);
        }

        fclose(fd_csv);
        close(fd_i2c);
        close(fd_error);
    }

    return 0;
}

