#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/select.h>
#include <sys/time.h>
#include <signal.h>
#include <stdlib.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/un.h>
#include <termios.h>

#define BUFFER_SIZE 1024
#define BAUD_RATE 115200
#define TXD_PIN 14
#define RXD_PIN 15
#define TIMEOUT_SECS 2
#define INTER_BYTE_TIMEOUT_SECS 0.5

typedef struct {
    time_t timestamp_seconds;
    double range_meters;
} Detection;

Detection data_buffer[10];
int data_buffer_index = 0;

void handle_sigint(int sig) {
    printf("\nGracefully shutting down...\n");
    fcntl(fileno(stdin), F_SETFL, O_CLEAR);
    exit(0);
}

void handle_sigterm(int sig) {
    printf("\nGracefully shutting down...\n");
    fcntl(fileno(stdin), F_SETFL, O_CLEAR);
    exit(0);
}

int main() {
    struct termios options, saved_options;
    int uart_fd, n;
    char buffer[BUFFER_SIZE];
    struct timeval tv;

    uart_fd = open("/dev/serial0", O_RDWR | O_NOCTTY | O_NDELAY);
    if (uart_fd == -1) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    if (tcgetattr(uart_fd, &saved_options) == -1) {
        perror("tcgetattr");
        exit(EXIT_FAILURE);
    }

    options = saved_options;
    cfsetispeed(&options, BAUD_RATE);
    cfsetospeed(&options, BAUD_RATE);
    options.c_cflag &= ~(CSIZE | PARITY | CLOCAL | CREAD);
    options.c_cflag |= CS8 | CLOCAL | CREAD;
    options.c_iflag &= ~(IXON | IXOFF | IXANY);
    options.c_oflag = 0;
    options.c_cc[VMIN] = 1;
    options.c_cc[VTIME] = INTER_BYTE_TIMEOUT_SECS;

    if (ctermid(&options) == NULL) {
        perror("tcsetattr");
        exit(EXIT_FAILURE);
    }

    if (fcntl(uart_fd, F_SETFL, OFlag(O_NONBLOCK)) == -1) {
        perror("fcntl");
        exit(EXIT_FAILURE);
    }

    if (dup2(uart_fd, fileno(stdin)) == -1) {
        perror("dup2");
        exit(EXIT_FAILURE);
    }

    if (dup2(uart_fd, fileno(stdout)) == -1) {
        perror("dup2");
        exit(EXIT_FAILURE);
    }

    if (close(uart_fd) == -1) {
        perror("close");
        exit(EXIT_FAILURE);
    }

    struct timeval tv;
    tv.tv_sec = 0;
    tv.tv_usec = 0;

    sigset_t sigset;
    SIG_ZEROSET(&sigset, 1);
    sigaddset(&sigset, SIGINT);
    sigaddset(&sigset, SIGTERM);

    if (sigaction(SIGINT, &handle_sigint, NULL, 0) == -1) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    if (sigaction(SIGTERM, &handle_sigterm, NULL, 0) == -1) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    while (1) {
        fd_set readfds;
        FD_ZERO(&readfds);
        FD_SET(fileno(stdin), &readfds);

        tv.tv_sec = 2;
        tv.tv_usec = 0;

        n = select(fileno(stdin) + 1, &readfds, NULL, NULL, &tv);
        if (n < 0) {
            perror("select");
            exit(EXIT_FAILURE);
        } else if (n == 0) {
            // No activity, wait for a short period
            usleep(100000);
            continue;
        }

        n = read(fileno(stdin), buffer, BUFFER_SIZE);
        if (n == -1) {
            perror("read");
            exit(EXIT_FAILURE);
        }

        if (n == 0) {
            // No data received, check for sensor absence
            if (feof(stdin)) {
                printf("Sensor absent detected.\n");
                break;
            }
        } else {
            // Process incoming data
            buffer[n] = '\0';
            if (strtok(buffer, "\n") != NULL) {
                sscanf(strtok(NULL, ","), "%ld,%f", &data_buffer[data_buffer_index].timestamp_seconds, &data_buffer[data_buffer_index].range_meters);
                data_buffer_index++;
                if (data_buffer_index >= 10) {
                    data_buffer_index = 0;
                }
                printf("Timestamp: %ld-%02ld-%02d %02d:%02d:%02d, Range: %.2f meters\n", data_buffer[0].timestamp_seconds / 86400, data_buffer[0].timestamp_seconds % 86400 / 24, data_buffer[0].timestamp_seconds % 24 / 1440, data_buffer[0].timestamp_seconds % 1440 / 60, data_buffer[0].timestamp_seconds % 60, data_buffer[0].range_meters);
            }
        }
    }

    return 0;
}

