}

int main() {
    pioInit();

    if (pioError()) {
        fprintf(stderr, "Error initializing pigpio: %s\n", pioGetErrorName());
        exit(1);
    }

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting SIGINT handler\n");
        exit(1);
    }

    sa.sa_handler = sigterm_handler;
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting SIGTERM handler\n");
        exit(1);
    }

    pioSetMode(GPIO_LEFT, PIO_OUTPUT);
    pioSetMode(GPIO_MIDDLE, PIO_OUTPUT);
    pioSetMode(GPIO_RIGHT, PIO_OUTPUT);

    pioSetPullup(GPIO_LEFT);
    pioSetPullup(GPIO_MIDDLE);
    pioSetPullup(GPIO_RIGHT);

    pioSetDirection(GPIO_LEFT, PIO_INPUT);
    pioSetDirection(GPIO_MIDDLE, PIO_INPUT);
    pioSetDirection(GPIO_RIGHT, PIO_INPUT);

    while (1) {
        int left = pioGet(GPIO_LEFT);
        int middle = pioGet(GPIO_MIDDLE);
        int right = pioGet(GPIO_RIGHT);

        if (left == 0 && middle == 0 && right == 0) {
            sendEmergencyStop();
        } else {
            printf("Left: %d, Middle: %d, Right: %d\n", left, middle, right);
        }

        usleep(UPDATE_PERIOD_MS * 1000 / 1000);
    }

    return 0;
}

void sendEmergencyStop() {
    int uart_fd = open(UART_PORT, O_WRONLY | O_NDELAY | O_CREAT, S_IRUSR | S_IWUSR | S_ISROC);
    if (uart_fd == -1) {
        perror("Error opening UART device");
        return;
    }

    char emergency_stop[] = "EMERGENCY STOP!\n";
    ssize_t written = write(uart_fd, emergency_stop, strlen(emergency_stop));
    if (written == -1) {
        perror("Error writing to UART device");
    }

    close(uart_fd);
}
